    #region Exceptions
    /// <summary>
    /// 并发异常
    /// </summary>
    public class ConcurrencyException : Warning
    {
        /// <summary>
        /// 消息
        /// </summary>
        private readonly string _message;

        /// <summary>
        /// 初始化并发异常
        /// </summary>
        public ConcurrencyException()
            : this("")
        {
        }

        /// <summary>
        /// 初始化并发异常
        /// </summary>
        /// <param name="exception">异常</param>
        public ConcurrencyException(Exception exception)
            : this("", exception)
        {
        }

        /// <summary>
        /// 初始化并发异常
        /// </summary>
        /// <param name="message">错误消息</param>
        /// <param name="exception">异常</param>
        /// <param name="code">错误码</param>
        /// <param name="httpStatusCode">Http状态码</param>
        public ConcurrencyException(string message, Exception exception = null, string code = null, int? httpStatusCode = null)
            : base(message, exception, code, httpStatusCode)
        {
            _message = message;
        }

        /// <inheritdoc />
        public override string Message => $"{R.ConcurrencyExceptionMessage}.{_message}";

        /// <inheritdoc />
        public override string GetMessage(bool isProduction = false)
        {
            if (isProduction)
                return R.ConcurrencyExceptionMessage;
            return GetMessage(this);
        }
    }

    /// <summary>
    /// 应用程序异常
    /// </summary>
    public class Warning : Exception
    {
        /// <summary>
        /// 初始化应用程序异常
        /// </summary>
        /// <param name="exception">异常</param>
        public Warning(Exception exception)
            : this(null, exception)
        {
        }

        /// <summary>
        /// 初始化应用程序异常
        /// </summary>
        /// <param name="message">错误消息</param>
        /// <param name="exception">异常</param>
        /// <param name="code">错误码</param>
        /// <param name="httpStatusCode">Http状态码</param>
        public Warning(string message, Exception exception = null, string code = null, int? httpStatusCode = null)
            : base(message ?? "", exception)
        {
            Code = code;
            HttpStatusCode = httpStatusCode;
        }

        /// <summary>
        /// 错误码
        /// </summary>
        public string Code { get; set; }

        /// <summary>
        /// Http状态码
        /// </summary>
        public int? HttpStatusCode { get; set; }

        /// <summary>
        /// 是否本地化异常消息
        /// </summary>
        public bool? IsLocalization { get; set; }

        /// <summary>
        /// 获取错误消息
        /// </summary>
        /// <param name="isProduction">是否生产环境</param>
        public virtual string GetMessage(bool isProduction = false)
        {
            return GetMessage(this);
        }

        /// <summary>
        /// 获取错误消息
        /// </summary>
        public static string GetMessage(Exception ex)
        {
            var result = new StringBuilder();
            var list = GetExceptions(ex);
            foreach (var exception in list)
                AppendMessage(result, exception);
            return result.ToString().Trim(Environment.NewLine.ToCharArray());
        }

        /// <summary>
        /// 添加异常消息
        /// </summary>
        private static void AppendMessage(StringBuilder result, Exception exception)
        {
            if (exception == null)
                return;
            result.AppendLine(exception.Message);
        }

        /// <summary>
        /// 获取异常列表
        /// </summary>
        public IList<Exception> GetExceptions()
        {
            return GetExceptions(this);
        }

        /// <summary>
        /// 获取异常列表
        /// </summary>
        /// <param name="ex">异常</param>
        public static IList<Exception> GetExceptions(Exception ex)
        {
            var result = new List<Exception>();
            AddException(result, ex);
            return result;
        }

        /// <summary>
        /// 添加内部异常
        /// </summary>
        private static void AddException(List<Exception> result, Exception exception)
        {
            if (exception == null)
                return;
            result.Add(exception);
            AddException(result, exception.InnerException);
        }
    }
    #endregion

    #region Expressions
    /// <summary>
    /// 参数重绑定操作
    /// </summary>
    public class ParameterRebinder : ExpressionVisitor
    {
        /// <summary>
        /// 参数字典
        /// </summary>
        private readonly Dictionary<ParameterExpression, ParameterExpression> _map;

        /// <summary>
        /// 初始化参数重绑定操作
        /// </summary>
        /// <param name="map">参数字典</param>
        public ParameterRebinder(Dictionary<ParameterExpression, ParameterExpression> map)
        {
            _map = map ?? new Dictionary<ParameterExpression, ParameterExpression>();
        }

        /// <summary>
        /// 替换参数
        /// </summary>
        /// <param name="map">参数字典</param>
        /// <param name="exp">表达式</param>
        public static Expression ReplaceParameters(Dictionary<ParameterExpression, ParameterExpression> map, Expression exp)
        {
            return new ParameterRebinder(map).Visit(exp);
        }

        /// <summary>
        /// 访问参数
        /// </summary>
        /// <param name="parameterExpression">参数</param>
        protected override Expression VisitParameter(ParameterExpression parameterExpression)
        {
            if (_map.TryGetValue(parameterExpression, out var replacement))
                parameterExpression = replacement;
            return base.VisitParameter(parameterExpression);
        }
    }

    /// <summary>
    /// 谓词表达式生成器
    /// </summary>
    public class PredicateExpressionBuilder<TEntity>
    {
        /// <summary>
        /// 参数
        /// </summary>
        private readonly ParameterExpression _parameter;
        /// <summary>
        /// 结果表达式
        /// </summary>
        private Expression _result;

        /// <summary>
        /// 初始化谓词表达式生成器
        /// </summary>
        public PredicateExpressionBuilder()
        {
            _parameter = Lambda.CreateParameter<TEntity>();
        }

        /// <summary>
        /// 获取参数
        /// </summary>
        public ParameterExpression GetParameter()
        {
            return _parameter;
        }

        /// <summary>
        /// 添加表达式
        /// </summary>
        /// <param name="property">属性表达式</param>
        /// <param name="operator">运算符</param>
        /// <param name="value">值</param>
        public void Append<TProperty>(Expression<Func<TEntity, TProperty>> property, Operator @operator, object value)
        {
            _result = _result.And(_parameter.Property(Lambda.GetMember(property)).Operation(@operator, value));
        }

        /// <summary>
        /// 添加表达式
        /// </summary>
        /// <param name="property">属性表达式</param>
        /// <param name="operator">运算符</param>
        /// <param name="value">值</param>
        public void Append<TProperty>(Expression<Func<TEntity, TProperty>> property, Operator @operator, Expression value)
        {
            _result = _result.And(_parameter.Property(Lambda.GetMember(property)).Operation(@operator, value));
        }

        /// <summary>
        /// 添加表达式
        /// </summary>
        /// <param name="property">属性名</param>
        /// <param name="operator">运算符</param>
        /// <param name="value">值</param>
        public void Append(string property, Operator @operator, object value)
        {
            _result = _result.And(_parameter.Property(property).Operation(@operator, value));
        }

        /// <summary>
        /// 添加表达式
        /// </summary>
        /// <param name="property">属性名</param>
        /// <param name="operator">运算符</param>
        /// <param name="value">值</param>
        public void Append(string property, Operator @operator, Expression value)
        {
            _result = _result.And(_parameter.Property(property).Operation(@operator, value));
        }

        /// <summary>
        /// 清空
        /// </summary>
        public void Clear()
        {
            _result = null;
        }

        /// <summary>
        /// 转换为Lambda表达式
        /// </summary>
        public Expression<Func<TEntity, bool>> ToLambda()
        {
            return _result.ToLambda<Func<TEntity, bool>>(_parameter);
        }
    }
    #endregion

    #region Helpers
    /// <summary>
    /// 命令行操作
    /// </summary>
    public class CommandLine
    {
        /// <summary>
        /// 日志操作
        /// </summary>
        private ILogger _logger;
        /// <summary>
        /// 命令,范例: dotnet
        /// </summary>
        private string _command;
        /// <summary>
        /// 命令参数,范例: --info
        /// </summary>
        private string _arguments;
        /// <summary>
        /// 环境变量
        /// </summary>
        private readonly IDictionary<string, string> _environmentVariables;
        /// <summary>
        /// 是否重定向标准输出流
        /// </summary>
        private bool _redirectStandardOutput;
        /// <summary>
        /// 是否重定向标准错误流
        /// </summary>
        private bool _redirectStandardError;
        /// <summary>
        /// 输出流字符编码,默认值: Encoding.UTF8
        /// </summary>
        private Encoding _outputEncoding;
        /// <summary>
        /// 是否使用操作系统shell启动,默认值: false
        /// </summary>
        private bool _useShellExecute;
        /// <summary>
        /// 工作目录
        /// </summary>
        private string _workingDirectory;
        /// <summary>
        /// 启动进程是否不要创建新窗口
        /// </summary>
        private bool _createNoWindow;
        /// <summary>
        /// 命令执行超时间隔
        /// </summary>
        private TimeSpan _timeout;
        /// <summary>
        /// 事件等待句柄
        /// </summary>
        private readonly EventWaitHandle _outputReceived;
        /// <summary>
        /// 预期完成输出消息
        /// </summary>
        private readonly List<string> _outputToMatch;

        /// <summary>
        /// 初始化命令行操作
        /// </summary>
        public CommandLine()
        {
            _logger = NullLogger.Instance;
            _redirectStandardOutput = true;
            _redirectStandardError = true;
            _outputEncoding = Encoding.UTF8;
            _useShellExecute = false;
            _createNoWindow = true;
            _environmentVariables = new Dictionary<string, string>();
            _timeout = TimeSpan.FromSeconds(30);
            _outputReceived = new EventWaitHandle(false, EventResetMode.ManualReset);
            _outputToMatch = new List<string>();
        }

        /// <summary>
        /// 创建命令行操作
        /// </summary>
        /// <param name="command">命令,范例: dotnet</param>
        /// <param name="arguments">命令参数,范例: --info</param>
        public static CommandLine Create(string command, string arguments = null)
        {
            return new CommandLine().Command(command).Arguments(arguments);
        }

        /// <summary>
        /// 设置日志操作
        /// </summary>
        public CommandLine Log(ILogger logger)
        {
            _logger = logger ?? NullLogger.Instance;
            return this;
        }

        /// <summary>
        /// 设置命令
        /// </summary>
        /// <param name="command">命令,范例: dotnet</param>
        public CommandLine Command(string command)
        {
            _command = command;
            return this;
        }

        /// <summary>
        /// 根据条件设置命令参数
        /// </summary>
        /// <param name="condition">条件,如果为false则不设置命令参数</param>
        /// <param name="arguments">命令参数,范例: --info</param>
        public CommandLine ArgumentsIf(bool condition, params string[] arguments)
        {
            if (condition == false)
                return this;
            return Arguments(arguments);
        }

        /// <summary>
        /// 设置命令参数
        /// </summary>
        /// <param name="arguments">命令参数,范例: --info</param>
        public CommandLine Arguments(params string[] arguments)
        {
            if (arguments == null)
                return this;
            return Arguments((IEnumerable<string>)arguments);
        }

        /// <summary>
        /// 根据条件设置命令参数
        /// </summary>
        /// <param name="condition">条件,如果为false则不设置命令参数</param>
        /// <param name="arguments">命令参数</param>
        public CommandLine ArgumentsIf(bool condition, IEnumerable<string> arguments)
        {
            if (condition == false)
                return this;
            return Arguments(arguments);
        }

        /// <summary>
        /// 设置命令参数
        /// </summary>
        /// <param name="arguments">命令参数</param>
        public CommandLine Arguments(IEnumerable<string> arguments)
        {
            if (arguments == null)
                return this;
            if (_arguments.IsEmpty() == false)
                _arguments += " ";
            _arguments += string.Join(" ", arguments);
            return this;
        }

        /// <summary>
        /// 设置环境变量
        /// </summary>
        /// <param name="key">键</param>
        /// <param name="value">值</param>
        public CommandLine Env(string key, string value)
        {
            if (key.IsEmpty())
                return this;
            if (_environmentVariables.ContainsKey(key))
                _environmentVariables.Remove(key);
            _environmentVariables.Add(key, value);
            return this;
        }

        /// <summary>
        /// 设置环境变量
        /// </summary>
        /// <param name="env">环境变量</param>
        public CommandLine Env(IDictionary<string, string> env)
        {
            if (env == null)
                return this;
            foreach (var item in env)
                Env(item.Key, item.Value);
            return this;
        }

        /// <summary>
        /// 设置重定向标准输出流
        /// </summary>
        /// <param name="value">是否重定向标准输出流,默认值: true,注意: 如果要设置UseShellExecute为 false,
        /// 则必须将RedirectStandardOutput设置为true</param>
        public CommandLine RedirectStandardOutput(bool value = true)
        {
            _redirectStandardOutput = value;
            if (value)
            {
                _useShellExecute = false;
                return this;
            }
            _useShellExecute = true;
            _outputEncoding = null;
            return this;
        }

        /// <summary>
        /// 设置重定向标准错误流
        /// </summary>
        /// <param name="value">是否重定向标准错误流</param>
        public CommandLine RedirectStandardError(bool value = true)
        {
            _redirectStandardError = value;
            return this;
        }

        /// <summary>
        /// 设置输出流字符编码
        /// </summary>
        /// <param name="encoding">输出流字符编码,默认值: Encoding.UTF8</param>
        public CommandLine OutputEncoding(Encoding encoding)
        {
            _outputEncoding = encoding;
            return this;
        }

        /// <summary>
        /// 设置是否使用操作系统shell启动
        /// </summary>
        /// <param name="value">是否使用操作系统shell启动,默认值: false</param>
        public CommandLine UseShellExecute(bool value = true)
        {
            _useShellExecute = value;
            if (value)
            {
                _redirectStandardOutput = false;
                _outputEncoding = null;
                return this;
            }
            _redirectStandardOutput = true;
            return this;
        }

        /// <summary>
        /// 设置工作目录
        /// </summary>
        /// <param name="value">工作目录</param>
        public CommandLine WorkingDirectory(string value)
        {
            _workingDirectory = value;
            return this;
        }

        /// <summary>
        /// 启动进程是否不要创建新窗口
        /// </summary>
        /// <param name="value">启动进程是否不要创建新窗口,默认为true</param>
        public CommandLine CreateNoWindow(bool value)
        {
            _createNoWindow = value;
            return this;
        }

        /// <summary>
        /// 设置命令执行超时间隔,默认值: 60秒
        /// </summary>
        /// <param name="timeout">命令执行超时间隔</param>
        public CommandLine Timeout(TimeSpan timeout)
        {
            _timeout = timeout;
            return this;
        }

        /// <summary>
        /// 设置命令执行完成的预期输出消息
        /// </summary>
        public CommandLine OutputToMatch(params string[] outputs)
        {
            _outputToMatch.AddRange(outputs);
            return this;
        }

        /// <summary>
        /// 执行命令行
        /// </summary>
        public Process Execute()
        {
            if (_command.IsEmpty())
                throw new ArgumentException("命令未设置");
            _logger.LogDebug($"Running command: {GetDebugText()}");
            var process = new Process
            {
                StartInfo = CreateProcessStartInfo()
            };
            process.OutputDataReceived += OnOutput;
            process.ErrorDataReceived += OnOutput;
            process.Start();
            process.BeginOutputReadLine();
            process.BeginErrorReadLine();
            var done = _outputReceived.WaitOne(_timeout);
            if (!done)
                throw new Exception($"命令 \"{GetDebugText()}\" 超时");
            return process;
        }

        /// <summary>
        /// 创建进程启动信息
        /// </summary>
        private ProcessStartInfo CreateProcessStartInfo()
        {
            var escapedArgs = _arguments.Replace("\"", "\\\"");
            var result = new ProcessStartInfo(_command, escapedArgs)
            {
                RedirectStandardOutput = _redirectStandardOutput,
                RedirectStandardError = _redirectStandardError,
                StandardOutputEncoding = _outputEncoding,
                StandardErrorEncoding = _outputEncoding,
                UseShellExecute = _useShellExecute,
                WorkingDirectory = _workingDirectory,
                CreateNoWindow = _createNoWindow,
            };
            foreach (var item in _environmentVariables)
                result.EnvironmentVariables.Add(item.Key, item.Value);
            return result;
        }

        /// <summary>
        /// 接收输出消息事件处理
        /// </summary>
        private void OnOutput(object sendingProcess, DataReceivedEventArgs e)
        {
            if (e.Data.IsEmpty())
                return;
            try
            {
                _logger.LogDebug(e.Data);
            }
            catch (InvalidOperationException)
            {
            }
            if (_outputToMatch.Any(e.Data.Contains))
                _outputReceived.Set();
        }

        /// <summary>
        /// 获取命令调试文本
        /// </summary>
        public string GetDebugText()
        {
            return $"{_command} {_arguments}";
        }

        /// <summary>
        /// 执行PowerShell命令
        /// </summary>
        /// <param name="command">PowerShell命令,范例: Set-ExecutionPolicy RemoteSigned</param>
        /// <param name="workingDirectory">工作目录</param>
        public static void ExecutePowerShell(string command, string workingDirectory = null)
        {
            using Process process = new Process();
            process.StartInfo.FileName = "cmd.exe";
            process.StartInfo.CreateNoWindow = false;
            process.StartInfo.RedirectStandardError = true;
            process.StartInfo.RedirectStandardInput = true;
            process.StartInfo.RedirectStandardOutput = true;
            process.StartInfo.UseShellExecute = false;
            process.StartInfo.WorkingDirectory = workingDirectory;
            process.Start();
            process.StandardInput.WriteLine($"powershell {command}");
            process.StandardInput.WriteLine("exit");
            process.StandardInput.AutoFlush = true;
            process.WaitForExit();
        }
    }

    /// <summary>
    /// 公共操作
    /// </summary>
    public static class Common
    {
        /// <summary>
        /// 获取当前应用程序基路径
        /// </summary>
        public static string ApplicationBaseDirectory => AppContext.BaseDirectory;
        /// <summary>
        /// 换行符
        /// </summary>
        public static string Line => System.Environment.NewLine;
        /// <summary>
        /// 是否Linux操作系统
        /// </summary>
        public static bool IsLinux => RuntimeInformation.IsOSPlatform(OSPlatform.Linux);
        /// <summary>
        /// 是否Windows操作系统
        /// </summary>
        public static bool IsWindows => RuntimeInformation.IsOSPlatform(OSPlatform.Windows);

        /// <summary>
        /// 获取类型
        /// </summary>
        /// <typeparam name="T">类型</typeparam>
        public static Type GetType<T>()
        {
            return GetType(typeof(T));
        }

        /// <summary>
        /// 获取类型
        /// </summary>
        /// <param name="type">类型</param>
        public static Type GetType(Type type)
        {
            return Nullable.GetUnderlyingType(type) ?? type;
        }

        /// <summary>
        /// 获取物理路径
        /// </summary>
        /// <param name="relativePath">相对路径,范例:"test/a.txt" 或 "/test/a.txt"</param>
        /// <param name="basePath">基路径,默认为AppContext.BaseDirectory</param>
        public static string GetPhysicalPath(string relativePath, string basePath = null)
        {
            if (relativePath.StartsWith("~"))
                relativePath = relativePath.TrimStart('~');
            if (relativePath.StartsWith("/"))
                relativePath = relativePath.TrimStart('/');
            if (relativePath.StartsWith("\\"))
                relativePath = relativePath.TrimStart('\\');
            basePath ??= ApplicationBaseDirectory;
            return Path.Combine(basePath, relativePath);
        }

        /// <summary>
        /// 连接路径
        /// </summary>
        /// <param name="paths">路径列表</param>
        public static string JoinPath(params string[] paths)
        {
            return Url.JoinPath(paths);
        }

        /// <summary>
        /// 获取当前目录路径
        /// </summary>
        public static string GetCurrentDirectory()
        {
            return Directory.GetCurrentDirectory();
        }

        /// <summary>
        /// 获取当前目录的上级路径
        /// </summary>
        /// <param name="depth">向上钻取的深度</param>
        public static string GetParentDirectory(int depth = 1)
        {
            var path = Directory.GetCurrentDirectory();
            for (int i = 0; i < depth; i++)
            {
                var parent = Directory.GetParent(path);
                if (parent is { Exists: true })
                    path = parent.FullName;
            }
            return path;
        }
    }

    /// <summary>
    /// 配置操作
    /// </summary>
    public static class Config
    {
        /// <summary>
        /// 配置
        /// </summary>
        private static IConfiguration _configuration;

        /// <summary>
        /// 设置配置
        /// </summary>
        /// <param name="configuration">配置</param>
        public static void SetConfiguration(IConfiguration configuration)
        {
            _configuration = configuration;
        }

        /// <summary>
        /// 获取配置值
        /// </summary>
        /// <param name="key">配置键</param>
        public static string GetValue(string key)
        {
            return GetValue<string>(key);
        }

        /// <summary>
        /// 获取配置值
        /// </summary>
        /// <param name="key">配置键</param>
        public static T GetValue<T>(string key)
        {
            return GetConfiguration().GetValue<T>(key);
        }

        /// <summary>
        /// 获取配置选项
        /// </summary>
        /// <typeparam name="TOptions">配置选项类型</typeparam>
        /// <param name="section">配置节</param>
        public static TOptions Get<TOptions>(string section)
        {
            return GetSection(section).Get<TOptions>();
        }

        /// <summary>
        /// 获取配置节
        /// </summary>
        /// <param name="section">配置节</param>
        public static IConfigurationSection GetSection(string section)
        {
            return GetConfiguration().GetSection(section);
        }

        /// <summary>
        /// 获取配置
        /// </summary>
        private static IConfiguration GetConfiguration()
        {
            return _configuration ??= CreateConfiguration();
        }

        /// <summary>
        /// 创建配置
        /// </summary>
        /// <param name="basePath">配置文件目录绝对路径</param>
        /// <param name="jsonFiles">配置文件列表,默认已包含appsettings.json</param>
        public static IConfiguration CreateConfiguration(string basePath = null, params string[] jsonFiles)
        {
            basePath ??= Common.ApplicationBaseDirectory;
            var builder = new ConfigurationBuilder()
                .SetBasePath(basePath)
                .AddJsonFile("appsettings.json", true, false);
            var environment = Environment.GetEnvironmentName();
            if (environment.IsEmpty() == false)
                builder.AddJsonFile($"appsettings.{environment}.json", true, false);
            builder.AddEnvironmentVariables();
            if (jsonFiles == null)
                return builder.Build();
            foreach (var file in jsonFiles)
                builder.AddJsonFile(file, true, false);
            return builder.Build();
        }

        /// <summary>
        /// 获取数据库连接字符串
        /// </summary>
        /// <param name="name">数据库连接字符串键名</param>
        public static string GetConnectionString(string name)
        {
            return GetConfiguration().GetConnectionString(name);
        }
    }

