    /// <summary>
    /// 类型转换
    /// </summary>
    public static class Convert
    {

        #region ToInt(转换为32位整型)

        /// <summary>
        /// 转换为32位整型
        /// </summary>
        /// <param name="input">输入值</param>
        public static int ToInt(object input)
        {
            return ToIntOrNull(input) ?? 0;
        }

        #endregion

        #region ToIntOrNull(转换为32位可空整型)

        /// <summary>
        /// 转换为32位可空整型
        /// </summary>
        /// <param name="input">输入值</param>
        public static int? ToIntOrNull(object input)
        {
            var success = int.TryParse(input.SafeString(), out var result);
            if (success)
                return result;
            try
            {
                var temp = ToDoubleOrNull(input, 0);
                if (temp == null)
                    return null;
                return System.Convert.ToInt32(temp);
            }
            catch
            {
                return null;
            }
        }

        #endregion

        #region ToLong(转换为64位整型)

        /// <summary>
        /// 转换为64位整型
        /// </summary>
        /// <param name="input">输入值</param>
        public static long ToLong(object input)
        {
            return ToLongOrNull(input) ?? 0;
        }

        #endregion

        #region ToLongOrNull(转换为64位可空整型)

        /// <summary>
        /// 转换为64位可空整型
        /// </summary>
        /// <param name="input">输入值</param>
        public static long? ToLongOrNull(object input)
        {
            var success = long.TryParse(input.SafeString(), out var result);
            if (success)
                return result;
            try
            {
                var temp = ToDecimalOrNull(input, 0);
                if (temp == null)
                    return null;
                return System.Convert.ToInt64(temp);
            }
            catch
            {
                return null;
            }
        }

        #endregion

        #region ToFloat(转换为32位浮点型)

        /// <summary>
        /// 转换为32位浮点型,并按指定小数位舍入
        /// </summary>
        /// <param name="input">输入值</param>
        /// <param name="digits">小数位数</param>
        public static float ToFloat(object input, int? digits = null)
        {
            return ToFloatOrNull(input, digits) ?? 0;
        }

        #endregion

        #region ToFloatOrNull(转换为32位可空浮点型)

        /// <summary>
        /// 转换为32位可空浮点型,并按指定小数位舍入
        /// </summary>
        /// <param name="input">输入值</param>
        /// <param name="digits">小数位数</param>
        public static float? ToFloatOrNull(object input, int? digits = null)
        {
            var success = float.TryParse(input.SafeString(), out var result);
            if (!success)
                return null;
            if (digits == null)
                return result;
            return (float)Math.Round(result, digits.Value);
        }

        #endregion

        #region ToDouble(转换为64位浮点型)

        /// <summary>
        /// 转换为64位浮点型,并按指定小数位舍入
        /// </summary>
        /// <param name="input">输入值</param>
        /// <param name="digits">小数位数</param>
        public static double ToDouble(object input, int? digits = null)
        {
            return ToDoubleOrNull(input, digits) ?? 0;
        }

        #endregion

        #region ToDoubleOrNull(转换为64位可空浮点型)

        /// <summary>
        /// 转换为64位可空浮点型,并按指定小数位舍入
        /// </summary>
        /// <param name="input">输入值</param>
        /// <param name="digits">小数位数</param>
        public static double? ToDoubleOrNull(object input, int? digits = null)
        {
            var success = double.TryParse(input.SafeString(), out var result);
            if (!success)
                return null;
            if (digits == null)
                return result;
            return Math.Round(result, digits.Value);
        }

        #endregion

        #region ToDecimal(转换为128位浮点型)

        /// <summary>
        /// 转换为128位浮点型,并按指定小数位舍入
        /// </summary>
        /// <param name="input">输入值</param>
        /// <param name="digits">小数位数</param>
        public static decimal ToDecimal(object input, int? digits = null)
        {
            return ToDecimalOrNull(input, digits) ?? 0;
        }

        #endregion

        #region ToDecimalOrNull(转换为128位可空浮点型)

        /// <summary>
        /// 转换为128位可空浮点型,并按指定小数位舍入
        /// </summary>
        /// <param name="input">输入值</param>
        /// <param name="digits">小数位数</param>
        public static decimal? ToDecimalOrNull(object input, int? digits = null)
        {
            var success = decimal.TryParse(input.SafeString(), out var result);
            if (!success)
                return null;
            if (digits == null)
                return result;
            return Math.Round(result, digits.Value);
        }

        #endregion

        #region ToBool(转换为布尔值)

        /// <summary>
        /// 转换为布尔值
        /// </summary>
        /// <param name="input">输入值</param>
        public static bool ToBool(object input)
        {
            return ToBoolOrNull(input) ?? false;
        }

        #endregion

        #region ToBoolOrNull(转换为可空布尔值)

        /// <summary>
        /// 转换为可空布尔值
        /// </summary>
        /// <param name="input">输入值</param>
        public static bool? ToBoolOrNull(object input)
        {
            var value = input.SafeString();
            switch (value)
            {
                case "1":
                    return true;
                case "0":
                    return false;
            }
            return bool.TryParse(value, out var result) ? result : null;
        }

        #endregion

        #region ToDateTime(转换为日期)

        /// <summary>
        /// 转换为日期
        /// </summary>
        /// <param name="input">输入值</param>
        public static DateTime ToDateTime(object input)
        {
            return ToDateTimeOrNull(input) ?? DateTime.MinValue;
        }

        #endregion

        #region ToDateTimeOrNull(转换为可空日期)

        /// <summary>
        /// 转换为可空日期
        /// </summary>
        /// <param name="input">输入值</param>
        public static DateTime? ToDateTimeOrNull(object input)
        {
            var success = DateTime.TryParse(input.SafeString(), out var result);
            if (success == false)
                return null;
            return result;
        }

        #endregion

        #region ToGuid(转换为Guid)

        /// <summary>
        /// 转换为Guid
        /// </summary>
        /// <param name="input">输入值</param>
        public static Guid ToGuid(object input)
        {
            return ToGuidOrNull(input) ?? Guid.Empty;
        }

        #endregion

        #region ToGuidOrNull(转换为可空Guid)

        /// <summary>
        /// 转换为可空Guid
        /// </summary>
        /// <param name="input">输入值</param>
        public static Guid? ToGuidOrNull(object input)
        {
            if (input == null)
                return null;
            if (input.GetType() == typeof(byte[]))
                return new Guid((byte[])input);
            return Guid.TryParse(input.SafeString(), out var result) ? result : null;
        }

        #endregion

        #region ToGuidList(转换为Guid集合)

        /// <summary>
        /// 转换为Guid集合
        /// </summary>
        /// <param name="input">以逗号分隔的Guid集合字符串，范例:83B0233C-A24F-49FD-8083-1337209EBC9A,EAB523C6-2FE7-47BE-89D5-C6D440C3033A</param>
        public static List<Guid> ToGuidList(string input)
        {
            return ToList<Guid>(input);
        }

        #endregion

        #region ToBytes(转换为字节数组)

        /// <summary>
        /// 转换为字节数组
        /// </summary>
        /// <param name="input">输入值</param>        
        public static byte[] ToBytes(string input)
        {
            return ToBytes(input, Encoding.UTF8);
        }

        /// <summary>
        /// 转换为字节数组
        /// </summary>
        /// <param name="input">输入值</param>
        /// <param name="encoding">字符编码</param>
        public static byte[] ToBytes(string input, Encoding encoding)
        {
            return string.IsNullOrWhiteSpace(input) ? new byte[] { } : encoding.GetBytes(input);
        }

        #endregion

        #region ToBase64(转换为base64字符串)

        /// <summary>
        /// 转换为base64字符串
        /// </summary>
        /// <param name="input">输入值</param>        
        public static string ToBase64(string input)
        {
            return input.IsEmpty() ? null : System.Convert.ToBase64String(Encoding.UTF8.GetBytes(input));
        }

        #endregion

        #region ToList(泛型集合转换)

        /// <summary>
        /// 泛型集合转换
        /// </summary>
        /// <typeparam name="T">目标元素类型</typeparam>
        /// <param name="input">以逗号分隔的元素集合字符串，范例:83B0233C-A24F-49FD-8083-1337209EBC9A,EAB523C6-2FE7-47BE-89D5-C6D440C3033A</param>
        public static List<T> ToList<T>(string input)
        {
            var result = new List<T>();
            if (string.IsNullOrWhiteSpace(input))
                return result;
            var array = input.Split(',');
            result.AddRange(from each in array where !string.IsNullOrWhiteSpace(each) select To<T>(each));
            return result;
        }

        #endregion

        #region To(通用泛型转换)

        /// <summary>
        /// 通用泛型转换
        /// </summary>
        /// <typeparam name="T">目标类型</typeparam>
        /// <param name="input">输入值</param>
        public static T To<T>(object input)
        {
            if (input == null)
                return default;
            if (input is string && string.IsNullOrWhiteSpace(input.ToString()))
                return default;
            var type = Common.GetType<T>();
            var typeName = type.Name.ToUpperInvariant();
            try
            {
                if (typeName == "STRING" || typeName == "GUID")
                    return (T)TypeDescriptor.GetConverter(typeof(T)).ConvertFromInvariantString(input.ToString());
                if (type.IsEnum)
                    return Enum.Parse<T>(input);
                if (input is IConvertible)
                    return (T)System.Convert.ChangeType(input, type, CultureInfo.InvariantCulture);
                if (input is JsonElement element)
                {
                    var value = element.GetRawText();
                    var options = new JsonSerializerOptions { PropertyNameCaseInsensitive = true };
                    return Json.ToObject<T>(value, options);
                }
                return (T)input;
            }
            catch
            {
                return default;
            }
        }

        #endregion

        #region ToDictionary(对象转换为属性名值对)

        /// <summary>
        /// 对象转换为属性名值对
        /// </summary>
        /// <param name="data">对象</param>
        public static IDictionary<string, object> ToDictionary(object data)
        {
            return ToDictionary(data, false);
        }

        /// <summary>
        /// 对象转换为属性名值对
        /// </summary>
        /// <param name="data">对象</param>
        /// <param name="useDisplayName">是否使用显示名称,可使用[Description] 或 [DisplayName]特性设置</param>
        public static IDictionary<string, object> ToDictionary(object data, bool useDisplayName)
        {
            var result = new Dictionary<string, object>();
            if (data == null)
                return result;
            if (data is IEnumerable<KeyValuePair<string, object>> dic)
                return new Dictionary<string, object>(dic);
            foreach (PropertyDescriptor property in TypeDescriptor.GetProperties(data))
            {
                var value = property.GetValue(data);
                result.Add(GetPropertyDescriptorName(property, useDisplayName), value);
            }
            return result;
        }

        /// <summary>
        /// 获取属性名
        /// </summary>
        private static string GetPropertyDescriptorName(PropertyDescriptor property, bool useDisplayName)
        {
            if (useDisplayName == false)
                return property.Name;
            if (string.IsNullOrEmpty(property.Description) == false)
                return property.Description;
            if (string.IsNullOrEmpty(property.DisplayName) == false)
                return property.DisplayName;
            return property.Name;
        }

        #endregion
    }

    /// <summary>
    /// 区域文化
    /// </summary>
    public static class Culture
    {
        /// <summary>
        /// 获取当前区域文化
        /// </summary>
        public static CultureInfo GetCurrentCulture()
        {
            return CultureInfo.CurrentCulture;
        }

        /// <summary>
        /// 获取当前UI区域文化
        /// </summary>
        public static CultureInfo GetCurrentUICulture()
        {
            return CultureInfo.CurrentUICulture;
        }

        /// <summary>
        /// 获取当前区域文化名称
        /// </summary>
        public static string GetCurrentCultureName()
        {
            return CultureInfo.CurrentCulture.Name;
        }

        /// <summary>
        /// 获取当前UI区域文化名称
        /// </summary>
        public static string GetCurrentUICultureName()
        {
            return CultureInfo.CurrentUICulture.Name;
        }

        /// <summary>
        /// 获取当前区域文化信息列表,包含所有父区域文化
        /// </summary>
        public static List<CultureInfo> GetCurrentCultures()
        {
            return GetCultures(GetCurrentCulture());
        }

        /// <summary>
        /// 获取当前UI区域文化信息列表,包含所有父区域文化
        /// </summary>
        public static List<CultureInfo> GetCurrentUICultures()
        {
            return GetCultures(GetCurrentUICulture());
        }

        /// <summary>
        /// 获取区域文化信息列表,包含所有父区域文化
        /// </summary>
        /// <param name="culture">区域文化信息</param>
        public static List<CultureInfo> GetCultures(CultureInfo culture)
        {
            var result = new List<CultureInfo>();
            if (culture == null)
                return result;
            while (culture.Equals(culture.Parent) == false)
            {
                result.Add(culture);
                culture = culture.Parent;
            }
            return result;
        }
    }

    /// <summary>
    /// 枚举操作
    /// </summary>
    public static class Enum
    {
        /// <summary>
        /// 获取实例
        /// </summary>
        /// <typeparam name="TEnum">枚举类型</typeparam>
        /// <param name="member">成员名或值,范例:Enum1枚举有成员A=0,则传入"A"或"0"获取 Enum1.A</param>
        public static TEnum Parse<TEnum>(object member)
        {
            string value = member.SafeString();
            if (string.IsNullOrWhiteSpace(value))
            {
                if (typeof(TEnum).IsGenericType)
                    return default(TEnum);
                throw new ArgumentNullException(nameof(member));
            }
            return (TEnum)System.Enum.Parse(Common.GetType<TEnum>(), value, true);
        }

        /// <summary>
        /// 获取成员名
        /// </summary>
        /// <typeparam name="TEnum">枚举类型</typeparam>
        /// <param name="member">成员名、值、实例均可,范例:Enum1枚举有成员A=0,则传入Enum1.A或0,获取成员名"A"</param>
        public static string GetName<TEnum>(object member)
        {
            return GetName(Common.GetType<TEnum>(), member);
        }

        /// <summary>
        /// 获取成员名
        /// </summary>
        /// <param name="type">枚举类型</param>
        /// <param name="member">成员名、值、实例均可</param>
        public static string GetName(Type type, object member)
        {
            if (type == null)
                return string.Empty;
            if (member == null)
                return string.Empty;
            if (member is string)
                return member.ToString();
            if (type.GetTypeInfo().IsEnum == false)
                return string.Empty;
            return System.Enum.GetName(type, member);
        }

        /// <summary>
        /// 获取成员值
        /// </summary>
        /// <typeparam name="TEnum">枚举类型</typeparam>
        /// <param name="member">成员名、值、实例均可，范例:Enum1枚举有成员A=0,可传入"A"、0、Enum1.A，获取值0</param>
        public static int? GetValue<TEnum>(object member)
        {
            return GetValue(Common.GetType<TEnum>(), member);
        }

        /// <summary>
        /// 获取成员值
        /// </summary>
        /// <param name="type">枚举类型</param>
        /// <param name="member">成员名、值、实例均可</param>
        public static int? GetValue(Type type, object member)
        {
            string value = member.SafeString();
            if (value.IsEmpty())
                return null;
            var result = System.Enum.Parse(type, value, true);
            return Convert.To<int?>(result);
        }

        /// <summary>
        /// 获取描述,使用System.ComponentModel.Description特性设置描述
        /// </summary>
        /// <typeparam name="TEnum">枚举类型</typeparam>
        /// <param name="member">成员名、值、实例均可</param>
        public static string GetDescription<TEnum>(object member)
        {
            return Reflection.GetDescription<TEnum>(GetName<TEnum>(member));
        }

        /// <summary>
        /// 获取描述,使用System.ComponentModel.Description特性设置描述
        /// </summary>
        /// <param name="type">枚举类型</param>
        /// <param name="member">成员名、值、实例均可</param>
        public static string GetDescription(Type type, object member)
        {
            return Reflection.GetDescription(type, GetName(type, member));
        }

        /// <summary>
        /// 获取项集合,文本设置为Description，值为Value
        /// </summary>
        /// <typeparam name="TEnum">枚举类型</typeparam>
        public static List<Item> GetItems<TEnum>()
        {
            return GetItems(typeof(TEnum));
        }

        /// <summary>
        /// 获取项集合,文本设置为Description，值为Value
        /// </summary>
        /// <param name="type">枚举类型</param>
        public static List<Item> GetItems(Type type)
        {
            type = Common.GetType(type);
            if (type.IsEnum == false)
                throw new InvalidOperationException(string.Format(R.TypeNotEnum, type));
            var result = new List<Item>();
            foreach (var field in type.GetFields())
                AddItem(type, result, field);
            return result.OrderBy(t => t.SortId).ToList();
        }

        /// <summary>
        /// 添加描述项
        /// </summary>
        private static void AddItem(Type type, ICollection<Item> result, FieldInfo field)
        {
            if (!field.FieldType.IsEnum)
                return;
            var value = GetValue(type, field.Name);
            var description = Reflection.GetDescription(field);
            result.Add(new Item(description, value, value));
        }

        /// <summary>
        /// 获取名称集合
        /// </summary>
        /// <typeparam name="TEnum">枚举类型</typeparam>
        public static List<string> GetNames<TEnum>()
        {
            return GetNames(typeof(TEnum));
        }

        /// <summary>
        /// 获取名称集合
        /// </summary>
        /// <param name="type">枚举类型</param>
        public static List<string> GetNames(Type type)
        {
            type = Common.GetType(type);
            if (type.IsEnum == false)
                throw new InvalidOperationException(string.Format(R.TypeNotEnum, type));
            var result = new List<string>();
            foreach (var field in type.GetFields())
            {
                if (!field.FieldType.IsEnum)
                    continue;
                result.Add(field.Name);
            }
            return result;
        }
    }

    /// <summary>
    /// 环境操作
    /// </summary>
    public static class Environment
    {
        /// <summary>
        /// DOTNET_ENVIRONMENT
        /// </summary>
        private const string DOTNET_ENVIRONMENT = "DOTNET_ENVIRONMENT";
        /// <summary>
        /// ASPNETCORE_ENVIRONMENT
        /// </summary>
        private const string ASPNETCORE_ENVIRONMENT = "ASPNETCORE_ENVIRONMENT";
        /// <summary>
        /// Development
        /// </summary>
        private const string Development = "Development";
        /// <summary>
        /// 换行符
        /// </summary>
        public static string NewLine => System.Environment.NewLine;
        /// <summary>
        /// 是否测试环境
        /// </summary>
        public static bool IsTest { get; set; }

        /// <summary>
        /// 设置环境变量
        /// </summary>
        /// <param name="name">环境变量名</param>
        /// <param name="value">值</param>
        public static void SetEnvironmentVariable(string name, object value)
        {
            System.Environment.SetEnvironmentVariable(name, value.SafeString());
        }

        /// <summary>
        /// 获取环境变量
        /// </summary>
        /// <param name="name">环境变量名</param>
        public static string GetEnvironmentVariable(string name)
        {
            return System.Environment.GetEnvironmentVariable(name);
        }

        /// <summary>
        /// 获取环境变量
        /// </summary>
        /// <param name="name">环境变量名</param>
        public static T GetEnvironmentVariable<T>(string name)
        {
            return Convert.To<T>(GetEnvironmentVariable(name));
        }

        /// <summary>
        /// 获取环境名称
        /// </summary>
        public static string GetEnvironmentName()
        {
            var environment = GetEnvironmentVariable(ASPNETCORE_ENVIRONMENT);
            if (environment.IsEmpty() == false)
                return environment;
            return GetEnvironmentVariable(DOTNET_ENVIRONMENT);
        }

        /// <summary>
        /// 设置开发环境变量,如果环境变量已设置则忽略
        /// </summary>
        public static void SetDevelopment()
        {
            var environment = GetEnvironmentVariable(DOTNET_ENVIRONMENT);
            if (environment.IsEmpty() == false)
                return;
            environment = GetEnvironmentVariable(ASPNETCORE_ENVIRONMENT);
            if (environment.IsEmpty() == false)
                return;
            SetEnvironmentVariable(DOTNET_ENVIRONMENT, Development);
            SetEnvironmentVariable(ASPNETCORE_ENVIRONMENT, Development);
        }

        /// <summary>
        /// 是否开发环境
        /// </summary>
        public static bool IsDevelopment()
        {
            var environment = GetEnvironmentVariable(DOTNET_ENVIRONMENT);
            if (environment == Development)
                return true;
            environment = GetEnvironmentVariable(ASPNETCORE_ENVIRONMENT);
            if (environment == Development)
                return true;
            return false;
        }
    }

    /// <summary>
    /// 文件流操作
    /// </summary>
    public static class File
    {

        #region ToBytes

        /// <summary>
        /// 流转换为字节数组
        /// </summary>
        /// <param name="stream">流</param>
        public static byte[] ToBytes(Stream stream)
        {
            stream.Seek(0, SeekOrigin.Begin);
            var buffer = new byte[stream.Length];
            stream.Read(buffer, 0, buffer.Length);
            return buffer;
        }

        /// <summary>
        /// 字符串转换成字节数组
        /// </summary>
        /// <param name="data">数据,默认字符编码utf-8</param>        
        public static byte[] ToBytes(string data)
        {
            return ToBytes(data, Encoding.UTF8);
        }

        /// <summary>
        /// 字符串转换成字节数组
        /// </summary>
        /// <param name="data">数据</param>
        /// <param name="encoding">字符编码</param>
        public static byte[] ToBytes(string data, Encoding encoding)
        {
            if (string.IsNullOrWhiteSpace(data))
                return Array.Empty<byte>();
            return encoding.GetBytes(data);
        }

        #endregion

        #region ToBytesAsync

        /// <summary>
        /// 流转换为字节数组
        /// </summary>
        /// <param name="stream">流</param>
        /// <param name="cancellationToken">取消令牌</param>
        public static async Task<byte[]> ToBytesAsync(Stream stream, CancellationToken cancellationToken = default)
        {
            stream.Seek(0, SeekOrigin.Begin);
            var buffer = new byte[stream.Length];
            await stream.ReadAsync(buffer, 0, buffer.Length, cancellationToken);
            return buffer;
        }

        #endregion

        #region ToStream

        /// <summary>
        /// 字符串转换成流
        /// </summary>
        /// <param name="data">数据</param>
        public static Stream ToStream(string data)
        {
            return ToStream(data, Encoding.UTF8);
        }

        /// <summary>
        /// 字符串转换成流
        /// </summary>
        /// <param name="data">数据</param>
        /// <param name="encoding">字符编码</param>
        public static Stream ToStream(string data, Encoding encoding)
        {
            if (data.IsEmpty())
                return Stream.Null;
            return new MemoryStream(ToBytes(data, encoding));
        }

        #endregion

        #region FileExists

        /// <summary>
        /// 判断文件是否存在
        /// </summary>
        /// <param name="path">文件绝对路径</param>
        public static bool FileExists(string path)
        {
            return System.IO.File.Exists(path);
        }

        #endregion

        #region DirectoryExists

        /// <summary>
        /// 判断目录是否存在
        /// </summary>
        /// <param name="path">目录绝对路径</param>
        public static bool DirectoryExists(string path)
        {
            return Directory.Exists(path);
        }

        #endregion

        #region CreateDirectory

        /// <summary>
        /// 创建目录
        /// </summary>
        /// <param name="path">文件或目录绝对路径</param>
        public static void CreateDirectory(string path)
        {
            if (path.IsEmpty())
                return;
            var file = new FileInfo(path);
            var directoryPath = file.Directory?.FullName;
            if (Directory.Exists(directoryPath))
                return;
            Directory.CreateDirectory(directoryPath);
        }

        #endregion

        #region ReadToString

        /// <summary>
        /// 读取文件到字符串
        /// </summary>
        /// <param name="filePath">文件绝对路径</param>
        public static string ReadToString(string filePath)
        {
            return ReadToString(filePath, Encoding.UTF8);
        }

        /// <summary>
        /// 读取文件到字符串
        /// </summary>
        /// <param name="filePath">文件绝对路径</param>
        /// <param name="encoding">字符编码</param>
        public static string ReadToString(string filePath, Encoding encoding)
        {
            if (System.IO.File.Exists(filePath) == false)
                return string.Empty;
            using var reader = new StreamReader(filePath, encoding);
            return reader.ReadToEnd();
        }

        /// <summary>
        /// 读取流转换成字符串
        /// </summary>
        /// <param name="stream">流</param>
        /// <param name="encoding">字符编码</param>
        /// <param name="bufferSize">缓冲区大小</param>
        /// <param name="isCloseStream">读取完成是否释放流，默认为true</param>
        public static string ReadToString(Stream stream, Encoding encoding = null, int bufferSize = 1024 * 2, bool isCloseStream = true)
        {
            if (stream == null)
                return string.Empty;
            encoding ??= Encoding.UTF8;
            if (stream.CanRead == false)
                return string.Empty;
            using var reader = new StreamReader(stream, encoding, true, bufferSize, !isCloseStream);
            if (stream.CanSeek)
                stream.Seek(0, SeekOrigin.Begin);
            var result = reader.ReadToEnd();
            if (stream.CanSeek)
                stream.Seek(0, SeekOrigin.Begin);
            return result;
        }

        #endregion

        #region ReadToStringAsync

        /// <summary>
        /// 读取文件到字符串
        /// </summary>
        /// <param name="filePath">文件绝对路径</param>
        public static async Task<string> ReadToStringAsync(string filePath)
        {
            return await ReadToStringAsync(filePath, Encoding.UTF8);
        }

        /// <summary>
        /// 读取文件到字符串
        /// </summary>
        /// <param name="filePath">文件绝对路径</param>
        /// <param name="encoding">字符编码</param>
        public static async Task<string> ReadToStringAsync(string filePath, Encoding encoding)
        {
            if (System.IO.File.Exists(filePath) == false)
                return string.Empty;
            using var reader = new StreamReader(filePath, encoding);
            return await reader.ReadToEndAsync();
        }

        #endregion

        #region ReadToStream

        /// <summary>
        /// 读取文件流
        /// </summary>
        /// <param name="filePath">文件绝对路径</param>
        public static Stream ReadToStream(string filePath)
        {
            try
            {
                return new FileStream(filePath, FileMode.Open);
            }
            catch
            {
                return null;
            }
        }

        #endregion

        #region ReadToBytes

        /// <summary>
        /// 将文件读取到字节流中
        /// </summary>
        /// <param name="filePath">文件的绝对路径</param>
        public static byte[] ReadToBytes(string filePath)
        {
            if (!System.IO.File.Exists(filePath))
                return null;
            var fileInfo = new FileInfo(filePath);
            using var reader = new BinaryReader(fileInfo.Open(FileMode.Open));
            return reader.ReadBytes((int)fileInfo.Length);
        }

        /// <summary>
        /// 读取流转换成字节数组
        /// </summary>
        /// <param name="stream">流</param>
        public static byte[] ReadToBytes(Stream stream)
        {
            if (stream == null)
                return null;
            if (stream.CanRead == false)
                return null;
            if (stream.CanSeek)
                stream.Seek(0, SeekOrigin.Begin);
            var buffer = new byte[stream.Length];
            stream.Read(buffer, 0, buffer.Length);
            if (stream.CanSeek)
                stream.Seek(0, SeekOrigin.Begin);
            return buffer;
        }

        #endregion

        #region ReadToBytesAsync

        /// <summary>
        /// 读取流转换成字节数组
        /// </summary>
        /// <param name="stream">流</param>
        /// <param name="cancellationToken">取消令牌</param>
        public static async Task<byte[]> ReadToBytesAsync(Stream stream, CancellationToken cancellationToken = default)
        {
            if (stream == null)
                return null;
            if (stream.CanRead == false)
                return null;
            if (stream.CanSeek)
                stream.Seek(0, SeekOrigin.Begin);
            var buffer = new byte[stream.Length];
            await stream.ReadAsync(buffer, 0, buffer.Length, cancellationToken);
            if (stream.CanSeek)
                stream.Seek(0, SeekOrigin.Begin);
            return buffer;
        }

        #endregion

        #region ReadToMemoryStreamAsync

        /// <summary>
        /// 读取文件到内存流
        /// </summary>
        /// <param name="filePath">文件绝对路径</param>
        /// <param name="cancellationToken">取消令牌</param>
        public static async Task<MemoryStream> ReadToMemoryStreamAsync(string filePath, CancellationToken cancellationToken = default)
        {
            try
            {
                if (FileExists(filePath) == false)
                    return null;
                var memoryStream = new MemoryStream();
                await using var stream = new FileStream(filePath, FileMode.Open);
                await stream.CopyToAsync(memoryStream, cancellationToken).ConfigureAwait(false);
                return memoryStream;
            }
            catch
            {
                return null;
            }
        }

        #endregion

        #region Write

        /// <summary>
        /// 将字符串写入文件
        /// </summary>
        /// <param name="filePath">文件绝对路径</param>
        /// <param name="content">内容</param>
        public static void Write(string filePath, string content)
        {
            if (content.IsEmpty())
                return;
            Write(filePath, Convert.ToBytes(content));
        }

        /// <summary>
        /// 将流写入文件
        /// </summary>
        /// <param name="filePath">文件绝对路径</param>
        /// <param name="content">内容</param>
        public static void Write(string filePath, Stream content)
        {
            if (content == null)
                return;
            using (content)
            {
                var bytes = ToBytes(content);
                Write(filePath, bytes);
            }
        }

        /// <summary>
        /// 将字节流写入文件
        /// </summary>
        /// <param name="filePath">文件绝对路径</param>
        /// <param name="content">内容</param>
        public static void Write(string filePath, byte[] content)
        {
            if (string.IsNullOrWhiteSpace(filePath))
                return;
            if (content == null)
                return;
            CreateDirectory(filePath);
            System.IO.File.WriteAllBytes(filePath, content);
        }

        #endregion

        #region WriteAsync

        /// <summary>
        /// 将字符串写入文件
        /// </summary>
        /// <param name="filePath">文件绝对路径</param>
        /// <param name="content">内容</param>
        /// <param name="cancellationToken">取消令牌</param>
        public static async Task WriteAsync(string filePath, string content, CancellationToken cancellationToken = default)
        {
            if (content.IsEmpty())
                return;
            await WriteAsync(filePath, Convert.ToBytes(content), cancellationToken);
        }

        /// <summary>
        /// 将流写入文件
        /// </summary>
        /// <param name="filePath">文件绝对路径</param>
        /// <param name="content">内容</param>
        /// <param name="cancellationToken">取消令牌</param>
        public static async Task WriteAsync(string filePath, Stream content, CancellationToken cancellationToken = default)
        {
            if (content == null)
                return;
            await using (content)
            {
                var bytes = await ToBytesAsync(content, cancellationToken);
                await WriteAsync(filePath, bytes, cancellationToken);
            }
        }

        /// <summary>
        /// 将字节流写入文件
        /// </summary>
        /// <param name="filePath">文件绝对路径</param>
        /// <param name="content">内容</param>
        /// <param name="cancellationToken">取消令牌</param>
        public static async Task WriteAsync(string filePath, byte[] content, CancellationToken cancellationToken = default)
        {
            if (string.IsNullOrWhiteSpace(filePath))
                return;
            if (content == null)
                return;
            CreateDirectory(filePath);
            await System.IO.File.WriteAllBytesAsync(filePath, content, cancellationToken);
        }

        #endregion

        #region Delete

        /// <summary>
        /// 删除文件
        /// </summary>
        /// <param name="filePaths">文件绝对路径集合</param>
        public static void Delete(IEnumerable<string> filePaths)
        {
            foreach (var filePath in filePaths)
                Delete(filePath);
        }

        /// <summary>
        /// 删除文件
        /// </summary>
        /// <param name="filePath">文件绝对路径</param>
        public static void Delete(string filePath)
        {
            if (string.IsNullOrWhiteSpace(filePath))
                return;
            if (System.IO.File.Exists(filePath))
                System.IO.File.Delete(filePath);
        }

        #endregion

        #region GetAllFiles

        /// <summary>
        /// 获取全部文件,包括所有子目录
        /// </summary>
        /// <param name="path">目录路径</param>
        /// <param name="searchPattern">搜索模式</param>
        public static List<FileInfo> GetAllFiles(string path, string searchPattern)
        {
            return Directory.GetFiles(path, searchPattern, SearchOption.AllDirectories)
                .Select(filePath => new FileInfo(filePath)).ToList();
        }

        #endregion

        #region Copy

        /// <summary>
        /// 复制文件
        /// </summary>
        /// <param name="sourceFilePath">源文件绝对路径</param>
        /// <param name="destinationFilePath">目标文件绝对路径</param>
        /// <param name="overwrite">目标文件存在时是否覆盖,默认值: false</param>
        public static void Copy(string sourceFilePath, string destinationFilePath, bool overwrite = false)
        {
            if (sourceFilePath.IsEmpty() || destinationFilePath.IsEmpty())
                return;
            if (FileExists(sourceFilePath) == false)
                return;
            CreateDirectory(destinationFilePath);
            System.IO.File.Copy(sourceFilePath, destinationFilePath, overwrite);
        }

        #endregion

        #region Move

        /// <summary>
        /// 移动文件
        /// </summary>
        /// <param name="sourceFilePath">源文件绝对路径</param>
        /// <param name="destinationFilePath">目标文件绝对路径</param>
        /// <param name="overwrite">目标文件存在时是否覆盖,默认值: false</param>
        public static void Move(string sourceFilePath, string destinationFilePath, bool overwrite = false)
        {
            if (sourceFilePath.IsEmpty() || destinationFilePath.IsEmpty())
                return;
            if (FileExists(sourceFilePath) == false)
                return;
            CreateDirectory(destinationFilePath);
            System.IO.File.Move(sourceFilePath, destinationFilePath, overwrite);
        }

        #endregion
    }

    /// <summary>
    /// 文件监视器
    /// </summary>
    public class FileWatcher : IDisposable
    {
        /// <summary>
        /// 文件系统监视器
        /// </summary>
        private readonly FileSystemWatcher _watcher;
        /// <summary>
        /// 防抖间隔
        /// </summary>
        private int _debounceInterval;
        /// <summary>
        /// 文件监视事件过滤器
        /// </summary>
        private readonly FileWatcherEventFilter _fileWatcherEventFilter;

        /// <summary>
        /// 初始化文件监视器
        /// </summary>
        public FileWatcher()
        {
            _watcher = new FileSystemWatcher();
            _watcher.NotifyFilter = NotifyFilters.DirectoryName | NotifyFilters.FileName | NotifyFilters.LastWrite
                                    | NotifyFilters.CreationTime | NotifyFilters.LastAccess
                                    | NotifyFilters.Attributes | NotifyFilters.Size | NotifyFilters.Security;
            _debounceInterval = 200;
            _fileWatcherEventFilter = new FileWatcherEventFilter();
        }

        /// <summary>
        /// 设置防抖间隔,默认值: 200 毫秒
        /// </summary>
        /// <param name="interval">防抖间隔, 单位: 毫秒</param>
        public FileWatcher Debounce(int interval)
        {
            _debounceInterval = interval;
            return this;
        }

        /// <summary>
        /// 设置监听目录路径
        /// </summary>
        /// <param name="path">目录绝对路径</param>
        /// <param name="includeSubdirectories">是否监听子目录,默认值: true</param>
        public FileWatcher Path(string path, bool includeSubdirectories = true)
        {
            _watcher.Path = path;
            _watcher.IncludeSubdirectories = includeSubdirectories;
            return this;
        }

        /// <summary>
        /// 设置监听通知过滤
        /// </summary>
        /// <param name="notifyFilters">监听通知过滤</param>
        public FileWatcher NotifyFilter(NotifyFilters notifyFilters)
        {
            _watcher.NotifyFilter = notifyFilters;
            return this;
        }

        /// <summary>
        /// 设置过滤模式
        /// </summary>
        /// <param name="filter">过滤模式,默认值: *.* ,范例: *.cshtml 可过滤cshtml文件</param>
        public FileWatcher Filter(string filter)
        {
            _watcher.Filter = filter;
            return this;
        }

        /// <summary>
        /// 处理文件创建监听事件
        /// </summary>
        /// <param name="action">文件创建监听事件处理器</param>
        public FileWatcher OnCreated(Action<object, FileSystemEventArgs> action)
        {
            _watcher.Created += (source, e) =>
            {
                if (_fileWatcherEventFilter.IsValid(e.FullPath, _debounceInterval))
                    action(source, e);
            };
            return this;
        }

        /// <summary>
        /// 处理文件创建监听事件
        /// </summary>
        /// <param name="action">文件创建监听事件处理器</param>
        public FileWatcher OnCreatedAsync(Func<object, FileSystemEventArgs, Task> action)
        {
            _watcher.Created += async (source, e) =>
            {
                if (_fileWatcherEventFilter.IsValid(e.FullPath, _debounceInterval))
                    await action(source, e);
            };
            return this;
        }

        /// <summary>
        /// 处理文件变更监听事件
        /// </summary>
        /// <param name="action">文件变更监听事件处理器</param>
        public FileWatcher OnChanged(Action<object, FileSystemEventArgs> action)
        {
            _watcher.Changed += (source, e) =>
            {
                if (_fileWatcherEventFilter.IsValid(e.FullPath, _debounceInterval))
                    action(source, e);
            };
            return this;
        }

        /// <summary>
        /// 处理文件变更监听事件
        /// </summary>
        /// <param name="action">文件变更监听事件处理器</param>
        public FileWatcher OnChangedAsync(Func<object, FileSystemEventArgs, Task> action)
        {
            _watcher.Changed += async (source, e) =>
            {
                if (_fileWatcherEventFilter.IsValid(e.FullPath, _debounceInterval))
                    await action(source, e);
            };
            return this;
        }

        /// <summary>
        /// 处理文件删除监听事件
        /// </summary>
        /// <param name="action">文件删除监听事件处理器</param>
        public FileWatcher OnDeleted(Action<object, FileSystemEventArgs> action)
        {
            _watcher.Deleted += (source, e) =>
            {
                if (_fileWatcherEventFilter.IsValid(e.FullPath, _debounceInterval))
                    action(source, e);
            };
            return this;
        }

        /// <summary>
        /// 处理文件删除监听事件
        /// </summary>
        /// <param name="action">文件删除监听事件处理器</param>
        public FileWatcher OnDeletedAsync(Func<object, FileSystemEventArgs, Task> action)
        {
            _watcher.Deleted += async (source, e) =>
            {
                if (_fileWatcherEventFilter.IsValid(e.FullPath, _debounceInterval))
                    await action(source, e);
            };
            return this;
        }

        /// <summary>
        /// 处理文件重命名监听事件
        /// </summary>
        /// <param name="action">文件重命名监听事件处理器</param>
        public FileWatcher OnRenamed(Action<object, RenamedEventArgs> action)
        {
            _watcher.Renamed += (source, e) =>
            {
                if (_fileWatcherEventFilter.IsValid(e.FullPath, _debounceInterval))
                    action(source, e);
            };
            return this;
        }

        /// <summary>
        /// 处理文件重命名监听事件
        /// </summary>
        /// <param name="action">文件重命名监听事件处理器</param>
        public FileWatcher OnRenamedAsync(Func<object, RenamedEventArgs, Task> action)
        {
            _watcher.Renamed += async (source, e) =>
            {
                if (_fileWatcherEventFilter.IsValid(e.FullPath, _debounceInterval))
                    await action(source, e);
            };
            return this;
        }

        /// <summary>
        /// 处理文件错误监听事件
        /// </summary>
        /// <param name="action">文件错误监听事件处理器</param>
        public FileWatcher OnError(Action<object, ErrorEventArgs> action)
        {
            _watcher.Error += (source, e) =>
            {
                action(source, e);
            };
            return this;
        }

        /// <summary>
        /// 处理文件错误监听事件
        /// </summary>
        /// <param name="action">文件错误监听事件处理器</param>
        public FileWatcher OnErrorAsync(Func<object, ErrorEventArgs, Task> action)
        {
            _watcher.Error += async (source, e) =>
            {
                await action(source, e);
            };
            return this;
        }

        /// <summary>
        /// 处理文件监听器释放事件
        /// </summary>
        /// <param name="action">文件监听器释放事件处理器</param>
        public FileWatcher OnDisposed(Action<object, EventArgs> action)
        {
            _watcher.Disposed += (source, e) =>
            {
                action(source, e);
            };
            return this;
        }

        /// <summary>
        /// 处理文件监听器释放事件
        /// </summary>
        /// <param name="action">文件监听器释放事件处理器</param>
        public FileWatcher OnDisposedAsync(Func<object, EventArgs, Task> action)
        {
            _watcher.Disposed += async (source, e) =>
            {
                await action(source, e);
            };
            return this;
        }

        /// <summary>
        /// 启动监听
        /// </summary>
        public FileWatcher Start()
        {
            _watcher.EnableRaisingEvents = true;
            return this;
        }

        /// <summary>
        /// 停止监听
        /// </summary>
        public FileWatcher Stop()
        {
            _watcher.EnableRaisingEvents = false;
            return this;
        }

        /// <summary>
        /// 释放
        /// </summary>
        public void Dispose()
        {
            _watcher?.Dispose();
        }
    }

    /// <summary>
    /// 文件监视事件过滤器
    /// </summary>
    internal class FileWatcherEventFilter
    {
        /// <summary>
        /// 最后一个文件
        /// </summary>
        private WatchFile _file;

        /// <summary>
        /// 监视事件是否有效
        /// </summary>
        /// <param name="path">文件路径</param>
        /// <param name="debounceInterval">防抖间隔</param>
        internal bool IsValid(string path, int debounceInterval)
        {
            if (_file != null && path == _file.Path && DateTime.Now - _file.Time < TimeSpan.FromMilliseconds(debounceInterval))
            {
                _file = new WatchFile(path);
                return false;
            }
            _file = new WatchFile(path);
            return true;
        }
    }

    /// <summary>
    /// 监视文件
    /// </summary>
    internal class WatchFile
    {
        /// <summary>
        /// 初始化监视文件
        /// </summary>
        /// <param name="path">文件路径</param>
        public WatchFile(string path)
        {
            Path = path;
            Time = DateTime.Now;
        }

        /// <summary>
        /// 文件路径
        /// </summary>
        public string Path { get; }

        /// <summary>
        /// 处理时间
        /// </summary>
        public DateTime Time { get; }
    }

    /// <summary>
    /// 容器操作
    /// </summary>
    public static class Ioc
    {
        /// <summary>
        /// 容器
        /// </summary>
        private static readonly Container _container = Container.Instance;
        /// <summary>
        /// 获取服务提供器操作
        /// </summary>
        private static Func<IServiceProvider> _getServiceProviderAction;

        /// <summary>
        /// 服务范围工厂
        /// </summary>
        public static IServiceScopeFactory ServiceScopeFactory { get; set; }

        /// <summary>
        /// 创建新容器
        /// </summary>
        public static Container CreateContainer()
        {
            return new Container();
        }

        /// <summary>
        /// 获取服务集合
        /// </summary>
        public static IServiceCollection GetServices()
        {
            return _container.GetServices();
        }

        /// <summary>
        /// 设置获取服务提供器操作
        /// </summary>
        /// <param name="action">获取服务提供器操作</param>
        public static void SetServiceProviderAction(Func<IServiceProvider> action)
        {
            _getServiceProviderAction = action;
        }

        /// <summary>
        /// 获取
        /// </summary>
        public static IServiceProvider GetServiceProvider()
        {
            var provider = _getServiceProviderAction?.Invoke();
            if (provider != null)
                return provider;
            return _container.GetServiceProvider();
        }

        /// <summary>
        /// 创建对象
        /// </summary>
        /// <typeparam name="T">对象类型</typeparam>
        public static T Create<T>()
        {
            return Create<T>(typeof(T));
        }

        /// <summary>
        /// 创建对象
        /// </summary>
        /// <typeparam name="T">返回对象类型</typeparam>
        /// <param name="type">对象类型</param>
        public static T Create<T>(Type type)
        {
            var service = Create(type);
            if (service == null)
                return default;
            return (T)service;
        }

        /// <summary>
        /// 创建对象
        /// </summary>
        /// <param name="type">对象类型</param>
        public static object Create(Type type)
        {
            if (type == null)
                return null;
            var provider = GetServiceProvider();
            return provider.GetService(type);
        }

        /// <summary>
        /// 创建对象集合
        /// </summary>
        /// <typeparam name="T">返回类型</typeparam>
        public static List<T> CreateList<T>()
        {
            return CreateList<T>(typeof(T));
        }

        /// <summary>
        /// 创建对象集合
        /// </summary>
        /// <typeparam name="T">返回类型</typeparam>
        /// <param name="type">对象类型</param>
        public static List<T> CreateList<T>(Type type)
        {
            Type serviceType = typeof(IEnumerable<>).MakeGenericType(type);
            var result = Create(serviceType);
            if (result == null)
                return new List<T>();
            return ((IEnumerable<T>)result).ToList();
        }

        /// <summary>
        /// 创建服务范围
        /// </summary>
        public static IServiceScope CreateScope()
        {
            var provider = GetServiceProvider();
            return provider.CreateScope();
        }

        /// <summary>
        /// 清理
        /// </summary>
        public static void Clear()
        {
            _container.Clear();
        }
    }

    /// <summary>
    /// Json操作
    /// </summary>
    public static class Json
    {
        /// <summary>
        /// 将对象转换为Json字符串
        /// </summary>
        /// <param name="value">目标对象</param>
        /// <param name="options">Json配置</param>
        public static string ToJson<T>(T value, JsonOptions options)
        {
            if (options == null)
                return ToJson(value);
            var jsonSerializerOptions = ToJsonSerializerOptions(options);
            return ToJson(value, jsonSerializerOptions, options.RemoveQuotationMarks, options.ToSingleQuotes, options.IgnoreInterface);
        }

        /// <summary>
        /// 转换序列化配置
        /// </summary>
        private static JsonSerializerOptions ToJsonSerializerOptions(JsonOptions options)
        {
            var jsonSerializerOptions = new JsonSerializerOptions();
            if (options.IgnoreEmptyString)
            {
                jsonSerializerOptions.TypeInfoResolver = new DefaultJsonTypeInfoResolver
                {
                    Modifiers = { IgnoreEmptyString }
                };
            }
            if (options.IgnoreNullValues)
                jsonSerializerOptions.DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull;
            if (options.IgnoreCase)
                jsonSerializerOptions.PropertyNameCaseInsensitive = true;
            if (options.ToCamelCase)
                jsonSerializerOptions.PropertyNamingPolicy = JsonNamingPolicy.CamelCase;
            jsonSerializerOptions.Encoder = JavaScriptEncoder.Create(UnicodeRanges.All);
            jsonSerializerOptions.Converters.Add(new DateTimeJsonConverter());
            jsonSerializerOptions.Converters.Add(new NullableDateTimeJsonConverter());
            jsonSerializerOptions.Converters.Add(new LongJsonConverter());
            jsonSerializerOptions.Converters.Add(new NullableLongJsonConverter());
            return jsonSerializerOptions;
        }

        /// <summary>
        /// 忽略空字符串
        /// </summary>
        private static void IgnoreEmptyString(JsonTypeInfo jsonTypeInfo)
        {
            if (jsonTypeInfo.Kind != JsonTypeInfoKind.Object)
                return;
            foreach (JsonPropertyInfo jsonPropertyInfo in jsonTypeInfo.Properties)
            {
                if (jsonPropertyInfo.PropertyType == typeof(string))
                {
                    jsonPropertyInfo.ShouldSerialize = static (_, value) => value.SafeString().IsEmpty() == false;
                }
            }
        }

        /// <summary>
        /// 将对象转换为Json字符串
        /// </summary>
        /// <param name="value">目标对象</param>
        /// <param name="options">序列化配置</param>
        /// <param name="removeQuotationMarks">是否移除双引号</param>
        /// <param name="toSingleQuotes">是否将双引号转成单引号</param>
        public static string ToJson<T>(T value, JsonSerializerOptions options = null, bool removeQuotationMarks = false, bool toSingleQuotes = false)
        {
            return ToJson(value, options, removeQuotationMarks, toSingleQuotes, true);
        }

        /// <summary>
        /// 将对象转换为Json字符串
        /// </summary>
        private static string ToJson<T>(T value, JsonSerializerOptions options, bool removeQuotationMarks, bool toSingleQuotes, bool ignoreInterface)
        {
            if (value == null)
                return string.Empty;
            options = GetToJsonOptions(options);
            var result = Serialize(value, options, ignoreInterface);
            if (removeQuotationMarks)
                result = result.Replace("\"", "");
            if (toSingleQuotes)
                result = result.Replace("\"", "'");
            return result;
        }

        /// <summary>
        /// 获取对象转换为Json字符串的序列化配置
        /// </summary>
        private static JsonSerializerOptions GetToJsonOptions(JsonSerializerOptions options)
        {
            if (options != null)
                return options;
            return new JsonSerializerOptions
            {
                DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
                Encoder = JavaScriptEncoder.Create(UnicodeRanges.All),
                Converters = {
                new DateTimeJsonConverter(),
                new NullableDateTimeJsonConverter(),
                new LongJsonConverter(),
                new NullableLongJsonConverter()
            }
            };
        }

        /// <summary>
        /// Json序列化
        /// </summary>
        private static string Serialize<T>(T value, JsonSerializerOptions options, bool ignoreInterface)
        {
            if (ignoreInterface)
            {
                object instance = value;
                if (instance != null)
                    return JsonSerializer.Serialize(instance, options);
            }
            return JsonSerializer.Serialize(value, options);
        }

        /// <summary>
        /// 将对象转换为Json字符串
        /// </summary>
        /// <param name="value">目标对象</param>
        /// <param name="options">序列化配置</param>
        /// <param name="cancellationToken">取消令牌</param>
        public static async Task<string> ToJsonAsync<T>(T value, JsonSerializerOptions options = null, CancellationToken cancellationToken = default)
        {
            if (value == null)
                return string.Empty;
            options = GetToJsonOptions(options);
            await using var stream = new MemoryStream();
            await JsonSerializer.SerializeAsync(stream, value, typeof(T), options, cancellationToken);
            stream.Position = 0;
            using var reader = new StreamReader(stream);
            return await reader.ReadToEndAsync(cancellationToken);
        }

        /// <summary>
        /// 将Json字符串转换为对象
        /// </summary>
        /// <param name="json">Json字符串</param>
        /// <param name="options">序列化配置</param>
        public static T ToObject<T>(string json, JsonOptions options)
        {
            if (string.IsNullOrWhiteSpace(json))
                return default;
            if (options == null)
                return ToObject<T>(json);
            return ToObject<T>(json, ToJsonSerializerOptions(options));
        }

        /// <summary>
        /// 将Json字符串转换为对象
        /// </summary>
        /// <param name="json">Json字符串</param>
        /// <param name="options">序列化配置</param>
        public static T ToObject<T>(string json, JsonSerializerOptions options = null)
        {
            if (string.IsNullOrWhiteSpace(json))
                return default;
            options = GetToObjectOptions(options);
            return JsonSerializer.Deserialize<T>(json, options);
        }

        /// <summary>
        /// 将Json字符串转换为对象
        /// </summary>
        /// <param name="json">Json字符串</param>
        /// <param name="returnType">返回类型</param>
        /// <param name="options">序列化配置</param>
        public static object ToObject(string json, Type returnType, JsonSerializerOptions options = null)
        {
            if (string.IsNullOrWhiteSpace(json))
                return default;
            options = GetToObjectOptions(options);
            return JsonSerializer.Deserialize(json, returnType, options);
        }

        /// <summary>
        /// 获取Json字符串转换为对象的序列化配置
        /// </summary>
        private static JsonSerializerOptions GetToObjectOptions(JsonSerializerOptions options)
        {
            if (options != null)
                return options;
            return new JsonSerializerOptions
            {
                PropertyNameCaseInsensitive = true,
                NumberHandling = JsonNumberHandling.AllowReadingFromString,
                Encoder = JavaScriptEncoder.Create(UnicodeRanges.All),
                Converters = {
                new DateTimeJsonConverter(),
                new NullableDateTimeJsonConverter(),
                new LongJsonConverter(),
                new NullableLongJsonConverter()
            }
            };
        }

        /// <summary>
        /// 将Json字节数组转换为对象
        /// </summary>
        /// <param name="json">Json字节数组</param>
        /// <param name="options">序列化配置</param>
        public static T ToObject<T>(byte[] json, JsonSerializerOptions options = null)
        {
            if (json == null)
                return default;
            options = GetToObjectOptions(options);
            return JsonSerializer.Deserialize<T>(json, options);
        }

        /// <summary>
        /// 将Json字节流转换为对象
        /// </summary>
        /// <param name="json">Json字节流</param>
        /// <param name="options">序列化配置</param>
        public static T ToObject<T>(Stream json, JsonSerializerOptions options = null)
        {
            if (json == null)
                return default;
            options = GetToObjectOptions(options);
            return JsonSerializer.Deserialize<T>(json, options);
        }

        /// <summary>
        /// 将Json字符串转换为对象
        /// </summary>
        /// <param name="json">Json字符串</param>
        /// <param name="options">序列化配置</param>
        /// <param name="encoding">Json字符编码,默认UTF8</param>
        /// <param name="cancellationToken">取消令牌</param>
        public static async Task<T> ToObjectAsync<T>(string json, JsonSerializerOptions options = null, Encoding encoding = null, CancellationToken cancellationToken = default)
        {
            if (string.IsNullOrWhiteSpace(json))
                return default;
            encoding ??= Encoding.UTF8;
            byte[] bytes = encoding.GetBytes(json);
            await using var stream = new MemoryStream(bytes);
            return await ToObjectAsync<T>(stream, options, cancellationToken);
        }

        /// <summary>
        /// 将Json流转换为对象
        /// </summary>
        /// <param name="json">Json流</param>
        /// <param name="options">序列化配置</param>
        /// <param name="cancellationToken">取消令牌</param>
        public static async Task<T> ToObjectAsync<T>(Stream json, JsonSerializerOptions options = null, CancellationToken cancellationToken = default)
        {
            if (json == null)
                return default;
            options = GetToObjectOptions(options);
            return await JsonSerializer.DeserializeAsync<T>(json, options, cancellationToken);
        }

        /// <summary>
        /// 将Json流转换为对象
        /// </summary>
        /// <param name="json">Json流</param>
        /// <param name="options">序列化配置</param>
        /// <param name="cancellationToken">取消令牌</param>
        public static async Task<T> ToObjectAsync<T>(byte[] json, JsonSerializerOptions options = null, CancellationToken cancellationToken = default)
        {
            if (json == null)
                return default;
            await using var stream = new MemoryStream(json);
            return await ToObjectAsync<T>(stream, options, cancellationToken);
        }

        /// <summary>
        /// 将对象转换为字节数组
        /// </summary>
        /// <param name="value">目标对象</param>
        /// <param name="options">Json配置</param>
        public static byte[] ToBytes<T>(T value, JsonSerializerOptions options = null)
        {
            options = GetToBytesOptions(options);
            return JsonSerializer.SerializeToUtf8Bytes(value, options);
        }

        /// <summary>
        /// 获取转换为字节数组的序列化配置
        /// </summary>
        private static JsonSerializerOptions GetToBytesOptions(JsonSerializerOptions options)
        {
            if (options != null)
                return options;
            return new JsonSerializerOptions
            {
                Encoder = JavaScriptEncoder.Create(UnicodeRanges.All),
                Converters = {
                new DateTimeJsonConverter(),
                new NullableDateTimeJsonConverter(),
                new LongJsonConverter(),
                new NullableLongJsonConverter()
            }
            };
        }
    }

    /// <summary>
    /// Lambda表达式操作
    /// </summary>
    public static class Lambda
    {

        #region GetType(获取类型)

        /// <summary>
        /// 获取类型
        /// </summary>
        /// <param name="expression">表达式,范例：t => t.Name</param>
        public static Type GetType(Expression expression)
        {
            var memberExpression = GetMemberExpression(expression);
            return memberExpression?.Type;
        }

        #endregion

        #region GetMember(获取成员)

        /// <summary>
        /// 获取成员
        /// </summary>
        /// <param name="expression">表达式,范例：t => t.Name</param>
        public static MemberInfo GetMember(Expression expression)
        {
            var memberExpression = GetMemberExpression(expression);
            return memberExpression?.Member;
        }

        /// <summary>
        /// 获取成员表达式
        /// </summary>
        /// <param name="expression">表达式</param>
        /// <param name="right">取表达式右侧,(l,r) => l.id == r.id，设置为true,返回r.id表达式</param>
        public static MemberExpression GetMemberExpression(Expression expression, bool right = false)
        {
            if (expression == null)
                return null;
            switch (expression.NodeType)
            {
                case ExpressionType.Lambda:
                    return GetMemberExpression(((LambdaExpression)expression).Body, right);
                case ExpressionType.Convert:
                case ExpressionType.Not:
                    return GetMemberExpression(((UnaryExpression)expression).Operand, right);
                case ExpressionType.MemberAccess:
                    return (MemberExpression)expression;
                case ExpressionType.Equal:
                case ExpressionType.NotEqual:
                case ExpressionType.GreaterThan:
                case ExpressionType.LessThan:
                case ExpressionType.GreaterThanOrEqual:
                case ExpressionType.LessThanOrEqual:
                    return GetMemberExpression(right ? ((BinaryExpression)expression).Right : ((BinaryExpression)expression).Left, right);
                case ExpressionType.Call:
                    return GetMethodCallExpressionName(expression);
            }
            return null;
        }

        /// <summary>
        /// 获取方法调用表达式的成员名称
        /// </summary>
        private static MemberExpression GetMethodCallExpressionName(Expression expression)
        {
            var methodCallExpression = (MethodCallExpression)expression;
            var left = (MemberExpression)methodCallExpression.Object;
            if (Reflection.IsGenericCollection(left?.Type))
            {
                var argumentExpression = methodCallExpression.Arguments.FirstOrDefault();
                if (argumentExpression != null && argumentExpression.NodeType == ExpressionType.MemberAccess)
                    return (MemberExpression)argumentExpression;
            }
            return left;
        }

        #endregion

        #region GetName(获取成员名称)

        /// <summary>
        /// 获取成员名称，范例：t => t.A.Name,返回 A.Name
        /// </summary>
        /// <param name="expression">表达式,范例：t => t.Name</param>
        public static string GetName(Expression expression)
        {
            var memberExpression = GetMemberExpression(expression);
            return GetMemberName(memberExpression);
        }

        /// <summary>
        /// 获取成员名称
        /// </summary>
        public static string GetMemberName(MemberExpression memberExpression)
        {
            if (memberExpression == null)
                return string.Empty;
            string result = memberExpression.ToString();
            return result.Substring(result.IndexOf(".", StringComparison.Ordinal) + 1);
        }

        #endregion

        #region GetNames(获取名称列表)

        /// <summary>
        /// 获取名称列表，范例：t => new object[] { t.A.B, t.C },返回A.B,C
        /// </summary>
        /// <typeparam name="T">实体类型</typeparam>
        /// <param name="expression">属性集合表达式,范例：t => new object[]{t.A,t.B}</param>
        public static List<string> GetNames<T>(Expression<Func<T, object[]>> expression)
        {
            var result = new List<string>();
            if (expression == null)
                return result;
            if (!(expression.Body is NewArrayExpression arrayExpression))
                return result;
            foreach (var each in arrayExpression.Expressions)
            {
                var name = GetName(each);
                if (string.IsNullOrWhiteSpace(name) == false)
                    result.Add(name);
            }
            return result;
        }

        #endregion

        #region GetLastName(获取最后一级成员名称)

        /// <summary>
        /// 获取最后一级成员名称，范例：t => t.A.Name,返回 Name
        /// </summary>
        /// <param name="expression">表达式,范例：t => t.Name</param>
        /// <param name="right">取表达式右侧,(l,r) => l.LId == r.RId，设置为true,返回RId</param>
        public static string GetLastName(Expression expression, bool right = false)
        {
            var memberExpression = GetMemberExpression(expression, right);
            if (memberExpression == null)
                return string.Empty;
            if (IsValueExpression(memberExpression))
                return string.Empty;
            string result = memberExpression.ToString();
            return result.Substring(result.LastIndexOf(".", StringComparison.Ordinal) + 1);
        }

        /// <summary>
        /// 是否值表达式
        /// </summary>
        /// <param name="expression">表达式</param>
        private static bool IsValueExpression(Expression expression)
        {
            if (expression == null)
                return false;
            switch (expression.NodeType)
            {
                case ExpressionType.MemberAccess:
                    return IsValueExpression(((MemberExpression)expression).Expression);
                case ExpressionType.Constant:
                    return true;
            }
            return false;
        }

        #endregion

        #region GetLastNames(获取最后一级成员名称列表)

        /// <summary>
        /// 获取最后一级成员名称列表，范例：t => new object[] { t.A.B, t.C },返回B,C
        /// </summary>
        /// <typeparam name="T">实体类型</typeparam>
        /// <param name="expression">属性集合表达式,范例：t => new object[]{t.A,t.B}</param>
        public static List<string> GetLastNames<T>(Expression<Func<T, object[]>> expression)
        {
            var result = new List<string>();
            if (expression == null)
                return result;
            if (!(expression.Body is NewArrayExpression arrayExpression))
                return result;
            foreach (var each in arrayExpression.Expressions)
            {
                var name = GetLastName(each);
                if (string.IsNullOrWhiteSpace(name) == false)
                    result.Add(name);
            }
            return result;
        }

        #endregion

        #region GetValue(获取值)

        /// <summary>
        /// 获取值,范例：t => t.Name == "A",返回 A
        /// </summary>
        /// <param name="expression">表达式,范例：t => t.Name == "A"</param>
        public static object GetValue(Expression expression)
        {
            if (expression == null)
                return null;
            switch (expression.NodeType)
            {
                case ExpressionType.Lambda:
                    return GetValue(((LambdaExpression)expression).Body);
                case ExpressionType.Convert:
                    return GetValue(((UnaryExpression)expression).Operand);
                case ExpressionType.Equal:
                case ExpressionType.NotEqual:
                case ExpressionType.GreaterThan:
                case ExpressionType.LessThan:
                case ExpressionType.GreaterThanOrEqual:
                case ExpressionType.LessThanOrEqual:
                    var hasParameter = HasParameter(((BinaryExpression)expression).Left);
                    if (hasParameter)
                        return GetValue(((BinaryExpression)expression).Right);
                    return GetValue(((BinaryExpression)expression).Left);
                case ExpressionType.Call:
                    return GetMethodCallExpressionValue(expression);
                case ExpressionType.MemberAccess:
                    return GetMemberValue((MemberExpression)expression);
                case ExpressionType.Constant:
                    return GetConstantExpressionValue(expression);
                case ExpressionType.Not:
                    if (expression.Type == typeof(bool))
                        return false;
                    return null;
            }
            return null;
        }

        /// <summary>
        /// 是否包含参数，用于检测是属性，而不是值
        /// </summary>
        private static bool HasParameter(Expression expression)
        {
            if (expression == null)
                return false;
            switch (expression.NodeType)
            {
                case ExpressionType.Convert:
                    return HasParameter(((UnaryExpression)expression).Operand);
                case ExpressionType.MemberAccess:
                    return HasParameter(((MemberExpression)expression).Expression);
                case ExpressionType.Parameter:
                    return true;
            }
            return false;
        }

        /// <summary>
        /// 获取方法调用表达式的值
        /// </summary>
        private static object GetMethodCallExpressionValue(Expression expression)
        {
            var methodCallExpression = (MethodCallExpression)expression;
            var value = GetValue(methodCallExpression.Arguments.FirstOrDefault());
            if (value != null)
                return value;
            if (methodCallExpression.Arguments.Count > 1)
                return GetValue(methodCallExpression.Arguments[1]);
            if (methodCallExpression.Object == null)
                return methodCallExpression.Type.InvokeMember(methodCallExpression.Method.Name, BindingFlags.InvokeMethod, null, null, null);
            return GetValue(methodCallExpression.Object);
        }

        /// <summary>
        /// 获取属性表达式的值
        /// </summary>
        private static object GetMemberValue(MemberExpression expression)
        {
            if (expression == null)
                return null;
            var field = expression.Member as FieldInfo;
            if (field != null)
            {
                var constValue = GetConstantExpressionValue(expression.Expression);
                return field.GetValue(constValue);
            }
            var property = expression.Member as PropertyInfo;
            if (property == null)
                return null;
            if (expression.Expression == null)
                return property.GetValue(null);
            if (expression.Expression is ConstantExpression)
            {
                var constValue = GetConstantExpressionValue(expression.Expression);
                return property.GetValue(constValue);
            }
            var value = GetMemberValue(expression.Expression as MemberExpression);
            if (value == null)
            {
                if (property.PropertyType == typeof(bool))
                    return true;
                return null;
            }
            return property.GetValue(value);
        }

        /// <summary>
        /// 获取常量表达式的值
        /// </summary>
        private static object GetConstantExpressionValue(Expression expression)
        {
            var constantExpression = (ConstantExpression)expression;
            return constantExpression.Value;
        }

        #endregion

        #region GetOperator(获取查询操作符)

        /// <summary>
        /// 获取查询操作符,范例：t => t.Name == "A",返回 Operator.Equal
        /// </summary>
        /// <param name="expression">表达式,范例：t => t.Name == "A"</param>
        public static Operator? GetOperator(Expression expression)
        {
            if (expression == null)
                return null;
            switch (expression.NodeType)
            {
                case ExpressionType.Lambda:
                    return GetOperator(((LambdaExpression)expression).Body);
                case ExpressionType.Convert:
                    return GetOperator(((UnaryExpression)expression).Operand);
                case ExpressionType.Equal:
                    return Operator.Equal;
                case ExpressionType.NotEqual:
                    return Operator.NotEqual;
                case ExpressionType.GreaterThan:
                    return Operator.Greater;
                case ExpressionType.LessThan:
                    return Operator.Less;
                case ExpressionType.GreaterThanOrEqual:
                    return Operator.GreaterEqual;
                case ExpressionType.LessThanOrEqual:
                    return Operator.LessEqual;
                case ExpressionType.Call:
                    return GetMethodCallExpressionOperator(expression);
            }
            return null;
        }

        /// <summary>
        /// 获取方法调用表达式的值
        /// </summary>
        private static Operator? GetMethodCallExpressionOperator(Expression expression)
        {
            var methodCallExpression = (MethodCallExpression)expression;
            switch (methodCallExpression?.Method?.Name?.ToLower())
            {
                case "contains":
                    return Operator.Contains;
                case "endswith":
                    return Operator.Ends;
                case "startswith":
                    return Operator.Starts;
            }
            return null;
        }

        #endregion

        #region GetParameter(获取参数)

        /// <summary>
        /// 获取参数，范例：t.Name,返回 t
        /// </summary>
        /// <param name="expression">表达式，范例：t.Name</param>
        public static ParameterExpression GetParameter(Expression expression)
        {
            if (expression == null)
                return null;
            switch (expression.NodeType)
            {
                case ExpressionType.Lambda:
                    return GetParameter(((LambdaExpression)expression).Body);
                case ExpressionType.Convert:
                    return GetParameter(((UnaryExpression)expression).Operand);
                case ExpressionType.Equal:
                case ExpressionType.NotEqual:
                case ExpressionType.GreaterThan:
                case ExpressionType.LessThan:
                case ExpressionType.GreaterThanOrEqual:
                case ExpressionType.LessThanOrEqual:
                    return GetParameter(((BinaryExpression)expression).Left);
                case ExpressionType.MemberAccess:
                    return GetParameter(((MemberExpression)expression).Expression);
                case ExpressionType.Call:
                    return GetParameter(((MethodCallExpression)expression).Object);
                case ExpressionType.Parameter:
                    return (ParameterExpression)expression;
            }
            return null;
        }

        #endregion

        #region GetGroupPredicates(获取分组的谓词表达式)

        /// <summary>
        /// 获取分组的谓词表达式，通过Or进行分组
        /// </summary>
        /// <param name="expression">谓词表达式</param>
        public static List<List<Expression>> GetGroupPredicates(Expression expression)
        {
            var result = new List<List<Expression>>();
            if (expression == null)
                return result;
            AddPredicates(expression, result, CreateGroup(result));
            return result;
        }

        /// <summary>
        /// 创建分组
        /// </summary>
        private static List<Expression> CreateGroup(List<List<Expression>> result)
        {
            var gourp = new List<Expression>();
            result.Add(gourp);
            return gourp;
        }

        /// <summary>
        /// 添加通过Or分割的谓词表达式
        /// </summary>
        private static void AddPredicates(Expression expression, List<List<Expression>> result, List<Expression> group)
        {
            switch (expression.NodeType)
            {
                case ExpressionType.Lambda:
                    AddPredicates(((LambdaExpression)expression).Body, result, group);
                    break;
                case ExpressionType.OrElse:
                    AddPredicates(((BinaryExpression)expression).Left, result, group);
                    AddPredicates(((BinaryExpression)expression).Right, result, CreateGroup(result));
                    break;
                case ExpressionType.AndAlso:
                    AddPredicates(((BinaryExpression)expression).Left, result, group);
                    AddPredicates(((BinaryExpression)expression).Right, result, group);
                    break;
                default:
                    group.Add(expression);
                    break;
            }
        }

        #endregion

        #region GetConditionCount(获取查询条件个数)

        /// <summary>
        /// 获取查询条件个数
        /// </summary>
        /// <param name="expression">谓词表达式,范例1：t => t.Name == "A" ，结果1。
        /// 范例2：t => t.Name == "A" &amp;&amp; t.Age =1 ，结果2。</param>
        public static int GetConditionCount(LambdaExpression expression)
        {
            if (expression == null)
                return 0;
            var result = expression.ToString().Replace("AndAlso", "|").Replace("OrElse", "|");
            return result.Split('|').Count();
        }

        #endregion

        #region GetAttribute(获取特性)

        /// <summary>
        /// 获取特性
        /// </summary>
        /// <typeparam name="TAttribute">特性类型</typeparam>
        /// <param name="expression">属性表达式</param>
        public static TAttribute GetAttribute<TAttribute>(Expression expression) where TAttribute : Attribute
        {
            var memberInfo = GetMember(expression);
            return memberInfo.GetCustomAttribute<TAttribute>();
        }

        /// <summary>
        /// 获取特性
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// <typeparam name="TProperty">属性类型</typeparam>
        /// <typeparam name="TAttribute">特性类型</typeparam>
        /// <param name="propertyExpression">属性表达式</param>
        public static TAttribute GetAttribute<TEntity, TProperty, TAttribute>(Expression<Func<TEntity, TProperty>> propertyExpression) where TAttribute : Attribute
        {
            return GetAttribute<TAttribute>(propertyExpression);
        }

        /// <summary>
        /// 获取特性
        /// </summary>
        /// <typeparam name="TProperty">属性类型</typeparam>
        /// <typeparam name="TAttribute">特性类型</typeparam>
        /// <param name="propertyExpression">属性表达式</param>
        public static TAttribute GetAttribute<TProperty, TAttribute>(Expression<Func<TProperty>> propertyExpression) where TAttribute : Attribute
        {
            return GetAttribute<TAttribute>(propertyExpression);
        }

        #endregion

        #region GetAttributes(获取特性列表)

        /// <summary>
        /// 获取特性列表
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// <typeparam name="TProperty">属性类型</typeparam>
        /// <typeparam name="TAttribute">特性类型</typeparam>
        /// <param name="propertyExpression">属性表达式</param>
        public static IEnumerable<TAttribute> GetAttributes<TEntity, TProperty, TAttribute>(Expression<Func<TEntity, TProperty>> propertyExpression) where TAttribute : Attribute
        {
            var memberInfo = GetMember(propertyExpression);
            return memberInfo.GetCustomAttributes<TAttribute>();
        }

        #endregion

        #region Constant(获取常量)

        /// <summary>
        /// 获取常量表达式
        /// </summary>
        /// <param name="value">值</param>
        /// <param name="expression">表达式</param>
        public static ConstantExpression Constant(object value, Expression expression = null)
        {
            var type = GetType(expression);
            if (type == null)
                return Expression.Constant(value);
            return Expression.Constant(value, type);
        }

        #endregion

        #region CreateParameter(创建参数表达式)

        /// <summary>
        /// 创建参数表达式
        /// </summary>
        /// <typeparam name="T">参数类型</typeparam>
        public static ParameterExpression CreateParameter<T>()
        {
            return Expression.Parameter(typeof(T), "t");
        }

        #endregion

        #region Equal(等于表达式)

        /// <summary>
        /// 创建等于运算lambda表达式
        /// </summary>
        /// <typeparam name="T">对象类型</typeparam>
        /// <param name="propertyName">属性名</param>
        /// <param name="value">值</param>
        public static Expression<Func<T, bool>> Equal<T>(string propertyName, object value)
        {
            var parameter = CreateParameter<T>();
            return parameter.Property(propertyName).Equal(value).ToPredicate<T>(parameter);
        }

        #endregion

        #region NotEqual(不等于表达式)

        /// <summary>
        /// 创建不等于运算lambda表达式
        /// </summary>
        /// <typeparam name="T">对象类型</typeparam>
        /// <param name="propertyName">属性名</param>
        /// <param name="value">值</param>
        public static Expression<Func<T, bool>> NotEqual<T>(string propertyName, object value)
        {
            var parameter = CreateParameter<T>();
            return parameter.Property(propertyName).NotEqual(value).ToPredicate<T>(parameter);
        }

        #endregion

        #region Greater(大于表达式)

        /// <summary>
        /// 创建大于运算lambda表达式
        /// </summary>
        /// <typeparam name="T">对象类型</typeparam>
        /// <param name="propertyName">属性名</param>
        /// <param name="value">值</param>
        public static Expression<Func<T, bool>> Greater<T>(string propertyName, object value)
        {
            var parameter = CreateParameter<T>();
            return parameter.Property(propertyName).Greater(value).ToPredicate<T>(parameter);
        }

        #endregion

        #region GreaterEqual(大于等于表达式)

        /// <summary>
        /// 创建大于等于运算lambda表达式
        /// </summary>
        /// <typeparam name="T">对象类型</typeparam>
        /// <param name="propertyName">属性名</param>
        /// <param name="value">值</param>
        public static Expression<Func<T, bool>> GreaterEqual<T>(string propertyName, object value)
        {
            var parameter = CreateParameter<T>();
            return parameter.Property(propertyName).GreaterEqual(value).ToPredicate<T>(parameter);
        }

        #endregion

        #region Less(小于表达式)

        /// <summary>
        /// 创建小于运算lambda表达式
        /// </summary>
        /// <typeparam name="T">对象类型</typeparam>
        /// <param name="propertyName">属性名</param>
        /// <param name="value">值</param>
        public static Expression<Func<T, bool>> Less<T>(string propertyName, object value)
        {
            var parameter = CreateParameter<T>();
            return parameter.Property(propertyName).Less(value).ToPredicate<T>(parameter);
        }

        #endregion

        #region LessEqual(小于等于表达式)

        /// <summary>
        /// 创建小于等于运算lambda表达式
        /// </summary>
        /// <typeparam name="T">对象类型</typeparam>
        /// <param name="propertyName">属性名</param>
        /// <param name="value">值</param>
        public static Expression<Func<T, bool>> LessEqual<T>(string propertyName, object value)
        {
            var parameter = CreateParameter<T>();
            return parameter.Property(propertyName).LessEqual(value).ToPredicate<T>(parameter);
        }

        #endregion

        #region Starts(调用StartsWith方法)

        /// <summary>
        /// 调用StartsWith方法
        /// </summary>
        /// <typeparam name="T">对象类型</typeparam>
        /// <param name="propertyName">属性名</param>
        /// <param name="value">值</param>
        public static Expression<Func<T, bool>> Starts<T>(string propertyName, object value)
        {
            var parameter = CreateParameter<T>();
            return parameter.Property(propertyName).StartsWith(value).ToPredicate<T>(parameter);
        }

        #endregion

        #region Ends(调用EndsWith方法)

        /// <summary>
        /// 调用EndsWith方法
        /// </summary>
        /// <typeparam name="T">对象类型</typeparam>
        /// <param name="propertyName">属性名</param>
        /// <param name="value">值</param>
        public static Expression<Func<T, bool>> Ends<T>(string propertyName, object value)
        {
            var parameter = CreateParameter<T>();
            return parameter.Property(propertyName).EndsWith(value).ToPredicate<T>(parameter);
        }

        #endregion

        #region Contains(调用Contains方法)

        /// <summary>
        /// 调用Contains方法
        /// </summary>
        /// <typeparam name="T">对象类型</typeparam>
        /// <param name="propertyName">属性名</param>
        /// <param name="value">值</param>
        public static Expression<Func<T, bool>> Contains<T>(string propertyName, object value)
        {
            var parameter = CreateParameter<T>();
            return parameter.Property(propertyName).Contains(value).ToPredicate<T>(parameter);
        }

        #endregion

        #region ParsePredicate(解析为谓词表达式)

        /// <summary>
        /// 解析为谓词表达式
        /// </summary>
        /// <typeparam name="T">实体类型</typeparam>
        /// <param name="propertyName">属性名</param>
        /// <param name="value">值</param>
        /// <param name="operator">运算符</param>
        public static Expression<Func<T, bool>> ParsePredicate<T>(string propertyName, object value, Operator @operator)
        {
            var parameter = CreateParameter<T>();
            return parameter.Property(propertyName).Operation(@operator, value).ToPredicate<T>(parameter);
        }

        #endregion
    }

    /// <summary>
    /// 随机数操作
    /// </summary>
    public class Random
    {
        /// <summary>
        /// 随机数
        /// </summary>
        private readonly System.Random _random;

        /// <summary>
        /// 初始化随机数
        /// </summary>
        public Random()
        {
            _random = new System.Random();
        }

        /// <summary>
        /// 获取指定范围的随机整数
        /// </summary>
        /// <param name="max">最大值</param>
        public int Next(int max)
        {
            return _random.Next(max);
        }

        /// <summary>
        /// 获取指定范围的随机整数，该范围包括最小值，但不包括最大值
        /// </summary>
        /// <param name="min">最小值</param>
        /// <param name="max">最大值</param>
        public int Next(int min, int max)
        {
            return _random.Next(min, max);
        }

        /// <summary>
        /// 从集合中随机获取值
        /// </summary>
        /// <param name="array">集合</param>
        public static T GetValue<T>(IEnumerable<T> array)
        {
            if (array == null)
                return default;
            var list = array.ToList();
            var index = System.Random.Shared.Next(0, list.Count);
            return list[index];
        }

        /// <summary>
        /// 从集合中随机获取值列表
        /// </summary>
        /// <param name="array">集合</param>
        /// <param name="count">获取数量</param>
        public static List<T> GetValues<T>(IEnumerable<T> array, int count)
        {
            var result = new List<T>();
            if (array == null)
                return result;
            var list = array.ToList();
            while (list.Count > 0 && result.Count < count)
            {
                var index = System.Random.Shared.Next(0, list.Count);
                var item = list[index];
                result.Add(item);
                list.Remove(item);
            }
            return result;
        }

        /// <summary>
        /// 对集合随机排序
        /// </summary>
        /// <typeparam name="T">集合元素类型</typeparam>
        /// <param name="array">集合</param>
        public static List<T> Sort<T>(IEnumerable<T> array)
        {
            if (array == null)
                return null;
            var list = array.ToList();
            for (int i = 0; i < list.Count; i++)
            {
                int index1 = System.Random.Shared.Next(0, list.Count);
                int index2 = System.Random.Shared.Next(0, list.Count);
                (list[index1], list[index2]) = (list[index2], list[index1]);
            }
            return list;
        }
    }

    /// <summary>
    /// 反射操作
    /// </summary>
    public static class Reflection
    {

        #region GetDescription(获取描述)

        /// <summary>
        /// 获取类型描述，使用DescriptionAttribute设置描述
        /// </summary>
        /// <typeparam name="T">类型</typeparam>
        public static string GetDescription<T>()
        {
            return GetDescription(Common.GetType<T>());
        }

        /// <summary>
        /// 获取类型成员描述，使用DescriptionAttribute设置描述
        /// </summary>
        /// <typeparam name="T">类型</typeparam>
        /// <param name="memberName">成员名称</param>
        public static string GetDescription<T>(string memberName)
        {
            return GetDescription(Common.GetType<T>(), memberName);
        }

        /// <summary>
        /// 获取类型成员描述，使用DescriptionAttribute设置描述
        /// </summary>
        /// <param name="type">类型</param>
        /// <param name="memberName">成员名称</param>
        public static string GetDescription(Type type, string memberName)
        {
            if (type == null)
                return string.Empty;
            if (string.IsNullOrWhiteSpace(memberName))
                return string.Empty;
            return GetDescription(type.GetTypeInfo().GetMember(memberName).FirstOrDefault());
        }

        /// <summary>
        /// 获取类型成员描述，使用DescriptionAttribute设置描述
        /// </summary>
        /// <param name="member">成员</param>
        public static string GetDescription(MemberInfo member)
        {
            if (member == null)
                return string.Empty;
            return member.GetCustomAttribute<DescriptionAttribute>() is { } attribute ? attribute.Description : member.Name;
        }

        #endregion

        #region GetDisplayName(获取显示名称)

        /// <summary>
        /// 获取显示名称，使用DisplayNameAttribute设置显示名称
        /// </summary>
        /// <typeparam name="T">类型</typeparam>
        public static string GetDisplayName<T>()
        {
            return GetDisplayName(Common.GetType<T>());
        }

        /// <summary>
        /// 获取显示名称，使用DisplayAttribute或DisplayNameAttribute设置显示名称
        /// </summary>
        public static string GetDisplayName(MemberInfo member)
        {
            if (member == null)
                return string.Empty;
            if (member.GetCustomAttribute<DisplayAttribute>() is { } displayAttribute)
                return displayAttribute.Name;
            if (member.GetCustomAttribute<DisplayNameAttribute>() is { } displayNameAttribute)
                return displayNameAttribute.DisplayName;
            return string.Empty;
        }

        #endregion

        #region GetDisplayNameOrDescription(获取显示名称或描述)

        /// <summary>
        /// 获取显示名称或描述,使用DisplayNameAttribute设置显示名称,使用DescriptionAttribute设置描述
        /// </summary>
        /// <typeparam name="T">类型</typeparam>
        public static string GetDisplayNameOrDescription<T>()
        {
            return GetDisplayNameOrDescription(Common.GetType<T>());
        }

        /// <summary>
        /// 获取属性显示名称或描述,使用DisplayAttribute或DisplayNameAttribute设置显示名称,使用DescriptionAttribute设置描述
        /// </summary>
        public static string GetDisplayNameOrDescription(MemberInfo member)
        {
            var result = GetDisplayName(member);
            return string.IsNullOrWhiteSpace(result) ? GetDescription(member) : result;
        }

        #endregion

        #region CreateInstance(动态创建实例)

        /// <summary>
        /// 动态创建实例
        /// </summary>
        /// <typeparam name="T">目标类型</typeparam>
        /// <param name="type">类型</param>
        /// <param name="parameters">传递给构造函数的参数</param>        
        public static T CreateInstance<T>(Type type, params object[] parameters)
        {
            return Convert.To<T>(Activator.CreateInstance(type, parameters));
        }

        #endregion

        #region FindImplementTypes(查找实现类型列表)

        /// <summary>
        /// 在指定的程序集中查找实现类型列表
        /// </summary>
        /// <typeparam name="TFind">查找类型</typeparam>
        /// <param name="assemblies">待查找的程序集列表</param>
        public static List<Type> FindImplementTypes<TFind>(params Assembly[] assemblies)
        {
            return FindImplementTypes(typeof(TFind), assemblies);
        }

        /// <summary>
        /// 在指定的程序集中查找实现类型列表
        /// </summary>
        /// <param name="findType">查找类型</param>
        /// <param name="assemblies">待查找的程序集列表</param>
        public static List<Type> FindImplementTypes(Type findType, params Assembly[] assemblies)
        {
            var result = new List<Type>();
            foreach (var assembly in assemblies)
                result.AddRange(GetTypes(findType, assembly));
            return result.Distinct().ToList();
        }

        /// <summary>
        /// 获取类型列表
        /// </summary>
        private static List<Type> GetTypes(Type findType, Assembly assembly)
        {
            var result = new List<Type>();
            if (assembly == null)
                return result;
            Type[] types;
            try
            {
                types = assembly.GetTypes();
            }
            catch (ReflectionTypeLoadException)
            {
                return result;
            }
            foreach (var type in types)
                AddType(result, findType, type);
            return result;
        }

        /// <summary>
        /// 添加类型
        /// </summary>
        private static void AddType(List<Type> result, Type findType, Type type)
        {
            if (type.IsInterface || type.IsAbstract)
                return;
            if (findType.IsAssignableFrom(type) == false && MatchGeneric(findType, type) == false)
                return;
            result.Add(type);
        }

        /// <summary>
        /// 泛型匹配
        /// </summary>
        private static bool MatchGeneric(Type findType, Type type)
        {
            if (findType.IsGenericTypeDefinition == false)
                return false;
            var definition = findType.GetGenericTypeDefinition();
            foreach (var implementedInterface in type.FindInterfaces((filter, criteria) => true, null))
            {
                if (implementedInterface.IsGenericType == false)
                    continue;
                return definition.IsAssignableFrom(implementedInterface.GetGenericTypeDefinition());
            }
            return false;
        }

        #endregion

        #region GetDirectInterfaceTypes(获取直接接口类型列表)

        /// <summary>
        /// 获取直接接口类型列表,排除基接口类型
        /// </summary>
        /// <typeparam name="T">在该类型上查找接口</typeparam>
        /// <param name="baseInterfaceTypes">基接口类型列表,只返回继承了基接口的直接接口</param>
        public static List<Type> GetDirectInterfaceTypes<T>(params Type[] baseInterfaceTypes)
        {
            return GetDirectInterfaceTypes(typeof(T), baseInterfaceTypes);
        }

        /// <summary>
        /// 获取直接接口类型列表,排除基接口类型
        /// </summary>
        /// <param name="type">在该类型上查找接口</param>
        /// <param name="baseInterfaceTypes">基接口类型列表,只返回继承了基接口的直接接口</param>
        public static List<Type> GetDirectInterfaceTypes(Type type, params Type[] baseInterfaceTypes)
        {
            var interfaceTypes = type.GetInterfaces();
            var directInterfaceTypes = interfaceTypes.Except(interfaceTypes.SelectMany(t => t.GetInterfaces())).ToList();
            if (baseInterfaceTypes == null || baseInterfaceTypes.Length == 0)
                return directInterfaceTypes;
            return GetInterfaceTypes(directInterfaceTypes, baseInterfaceTypes);
        }

        /// <summary>
        /// 获取接口类型
        /// </summary>
        private static List<Type> GetInterfaceTypes(IEnumerable<Type> interfaceTypes, Type[] baseInterfaceTypes)
        {
            var result = new List<Type>();
            foreach (var interfaceType in interfaceTypes)
            {
                if (interfaceType.GetInterfaces().Any(baseInterfaceTypes.Contains) == false)
                    continue;
                if (interfaceType.IsGenericType && !interfaceType.IsGenericTypeDefinition && interfaceType.FullName == null)
                {
                    result.Add(interfaceType.GetGenericTypeDefinition());
                    continue;
                }
                result.Add(interfaceType);
            }
            return result;
        }

        #endregion

        #region GetInterfaceTypes(获取接口类型列表)

        /// <summary>
        /// 获取接口类型列表,排除基接口类型
        /// </summary>
        /// <typeparam name="T">在该类型上查找接口</typeparam>
        /// <param name="baseInterfaceTypes">基接口类型列表</param>
        public static List<Type> GetInterfaceTypes<T>(params Type[] baseInterfaceTypes)
        {
            return GetInterfaceTypes(typeof(T), baseInterfaceTypes);
        }

        /// <summary>
        /// 获取接口类型列表,排除基接口类型
        /// </summary>
        /// <param name="type">在该类型上查找接口</param>
        /// <param name="baseInterfaceTypes">基接口类型列表</param>
        public static List<Type> GetInterfaceTypes(Type type, params Type[] baseInterfaceTypes)
        {
            var interfaceTypes = type.GetInterfaces();
            if (baseInterfaceTypes == null || baseInterfaceTypes.Length == 0)
                return interfaceTypes.ToList();
            return GetInterfaceTypes(interfaceTypes, baseInterfaceTypes);
        }

        #endregion

        #region IsCollection(是否集合)

        /// <summary>
        /// 是否集合
        /// </summary>
        /// <param name="type">类型</param>
        public static bool IsCollection(Type type)
        {
            if (type.IsArray)
                return true;
            return IsGenericCollection(type);
        }

        #endregion

        #region IsGenericCollection(是否泛型集合)

        /// <summary>
        /// 是否泛型集合
        /// </summary>
        /// <param name="type">类型</param>
        public static bool IsGenericCollection(Type type)
        {
            if (!type.IsGenericType)
                return false;
            var typeDefinition = type.GetGenericTypeDefinition();
            return typeDefinition == typeof(IEnumerable<>)
                   || typeDefinition == typeof(IReadOnlyCollection<>)
                   || typeDefinition == typeof(IReadOnlyList<>)
                   || typeDefinition == typeof(ICollection<>)
                   || typeDefinition == typeof(IList<>)
                   || typeDefinition == typeof(List<>);
        }

        #endregion

        #region IsBool(是否布尔类型)

        /// <summary>
        /// 是否布尔类型
        /// </summary>
        /// <param name="member">成员</param>
        public static bool IsBool(MemberInfo member)
        {
            if (member == null)
                return false;
            switch (member.MemberType)
            {
                case MemberTypes.TypeInfo:
                    return member.ToString() == "System.Boolean";
                case MemberTypes.Property:
                    return IsBool((PropertyInfo)member);
            }
            return false;
        }

        /// <summary>
        /// 是否布尔类型
        /// </summary>
        private static bool IsBool(PropertyInfo property)
        {
            return property.PropertyType == typeof(bool) || property.PropertyType == typeof(bool?);
        }

        #endregion

        #region IsEnum(是否枚举类型)

        /// <summary>
        /// 是否枚举类型
        /// </summary>
        /// <param name="member">成员</param>
        public static bool IsEnum(MemberInfo member)
        {
            if (member == null)
                return false;
            switch (member.MemberType)
            {
                case MemberTypes.TypeInfo:
                    return ((TypeInfo)member).IsEnum;
                case MemberTypes.Property:
                    return IsEnum((PropertyInfo)member);
            }
            return false;
        }

        /// <summary>
        /// 是否枚举类型
        /// </summary>
        private static bool IsEnum(PropertyInfo property)
        {
            if (property.PropertyType.GetTypeInfo().IsEnum)
                return true;
            var value = Nullable.GetUnderlyingType(property.PropertyType);
            if (value == null)
                return false;
            return value.GetTypeInfo().IsEnum;
        }

        #endregion

        #region IsDate(是否日期类型)

        /// <summary>
        /// 是否日期类型
        /// </summary>
        /// <param name="member">成员</param>
        public static bool IsDate(MemberInfo member)
        {
            if (member == null)
                return false;
            switch (member.MemberType)
            {
                case MemberTypes.TypeInfo:
                    return member.ToString() == "System.DateTime";
                case MemberTypes.Property:
                    return IsDate((PropertyInfo)member);
            }
            return false;
        }

        /// <summary>
        /// 是否日期类型
        /// </summary>
        private static bool IsDate(PropertyInfo property)
        {
            if (property.PropertyType == typeof(DateTime))
                return true;
            if (property.PropertyType == typeof(DateTime?))
                return true;
            return false;
        }

        #endregion

        #region IsInt(是否整型)

        /// <summary>
        /// 是否整型
        /// </summary>
        /// <param name="member">成员</param>
        public static bool IsInt(MemberInfo member)
        {
            if (member == null)
                return false;
            switch (member.MemberType)
            {
                case MemberTypes.TypeInfo:
                    return member.ToString() == "System.Int32" || member.ToString() == "System.Int16" || member.ToString() == "System.Int64";
                case MemberTypes.Property:
                    return IsInt((PropertyInfo)member);
            }
            return false;
        }

        /// <summary>
        /// 是否整型
        /// </summary>
        private static bool IsInt(PropertyInfo property)
        {
            if (property.PropertyType == typeof(int))
                return true;
            if (property.PropertyType == typeof(int?))
                return true;
            if (property.PropertyType == typeof(short))
                return true;
            if (property.PropertyType == typeof(short?))
                return true;
            if (property.PropertyType == typeof(long))
                return true;
            if (property.PropertyType == typeof(long?))
                return true;
            return false;
        }

        #endregion

        #region IsNumber(是否数值类型)

        /// <summary>
        /// 是否浮点型
        /// </summary>
        /// <param name="member">成员</param>
        public static bool IsNumber(MemberInfo member)
        {
            if (member == null)
                return false;
            if (IsInt(member))
                return true;
            switch (member.MemberType)
            {
                case MemberTypes.TypeInfo:
                    return member.ToString() == "System.Double" || member.ToString() == "System.Decimal" || member.ToString() == "System.Single";
                case MemberTypes.Property:
                    return IsNumber((PropertyInfo)member);
            }
            return false;
        }

        /// <summary>
        /// 是否数值类型
        /// </summary>
        private static bool IsNumber(PropertyInfo property)
        {
            if (property.PropertyType == typeof(double))
                return true;
            if (property.PropertyType == typeof(double?))
                return true;
            if (property.PropertyType == typeof(decimal))
                return true;
            if (property.PropertyType == typeof(decimal?))
                return true;
            if (property.PropertyType == typeof(float))
                return true;
            if (property.PropertyType == typeof(float?))
                return true;
            return false;
        }

        #endregion

        #region GetElementType(获取元素类型)

        /// <summary>
        /// 获取元素类型，如果是集合，返回集合的元素类型
        /// </summary>
        /// <param name="type">类型</param>
        public static Type GetElementType(Type type)
        {
            if (IsCollection(type) == false)
                return type;
            if (type.IsArray)
                return type.GetElementType();
            var genericArgumentsTypes = type.GetTypeInfo().GetGenericArguments();
            if (genericArgumentsTypes == null || genericArgumentsTypes.Length == 0)
                throw new ArgumentException(nameof(genericArgumentsTypes));
            return genericArgumentsTypes[0];
        }

        #endregion

        #region GetTopBaseType(获取顶级基类)

        /// <summary>
        /// 获取顶级基类
        /// </summary>
        /// <typeparam name="T">类型</typeparam>
        public static Type GetTopBaseType<T>()
        {
            return GetTopBaseType(typeof(T));
        }

        /// <summary>
        /// 获取顶级基类
        /// </summary>
        /// <param name="type">类型</param>
        public static Type GetTopBaseType(Type type)
        {
            if (type == null)
                return null;
            if (type.IsInterface)
                return type;
            if (type.BaseType == typeof(object))
                return type;
            return GetTopBaseType(type.BaseType);
        }

        #endregion

        #region GetPropertyValue(获取属性值)

        /// <summary>
        /// 获取属性值
        /// </summary>
        /// <param name="instance">实例</param>
        /// <param name="propertyName">属性名</param>
        public static object GetPropertyValue(object instance, string propertyName)
        {
            if (instance == null)
                return null;
            var property = instance.GetType().GetProperty(propertyName);
            return property == null ? null : property.GetValue(instance);
        }

        #endregion
    }

    /// <summary>
    /// 正则操作
    /// </summary>
    public static class Regex
    {
        /// <summary>
        /// 获取匹配值集合
        /// </summary>
        /// <param name="input">输入字符串</param>
        /// <param name="pattern">模式字符串</param>
        /// <param name="resultPatterns">结果模式字符串数组,范例：new[]{"$1","$2"}</param>
        /// <param name="options">选项</param>
        public static Dictionary<string, string> GetValues(string input, string pattern, string[] resultPatterns, RegexOptions options = RegexOptions.IgnoreCase)
        {
            var result = new Dictionary<string, string>();
            if (string.IsNullOrWhiteSpace(input))
                return result;
            var match = System.Text.RegularExpressions.Regex.Match(input, pattern, options);
            if (match.Success == false)
                return result;
            AddResults(result, match, resultPatterns);
            return result;
        }

        /// <summary>
        /// 添加匹配结果
        /// </summary>
        private static void AddResults(Dictionary<string, string> result, Match match, string[] resultPatterns)
        {
            if (resultPatterns == null)
            {
                result.Add(string.Empty, match.Value);
                return;
            }
            foreach (var resultPattern in resultPatterns)
                result.Add(resultPattern, match.Result(resultPattern));
        }

        /// <summary>
        /// 获取匹配值
        /// </summary>
        /// <param name="input">输入字符串</param>
        /// <param name="pattern">模式字符串</param>
        /// <param name="resultPattern">结果模式字符串,范例："$1"用来获取第一个()内的值</param>
        /// <param name="options">选项</param>
        public static string GetValue(string input, string pattern, string resultPattern = "", RegexOptions options = RegexOptions.IgnoreCase)
        {
            if (string.IsNullOrWhiteSpace(input))
                return string.Empty;
            var match = System.Text.RegularExpressions.Regex.Match(input, pattern, options);
            if (match.Success == false)
                return string.Empty;
            return string.IsNullOrWhiteSpace(resultPattern) ? match.Value : match.Result(resultPattern);
        }

        /// <summary>
        /// 分割成字符串数组
        /// </summary>
        /// <param name="input">输入字符串</param>
        /// <param name="pattern">模式字符串</param>
        /// <param name="options">选项</param>
        public static string[] Split(string input, string pattern, RegexOptions options = RegexOptions.IgnoreCase)
        {
            if (string.IsNullOrWhiteSpace(input))
                return new string[] { };
            return System.Text.RegularExpressions.Regex.Split(input, pattern, options);
        }

        /// <summary>
        /// 替换
        /// </summary>
        /// <param name="input">输入字符串</param>
        /// <param name="pattern">模式字符串</param>
        /// <param name="replacement">替换字符串</param>
        /// <param name="options">选项</param>
        public static string Replace(string input, string pattern, string replacement, RegexOptions options = RegexOptions.IgnoreCase)
        {
            if (string.IsNullOrWhiteSpace(input))
                return string.Empty;
            return System.Text.RegularExpressions.Regex.Replace(input, pattern, replacement, options);
        }

        /// <summary>
        /// 验证输入与模式是否匹配
        /// </summary>
        /// <param name="input">输入字符串</param>
        /// <param name="pattern">模式字符串</param>        
        public static bool IsMatch(string input, string pattern)
        {
            return System.Text.RegularExpressions.Regex.IsMatch(input, pattern);
        }

        /// <summary>
        /// 验证输入与模式是否匹配
        /// </summary>
        /// <param name="input">输入的字符串</param>
        /// <param name="pattern">模式字符串</param>
        /// <param name="options">选项</param>
        public static bool IsMatch(string input, string pattern, RegexOptions options)
        {
            return System.Text.RegularExpressions.Regex.IsMatch(input, pattern, options);
        }

        /// <summary>
        ///获取匹配结果
        /// </summary>
        /// <param name="input">输入字符串</param>
        /// <param name="pattern">模式字符串</param>
        public static Match Match(string input, string pattern)
        {
            return System.Text.RegularExpressions.Regex.Match(input, pattern);
        }

        /// <summary>
        ///获取匹配结果
        /// </summary>
        /// <param name="input">输入字符串</param>
        /// <param name="pattern">模式字符串</param>
        /// <param name="options">选项</param>
        public static Match Match(string input, string pattern, RegexOptions options)
        {
            return System.Text.RegularExpressions.Regex.Match(input, pattern, options);
        }

        /// <summary>
        ///获取匹配结果集合
        /// </summary>
        /// <param name="input">输入字符串</param>
        /// <param name="pattern">模式字符串</param>
        public static MatchCollection Matches(string input, string pattern)
        {
            return System.Text.RegularExpressions.Regex.Matches(input, pattern);
        }

        /// <summary>
        ///获取匹配结果集合
        /// </summary>
        /// <param name="input">输入字符串</param>
        /// <param name="pattern">模式字符串</param>
        /// <param name="options">选项</param>
        public static MatchCollection Matches(string input, string pattern, RegexOptions options)
        {
            return System.Text.RegularExpressions.Regex.Matches(input, pattern, options);
        }

        /// <summary>
        ///获取匹配结果集合
        /// </summary>
        /// <param name="input">输入字符串</param>
        /// <param name="pattern">模式字符串</param>
        /// <param name="options">选项</param>
        /// <param name="matchTimeout">匹配超时间隔</param>
        public static MatchCollection Matches(string input, string pattern, RegexOptions options, TimeSpan matchTimeout)
        {
            return System.Text.RegularExpressions.Regex.Matches(input, pattern, options, matchTimeout);
        }
    }

    /// <summary>
    /// 字符串操作
    /// </summary>
    public static class String
    {

        #region Join(将集合连接为带分隔符的字符串)

        /// <summary>
        /// 将集合连接为带分隔符的字符串
        /// </summary>
        /// <typeparam name="T">集合元素类型</typeparam>
        /// <param name="values">值</param>
        /// <param name="quotes">引号，默认不带引号，范例：单引号 "'"</param>
        /// <param name="separator">分隔符，默认使用逗号分隔</param>
        public static string Join<T>(IEnumerable<T> values, string quotes = "", string separator = ",")
        {
            if (values == null)
                return string.Empty;
            var result = new StringBuilder();
            foreach (var each in values)
                result.AppendFormat("{0}{1}{0}{2}", quotes, each, separator);
            return result.ToString().RemoveEnd(separator);
        }

        #endregion

        #region FirstLowerCase(首字母小写)

        /// <summary>
        /// 首字母小写
        /// </summary>
        /// <param name="value">值</param>
        public static string FirstLowerCase(string value)
        {
            if (string.IsNullOrWhiteSpace(value))
                return string.Empty;
            var result = Rune.DecodeFromUtf16(value, out var rune, out var charsConsumed);
            if (result != OperationStatus.Done || Rune.IsLower(rune))
                return value;
            return Rune.ToLowerInvariant(rune) + value[charsConsumed..];
        }

        #endregion

        #region FirstUpperCase(首字母大写)

        /// <summary>
        /// 首字母大写
        /// </summary>
        /// <param name="value">值</param>
        public static string FirstUpperCase(string value)
        {
            if (string.IsNullOrWhiteSpace(value))
                return string.Empty;
            var result = Rune.DecodeFromUtf16(value, out var rune, out var charsConsumed);
            if (result != OperationStatus.Done || Rune.IsUpper(rune))
                return value;
            return Rune.ToUpperInvariant(rune) + value[charsConsumed..];
        }

        #endregion

        #region RemoveStart(移除起始字符串)

        /// <summary>
        /// 移除起始字符串
        /// </summary>
        /// <param name="value">值</param>
        /// <param name="start">要移除的值</param>
        /// <param name="ignoreCase">是否忽略大小写,默认值: true</param>
        public static string RemoveStart(string value, string start, bool ignoreCase = true)
        {
            if (string.IsNullOrWhiteSpace(value))
                return string.Empty;
            if (string.IsNullOrEmpty(start))
                return value;
            var options = ignoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
            if (value.StartsWith(start, options) == false)
                return value;
            return value.Substring(start.Length, value.Length - start.Length);
        }

        /// <summary>
        /// 移除起始字符串
        /// </summary>
        /// <param name="value">值</param>
        /// <param name="start">要移除的值</param>
        public static StringBuilder RemoveStart(StringBuilder value, string start)
        {
            if (value == null || value.Length == 0)
                return null;
            if (string.IsNullOrEmpty(start))
                return value;
            if (start.Length > value.Length)
                return value;
            var chars = start.ToCharArray();
            for (int i = 0; i < chars.Length; i++)
            {
                if (value[i] != chars[i])
                    return value;
            }
            return value.Remove(0, start.Length);
        }

        #endregion

        #region RemoveEnd(移除末尾字符串)

        /// <summary>
        /// 移除末尾字符串
        /// </summary>
        /// <param name="value">值</param>
        /// <param name="end">要移除的值</param>
        /// <param name="ignoreCase">是否忽略大小写,默认值: true</param>
        public static string RemoveEnd(string value, string end, bool ignoreCase = true)
        {
            if (string.IsNullOrWhiteSpace(value))
                return string.Empty;
            if (string.IsNullOrEmpty(end))
                return value;
            var options = ignoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
            if (value.EndsWith(end, options) == false)
                return value;
            return value.Substring(0, value.LastIndexOf(end, options));
        }

        /// <summary>
        /// 移除末尾字符串
        /// </summary>
        /// <param name="value">值</param>
        /// <param name="end">要移除的值</param>
        public static StringBuilder RemoveEnd(StringBuilder value, string end)
        {
            if (value == null || value.Length == 0)
                return null;
            if (string.IsNullOrEmpty(end))
                return value;
            if (end.Length > value.Length)
                return value;
            var chars = end.ToCharArray();
            for (int i = chars.Length - 1; i >= 0; i--)
            {
                var j = value.Length - (chars.Length - i);
                if (value[j] != chars[i])
                    return value;
            }
            return value.Remove(value.Length - end.Length, end.Length);
        }

        #endregion

        #region PinYin(获取汉字的拼音简码)

        /// <summary>
        /// 获取汉字的拼音简码，即首字母缩写,范例：中国,返回zg
        /// </summary>
        /// <param name="chineseText">汉字文本,范例： 中国</param>
        public static string PinYin(string chineseText)
        {
            if (chineseText.IsEmpty())
                return string.Empty;
            var result = new StringBuilder();
            foreach (char text in chineseText)
                result.Append(ResolvePinYin(text));
            return result.ToString().ToLower();
        }

        /// <summary>
        /// 解析单个汉字的拼音简码
        /// </summary>
        private static string ResolvePinYin(char text)
        {
            byte[] charBytes = Encoding.UTF8.GetBytes(text.ToString());
            if (charBytes[0] <= 127)
                return text.ToString();
            var unicode = (ushort)(charBytes[0] * 256 + charBytes[1]);
            string pinYin = ResolveByCode(unicode);
            if (pinYin.IsEmpty() == false)
                return pinYin;
            return ResolveByConst(text.ToString());
        }

        /// <summary>
        /// 使用字符编码方式获取拼音简码
        /// </summary>
        private static string ResolveByCode(ushort unicode)
        {
            if (unicode >= '\uB0A1' && unicode <= '\uB0C4')
                return "A";
            if (unicode >= '\uB0C5' && unicode <= '\uB2C0' && unicode != 45464)
                return "B";
            if (unicode >= '\uB2C1' && unicode <= '\uB4ED')
                return "C";
            if (unicode >= '\uB4EE' && unicode <= '\uB6E9')
                return "D";
            if (unicode >= '\uB6EA' && unicode <= '\uB7A1')
                return "E";
            if (unicode >= '\uB7A2' && unicode <= '\uB8C0')
                return "F";
            if (unicode >= '\uB8C1' && unicode <= '\uB9FD')
                return "G";
            if (unicode >= '\uB9FE' && unicode <= '\uBBF6')
                return "H";
            if (unicode >= '\uBBF7' && unicode <= '\uBFA5')
                return "J";
            if (unicode >= '\uBFA6' && unicode <= '\uC0AB')
                return "K";
            if (unicode >= '\uC0AC' && unicode <= '\uC2E7')
                return "L";
            if (unicode >= '\uC2E8' && unicode <= '\uC4C2')
                return "M";
            if (unicode >= '\uC4C3' && unicode <= '\uC5B5')
                return "N";
            if (unicode >= '\uC5B6' && unicode <= '\uC5BD')
                return "O";
            if (unicode >= '\uC5BE' && unicode <= '\uC6D9')
                return "P";
            if (unicode >= '\uC6DA' && unicode <= '\uC8BA')
                return "Q";
            if (unicode >= '\uC8BB' && unicode <= '\uC8F5')
                return "R";
            if (unicode >= '\uC8F6' && unicode <= '\uCBF9')
                return "S";
            if (unicode >= '\uCBFA' && unicode <= '\uCDD9')
                return "T";
            if (unicode >= '\uCDDA' && unicode <= '\uCEF3')
                return "W";
            if (unicode >= '\uCEF4' && unicode <= '\uD188')
                return "X";
            if (unicode >= '\uD1B9' && unicode <= '\uD4D0')
                return "Y";
            if (unicode >= '\uD4D1' && unicode <= '\uD7F9')
                return "Z";
            return string.Empty;
        }

        /// <summary>
        /// 通过拼音简码常量获取
        /// </summary>
        private static string ResolveByConst(string text)
        {
            int index = Const.ChinesePinYin.IndexOf(text, StringComparison.Ordinal);
            if (index < 0)
                return string.Empty;
            return Const.ChinesePinYin.Substring(index + 1, 1);
        }

        #endregion

        #region Extract(提取字符串中的变量值)

        /// <summary>
        /// 提取字符串中的变量值
        /// </summary>
        /// <param name="value">原始值,范例: Hello,World</param>
        /// <param name="format">字符串格式,范例: 原始值为Hello,World,格式为Hello,{value} ,则value变量的值为World</param>
        public static IDictionary<string, string> Extract(string value, string format)
        {
            var result = new Dictionary<string, string>();
            if (value.IsEmpty())
                return result;
            if (format.IsEmpty())
                return result;
            if (format.Contains("{", StringComparison.Ordinal) == false)
                return result;
            if (format.Contains("}", StringComparison.Ordinal) == false)
                return result;
            var formatItems = SplitFormat(format.SafeString());
            return ExtractValue(value.SafeString(), formatItems);
        }

        /// <summary>
        /// 拆分格式字符串
        /// </summary>
        private static List<string> SplitFormat(string format)
        {
            var result = new List<string>();
            var item = new StringBuilder();
            for (int i = 0; i < format.Length; i++)
            {
                var temp = format[i];
                if (temp == '{')
                {
                    item.RemoveEnd("{");
                    if (i == 0)
                    {
                        result.Add(string.Empty);
                    }
                    if (item.Length > 0)
                    {
                        result.Add(item.ToString());
                        item.Clear();
                    }
                    item.Append(temp);
                    continue;
                }
                if (temp == '}')
                {
                    if (item.ToString().IsEmpty())
                        continue;
                    item.RemoveEnd("}");
                    item.Append(temp);
                    result.Add(item.ToString());
                    item.Clear();
                    if (i == format.Length - 1)
                        result.Add(string.Empty);
                    continue;
                }
                item.Append(temp);
                if (i == format.Length - 1)
                {
                    result.Add(item.ToString());
                    item.Clear();
                }
            }
            return result;
        }

        /// <summary>
        /// 提取字符串中变量值
        /// </summary>
        private static IDictionary<string, string> ExtractValue(string value, List<string> formatItems)
        {
            var result = new Dictionary<string, string>();
            var leftIndex = 0;
            var length = 0;
            for (int i = 0; i < formatItems.Count; i++)
            {
                var item = formatItems[i];
                if (item == string.Empty)
                    continue;
                if (item.StartsWith("{", StringComparison.Ordinal) == false)
                {
                    leftIndex += item.Length;
                    continue;
                }
                if (i + 1 < formatItems.Count)
                {
                    var rightItem = formatItems[i + 1];
                    if (rightItem == string.Empty)
                        length = value.Length - leftIndex;
                    else
                        length = value.IndexOf(rightItem, leftIndex + 1, StringComparison.OrdinalIgnoreCase) - leftIndex;
                }
                var varName = item.Replace("{", "").Replace("}", "");
                if (length <= 0)
                {
                    result.Add(varName, string.Empty);
                    continue;
                }
                var variableValue = value.Substring(leftIndex, length);
                result.Add(varName, variableValue);
                leftIndex += length;
            }
            return result;
        }

        #endregion
    }

    /// <summary>
    /// 线程操作
    /// </summary>
    public static class Thread
    {
        /// <summary>
        /// 执行多个操作，等待所有操作完成
        /// </summary>
        /// <param name="actions">操作集合</param>
        public static void WaitAll(params Action[] actions)
        {
            if (actions == null)
                return;
            var tasks = new List<Task>();
            foreach (var action in actions)
                tasks.Add(Task.Factory.StartNew(action, TaskCreationOptions.None));
            Task.WaitAll(tasks.ToArray());
        }

        /// <summary>
        /// 并发执行多个操作
        /// </summary>
        /// <param name="actions">操作集合</param>
        public static void ParallelInvoke(params Action[] actions)
        {
            Parallel.Invoke(actions);
        }

        /// <summary>
        /// 循环并发执行操作
        /// </summary>
        /// <param name="action">操作</param>
        /// <param name="count">执行次数</param>
        /// <param name="options">并发执行配置</param>
        public static void ParallelFor(Action action, int count = 1, ParallelOptions options = null)
        {
            if (options == null)
            {
                Parallel.For(0, count, i => action());
                return;
            }
            Parallel.For(0, count, options, i => action());
        }

        /// <summary>
        /// 循环并发执行操作
        /// </summary>
        /// <param name="action">操作</param>
        /// <param name="count">执行次数</param>
        /// <param name="options">并发执行配置</param>
        public static async Task ParallelForAsync(Func<ValueTask> action, int count = 1, ParallelOptions options = null)
        {
            if (options == null)
            {
                await Parallel.ForEachAsync(Enumerable.Range(1, count), async (i, token) => await action());
                return;
            }
            await Parallel.ForEachAsync(Enumerable.Range(1, count), options, async (i, token) => await action());
        }

        /// <summary>
        /// 循环并发执行操作
        /// </summary>
        /// <param name="action">操作</param>
        /// <param name="count">执行次数</param>
        /// <param name="options">并发执行配置</param>
        public static async Task ParallelForAsync(Func<int, ValueTask> action, int count = 1, ParallelOptions options = null)
        {
            if (options == null)
            {
                await Parallel.ForEachAsync(Enumerable.Range(1, count), async (i, token) => await action(i));
                return;
            }
            await Parallel.ForEachAsync(Enumerable.Range(1, count), options, async (i, token) => await action(i));
        }
    }

    /// <summary>
    /// 时间操作
    /// </summary>
    public static class Time
    {
        /// <summary>
        /// 日期
        /// </summary>
        private static readonly AsyncLocal<DateTime?> _dateTime = new();
        /// <summary>
        /// 是否使用Utc日期
        /// </summary>
        private static readonly AsyncLocal<bool?> _isUseUtc = new();
        /// <summary>
        /// 是否使用Utc日期
        /// </summary>
        private static bool IsUseUtc => _isUseUtc.Value != null ? _isUseUtc.Value.SafeValue() : TimeOptions.IsUseUtc;

        /// <summary>
        /// 设置时间
        /// </summary>
        /// <param name="dateTime">时间</param>
        public static void SetTime(DateTime? dateTime)
        {
            _dateTime.Value = dateTime;
        }

        /// <summary>
        /// 设置时间
        /// </summary>
        /// <param name="dateTime">时间</param>
        public static void SetTime(string dateTime)
        {
            SetTime(Convert.ToDateTimeOrNull(dateTime));
        }

        /// <summary>
        /// 设置使用Utc日期
        /// </summary>
        /// <param name="isUseUtc">是否使用Utc日期,默认值: true</param>
        public static void UseUtc(bool? isUseUtc = true)
        {
            _isUseUtc.Value = isUseUtc;
        }

        /// <summary>
        /// 重置时间和Utc标志
        /// </summary>
        public static void Reset()
        {
            _dateTime.Value = null;
            _isUseUtc.Value = null;
        }

        /// <summary>
        /// 获取当前日期时间
        /// </summary>
        public static DateTime Now
        {
            get
            {
                if (_dateTime.Value != null)
                    return _dateTime.Value.Value;
                return IsUseUtc ? DateTime.UtcNow : DateTime.Now;
            }
        }


        /// <summary>
        /// 转换为标准化日期
        /// </summary>
        /// <param name="date">日期</param>
        public static DateTime? Normalize(DateTime? date)
        {
            if (date == null)
                return null;
            return Normalize(date.Value);
        }

        /// <summary>
        /// 转换为标准化日期
        /// </summary>
        /// <param name="date">日期</param>
        public static DateTime Normalize(DateTime date)
        {
            if (IsUseUtc)
                return ToUniversalTime(date);
            return ToLocalTime(date);
        }

        /// <summary>
        /// 转换为UTC日期
        /// </summary>
        /// <param name="date">日期</param>
        public static DateTime ToUniversalTime(DateTime date)
        {
            if (date == DateTime.MinValue)
                return DateTime.MinValue;
            switch (date.Kind)
            {
                case DateTimeKind.Local:
                    return date.ToUniversalTime();
                case DateTimeKind.Unspecified:
                    return DateTime.SpecifyKind(date, DateTimeKind.Local).ToUniversalTime();
                default:
                    return date;
            }
        }

        /// <summary>
        /// 转换为本地化日期
        /// </summary>
        /// <param name="date">日期</param>
        public static DateTime ToLocalTime(DateTime date)
        {
            if (date == DateTime.MinValue)
                return DateTime.MinValue;
            switch (date.Kind)
            {
                case DateTimeKind.Utc:
                    return date.ToLocalTime();
                case DateTimeKind.Unspecified:
                    return DateTime.SpecifyKind(date, DateTimeKind.Local);
                default:
                    return date;
            }
        }

        /// <summary>
        /// Utc日期转换为本地化日期
        /// </summary>
        /// <param name="date">日期</param>
        public static DateTime UtcToLocalTime(DateTime date)
        {
            if (date == DateTime.MinValue)
                return DateTime.MinValue;
            if (date.Kind == DateTimeKind.Utc)
                return date.ToLocalTime();
            if (date.Kind == DateTimeKind.Local)
                return date;
            if (IsUseUtc)
                return DateTime.SpecifyKind(date, DateTimeKind.Utc).ToLocalTime();
            return date;
        }

        /// <summary>
        /// 获取Unix时间戳
        /// </summary>
        public static long GetUnixTimestamp()
        {
            return GetUnixTimestamp(DateTime.Now);
        }

        /// <summary>
        /// 获取Unix时间戳
        /// </summary>
        /// <param name="time">时间</param>
        public static long GetUnixTimestamp(DateTime time)
        {
            var start = TimeZoneInfo.ConvertTime(new DateTime(1970, 1, 1), TimeZoneInfo.Local);
            long ticks = (time - start.Add(new TimeSpan(8, 0, 0))).Ticks;
            return Util.Helpers.Convert.ToLong(ticks / TimeSpan.TicksPerSecond);
        }

        /// <summary>
        /// 从Unix时间戳获取时间
        /// </summary>
        /// <param name="timestamp">Unix时间戳</param>
        public static DateTime GetTimeFromUnixTimestamp(long timestamp)
        {
            var start = TimeZoneInfo.ConvertTime(new DateTime(1970, 1, 1), TimeZoneInfo.Local);
            TimeSpan span = new TimeSpan(long.Parse(timestamp + "0000000"));
            return start.Add(span).Add(new TimeSpan(8, 0, 0));
        }
    }

    /// <summary>
    /// Url操作
    /// </summary>
    public static class Url
    {
        /// <summary>
        /// 连接路径
        /// </summary>
        /// <param name="paths">路径列表</param>
        public static string JoinPath(params string[] paths)
        {
            if (paths == null)
                return string.Empty;
            paths = paths.Where(path => string.IsNullOrWhiteSpace(path) == false).Select(t => t.Replace(@"\", "/")).ToArray();
            if (paths.Length == 0)
                return string.Empty;
            var firstPath = paths.First();
            var lastPath = paths.Last();
            string schema = string.Empty;
            if (firstPath.StartsWith("http:", StringComparison.OrdinalIgnoreCase))
                schema = "http://";
            if (firstPath.StartsWith("https:", StringComparison.OrdinalIgnoreCase))
                schema = "https://";
            paths = paths.Select(t => t.Trim('/')).ToArray();
            var result = Path.Combine(paths).Replace(@"\", "/");
            if (paths.Any(path => path.StartsWith(".")))
            {
                result = Path.GetFullPath(Path.Combine(paths));
                result = result.RemoveStart(AppContext.BaseDirectory).Replace(@"\", "/");
            }
            if (firstPath.StartsWith('/'))
                result = $"/{result}";
            if (lastPath.EndsWith('/'))
                result = $"{result}/";
            result = result.RemoveStart("http:/").RemoveStart("https:/");
            if (schema.IsEmpty())
                return result;
            return schema + result.RemoveStart("/");
        }
    }

    /// <summary>
    /// Xml操作 - 生成器
    /// </summary>
    public partial class Xml
    {
        /// <summary>
        /// 初始化Xml操作
        /// </summary>
        /// <param name="xml">Xml字符串</param>
        public Xml(string xml = null)
        {
            Document = new XmlDocument();
            Document.LoadXml(GetXml(xml));
            Root = Document.DocumentElement;
            if (Root == null)
                throw new ArgumentException(nameof(xml));
        }

        /// <summary>
        /// 获取Xml字符串
        /// </summary>
        private string GetXml(string xml)
        {
            return string.IsNullOrWhiteSpace(xml) ? "<xml></xml>" : xml;
        }

        /// <summary>
        /// Xml文档
        /// </summary>
        public XmlDocument Document { get; }

        /// <summary>
        /// Xml根节点
        /// </summary>
        public XmlElement Root { get; }

        /// <summary>
        /// 添加节点
        /// </summary>
        /// <param name="name">节点名称</param>
        /// <param name="value">值</param>
        /// <param name="parent">父节点</param>
        public XmlNode AddNode(string name, object value = null, XmlNode parent = null)
        {
            var node = CreateNode(name, value, XmlNodeType.Element);
            GetParent(parent).AppendChild(node);
            return node;
        }

        /// <summary>
        /// 创建节点
        /// </summary>
        private XmlNode CreateNode(string name, object value, XmlNodeType type)
        {
            var node = Document.CreateNode(type, name, string.Empty);
            if (string.IsNullOrWhiteSpace(value.SafeString()) == false)
                node.InnerText = value.SafeString();
            return node;
        }

        /// <summary>
        /// 获取父节点
        /// </summary>
        private XmlNode GetParent(XmlNode parent)
        {
            if (parent == null)
                return Root;
            return parent;
        }

        /// <summary>
        /// 添加CDATA节点
        /// </summary>
        /// <param name="value">值</param>
        /// <param name="parent">父节点</param>
        public XmlNode AddCDataNode(object value, XmlNode parent = null)
        {
            var node = CreateNode(CreateId(), value, XmlNodeType.CDATA);
            GetParent(parent).AppendChild(node);
            return node;
        }

        /// <summary>
        /// 创建标识
        /// </summary>
        private string CreateId()
        {
            return System.Guid.NewGuid().ToString("N");
        }

        /// <summary>
        /// 添加CDATA节点
        /// </summary>
        /// <param name="value">值</param>
        /// <param name="parentName">父节点名称</param>
        public XmlNode AddCDataNode(object value, string parentName)
        {
            var parent = CreateNode(parentName, null, XmlNodeType.Element);
            Root.AppendChild(parent);
            return AddCDataNode(value, parent);
        }

        /// <summary>
        /// 输出Xml
        /// </summary>
        public override string ToString()
        {
            return Document.OuterXml;
        }
    }

    /// <summary>
    /// Xml操作 - 工具
    /// </summary>
    public partial class Xml
    {
        /// <summary>
        /// 将Xml字符串转换为XDocument
        /// </summary>
        /// <param name="xml">Xml字符串</param>
        public static XDocument ToDocument(string xml)
        {
            return XDocument.Parse(xml);
        }

        /// <summary>
        /// 将Xml字符串转换为XElement列表
        /// </summary>
        /// <param name="xml">Xml字符串</param>
        public static List<XElement> ToElements(string xml)
        {
            var document = ToDocument(xml);
            if (document?.Root == null)
                return new List<XElement>();
            return document.Root.Elements().ToList();
        }

        /// <summary>
        /// 加载Xml文件到XDocument
        /// </summary>
        /// <param name="filePath">Xml文件绝对路径</param>
        public static async Task<XDocument> LoadFileToDocumentAsync(string filePath)
        {
            return await LoadFileToDocumentAsync(filePath, Encoding.UTF8);
        }

        /// <summary>
        /// 加载Xml文件到XDocument
        /// </summary>
        /// <param name="filePath">Xml文件绝对路径</param>
        /// <param name="encoding">字符编码</param>
        public static async Task<XDocument> LoadFileToDocumentAsync(string filePath, Encoding encoding)
        {
            var xml = await Util.Helpers.File.ReadToStringAsync(filePath, encoding);
            return ToDocument(xml);
        }

