    #region SystemTextJson
    /// <summary>
    /// 日期格式Json转换器
    /// </summary>
    public class DateTimeJsonConverter : JsonConverter<DateTime>
    {
        /// <summary>
        /// 日期格式
        /// </summary>
        private readonly string _format;

        /// <summary>
        /// 初始化日期格式Json转换器
        /// </summary>
        public DateTimeJsonConverter() : this("yyyy-MM-dd HH:mm:ss")
        {
        }

        /// <summary>
        /// 初始化日期格式Json转换器
        /// </summary>
        /// <param name="format">日期格式,默认值: yyyy-MM-dd HH:mm:ss</param>
        public DateTimeJsonConverter(string format)
        {
            _format = format;
        }

        /// <summary>
        /// 读取数据
        /// </summary>
        public override DateTime Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            if (reader.TokenType == JsonTokenType.String)
                return Time.ToLocalTime(Util.Helpers.Convert.ToDateTime(reader.GetString()));
            if (reader.TryGetDateTime(out var date))
                return Time.ToLocalTime(date);
            return DateTime.MinValue;
        }

        /// <summary>
        /// 写入数据
        /// </summary>
        public override void Write(Utf8JsonWriter writer, DateTime value, JsonSerializerOptions options)
        {
            var date = Time.ToLocalTime(value).ToString(_format);
            writer.WriteStringValue(date);
        }
    }

    /// <summary>
    /// 枚举Json转换器
    /// </summary>
    public class EnumJsonConverter<T> : JsonConverter<T> where T : struct, Enum
    {
        /// <summary>
        /// 读取数据
        /// </summary>
        public override T Read(ref Utf8JsonReader reader, System.Type type, JsonSerializerOptions options)
        {
            var isSuccess = reader.TryGetSingle(out var floatValue);
            if (isSuccess)
                return (T)System.Enum.Parse(type, floatValue.ToString(CultureInfo.InvariantCulture), true);
            isSuccess = reader.TryGetInt32(out var intValue);
            if (isSuccess)
                return (T)System.Enum.Parse(type, intValue.ToString(CultureInfo.InvariantCulture), true);
            return default;
        }


        /// <summary>
        /// 写入数据
        /// </summary>
        public override void Write(Utf8JsonWriter writer, T value, JsonSerializerOptions options)
        {
            var code = Type.GetTypeCode(typeof(T));
            switch (code)
            {
                case TypeCode.Byte:
                    writer.WriteNumberValue(Unsafe.As<T, byte>(ref value));
                    break;
                case TypeCode.Int32:
                    writer.WriteNumberValue(Unsafe.As<T, int>(ref value));
                    break;
            }
        }
    }

    /// <summary>
    /// 枚举Json转换器工厂
    /// </summary>
    public class EnumJsonConverterFactory : JsonConverterFactory
    {
        /// <summary>
        /// 是否允许转换为枚举
        /// </summary>
        /// <param name="type">转换类型</param>
        public override bool CanConvert(Type type)
        {
            return type.IsEnum;
        }

        /// <summary>
        /// 创建枚举Json转换器
        /// </summary>
        /// <param name="type">转换类型</param>
        /// <param name="options">Json序列化配置</param>
        public override JsonConverter CreateConverter(Type type, JsonSerializerOptions options)
        {
            return (JsonConverter)Activator.CreateInstance(GetEnumConverterType(type));
        }

        /// <summary>
        /// 获取枚举Json转换器类型
        /// </summary>
        /// <param name="enumType">枚举类型</param>
        private static Type GetEnumConverterType(Type enumType) => typeof(EnumJsonConverter<>).MakeGenericType(enumType);
    }

    /// <summary>
    /// long格式Json转换器
    /// </summary>
    public class LongJsonConverter : JsonConverter<long>
    {
        /// <summary>
        /// 读取数据
        /// </summary>
        public override long Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            if (reader.TokenType == JsonTokenType.String)
                return Util.Helpers.Convert.ToLong(reader.GetString());
            return reader.TryGetInt64(out var value) ? value : 0;
        }

        /// <summary>
        /// 写入数据
        /// </summary>
        public override void Write(Utf8JsonWriter writer, long value, JsonSerializerOptions options)
        {
            writer.WriteStringValue(value.SafeString());
        }
    }

    /// <summary>
    /// 可空日期格式Json转换器
    /// </summary>
    public class NullableDateTimeJsonConverter : JsonConverter<DateTime?>
    {
        /// <summary>
        /// 日期格式
        /// </summary>
        private readonly string _format;

        /// <summary>
        /// 初始化可空日期格式Json转换器
        /// </summary>
        public NullableDateTimeJsonConverter() : this("yyyy-MM-dd HH:mm:ss")
        {
        }

        /// <summary>
        /// 初始化可空日期格式Json转换器
        /// </summary>
        /// <param name="format">日期格式,默认值: yyyy-MM-dd HH:mm:ss</param>
        public NullableDateTimeJsonConverter(string format)
        {
            _format = format;
        }

        /// <summary>
        /// 读取数据
        /// </summary>
        public override DateTime? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            if (reader.TokenType == JsonTokenType.String)
            {
                return Time.ToLocalTime(Util.Helpers.Convert.ToDateTime(reader.GetString()));
            }
            if (reader.TryGetDateTime(out var date))
            {
                return Time.ToLocalTime(date);
            }
            return DateTime.MinValue;
        }

        /// <summary>
        /// 写入数据
        /// </summary>
        public override void Write(Utf8JsonWriter writer, DateTime? value, JsonSerializerOptions options)
        {
            if (value == null)
            {
                writer.WriteNullValue();
                return;
            }
            var date = Time.ToLocalTime(value.Value).ToString(_format);
            writer.WriteStringValue(date);
        }
    }

    /// <summary>
    /// 可空long格式Json转换器
    /// </summary>
    public class NullableLongJsonConverter : JsonConverter<long?>
    {
        /// <summary>
        /// 读取数据
        /// </summary>
        public override long? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            if (reader.TokenType == JsonTokenType.String)
                return Util.Helpers.Convert.ToLongOrNull(reader.GetString());
            return reader.TryGetInt64(out var value) ? value : null;
        }

        /// <summary>
        /// 写入数据
        /// </summary>
        public override void Write(Utf8JsonWriter writer, long? value, JsonSerializerOptions options)
        {
            writer.WriteStringValue(value.SafeString());
        }
    }

    /// <summary>
    /// Utc日期格式Json转换器
    /// </summary>
    public class UtcDateTimeJsonConverter : JsonConverter<DateTime>
    {
        /// <summary>
        /// 日期格式
        /// </summary>
        private readonly string _format;

        /// <summary>
        /// 初始化Utc日期格式Json转换器
        /// </summary>
        public UtcDateTimeJsonConverter() : this("yyyy-MM-ddTHH:mm:sszzzz")
        {
        }

        /// <summary>
        /// 初始化Utc日期格式Json转换器
        /// </summary>
        /// <param name="format">日期格式,默认值: yyyy-MM-ddTHH:mm:sszzzz</param>
        public UtcDateTimeJsonConverter(string format)
        {
            _format = format;
        }

        /// <summary>
        /// 读取数据
        /// </summary>
        public override DateTime Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            if (reader.TokenType == JsonTokenType.String)
            {
                return Time.UtcToLocalTime(Util.Helpers.Convert.ToDateTime(reader.GetString()));
            }
            if (reader.TryGetDateTime(out var date))
            {
                return Time.UtcToLocalTime(date);
            }
            return DateTime.MinValue;
        }

        /// <summary>
        /// 写入数据
        /// </summary>
        public override void Write(Utf8JsonWriter writer, DateTime value, JsonSerializerOptions options)
        {
            var date = Time.Normalize(value).ToString(_format);
            writer.WriteStringValue(date);
        }
    }

