    }

    /// <summary>
    /// 对象映射扩展
    /// </summary>
    public static class ObjectMapperExtensions
    {
        /// <summary>
        /// 对象映射器
        /// </summary>
        private static IObjectMapper _mapper;

        /// <summary>
        /// 设置对象映射器
        /// </summary>
        /// <param name="mapper">对象映射器</param>
        public static void SetMapper(IObjectMapper mapper)
        {
            _mapper = mapper ?? throw new ArgumentNullException(nameof(mapper));
        }

        /// <summary>
        /// 将源对象映射到目标对象
        /// </summary>
        /// <typeparam name="TDestination">目标类型</typeparam>
        /// <param name="source">源对象</param>
        public static TDestination MapTo<TDestination>(this object source)
        {
            if (_mapper == null)
                throw new ArgumentNullException(nameof(_mapper));
            return _mapper.Map<object, TDestination>(source);
        }

        /// <summary>
        /// 将源对象映射到目标对象
        /// </summary>
        /// <typeparam name="TSource">源类型</typeparam>
        /// <typeparam name="TDestination">目标类型</typeparam>
        /// <param name="source">源对象</param>
        /// <param name="destination">目标对象</param>
        public static TDestination MapTo<TSource, TDestination>(this TSource source, TDestination destination)
        {
            if (_mapper == null)
                throw new ArgumentNullException(nameof(_mapper));
            return _mapper.Map(source, destination);
        }

        /// <summary>
        /// 将源集合映射到目标集合
        /// </summary>
        /// <typeparam name="TDestination">目标元素类型,范例：Sample,不要加List</typeparam>
        /// <param name="source">源集合</param>
        public static List<TDestination> MapToList<TDestination>(this System.Collections.IEnumerable source)
        {
            return MapTo<List<TDestination>>(source);
        }
    }

    /// <summary>
    /// 反射扩展
    /// </summary>
    public static class ReflectionExtensions
    {
        /// <summary>
        /// 获取实例上的属性值
        /// </summary>
        /// <param name="member">成员信息</param>
        /// <param name="instance">成员所在的类实例</param>
        public static object GetPropertyValue(this MemberInfo member, object instance)
        {
            if (member == null)
                throw new ArgumentNullException(nameof(member));
            if (instance == null)
                throw new ArgumentNullException(nameof(instance));
            return instance.GetType().GetProperty(member.Name)?.GetValue(instance);
        }
    }

    /// <summary>
    /// 服务扩展
    /// </summary>
    public static class ServiceCollectionExtensions
    {
        /// <summary>
        /// 获取配置实例
        /// </summary>
        /// <param name="services">服务集合</param>
        public static IConfiguration GetConfiguration(this IServiceCollection services)
        {
            return services.GetSingletonInstance<IConfiguration>();
        }

        /// <summary>
        /// 获取单例实例
        /// </summary>
        /// <param name="services">服务集合</param>
        public static T GetSingletonInstance<T>(this IServiceCollection services)
        {
            var descriptor = services.FirstOrDefault(t => t.ServiceType == typeof(T) && t.Lifetime == ServiceLifetime.Singleton);
            if (descriptor == null)
                return default;
            if (descriptor.ImplementationInstance != null)
                return (T)descriptor.ImplementationInstance;
            if (descriptor.ImplementationFactory != null)
                return (T)descriptor.ImplementationFactory.Invoke(null);
            return default;
        }
    }

    /// <summary>
    /// 字符串扩展
    /// </summary>
    public static class StringExtensions
    {
        /// <summary>
        /// 移除起始字符串
        /// </summary>
        /// <param name="value">值</param>
        /// <param name="start">要移除的值</param>
        /// <param name="ignoreCase">是否忽略大小写,默认值: true</param>
        public static string RemoveStart(this string value, string start, bool ignoreCase = true)
        {
            return String.RemoveStart(value, start, ignoreCase);
        }

        /// <summary>
        /// 移除末尾字符串
        /// </summary>
        /// <param name="value">值</param>
        /// <param name="end">要移除的值</param>
        /// <param name="ignoreCase">是否忽略大小写,默认值: true</param>
        public static string RemoveEnd(this string value, string end, bool ignoreCase = true)
        {
            return String.RemoveEnd(value, end, ignoreCase);
        }

        /// <summary>
        /// 移除起始字符串
        /// </summary>
        /// <param name="value">值</param>
        /// <param name="start">要移除的值</param>
        public static StringBuilder RemoveStart(this StringBuilder value, string start)
        {
            return String.RemoveStart(value, start);
        }

        /// <summary>
        /// 移除末尾字符串
        /// </summary>
        /// <param name="value">值</param>
        /// <param name="end">要移除的值</param>
        public static StringBuilder RemoveEnd(this StringBuilder value, string end)
        {
            return String.RemoveEnd(value, end);
        }

        /// <summary>
        /// 移除起始字符串
        /// </summary>
        /// <param name="writer">字符串写入器</param>
        /// <param name="start">要移除的值</param>
        public static StringWriter RemoveStart(this StringWriter writer, string start)
        {
            if (writer == null)
                return null;
            var builder = writer.GetStringBuilder();
            builder.RemoveStart(start);
            return writer;
        }

        /// <summary>
        /// 移除末尾字符串
        /// </summary>
        /// <param name="writer">字符串写入器</param>
        /// <param name="end">要移除的值</param>
        public static StringWriter RemoveEnd(this StringWriter writer, string end)
        {
            if (writer == null)
                return null;
            var builder = writer.GetStringBuilder();
            builder.RemoveEnd(end);
            return writer;
        }
    }

    /// <summary>
    /// 验证扩展
    /// </summary>
    public static class ValidationExtensions
    {
        /// <summary>
        /// 检测对象是否为null,为null则抛出<see cref="ArgumentNullException"/>异常
        /// </summary>
        /// <param name="obj">对象</param>
        /// <param name="parameterName">参数名</param>
        public static void CheckNull(this object obj, string parameterName)
        {
            if (obj == null)
                throw new ArgumentNullException(parameterName);
        }

        /// <summary>
        /// 是否为空
        /// </summary>
        /// <param name="value">值</param>
        public static bool IsEmpty([NotNullWhen(false)] this string? value)
        {
            return string.IsNullOrWhiteSpace(value);
        }

        /// <summary>
        /// 是否为空
        /// </summary>
        /// <param name="value">值</param>
        public static bool IsEmpty(this Guid value)
        {
            return value == Guid.Empty;
        }

        /// <summary>
        /// 是否为空
        /// </summary>
        /// <param name="value">值</param>
        public static bool IsEmpty([NotNullWhen(false)] this Guid? value)
        {
            if (value == null)
                return true;
            return value == Guid.Empty;
        }

        /// <summary>
        /// 是否为空
        /// </summary>
        /// <param name="value">值</param>
        public static bool IsEmpty<T>(this IEnumerable<T>? value)
        {
            if (value == null)
                return true;
            return !value.Any();
        }

        /// <summary>
        /// 是否默认值
        /// </summary>
        /// <typeparam name="T">值类型</typeparam>
        /// <param name="value">值</param>
        public static bool IsDefault<T>(this T value)
        {
            return EqualityComparer<T>.Default.Equals(value, default);
        }
    }
    #endregion
}

namespace AutoMapper
{
    global using AutoMapper;
    global using AutoMapper.Internal;
    global using Microsoft.Extensions.DependencyInjection;
    global using System;
    global using System.Linq;
    global using System.Linq.Expressions;

    #region Infrastructure
    /// <summary>
    /// AutoMapper服务注册器
    /// </summary>
    public class AutoMapperServiceRegistrar : IServiceRegistrar
    {
        /// <summary>
        /// 获取服务名
        /// </summary>
        public static string ServiceName => "AutoMapperServiceRegistrar";

        /// <summary>
        /// 排序号
        /// </summary>
        public int OrderId => 300;

        /// <summary>
        /// 是否启用
        /// </summary>
        public bool Enabled => ServiceRegistrarConfig.IsEnabled(ServiceName);

        /// <summary>
        /// 注册服务
        /// </summary>
        /// <param name="serviceContext">服务上下文</param>
        public Action Register(ServiceContext serviceContext)
        {
            var types = serviceContext.TypeFinder.Find<IAutoMapperConfig>();
            var instances = types.Select(type => Reflection.CreateInstance<IAutoMapperConfig>(type)).ToList();
            var expression = new MapperConfigurationExpression();
            instances.ForEach(t => t.Config(expression));
            var mapper = new ObjectMapper(expression);
            ObjectMapperExtensions.SetMapper(mapper);
            serviceContext.HostBuilder.ConfigureServices((context, services) =>
            {
                services.AddSingleton<IObjectMapper>(mapper);
            });
            return null;
        }
    }

    /// <summary>
    /// AutoMapper服务注册器配置扩展
    /// </summary>
    public static class ServiceRegistrarConfigExtensions
    {
        /// <summary>
        /// 启用AutoMapper服务注册器
        /// </summary>
        /// <param name="config">服务注册器配置</param>
        public static ServiceRegistrarConfig EnableAutoMapperServiceRegistrar(this ServiceRegistrarConfig config)
        {
            ServiceRegistrarConfig.Enable(AutoMapperServiceRegistrar.ServiceName);
            return config;
        }

        /// <summary>
        ///禁用AutoMapper服务注册器
        /// </summary>
        /// <param name="config">服务注册器配置</param>
        public static ServiceRegistrarConfig DisableAutoMapperServiceRegistrar(this ServiceRegistrarConfig config)
        {
            ServiceRegistrarConfig.Disable(AutoMapperServiceRegistrar.ServiceName);
            return config;
        }
    }
    #endregion

    /// <summary>
    /// AutoMapper配置表达式扩展
    /// </summary>
    public static class AutoMapperExpressionExtensions
    {
        /// <summary>
        /// 忽略属性
        /// </summary>
        public static IMappingExpression<TDestination, TMember> Ignore<TDestination, TMember, TResult>(this IMappingExpression<TDestination, TMember> mappingExpression, Expression<Func<TMember, TResult>> destinationMember)
        {
            return mappingExpression.ForMember(destinationMember, options => options.Ignore());
        }
    }

    /// <summary>
    /// AutoMapper配置
    /// </summary>
    public interface IAutoMapperConfig
    {
        /// <summary>
        /// 配置映射
        /// </summary>
        /// <param name="expression">配置映射表达式</param>
        void Config(IMapperConfigurationExpression expression);
    }

    /// <summary>
    /// AutoMapper对象映射器
    /// </summary>
    public class ObjectMapper : IObjectMapper
    {
        /// <summary>
        /// 最大递归获取结果次数
        /// </summary>
        private const int MaxGetResultCount = 16;
        /// <summary>
        /// 同步锁
        /// </summary>
        private static readonly object Sync = new();
        /// <summary>
        /// 配置表达式
        /// </summary>
        private readonly MapperConfigurationExpression _configExpression;
        /// <summary>
        /// 配置提供器
        /// </summary>
        private IConfigurationProvider _config;
        /// <summary>
        /// 对象映射器
        /// </summary>
        private IMapper _mapper;

        /// <summary>
        /// 初始化AutoMapper对象映射器
        /// </summary>
        /// <param name="expression">配置表达式</param>
        public ObjectMapper(MapperConfigurationExpression expression)
        {
            _configExpression = expression ?? throw new ArgumentNullException(nameof(expression));
            _config = new MapperConfiguration(expression);
            _mapper = _config.CreateMapper();
        }

        /// <summary>
        /// 将源对象映射到目标对象
        /// </summary>
        /// <typeparam name="TSource">源类型</typeparam>
        /// <typeparam name="TDestination">目标类型</typeparam>
        /// <param name="source">源对象</param>
        public TDestination Map<TSource, TDestination>(TSource source)
        {
            return Map<TSource, TDestination>(source, default);
        }

        /// <summary>
        /// 将源对象映射到目标对象
        /// </summary>
        /// <typeparam name="TSource">源类型</typeparam>
        /// <typeparam name="TDestination">目标类型</typeparam>
        /// <param name="source">源对象</param>
        /// <param name="destination">目标对象</param>
        public TDestination Map<TSource, TDestination>(TSource source, TDestination destination)
        {
            if (source == null)
                return default;
            var sourceType = GetType(source);
            var destinationType = GetType(destination);
            return GetResult(sourceType, destinationType, source, destination, 0);
        }

        /// <summary>
        /// 获取类型
        /// </summary>
        private Type GetType<T>(T obj)
        {
            if (obj == null)
                return GetType(typeof(T));
            return GetType(obj.GetType());
        }

        /// <summary>
        /// 获取类型
        /// </summary>
        private Type GetType(Type type)
        {
            return Reflection.GetElementType(type);
        }

        /// <summary>
        /// 获取结果
        /// </summary>
        private TDestination GetResult<TDestination>(Type sourceType, Type destinationType, object source, TDestination destination, int i)
        {
            try
            {
                if (i >= MaxGetResultCount)
                    return default;
                i += 1;
                if (Exists(sourceType, destinationType))
                    return GetResult(source, destination);
                lock (Sync)
                {
                    if (Exists(sourceType, destinationType))
                        return GetResult(source, destination);
                    ConfigMap(sourceType, destinationType);
                }
                return GetResult(source, destination);
            }
            catch (AutoMapperMappingException ex)
            {
                if (ex.InnerException != null && ex.InnerException.Message.StartsWith("Missing type map configuration"))
                    return GetResult(GetType(ex.MemberMap.SourceType), GetType(ex.MemberMap.DestinationType), source, destination, i);
                throw;
            }
        }

        /// <summary>
        /// 是否已存在映射配置
        /// </summary>
        private bool Exists(Type sourceType, Type destinationType)
        {
            return _config.Internal().FindTypeMapFor(sourceType, destinationType) != null;
        }

        /// <summary>
        /// 获取映射结果
        /// </summary>
        private TDestination GetResult<TSource, TDestination>(TSource source, TDestination destination)
        {
            return _mapper.Map(source, destination);
        }

        /// <summary>
        /// 动态配置映射
        /// </summary>
        private void ConfigMap(Type sourceType, Type destinationType)
        {
            _configExpression.CreateMap(sourceType, destinationType);
            _config = new MapperConfiguration(_configExpression);
            _mapper = _config.CreateMapper();
        }
    }
}

namespace AspectCore
{
    global using AspectCore.Configuration;
    global using AspectCore.DynamicProxy;
    global using AspectCore.DynamicProxy.Parameters;
    global using AspectCore.Extensions.AspectScope;
    global using AspectCore.Extensions.DependencyInjection;
    global using Microsoft.Extensions.DependencyInjection;
    global using System;
    global using System.Threading.Tasks;

    /// <summary>
    /// Aop配置
    /// </summary>
    public class AopOptions
    {
        /// <summary>
        /// 是否启用IAopProxy接口标记
        /// </summary>
        public bool IsEnableIAopProxy { get; set; }
        /// <summary>
        /// 是否启用参数拦截器,默认值: true
        /// </summary>
        public bool IsEnableParameterAspect { get; set; } = true;
    }

    /// <summary>
    /// Aop配置扩展
    /// </summary>
    public static class AppBuilderExtensions
    {
        /// <summary>
        /// 启用AspectCore拦截器
        /// </summary>
        /// <param name="builder">应用生成器</param>
        public static IAppBuilder AddAop(this IAppBuilder builder)
        {
            return builder.AddAop(false);
        }

        /// <summary>
        /// 启用AspectCore拦截器
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="isEnableIAopProxy">是否启用IAopProxy接口标记</param>
        public static IAppBuilder AddAop(this IAppBuilder builder, bool isEnableIAopProxy)
        {
            return builder.AddAop(null, isEnableIAopProxy);
        }

        /// <summary>
        /// 启用AspectCore拦截器
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="setupAction">AspectCore拦截器配置操作</param>
        public static IAppBuilder AddAop(this IAppBuilder builder, Action<IAspectConfiguration> setupAction)
        {
            return builder.AddAop(setupAction, false);
        }

        /// <summary>
        /// 启用AspectCore拦截器
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="setupAction">AspectCore拦截器配置操作</param>
        /// <param name="isEnableIAopProxy">是否启用IAopProxy接口标记</param>
        private static IAppBuilder AddAop(this IAppBuilder builder, Action<IAspectConfiguration> setupAction, bool isEnableIAopProxy)
        {
            return builder.AddAop(setupAction, t => t.IsEnableIAopProxy = isEnableIAopProxy);
        }

        /// <summary>
        /// 启用AspectCore拦截器
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="setupAction">AspectCore拦截器配置操作</param>
        /// <param name="action">配置操作</param>
        private static IAppBuilder AddAop(this IAppBuilder builder, Action<IAspectConfiguration> setupAction, Action<AopOptions> action)
        {
            builder.CheckNull(nameof(builder));
            builder.Host.UseServiceProviderFactory(new DynamicProxyServiceProviderFactory());
            builder.Host.ConfigureServices((context, services) =>
            {
                var options = new AopOptions();
                action?.Invoke(options);
                ConfigureDynamicProxy(services, setupAction, options.IsEnableParameterAspect, options.IsEnableIAopProxy);
                RegisterAspectScoped(services);
            });
            return builder;
        }

        /// <summary>
        /// 配置拦截器
        /// </summary>
        private static void ConfigureDynamicProxy(IServiceCollection services, Action<IAspectConfiguration> setupAction, bool isEnableParameterAspect, bool isEnableIAopProxy)
        {
            services.ConfigureDynamicProxy(config =>
            {
                if (setupAction == null)
                {
                    config.NonAspectPredicates.Add(t => !IsProxy(t.DeclaringType, isEnableIAopProxy));
                    if (isEnableParameterAspect)
                        config.EnableParameterAspect();
                    return;
                }
                setupAction.Invoke(config);
            });
        }

        /// <summary>
        /// 是否创建代理
        /// </summary>
        private static bool IsProxy(Type type, bool isEnableIAopProxy)
        {
            if (type == null)
                return false;
            if (isEnableIAopProxy == false)
            {
                return type.SafeString().Contains("Xunit.DependencyInjection.ITestOutputHelperAccessor") == false;
            }
            var interfaces = type.GetInterfaces();
            if (interfaces == null || interfaces.Length == 0)
                return false;
            foreach (var item in interfaces)
            {
                if (item == typeof(IAopProxy))
                    return true;
            }
            return false;
        }

        /// <summary>
        /// 注册拦截器服务
        /// </summary>
        private static void RegisterAspectScoped(IServiceCollection services)
        {
            services.AddScoped<IAspectScheduler, ScopeAspectScheduler>();
            services.AddScoped<IAspectBuilderFactory, ScopeAspectBuilderFactory>();
            services.AddScoped<IAspectContextFactory, ScopeAspectContextFactory>();
        }
    }

    /// <summary>
    /// 异常扩展
    /// </summary>
    public static class ExceptionExtensions
    {
        /// <summary>
        /// 获取原始异常
        /// </summary>
        /// <param name="exception">异常</param>
        public static Exception GetRawException(this Exception exception)
        {
            if (exception == null)
                return null;
            if (exception is AspectCore.DynamicProxy.AspectInvocationException aspectInvocationException)
            {
                if (aspectInvocationException.InnerException == null)
                    return aspectInvocationException;
                return GetRawException(aspectInvocationException.InnerException);
            }
            return exception;
        }
    }

    /// <summary>
    /// Aop代理标记
    /// </summary>
    public interface IAopProxy
    {
    }

    /// <summary>
    /// 忽略拦截
    /// </summary>
    public class IgnoreAttribute : NonAspectAttribute
    {
    }

    /// <summary>
    /// 拦截器基类
    /// </summary>
    public abstract class InterceptorBase : AbstractInterceptorAttribute
    {
    }

    /// <summary>
    /// 验证参数不能为空
    /// </summary>
    public class NotEmptyAttribute : ParameterInterceptorBase
    {
        /// <summary>
        /// 执行
        /// </summary>
        public override Task Invoke(ParameterAspectContext context, ParameterAspectDelegate next)
        {
            if (string.IsNullOrWhiteSpace(context.Parameter.Value.SafeString()))
                throw new ArgumentNullException(context.Parameter.Name);
            return next(context);
        }
    }

    /// <summary>
    /// 验证参数不能为null
    /// </summary>
    public class NotNullAttribute : ParameterInterceptorBase
    {
        /// <summary>
        /// 执行
        /// </summary>
        public override Task Invoke(ParameterAspectContext context, ParameterAspectDelegate next)
        {
            if (context.Parameter.Value == null)
                throw new ArgumentNullException(context.Parameter.Name);
            return next(context);
        }
    }

    /// <summary>
    /// 参数拦截器基类
    /// </summary>
    public abstract class ParameterInterceptorBase : ParameterInterceptorAttribute
    {
    }
}

namespace Validation
{
    global using System;
    global using System.Collections.Generic;
    global using System.ComponentModel.DataAnnotations;
    global using System.Globalization;
    global using System.Linq;
    global using System.Threading.Tasks;
    using AspectCore;
    using AspectCore.DynamicProxy.Parameters;

    #region Validators
    /// <summary>
    /// 身份证验证
    /// </summary>
    [AttributeUsage(AttributeTargets.Property)]
    public class IdCardAttribute : ValidationAttribute
    {
        /// <summary>
        /// 格式化错误消息
        /// </summary>
        public override string FormatErrorMessage(string name)
        {
            if (ErrorMessage == null && ErrorMessageResourceName == null)
                ErrorMessage = R.InvalidIdCard;
            return string.Format(CultureInfo.CurrentCulture, ErrorMessageString);
        }

        /// <summary>
        /// 是否验证通过
        /// </summary>
        protected override ValidationResult IsValid(object value, ValidationContext validationContext)
        {
            if (value.SafeString().IsEmpty())
                return ValidationResult.Success;
            if (Util.Helpers.Regex.IsMatch(value.SafeString(), ValidatePattern.IdCardPattern))
                return ValidationResult.Success;
            return new ValidationResult(FormatErrorMessage(string.Empty));
        }
    }

    /// <summary>
    /// 验证模式
    /// </summary>
    public static class ValidatePattern
    {
        /// <summary>
        /// 手机号验证正则表达式
        /// </summary>
        public static string MobilePhonePattern = "^1[0-9]{10}$";
        /// <summary>
        /// 身份证验证正则表达式
        /// </summary>
        public static string IdCardPattern = @"(^\d{15}$)|(^\d{18}$)|(^\d{17}(\d|X|x)$)";
    }
    #endregion

    /// <summary>
    /// 数据注解验证操作
    /// </summary>
    public static class DataAnnotationValidation
    {
        /// <summary>
        /// 验证
        /// </summary>
        /// <param name="target">验证目标</param>
        public static ValidationResultCollection Validate(object target)
        {
            if (target == null)
                throw new ArgumentNullException(nameof(target));
            var result = new ValidationResultCollection();
            var validationResults = new List<ValidationResult>();
            var context = new ValidationContext(target, null, null);
            var isValid = Validator.TryValidateObject(target, context, validationResults, true);
            if (!isValid)
                result.AddList(validationResults);
            return result;
        }
    }

    /// <summary>
    /// 验证操作
    /// </summary>
    public interface IValidation
    {
        /// <summary>
        /// 验证
        /// </summary>
        ValidationResultCollection Validate();
    }

    /// <summary>
    /// 验证处理器
    /// </summary>
    public interface IValidationHandler
    {
        /// <summary>
        /// 处理验证错误
        /// </summary>
        /// <param name="results">验证结果集合</param>
        void Handle(ValidationResultCollection results);
    }

    /// <summary>
    /// 验证规则
    /// </summary>
    public interface IValidationRule
    {
        /// <summary>
        /// 验证
        /// </summary>
        ValidationResult Validate();
    }

    /// <summary>
    /// 验证失败，不做任何处理
    /// </summary>
    public class NothingHandler : IValidationHandler
    {
        /// <summary>
        /// 处理验证错误
        /// </summary>
        /// <param name="results">验证结果集合</param>
        public void Handle(ValidationResultCollection results)
        {
        }
    }

    /// <summary>
    /// 验证失败，抛出异常
    /// </summary>
    public class ThrowHandler : IValidationHandler
    {
        /// <summary>
        /// 处理验证错误
        /// </summary>
        /// <param name="results">验证结果集合</param>
        public void Handle(ValidationResultCollection results)
        {
            if (results.IsValid)
                return;
            throw new Warning(results.First().ErrorMessage);
        }
    }

    /// <summary>
    /// 验证结果集合
    /// </summary>
    public class ValidationResultCollection : List<ValidationResult>
    {
        /// <summary>
        /// 初始化验证结果集合
        /// </summary>
        public ValidationResultCollection() : this("")
        {
        }

        /// <summary>
        /// 初始化验证结果集合
        /// </summary>
        /// <param name="result">验证结果</param>
        public ValidationResultCollection(string result)
        {
            if (string.IsNullOrWhiteSpace(result))
                return;
            Add(new ValidationResult(result));
        }

        /// <summary>
        /// 成功验证结果集合
        /// </summary>
        public static readonly ValidationResultCollection Success = new();

        /// <summary>
        /// 是否有效
        /// </summary>
        public bool IsValid => Count == 0;

        /// <summary>
        /// 添加验证结果集合
        /// </summary>
        /// <param name="results">验证结果集合</param>
        public void AddList(IEnumerable<ValidationResult> results)
        {
            if (results == null)
                return;
            foreach (var result in results)
                Add(result);
        }

        /// <summary>
        /// 输出验证消息
        /// </summary>
        public override string ToString()
        {
            if (IsValid)
                return string.Empty;
            return this.First().ErrorMessage;
        }
    }

    /// <summary>
    /// 验证拦截器
    /// </summary>
    public class ValidAttribute : ParameterInterceptorBase
    {
        /// <summary>
        /// 执行
        /// </summary>
        public override async Task Invoke(ParameterAspectContext context, ParameterAspectDelegate next)
        {
            Validate(context.Parameter);
            await next(context);
        }

        /// <summary>
        /// 验证
        /// </summary>
        private void Validate(Parameter parameter)
        {
            if (Reflection.IsGenericCollection(parameter.RawType))
            {
                ValidateCollection(parameter);
                return;
            }
            IValidation validation = parameter.Value as IValidation;
            validation?.Validate();
        }

        /// <summary>
        /// 验证集合
        /// </summary>
        private void ValidateCollection(Parameter parameter)
        {
            if (!(parameter.Value is IEnumerable<IValidation> validations))
                return;
            foreach (var validation in validations)
                validation.Validate();
        }
    }
}

namespace Security
{
    global using System;
    global using System.Linq;
    global using System.Security.Claims;
    global using System.Security.Cryptography;
    global using System.Security.Principal;
    global using System.Text;
    global using System.Threading.Tasks;

    /// <summary>
    /// 加密操作
    /// </summary>
    public static class Encrypt
    {

        #region Md5加密

        /// <summary>
        /// Md5加密，返回16位结果
        /// </summary>
        /// <param name="value">值</param>
        public static string Md5By16(string value)
        {
            return Md5By16(value, Encoding.UTF8);
        }

        /// <summary>
        /// Md5加密，返回16位结果
        /// </summary>
        /// <param name="value">值</param>
        /// <param name="encoding">字符编码</param>
        public static string Md5By16(string value, Encoding encoding)
        {
            return Md5(value, encoding, 4, 8);
        }

        /// <summary>
        /// Md5加密
        /// </summary>
        private static string Md5(string value, Encoding encoding, int? startIndex, int? length)
        {
            if (string.IsNullOrWhiteSpace(value))
                return string.Empty;
            var md5 = MD5.Create();
            string result;
            try
            {
                var hash = md5.ComputeHash(encoding.GetBytes(value));
                result = startIndex == null ? BitConverter.ToString(hash) : BitConverter.ToString(hash, startIndex.SafeValue(), length.SafeValue());
            }
            finally
            {
                md5.Clear();
            }
            return result.Replace("-", "");
        }

        /// <summary>
        /// Md5加密，返回32位结果
        /// </summary>
        /// <param name="value">值</param>
        public static string Md5By32(string value)
        {
            return Md5By32(value, Encoding.UTF8);
        }

        /// <summary>
        /// Md5加密，返回32位结果
        /// </summary>
        /// <param name="value">值</param>
        /// <param name="encoding">字符编码</param>
        public static string Md5By32(string value, Encoding encoding)
        {
            return Md5(value, encoding, null, null);
        }

        #endregion

        #region DES加密

        /// <summary>
        /// DES密钥,24位字符串
        /// </summary>
        public static string DesKey = "#s^un2ye21fcv%|f0XpR,+vh";

        /// <summary>
        /// DES加密
        /// </summary>
        /// <param name="value">待加密的值</param>
        public static string DesEncrypt(object value)
        {
            return DesEncrypt(value, DesKey);
        }

        /// <summary>
        /// DES加密
        /// </summary>
        /// <param name="value">待加密的值</param>
        /// <param name="key">密钥,24位</param>
        /// <param name="encoding">编码</param>
        /// <param name="cipherMode">加密模式</param>
        /// <param name="paddingMode">填充模式</param>
        public static string DesEncrypt(object value, string key, Encoding encoding = null, CipherMode cipherMode = CipherMode.ECB, PaddingMode paddingMode = PaddingMode.PKCS7)
        {
            string text = value.SafeString();
            if (ValidateDes(text, key) == false)
                return string.Empty;
            using var transform = CreateDesProvider(key, cipherMode, paddingMode).CreateEncryptor();
            return GetEncryptResult(text, encoding, transform);
        }

        /// <summary>
        /// 验证Des加密参数
        /// </summary>
        private static bool ValidateDes(string text, string key)
        {
            if (text.IsEmpty() || key.IsEmpty())
                return false;
            return key.Length == 24;
        }

        /// <summary>
        /// 创建Des加密服务提供程序
        /// </summary>
        private static TripleDES CreateDesProvider(string key, CipherMode cipherMode, PaddingMode paddingMode)
        {
            var result = TripleDES.Create();
            result.Key = Encoding.ASCII.GetBytes(key);
            result.Mode = cipherMode;
            result.Padding = paddingMode;
            return result;
        }

        /// <summary>
        /// 获取加密结果
        /// </summary>
        private static string GetEncryptResult(string value, Encoding encoding, ICryptoTransform transform)
        {
            encoding ??= Encoding.UTF8;
            var bytes = encoding.GetBytes(value);
            var result = transform.TransformFinalBlock(bytes, 0, bytes.Length);
            return System.Convert.ToBase64String(result);
        }

        /// <summary>
        /// DES解密
        /// </summary>
        /// <param name="value">加密后的值</param>
        public static string DesDecrypt(object value)
        {
            return DesDecrypt(value, DesKey);
        }

        /// <summary>
        /// DES解密
        /// </summary>
        /// <param name="value">加密后的值</param>
        /// <param name="key">密钥,24位</param>
        /// <param name="encoding">编码</param>
        /// <param name="cipherMode">加密模式</param>
        /// <param name="paddingMode">填充模式</param>
        public static string DesDecrypt(object value, string key, Encoding encoding = null, CipherMode cipherMode = CipherMode.ECB, PaddingMode paddingMode = PaddingMode.PKCS7)
        {
            string text = value.SafeString();
            if (!ValidateDes(text, key))
                return string.Empty;
            using var transform = CreateDesProvider(key, cipherMode, paddingMode).CreateDecryptor();
            return GetDecryptResult(text, encoding, transform);
        }

        /// <summary>
        /// 获取解密结果
        /// </summary>
        private static string GetDecryptResult(string value, Encoding encoding, ICryptoTransform transform)
        {
            encoding ??= Encoding.UTF8;
            var bytes = System.Convert.FromBase64String(value);
            var result = transform.TransformFinalBlock(bytes, 0, bytes.Length);
            return encoding.GetString(result);
        }

        #endregion

        #region AES加密

        /// <summary>
        /// 128位0向量
        /// </summary>
        private static byte[] _iv;
        /// <summary>
        /// 128位0向量
        /// </summary>
        private static byte[] Iv
        {
            get
            {
                if (_iv == null)
                {
                    var size = 16;
                    _iv = new byte[size];
                    for (int i = 0; i < size; i++)
                        _iv[i] = 0;
                }
                return _iv;
            }
        }

        /// <summary>
        /// AES密钥
        /// </summary>
        public static string AesKey = "QaP1AF8utIarcBqdhYTZpVGbiNQ9M6IL";

        /// <summary>
        /// AES加密
        /// </summary>
        /// <param name="value">待加密的值</param>
        public static string AesEncrypt(string value)
        {
            return AesEncrypt(value, AesKey);
        }

        /// <summary>
        /// AES加密
        /// </summary>
        /// <param name="value">待加密的值</param>
        /// <param name="key">密钥</param>
        /// <param name="encoding">编码</param>
        /// <param name="cipherMode">加密模式</param>
        /// <param name="paddingMode">填充模式</param>
        /// <param name="iv">初始化向量</param>
        public static string AesEncrypt(string value, string key, Encoding encoding = null, CipherMode cipherMode = CipherMode.CBC, PaddingMode paddingMode = PaddingMode.PKCS7, byte[] iv = null)
        {
            if (value.IsEmpty() || key.IsEmpty())
                return string.Empty;
            iv ??= Iv;
            var aes = CreateAes(key, cipherMode, paddingMode, iv);
            using var transform = aes.CreateEncryptor(aes.Key, aes.IV);
            return GetEncryptResult(value, encoding, transform);
        }

        /// <summary>
        /// 创建Aes
        /// </summary>
        private static Aes CreateAes(string key, CipherMode cipherMode, PaddingMode paddingMode, byte[] iv)
        {
            var result = Aes.Create();
            result.Key = Encoding.ASCII.GetBytes(key);
            result.Mode = cipherMode;
            result.Padding = paddingMode;
            result.IV = iv;
            return result;
        }

        /// <summary>
        /// AES解密
        /// </summary>
        /// <param name="value">加密后的值</param>
        public static string AesDecrypt(string value)
        {
            return AesDecrypt(value, AesKey);
        }

        /// <summary>
        /// AES解密
        /// </summary>
        /// <param name="value">加密后的值</param>
        /// <param name="key">密钥</param>
        /// <param name="encoding">编码</param>
        /// <param name="cipherMode">加密模式</param>
        /// <param name="paddingMode">填充模式</param>
        /// <param name="iv">初始化向量</param>
        public static string AesDecrypt(string value, string key, Encoding encoding = null, CipherMode cipherMode = CipherMode.CBC, PaddingMode paddingMode = PaddingMode.PKCS7, byte[] iv = null)
        {
            if (value.IsEmpty() || key.IsEmpty())
                return string.Empty;
            iv ??= Iv;
            var aes = CreateAes(key, cipherMode, paddingMode, iv);
            using var transform = aes.CreateDecryptor(aes.Key, aes.IV);
            return GetDecryptResult(value, encoding, transform);
        }

        #endregion

        #region HmacSha256加密

        /// <summary>
        /// HMACSHA256加密
        /// </summary>
        /// <param name="value">值</param>
        /// <param name="key">密钥</param>
        /// <param name="encoding">字符编码</param>
        /// <param name="allowEmptyValue">是否允许空值</param>
        public static string HmacSha256(string value, string key, Encoding encoding = null, bool allowEmptyValue = false)
        {
            if (value.IsEmpty() || key.IsEmpty())
            {
                if (allowEmptyValue == false)
                    return string.Empty;
                value = string.Empty;
            }
            encoding ??= Encoding.UTF8;
            var sha256 = new HMACSHA256(Encoding.ASCII.GetBytes(key));
            var hash = sha256.ComputeHash(encoding.GetBytes(value));
            return string.Join("", hash.ToList().Select(t => t.ToString("x2")).ToArray());
        }

        #endregion

        #region RSA加密

        /// <summary>
        /// RSA签名
        /// </summary>
        /// <param name="value">待加密的值</param>
        /// <param name="privateKey">私钥</param>
        /// <param name="encoding">编码</param>
        /// <param name="hashAlgorithm">加密算法,默认值: HashAlgorithmName.SHA1</param>
        /// <param name="rsaKeyType">Rsa密钥类型,默认值: Pkcs1</param>
        public static string RsaSign(string value, string privateKey, Encoding encoding = null, HashAlgorithmName? hashAlgorithm = null, RSAKeyType rsaKeyType = RSAKeyType.Pkcs1)
        {
            if (value.IsEmpty() || privateKey.IsEmpty())
                return string.Empty;
            var rsa = RSA.Create();
            ImportPrivateKey(rsa, privateKey, rsaKeyType);
            encoding ??= Encoding.UTF8;
            hashAlgorithm ??= HashAlgorithmName.SHA1;
            var result = rsa.SignData(encoding.GetBytes(value), hashAlgorithm.Value, RSASignaturePadding.Pkcs1);
            return System.Convert.ToBase64String(result);
        }

        /// <summary>
        /// 导入私钥
        /// </summary>
        private static void ImportPrivateKey(RSA rsa, string privateKey, RSAKeyType rsaKeyType)
        {
            rsa.ImportPrivateKey(rsaKeyType, privateKey);
        }

        /// <summary>
        /// Rsa验签
        /// </summary>
        /// <param name="value">待验签的值</param>
        /// <param name="publicKey">公钥</param>
        /// <param name="sign">签名</param>
        /// <param name="encoding">编码</param>
        /// <param name="hashAlgorithm">加密算法,默认值: HashAlgorithmName.SHA1</param>
        public static bool RsaVerify(string value, string publicKey, string sign, Encoding encoding = null, HashAlgorithmName? hashAlgorithm = null)
        {
            if (value.IsEmpty() || publicKey.IsEmpty() || sign.IsEmpty())
                return false;
            var rsa = RSA.Create();
            ImportPublicKey(rsa, publicKey);
            encoding ??= Encoding.UTF8;
            var signData = System.Convert.FromBase64String(sign);
            hashAlgorithm ??= HashAlgorithmName.SHA1;
            return rsa.VerifyData(encoding.GetBytes(value), signData, hashAlgorithm.Value, RSASignaturePadding.Pkcs1);
        }

        /// <summary>
        /// 导入公钥
        /// </summary>
        private static void ImportPublicKey(RSA rsa, string publicKey)
        {
            var key = System.Convert.FromBase64String(publicKey);
            rsa.ImportSubjectPublicKeyInfo(key, out _);
        }

        /// <summary>
        /// RSA加密
        /// </summary>
        /// <param name="value">待加密的值</param>
        /// <param name="publicKey">公钥</param>
        public static string RsaEncrypt(string value, string publicKey)
        {
            if (value.IsEmpty() || publicKey.IsEmpty())
                return string.Empty;
            var rsa = RSA.Create();
            ImportPublicKey(rsa, publicKey);
            return rsa.EncryptBigData(value, RSAEncryptionPadding.Pkcs1);
        }

        /// <summary>
        /// RSA解密
        /// </summary>
        /// <param name="value">加密后的值</param>
        /// <param name="privateKey">私钥</param>
        public static string RsaDecrypt(string value, string privateKey)
        {
            if (value.IsEmpty() || privateKey.IsEmpty())
                return string.Empty;
            var rsa = RSA.Create();
            ImportPrivateKey(rsa, privateKey, RSAKeyType.Pkcs1);
            return rsa.DecryptBigData(value, RSAEncryptionPadding.Pkcs1);
        }

        #endregion

        #region 生成RSA公钥和私钥对

        /// <summary>
        /// 生成RSA公钥和私钥对,返回值Item1为公钥,Item2为私钥
        /// </summary>
        public static (string, string) CreateRsaKey()
        {
            var rsa = RSA.Create();
            var publicKey = FormatPublicKey(rsa.ExportSubjectPublicKeyInfoPem());
            var privateKey = rsa.ExportPrivateKey(RSAKeyType.Pkcs1);
            return (publicKey, privateKey);
        }

        /// <summary>
        /// 格式化公钥
        /// </summary>
        private static string FormatPublicKey(string key)
        {
            return key.Replace("-----BEGIN RSA PRIVATE KEY-----", "")
                .Replace("-----END RSA PRIVATE KEY-----", "")
                .Replace("-----BEGIN RSA PUBLIC KEY-----", "")
                .Replace("-----END RSA PUBLIC KEY-----", "")
                .Replace("-----BEGIN PRIVATE KEY-----", "")
                .Replace("-----END PRIVATE KEY-----", "")
                .Replace("-----BEGIN PUBLIC KEY-----", "")
                .Replace("-----END PUBLIC KEY-----", "")
                .Replace(Environment.NewLine, "");
        }

        #endregion
    }

