        /// <param name="condition">查询条件</param>
        /// <param name="action">访问IQueryable的回调函数,用于执行Include等操作</param>
        /// <param name="cancellationToken">取消令牌</param>
        Task<TEntity> SingleAsync(Expression<Func<TEntity, bool>> condition, Func<IQueryable<TEntity>, IQueryable<TEntity>> action, CancellationToken cancellationToken = default);
        /// <summary>
        /// 查找实体列表
        /// </summary>
        /// <param name="condition">查询条件</param>
        List<TEntity> FindAll(Expression<Func<TEntity, bool>> condition = null);
        /// <summary>
        /// 查找实体列表
        /// </summary>
        /// <param name="condition">查询条件</param>
        /// <param name="cancellationToken">取消令牌</param>
        Task<List<TEntity>> FindAllAsync(Expression<Func<TEntity, bool>> condition = null, CancellationToken cancellationToken = default);
        /// <summary>
        /// 判断是否存在
        /// </summary>
        /// <param name="ids">标识列表</param>
        bool Exists(params TKey[] ids);
        /// <summary>
        /// 判断是否存在
        /// </summary>
        /// <param name="condition">条件</param>
        bool Exists(Expression<Func<TEntity, bool>> condition);
        /// <summary>
        /// 判断是否存在
        /// </summary>
        /// <param name="ids">标识列表</param>
        Task<bool> ExistsAsync(params TKey[] ids);
        /// <summary>
        /// 判断是否存在
        /// </summary>
        /// <param name="condition">条件</param>
        /// <param name="cancellationToken">取消令牌</param>
        Task<bool> ExistsAsync(Expression<Func<TEntity, bool>> condition, CancellationToken cancellationToken = default);
        /// <summary>
        /// 查找数量
        /// </summary>
        /// <param name="condition">条件</param>
        int Count(Expression<Func<TEntity, bool>> condition = null);
        /// <summary>
        /// 查找数量
        /// </summary>
        /// <param name="condition">查询条件</param>
        /// <param name="cancellationToken">取消令牌</param>
        Task<int> CountAsync(Expression<Func<TEntity, bool>> condition = null, CancellationToken cancellationToken = default);
    }

    /// <summary>
    /// 存储器
    /// </summary>
    /// <typeparam name="TEntity">对象类型</typeparam>
    public interface IStore<TEntity> : IStore<TEntity, Guid>, IQueryStore<TEntity>
        where TEntity : class, IKey<Guid>
    {
    }

    /// <summary>
    /// 存储器
    /// </summary>
    /// <typeparam name="TEntity">对象类型</typeparam>
    /// <typeparam name="TKey">对象标识类型</typeparam>
    public interface IStore<TEntity, in TKey> : IQueryStore<TEntity, TKey> where TEntity : class, IKey<TKey>
    {
        /// <summary>
        /// 添加实体
        /// </summary>
        /// <param name="entity">实体</param>
        /// <param name="cancellationToken">取消令牌</param>
        Task AddAsync(TEntity entity, CancellationToken cancellationToken = default);
        /// <summary>
        /// 添加实体集合
        /// </summary>
        /// <param name="entities">实体集合</param>
        /// <param name="cancellationToken">取消令牌</param>
        Task AddAsync(IEnumerable<TEntity> entities, CancellationToken cancellationToken = default);
        /// <summary>
        /// 修改实体
        /// </summary>
        /// <param name="entity">实体</param>
        /// <param name="cancellationToken">取消令牌</param>
        Task UpdateAsync(TEntity entity, CancellationToken cancellationToken = default);
        /// <summary>
        /// 修改实体集合
        /// </summary>
        /// <param name="entities">实体集合</param>
        /// <param name="cancellationToken">取消令牌</param>
        Task UpdateAsync(IEnumerable<TEntity> entities, CancellationToken cancellationToken = default);
        /// <summary>
        /// 移除实体
        /// </summary>
        /// <param name="id">标识</param>
        /// <param name="cancellationToken">取消令牌</param>
        Task RemoveAsync(object id, CancellationToken cancellationToken = default);
        /// <summary>
        /// 移除实体
        /// </summary>
        /// <param name="entity">实体</param>
        /// <param name="cancellationToken">取消令牌</param>
        Task RemoveAsync(TEntity entity, CancellationToken cancellationToken = default);
        /// <summary>
        /// 移除实体集合
        /// </summary>
        /// <param name="ids">标识集合</param>
        /// <param name="cancellationToken">取消令牌</param>
        Task RemoveAsync(IEnumerable<TKey> ids, CancellationToken cancellationToken = default);
        /// <summary>
        /// 移除实体集合
        /// </summary>
        /// <param name="entities">实体集合</param>
        /// <param name="cancellationToken">取消令牌</param>
        Task RemoveAsync(IEnumerable<TEntity> entities, CancellationToken cancellationToken = default);
    }
    #endregion

    #region Trees
    /// <summary>
    /// 树形查询参数
    /// </summary>
    public interface ITreeQueryParameter : IPage
    {
        /// <summary>
        /// 父标识
        /// </summary>
        string ParentId { get; set; }
        /// <summary>
        /// 层级
        /// </summary>
        int? Level { get; set; }
        /// <summary>
        /// 路径
        /// </summary>
        string Path { get; set; }
        /// <summary>
        /// 启用
        /// </summary>
        bool? Enabled { get; set; }
    }

    /// <summary>
    /// 树形查询参数
    /// </summary>
    public class TreeQueryParameter : QueryParameter, ITreeQueryParameter
    {
        /// <summary>
        /// 初始化树形查询参数
        /// </summary>
        public TreeQueryParameter()
        {
            Order = "SortId";
        }

        /// <summary>
        /// 父标识
        /// </summary>
        public string ParentId { get; set; }

        /// <summary>
        /// 层级
        /// </summary>
        public int? Level { get; set; }

        /// <summary>
        /// 路径
        /// </summary>
        public string Path { get; set; }

        /// <summary>
        /// 启用
        /// </summary>
        [Display(Name = "enabled")]
        public bool? Enabled { get; set; }
    }
    #endregion

    /// <summary>
    /// 连接字符串集合
    /// </summary>
    public class ConnectionStringCollection : Dictionary<string, string>
    {
        /// <summary>
        /// 默认连接字符串名称,值: Default
        /// </summary>
        public const string DefaultName = "Default";

        /// <summary>
        /// 默认连接字符串
        /// </summary>
        public string Default
        {
            get => this.GetValue(DefaultName);
            set => this[DefaultName] = value;
        }

        /// <summary>
        /// 获取连接字符串
        /// </summary>
        /// <param name="name">连接字符串名称</param>
        public string GetConnectionString(string name)
        {
            return ContainsKey(name) ? this.GetValue(name) : Default;
        }
    }

    /// <summary>
    /// 连接字符串名称
    /// </summary>
    public class ConnectionStringNameAttribute : Attribute
    {
        /// <summary>
        /// 连接字符串名称
        /// </summary>
        public string Name { get; }

        /// <summary>
        /// 初始化连接字符串名称
        /// </summary>
        /// <param name="name">连接字符串名称</param>
        public ConnectionStringNameAttribute(string name)
        {
            Name = name;
        }

        /// <summary>
        /// 获取连接字符串名称,如果未设置名称则返回类型名
        /// </summary>
        /// <typeparam name="T">类型</typeparam>
        public static string GetName<T>()
        {
            return GetName(typeof(T));
        }

        /// <summary>
        /// 获取连接字符串名称,如果未设置名称则返回类型名
        /// </summary>
        /// <param name="type">类型</param>
        public static string GetName(Type type)
        {
            if (type == null)
                return null;
            var attribute = type.GetCustomAttribute<ConnectionStringNameAttribute>();
            return attribute == null || attribute.Name.IsEmpty() ? type.Name : attribute.Name;
        }
    }

    /// <summary>
    /// 查询条件
    /// </summary>
    /// <typeparam name="TEntity">实体类型</typeparam>
    public interface ICondition<TEntity>
    {
        /// <summary>
        /// 获取查询条件
        /// </summary>
        Expression<Func<TEntity, bool>> GetCondition();
    }

    /// <summary>
    /// 工作单元
    /// </summary>
    [Ignore]
    public interface IUnitOfWork : IDisposable, IFilterOperation
    {
        /// <summary>
        /// 提交,返回影响的行数
        /// </summary>
        Task<int> CommitAsync();
    }

    /// <summary>
    /// 工作单元操作管理器,用于将操作延迟到工作单元提交后执行
    /// </summary>
    public interface IUnitOfWorkActionManager : IScopeDependency
    {
        /// <summary>
        /// 注册操作
        /// </summary>
        /// <param name="action">操作</param>
        void Register(Func<Task> action);
        /// <summary>
        /// 执行操作
        /// </summary>
        Task ExecuteAsync();
    }

    /// <summary>
    /// 空工作单元操作管理器
    /// </summary>
    public class NullUnitOfWorkActionManager : IUnitOfWorkActionManager
    {
        /// <summary>
        /// 初始化空工作单元操作管理器
        /// </summary>
        public NullUnitOfWorkActionManager()
        {
        }

        /// <summary>
        /// 空工作单元操作管理器实例
        /// </summary>
        public static readonly IUnitOfWorkActionManager Instance = new NullUnitOfWorkActionManager();

        /// <inheritdoc />
        public void Register(Func<Task> action)
        {
        }

        /// <inheritdoc />
        public Task ExecuteAsync()
        {
            return Task.CompletedTask;
        }
    }

    /// <summary>
    /// 分页集合
    /// </summary>
    /// <typeparam name="T">元素类型</typeparam>
    public class PageList<T>
    {
        /// <summary>
        /// 初始化分页集合
        /// </summary>
        public PageList() : this(0)
        {
        }

        /// <summary>
        /// 初始化分页集合
        /// </summary>
        /// <param name="data">内容</param>
        public PageList(IEnumerable<T> data = null)
            : this(0, data)
        {
        }

        /// <summary>
        /// 初始化分页集合
        /// </summary>
        /// <param name="totalCount">总行数</param>
        /// <param name="data">内容</param>
        public PageList(int totalCount, IEnumerable<T> data = null)
            : this(1, 20, totalCount, data)
        {
        }

        /// <summary>
        /// 初始化分页集合
        /// </summary>
        /// <param name="page">页索引</param>
        /// <param name="pageSize">每页显示行数</param>
        /// <param name="totalCount">总行数</param>
        /// <param name="data">内容</param>
        public PageList(int page, int pageSize, int totalCount, IEnumerable<T> data = null)
            : this(page, pageSize, totalCount, "", data)
        {
        }

        /// <summary>
        /// 初始化分页集合
        /// </summary>
        /// <param name="page">页索引</param>
        /// <param name="pageSize">每页显示行数</param>
        /// <param name="totalCount">总行数</param>
        /// <param name="order">排序条件</param>
        /// <param name="data">内容</param>
        public PageList(int page, int pageSize, int totalCount, string order, IEnumerable<T> data = null)
        {
            Data = data?.ToList() ?? new List<T>();
            var pager = new Pager(page, pageSize, totalCount);
            Total = pager.Total;
            PageCount = pager.GetPageCount();
            Page = pager.Page;
            PageSize = pager.PageSize;
            Order = order;
        }

        /// <summary>
        /// 初始化分页集合
        /// </summary>
        /// <param name="pager">查询对象</param>
        /// <param name="data">内容</param>
        public PageList(IPage pager, IEnumerable<T> data = null)
            : this(pager.Page, pager.PageSize, pager.Total, pager.Order, data)
        {
        }

        /// <summary>
        /// 页索引，即第几页，从1开始
        /// </summary>
        public int Page { get; set; }

        /// <summary>
        /// 每页显示行数
        /// </summary>
        public int PageSize { get; set; }

        /// <summary>
        /// 总行数
        /// </summary>
        public int Total { get; set; }

        /// <summary>
        /// 总页数
        /// </summary>
        public int PageCount { get; set; }

        /// <summary>
        /// 排序条件
        /// </summary>
        public string Order { get; set; }

        /// <summary>
        /// 内容
        /// </summary>
        public List<T> Data { get; init; }

        /// <summary>
        /// 索引器
        /// </summary>
        /// <param name="index">索引</param>
        public T this[int index]
        {
            get => Data[index];
            set => Data[index] = value;
        }

        /// <summary>
        /// 添加元素
        /// </summary>
        /// <param name="item">元素</param>
        public void Add(T item)
        {
            Data.Add(item);
        }

        /// <summary>
        /// 添加元素集合
        /// </summary>
        /// <param name="collection">元素集合</param>
        public void AddRange(IEnumerable<T> collection)
        {
            Data.AddRange(collection);
        }

        /// <summary>
        /// 清空
        /// </summary>
        public void Clear()
        {
            Data.Clear();
        }

        /// <summary>
        /// 转换分页集合
        /// </summary>
        /// <typeparam name="TResult">目标元素类型</typeparam>
        /// <param name="converter">转换方法</param>
        public PageList<TResult> Convert<TResult>(Func<T, TResult> converter)
        {
            return Convert(Data.Select(converter));
        }

        /// <summary>
        /// 转换分页集合
        /// </summary>
        /// <param name="data">内容</param>
        public PageList<TResult> Convert<TResult>(IEnumerable<TResult> data)
        {
            return new(Page, PageSize, Total, Order, data);
        }
    }

    /// <summary>
    /// 存储器扩展
    /// </summary>
    public static class StoreExtensions
    {
        /// <summary>
        /// 设置为不跟踪实体
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// <typeparam name="TKey">实体标识类型</typeparam>
        /// <param name="source">源</param>
        public static IQueryStore<TEntity, TKey> NoTracking<TEntity, TKey>(this IQueryStore<TEntity, TKey> source) where TEntity : class, IKey<TKey>
        {
            source.CheckNull(nameof(source));
            if (source is ITrack store)
                store.NoTracking();
            return source;
        }
    }
}

