        /// <param name="encoding">字符编码</param>
        public static NameValueCollection ParseQueryString(string query, Encoding encoding)
        {
            return HttpUtility.ParseQueryString(query, encoding);
        }

        #endregion

        #region DownloadAsync(下载)

        /// <summary>
        /// 下载文件
        /// </summary>
        /// <param name="filePath">文件绝对路径</param>
        /// <param name="fileName">文件名,包含扩展名</param>
        public static async Task DownloadFileAsync(string filePath, string fileName)
        {
            await DownloadFileAsync(filePath, fileName, Encoding.UTF8);
        }

        /// <summary>
        /// 下载文件
        /// </summary>
        /// <param name="filePath">文件绝对路径</param>
        /// <param name="fileName">文件名,包含扩展名</param>
        /// <param name="encoding">字符编码</param>
        public static async Task DownloadFileAsync(string filePath, string fileName, Encoding encoding)
        {
            var bytes = File.ReadToBytes(filePath);
            await DownloadAsync(bytes, fileName, encoding);
        }

        /// <summary>
        /// 下载
        /// </summary>
        /// <param name="stream">流</param>
        /// <param name="fileName">文件名,包含扩展名</param>
        public static async Task DownloadAsync(Stream stream, string fileName)
        {
            await DownloadAsync(stream, fileName, Encoding.UTF8);
        }

        /// <summary>
        /// 下载
        /// </summary>
        /// <param name="stream">流</param>
        /// <param name="fileName">文件名,包含扩展名</param>
        /// <param name="encoding">字符编码</param>
        public static async Task DownloadAsync(Stream stream, string fileName, Encoding encoding)
        {
            var bytes = await File.ToBytesAsync(stream);
            await DownloadAsync(bytes, fileName, encoding);
        }

        /// <summary>
        /// 下载
        /// </summary>
        /// <param name="bytes">字节流</param>
        /// <param name="fileName">文件名,包含扩展名</param>
        public static async Task DownloadAsync(byte[] bytes, string fileName)
        {
            await DownloadAsync(bytes, fileName, Encoding.UTF8);
        }

        /// <summary>
        /// 下载
        /// </summary>
        /// <param name="bytes">字节流</param>
        /// <param name="fileName">文件名,包含扩展名</param>
        /// <param name="encoding">字符编码</param>
        public static async Task DownloadAsync(byte[] bytes, string fileName, Encoding encoding)
        {
            if (bytes == null || bytes.Length == 0)
                return;
            fileName = fileName.Replace(" ", "");
            fileName = UrlEncode(fileName, encoding);
            Response.ContentType = "application/octet-stream";
            Response.Headers.Append("Content-Disposition", $"attachment; filename={fileName}");
            Response.Headers.Append("Content-Length", bytes.Length.ToString());
            await Response.Body.WriteAsync(bytes, 0, bytes.Length);
        }

        #endregion

        #region GetCookie(获取Cookie)

        /// <summary>
        /// 获取Cookie
        /// </summary>
        /// <param name="key">cookie键名</param>
        public static string GetCookie(string key)
        {
            return Request?.Cookies[key];
        }

        #endregion

        #region SetCookie(设置Cookie)

        /// <summary>
        /// 设置Cookie
        /// </summary>
        /// <param name="key">cookie键名</param>
        /// <param name="value">值</param>
        public static void SetCookie(string key, string value)
        {
            Response?.Cookies.Append(key, value);
        }

        /// <summary>
        /// 设置Cookie
        /// </summary>
        /// <param name="key">cookie键名</param>
        /// <param name="value">值</param>
        /// <param name="options">Cookie配置</param>
        public static void SetCookie(string key, string value, CookieOptions options)
        {
            Response?.Cookies.Append(key, value, options);
        }

        #endregion

        #region RemoveCookie(移除Cookie)

        /// <summary>
        /// 移除Cookie
        /// </summary>
        /// <param name="key">cookie键名</param>
        public static void RemoveCookie(string key)
        {
            Response?.Cookies.Delete(key);
        }

        /// <summary>
        /// 移除Cookie
        /// </summary>
        /// <param name="key">cookie键名</param>
        /// <param name="options">Cookie配置</param>
        public static void RemoveCookie(string key, CookieOptions options)
        {
            Response?.Cookies.Delete(key, options);
        }

        #endregion
    }
    #endregion

    #region Infrastructure
    /// <summary>
    /// AspNetCore服务注册器
    /// </summary>
    public class AspNetCoreServiceRegistrar : IServiceRegistrar
    {
        /// <summary>
        /// 获取服务名
        /// </summary>
        public static string ServiceName => "AspNetCoreServiceRegistrar";

        /// <summary>
        /// 排序号
        /// </summary>
        public int OrderId => 200;

        /// <summary>
        /// 是否启用
        /// </summary>
        public bool Enabled => ServiceRegistrarConfig.IsEnabled(ServiceName);

        /// <summary>
        /// 注册服务
        /// </summary>
        /// <param name="serviceContext">服务上下文</param>
        public Action Register(ServiceContext serviceContext)
        {
            serviceContext.HostBuilder.ConfigureServices((context, services) =>
            {
                RegisterHttpContextAccessor(services);
                services.AddHttpClient();
                RegisterServiceLocator();
                RegisterHttpClient(services);
                ConfigJsonOptions(services);
            });
            return null;
        }

        /// <summary>
        /// 注册Http上下文访问器
        /// </summary>
        private void RegisterHttpContextAccessor(IServiceCollection services)
        {
            var httpContextAccessor = new HttpContextAccessor();
            services.TryAddSingleton<IHttpContextAccessor>(httpContextAccessor);
            Web.HttpContextAccessor = httpContextAccessor;
        }

        /// <summary>
        /// 注册服务定位器
        /// </summary>
        private void RegisterServiceLocator()
        {
            Ioc.SetServiceProviderAction(() => Web.ServiceProvider);
        }

        /// <summary>
        /// 注册Http客户端
        /// </summary>
        private void RegisterHttpClient(IServiceCollection services)
        {
            services.TryAddSingleton<IHttpClient, HttpClientService>();
        }

        /// <summary>
        /// 配置Json
        /// </summary>
        private void ConfigJsonOptions(IServiceCollection services)
        {
            services.Configure((Microsoft.AspNetCore.Mvc.JsonOptions options) =>
            {
                options.JsonSerializerOptions.Converters.Add(new DateTimeJsonConverter());
                options.JsonSerializerOptions.Converters.Add(new NullableDateTimeJsonConverter());
            });
        }
    }
    #endregion

    #region Security
    /// <summary>
    /// 访问控制过滤器
    /// </summary>
    public class AclFilter : AuthorizeFilter
    {
        /// <summary>
        /// 初始化访问控制过滤器
        /// </summary>
        public AclFilter()
            : base(new AclPolicyProvider(), new[] { new AclAttribute() })
        {
        }

        /// <summary>
        /// 授权
        /// </summary>
        /// <param name="context">授权过滤器上下文</param>
        public override async Task OnAuthorizationAsync(AuthorizationFilterContext context)
        {
            context.CheckNull(nameof(context));
            if (context.IsEffectivePolicy(this) == false)
            {
                return;
            }
            var effectivePolicy = await GetEffectivePolicyAsync(context);
            if (effectivePolicy == null)
                return;
            var policyEvaluator = context.HttpContext.RequestServices.GetRequiredService<IPolicyEvaluator>();
            var authenticateResult = await policyEvaluator.AuthenticateAsync(effectivePolicy, context.HttpContext);
            if (HasAllowAnonymous(context))
            {
                return;
            }
            var authorizationResult = await policyEvaluator.AuthorizeAsync(effectivePolicy, authenticateResult, context.HttpContext, context);
            SetContextResult(context, authorizationResult);
        }

        /// <summary>
        /// 获取有效授权策略
        /// </summary>
        protected async Task<AuthorizationPolicy> GetEffectivePolicyAsync(AuthorizationFilterContext context)
        {
            var builder = new AuthorizationPolicyBuilder(await ComputePolicyAsync());
            for (var i = 0; i < context.Filters.Count; i++)
            {
                if (ReferenceEquals(this, context.Filters[i]))
                    continue;
                if (context.Filters[i] is AclFilter authorizeFilter)
                {
                    builder.Combine(await authorizeFilter.ComputePolicyAsync());
                }
            }
            var endpoint = context.HttpContext.GetEndpoint();
            if (endpoint != null)
            {
                var policyProvider = PolicyProvider ?? context.HttpContext.RequestServices.GetRequiredService<IAuthorizationPolicyProvider>();
                var endpointAuthorizeData = endpoint.Metadata.GetOrderedMetadata<IAuthorizeData>() ?? Array.Empty<IAuthorizeData>();
                var endpointPolicy = await AuthorizationPolicy.CombineAsync(policyProvider, endpointAuthorizeData);
                if (endpointPolicy != null && endpointPolicy.Requirements.Any(t => t is AclRequirement))
                {
                    builder.Requirements.Remove(builder.Requirements.FirstOrDefault(t => t is AclRequirement));
                    builder.Combine(endpointPolicy);
                }
            }
            return builder.Build();
        }

        /// <summary>
        /// 合并授权策略
        /// </summary>
        protected async ValueTask<AuthorizationPolicy> ComputePolicyAsync()
        {
            return await AuthorizationPolicy.CombineAsync(PolicyProvider, AuthorizeData);
        }

        /// <summary>
        /// 是否允许匿名访问
        /// </summary>
        protected bool HasAllowAnonymous(AuthorizationFilterContext context)
        {
            var filters = context.Filters;
            for (var i = 0; i < filters.Count; i++)
            {
                if (filters[i] is IAllowAnonymousFilter)
                {
                    return true;
                }
            }
            var endpoint = context.HttpContext.GetEndpoint();
            if (endpoint?.Metadata?.GetMetadata<IAllowAnonymous>() != null)
            {
                return true;
            }
            return false;
        }

        /// <summary>
        /// 设置授权过滤器上下文结果
        /// </summary>
        /// <param name="context">授权过滤器上下文</param>
        /// <param name="authorizationResult">授权结果</param>
        protected virtual void SetContextResult(AuthorizationFilterContext context, PolicyAuthorizationResult authorizationResult)
        {
            if (authorizationResult.Succeeded)
                return;
            context.Result = new JsonResult(new { Code = StateCode.Unauthorized }) { StatusCode = 200 };
        }
    }

    /// <summary>
    /// 授权处理器
    /// </summary>
    public class AclHandler : AuthorizationHandler<AclRequirement>
    {
        /// <summary>
        /// 处理授权要求
        /// </summary>
        /// <param name="context">授权处理器上下文</param>
        /// <param name="requirement">授权要求</param>
        protected override async Task HandleRequirementAsync(AuthorizationHandlerContext context, AclRequirement requirement)
        {
            if (context == null)
                return;
            if (requirement == null)
                return;
            var httpContext = GetHttpContext(context.Resource);
            if (httpContext == null)
                return;
            var options = GetAclOptions(httpContext);
            if (options.AllowAnonymous)
            {
                context.Succeed(requirement);
                return;
            }
            if (httpContext.GetIdentity().IsAuthenticated == false)
                return;
            if (options.IgnoreAcl)
            {
                context.Succeed(requirement);
                return;
            }
            if (requirement.Ignore)
            {
                context.Succeed(requirement);
                return;
            }
            var permissionManager = httpContext.RequestServices.GetService<IPermissionManager>();
            if (permissionManager == null)
            {
                context.Fail(new AuthorizationFailureReason(this, "未实现IPermissionManager"));
                return;
            }
            var uri = GetResourceUri(requirement, httpContext, options);
            var result = await permissionManager.HasPermissionAsync(uri);
            if (result)
            {
                context.Succeed(requirement);
                return;
            }
            context.Fail(new AuthorizationFailureReason(this, $"没有访问资源 {uri} 的权限"));
        }

        /// <summary>
        /// 获取Http上下文
        /// </summary>
        /// <param name="resource">资源</param>
        protected virtual HttpContext GetHttpContext(dynamic resource)
        {
            if (resource is DefaultHttpContext httpContext)
                return httpContext;
            return resource.HttpContext;
        }

        /// <summary>
        /// 获取访问控制配置
        /// </summary>
        protected virtual AclOptions GetAclOptions(HttpContext httpContext)
        {
            var result = httpContext.RequestServices.GetService<IOptions<AclOptions>>();
            return result == null ? new AclOptions() : result.Value;
        }

        /// <summary>
        /// 获取资源标识
        /// </summary>
        protected virtual string GetResourceUri(AclRequirement requirement, HttpContext httpContext, AclOptions options)
        {
            if (requirement.Uri.IsEmpty() == false)
                return requirement.Uri;
            if (options.ResourceUri.IsEmpty() == false)
                return options.ResourceUri;
            return GetResourceUri(httpContext.Request.Path, httpContext.Request.Method);
        }

        /// <summary>
        /// 获取资源标识
        /// </summary>
        protected virtual string GetResourceUri(string path, string httpMethod)
        {
            if (path.IsEmpty())
                return null;
            var result = $"{path}#{httpMethod}";
            return result.ToLower(CultureInfo.InvariantCulture);
        }
    }

    /// <summary>
    /// 授权中间件结果处理器
    /// </summary>
    public class AclMiddlewareResultHandler : IAuthorizationMiddlewareResultHandler
    {
        /// <summary>
        /// 默认处理器
        /// </summary>
        private readonly AuthorizationMiddlewareResultHandler defaultHandler = new();

        /// <summary>
        /// 处理授权结果
        /// </summary>
        public async Task HandleAsync(RequestDelegate next, HttpContext context, AuthorizationPolicy policy, PolicyAuthorizationResult authorizeResult)
        {
            if (authorizeResult.Succeeded == false)
            {
                var factory = context.RequestServices.GetRequiredService<IUnauthorizedResultFactory>();
                context.Response.StatusCode = factory.HttpStatusCode;
                await context.Response.WriteAsJsonAsync(factory.CreateResult(context));
                return;
            }
            await defaultHandler.HandleAsync(next, context, policy, authorizeResult);
        }
    }

    /// <summary>
    /// 授权辅助操作
    /// </summary>
    public static class AclPolicyHelper
    {
        /// <summary>
        /// 策略前缀
        /// </summary>
        public const string Prefix = "acl_";

        /// <summary>
        /// 获取授权要求
        /// </summary>
        public static AclRequirement GetRequirement(string policy)
        {
            var json = policy.RemoveStart(Prefix);
            return Util.Helpers.Json.ToObject<AclRequirement>(json);
        }

        /// <summary>
        /// 获取授权策略
        /// </summary>
        /// <param name="uri">资源标识</param>
        /// <param name="ignore">是否忽略</param>
        public static string GetPolicy(string uri, bool ignore)
        {
            var requirement = new AclRequirement
            {
                Uri = uri,
                Ignore = ignore
            };
            return $"{Prefix}{Util.Helpers.Json.ToJson(requirement)}";
        }
    }

    /// <summary>
    /// 授权策略提供器
    /// </summary>
    public class AclPolicyProvider : IAuthorizationPolicyProvider
    {
        /// <summary>
        /// 获取授权策略
        /// </summary>
        /// <param name="policyName">授权策略名称</param>
        public Task<AuthorizationPolicy> GetPolicyAsync(string policyName)
        {
            var builder = new AuthorizationPolicyBuilder();
            var requirement = AclPolicyHelper.GetRequirement(policyName);
            builder.AddRequirements(requirement);
            return Task.FromResult(builder.Build());
        }

        /// <summary>
        /// 获取默认授权策略
        /// </summary>
        public Task<AuthorizationPolicy> GetDefaultPolicyAsync()
        {
            return Task.FromResult(new AuthorizationPolicyBuilder().RequireAuthenticatedUser().Build());
        }

        /// <summary>
        /// 获取回退授权策略
        /// </summary>
        public Task<AuthorizationPolicy> GetFallbackPolicyAsync()
        {
            return Task.FromResult<AuthorizationPolicy>(null);
        }
    }

    /// <summary>
    /// 授权要求
    /// </summary>
    public class AclRequirement : IAuthorizationRequirement
    {
        /// <summary>
        /// 是否忽略
        /// </summary>
        public bool Ignore { get; set; }
        /// <summary>
        /// 资源标识
        /// </summary>
        public string Uri { get; set; }
    }

    /// <summary>
    /// 未授权返回结果工厂
    /// </summary>
    public interface IUnauthorizedResultFactory : ISingletonDependency
    {
        /// <summary>
        /// 设置Http状态码
        /// </summary>
        int HttpStatusCode { get; }
        /// <summary>
        /// 创建未授权返回结果
        /// </summary>
        /// <param name="context">Http上下文</param>
        object CreateResult(HttpContext context);
    }

    /// <summary>
    /// 未授权返回结果工厂
    /// </summary>
    public class UnauthorizedResultFactory : IUnauthorizedResultFactory
    {
        /// <inheritdoc />
        public virtual int HttpStatusCode => 200;

        /// <inheritdoc />
        public virtual object CreateResult(HttpContext context)
        {
            return new { Code = StateCode.Unauthorized };
        }
    }

    /// <summary>
    /// 基于数据保护提供程序的加密器
    /// </summary>
    public class DataProtectionEncryptor : IEncryptor
    {
        /// <summary>
        /// 数据保护器
        /// </summary>
        private readonly IDataProtector _dataProtector;

        /// <summary>
        /// 初始化加密器
        /// </summary>
        /// <param name="dataProtector">数据保护器</param>
        public DataProtectionEncryptor(IDataProtector dataProtector)
        {
            _dataProtector = dataProtector ?? throw new ArgumentNullException(nameof(dataProtector));
        }

        /// <inheritdoc />
        public string Encrypt(string data)
        {
            if (data.IsEmpty())
                return null;
            return _dataProtector.Protect(data);
        }

        /// <inheritdoc />
        public string Decrypt(string data)
        {
            if (data.IsEmpty())
                return null;
            return _dataProtector.Unprotect(data);
        }
    }

    /// <summary>
    /// 访问控制
    /// </summary>
    public class AclAttribute : AuthorizeAttribute
    {
        /// <summary>
        /// 是否忽略
        /// </summary>
        private bool _ignore;
        /// <summary>
        /// 资源标识
        /// </summary>
        private string _resourceUri;

        /// <summary>
        /// 初始化访问控制
        /// </summary>
        public AclAttribute()
        {
            Policy = AclPolicyHelper.GetPolicy(null, false);
        }

        /// <summary>
        /// 初始化访问控制
        /// </summary>
        /// <param name="resourceUri">资源标识</param>
        public AclAttribute(string resourceUri)
        {
            ResourceUri = resourceUri;
        }

        /// <summary>
        /// 是否忽略授权检查,设置为true则不验证权限,但仍然需要登录,需要匿名访问请使用AllowAnonymous特性
        /// </summary>
        public bool Ignore
        {
            get
            {
                var requirement = AclPolicyHelper.GetRequirement(Policy);
                return requirement.Ignore;
            }
            set
            {
                _ignore = value;
                Policy = AclPolicyHelper.GetPolicy(_resourceUri, _ignore);
            }
        }

        /// <summary>
        /// 资源标识
        /// </summary>
        public string ResourceUri
        {
            get
            {
                var requirement = AclPolicyHelper.GetRequirement(Policy);
                return requirement.Uri;
            }
            set
            {
                _resourceUri = value;
                Policy = AclPolicyHelper.GetPolicy(_resourceUri, _ignore);
            }
        }
    }

    /// <summary>
    /// 访问控制配置
    /// </summary>
    public class AclOptions
    {
        /// <summary>
        /// 是否允许匿名访问,无需授权,无需登录
        /// </summary>
        public bool AllowAnonymous { get; set; }
        /// <summary>
        /// 是否忽略授权检查,无需授权,但仍需要登录
        /// </summary>
        public bool IgnoreAcl { get; set; }
        /// <summary>
        /// 全局资源标识,未指定资源标识的Api使用该值
        /// </summary>
        public string ResourceUri { get; set; }
    }

