    /// <summary>
    /// AspNetCore操作扩展
    /// </summary>
    public static class AppBuilderExtensions
    {
        /// <summary>
        /// 配置授权访问控制
        /// </summary>
        /// <param name="builder">应用生成器</param>
        public static IAppBuilder AddAcl(this IAppBuilder builder)
        {
            return builder.AddAcl<DefaultPermissionManager>();
        }

        /// <summary>
        /// 配置授权访问控制
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="setupAction">访问控制配置操作</param>
        public static IAppBuilder AddAcl(this IAppBuilder builder, Action<AclOptions> setupAction)
        {
            return builder.AddAcl<DefaultPermissionManager>(setupAction);
        }

        /// <summary>
        /// 配置授权访问控制
        /// </summary>
        /// <typeparam name="TPermissionManager">权限管理器类型</typeparam>
        /// <param name="builder">应用生成器</param>
        public static IAppBuilder AddAcl<TPermissionManager>(this IAppBuilder builder) where TPermissionManager : class, IPermissionManager
        {
            return builder.AddAcl<TPermissionManager, AclMiddlewareResultHandler>();
        }

        /// <summary>
        /// 配置授权访问控制
        /// </summary>
        /// <typeparam name="TPermissionManager">权限管理器类型</typeparam>
        /// <param name="builder">应用生成器</param>
        /// <param name="setupAction">访问控制配置操作</param>
        public static IAppBuilder AddAcl<TPermissionManager>(this IAppBuilder builder, Action<AclOptions> setupAction) where TPermissionManager : class, IPermissionManager
        {
            return builder.AddAcl<TPermissionManager, AclMiddlewareResultHandler>(setupAction);
        }

        /// <summary>
        /// 配置授权访问控制
        /// </summary>
        /// <typeparam name="TPermissionManager">权限管理器类型</typeparam>
        /// <typeparam name="TAuthorizationMiddlewareResultHandler">授权中间件结果处理器类型</typeparam>
        /// <param name="builder">应用生成器</param>
        public static IAppBuilder AddAcl<TPermissionManager, TAuthorizationMiddlewareResultHandler>(this IAppBuilder builder)
            where TPermissionManager : class, IPermissionManager
            where TAuthorizationMiddlewareResultHandler : class, IAuthorizationMiddlewareResultHandler
        {
            return builder.AddAcl<TPermissionManager, TAuthorizationMiddlewareResultHandler>(null);
        }

        /// <summary>
        /// 配置授权访问控制
        /// </summary>
        /// <typeparam name="TPermissionManager">权限管理器类型</typeparam>
        /// <typeparam name="TAuthorizationMiddlewareResultHandler">授权中间件结果处理器类型</typeparam>
        /// <param name="builder">应用生成器</param>
        /// <param name="setupAction">访问控制配置操作</param>
        public static IAppBuilder AddAcl<TPermissionManager, TAuthorizationMiddlewareResultHandler>(this IAppBuilder builder, Action<AclOptions> setupAction)
            where TPermissionManager : class, IPermissionManager
            where TAuthorizationMiddlewareResultHandler : class, IAuthorizationMiddlewareResultHandler
        {
            builder.CheckNull(nameof(builder));
            builder.Host.ConfigureServices((context, services) =>
            {
                services.AddSingleton<IAuthorizationHandler, AclHandler>();
                services.AddSingleton<IAuthorizationPolicyProvider, AclPolicyProvider>();
                services.AddSingleton<IAuthorizationMiddlewareResultHandler, TAuthorizationMiddlewareResultHandler>();
                services.AddSingleton<IPermissionManager, TPermissionManager>();
                if (setupAction != null)
                    services.Configure(setupAction);
            });
            return builder;
        }
    }

    /// <summary>
    /// 身份标识扩展
    /// </summary>
    public static class IdentityExtensions
    {
        /// <summary>
        /// 获取用户标识声明值
        /// </summary>
        /// <param name="identity">用户标识</param>
        /// <param name="type">声明类型</param>
        public static string GetValue(this ClaimsIdentity identity, string type)
        {
            var claim = identity.FindFirst(type);
            if (claim == null)
                return string.Empty;
            return claim.Value;
        }

        /// <summary>
        /// 获取身份标识
        /// </summary>
        /// <param name="context">Http上下文</param>
        public static ClaimsIdentity GetIdentity(this HttpContext context)
        {
            if (context?.User is not { } principal)
                return UnauthenticatedIdentity.Instance;
            if (principal.Identity is ClaimsIdentity identity)
                return identity;
            return UnauthenticatedIdentity.Instance;
        }
    }

    /// <summary>
    /// Web应用生成器扩展
    /// </summary>
    public static class WebApplicationBuilderExtensions
    {
        /// <summary>
        /// 转换为Util应用生成器
        /// </summary>
        /// <param name="builder">Web应用生成器</param>
        public static IAppBuilder AsBuild(this WebApplicationBuilder builder)
        {
            builder.CheckNull(nameof(builder));
            return new AppBuilder(builder.Host);
        }
    }
}

namespace Localization
{
    global using Microsoft.AspNetCore.Builder;
    global using Microsoft.AspNetCore.Localization;
    global using Microsoft.Extensions.Caching.Memory;
    global using Microsoft.Extensions.Configuration;
    global using Microsoft.Extensions.DependencyInjection;
    global using Microsoft.Extensions.DependencyInjection.Extensions;
    global using Microsoft.Extensions.Localization;
    global using Microsoft.Extensions.Logging;
    global using Microsoft.Extensions.Logging.Abstractions;
    global using Microsoft.Extensions.Options;
    global using System;
    global using System.Collections.Concurrent;
    global using System.Collections.Generic;
    global using System.Globalization;
    global using System.IO;
    global using System.Linq;
    global using System.Reflection;
    global using System.Threading.Tasks;

    /// <summary>
    /// 本地化资源查找器
    /// </summary>
    public abstract class StringLocalizerBase : IStringLocalizer
    {
        /// <summary>
        /// 缓存
        /// </summary>
        protected readonly IMemoryCache Cache;
        /// <summary>
        /// 资源类型
        /// </summary>
        protected readonly string Type;
        /// <summary>
        /// 本地化配置
        /// </summary>
        protected LocalizationOptions Options;

        /// <summary>
        /// 初始化本地化资源查找器
        /// </summary>
        /// <param name="cache">缓存</param>
        /// <param name="type">资源类型</param>
        /// <param name="options">本地化配置</param>
        protected StringLocalizerBase(IMemoryCache cache, string type, IOptions<LocalizationOptions> options)
        {
            Cache = cache;
            Type = type;
            Options = options?.Value ?? new LocalizationOptions();
        }

        /// <inheritdoc />
        public LocalizedString this[string name]
        {
            get
            {
                if (name.IsEmpty())
                    throw new ArgumentNullException(nameof(name));
                return GetResult(name);
            }
        }

        /// <inheritdoc />
        public LocalizedString this[string name, params object[] arguments]
        {
            get
            {
                if (name.IsEmpty())
                    throw new ArgumentNullException(nameof(name));
                return GetResult(name, arguments);
            }
        }

        /// <summary>
        /// 获取本地化字符串结果
        /// </summary>
        /// <param name="name">资源名称</param>
        /// <param name="arguments">参数列表</param>
        protected virtual LocalizedString GetResult(string name, params object[] arguments)
        {
            LocalizedString result = null;
            var cultures = Util.Helpers.Culture.GetCurrentUICultures();
            foreach (var culture in cultures)
            {
                result = GetLocalizedStringByCache(culture, name);
                if (result.ResourceNotFound == false)
                    return FormatResult(result, name, arguments);
            }
            return FormatResult(result, name, arguments);
        }

        /// <summary>
        /// 从缓存获取本地化字符串
        /// </summary>
        /// <param name="culture">区域文化</param>
        /// <param name="name">资源名称</param>
        protected virtual LocalizedString GetLocalizedStringByCache(CultureInfo culture, string name)
        {
            var key = CacheHelper.GetCacheKey(culture.Name, Type, name);
            return Cache == null ? GetLocalizedString(culture, name) : Cache.GetOrCreate(key, entry =>
            {
                entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromSeconds(CacheHelper.GetExpiration(Options));
                return GetLocalizedString(culture, name);
            });
        }

        /// <summary>
        /// 获取本地化字符串
        /// </summary>
        /// <param name="culture">区域文化</param>
        /// <param name="name">资源名称</param>
        protected virtual LocalizedString GetLocalizedString(CultureInfo culture, string name)
        {
            var value = GetValue(culture, name, Type);
            if (value.IsEmpty())
                return new LocalizedString(name, string.Empty, true, null);
            return new LocalizedString(name, value, false, null);
        }

        /// <summary>
        /// 获取资源值
        /// </summary>
        /// <param name="culture">区域文化</param>
        /// <param name="name">资源名称</param>
        /// <param name="type">资源类型</param>
        protected abstract string GetValue(CultureInfo culture, string name, string type);

        /// <summary>
        /// 格式化结果
        /// </summary>
        /// <param name="result">本地化字符串结果</param>
        /// <param name="name">资源名称</param>
        /// <param name="arguments">参数列表</param>
        protected virtual LocalizedString FormatResult(LocalizedString result, string name, params object[] arguments)
        {
            if (result == null)
                return new LocalizedString(name, string.Format(name, arguments), true, null);
            if (result.ResourceNotFound)
                return new LocalizedString(result.Name, string.Format(result.Name, arguments), true, null);
            if (arguments == null || arguments.Length == 0)
                return result;
            return new LocalizedString(result.Name, string.Format(result.Value, arguments), false, result.SearchedLocation);
        }

        /// <summary>
        /// 获取全部本地化字符串
        /// </summary>
        /// <param name="includeParentCultures">是否包含父区域</param>
        public abstract IEnumerable<LocalizedString> GetAllStrings(bool includeParentCultures);
    }

    /// <summary>
    /// 缓存辅助操作
    /// </summary>
    internal static class CacheHelper
    {
        /// <summary>
        /// 获取缓存键
        /// </summary>
        /// <param name="culture">区域文化</param>
        /// <param name="type">资源类型</param>
        /// <param name="name">资源名称</param>
        public static string GetCacheKey(string culture, string type, string name)
        {
            return $"{culture}-{type}-{name}";
        }

        /// <summary>
        /// 获取缓存过期时间间隔
        /// </summary>
        public static int GetExpiration(LocalizationOptions options)
        {
            return options.Expiration + Random.Shared.Next(1200);
        }
    }

    #region Json
    /// <summary>
    /// 路径解析器
    /// </summary>
    public interface IPathResolver
    {
        /// <summary>
        /// 获取根命名空间
        /// </summary>
        /// <param name="assembly">资源类型所在的程序集</param>
        string GetRootNamespace(Assembly assembly);
        /// <summary>
        /// 获取资源根目录路径
        /// </summary>
        /// <param name="assembly">资源类型所在的程序集</param>
        /// <param name="rootPath">配置的根路径</param>
        string GetResourcesRootPath(Assembly assembly, string rootPath);
        /// <summary>
        /// 获取资源基名称
        /// </summary>
        /// <param name="assembly">资源类型所在的程序集</param>
        /// <param name="typeFullName">资源类型完全限定名</param>
        string GetResourcesBaseName(Assembly assembly, string typeFullName);
        /// <summary>
        /// 获取Json资源文件绝对路径
        /// </summary>
        /// <param name="rootPath">资源根目录路径</param>
        /// <param name="baseName">资源基名称</param>
        /// <param name="culture">区域文化</param>
        string GetJsonResourcePath(string rootPath, string baseName, CultureInfo culture);
    }

    /// <summary>
    /// Json本地化资源查找器
    /// </summary>
    public class JsonStringLocalizer : StringLocalizerBase
    {
        /// <summary>
        /// 路径解析器
        /// </summary>
        private readonly IPathResolver _pathResolver;
        /// <summary>
        /// 资源根目录路径
        /// </summary>
        private readonly string _resourcesRootPath;
        /// <summary>
        /// 资源基名称
        /// </summary>
        private readonly string _resourcesBaseName;
        /// <summary>
        /// 日志
        /// </summary>
        private readonly ILogger _logger;
        /// <summary>
        /// 资源缓存
        /// </summary>
        private readonly ConcurrentDictionary<string, IEnumerable<KeyValuePair<string, string>>> _resourcesCache;
        /// <summary>
        /// 搜索位置
        /// </summary>
        private readonly string _searchedLocation;

        /// <summary>
        /// 初始化Json本地化资源查找器
        /// </summary>
        /// <param name="pathResolver">路径解析器</param>
        /// <param name="resourcesRootPath">资源根目录路径</param>
        /// <param name="resourcesBaseName">资源基名称</param>
        /// <param name="logger">日志</param>
        /// <param name="cache">缓存</param>
        /// <param name="options">本地化配置</param>
        public JsonStringLocalizer(IPathResolver pathResolver, string resourcesRootPath, string resourcesBaseName, ILogger logger,
            IMemoryCache cache, IOptions<JsonLocalizationOptions> options)
            : base(cache, resourcesBaseName, options)
        {
            _pathResolver = pathResolver;
            _resourcesRootPath = resourcesRootPath;
            _resourcesBaseName = resourcesBaseName;
            _logger = logger ?? NullLogger.Instance;
            _resourcesCache = new ConcurrentDictionary<string, IEnumerable<KeyValuePair<string, string>>>();
            _searchedLocation = $"{resourcesRootPath}.{resourcesBaseName}";
        }

        /// <summary>
        /// 获取本地化字符串
        /// </summary>
        /// <param name="culture">区域文化</param>
        /// <param name="name">资源名称</param>
        protected override LocalizedString GetLocalizedString(CultureInfo culture, string name)
        {
            var value = GetValue(culture, name, _resourcesBaseName) ?? GetValue(culture, name, null);
            if (value.IsEmpty())
                return new LocalizedString(name, string.Empty, true, null);
            return new LocalizedString(name, value, false, _searchedLocation);
        }

        /// <summary>
        /// 获取资源值
        /// </summary>
        /// <param name="culture">区域文化</param>
        /// <param name="name">资源名称</param>
        /// <param name="type">资源类型</param>
        protected override string GetValue(CultureInfo culture, string name, string type)
        {
            var resources = GetResourcesByCache(culture, type);
            if (resources == null)
                return null;
            var resource = resources.SingleOrDefault(t => t.Key == name);
            var result = resource.Value;
            _logger.SearchedLocation(name, _searchedLocation, culture);
            return result;
        }

        /// <summary>
        /// 从缓存获取资源列表
        /// </summary>
        /// <param name="culture">区域文化</param>
        /// <param name="resourcesBaseName">资源基名称</param>
        protected virtual IEnumerable<KeyValuePair<string, string>> GetResourcesByCache(CultureInfo culture, string resourcesBaseName)
        {
            return _resourcesCache.GetOrAdd($"{culture.Name}_{resourcesBaseName}", _ => GetResources(culture, resourcesBaseName));
        }

        /// <summary>
        /// 获取资源列表
        /// </summary>
        /// <param name="culture">区域文化</param>
        /// <param name="resourcesBaseName">资源基名称</param>
        protected virtual IEnumerable<KeyValuePair<string, string>> GetResources(CultureInfo culture, string resourcesBaseName)
        {
            var path = _pathResolver.GetJsonResourcePath(_resourcesRootPath, resourcesBaseName, culture);
            if (File.Exists(path) == false)
            {
                if (resourcesBaseName.IsEmpty())
                    return null;
                path = _pathResolver.GetJsonResourcePath(_resourcesRootPath, resourcesBaseName.Replace('.', Path.DirectorySeparatorChar), culture);
            }
            if (File.Exists(path) == false)
                return null;
            var builder = new ConfigurationBuilder()
                .AddJsonFile(path, optional: false, reloadOnChange: false);
            var config = builder.Build();
            return config.AsEnumerable();
        }

        /// <summary>
        /// 获取全部本地化字符串
        /// </summary>
        /// <param name="includeParentCultures">是否包含父区域</param>
        public override IEnumerable<LocalizedString> GetAllStrings(bool includeParentCultures)
        {
            var result = new List<LocalizedString>();
            var cultures = Util.Helpers.Culture.GetCurrentUICultures();
            foreach (var culture in cultures)
            {
                var resources = ToLocalizedStrings(GetResourcesByCache(culture, _resourcesBaseName));
                result.AddRange(resources);
                if (includeParentCultures == false)
                    return result;
            }
            return result;
        }

        /// <summary>
        /// 转换为LocalizedString集合
        /// </summary>
        protected virtual IEnumerable<LocalizedString> ToLocalizedStrings(IEnumerable<KeyValuePair<string, string>> resources)
        {
            var result = new List<LocalizedString>();
            foreach (var resource in resources)
                result.Add(new LocalizedString(resource.Key, resource.Value, false, _searchedLocation));
            return result;
        }
    }

    /// <summary>
    /// Json本地化资源查找器工厂
    /// </summary>
    public class JsonStringLocalizerFactory : IStringLocalizerFactory
    {
        /// <summary>
        /// 资源根目录路径
        /// </summary>
        private readonly string _rootPath;
        /// <summary>
        /// 路径解析器
        /// </summary>
        private readonly IPathResolver _pathResolver;
        /// <summary>
        /// 日志工厂
        /// </summary>
        private readonly ILoggerFactory _loggerFactory;
        /// <summary>
        /// 缓存
        /// </summary>
        private readonly IMemoryCache _cache;
        /// <summary>
        /// 本地化配置
        /// </summary>
        private readonly IOptions<JsonLocalizationOptions> _options;

        /// <summary>
        /// 初始化Json本地化资源查找器工厂
        /// </summary>
        /// <param name="options">本地化配置</param>
        /// <param name="pathResolver">路径解析器</param>
        /// <param name="loggerFactory">日志工厂</param>
        /// <param name="cache">缓存</param>
        public JsonStringLocalizerFactory(IOptions<JsonLocalizationOptions> options, IPathResolver pathResolver, ILoggerFactory loggerFactory, IMemoryCache cache = null)
        {
            _options = options;
            _rootPath = options.Value.ResourcesPath;
            _pathResolver = pathResolver ?? throw new ArgumentNullException(nameof(pathResolver));
            _loggerFactory = loggerFactory ?? throw new ArgumentNullException(nameof(loggerFactory));
            _cache = cache;
        }

        /// <inheritdoc />
        public IStringLocalizer Create(Type resourceSource)
        {
            resourceSource.CheckNull(nameof(resourceSource));
            var assembly = resourceSource.Assembly;
            var rootPath = _pathResolver.GetResourcesRootPath(assembly, _rootPath);
            var baseName = _pathResolver.GetResourcesBaseName(assembly, resourceSource.FullName);
            return new JsonStringLocalizer(_pathResolver, rootPath, baseName, _loggerFactory.CreateLogger<JsonStringLocalizer>(), _cache, _options);
        }

        /// <inheritdoc />
        public IStringLocalizer Create(string baseName, string location)
        {
            location ??= new AssemblyName(GetType().Assembly.FullName).Name;
            var assemblyName = new AssemblyName(location);
            var assembly = Assembly.Load(assemblyName);
            var rootPath = _pathResolver.GetResourcesRootPath(assembly, _rootPath);
            return new JsonStringLocalizer(_pathResolver, rootPath, baseName, _loggerFactory.CreateLogger<JsonStringLocalizer>(), _cache, _options);
        }
    }

    /// <summary>
    /// Json本地化日志扩展
    /// </summary>
    internal static class JsonStringLocalizerLoggerExtensions
    {
        private static readonly Action<ILogger, string, string, CultureInfo, Exception> _searchedLocation;

        static JsonStringLocalizerLoggerExtensions()
        {
            _searchedLocation = LoggerMessage.Define<string, string, CultureInfo>(
                LogLevel.Debug,
                1,
                $"{nameof(JsonStringLocalizer)} searched for '{{Key}}' in '{{LocationSearched}}' with culture '{{Culture}}'.");
        }

        public static void SearchedLocation(this ILogger logger, string key, string searchedLocation, CultureInfo culture)
        {
            _searchedLocation(logger, key, searchedLocation, culture, null);
        }
    }

    /// <summary>
    /// 路径解析器
    /// </summary>
    public class PathResolver : IPathResolver
    {
        /// <inheritdoc />
        public string GetRootNamespace(Assembly assembly)
        {
            assembly.CheckNull(nameof(assembly));
            var attribute = assembly.GetCustomAttribute<RootNamespaceAttribute>();
            return attribute == null ? assembly.GetName().Name : attribute.RootNamespace;
        }

        /// <inheritdoc />
        public string GetResourcesRootPath(Assembly assembly, string rootPath)
        {
            if (assembly == null)
                return rootPath;
            var attribute = assembly.GetCustomAttribute<ResourceLocationAttribute>();
            return attribute == null ? rootPath : attribute.ResourceLocation;
        }

        /// <inheritdoc />
        public string GetResourcesBaseName(Assembly assembly, string typeFullName)
        {
            var rootNamespace = GetRootNamespace(assembly);
            return typeFullName.RemoveStart($"{rootNamespace}.");
        }

        /// <inheritdoc />
        public string GetJsonResourcePath(string rootPath, string baseName, CultureInfo culture)
        {
            if (baseName.IsEmpty())
                return Path.Combine(Common.ApplicationBaseDirectory, rootPath, $"{culture.Name}.json");
            baseName = FixInnerClassPath(baseName);
            return Path.Combine(Common.ApplicationBaseDirectory, rootPath, $"{baseName}.{culture.Name}.json");
        }

        /// <summary>
        /// 修复内部类分隔符+
        /// </summary>
        private string FixInnerClassPath(string path)
        {
            const char innerClassSeparator = '+';
            return path.Contains(innerClassSeparator) ? path.Replace(innerClassSeparator, '.') : path;
        }
    }
    #endregion

    #region Store
    /// <summary>
    /// 本地化资源管理器
    /// </summary>
    public interface ILocalizedManager
    {
        /// <summary>
        /// 加载全部本地化资源
        /// </summary>
        void LoadAllResources();
        /// <summary>
        /// 加载全部本地化资源
        /// </summary>
        /// <param name="culture">区域文化,范例: zh-CN</param>
        void LoadAllResources(string culture);
        /// <summary>
        /// 加载全部本地化资源
        /// </summary>
        /// <param name="culture">区域文化,范例: zh-CN</param>
        /// <param name="type">资源类型</param>
        void LoadAllResources(string culture, string type);
        /// <summary>
        /// 加载指定类型的本地化资源
        /// </summary>
        /// <param name="type">资源类型</param>
        void LoadResourcesByType(string type);
    }

    /// <summary>
    /// 本地化资源存储器
    /// </summary>
    public interface ILocalizedStore
    {
        /// <summary>
        /// 获取本地化资源值,未查找到资源返回null
        /// </summary>
        /// <param name="culture">区域文化,范例: zh-CN</param>
        /// <param name="type">资源类型</param>
        /// <param name="name">资源名称</param>
        string GetValue(string culture, string type, string name);
        /// <summary>
        /// 获取区域文化列表
        /// </summary>
        IList<string> GetCultures();
        /// <summary>
        /// 获取资源类型列表
        /// </summary>
        IList<string> GetTypes();
        /// <summary>
        /// 获取本地化资源集合
        /// </summary>
        /// <param name="culture">区域文化,范例: zh-CN</param>
        /// <param name="type">资源类型</param>
        IDictionary<string, string> GetResources(string culture, string type);
    }

    /// <summary>
    /// 本地化资源管理器
    /// </summary>
    public class LocalizedManager : ILocalizedManager
    {
        /// <summary>
        /// 本地化资源存储器
        /// </summary>
        private readonly ILocalizedStore _store;
        /// <summary>
        /// 缓存
        /// </summary>
        private readonly IMemoryCache _cache;
        /// <summary>
        /// 本地化配置
        /// </summary>
        private readonly LocalizationOptions _options;

        /// <summary>
        /// 初始化本地化资源管理器
        /// </summary>
        /// <param name="store">本地化资源存储器</param>
        /// <param name="cache">缓存</param>
        /// <param name="options">本地化配置</param>
        public LocalizedManager(ILocalizedStore store, IMemoryCache cache, IOptions<LocalizationOptions> options)
        {
            _store = store ?? throw new ArgumentNullException(nameof(store));
            _cache = cache ?? throw new ArgumentNullException(nameof(cache));
            _options = options?.Value ?? new LocalizationOptions();
        }

        /// <inheritdoc />
        public virtual void LoadAllResources()
        {
            var cultures = GetCultures();
            foreach (var culture in cultures)
                LoadAllResources(culture);
        }

        /// <summary>
        /// 获取区域文化列表
        /// </summary>
        protected virtual List<string> GetCultures()
        {
            var result = new List<string> {
            Util.Helpers.Culture.GetCurrentUICultureName()
        };
            var cultures = _store.GetCultures();
            if (cultures is { Count: > 0 })
                result.AddRange(cultures);
            return result.Distinct().ToList();
        }

        /// <inheritdoc />
        public virtual void LoadAllResources(string culture)
        {
            if (culture.IsEmpty())
                return;
            var types = _store.GetTypes();
            if (types == null || types.Count == 0)
            {
                LoadAllResources(culture, null);
                return;
            }
            foreach (var type in types)
                LoadAllResources(culture, type);
        }

        /// <inheritdoc />
        public virtual void LoadAllResources(string culture, string type)
        {
            if (culture.IsEmpty())
                return;
            var resources = _store.GetResources(culture, type);
            if (resources == null)
                return;
            foreach (var resource in resources)
                LoadResourceCache(culture, type, resource.Key, resource.Value);
        }

        /// <summary>
        /// 加载资源缓存
        /// </summary>
        protected virtual void LoadResourceCache(string culture, string type, string name, string value)
        {
            var cacheKey = CacheHelper.GetCacheKey(culture, type, name);
            var localizedString = new LocalizedString(name, value, false, null);
            _cache.Set(cacheKey, localizedString, TimeSpan.FromSeconds(CacheHelper.GetExpiration(_options)));
        }

        /// <inheritdoc />
        public void LoadResourcesByType(string type)
        {
            var cultures = GetCultures();
            foreach (var culture in cultures)
                LoadAllResources(culture, type);
        }
    }

    /// <summary>
    /// 数据存储本地化资源查找器
    /// </summary>
    public class StoreStringLocalizer : StringLocalizerBase
    {
        /// <summary>
        /// 日志
        /// </summary>
        private readonly ILogger _logger;
        /// <summary>
        /// 本地化资源存储器
        /// </summary>
        private readonly ILocalizedStore _store;

        /// <summary>
        /// 初始化数据存储本地化资源查找器
        /// </summary>
        /// <param name="logger">日志</param>
        /// <param name="cache">缓存</param>
        /// <param name="store">本地化资源存储器</param>
        /// <param name="type">资源类型</param>
        /// <param name="options">本地化配置</param>
        public StoreStringLocalizer(ILogger logger, IMemoryCache cache, ILocalizedStore store, string type, IOptions<LocalizationOptions> options) : base(cache, type, options)
        {
            _logger = logger ?? NullLogger.Instance;
            _store = store ?? throw new ArgumentNullException(nameof(store));
        }

        /// <summary>
        /// 获取本地化字符串结果
        /// </summary>
        /// <param name="name">资源名称</param>
        /// <param name="arguments">参数列表</param>
        protected override LocalizedString GetResult(string name, params object[] arguments)
        {
            var culture = Util.Helpers.Culture.GetCurrentUICulture();
            var result = GetLocalizedStringByCache(culture, name);
            return FormatResult(result, name, arguments);
        }

        /// <summary>
        /// 获取资源值
        /// </summary>
        /// <param name="culture">区域文化</param>
        /// <param name="name">资源名称</param>
        /// <param name="type">资源类型</param>
        protected override string GetValue(CultureInfo culture, string name, string type)
        {
            var result = _store.GetValue(culture.Name, type, name);
            _logger.Searched(name, type, culture);
            return result;
        }

        /// <inheritdoc />
        public override IEnumerable<LocalizedString> GetAllStrings(bool includeParentCultures)
        {
            var result = new List<LocalizedString>();
            var cultures = Helpers.Culture.GetCurrentUICultures();
            foreach (var culture in cultures)
            {
                var resources = GetAllStrings(culture.Name);
                result.AddRange(resources);
                if (includeParentCultures == false)
                    return result;
            }
            return result;
        }

        /// <summary>
        /// 获取全部本地化字符串
        /// </summary>
        /// <param name="culture">区域文化</param>
        protected virtual IEnumerable<LocalizedString> GetAllStrings(string culture)
        {
            var result = new List<LocalizedString>();
            var types = _store.GetTypes();
            if (types == null || types.Count == 0)
            {
                result.AddRange(GetAllStrings(culture, null));
                return result;
            }
            foreach (var type in types)
                result.AddRange(GetAllStrings(culture, type));
            return result;
        }

        /// <summary>
        /// 获取全部本地化字符串
        /// </summary>
        /// <param name="culture">区域文化</param>
        /// <param name="type">资源类型</param>
        protected virtual IEnumerable<LocalizedString> GetAllStrings(string culture, string type)
        {
            var resources = _store.GetResources(culture, type);
            if (resources == null)
                return new List<LocalizedString>();
            return ToLocalizedStrings(resources);
        }

        /// <summary>
        /// 转换为LocalizedString集合
        /// </summary>
        protected virtual IEnumerable<LocalizedString> ToLocalizedStrings(IEnumerable<KeyValuePair<string, string>> resources)
        {
            var result = new List<LocalizedString>();
            foreach (var resource in resources)
                result.Add(new LocalizedString(resource.Key, resource.Value, false, null));
            return result;
        }
    }

    /// <summary>
    /// 数据存储本地化资源查找器工厂
    /// </summary>
    public class StoreStringLocalizerFactory : IStringLocalizerFactory
    {
        /// <summary>
        /// 日志工厂
        /// </summary>
        private readonly ILoggerFactory _loggerFactory;
        /// <summary>
        /// 本地化资源存储器
        /// </summary>
        private readonly ILocalizedStore _store;
        /// <summary>
        /// 缓存
        /// </summary>
        private readonly IMemoryCache _cache;
        /// <summary>
        /// 本地化配置
        /// </summary>
        private readonly IOptions<LocalizationOptions> _options;

        /// <summary>
        /// 初始化数据存储本地化资源查找器工厂
        /// </summary>
        /// <param name="options">本地化配置</param>
        /// <param name="loggerFactory">日志工厂</param>
        /// <param name="store">本地化资源存储器</param>
        /// <param name="cache">缓存</param>
        public StoreStringLocalizerFactory(IOptions<LocalizationOptions> options, ILoggerFactory loggerFactory, ILocalizedStore store, IMemoryCache cache)
        {
            _options = options;
            _loggerFactory = loggerFactory ?? throw new ArgumentNullException(nameof(loggerFactory));
            _store = store ?? throw new ArgumentNullException(nameof(store));
            _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        }

        /// <inheritdoc />
        public IStringLocalizer Create(Type resourceSource)
        {
            resourceSource.CheckNull(nameof(resourceSource));
            var type = LocalizedTypeAttribute.GetResourceType(resourceSource);
            return new StoreStringLocalizer(_loggerFactory.CreateLogger<StoreStringLocalizer>(), _cache, _store, type, _options);
        }

        /// <inheritdoc />
        public IStringLocalizer Create(string baseName, string location)
        {
            return new StoreStringLocalizer(_loggerFactory.CreateLogger<StoreStringLocalizer>(), _cache, _store, baseName, _options);
        }
    }

    /// <summary>
    /// 数据存储本地化日志扩展
    /// </summary>
    internal static class StoreStringLocalizerLoggerExtensions
    {
        private static readonly Action<ILogger, string, string, CultureInfo, Exception> _searched;

        static StoreStringLocalizerLoggerExtensions()
        {
            _searched = LoggerMessage.Define<string, string, CultureInfo>(
                LogLevel.Debug,
                1,
                $"{nameof(StoreStringLocalizer)} 查找名为 '{{Key}}'的本地化资源, 资源类型为 '{{Type}}',区域文化为 '{{Culture}}'.");
        }

        public static void Searched(this ILogger logger, string key, string type, CultureInfo culture)
        {
            _searched(logger, key, type, culture, null);
        }
    }
    #endregion

    /// <summary>
    /// 本地化操作扩展
    /// </summary>
    public static class AppBuilderExtensions
    {

        #region AddJsonLocalization

        /// <summary>
        /// 配置Json本地化
        /// </summary>
        /// <param name="builder">应用生成器</param>
        public static IAppBuilder AddJsonLocalization(this IAppBuilder builder)
        {
            return builder.AddJsonLocalization("Resources");
        }

        /// <summary>
        /// 配置Json本地化
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="resourcesPath">资源路径,默认值: Resources</param>
        public static IAppBuilder AddJsonLocalization(this IAppBuilder builder, string resourcesPath)
        {
            return builder.AddJsonLocalization(t => t.ResourcesPath = resourcesPath);
        }

        /// <summary>
        /// 配置Json本地化
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="setupAction">Json本地化配置操作</param>
        public static IAppBuilder AddJsonLocalization(this IAppBuilder builder, Action<JsonLocalizationOptions> setupAction)
        {
            builder.CheckNull(nameof(builder));
            var options = new JsonLocalizationOptions();
            setupAction?.Invoke(options);
            builder.Host.ConfigureServices((context, services) =>
            {
                if (setupAction != null)
                {
                    services.Configure(setupAction);
                    void Action(LocalizationOptions localizationOptions)
                    {
                        localizationOptions.Expiration = options.Expiration;
                        localizationOptions.IsLocalizeWarning = options.IsLocalizeWarning;
                        localizationOptions.Cultures = options.Cultures;
                    }
                    services.Configure((Action<LocalizationOptions>)Action);
                }
                services.AddMemoryCache();
                services.RemoveAll(typeof(IStringLocalizerFactory));
                services.RemoveAll(typeof(IStringLocalizer<>));
                services.RemoveAll(typeof(IStringLocalizer));
                services.TryAddSingleton<IPathResolver, PathResolver>();
                services.TryAddSingleton<IStringLocalizerFactory, JsonStringLocalizerFactory>();
                services.TryAddTransient(typeof(IStringLocalizer<>), typeof(StringLocalizer<>));
                services.TryAddTransient(typeof(IStringLocalizer), typeof(StringLocalizer));
            });
            if (options.Cultures == null || options.Cultures.Count == 0)
                return builder;
            builder.Host.ConfigureServices((_, services) =>
            {
                ConfigRequestLocalization(services, options);
            });
            return builder;
        }

        /// <summary>
        /// 配置请求本地化
        /// </summary>
        private static void ConfigRequestLocalization(IServiceCollection services, LocalizationOptions options)
        {
            services.Configure<RequestLocalizationOptions>(localizationOptions =>
            {
                var supportedCultures = options.Cultures.Select(culture => new CultureInfo(culture)).ToList();
                localizationOptions.DefaultRequestCulture = new RequestCulture(culture: supportedCultures[0], uiCulture: supportedCultures[0]);
                localizationOptions.SupportedCultures = supportedCultures;
                localizationOptions.SupportedUICultures = supportedCultures;
                localizationOptions.AddInitialRequestCultureProvider(new CustomRequestCultureProvider(async context =>
                {
                    var culture = context.Request.Headers.ContentLanguage.FirstOrDefault();
                    if (culture.IsEmpty())
                        culture = "zh-CN";
                    return await Task.FromResult(new ProviderCultureResult(culture));
                }));
            });
        }

        #endregion

        #region AddStoreLocalization

        /// <summary>
        /// 配置基于数据存储的本地化
        /// </summary>
        /// <param name="builder">应用生成器</param>
        public static IAppBuilder AddStoreLocalization<TStore>(this IAppBuilder builder) where TStore : ILocalizedStore
        {
            return builder.AddStoreLocalization<TStore>(options => options.Expiration = 28800);
        }

        /// <summary>
        /// 配置基于数据存储的本地化
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="setupAction">本地化配置操作</param>
        public static IAppBuilder AddStoreLocalization<TStore>(this IAppBuilder builder, Action<LocalizationOptions> setupAction) where TStore : ILocalizedStore
        {
            builder.CheckNull(nameof(builder));
            var options = new LocalizationOptions();
            setupAction?.Invoke(options);
            builder.Host.ConfigureServices((context, services) =>
            {
                if (setupAction != null)
                    services.Configure(setupAction);
                services.AddMemoryCache();
                services.RemoveAll(typeof(IStringLocalizerFactory));
                services.RemoveAll(typeof(IStringLocalizer<>));
                services.RemoveAll(typeof(IStringLocalizer));
                services.TryAddSingleton<IStringLocalizerFactory, StoreStringLocalizerFactory>();
                services.TryAddTransient(typeof(IStringLocalizer<>), typeof(StringLocalizer<>));
                services.TryAddTransient(typeof(IStringLocalizer), typeof(StringLocalizer));
                services.TryAddTransient(typeof(ILocalizedStore), typeof(TStore));
                services.TryAddTransient<ILocalizedManager, LocalizedManager>();
            });
            builder.Host.ConfigureServices((_, services) =>
            {
                if (options.Cultures == null || options.Cultures.Count == 0)
                    return;
                ConfigRequestLocalization(services, options);
            });
            return builder;
        }

        #endregion
    }

    /// <summary>
    /// Json本地化配置
    /// </summary>
    public class JsonLocalizationOptions : LocalizationOptions
    {
        /// <summary>
        /// 初始化Json本地化配置
        /// </summary>
        public JsonLocalizationOptions()
        {
            ResourcesPath = "Resources";
        }

        /// <summary>
        /// 资源路径
        /// </summary>
        public string ResourcesPath { get; set; }
    }

    /// <summary>
    /// 本地化配置
    /// </summary>
    public class LocalizationOptions
    {
        /// <summary>
        /// 初始化本地化配置
        /// </summary>
        public LocalizationOptions()
        {
            Cultures = new List<string>();
        }

        /// <summary>
        /// 语言文化
        /// </summary>
        public IList<string> Cultures { get; set; }

        /// <summary>
        /// 缓存过期时间间隔,单位: 秒 ,默认值: 28800
        /// </summary>
        public int Expiration { get; set; } = 28800;

        /// <summary>
        /// 是否本地化Warning异常消息,默认值: false
        /// </summary>
        public bool IsLocalizeWarning { get; set; }
    }

    /// <summary>
    /// 本地化资源类型
    /// </summary>
    public class LocalizedTypeAttribute : Attribute
    {
        /// <summary>
        /// 本地化资源类型
        /// </summary>
        public string Type { get; }

        /// <summary>
        /// 初始化本地化资源类型
        /// </summary>
        /// <param name="type">本地化资源类型</param>
        public LocalizedTypeAttribute(string type)
        {
            Type = type;
        }

        /// <summary>
        /// 获取本地化资源类型,如果未设置则返回类型名
        /// </summary>
        /// <typeparam name="T">类型</typeparam>
        public static string GetResourceType<T>()
        {
            return GetResourceType(typeof(T));
        }

        /// <summary>
        /// 获取本地化资源类型,如果未设置则返回类型名
        /// </summary>
        /// <param name="type">类型</param>
        public static string GetResourceType(Type type)
        {
            if (type == null)
                return null;
            var attribute = type.GetCustomAttribute<LocalizedTypeAttribute>();
            return attribute == null || attribute.Type.IsEmpty() ? type.Name : attribute.Type;
        }
    }

    /// <summary>
    /// 本地化资源查找器
    /// </summary>
    public class NullStringLocalizer : IStringLocalizer
    {
        /// <summary>
        /// 本地化资源查找器空实例
        /// </summary>
        public static readonly IStringLocalizer Instance = new NullStringLocalizer();

        /// <inheritdoc />
        public LocalizedString this[string name] => new(name, name, true);

        /// <inheritdoc />
        public LocalizedString this[string name, params object[] arguments]
        {
            get
            {
                var value = string.Format(name, arguments);
                return new LocalizedString(value, value, true);
            }
        }

        /// <inheritdoc />
        public IEnumerable<LocalizedString> GetAllStrings(bool includeParentCultures) => new List<LocalizedString>();
    }

    /// <summary>
    /// 本地化资源查找器
    /// </summary>
    internal class StringLocalizer : IStringLocalizer
    {
        /// <summary>
        /// 本地化资源查找器
        /// </summary>
        private readonly IStringLocalizer _localizer;

        /// <summary>
        /// 初始化本地化资源查找器
        /// </summary>
        /// <param name="factory">本地化资源查找器工厂</param>
        public StringLocalizer(IStringLocalizerFactory factory)
        {
            var assemblyName = new AssemblyName(GetType().Assembly.FullName!);
            _localizer = factory.Create(string.Empty, assemblyName.FullName);
        }

        /// <inheritdoc />
        public LocalizedString this[string name] => _localizer[name];

        /// <inheritdoc />
        public LocalizedString this[string name, params object[] arguments] => _localizer[name, arguments];

        /// <inheritdoc />
        public IEnumerable<LocalizedString> GetAllStrings(bool includeParentCultures) => _localizer.GetAllStrings(includeParentCultures);
    }
}

namespace IdGenerator
{
    global using NanoidDotNet;
    global using System;
    global using System.Threading;
    global using System.Threading.Tasks;
    global using Yitter.IdGenerator;

    /// <summary>
    /// 标识生成器
    /// </summary>
    public static partial class Id
    {
        /// <summary>
        /// 标识
        /// </summary>
        private static readonly AsyncLocal<string> _id = new();

        /// <summary>
        /// 设置标识
        /// </summary>
        /// <param name="id">标识</param>
        public static void SetId(string id)
        {
            _id.Value = id;
        }

        /// <summary>
        /// 重置标识
        /// </summary>
        public static void Reset()
        {
            _id.Value = null;
        }

        /// <summary>
        /// 使用去掉分隔符的Guid创建标识
        /// </summary>
        public static string Create()
        {
            return string.IsNullOrEmpty(_id.Value) ? System.Guid.NewGuid().ToString("N") : _id.Value;
        }

        /// <summary>
        /// 创建Guid标识
        /// </summary>
        public static Guid CreateGuid()
        {
            return string.IsNullOrEmpty(_id.Value) ? System.Guid.NewGuid() : _id.Value.ToGuid();
        }
    }

    /// <summary>
    /// 标识生成器
    /// </summary>
    public static partial class Id
    {
        /// <summary>
        /// 使用 YitIdHelper 雪花漂移算法创建标识
        /// </summary>
        public static long CreateYitId()
        {
            if (string.IsNullOrEmpty(_id.Value) == false)
                return Convert.ToLong(_id.Value);
            try
            {
                return YitIdHelper.NextId();
            }
            catch
            {
                var options = new IdGeneratorOptions(1);
                YitIdHelper.SetIdGenerator(options);
                return YitIdHelper.NextId();
            }
        }
    }

    /// <summary>
    /// 标识生成器
    /// </summary>
    public static partial class Id
    {
        /// <summary>
        /// 使用 Nanoid 创建标识,返回 21 个字符的标识.
        /// </summary>
        public static string CreateNanoid()
        {
            return CreateNanoid(21);
        }

        /// <summary>
        /// 使用 Nanoid 创建标识,返回 21 个字符的标识.
        /// </summary>
        public static async Task<string> CreateNanoidAsync()
        {
            return await CreateNanoidAsync(21);
        }

        /// <summary>
        /// 使用 Nanoid 创建标识
        /// </summary>
        /// <param name="size">字符数</param>
        public static string CreateNanoid(int size)
        {
            return CreateNanoid(null, size);
        }

        /// <summary>
        /// 使用 Nanoid 创建标识
        /// </summary>
        /// <param name="size">字符数</param>
        public static async Task<string> CreateNanoidAsync(int size)
        {
            return await CreateNanoidAsync(null, size);
        }

        /// <summary>
        /// 使用 Nanoid 创建标识
        /// </summary>
        /// <param name="alphabet">可选字符,范例 abcd</param>
        public static string CreateNanoid(string alphabet)
        {
            return CreateNanoid(alphabet, 21);
        }

        /// <summary>
        /// 使用 Nanoid 创建标识
        /// </summary>
        /// <param name="alphabet">可选字符,范例 abcd</param>
        public static async Task<string> CreateNanoidAsync(string alphabet)
        {
            return await CreateNanoidAsync(alphabet, 21);
        }

        /// <summary>
        /// 使用 Nanoid 创建标识
        /// </summary>
        /// <param name="alphabet">可选字符,范例 abcd</param>
        /// <param name="size">字符数</param>
        public static string CreateNanoid(string alphabet, int size)
        {
            if (string.IsNullOrEmpty(_id.Value) == false)
                return _id.Value;
            if (string.IsNullOrEmpty(alphabet))
                return Nanoid.Generate(size: size);
            return Nanoid.Generate(alphabet, size);
        }

        /// <summary>
        /// 使用 Nanoid 创建标识
        /// </summary>
        /// <param name="alphabet">可选字符,范例 abcd</param>
        /// <param name="size">字符数</param>
        public static async Task<string> CreateNanoidAsync(string alphabet, int size)
        {
            if (string.IsNullOrEmpty(_id.Value) == false)
                return _id.Value;
            if (string.IsNullOrEmpty(alphabet))
                return await Nanoid.GenerateAsync(size: size);
            return await Nanoid.GenerateAsync(alphabet, size);
        }

        /// <summary>
        /// 使用 Nanoid 创建标识
        /// </summary>
        /// <param name="random">随机数</param>
        /// <param name="alphabet">可选字符,范例 abcd</param>
        /// <param name="size">字符数</param>
        public static string CreateNanoid(System.Random random, string alphabet = "_-0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ", int size = 21)
        {
            if (string.IsNullOrEmpty(_id.Value) == false)
                return _id.Value;
            return Nanoid.Generate(random, alphabet, size);
        }
    }
}

namespace Logging
{
    global using Exceptionless;
    global using Microsoft.Extensions.Configuration;
    global using Microsoft.Extensions.DependencyInjection;
    global using Microsoft.Extensions.Logging;
    global using Serilog;
    global using Serilog.Configuration;
    global using Serilog.Core;
    global using Serilog.Events;
    global using System;
    global using System.Collections.Generic;
    global using System.Diagnostics;
    global using System.Text;

    #region Logging
    /// <summary>
    /// 日志操作
    /// </summary>
    /// <typeparam name="TCategoryName">日志类别</typeparam>
    public interface ILog<out TCategoryName> : ILog
    {
    }

    /// <summary>
    /// 日志操作
    /// </summary>
    public interface ILog
    {
        /// <summary>
        /// 设置日志事件标识
        /// </summary>
        /// <param name="eventId">日志事件标识</param>
        ILog EventId(EventId eventId);
        /// <summary>
        /// 设置异常
        /// </summary>
        /// <param name="exception">异常</param>
        ILog Exception(Exception exception);
        /// <summary>
        /// 设置自定义扩展属性
        /// </summary>
        /// <param name="propertyName">属性名</param>
        /// <param name="propertyValue">属性值</param>
        ILog Property(string propertyName, string propertyValue);
        /// <summary>
        /// 设置日志状态对象
        /// </summary>
        /// <param name="state">状态对象</param>
        ILog State(object state);
        /// <summary>
        /// 设置日志消息
        /// </summary>
        /// <param name="message">日志消息</param>
        /// <param name="args">日志消息参数</param>
        ILog Message(string message, params object[] args);
        /// <summary>
        /// 是否启用
        /// </summary>
        /// <param name="logLevel">日志级别</param>
        bool IsEnabled(LogLevel logLevel);
        /// <summary>
        /// 开启日志范围
        /// </summary>
        /// <typeparam name="TState">日志状态类型</typeparam>
        /// <param name="state">日志状态</param>
        IDisposable BeginScope<TState>(TState state);
        /// <summary>
        /// 写跟踪日志
        /// </summary>
        ILog LogTrace();
        /// <summary>
        /// 写调试日志
        /// </summary>
        ILog LogDebug();
        /// <summary>
        /// 写信息日志
        /// </summary>
        ILog LogInformation();
        /// <summary>
        /// 写警告日志
        /// </summary>
        ILog LogWarning();
        /// <summary>
        /// 写错误日志
        /// </summary>
        ILog LogError();
        /// <summary>
        /// 写致命日志
        /// </summary>
        ILog LogCritical();
    }

    /// <summary>
    /// 日志上下文访问器
    /// </summary>
    public interface ILogContextAccessor
    {
        /// <summary>
        /// 日志上下文
        /// </summary>
        LogContext Context { get; set; }
    }

    /// <summary>
    /// 日志操作扩展
    /// </summary>
    public static class ILogExtensions
    {
        /// <summary>
        /// 添加消息
        /// </summary>
        /// <param name="log">配置项</param>
        /// <param name="message">消息</param>
        /// <param name="args">日志消息参数</param>
        public static ILog Append(this ILog log, string message, params object[] args)
        {
            log.CheckNull(nameof(log));
            log.Message(message, args);
            return log;
        }

        /// <summary>
        /// 当条件为true添加消息
        /// </summary>
        /// <param name="log">配置项</param>
        /// <param name="message">消息</param>
        /// <param name="condition">条件,值为true则添加消息</param>
        /// <param name="args">日志消息参数</param>
        public static ILog AppendIf(this ILog log, string message, bool condition, params object[] args)
        {
            log.CheckNull(nameof(log));
            if (condition)
                log.Message(message, args);
            return log;
        }

        /// <summary>
        /// 添加消息并换行
        /// </summary>
        /// <param name="log">配置项</param>
        /// <param name="message">消息</param>
        /// <param name="args">日志消息参数</param>
        public static ILog AppendLine(this ILog log, string message, params object[] args)
        {
            log.CheckNull(nameof(log));
            log.Message(message, args);
            log.Message(Environment.NewLine);
            return log;
        }

        /// <summary>
        /// 当条件为true添加消息并换行
        /// </summary>
        /// <param name="log">配置项</param>
        /// <param name="message">消息</param>
        /// <param name="condition">条件,值为true则添加消息</param>
        /// <param name="args">日志消息参数</param>
        public static ILog AppendLineIf(this ILog log, string message, bool condition, params object[] args)
        {
            log.CheckNull(nameof(log));
            if (condition)
            {
                log.Message(message, args);
                log.Message(Environment.NewLine);
            }
            return log;
        }

        /// <summary>
        /// 消息换行
        /// </summary>
        /// <param name="log">配置项</param>
        public static ILog Line(this ILog log)
        {
            log.CheckNull(nameof(log));
            log.Message(Environment.NewLine);
            return log;
        }
    }

    /// <summary>
    /// 日志操作工厂
    /// </summary>
    public interface ILogFactory
    {
        /// <summary>
        /// 创建日志操作
        /// </summary>
        /// <param name="categoryName">日志类别</param>
        ILog CreateLog(string categoryName);
        /// <summary>
        /// 创建日志操作
        /// </summary>
        /// <param name="type">日志类别类型</param>
        ILog CreateLog(Type type);
    }

    /// <summary>
    /// 日志记录包装器
    /// </summary>
    public interface ILoggerWrapper
    {
        /// <summary>
        /// 是否启用
        /// </summary>
        /// <param name="logLevel">日志级别</param>
        bool IsEnabled(LogLevel logLevel);
        /// <summary>写日志</summary>
        /// <param name="logLevel">日志级别</param>
        /// <param name="eventId">日志事件标识</param>
        /// <param name="state">日志状态对象</param>
        /// <param name="exception">异常</param>
        /// <param name="formatter">消息格式化操作</param>
        /// <typeparam name="TState">日志状态类型</typeparam>
        void Log<TState>(LogLevel logLevel, EventId eventId, TState state, Exception exception, Func<TState, Exception, string> formatter);
        /// <summary>
        /// 创建日志范围
        /// </summary>
        /// <param name="state">日志状态</param>
        /// <typeparam name="TState">日志状态类型</typeparam>
        IDisposable BeginScope<TState>(TState state);
        /// <summary>
        /// 写跟踪日志
        /// </summary>
        /// <param name="eventId">日志事件标识</param>
        /// <param name="exception">异常</param>
