        /// <param name="exception">异常</param>
        /// <param name="message">日志消息</param>
        /// <param name="args">日志消息参数</param>
        void LogDebug(EventId eventId, Exception exception, string message, params object[] args);
        /// <summary>
        /// 写信息日志
