        }

        /// <summary>
        /// 添加日志级别扩展属性
        /// </summary>
        /// <param name="source">日志扩展配置</param>
        public static LoggerConfiguration WithLogLevel(this LoggerEnrichmentConfiguration source)
        {
            source.CheckNull(nameof(source));
            return source.With<LogLevelEnricher>();
        }
    }

