    /// <summary>
    /// 本地事件总线服务注册器
    /// </summary>
    public class LocalEventBusServiceRegistrar : IServiceRegistrar
    {
        /// <summary>
        /// 获取服务名
        /// </summary>
        public static string ServiceName => "Util.Events.Infrastructure.LocalEventBusServiceRegistrar";

        /// <summary>
        /// 排序号
        /// </summary>
        public int OrderId => 510;

        /// <summary>
        /// 是否启用
        /// </summary>
        public bool Enabled => ServiceRegistrarConfig.IsEnabled(ServiceName);

        /// <summary>
        /// 注册服务
        /// </summary>
        /// <param name="serviceContext">服务上下文</param>
        public Action Register(ServiceContext serviceContext)
        {
            serviceContext.HostBuilder.ConfigureServices((context, services) =>
            {
                RegisterDependency(services);
                RegisterEventHandlers(services, serviceContext.TypeFinder);
            });
            return null;
        }

        /// <summary>
        /// 注册依赖
        /// </summary>
        private void RegisterDependency(IServiceCollection services)
        {
            services.TryAddTransient<ILocalEventBus, LocalEventBus>();
        }

        /// <summary>
        /// 注册事件处理器
        /// </summary>
        private void RegisterEventHandlers(IServiceCollection services, ITypeFinder finder)
        {
            Type handlerType = typeof(IEventHandler<>);
            var handlerTypes = GetTypes(finder, handlerType);
            foreach (var handler in handlerTypes)
            {
                var serviceTypes = handler.FindInterfaces((filter, criteria) => criteria != null && filter.IsGenericType && ((Type)criteria).IsAssignableFrom(filter.GetGenericTypeDefinition()), handlerType);
                serviceTypes.ToList().ForEach(serviceType => services.AddScoped(serviceType, handler));
            }
        }

        /// <summary>
        /// 获取类型集合
        /// </summary>
        private Type[] GetTypes(ITypeFinder finder, Type type)
        {
            return finder.Find(type).ToArray();
        }
    }

    /// <summary>
    /// 本地事件总线服务注册器配置扩展
    /// </summary>
    public static class ServiceRegistrarConfigExtensions
    {
        /// <summary>
        /// 启用本地事件总线服务注册器
        /// </summary>
        /// <param name="config">服务注册器配置</param>
        public static ServiceRegistrarConfig EnableLocalEventBusServiceRegistrar(this ServiceRegistrarConfig config)
        {
            ServiceRegistrarConfig.Enable(LocalEventBusServiceRegistrar.ServiceName);
            return config;
        }

        /// <summary>
        ///禁用本地事件总线服务注册器
        /// </summary>
        /// <param name="config">服务注册器配置</param>
        public static ServiceRegistrarConfig DisableLocalEventBusServiceRegistrar(this ServiceRegistrarConfig config)
        {
            ServiceRegistrarConfig.Disable(LocalEventBusServiceRegistrar.ServiceName);
            return config;
        }
    }

    /// <summary>
    /// 本地事件处理器基类
    /// </summary>
    /// <typeparam name="TEvent">事件类型</typeparam>
    public abstract class EventHandlerBase<TEvent> : IEventHandler<TEvent>, ILocalEventHandler where TEvent : IEvent
    {
        /// <summary>
        /// 处理事件
        /// </summary>
        /// <param name="event">事件</param>
        /// <param name="cancellationToken">取消令牌</param>
        public abstract Task HandleAsync(TEvent @event, CancellationToken cancellationToken);

        /// <summary>
        /// 序号
        /// </summary>
        public virtual int Order => 0;

        /// <summary>
        /// 是否启用
        /// </summary>
        public virtual bool Enabled => true;
    }

    /// <summary>
    /// 本地事件处理器
    /// </summary>
    public interface ILocalEventHandler : IEventHandler
    {
        /// <summary>
        /// 序号
        /// </summary>
        int Order { get; }
    }

    /// <summary>
    /// 基于内存的本地事件总线
    /// </summary>
    public class LocalEventBus : ILocalEventBus
    {
        /// <summary>
        /// 服务提供器
        /// </summary>
        private readonly IServiceProvider _serviceProvider;

        /// <summary>
        /// 初始化本地事件总线
        /// </summary>
        /// <param name="serviceProvider">服务提供器</param>
        public LocalEventBus(IServiceProvider serviceProvider)
        {
            _serviceProvider = serviceProvider ?? throw new ArgumentNullException(nameof(serviceProvider));
        }

        /// <inheritdoc />
        public async Task PublishAsync<TEvent>(TEvent @event, CancellationToken cancellationToken = default) where TEvent : IEvent
        {
            cancellationToken.ThrowIfCancellationRequested();
            if (@event == null)
                return;
            await PublishLocalEventAsync(@event, cancellationToken);
        }

        /// <summary>
        /// 发布本地事件
        /// </summary>
        private async Task PublishLocalEventAsync<TEvent>(TEvent @event, CancellationToken cancellationToken) where TEvent : IEvent
        {
            var eventType = @event.GetType();
            var handlers = GetEventHandlers(eventType);
            if (handlers == null)
                return;
            foreach (var handler in handlers.Where(t => t is { Enabled: true }).OrderBy(t => t.Order))
            {
                var method = typeof(IEventHandler<>).MakeGenericType(eventType).GetMethod("HandleAsync", new[] { eventType, typeof(CancellationToken) });
                if (method == null)
                    return;
                var result = method.Invoke(handler, new object[] { @event, cancellationToken });
                if (result == null)
                    return;
                await (Task)result;
            }
        }

        /// <summary>
        /// 获取事件处理器列表
        /// </summary>
        private IEnumerable<ILocalEventHandler> GetEventHandlers(Type eventType)
        {
            var handlerType = typeof(IEventHandler<>).MakeGenericType(eventType);
            var serviceType = typeof(IEnumerable<>).MakeGenericType(handlerType);
            var handlers = _serviceProvider.GetService(serviceType);
            if (handlers is not IEnumerable<IEventHandler> eventHandlers)
                yield break;
            foreach (var handler in eventHandlers)
                yield return handler as ILocalEventHandler;
        }
    }
    #endregion

