    #region Filter
    /// <summary>
    /// 模型过滤器,对模板中的@model进行替换
    /// </summary>
    public class ModelFilter : ITemplateFilter
    {
        /// <summary>
        /// 过滤模板
        /// </summary>
        /// <param name="template">模板字符串</param>
        public string Filter(string template)
        {
            return Util.Helpers.Regex.Replace(template, @"@model\s+(\w+)", "@inherits RazorEngineCore.RazorEngineTemplateBase<$1>");
        }
    }

    /// <summary>
    /// 部分视图过滤器,移除模板中的await
    /// </summary>
    public class PartialAsyncFilter : ITemplateFilter
    {
        /// <summary>
        /// 过滤模板
        /// </summary>
        /// <param name="template">模板字符串</param>
        public string Filter(string template)
        {
            return Util.Helpers.Regex.Replace(template, @"await\s+Html.PartialAsync", "Html.PartialAsync");
        }
    }
    #endregion

