        public void SaveToStream(Stream stream)
        {
            this.SaveToStreamAsync(stream).GetAwaiter().GetResult();
        }

        public Task SaveToStreamAsync(Stream stream)
        {
            return this.assemblyByteCode.CopyToAsync(stream);
        }

        public void SaveToFile(string fileName)
        {
            this.SaveToFileAsync(fileName).GetAwaiter().GetResult();
        }

        public Task SaveToFileAsync(string fileName)
        {
            using (FileStream fileStream = new FileStream(
                       path: fileName,
                       mode: FileMode.CreateNew,
                       access: FileAccess.Write,
                       share: FileShare.None,
                       bufferSize: 4096,
                       useAsync: true))
            {
                return assemblyByteCode.CopyToAsync(fileStream);
            }
        }

        public string Run(Action<T> initializer)
        {
            return this.RunAsync(initializer).GetAwaiter().GetResult();
        }

        public async Task<string> RunAsync(Action<T> initializer)
        {
            T instance = (T)Activator.CreateInstance(this.templateType);
            initializer(instance);

            await instance.ExecuteAsync();

            return instance.Result();
        }
    }

    public class RazorEngineException : Exception
    {
        public RazorEngineException()
        {
        }

        protected RazorEngineException(SerializationInfo info, StreamingContext context) : base(info, context)
        {
        }

        public RazorEngineException(string message) : base(message)
        {
        }

        public RazorEngineException(string message, Exception innerException) : base(message, innerException)
        {
        }
    }

    public abstract class RazorEngineTemplateBase : IRazorEngineTemplate
    {
        private readonly StringBuilder stringBuilder = new StringBuilder();

        private string attributeSuffix = null;

        public dynamic Model { get; set; }

        public HtmlHelper Html { get; set; }

        public virtual void WriteLiteral(string literal = null)
        {
            this.stringBuilder.Append(literal);
        }

        public virtual void Write(object obj = null)
        {
            this.stringBuilder.Append(obj);
        }

        public virtual void BeginWriteAttribute(string name, string prefix, int prefixOffset, string suffix, int suffixOffset, int attributeValuesCount)
        {
            this.attributeSuffix = suffix;
            this.stringBuilder.Append(prefix);
        }

        public virtual void WriteAttributeValue(string prefix, int prefixOffset, object value, int valueOffset, int valueLength, bool isLiteral)
        {
            this.stringBuilder.Append(prefix);
            this.stringBuilder.Append(value);
        }

        public virtual void EndWriteAttribute()
        {
            this.stringBuilder.Append(this.attributeSuffix);
            this.attributeSuffix = null;
        }

        public virtual Task ExecuteAsync()
        {
            return Task.CompletedTask;
        }

        public virtual string Result()
        {
            return this.stringBuilder.ToString();
        }
    }

    public abstract class RazorEngineTemplateBase<T> : RazorEngineTemplateBase
    {
        public new T Model { get; set; }
    }
    #endregion

    #region Templates.Handlebars
    /// <summary>
    /// Handlebars模板引擎
    /// </summary>
    public class HandlebarsTemplateEngine : IHandlebarsTemplateEngine
    {
        /// <summary>
        /// 模板缓存
        /// </summary>
        protected static readonly ConcurrentDictionary<int, HandlebarsTemplate<object, object>> TemplateCache = new();
        /// <summary>
        /// 文本编码器
        /// </summary>
        private ITextEncoder _encoder;

        /// <summary>
        /// 清除缓存
        /// </summary>
        public static void ClearCache()
        {
            TemplateCache.Clear();
        }

        /// <summary>
        /// 设置文本编码器
        /// </summary>
        /// <param name="encoder">文本编码器</param>
        public IHandlebarsTemplateEngine Encoder(ITextEncoder encoder)
        {
            _encoder = encoder;
            return this;
        }

        /// <summary>
        /// 设置 Html 编码器
        /// </summary>
        public IHandlebarsTemplateEngine HtmlEncoder()
        {
            return Encoder(new HtmlEncoder());
        }

        /// <summary>
        /// 渲染模板
        /// </summary>
        /// <param name="template">模板字符串</param>
        /// <param name="data">模板数据</param>
        public virtual string Render(string template, object data = null)
        {
            if (string.IsNullOrWhiteSpace(template))
                return null;
            var compiledTemplate = GetCompiledTemplateFromCache(template);
            return compiledTemplate?.Invoke(data);
        }

        /// <summary>
        /// 从缓存中获取已编译模板
        /// </summary>
        protected virtual HandlebarsTemplate<object, object> GetCompiledTemplateFromCache(string template)
        {
            return TemplateCache.GetOrAdd(template.GetHashCode(), _ =>
            {
                var handlebars = Handlebars.Create();
                handlebars.Configuration.TextEncoder = _encoder;
                return handlebars.Compile(template);
            });
        }

        /// <summary>
        /// 渲染模板
        /// </summary>
        /// <param name="template">模板字符串</param>
        /// <param name="data">模板数据</param>
        public virtual Task<string> RenderAsync(string template, object data = null)
        {
            return Task.FromResult(Render(template, data));
        }
    }

    /// <summary>
    /// Handlebars模板引擎
    /// </summary>
    public interface IHandlebarsTemplateEngine : ITemplateEngine
    {
        /// <summary>
        /// 设置文本编码器
        /// </summary>
        /// <param name="encoder">文本编码器</param>
        IHandlebarsTemplateEngine Encoder(ITextEncoder encoder);
        /// <summary>
        /// 设置 Html 编码器
        /// </summary>
        IHandlebarsTemplateEngine HtmlEncoder();
    }

    /// <summary>
    /// Handlebars模板引擎服务注册器
    /// </summary>
    public class HandlebarsServiceRegistrar : IServiceRegistrar
    {
        /// <summary>
        /// 获取服务名
        /// </summary>
        public static string ServiceName => "Util.Templates.Infrastructure.HandlebarsServiceRegistrar";

        /// <summary>
        /// 排序号
        /// </summary>
        public int OrderId => 620;

        /// <summary>
        /// 是否启用
        /// </summary>
        public bool Enabled => ServiceRegistrarConfig.IsEnabled(ServiceName);

        /// <summary>
        /// 注册服务
        /// </summary>
        /// <param name="serviceContext">服务上下文</param>
        public Action Register(ServiceContext serviceContext)
        {
            serviceContext.HostBuilder.ConfigureServices((context, services) =>
            {
                services.AddSingleton<ITemplateEngine, HandlebarsTemplateEngine>();
                services.AddSingleton<IHandlebarsTemplateEngine, HandlebarsTemplateEngine>();
            });
            return null;
        }
    }

    /// <summary>
    /// Handlebars模板引擎服务注册器配置扩展
    /// </summary>
    public static class ServiceRegistrarConfigExtensions
    {
        /// <summary>
        /// 启用Handlebars模板引擎服务注册器
        /// </summary>
        /// <param name="config">服务注册器配置</param>
        public static ServiceRegistrarConfig EnableHandlebarsServiceRegistrar(this ServiceRegistrarConfig config)
        {
            ServiceRegistrarConfig.Enable(HandlebarsServiceRegistrar.ServiceName);
            return config;
        }

        /// <summary>
        ///禁用Handlebars模板引擎服务注册器
        /// </summary>
        /// <param name="config">服务注册器配置</param>
        public static ServiceRegistrarConfig DisableHandlebarsServiceRegistrar(this ServiceRegistrarConfig config)
        {
            ServiceRegistrarConfig.Disable(HandlebarsServiceRegistrar.ServiceName);
            return config;
        }
    }

    #endregion
}

namespace Caching
{
    global using AspectCore.DynamicProxy;
    global using EasyCaching.Bus.Redis;
    global using EasyCaching.Core;
    global using EasyCaching.Core.Configurations;
    global using EasyCaching.Core.Interceptor;
    global using EasyCaching.HybridCache;
    global using EasyCaching.InMemory;
    global using EasyCaching.Redis;
    global using EasyCaching.Serialization.SystemTextJson.Configurations;
    global using Microsoft.Extensions.Configuration;
    global using Microsoft.Extensions.DependencyInjection;
    global using Microsoft.Extensions.DependencyInjection.Extensions;
    global using System;
    global using System.Collections.Generic;
    global using System.Linq;
    global using System.Reflection;
    global using System.Text.Json.Serialization;
    global using System.Threading;
    global using System.Threading.Tasks;

    #region Caching
    /// <summary>
    /// 缓存拦截器
    /// </summary>
    public class CacheAttribute : InterceptorBase
    {
        /// <summary>
        /// 缓存键前缀,可使用占位符, {0} 表示第一个参数值,范例: User-{0}
        /// </summary>
        public string Prefix { get; set; }
        /// <summary>
        /// 缓存过期间隔,单位:秒,默认值:36000
        /// </summary>
        public int Expiration { get; set; } = 36000;

        /// <summary>
        /// 执行
        /// </summary>
        public override async Task Invoke(AspectContext context, AspectDelegate next)
        {
            var cache = GetCache(context);
            var returnType = GetReturnType(context);
            var key = CreateCacheKey(context);
            var value = await GetCacheValue(cache, returnType, key);
            if (value != null)
            {
                SetReturnValue(context, returnType, value);
                return;
            }
            await next(context);
            await SetCache(context, cache, key);
        }

        /// <summary>
        /// 获取缓存服务
        /// </summary>
        protected virtual ICache GetCache(AspectContext context)
        {
            return context.ServiceProvider.GetService<ICache>();
        }

        /// <summary>
        /// 获取返回类型
        /// </summary>
        private Type GetReturnType(AspectContext context)
        {
            return context.IsAsync() ? context.ServiceMethod.ReturnType.GetGenericArguments().First() : context.ServiceMethod.ReturnType;
        }

        /// <summary>
        /// 创建缓存键
        /// </summary>
        private string CreateCacheKey(AspectContext context)
        {
            var keyGenerator = context.ServiceProvider.GetService<ICacheKeyGenerator>();
            return keyGenerator.CreateCacheKey(context.ServiceMethod, context.Parameters, GetPrefix(context));
        }

        /// <summary>
        /// 获取缓存键前缀
        /// </summary>
        private string GetPrefix(AspectContext context)
        {
            try
            {
                return string.Format(Prefix, context.Parameters.ToArray());
            }
            catch
            {
                return Prefix;
            }
        }

        /// <summary>
        /// 获取缓存值
        /// </summary>
        private async Task<object> GetCacheValue(ICache cache, Type returnType, string key)
        {
            return await cache.GetAsync(key, returnType);
        }

        /// <summary>
        /// 设置返回值
        /// </summary>
        private void SetReturnValue(AspectContext context, Type returnType, object value)
        {
            if (context.IsAsync())
            {
                context.ReturnValue = typeof(Task).GetMethods()
                    .First(p => p.Name == "FromResult" && p.ContainsGenericParameters)
                    .MakeGenericMethod(returnType).Invoke(null, new[] { value });
                return;
            }
            context.ReturnValue = value;
        }

        /// <summary>
        /// 设置缓存
        /// </summary>
        private async Task SetCache(AspectContext context, ICache cache, string key)
        {
            var options = new CacheOptions { Expiration = TimeSpan.FromSeconds(Expiration) };
            var returnValue = context.IsAsync() ? await context.UnwrapAsyncReturnValue() : context.ReturnValue;
            await cache.SetAsync(key, returnValue, options);
        }
    }

    /// <summary>
    /// 缓存键
    /// </summary>
    public class CacheKey
    {
        /// <summary>
        /// 缓存键
        /// </summary>
        private string _key;

        /// <summary>
        /// 初始化缓存键
        /// </summary>
        public CacheKey()
        {
        }

        /// <summary>
        /// 初始化缓存键
        /// </summary>
        /// <param name="key">缓存键</param>
        /// <param name="parameters">缓存键参数</param>
        public CacheKey(string key, params object[] parameters)
        {
            _key = string.Format(key, parameters);
        }

        /// <summary>
        /// 缓存键
        /// </summary>
        public string Key
        {
            get => ToString();
            set => _key = value;
        }

        /// <summary>
        /// 缓存键前缀
        /// </summary>
        public string Prefix { get; set; }

        /// <summary>
        /// 获取缓存键
        /// </summary>
        public override string ToString()
        {
            return $"{Prefix}{_key}";
        }
    }

    /// <summary>
    /// 缓存键扩展
    /// </summary>
    public static class CacheKeyExtensions
    {
        /// <summary>
        /// 验证缓存键
        /// </summary>
        /// <param name="cacheKey">缓存键</param>
        public static void Validate(this CacheKey cacheKey)
        {
            cacheKey.CheckNull(nameof(cacheKey));
            cacheKey.Key.CheckNull(nameof(cacheKey.Key));
        }
    }

    /// <summary>
    /// 缓存配置
    /// </summary>
    public class CacheOptions
    {
        /// <summary>
        /// 过期时间间隔,默认值: 8小时
        /// </summary>
        public TimeSpan? Expiration { get; set; }
    }

