    #region EasyCaching
    /// <summary>
    /// EasyCaching缓存操作扩展
    /// </summary>
    public static class AppBuilderExtensions
    {

        #region 字段

        /// <summary>
        /// 最大随机秒数
        /// </summary>
        public static int MaxRdSecond = 1200;

        #endregion

        #region AddMemoryCache

        /// <summary>
        /// 配置EasyCaching内存缓存操作
        /// </summary>
        /// <param name="builder">应用生成器</param>
        public static IAppBuilder AddMemoryCache(this IAppBuilder builder)
        {
            return builder.AddMemoryCache(options =>
            {
                options.MaxRdSecond = MaxRdSecond;
                options.CacheNulls = true;
            });
        }

        /// <summary>
        /// 配置EasyCaching内存缓存操作
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="configuration">配置</param>
        /// <param name="section">配置节名称,默认值: "EasyCaching:Memory"</param>
        public static IAppBuilder AddMemoryCache(this IAppBuilder builder, IConfiguration configuration, string section = "EasyCaching:Memory")
        {
            builder.CheckNull(nameof(builder));
            builder.Host.ConfigureServices((context, services) =>
            {
                ConfigCommonService(services);
                services.TryAddSingleton<ILocalCache, MemoryCacheManager>();
                services.AddEasyCaching(options => options.UseInMemory(configuration, CacheProviderKey.MemoryCache, section));
            });
            return builder;
        }

        /// <summary>
        /// 配置公共服务
        /// </summary>
        private static void ConfigCommonService(IServiceCollection services)
        {
            services.TryAddSingleton<ICache, CacheManager>();
            services.TryAddSingleton<ICacheKeyGenerator, CacheKeyGenerator>();
            services.TryAddSingleton<IEasyCachingKeyGenerator, DefaultEasyCachingKeyGenerator>();
        }

        /// <summary>
        /// 配置EasyCaching内存缓存操作
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="setupAction">内存缓存配置操作</param>
        public static IAppBuilder AddMemoryCache(this IAppBuilder builder, Action<InMemoryOptions> setupAction)
        {
            builder.CheckNull(nameof(builder));
            builder.Host.ConfigureServices((context, services) =>
            {
                ConfigCommonService(services);
                services.TryAddSingleton<ILocalCache, MemoryCacheManager>();
                services.AddEasyCaching(options => options.UseInMemory(setupAction));
            });
            return builder;
        }

        #endregion

        #region AddRedisCache

        /// <summary>
        /// 配置EasyCaching Redis缓存操作
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="host">Redis服务地址,范例: 127.0.0.1</param>
        /// <param name="port">Redis服务端口,默认值: 6379</param>
        /// <param name="keyPrefix">缓存键前缀,默认值: null</param>
        public static IAppBuilder AddRedisCache(this IAppBuilder builder, string host, int port = 6379, string keyPrefix = null)
        {
            return builder.AddRedisCache(options =>
            {
                options.MaxRdSecond = MaxRdSecond;
                options.CacheNulls = true;
                options.DBConfig.AllowAdmin = true;
                options.DBConfig.KeyPrefix = keyPrefix;
                options.DBConfig.Endpoints.Add(new ServerEndPoint(host, port));
            });
        }

        /// <summary>
        /// 配置EasyCaching Redis缓存操作
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="configuration">配置</param>
        /// <param name="section">配置节名称,默认值: "EasyCaching:Redis"</param>
        public static IAppBuilder AddRedisCache(this IAppBuilder builder, IConfiguration configuration, string section = "EasyCaching:Redis")
        {
            builder.CheckNull(nameof(builder));
            CachingOptions.AddRedisEndPoints(configuration, section);
            builder.Host.ConfigureServices((context, services) =>
            {
                ConfigCommonService(services);
                services.TryAddSingleton<IRedisCache, RedisCacheManager>();
                services.AddEasyCaching(options =>
                {
                    var serializerNameKey = $"{section}:SerializerName";
                    var serializerName = configuration[serializerNameKey];
                    if (serializerName.IsEmpty())
                        configuration[serializerNameKey] = CacheProviderKey.SystemTextJson;
                    options.UseRedis(configuration, CacheProviderKey.RedisCache, section);
                    ConfigRedisSerializer(options);
                });
            });
            return builder;
        }

        /// <summary>
        /// 配置Redis序列化
        /// </summary>
        private static void ConfigRedisSerializer(EasyCachingOptions options)
        {
            options.WithSystemTextJson(t => t.DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull, CacheProviderKey.SystemTextJson);
        }

        /// <summary>
        /// 配置EasyCaching Redis缓存操作
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="setupAction">Redis缓存配置操作</param>
        public static IAppBuilder AddRedisCache(this IAppBuilder builder, Action<RedisOptions> setupAction)
        {
            builder.CheckNull(nameof(builder));
            CachingOptions.AddRedisEndPoints(setupAction);
            builder.Host.ConfigureServices((context, services) =>
            {
                ConfigCommonService(services);
                services.TryAddSingleton<IRedisCache, RedisCacheManager>();
                services.AddEasyCaching(options =>
                {
                    ConfigRedisSerializer(options);
                    options.UseRedis(redisOptions =>
                    {
                        redisOptions.SerializerName = CacheProviderKey.SystemTextJson;
                        setupAction(redisOptions);
                    });
                });
            });
            return builder;
        }

        #endregion

        #region AddHybridCache

        /// <summary>
        /// 配置EasyCaching 2级缓存操作
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="topicName">订阅主题,默认值: "EasyCachingHybridCache"</param>
        public static IAppBuilder AddHybridCache(this IAppBuilder builder, string topicName = "EasyCachingHybridCache")
        {
            return builder.AddHybridCache(hybridOptions =>
            {
                hybridOptions.LocalCacheProviderName = CacheProviderKey.MemoryCache;
                hybridOptions.DistributedCacheProviderName = CacheProviderKey.RedisCache;
                hybridOptions.TopicName = topicName;
            }, redisBusOptions =>
            {
                CachingOptions.GetRedisEndPoints().ForEach(endpoint =>
                {
                    redisBusOptions.Endpoints.Add(endpoint);
                });
                redisBusOptions.SerializerName = CacheProviderKey.SystemTextJson;
            });
        }

        /// <summary>
        /// 配置EasyCaching 2级缓存操作
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="configuration">配置</param>
        /// <param name="hybridSection">2级缓存配置节名称,默认值: "EasyCaching:Hybrid"</param>
        /// <param name="redisBusSection">Redis总线配置节名称,默认值: "EasyCaching:RedisBus"</param>
        public static IAppBuilder AddHybridCache(this IAppBuilder builder, IConfiguration configuration,
                string hybridSection = "EasyCaching:Hybrid", string redisBusSection = "EasyCaching:RedisBus")
        {
            builder.CheckNull(nameof(builder));
            builder.Host.ConfigureServices((context, services) =>
            {
                services.AddEasyCaching(options =>
                {
                    options.UseHybrid(configuration, CacheProviderKey.HybridCache, hybridSection);
                    options.WithRedisBus(configuration, CacheProviderKey.RedisBus, redisBusSection);
                });
            });
            return builder;
        }

        /// <summary>
        /// 配置EasyCaching 2级缓存操作
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="hybridConfigAction">2缓存配置操作</param>
        /// <param name="redisBusConfigAction">Redis总线配置操作</param>
        public static IAppBuilder AddHybridCache(this IAppBuilder builder, Action<HybridCachingOptions> hybridConfigAction, Action<RedisBusOptions> redisBusConfigAction)
        {
            builder.CheckNull(nameof(builder));
            builder.Host.ConfigureServices((context, services) =>
            {
                services.AddEasyCaching(options =>
                {
                    options.UseHybrid(hybridConfigAction);
                    options.WithRedisBus(redisBusConfigAction);
                });
            });
            return builder;
        }

        #endregion
    }

    /// <summary>
    /// 缓存键生成器
    /// </summary>
    public class CacheKeyGenerator : ICacheKeyGenerator
    {
        /// <summary>
        /// EasyCaching缓存键生成器
        /// </summary>
        private readonly IEasyCachingKeyGenerator _keyGenerator;

        /// <summary>
        /// 初始化缓存键生成器
        /// </summary>
        /// <param name="keyGenerator">EasyCaching缓存键生成器</param>
        public CacheKeyGenerator(IEasyCachingKeyGenerator keyGenerator)
        {
            _keyGenerator = keyGenerator ?? throw new ArgumentNullException(nameof(keyGenerator));
        }

        /// <inheritdoc />
        public string CreateCacheKey(MethodInfo methodInfo, object[] args, string prefix)
        {
            return _keyGenerator.GetCacheKey(methodInfo, args, prefix);
        }
    }

    /// <summary>
    /// EasyCaching缓存服务
    /// </summary>
    public class CacheManager : ICache
    {

        #region 字段

        /// <summary>
        /// 缓存提供器
        /// </summary>
        private readonly IEasyCachingProviderBase _provider;
        /// <summary>
        /// 缓存提供器
        /// </summary>
        private readonly IEasyCachingProvider _cachingProvider;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化EasyCaching缓存服务
        /// </summary>
        /// <param name="provider">EasyCaching缓存提供器</param>
        /// <param name="hybridProvider">EasyCaching 2级缓存提供器</param>
        public CacheManager(IEasyCachingProvider provider, IHybridCachingProvider hybridProvider = null)
        {
            CachingOptions.Clear();
            if (provider != null)
            {
                _provider = provider;
                _cachingProvider = provider;
            }
            if (hybridProvider != null)
                _provider = hybridProvider;
            _provider.CheckNull(nameof(provider));
        }

        #endregion

        #region Exists

        /// <inheritdoc />
        public bool Exists(CacheKey key)
        {
            key.Validate();
            return Exists(key.Key);
        }

        /// <inheritdoc />
        public bool Exists(string key)
        {
            return _provider.Exists(key);
        }

        #endregion

        #region ExistsAsync

        /// <inheritdoc />
        public async Task<bool> ExistsAsync(CacheKey key, CancellationToken cancellationToken = default)
        {
            key.Validate();
            return await ExistsAsync(key.Key, cancellationToken);
        }

        /// <inheritdoc />
        public async Task<bool> ExistsAsync(string key, CancellationToken cancellationToken = default)
        {
            return await _provider.ExistsAsync(key, cancellationToken);
        }

        #endregion

        #region Get

        /// <inheritdoc />
        public T Get<T>(CacheKey key)
        {
            key.Validate();
            return Get<T>(key.Key);
        }

        /// <inheritdoc />
        public T Get<T>(string key)
        {
            var result = _provider.Get<T>(key);
            return result.Value;
        }

        /// <inheritdoc />
        public List<T> Get<T>(IEnumerable<CacheKey> keys)
        {
            return Get<T>(ToKeys(keys));
        }

        /// <summary>
        /// 转换为缓存键字符串集合
        /// </summary>
        private IEnumerable<string> ToKeys(IEnumerable<CacheKey> keys)
        {
            keys.CheckNull(nameof(keys));
            var cacheKeys = keys.ToList();
            cacheKeys.ForEach(t => t.Validate());
            return cacheKeys.Select(t => t.Key);
        }

        /// <inheritdoc />
        public List<T> Get<T>(IEnumerable<string> keys)
        {
            Validate();
            var result = _cachingProvider.GetAll<T>(keys);
            return result.Values.Select(t => t.Value).ToList();
        }

        /// <summary>
        /// 验证
        /// </summary>
        private void Validate()
        {
            if (_cachingProvider == null)
                throw new NotSupportedException("2级缓存不支持该操作");
        }

        /// <inheritdoc />
        public T Get<T>(CacheKey key, Func<T> action, CacheOptions options = null)
        {
            key.Validate();
            return Get(key.Key, action, options);
        }

        /// <inheritdoc />
        public T Get<T>(string key, Func<T> action, CacheOptions options = null)
        {
            var result = _provider.Get(key, action, GetExpiration(options));
            return result.Value;
        }

        /// <summary>
        /// 获取过期时间间隔
        /// </summary>
        private TimeSpan GetExpiration(CacheOptions options)
        {
            var result = options?.Expiration;
            result ??= TimeSpan.FromHours(8);
            return result.SafeValue();
        }

        #endregion

        #region GetAsync

        /// <inheritdoc />
        public async Task<object> GetAsync(string key, Type type, CancellationToken cancellationToken = default)
        {
            return await _provider.GetAsync(key, type, cancellationToken);
        }

        /// <inheritdoc />
        public async Task<T> GetAsync<T>(CacheKey key, CancellationToken cancellationToken = default)
        {
            key.Validate();
            return await GetAsync<T>(key.Key, cancellationToken);
        }

        /// <inheritdoc />
        public async Task<T> GetAsync<T>(string key, CancellationToken cancellationToken = default)
        {
            var result = await _provider.GetAsync<T>(key, cancellationToken);
            return result.Value;
        }

        /// <inheritdoc />
        public async Task<List<T>> GetAsync<T>(IEnumerable<CacheKey> keys, CancellationToken cancellationToken = default)
        {
            return await GetAsync<T>(ToKeys(keys), cancellationToken);
        }

        /// <inheritdoc />
        public async Task<List<T>> GetAsync<T>(IEnumerable<string> keys, CancellationToken cancellationToken = default)
        {
            Validate();
            var result = await _cachingProvider.GetAllAsync<T>(keys, cancellationToken);
            return result.Values.Select(t => t.Value).ToList();
        }

        /// <inheritdoc />
        public async Task<T> GetAsync<T>(CacheKey key, Func<Task<T>> action, CacheOptions options = null, CancellationToken cancellationToken = default)
        {
            key.Validate();
            return await GetAsync(key.Key, action, options, cancellationToken);
        }

        /// <inheritdoc />
        public async Task<T> GetAsync<T>(string key, Func<Task<T>> action, CacheOptions options = null, CancellationToken cancellationToken = default)
        {
            var result = await _provider.GetAsync(key, action, GetExpiration(options), cancellationToken);
            return result.Value;
        }

        #endregion

        #region GetByPrefix

        /// <inheritdoc />
        public List<T> GetByPrefix<T>(string prefix)
        {
            if (prefix.IsEmpty())
                return new List<T>();
            Validate();
            return _cachingProvider.GetByPrefix<T>(prefix).Where(t => t.Value.HasValue).Select(t => t.Value.Value).ToList();
        }

        #endregion

        #region GetByPrefixAsync

        /// <inheritdoc />
        public async Task<List<T>> GetByPrefixAsync<T>(string prefix, CancellationToken cancellationToken = default)
        {
            if (prefix.IsEmpty())
                return new List<T>();
            Validate();
            var result = await _cachingProvider.GetByPrefixAsync<T>(prefix, cancellationToken);
            return result.Where(t => t.Value.HasValue).Select(t => t.Value.Value).ToList();
        }

        #endregion

        #region TrySet

        /// <inheritdoc />
        public bool TrySet<T>(CacheKey key, T value, CacheOptions options = null)
        {
            key.Validate();
            return TrySet(key.Key, value, options);
        }

        /// <inheritdoc />
        public bool TrySet<T>(string key, T value, CacheOptions options = null)
        {
            return _provider.TrySet(key, value, GetExpiration(options));
        }

        #endregion

        #region TrySetAsync

        /// <inheritdoc />
        public async Task<bool> TrySetAsync<T>(CacheKey key, T value, CacheOptions options = null, CancellationToken cancellationToken = default)
        {
            key.Validate();
            return await TrySetAsync(key.Key, value, options, cancellationToken);
        }

        /// <inheritdoc />
        public async Task<bool> TrySetAsync<T>(string key, T value, CacheOptions options = null, CancellationToken cancellationToken = default)
        {
            return await _provider.TrySetAsync(key, value, GetExpiration(options), cancellationToken);
        }

        #endregion

        #region Set

        /// <inheritdoc />
        public void Set<T>(CacheKey key, T value, CacheOptions options = null)
        {
            key.Validate();
            Set(key.Key, value, options);
        }

        /// <inheritdoc />
        public void Set<T>(string key, T value, CacheOptions options = null)
        {
            _provider.Set(key, value, GetExpiration(options));
        }

        /// <inheritdoc />
        public void Set<T>(IDictionary<CacheKey, T> items, CacheOptions options = null)
        {
            Set(ToItems(items), options);
        }

        /// <summary>
        /// 转换为缓存项集合
        /// </summary>
        private IDictionary<string, T> ToItems<T>(IDictionary<CacheKey, T> items)
        {
            items.CheckNull(nameof(items));
            return items.Select(item =>
            {
                item.Key.Validate();
                return new KeyValuePair<string, T>(item.Key.Key, item.Value);
            }).ToDictionary(t => t.Key, t => t.Value);
        }

        /// <inheritdoc />
        public void Set<T>(IDictionary<string, T> items, CacheOptions options = null)
        {
            _provider.SetAll(items, GetExpiration(options));
        }

        #endregion

        #region SetAsync

        /// <inheritdoc />
        public async Task SetAsync<T>(CacheKey key, T value, CacheOptions options = null, CancellationToken cancellationToken = default)
        {
            key.Validate();
            await SetAsync(key.Key, value, options, cancellationToken);
        }

        /// <inheritdoc />
        public async Task SetAsync<T>(string key, T value, CacheOptions options = null, CancellationToken cancellationToken = default)
        {
            await _provider.SetAsync(key, value, GetExpiration(options), cancellationToken);
        }

        /// <inheritdoc />
        public async Task SetAsync<T>(IDictionary<CacheKey, T> items, CacheOptions options = null, CancellationToken cancellationToken = default)
        {
            await SetAsync(ToItems(items), options, cancellationToken);
        }

        /// <inheritdoc />
        public async Task SetAsync<T>(IDictionary<string, T> items, CacheOptions options = null, CancellationToken cancellationToken = default)
        {
            await _provider.SetAllAsync(items, GetExpiration(options), cancellationToken);
        }

        #endregion

        #region Remove

        /// <inheritdoc />
        public void Remove(CacheKey key)
        {
            key.Validate();
            Remove(key.Key);
        }

        /// <inheritdoc />
        public void Remove(string key)
        {
            _provider.Remove(key);
        }

        /// <inheritdoc />
        public void Remove(IEnumerable<CacheKey> keys)
        {
            Remove(ToKeys(keys));
        }

        /// <inheritdoc />
        public void Remove(IEnumerable<string> keys)
        {
            _provider.RemoveAll(keys);
        }

        #endregion

        #region RemoveAsync

        /// <inheritdoc />
        public async Task RemoveAsync(CacheKey key, CancellationToken cancellationToken = default)
        {
            key.Validate();
            await RemoveAsync(key.Key, cancellationToken);
        }

        /// <inheritdoc />
        public async Task RemoveAsync(string key, CancellationToken cancellationToken = default)
        {
            await _provider.RemoveAsync(key, cancellationToken);
        }

        /// <inheritdoc />
        public async Task RemoveAsync(IEnumerable<CacheKey> keys, CancellationToken cancellationToken = default)
        {
            await RemoveAsync(ToKeys(keys), cancellationToken);
        }

        /// <inheritdoc />
        public async Task RemoveAsync(IEnumerable<string> keys, CancellationToken cancellationToken = default)
        {
            await _provider.RemoveAllAsync(keys, cancellationToken);
        }

        #endregion

        #region RemoveByPrefix

        /// <summary>
        /// 通过缓存键前缀移除缓存
        /// </summary>
        /// <param name="prefix">缓存键前缀</param>
        public void RemoveByPrefix(string prefix)
        {
            if (prefix.IsEmpty())
                return;
            _provider.RemoveByPrefix(prefix);
        }

        #endregion

        #region RemoveByPrefixAsync

        /// <inheritdoc />
        public async Task RemoveByPrefixAsync(string prefix, CancellationToken cancellationToken = default)
        {
            if (prefix.IsEmpty())
                return;
            await _provider.RemoveByPrefixAsync(prefix, cancellationToken);
        }

        #endregion

        #region RemoveByPattern

        /// <inheritdoc />
        public void RemoveByPattern(string pattern)
        {
            if (pattern.IsEmpty())
                return;
            _provider.RemoveByPattern(pattern);
        }

        #endregion

        #region RemoveByPatternAsync

        /// <inheritdoc />
        public async Task RemoveByPatternAsync(string pattern, CancellationToken cancellationToken = default)
        {
            if (pattern.IsEmpty())
                return;
            await _provider.RemoveByPatternAsync(pattern, cancellationToken);
        }

        #endregion

        #region Clear

        /// <inheritdoc />
        public void Clear()
        {
            Validate();
            _cachingProvider.Flush();
        }

        #endregion

        #region ClearAsync

        /// <inheritdoc />
        public async Task ClearAsync(CancellationToken cancellationToken = default)
        {
            Validate();
            await _cachingProvider.FlushAsync(cancellationToken);
        }

        #endregion
    }

    /// <summary>
    /// 缓存提供器标识
    /// </summary>
    public static class CacheProviderKey
    {
        /// <summary>
        /// 内存缓存提供器标识
        /// </summary>
        public const string MemoryCache = "DefaultInMemory";
        /// <summary>
        /// Redis缓存提供器标识
        /// </summary>
        public const string RedisCache = "DefaultRedis";
        /// <summary>
        /// Hybrid缓存提供器标识
        /// </summary>
        public const string HybridCache = "DefaultHybrid";
        /// <summary>
        /// Redis总线提供器标识
        /// </summary>
        public const string RedisBus = "DefaultRedis";
        /// <summary>
        /// SystemTextJson序列化提供程序标识
        /// </summary>
        public const string SystemTextJson = "SystemTextJson";
    }

    /// <summary>
    /// EasyCaching配置
    /// </summary>
    internal class CachingOptions
    {
        /// <summary>
        /// Redis服务端点列表
        /// </summary>
        private static List<ServerEndPoint> _redisEndPoints = new();

        /// <summary>
        /// 添加Redis服务端点
        /// </summary>
        /// <param name="configuration">配置</param>
        /// <param name="section">配置节名称</param>
        public static void AddRedisEndPoints(IConfiguration configuration, string section)
        {
            var config = configuration.GetSection($"{section}:DbConfig:Endpoints");
            var endpoints = config.GetChildren();
            foreach (var endpoint in endpoints)
            {
                var host = endpoint["Host"];
                var port = endpoint["Port"].ToIntOrNull() ?? 6379;
                _redisEndPoints.Add(new ServerEndPoint(host, port));
            }
        }

        /// <summary>
        /// 添加Redis服务端点
        /// </summary>
        /// <param name="setupAction">配置操作</param>
        public static void AddRedisEndPoints(Action<RedisOptions> setupAction)
        {
            setupAction.CheckNull(nameof(setupAction));
            var options = new RedisOptions();
            setupAction(options);
            _redisEndPoints.AddRange(options.DBConfig.Endpoints);
        }

        /// <summary>
        /// 获取Redis服务端点列表
        /// </summary>
        public static List<ServerEndPoint> GetRedisEndPoints()
        {
            return _redisEndPoints;
        }

        /// <summary>
        /// 清理
        /// </summary>
        public static void Clear()
        {
            _redisEndPoints = null;
        }
    }

    /// <summary>
    /// EasyCaching内存缓存服务
    /// </summary>
    public class MemoryCacheManager : CacheManager, ILocalCache
    {
        /// <summary>
        /// 初始化EasyCaching内存缓存服务
        /// </summary>
        /// <param name="factory">EasyCaching缓存提供器工厂</param>
        public MemoryCacheManager(IEasyCachingProviderFactory factory) : base(factory?.GetCachingProvider(CacheProviderKey.MemoryCache))
        {
        }
    }

    /// <summary>
    /// EasyCaching Redis缓存服务
    /// </summary>
    public class RedisCacheManager : CacheManager, IRedisCache
    {
        /// <summary>
        /// Redis缓存提供器
        /// </summary>
        private readonly IRedisCachingProvider _provider;

        /// <summary>
        /// 初始化EasyCaching Redis缓存服务
        /// </summary>
        /// <param name="factory">EasyCaching缓存提供器工厂</param>
        public RedisCacheManager(IEasyCachingProviderFactory factory) : base(factory?.GetCachingProvider(CacheProviderKey.RedisCache))
        {
            if (factory == null)
                throw new ArgumentNullException(nameof(factory));
            _provider = factory.GetRedisProvider(CacheProviderKey.RedisCache);
        }
    }

    #endregion
}

