        #region Font

        /// <inheritdoc />
        public IImageWrapper Font(float size, FontStyle style = FontStyle.Regular, string fontName = null)
        {
            if (fontName.IsEmpty())
                fontName = _defaultFontName;
            var fontFamily = ImageManager.GetFont(fontName);
            _font = new Font(fontFamily, size, style);
            return this;
        }

        /// <inheritdoc />
        public IImageWrapper Font(float size, string fontName)
        {
            return Font(size, FontStyle.Regular, fontName);
        }

        #endregion

        #region Text

        /// <inheritdoc />
        public IImageWrapper Text(string text, string color, float x, float y)
        {
            _commands.Add(new TextCommand(_font, text, color, x, y));
            return this;
        }

        /// <inheritdoc />
        public IImageWrapper Text(string text, string color, RichTextOptions options)
        {
            _commands.Add(new TextCommand(options, text, color));
            return this;
        }

        #endregion

        #region TextCenter

        /// <inheritdoc />
        public IImageWrapper TextCenter(string text, string color)
        {
            var options = new RichTextOptions(_font)
            {
                VerticalAlignment = VerticalAlignment.Center,
                HorizontalAlignment = HorizontalAlignment.Center,
                Origin = new Vector2(_width / 2, _height / 2)
            };
            return Text(text, color, options);
        }

        #endregion

        #region SaveAsync

        /// <inheritdoc />
        public async Task SaveAsync(string path, CancellationToken cancellationToken = default)
        {
            using var image = GetImage();
            _commands.ForEach(command => command.Invoke(image));
            Util.Helpers.File.CreateDirectory(path);
            await image.SaveAsync(path, GetImageEncoder(), cancellationToken);
        }

        /// <summary>
        /// 获取图片实例
        /// </summary>
        protected Image GetImage()
        {
            if (_loadPath.IsEmpty())
                return new Image<Rgba32>(_width, _height, GetColor(_backgroundColor));
            return Image.Load(_loadPath);
        }

        /// <summary>
        /// 获取颜色
        /// </summary>
        /// <param name="color">颜色值</param>
        protected Color GetColor(string color)
        {
            return Color.ParseHex(color);
        }

        /// <summary>
        /// 获取图片编码器
        /// </summary>
        private IImageEncoder GetImageEncoder()
        {
            return GetImageEncoder(_imageType);
        }

        #endregion

        #region ToStreamAsync

        /// <inheritdoc />
        public async Task<byte[]> ToStreamAsync(CancellationToken cancellationToken = default)
        {
            using var image = GetImage();
            using var stream = new MemoryStream();
            _commands.ForEach(command => command.Invoke(image));
            await image.SaveAsync(stream, GetImageEncoder(), cancellationToken);
            return await Util.Helpers.File.ToBytesAsync(stream, cancellationToken);
        }

        #endregion

        #region ToBase64

        /// <inheritdoc />
        public string ToBase64()
        {
            using var image = GetImage();
            _commands.ForEach(command => command.Invoke(image));
            return image.ToBase64String(GetImageFormat());
        }

        /// <summary>
        /// 获取图片格式
        /// </summary>
        private IImageFormat GetImageFormat()
        {
            return GetImageFormat(_imageType);
        }

        #endregion

        #region GetImageEncoder

        /// <summary>
        /// 获取图片编码器
        /// </summary>
        public static IImageEncoder GetImageEncoder(ImageType type)
        {
            switch (type)
            {
                case Images.ImageType.Png:
                    return new PngEncoder();
                case Images.ImageType.Gif:
                    return new GifEncoder();
                case Images.ImageType.Bmp:
                    return new BmpEncoder();
                case Images.ImageType.Jpg:
                    return new JpegEncoder();
                default:
                    return new PngEncoder();
            }
        }

        #endregion

        #region GetImageFormat

        /// <summary>
        /// 获取图片格式
        /// </summary>
        public static IImageFormat GetImageFormat(ImageType type)
        {
            switch (type)
            {
                case Images.ImageType.Png:
                    return PngFormat.Instance;
                case Images.ImageType.Gif:
                    return GifFormat.Instance;
                case Images.ImageType.Bmp:
                    return BmpFormat.Instance;
                case Images.ImageType.Jpg:
                    return JpegFormat.Instance;
                default:
                    return PngFormat.Instance;
            }
        }

        #endregion
    }

    #endregion

    #region Images.Avatar
    /// <summary>
    /// 头像服务
    /// </summary>
    public class AvatarManager : IAvatarManager
    {

        #region 字段

        /// <summary>
        /// 背景色
        /// </summary>
        private string _backgroundColor;
        /// <summary>
        /// 头像大小
        /// </summary>
        private int _size;
        /// <summary>
        /// 字体名称
        /// </summary>
        private string _fontName;
        /// <summary>
        /// 字体大小
        /// </summary>
        private double _fontSize;
        /// <summary>
        /// 字体颜色
        /// </summary>
        private string _fontColor;
        /// <summary>
        /// 字体是否粗体
        /// </summary>
        private bool _isBold;
        /// <summary>
        /// 字体是否斜体
        /// </summary>
        private bool _isItalic;
        /// <summary>
        /// 字体是否大写
        /// </summary>
        private bool _isUppercase;
        /// <summary>
        /// 文本
        /// </summary>
        private string _text;
        /// <summary>
        /// 文本长度
        /// </summary>
        private int _length;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化头像服务
        /// </summary>
        /// <param name="imageManager">图片服务</param>
        public AvatarManager(IImageManager imageManager)
        {
            ImageManager = imageManager ?? throw new ArgumentNullException(nameof(imageManager));
            _backgroundColor = "5d005d";
            _size = 64;
            _fontSize = 0.5;
            _fontColor = "ffffff";
            _isUppercase = true;
        }

        #endregion

        #region 属性

        /// <summary>
        /// 图片服务
        /// </summary>
        protected IImageManager ImageManager { get; }

        #endregion

        #region BackgroundColor

        /// <inheritdoc />
        public IAvatarManager BackgroundColor(string color)
        {
            _backgroundColor = color;
            return this;
        }

        #endregion

        #region Size

        /// <inheritdoc />
        public IAvatarManager Size(int size)
        {
            _size = size;
            return this;
        }

        #endregion

        #region Font

        /// <inheritdoc />
        public IAvatarManager Font(string fontName)
        {
            _fontName = fontName;
            return this;
        }

        #endregion

        #region FontSize

        /// <inheritdoc />
        public IAvatarManager FontSize(double size)
        {
            _fontSize = size;
            return this;
        }

        #endregion

        #region FontColor

        /// <inheritdoc />
        public IAvatarManager FontColor(string color)
        {
            _fontColor = color;
            return this;
        }

        #endregion

        #region Bold

        /// <inheritdoc />
        public IAvatarManager Bold(bool isBold = true)
        {
            _isBold = isBold;
            return this;
        }

        #endregion

        #region Italic

        /// <inheritdoc />
        public IAvatarManager Italic(bool isItalic = true)
        {
            _isItalic = isItalic;
            return this;
        }

        #endregion

        #region Uppercase

        /// <inheritdoc />
        public IAvatarManager Uppercase(bool isUppercase = true)
        {
            _isUppercase = isUppercase;
            return this;
        }

        #endregion

        #region Text

        /// <inheritdoc />
        public IAvatarManager Text(string text, int length = 1)
        {
            _text = text;
            _length = length;
            return this;
        }

        #endregion

        #region SaveAsync

        /// <inheritdoc />
        public virtual async Task SaveAsync(string path, CancellationToken cancellationToken = default)
        {
            if (_text.IsEmpty())
                return;
            var imageWrapper = GetImageWrapper();
            await imageWrapper.SaveAsync(path, cancellationToken);
        }

        /// <summary>
        /// 获取图片包装器
        /// </summary>
        private IImageWrapper GetImageWrapper()
        {
            return ImageManager.CreateImage(GetSize(), GetSize(), _backgroundColor)
                .Font(GetFontSize(), GetFontStyle(), _fontName)
                .TextCenter(GetText(), _fontColor);
        }

        /// <summary>
        /// 获取头像大小
        /// </summary>
        private int GetSize()
        {
            if (_size < 16)
                return 16;
            if (_size > 512)
                return 512;
            return _size;
        }

        /// <summary>
        /// 获取字体大小
        /// </summary>
        private float GetFontSize()
        {
            if (_fontSize is >= 0.1 and <= 1)
                return _size * (float)_fontSize;
            if (_fontSize < 16)
                return 16;
            if (_fontSize > _size)
                return _size * 0.5f;
            return (float)_fontSize;
        }

        /// <summary>
        /// 获取字体样式
        /// </summary>
        private FontStyle GetFontStyle()
        {
            if (_isBold && _isItalic)
                return FontStyle.BoldItalic;
            if (_isBold)
                return FontStyle.Bold;
            if (_isItalic)
                return FontStyle.Italic;
            return FontStyle.Regular;
        }

        /// <summary>
        /// 获取文本
        /// </summary>
        private string GetText()
        {
            if (_text.IsEmpty())
                return null;
            _text = GetPlusSeparatedText();
            if (_isUppercase)
                _text = _text.ToUpperInvariant();
            if (_text.Length > _length)
                return _text.Substring(0, _length);
            return _text;
        }

        /// <summary>
        /// 获取加号分隔文本
        /// </summary>
        private string GetPlusSeparatedText()
        {
            if (_text.Contains("+") == false)
                return _text;
            _length = 3;
            return _text.Split("+").Where(t => t.IsEmpty() == false).Select(t => t.Trim().Substring(0, 1)).Join(separator: "");
        }

        #endregion

        #region ToStreamAsync

        /// <summary>
        /// 转换为图片流
        /// </summary>
        /// <param name="cancellationToken">取消令牌</param>
        public virtual async Task<byte[]> ToStreamAsync(CancellationToken cancellationToken = default)
        {
            if (_text.IsEmpty())
                return null;
            var imageWrapper = GetImageWrapper();
            return await imageWrapper.ToStreamAsync(cancellationToken);
        }

        #endregion

        #region ToBase64

        /// <inheritdoc />
        public string ToBase64()
        {
            if (_text.IsEmpty())
                return null;
            var imageWrapper = GetImageWrapper();
            return imageWrapper.ToBase64();
        }

        #endregion
    }

    /// <summary>
    /// 头像服务
