    /// <summary>
    /// 本地文件存储操作扩展
    /// </summary>
    public static class AppBuilderExtensions
    {
        /// <summary>
        /// 配置本地文件存储操作,将文件上传到Web服务器目录
        /// </summary>
        /// <param name="builder">应用生成器</param>
        public static IAppBuilder AddLocalFileStore(this IAppBuilder builder)
        {
            return builder.AddLocalFileStore(null);
        }

        /// <summary>
        /// 配置本地文件存储操作,将文件上传到Web服务器目录
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="setupAction">本地文件存储配置操作</param>
        public static IAppBuilder AddLocalFileStore(this IAppBuilder builder, Action<LocalStoreOptions> setupAction)
        {
            builder.CheckNull(nameof(builder));
            builder.Host.ConfigureServices((context, services) =>
            {
                if (setupAction != null)
                    services.Configure(setupAction);
                services.TryAddTransient<IFileStore, LocalFileStore>();
                services.TryAddTransient<ILocalFileStore, LocalFileStore>();
            });
            return builder;
        }
    }

    /// <summary>
    /// 存储桶名称处理器
    /// </summary>
    public class BucketNameProcessor : IBucketNameProcessor
    {
        /// <inheritdoc />
        public ProcessedName Process(string bucketName)
        {
            if (bucketName.IsEmpty())
                throw new ArgumentNullException(nameof(bucketName));
            var result = bucketName.ToLowerInvariant().Replace("_", "-").Replace(".", "-").Trim('-');
            return new ProcessedName(result, bucketName);
        }
    }

    /// <summary>
    /// 存储桶名称处理器工厂
    /// </summary>
    public class BucketNameProcessorFactory : IBucketNameProcessorFactory
    {
        /// <inheritdoc />
        public IBucketNameProcessor CreateProcessor(string policy)
        {
            if (policy.IsEmpty())
                return new BucketNameProcessor();
            throw new NotImplementedException($"存储桶名称处理策略 {policy} 未实现.");
        }
    }

