    /// <summary>
    /// 文件名处理器工厂
    /// </summary>
    public class FileNameProcessorFactory : IFileNameProcessorFactory
    {
        /// <summary>
        /// 用户会话
        /// </summary>
        private readonly ISession _session;

        /// <summary>
        /// 初始化文件名处理器工厂
        /// </summary>
        /// <param name="session">用户会话</param>
        public FileNameProcessorFactory(ISession session)
        {
            _session = session ?? NullSession.Instance;
        }

        /// <inheritdoc />
        public IFileNameProcessor CreateProcessor(string policy)
        {
            if (policy.IsEmpty())
                return new FileNameProcessor();
            if (policy.ToUpperInvariant() == UserTimeFileNameProcessor.Policy)
                return new UserTimeFileNameProcessor(_session);
            throw new NotImplementedException($"文件名处理策略 {policy} 未实现.");
        }
    }

    /// <summary>
    /// 文件存储服务操作扩展
    /// </summary>
    public static class FileStoreExtensions
    {
        /// <summary>
        /// 保存文件
        /// </summary>
        /// <param name="fileStore">文件存储服务</param>
        /// <param name="fileInfo">文件信息</param>
        /// <param name="policy">文件名处理策略</param>
        /// <param name="cancellationToken">取消令牌</param>
        public static async Task<FileResult> SaveFileAsync(this ILocalFileStore fileStore, FileInfo fileInfo, string policy = null, CancellationToken cancellationToken = default)
        {
            fileStore.CheckNull(nameof(fileStore));
            var path = fileInfo.FullName;
            if (System.IO.File.Exists(path) == false)
                throw new FileNotFoundException("保存文件失败,文件路径不正确.", path);
            var fileName = System.IO.Path.GetFileName(path);
            await using var stream = Util.Helpers.File.ReadToStream(path);
            return await fileStore.SaveFileAsync(stream, fileName, policy, cancellationToken);
        }

        /// <summary>
        /// 保存文件
        /// </summary>
        /// <param name="fileStore">文件存储服务</param>
        /// <param name="bytes">文件流</param>
        /// <param name="fileName">文件名,包含扩展名</param>
        /// <param name="policy">文件名处理策略</param>
        /// <param name="cancellationToken">取消令牌</param>
        public static async Task<FileResult> SaveFileAsync(this ILocalFileStore fileStore, byte[] bytes, string fileName, string policy = null, CancellationToken cancellationToken = default)
        {
            fileStore.CheckNull(nameof(fileStore));
            await using var stream = new MemoryStream(bytes);
            return await fileStore.SaveFileAsync(stream, fileName, policy, cancellationToken);
        }

        /// <summary>
        /// 获取文件字节流
        /// </summary>
        /// <param name="fileStore">文件存储服务</param>
        /// <param name="fileName">文件名,包含扩展名</param>
        /// <param name="cancellationToken">取消令牌</param>
        public static async Task<byte[]> GetFileBytesAsync(this ILocalFileStore fileStore, string fileName, CancellationToken cancellationToken = default)
        {
            var stream = await fileStore.GetFileStreamAsync(fileName, cancellationToken);
            await using (stream)
            {
                return await Util.Helpers.File.ToBytesAsync(stream, cancellationToken);
            }
        }
    }

    /// <summary>
    /// 文件验证操作
    /// </summary>
    public static class FileValidation
    {
        /// <summary>
        /// 扩展名是否有效
        /// </summary>
        /// <param name="fileName">文件名,范例: a.jpg</param>
        /// <param name="accepts">接受的扩展名列表,以逗号分隔,范例: .jpg,.png,.gif</param>
        public static bool IsValidExtension(string fileName, string accepts)
        {
            if (fileName.IsEmpty())
                return false;
            if (accepts.IsEmpty())
                return true;
            var extension = Path.GetExtension(fileName);
            var list = accepts.Split(',').Where(t => t.IsEmpty() == false).ToList();
            if (list.Count == 0)
                return true;
            return list.Any(type => type.TrimStart('.') == extension.TrimStart('.'));
        }
    }

    /// <summary>
    /// 基于用户标识和时间的文件名处理器
    /// </summary>
    public class UserTimeFileNameProcessor : IFileNameProcessor
    {
        /// <summary>
        /// 策略名称
        /// </summary>
        public const string Policy = "USERTIME";
        /// <summary>
        /// 用户会话
        /// </summary>
        private readonly ISession _session;

        /// <summary>
        /// 初始化基于用户标识和时间的文件名处理器
        /// </summary>
        /// <param name="session">用户会话</param>
        public UserTimeFileNameProcessor(ISession session)
        {
            _session = session ?? NullSession.Instance;
        }

        /// <inheritdoc />
        public ProcessedName Process(string fileName)
        {
            if (fileName.IsEmpty())
                return new ProcessedName(null);
            var extension = Path.GetExtension(fileName);
            var name = $"{Id.Create()}{extension}";
            var result = Util.Helpers.Common.JoinPath(_session.UserId, $"{Time.Now:yyyy-MM-dd}", name);
            return new ProcessedName(result, fileName);
        }
    }

