        IFileStore Create(MinioOptions options);
        /// <summary>
        /// 创建文件存储服务
        /// </summary>
        /// <param name="options">阿里云对象存储配置</param>
        IFileStore Create(AliyunOssOptions options);
        /// <summary>
        /// 创建阿里云对象存储服务
        /// </summary>
        /// <param name="options">阿里云对象存储配置</param>
        IAliyunOssFileStore CreateAliyunOss(AliyunOssOptions options);
    }
    #endregion
