    #region Tenants.Abstractions
    /// <summary>
    /// 域名租户解析器
    /// </summary>
    public interface IDomainTenantResolver : ITransientDependency
    {
        /// <summary>
        /// 解析租户标识
        /// </summary>
        /// <param name="host">域名,范例: a.test.com</param>
        Task<string> ResolveTenantIdAsync(string host);
    }

    /// <summary>
    /// 切换租户管理器
    /// </summary>
    public interface ISwitchTenantManager : ITransientDependency
    {
        /// <summary>
        /// 获取切换的租户标识
        /// </summary>
        string GetSwitchTenantId();
        /// <summary>
        /// 切换租户标识
        /// </summary>
        /// <param name="tenantId">租户标识</param>
        Task SwitchTenantAsync(string tenantId);
        /// <summary>
        /// 重置租户标识
        /// </summary>
        Task ResetTenantAsync();
    }

    /// <summary>
    /// 租户
    /// </summary>
    public interface ITenant
    {
        /// <summary>
        /// 租户标识
        /// </summary>
        string TenantId { get; set; }
    }

    /// <summary>
    /// 租户管理器
    /// </summary>
    public interface ITenantManager : IScopeDependency
    {
        /// <summary>
        /// 是否启用多租户架构
        /// </summary>
        bool Enabled();
        /// <summary>
        /// 是否允许使用多数据库
        /// </summary>
        bool AllowMultipleDatabase();
        /// <summary>
        /// 是否平台供应商
        /// </summary>
        bool IsHost();
        /// <summary>
        /// 获取当前租户标识
        /// </summary>
        string GetTenantId();
        /// <summary>
        /// 获取当前租户配置
        /// </summary>
        TenantInfo GetTenant();
        /// <summary>
        /// 是否禁用租户过滤器
        /// </summary>
        bool IsDisableTenantFilter();
    }

    /// <summary>
    /// 租户存储器
    /// </summary>
    public interface ITenantStore : IScopeDependency
    {
        /// <summary>
        /// 获取当前租户配置
        /// </summary>
        /// <param name="tenantId">租户标识</param>
        TenantInfo GetTenant(string tenantId);
    }

    /// <summary>
    /// 查看租户管理器
    /// </summary>
    public interface IViewAllTenantManager : ITransientDependency
    {
        /// <summary>
        /// 是否禁用租户过滤器
