    #region Tenants

    #region Managements
    /// <summary>
    /// 切换租户管理器
    /// </summary>
    public class SwitchTenantManager : ISwitchTenantManager
    {
        /// <summary>
        /// 切换租户键名
        /// </summary>
        public const string Key = "x-switch-tenant";

        /// <inheritdoc />
        public string GetSwitchTenantId()
        {
            return Web.GetCookie(Key);
        }

        /// <inheritdoc />
        public Task SwitchTenantAsync(string tenantId)
        {
            Web.SetCookie(Key, tenantId);
            return Task.CompletedTask;
        }

        /// <inheritdoc />
        public Task ResetTenantAsync()
        {
            Web.RemoveCookie(Key);
            return Task.CompletedTask;
        }
    }

    /// <summary>
    /// 租户管理器
    /// </summary>
    public class TenantManager : ITenantManager
    {
        /// <summary>
        /// 当前租户标识
        /// </summary>
        private static readonly AsyncLocal<string> _currentTenantId;

        /// <summary>
        /// 初始化租户管理器
        /// </summary>
        static TenantManager()
        {
            _currentTenantId = new AsyncLocal<string>();
        }

        /// <summary>
        /// 初始化租户管理器
        /// </summary>
        /// <param name="tenantStore">租户存储器</param>
        /// <param name="viewAllTenantManager">查看租户管理器</param>
        /// <param name="switchTenantManager">切换租户管理器</param>
        /// <param name="session">用户会话</param>
        /// <param name="options">租户配置</param>
        public TenantManager(ITenantStore tenantStore, IViewAllTenantManager viewAllTenantManager, ISwitchTenantManager switchTenantManager,
            Sessions.ISession session, IOptions<TenantOptions> options)
        {
            TenantStore = tenantStore ?? throw new ArgumentNullException(nameof(tenantStore));
            ViewAllTenantManager = viewAllTenantManager ?? throw new ArgumentNullException(nameof(viewAllTenantManager));
            SwitchTenantManager = switchTenantManager ?? throw new ArgumentNullException(nameof(switchTenantManager));
            Session = session ?? throw new ArgumentNullException(nameof(session));
            Options = options?.Value ?? TenantOptions.Null;
        }

        /// <summary>
        /// 租户存储器
        /// </summary>
        protected ITenantStore TenantStore { get; }
        /// <summary>
        /// 查看租户管理器
        /// </summary>
        protected IViewAllTenantManager ViewAllTenantManager { get; }
        /// <summary>
        /// 切换租户管理器
        /// </summary>
        protected ISwitchTenantManager SwitchTenantManager { get; }
        /// <summary>
        /// 用户会话
        /// </summary>
        protected Sessions.ISession Session { get; }
        /// <summary>
        /// 租户配置
        /// </summary>
        protected TenantOptions Options { get; }

        /// <summary>
        /// 当前租户标识
        /// </summary>
        public static string CurrentTenantId
        {
            get => _currentTenantId.Value;
            set => _currentTenantId.Value = value;
        }

        /// <inheritdoc />
        public virtual bool Enabled()
        {
            return Options.IsEnabled;
        }

        /// <inheritdoc />
        public virtual bool AllowMultipleDatabase()
        {
            return Options.IsAllowMultipleDatabase;
        }

        /// <inheritdoc />
        public virtual bool IsHost()
        {
            if (Session.IsAuthenticated == false)
                return false;
            if (Session.UserId.IsEmpty())
                return false;
            if (Session.TenantId != CurrentTenantId)
                return false;
            return Session.TenantId == Options.DefaultTenantId;
        }

        /// <inheritdoc />
        public virtual string GetTenantId()
        {
            if (IsHost() == false)
                return CurrentTenantId;
            var switchTenantId = SwitchTenantManager.GetSwitchTenantId();
            return switchTenantId.IsEmpty() ? CurrentTenantId : switchTenantId;
        }

        /// <inheritdoc />
        public virtual TenantInfo GetTenant()
        {
            return TenantStore.GetTenant(GetTenantId());
        }

        /// <inheritdoc />
        public virtual bool IsDisableTenantFilter()
        {
            if (IsHost() == false)
                return false;
            return ViewAllTenantManager.IsDisableTenantFilter();
        }
    }

    /// <summary>
    /// 查看租户管理器
    /// </summary>
    public class ViewAllTenantManager : IViewAllTenantManager
    {
        /// <summary>
        /// 查看所有租户键名
        /// </summary>
        public const string Key = "x-view-all-tenant";

        /// <inheritdoc />
        public bool IsDisableTenantFilter()
        {
            var result = Web.GetCookie(Key);
            if (result.IsEmpty())
                return false;
            return result.ToBool();
        }

        /// <inheritdoc />
        public Task EnableViewAllAsync()
        {
            Web.SetCookie(Key, "true");
            return Task.CompletedTask;
        }

        /// <inheritdoc />
        public Task DisableViewAllAsync()
        {
            Web.RemoveCookie(Key);
            return Task.CompletedTask;
        }
    }

    #endregion

    #region Middlewares
    /// <summary>
    /// 租户处理中间件
    /// </summary>
    public class TenantMiddleware
    {
        /// <summary>
        /// 中间件管道
        /// </summary>
        private readonly RequestDelegate _next;

        /// <summary>
        /// 初始化租户处理中间件
        /// </summary>
        /// <param name="next">中间件管道</param>
        public TenantMiddleware(RequestDelegate next)
        {
            _next = next;
        }

        /// <summary>
        /// 执行管道
        /// </summary>
        /// <param name="httpContext">Http上下文</param>
        public async Task InvokeAsync(HttpContext httpContext)
        {
            if (_next == null)
                return;
            if (httpContext == null)
            {
                await _next(httpContext);
                return;
            }
            var log = httpContext.RequestServices.GetService<ILogger<TenantMiddleware>>() ?? NullLogger<TenantMiddleware>.Instance;
            var resolver = httpContext.RequestServices.GetRequiredService<ITenantResolver>();
            try
            {
                var tenantId = await resolver.ResolveAsync(httpContext);
                TenantManager.CurrentTenantId = tenantId;
                await _next(httpContext);
            }
            catch (Exception exception)
            {
                log.LogError(exception, "租户处理中间件发生异常");
                throw;
            }
        }
    }
    #endregion

    #region Resolvers
    /// <summary>
    /// 域名租户解析器
    /// </summary>
    internal class DomainTenantResolver : IDomainTenantResolver
    {
        /// <summary>
        /// 租户域名存储器
        /// </summary>
        private readonly ITenantDomainStore _store;
        /// <summary>
        /// 租户配置
        /// </summary>
        private readonly TenantOptions _options;

        /// <summary>
        /// 初始化域名租户解析器
        /// </summary>
        /// <param name="store">租户域名存储器</param>
        /// <param name="options">租户配置</param>
        public DomainTenantResolver(ITenantDomainStore store, IOptions<TenantOptions> options)
        {
            _store = store ?? throw new ArgumentNullException(nameof(store));
            _options = options?.Value ?? new TenantOptions();
        }

        /// <inheritdoc />
        public async Task<string> ResolveTenantIdAsync(string host)
        {
            if (host.IsEmpty())
                return null;
            var domainMap = new Dictionary<string, string>();
            var domainFormat = string.Empty;
            var resolvers = _options.Resolvers.GetResolvers<Resolvers.DomainTenantResolver>();
            foreach (var resolver in resolvers)
            {
                if (resolver.DomainMap != null)
                {
                    foreach (var item in resolver.DomainMap)
                    {
                        domainMap.Add(item.Key, item.Value);
                    }
                }
                domainFormat += $",{resolver.DomainFormat}";
            }
            var map = await DomainTenantResolverHelper.CombineMapAsync(domainMap, _store);
            return DomainTenantResolverHelper.ResolveTenantId(host, map, domainFormat);
        }
    }

    /// <summary>
    /// 基于Cookie的租户解析器
    /// </summary>
    public class CookieTenantResolver : TenantResolverBase
    {
        /// <summary>
        /// 解析租户标识
        /// </summary>
        protected override Task<string> Resolve(HttpContext context)
        {
            var key = GetTenantKey(context);
            var tenantId = context.Request.Cookies[key];
            GetLog(context).LogTrace($"执行Cookie租户解析器,{key}={tenantId}");
            return Task.FromResult(tenantId);
        }
    }

    /// <summary>
    /// 默认租户解析器
    /// </summary>
    public class DefaultTenantResolver : ITenantResolver
    {
        /// <summary>
        /// 租户配置
        /// </summary>
        private readonly TenantOptions _options;
        /// <inheritdoc />
        public int Priority { get; set; }

        /// <summary>
        /// 初始化默认租户解析器
        /// </summary>
        /// <param name="options">租户配置</param>
        public DefaultTenantResolver(IOptions<TenantOptions> options)
        {
            _options = options?.Value ?? TenantOptions.Null;
        }

        /// <inheritdoc />
        public async Task<string> ResolveAsync(HttpContext context)
        {
            if (context == null)
                return null;
            if (_options.IsEnabled == false)
                return null;
            var session = context.RequestServices.GetService<Util.Sessions.ISession>();
            if (session is { IsAuthenticated: true })
                return session.TenantId;
            if (_options.Resolvers == null)
                return null;
            foreach (var resolver in _options.Resolvers.OrderByDescending(t => t.Priority))
            {
                var result = await resolver.ResolveAsync(context);
                if (result.IsEmpty() == false)
                    return result;
            }
            return null;
        }
    }

    /// <summary>
    /// 基于域名的租户解析器
    /// </summary>
    public class DomainTenantResolver : TenantResolverBase
    {
        /// <summary>
        /// 初始化基于域名的租户解析器
        /// </summary>
        public DomainTenantResolver()
        {
        }

        /// <summary>
        /// 初始化基于域名的租户解析器
        /// </summary>
        /// <param name="domainFormat">域名格式字符串,范例:{0}.a.com</param>
        public DomainTenantResolver(string domainFormat)
        {
            DomainFormat = domainFormat;
        }

        /// <summary>
        /// 初始化基于域名的租户解析器
        /// </summary>
        /// <param name="domainMap">域名映射配置,键为域名,值为租户标识</param>
        public DomainTenantResolver(IDictionary<string, string> domainMap)
        {
            DomainMap = domainMap;
        }

        /// <summary>
        /// 域名格式字符串
        /// </summary>
        public string DomainFormat { get; }

        /// <summary>
        /// 域名映射配置
        /// </summary>
        public IDictionary<string, string> DomainMap { get; }

        /// <summary>
        /// 解析租户标识
        /// </summary>
        protected override async Task<string> Resolve(HttpContext context)
        {
            var host = DomainTenantResolverHelper.RemoveDomainPrefix(context.Request.Host.Value);
            if (host.IsEmpty())
                return null;
            var result = await Resolve(context, host);
            GetLog(context).LogTrace($"执行域名租户解析器,host={host},tenantId={result}");
            return result;
        }

        /// <summary>
        /// 解析租户标识
        /// </summary>
        private async Task<string> Resolve(HttpContext context, string host)
        {
            var store = context.RequestServices.GetService<ITenantDomainStore>();
            var map = await DomainTenantResolverHelper.CombineMapAsync(DomainMap, store);
            return DomainTenantResolverHelper.ResolveTenantId(host, map, DomainFormat);
        }
    }

    /// <summary>
    /// 租户域名解析器辅助操作
    /// </summary>
    public class DomainTenantResolverHelper
    {
        /// <summary>
        /// 解析租户标识
        /// </summary>
        /// <param name="domain">域名</param>
        /// <param name="domainMap">域名映射配置</param>
        /// <param name="domainFormat">域名格式字符串</param>
        public static string ResolveTenantId(string domain, IDictionary<string, string> domainMap, string domainFormat)
        {
            if (domain.IsEmpty())
                return null;
            var host = RemoveDomainPrefix(domain);
            if (host.IsEmpty())
                return null;
            if (domainMap is { Count: > 0 })
            {
                var result = ResolveByMap(host, domainMap);
                if (result.IsEmpty() == false)
                    return result;
            }
            domainFormat = domainFormat.RemoveStart(",").RemoveEnd(",");
            return domainFormat.IsEmpty() ? ResolveBySplit(host) : ResolveByFormat(host, domainFormat);
        }

        /// <summary>
        /// 移除域名前缀
        /// </summary>
        public static string RemoveDomainPrefix(string domain)
        {
            return domain.RemoveStart("http://").RemoveStart("https://");
        }

        /// <summary>
        /// 通过域名映射配置解析
        /// </summary>
        private static string ResolveByMap(string host, IDictionary<string, string> domainMap)
        {
            foreach (var item in domainMap)
            {
                if (item.Key == host)
                    return item.Value;
            }
            return null;
        }

        /// <summary>
        /// 通过域名格式字符串解析
        /// </summary>
        private static string ResolveByFormat(string host, string domainFormat)
        {
            var formats = GetDomainFormats(domainFormat);
            foreach (var format in formats)
            {
                if (format.IsEmpty())
                    continue;
                var result = Util.Helpers.String.Extract(host, RemoveDomainPrefix(format)).FirstOrDefault().Value;
                if (result.IsEmpty() == false)
                    return result;
            }
            return null;
        }

        /// <summary>
        /// 获取域名格式列表
        /// </summary>
        private static IEnumerable<string> GetDomainFormats(string domainFormat)
        {
            if (domainFormat.IndexOf(",", StringComparison.Ordinal) >= 0)
                return domainFormat.Split(',');
            if (domainFormat.IndexOf(";", StringComparison.Ordinal) >= 0)
                return domainFormat.Split(';');
            return new[] { domainFormat };
        }

        /// <summary>
        /// 通过拆分解析
        /// </summary>
        private static string ResolveBySplit(string host)
        {
            var items = host.Split('.');
            if (items.Length > 2)
                return items[0];
            return null;
        }

        /// <summary>
        /// 合并域名映射字典和租户域名存储器中的域名映射项
        /// </summary>
        /// <param name="domainMap">域名映射字典</param>
        /// <param name="store">租户域名存储器</param>
        public static async Task<IDictionary<string, string>> CombineMapAsync(IDictionary<string, string> domainMap, ITenantDomainStore store)
        {
            if (store == null)
                return domainMap;
            var map = await store.GetAsync();
            if (map == null || map.Count == 0)
                return domainMap;
            domainMap ??= new Dictionary<string, string>();
            foreach (var item in map)
            {
                if (domainMap.ContainsKey(item.Key) == false)
                {
                    domainMap.Add(item.Key, item.Value);
                }
            }
            return domainMap;
        }
    }

    /// <summary>
    /// 基于请求头的租户解析器
    /// </summary>
    public class HeaderTenantResolver : TenantResolverBase
    {
        /// <summary>
        /// 解析租户标识
        /// </summary>
        protected override Task<string> Resolve(HttpContext context)
        {
            var key = GetTenantKey(context);
            context.Request.Headers.TryGetValue(key, out var result);
            var tenantId = result.FirstOrDefault();
            GetLog(context).LogTrace($"执行请求头租户解析器,{key}={tenantId}");
            return Task.FromResult(tenantId);
        }
    }

    /// <summary>
    /// 租户域名存储器
    /// </summary>
    public interface ITenantDomainStore : ITransientDependency
    {
        /// <summary>
        /// 获取租户域名映射,键为域名,值为租户标识
        /// </summary>
        Task<IDictionary<string, string>> GetAsync();
    }

    /// <summary>
    /// 空租户域名存储器
    /// </summary>
    [Ioc(-9)]
    public class NullTenantDomainStore : ITenantDomainStore
    {
        /// <summary>
        /// 结果
        /// </summary>
        private readonly IDictionary<string, string> _result;

        /// <summary>
        /// 初始化空租户域名存储器
        /// </summary>
        public NullTenantDomainStore()
        {
            _result = new Dictionary<string, string>();
        }

        /// <summary>
        /// 空租户域名存储器
        /// </summary>
        public static readonly ITenantDomainStore Instance = new NullTenantDomainStore();

        /// <inheritdoc />
        public Task<IDictionary<string, string>> GetAsync()
        {
            return Task.FromResult(_result);
        }
    }

    /// <summary>
    /// 基于查询字符串的租户解析器
    /// </summary>
    public class QueryStringTenantResolver : TenantResolverBase
    {
        /// <summary>
        /// 解析租户标识
        /// </summary>
        protected override Task<string> Resolve(HttpContext context)
        {
            var key = GetTenantKey(context);
            var tenantId = context.Request.Query[key].FirstOrDefault();
            GetLog(context).LogTrace($"执行查询字符串租户解析器,{key}={tenantId}");
            return Task.FromResult(tenantId);
        }
    }

    /// <summary>
    /// 租户解析器
    /// </summary>
    public abstract class TenantResolverBase : ITenantResolver
    {
        /// <inheritdoc />
        public int Priority { get; set; }

        /// <inheritdoc />
        public async Task<string> ResolveAsync(HttpContext context)
        {
            if (context == null)
                return null;
            return await Resolve(context);
        }

        /// <summary>
        /// 解析租户标识
        /// </summary>
        protected abstract Task<string> Resolve(HttpContext context);

        /// <summary>
        /// 获取租户键名
        /// </summary>
        protected string GetTenantKey(HttpContext context)
        {
            var options = context.RequestServices.GetRequiredService<IOptions<TenantOptions>>();
            return options.Value.TenantKey;
        }

        /// <summary>
        /// 获取日志记录器
        /// </summary>
        protected ILogger<ITenantResolver> GetLog(HttpContext context)
        {
            return context.RequestServices.GetService<ILogger<ITenantResolver>>() ?? NullLogger<ITenantResolver>.Instance;
        }
    }

    #endregion

    /// <summary>
    /// 租户操作扩展
    /// </summary>
    public static class AppBuilderExtensions
    {
        /// <summary>
        /// 配置租户操作
        /// </summary>
        /// <param name="builder">应用生成器</param>
        public static IAppBuilder AddTenant(this IAppBuilder builder)
        {
            return builder.AddTenant(null);
        }

        /// <summary>
        /// 配置租户操作
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="setupAction">租户配置操作</param>
        public static IAppBuilder AddTenant(this IAppBuilder builder, Action<TenantOptions> setupAction)
        {
            builder.CheckNull(nameof(builder));
            var options = new TenantOptions
            {
                IsEnabled = true
            };
            setupAction?.Invoke(options);
            builder.Host.ConfigureServices((context, services) =>
            {
                services.TryAddSingleton<ITenantResolver, DefaultTenantResolver>();
                services.TryAddSingleton<IOptions<TenantOptions>>(new OptionsWrapper<TenantOptions>(options));
            });
            return builder;
        }
    }

    /// <summary>
    /// 租户解析器
    /// </summary>
    public interface ITenantResolver
    {
        /// <summary>
        /// 解析租户标识
        /// </summary>
        /// <param name="context">Http上下文</param>
        Task<string> ResolveAsync(HttpContext context);
        /// <summary>
        /// 优先级,值越大则优先解析
        /// </summary>
        int Priority { get; set; }
    }

    /// <summary>
    /// 租户处理中间件扩展
    /// </summary>
    public static class TenantMiddlewareExtensions
    {
        /// <summary>
        /// 注册租户处理中间件,注意: 必须在 app.UseAuthentication() 之后调用
        /// </summary>
        /// <param name="builder">应用程序生成器</param>
        public static IApplicationBuilder UseTenant(this IApplicationBuilder builder)
        {
            return builder.UseMiddleware<TenantMiddleware>();
        }
    }

    /// <summary>
    /// 租户配置
    /// </summary>
    public class TenantOptions
    {
        /// <summary>
        /// 初始化租户配置
        /// </summary>
        public TenantOptions()
        {
            TenantKey = DefaultTenantKey;
            Resolvers = new TenantResolverCollection {
            new HeaderTenantResolver{ Priority = 9 },
            new QueryStringTenantResolver{ Priority = 7 },
            new CookieTenantResolver{ Priority = 5 }
        };
        }

        /// <summary>
        /// 租户配置空实例
        /// </summary>
        public static readonly TenantOptions Null = new();

        /// <summary>
        /// 默认租户键名,默认值: x-tenant-id
        /// </summary>
        public const string DefaultTenantKey = "x-tenant-id";

        /// <summary>
        /// 是否启用多租户架构
        /// </summary>
        public bool IsEnabled { get; set; }

        /// <summary>
        /// 是否允许使用多数据库
        /// </summary>
        public bool IsAllowMultipleDatabase { get; set; }

        /// <summary>
        /// 默认租户标识
        /// </summary>
        public string DefaultTenantId { get; set; }

        /// <summary>
        /// 租户键名,默认值: x-tenant-id
        /// </summary>
        public string TenantKey { get; set; }

        /// <summary>
        /// 租户解析器集合
        /// </summary>
        public TenantResolverCollection Resolvers { get; }
    }

    /// <summary>
    /// 租户解析器集合
    /// </summary>
    public class TenantResolverCollection : IEnumerable<ITenantResolver>
    {
        /// <summary>
        /// 租户解析器列表
        /// </summary>
        private readonly Dictionary<string, ITenantResolver> _resolvers;

        /// <summary>
        /// 初始化租户解析器集合
        /// </summary>
        public TenantResolverCollection()
        {
            _resolvers = new Dictionary<string, ITenantResolver>();
        }

        /// <summary>
        /// 获取枚举器
        /// </summary>
        IEnumerator IEnumerable.GetEnumerator()
        {
            return GetEnumerator();
        }

        /// <summary>
        /// 获取枚举器
        /// </summary>
        public IEnumerator<ITenantResolver> GetEnumerator()
        {
            return GetResolvers().GetEnumerator();
        }

        /// <summary>
        /// 获取租户解析器列表
        /// </summary>
        public List<ITenantResolver> GetResolvers()
        {
            return _resolvers
                .Select(t => t.Value)
                .OrderByDescending(t => t.Priority)
                .ToList();
        }

        /// <summary>
        /// 获取租户解析器列表
        /// </summary>
        public List<TResolver> GetResolvers<TResolver>() where TResolver : ITenantResolver
        {
            return _resolvers
                .Where(t => t.Value.GetType() == typeof(TResolver))
                .Select(t => (TResolver)t.Value)
                .OrderByDescending(t => t.Priority)
                .ToList();
        }

        /// <summary>
        /// 获取租户解析器
        /// </summary>
        /// <typeparam name="TResolver">租户解析器类型</typeparam>
        public TResolver GetResolver<TResolver>() where TResolver : ITenantResolver
        {
            var key = typeof(TResolver).FullName;
            return GetResolver<TResolver>(key);
        }

        /// <summary>
        /// 获取租户解析器
        /// </summary>
        /// <typeparam name="TResolver">租户解析器类型</typeparam>
        /// <param name="key">租户解析器键名</param>
        public TResolver GetResolver<TResolver>(string key) where TResolver : ITenantResolver
        {
            var result = _resolvers.FirstOrDefault(t => t.Key == key);
            if (result.Value == null)
                return default;
            return (TResolver)result.Value;
        }

        /// <summary>
        /// 添加租户解析器
        /// </summary>
        /// <param name="resolver">租户解析器</param>
        public void Add(ITenantResolver resolver)
        {
            if (resolver == null)
                return;
            var key = resolver.GetType().FullName;
            Add(key, resolver);
        }

        /// <summary>
        /// 添加租户解析器
        /// </summary>
        /// <param name="key">租户解析器键名</param>
        /// <param name="resolver">租户解析器</param>
        public void Add(string key, ITenantResolver resolver)
        {
            if (key.IsEmpty())
                return;
            if (resolver == null)
                return;
            Remove(key);
            _resolvers.Add(key, resolver);
        }

        /// <summary>
        /// 添加租户解析器列表
        /// </summary>
        /// <param name="resolvers">租户解析器列表</param>
        public void Add(IList<ITenantResolver> resolvers)
        {
            if (resolvers == null)
                return;
            foreach (var resolver in resolvers)
                Add(resolver);
        }

        /// <summary>
        /// 移除租户解析器
        /// </summary>
        /// <typeparam name="TResolver">租户解析器类型</typeparam>
        public void Remove<TResolver>() where TResolver : ITenantResolver
        {
            var key = typeof(TResolver).FullName;
            Remove(key);
        }

        /// <summary>
        /// 移除租户解析器
        /// </summary>
        /// <param name="key">租户解析器键名</param>
        public void Remove(string key)
        {
            if (key.IsEmpty())
                return;
            _resolvers.Remove(key);
        }

        /// <summary>
        /// 清空租户解析器
        /// </summary>
        public void Clear()
        {
            _resolvers.Clear();
        }
    }

    #endregion
}

