    public interface ICompareChange<in T> where T : IDomainObject
    {
        /// <summary>
        /// 获取变更属性
        /// </summary>
        /// <param name="other">其它领域对象</param>
        ChangeValueCollection GetChanges(T other);
    }

    /// <summary>
    /// 键列表比较器
    /// </summary>
    /// <typeparam name="TKey">标识类型</typeparam>
    public class KeyListComparator<TKey>
    {
        /// <summary>
        /// 比较
        /// </summary>
        /// <param name="newList">新实体集合</param>
        /// <param name="originalList">旧实体集合</param>
        public KeyListCompareResult<TKey> Compare(IEnumerable<TKey> newList, IEnumerable<TKey> originalList)
        {
            newList.CheckNull(nameof(newList));
            originalList.CheckNull(nameof(originalList));
            var newEntities = newList.ToList();
            var originalEntities = originalList.ToList();
            var createList = GetCreateList(newEntities, originalEntities);
            var updateList = GetUpdateList(newEntities, originalEntities);
            var deleteList = GetDeleteList(newEntities, originalEntities);
            return new KeyListCompareResult<TKey>(createList, updateList, deleteList);
        }

        /// <summary>
        /// 获取创建列表
        /// </summary>
        private List<TKey> GetCreateList(List<TKey> newList, List<TKey> originalList)
        {
            var result = newList.Except(originalList);
            return result.ToList();
        }

        /// <summary>
        /// 获取更新列表
        /// </summary>
        private List<TKey> GetUpdateList(List<TKey> newList, List<TKey> originalList)
        {
            return newList.FindAll(id => originalList.Exists(t => t.Equals(id)));
        }

        /// <summary>
        /// 获取删除列表
        /// </summary>
        private List<TKey> GetDeleteList(List<TKey> newList, List<TKey> originalList)
        {
            var result = originalList.Except(newList);
            return result.ToList();
        }
    }

    /// <summary>
    /// 键列表比较结果
    /// </summary>
    public class KeyListCompareResult<TKey>
    {
        /// <summary>
        /// 初始化键列表比较结果
        /// </summary>
        /// <param name="createList">创建列表</param>
        /// <param name="updateList">更新列表</param>
        /// <param name="deleteList">删除列表</param>
        public KeyListCompareResult(List<TKey> createList, List<TKey> updateList, List<TKey> deleteList)
        {
            CreateList = createList;
            UpdateList = updateList;
            DeleteList = deleteList;
        }

        /// <summary>
        /// 创建列表
        /// </summary>
        public List<TKey> CreateList { get; }

        /// <summary>
        /// 更新列表
        /// </summary>
        public List<TKey> UpdateList { get; }

        /// <summary>
        /// 删除列表
        /// </summary>
        public List<TKey> DeleteList { get; }
    }

    /// <summary>
    /// 实体列表比较器
    /// </summary>
    /// <typeparam name="TEntity">实体类型</typeparam>
    /// <typeparam name="TKey">标识类型</typeparam>
    public class ListComparator<TEntity, TKey> where TEntity : IKey<TKey>
    {
        /// <summary>
        /// 比较
        /// </summary>
        /// <param name="newList">新实体集合</param>
        /// <param name="originalList">旧实体集合</param>
        public ListCompareResult<TEntity, TKey> Compare(IEnumerable<TEntity> newList, IEnumerable<TEntity> originalList)
        {
            newList.CheckNull(nameof(newList));
            originalList.CheckNull(nameof(originalList));
            var newEntities = newList.ToList();
            var originalEntities = originalList.ToList();
            var createList = GetCreateList(newEntities, originalEntities);
            var updateList = GetUpdateList(newEntities, originalEntities);
            var deleteList = GetDeleteList(newEntities, originalEntities);
            return new ListCompareResult<TEntity, TKey>(createList, updateList, deleteList);
        }

        /// <summary>
        /// 获取创建列表
        /// </summary>
        private List<TEntity> GetCreateList(List<TEntity> newList, List<TEntity> originalList)
        {
            var result = newList.Except(originalList);
            return result.ToList();
        }

        /// <summary>
        /// 获取更新列表
        /// </summary>
        private List<TEntity> GetUpdateList(List<TEntity> newList, List<TEntity> originalList)
        {
            return newList.FindAll(entity => originalList.Exists(t => t.Id.Equals(entity.Id)));
        }

        /// <summary>
        /// 获取删除列表
        /// </summary>
        private List<TEntity> GetDeleteList(List<TEntity> newList, List<TEntity> originalList)
        {
            var result = originalList.Except(newList);
            return result.ToList();
        }
    }

    /// <summary>
    /// 列表比较结果
    /// </summary>
    public class ListCompareResult<TEntity, TKey> where TEntity : IKey<TKey>
    {
        /// <summary>
        /// 初始化列表比较结果
        /// </summary>
        /// <param name="createList">创建列表</param>
        /// <param name="updateList">更新列表</param>
        /// <param name="deleteList">删除列表</param>
        public ListCompareResult(List<TEntity> createList, List<TEntity> updateList, List<TEntity> deleteList)
        {
            CreateList = createList;
            UpdateList = updateList;
            DeleteList = deleteList;
        }

        /// <summary>
        /// 创建列表
        /// </summary>
        public List<TEntity> CreateList { get; }

        /// <summary>
        /// 更新列表
        /// </summary>
        public List<TEntity> UpdateList { get; }

        /// <summary>
        /// 删除列表
        /// </summary>
        public List<TEntity> DeleteList { get; }
    }

