    /// <summary>
    /// 聚合根
    /// </summary>
    /// <typeparam name="TEntity">实体类型</typeparam>
    public abstract class AggregateRoot<TEntity> : AggregateRoot<TEntity, Guid> where TEntity : IAggregateRoot<TEntity, Guid>
    {
        /// <summary>
        /// 初始化聚合根
        /// </summary>
        /// <param name="id">标识</param>
        protected AggregateRoot(Guid id) : base(id)
        {
        }
    }

    /// <summary>
    /// 聚合根
    /// </summary>
    /// <typeparam name="TEntity">实体类型</typeparam>
    /// <typeparam name="TKey">标识类型</typeparam>
    public abstract class AggregateRoot<TEntity, TKey> : EntityBase<TEntity, TKey>, IAggregateRoot<TEntity, TKey>, IDomainEventManager where TEntity : IAggregateRoot<TEntity, TKey>
    {
        /// <summary>
        /// 领域事件列表
        /// </summary>
        private List<IEvent> _domainEvents;

        /// <summary>
        /// 初始化聚合根
        /// </summary>
        /// <param name="id">标识</param>
        protected AggregateRoot(TKey id) : base(id)
        {
        }

        /// <summary>
        /// 版本号
        /// </summary>
        public byte[] Version { get; set; }

        /// <inheritdoc />
        [NotMapped]
        public IReadOnlyCollection<IEvent> DomainEvents => _domainEvents?.AsReadOnly();

        /// <inheritdoc />
        public void AddDomainEvent(IEvent @event)
        {
            if (@event == null)
                return;
            _domainEvents ??= new List<IEvent>();
            _domainEvents.Add(@event);
        }

        /// <inheritdoc />
        public void RemoveDomainEvent(IEvent @event)
        {
            if (@event == null)
                return;
            _domainEvents?.Remove(@event);
        }

        /// <inheritdoc />
        public void ClearDomainEvents()
        {
            _domainEvents?.Clear();
        }
    }

    /// <summary>
    /// 领域对象基类
    /// </summary>
    public abstract class DomainObjectBase<T> : IDomainObject, ICompareChange<T> where T : IDomainObject
    {

        #region 字段

        /// <summary>
        /// 验证规则集合
        /// </summary>
        private readonly List<IValidationRule> _rules;
        /// <summary>
        /// 验证处理器
        /// </summary>
        private IValidationHandler _handler;
        /// <summary>
        /// 变更值集合
        /// </summary>
        private ChangeValueCollection _changeValues;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化领域对象基类
        /// </summary>
        protected DomainObjectBase()
        {
            _rules = new List<IValidationRule>();
            _handler = new ThrowHandler();
        }

        #endregion

        #region Validate(验证)

        /// <summary>
        /// 设置验证处理器
        /// </summary>
        /// <param name="handler">验证处理器</param>
        public void SetValidationHandler(IValidationHandler handler)
        {
            if (handler == null)
                return;
            _handler = handler;
        }

        /// <summary>
        /// 添加验证规则列表
        /// </summary>
        /// <param name="rules">验证规则列表</param>
        public void AddValidationRules(IEnumerable<IValidationRule> rules)
        {
            if (rules == null)
                return;
            foreach (var rule in rules)
                AddValidationRule(rule);
        }

        /// <summary>
        /// 添加验证规则
        /// </summary>
        /// <param name="rule">验证规则</param>
        public void AddValidationRule(IValidationRule rule)
        {
            if (rule == null)
                return;
            _rules.Add(rule);
        }

        /// <summary>
        /// 验证
        /// </summary>
        public virtual ValidationResultCollection Validate()
        {
            var result = GetValidationResults();
            HandleValidationResults(result);
            return result;
        }

        /// <summary>
        /// 获取验证结果
        /// </summary>
        private ValidationResultCollection GetValidationResults()
        {
            var result = DataAnnotationValidation.Validate(this);
            Validate(result);
            foreach (var rule in _rules)
                result.Add(rule.Validate());
            return result;
        }

        /// <summary>
        /// 自定义验证钩子方法
        /// </summary>
        /// <param name="results">验证结果集合</param>
        protected virtual void Validate(ValidationResultCollection results)
        {
        }

        /// <summary>
        /// 处理验证结果
        /// </summary>
        protected virtual void HandleValidationResults(ValidationResultCollection results)
        {
            if (results.IsValid)
                return;
            _handler.Handle(results);
        }

        #endregion

        #region GetChanges(获取变更属性)

        /// <summary>
        /// 获取变更属性
        /// </summary>
        /// <param name="newEntity">新对象</param>
        public ChangeValueCollection GetChanges(T newEntity)
        {
            if (Equals(newEntity, null))
                return new ChangeValueCollection();
            _changeValues = CreateChangeValueCollection(newEntity);
            AddChanges(newEntity);
            return _changeValues;
        }

        /// <summary>
        /// 创建变更值集合
        /// </summary>
        protected virtual ChangeValueCollection CreateChangeValueCollection(T newEntity)
        {
            var description = Util.Helpers.Reflection.GetDisplayNameOrDescription(newEntity.GetType());
            return new ChangeValueCollection(newEntity.GetType().ToString(), description);
        }

        /// <summary>
        /// 添加变更列表
        /// </summary>
        /// <param name="newEntity">新对象</param>
        protected virtual void AddChanges(T newEntity)
        {
        }

        /// <summary>
        /// 添加变更
        /// </summary>
        /// <param name="expression">属性表达式,范例：t => t.Name</param>
        /// <param name="newValue">新值,范例：newEntity.Name</param>
        protected void AddChange<TProperty, TValue>(Expression<Func<T, TProperty>> expression, TValue newValue)
        {
            var member = Util.Helpers.Lambda.GetMemberExpression(expression);
            var name = Util.Helpers.Lambda.GetMemberName(member);
            var description = Util.Helpers.Reflection.GetDisplayNameOrDescription(member.Member);
            var value = member.Member.GetPropertyValue(this);
            AddChange(name, description, Util.Helpers.Convert.To<TValue>(value), newValue);
        }

        /// <summary>
        /// 添加变更
        /// </summary>
        /// <param name="propertyName">属性名</param>
        /// <param name="description">描述</param>
        /// <param name="oldValue">旧值,范例：this.Name</param>
        /// <param name="newValue">新值,范例：newEntity.Name</param>
        protected void AddChange<TValue>(string propertyName, string description, TValue oldValue, TValue newValue)
        {
            if (Equals(oldValue, newValue))
                return;
            string oldValueString = oldValue.SafeString().ToLower().Trim();
            string newValueString = newValue.SafeString().ToLower().Trim();
            if (oldValueString == newValueString)
                return;
            _changeValues.Add(propertyName, description, oldValueString, newValueString);
        }

        /// <summary>
        /// 添加变更
        /// </summary>
        /// <param name="oldObject">旧对象</param>
        /// <param name="newObject">新对象</param>
        protected void AddChange<TDomainObject>(ICompareChange<TDomainObject> oldObject, TDomainObject newObject) where TDomainObject : IDomainObject
        {
            if (Equals(oldObject, null))
                return;
            if (Equals(newObject, null))
                return;
            _changeValues.AddRange(oldObject.GetChanges(newObject));
        }

        /// <summary>
        /// 添加变更
        /// </summary>
        /// <param name="oldObjects">旧对象列表</param>
        /// <param name="newObjects">新对象列表</param>
        protected void AddChange<TDomainObject>(IEnumerable<ICompareChange<TDomainObject>> oldObjects, IEnumerable<TDomainObject> newObjects) where TDomainObject : IDomainObject
        {
            if (Equals(oldObjects, null))
                return;
            if (Equals(newObjects, null))
                return;
            var oldList = oldObjects.ToList();
            var newList = newObjects.ToList();
            for (int i = 0; i < oldList.Count; i++)
            {
                if (newList.Count <= i)
                    return;
                AddChange(oldList[i], newList[i]);
            }
        }

        #endregion
    }

    /// <summary>
    /// 领域实体
    /// </summary>
    /// <typeparam name="TEntity">实体类型</typeparam>
    public abstract class EntityBase<TEntity> : EntityBase<TEntity, Guid> where TEntity : IEntity<TEntity, Guid>
    {
        /// <summary>
        /// 初始化领域实体
        /// </summary>
        /// <param name="id">标识</param>
        protected EntityBase(Guid id) : base(id)
        {
        }
    }

    /// <summary>
    /// 领域实体
    /// </summary>
    /// <typeparam name="TEntity">实体类型</typeparam>
    /// <typeparam name="TKey">标识类型</typeparam>
    public abstract class EntityBase<TEntity, TKey> : DomainObjectBase<TEntity>, IEntity<TEntity, TKey> where TEntity : IEntity<TEntity, TKey>
    {
        /// <summary>
        /// 初始化领域实体
        /// </summary>
        /// <param name="id">标识</param>
        protected EntityBase(TKey id)
        {
            Id = id;
            ExtraProperties = new ExtraPropertyDictionary();
        }

        /// <summary>
        /// 标识
        /// </summary>
        [Key]
        public TKey Id { get; private set; }

        /// <summary>
        /// 扩展属性集合
        /// </summary>
        protected ExtraPropertyDictionary ExtraProperties { get; set; }

        /// <summary>
        /// 相等运算
        /// </summary>
        public override bool Equals(object other)
        {
            return this == (other as EntityBase<TEntity, TKey>);
        }

        /// <summary>
        /// 获取哈希
        /// </summary>
        public override int GetHashCode()
        {
            return ReferenceEquals(Id, null) ? 0 : Id.GetHashCode();
        }

        /// <summary>
        /// 相等比较
        /// </summary>
        public static bool operator ==(EntityBase<TEntity, TKey> left, EntityBase<TEntity, TKey> right)
        {
            if ((object)left == null && (object)right == null)
                return true;
            if (!(left is TEntity) || !(right is TEntity))
                return false;
            if (Equals(left.Id, null))
                return false;
            if (left.Id.Equals(default(TKey)))
                return false;
            return left.Id.Equals(right.Id);
        }

        /// <summary>
        /// 不相等比较
        /// </summary>
        public static bool operator !=(EntityBase<TEntity, TKey> left, EntityBase<TEntity, TKey> right)
        {
            return !(left == right);
        }

        /// <summary>
        /// 创建变更值集合
        /// </summary>
        protected override ChangeValueCollection CreateChangeValueCollection(TEntity newEntity)
        {
            var description = Util.Helpers.Reflection.GetDisplayNameOrDescription(newEntity.GetType());
            return new ChangeValueCollection(newEntity.GetType().ToString(), description, newEntity.Id.SafeString());
        }

        /// <summary>
        /// 初始化
        /// </summary>
        public virtual void Init()
        {
            InitId();
        }

        /// <summary>
        /// 初始化标识
        /// </summary>
        protected virtual void InitId()
        {
            if (typeof(TKey) == typeof(int) || typeof(TKey) == typeof(long))
                return;
            if (string.IsNullOrWhiteSpace(Id.SafeString()) || Id.Equals(default(TKey)))
                Id = CreateId();
        }

        /// <summary>
        /// 创建标识
        /// </summary>
        protected virtual TKey CreateId()
        {
            return Util.Helpers.Convert.To<TKey>(Guid.NewGuid());
        }

        /// <summary>
        /// 验证
        /// </summary>
        protected override void Validate(ValidationResultCollection results)
        {
            ValidateId(results);
        }

        /// <summary>
        /// 验证标识
        /// </summary>
        protected virtual void ValidateId(ValidationResultCollection results)
        {
            if (typeof(TKey) == typeof(int) || typeof(TKey) == typeof(long))
                return;
            if (string.IsNullOrWhiteSpace(Id.SafeString()) || Id.Equals(default(TKey)))
                results.Add(new ValidationResult(R.IdIsEmpty));
        }

        /// <summary>
        /// 克隆副本
        /// </summary>
        public virtual TEntity Clone()
        {
            return this.MapTo<TEntity>();
        }
    }

