    /// <summary>
    /// 树形实体
    /// </summary>
    /// <typeparam name="TEntity">实体类型</typeparam>
    /// <typeparam name="TKey">实体标识类型</typeparam>
    /// <typeparam name="TParentId">父标识类型</typeparam>
    public interface ITreeEntity<TEntity, TKey, TParentId> : IAggregateRoot<TEntity, TKey>, IParentId<TParentId>, IPath, IEnabled, ISortId where TEntity : ITreeEntity<TEntity, TKey, TParentId>
    {
        /// <summary>
        /// 初始化路径
        /// </summary>
        void InitPath();
        /// <summary>
        /// 初始化路径
        /// </summary>
        /// <param name="parent">父节点</param>
        void InitPath(TEntity parent);
        /// <summary>
        /// 从路径中获取所有上级节点标识
        /// </summary>
        /// <param name="excludeSelf">是否排除当前节点,默认排除自身</param>
        List<TKey> GetParentIdsFromPath(bool excludeSelf = true);
    }

    /// <summary>
    /// 树形仓储
    /// </summary>
    /// <typeparam name="TEntity">实体类型</typeparam>
    public interface ITreeRepository<TEntity> : ITreeRepository<TEntity, Guid, Guid?> where TEntity : class, ITreeEntity<TEntity, Guid, Guid?>
    {
    }

    /// <summary>
    /// 树形仓储
    /// </summary>
    /// <typeparam name="TEntity">实体类型</typeparam>
    /// <typeparam name="TKey">实体标识类型</typeparam>
    /// <typeparam name="TParentId">父标识类型</typeparam>
    public interface ITreeRepository<TEntity, in TKey, in TParentId> : IRepository<TEntity, TKey>
        where TEntity : class, ITreeEntity<TEntity, TKey, TParentId>
    {
        /// <summary>
        /// 获取全部下级实体
        /// </summary>
        /// <param name="parent">父实体</param>
        Task<List<TEntity>> GetAllChildrenAsync(TEntity parent);
    }

    /// <summary>
    /// 树形实体
    /// </summary>
    /// <typeparam name="TEntity">树形实体类型</typeparam>
    public abstract class TreeEntityBase<TEntity> : TreeEntityBase<TEntity, Guid, Guid?> where TEntity : ITreeEntity<TEntity, Guid, Guid?>
    {
        /// <summary>
        /// 初始化树形实体
        /// </summary>
        /// <param name="id">标识</param>
        /// <param name="path">路径</param>
        /// <param name="level">层级</param>
        protected TreeEntityBase(Guid id, string path, int level)
            : base(id, path, level)
        {
        }
    }

    /// <summary>
    /// 树形实体
    /// </summary>
    /// <typeparam name="TEntity">树形实体类型</typeparam>
    /// <typeparam name="TKey">标识类型</typeparam>
    /// <typeparam name="TParentId">父标识类型</typeparam>
    public abstract class TreeEntityBase<TEntity, TKey, TParentId> : AggregateRoot<TEntity, TKey>, ITreeEntity<TEntity, TKey, TParentId> where TEntity : ITreeEntity<TEntity, TKey, TParentId>
    {
        /// <summary>
        /// 初始化树形实体
        /// </summary>
        /// <param name="id">标识</param>
        /// <param name="path">路径</param>
        /// <param name="level">层级</param>
        protected TreeEntityBase(TKey id, string path, int level)
            : base(id)
        {
            Path = path;
            Level = level;
        }

        /// <summary>
        /// 父标识
        /// </summary>
        public TParentId ParentId { get; set; }

        /// <summary>
        /// 路径
        /// </summary>
        public virtual string Path { get; private set; }

        /// <summary>
        /// 层级
        /// </summary>
        public int Level { get; private set; }

        /// <summary>
        /// 启用
        /// </summary>
        public bool Enabled { get; set; }

        /// <summary>
        /// 排序号
        /// </summary>
        public int? SortId { get; set; }

        /// <summary>
        /// 初始化路径
        /// </summary>
        public virtual void InitPath()
        {
            InitPath(default);
        }

        /// <summary>
        /// 初始化路径
        /// </summary>
        /// <param name="parent">父节点</param>
        public virtual void InitPath(TEntity parent)
        {
            if (Equals(parent, null))
            {
                Level = 1;
                Path = $"{Id},";
                return;
            }
            Level = parent.Level + 1;
            Path = $"{parent.Path}{Id},";
        }

        /// <summary>
        /// 从路径中获取所有上级节点标识
        /// </summary>
        /// <param name="excludeSelf">是否排除当前节点,默认排除自身</param>
        public List<TKey> GetParentIdsFromPath(bool excludeSelf = true)
        {
            if (Path.IsEmpty())
                return new List<TKey>();
            var result = Path.Split(',').Where(id => !id.IsEmpty() && id != ",").ToList();
            if (excludeSelf)
                result = result.Where(id => id.SafeString().ToUpperInvariant() != Id.SafeString().ToUpperInvariant()).ToList();
            return result.Select(Util.Helpers.Convert.To<TKey>).ToList();
        }
    }

    /// <summary>
    /// 树形路径更新服务
    /// </summary>
    public class UpdatePathManager<TEntity, TKey, TParentId>
        where TEntity : class, ITreeEntity<TEntity, TKey, TParentId>
    {
        /// <summary>
        /// 仓储
        /// </summary>
        private readonly ITreeRepository<TEntity, TKey, TParentId> _repository;

        /// <summary>
        /// 初始化树型路径更新服务
        /// </summary>
        /// <param name="repository">仓储</param>
        public UpdatePathManager(ITreeRepository<TEntity, TKey, TParentId> repository)
        {
            _repository = repository;
        }

        /// <summary>
        /// 更新实体及所有下级节点路径
        /// </summary>
        /// <param name="entity">实体</param>
        public async Task UpdatePathAsync(TEntity entity)
        {
            entity.CheckNull(nameof(entity));
            if (entity.ParentId.Equals(entity.Id))
                throw new Warning(DomainResource.NotSupportMoveToChildren);
            var old = await _repository.NoTracking().FindByIdAsync(entity.Id);
            if (old == null)
                return;
            if (entity.ParentId.Equals(old.ParentId))
                return;
            var children = await _repository.GetAllChildrenAsync(entity);
            if (children.Exists(t => t.Id.Equals(entity.ParentId)))
                throw new Warning(DomainResource.NotSupportMoveToChildren);
            var parent = await _repository.FindByIdAsync(entity.ParentId);
            entity.InitPath(parent);
            UpdateChildrenPath(entity, children);
            await _repository.UpdateAsync(children);
        }

        /// <summary>
        /// 修改路径
        /// </summary>
        private void UpdateChildrenPath(TEntity parent, List<TEntity> children)
        {
            if (parent == null || children == null)
                return;
            var list = children.Where(t => t.ParentId.Equals(parent.Id)).ToList();
            foreach (var child in list)
            {
                child.InitPath(parent);
                UpdateChildrenPath(child, children);
            }
        }
    }

    #endregion

    /// <summary>
    /// 扩展属性字典扩展
    /// </summary>
    public static class ExtraPropertyDictionaryExtensions
    {
        /// <summary>
        /// 获取属性
        /// </summary>
        /// <param name="source">扩展属性字典</param>
        /// <param name="name">属性名</param>
        public static TProperty GetProperty<TProperty>(this ExtraPropertyDictionary source, string name)
        {
            source.CheckNull(nameof(source));
            if (source.TryGetValue(name, out var value) == false)
                return default;
            if (value is JsonElement element)
                return Util.Helpers.Json.ToObject<TProperty>(Util.Helpers.Json.ToJson(element));
            return Util.Helpers.Convert.To<TProperty>(value);
        }

        /// <summary>
        /// 设置属性,如果存在则先移除旧属性,当值为null时移除该属性
        /// </summary>
        /// <param name="source">扩展属性字典</param>
        /// <param name="name">属性名</param>
        /// <param name="value">属性值</param>
        public static ExtraPropertyDictionary SetProperty(this ExtraPropertyDictionary source, string name, object value)
        {
            source.CheckNull(nameof(source));
            source.RemoveProperty(name);
            if (value == null)
                return source;
            source[name] = GetPropertyValue(source, value);
            return source;
        }

        /// <summary>
        /// 获取属性值
        /// </summary>
        private static object GetPropertyValue(ExtraPropertyDictionary source, object value)
        {
            if (value is string && source.IsTrimString)
                return value.SafeString();
            if (value is DateTime dateValue)
                return Time.Normalize(dateValue);
            return value;
        }

        /// <summary>
        /// 移除属性
        /// </summary>
        /// <param name="source">扩展属性字典</param>
        /// <param name="name">属性名</param>
        public static ExtraPropertyDictionary RemoveProperty(this ExtraPropertyDictionary source, string name)
        {
            source.CheckNull(nameof(source));
            if (source.ContainsKey(name))
                source.Remove(name);
            return source;
        }
    }

    /// <summary>
    /// 树形仓储扩展
    /// </summary>
    public static class ITreeRepositoryExtensions
    {
        /// <summary>
        /// 更新实体及所有下级节点路径
        /// </summary>
        /// <param name="repository">仓储</param>
        /// <param name="entity">实体</param>
        public static async Task UpdatePathAsync<TEntity, TKey, TParentId>(this ITreeRepository<TEntity, TKey, TParentId> repository, TEntity entity)
            where TEntity : class, ITreeEntity<TEntity, TKey, TParentId>
        {
            var manager = new UpdatePathManager<TEntity, TKey, TParentId>(repository);
            await manager.UpdatePathAsync(entity);
        }

        /// <summary>
        /// 获取缺失的父标识列表
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// <param name="entities">实体列表</param>
        public static List<string> GetMissingParentIds<TEntity>(this IEnumerable<TEntity> entities) where TEntity : class, ITreeEntity<TEntity, Guid, Guid?>
        {
            return GetMissingParentIds<TEntity, Guid, Guid?>(entities);
        }

        /// <summary>
        /// 获取缺失的父标识列表
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// /// <typeparam name="TKey">标识类型</typeparam>
        /// <typeparam name="TParentId">父标识类型</typeparam>
        /// <param name="entities">实体列表</param>
        public static List<string> GetMissingParentIds<TEntity, TKey, TParentId>(this IEnumerable<TEntity> entities) where TEntity : class, ITreeEntity<TEntity, TKey, TParentId>
        {
            var result = new List<string>();
            if (entities == null)
                return result;
            var list = entities.ToList();
            list.ForEach(entity =>
            {
                if (entity == null)
                    return;
                result.AddRange(entity.GetParentIdsFromPath().Select(t => t.SafeString()));
            });
            var ids = list.Select(t => t?.Id.SafeString());
            return result.Except(ids).ToList();
        }
    }

    /// <summary>
    /// 列表比较器扩展
    /// </summary>
    public static class ListCompareExtensions
    {
        /// <summary>
        /// 比较
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// <param name="newList">新实体集合</param>
        /// <param name="originalList">旧实体集合</param>
        public static ListCompareResult<TEntity, Guid> Compare<TEntity>(this IEnumerable<TEntity> newList, IEnumerable<TEntity> originalList)
            where TEntity : IKey<Guid>
        {
            return Compare<TEntity, Guid>(newList, originalList);
        }

        /// <summary>
        /// 比较
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// <typeparam name="TKey">标识类型</typeparam>
        /// <param name="newList">新实体集合</param>
        /// <param name="originalList">旧实体集合</param>
        public static ListCompareResult<TEntity, TKey> Compare<TEntity, TKey>(this IEnumerable<TEntity> newList, IEnumerable<TEntity> originalList)
            where TEntity : IKey<TKey>
        {
            var comparator = new ListComparator<TEntity, TKey>();
            return comparator.Compare(newList, originalList);
        }

        /// <summary>
        /// 比较
        /// </summary>
        /// <param name="newList">新实体标识集合</param>
        /// <param name="originalList">旧实体标识集合</param>
        public static KeyListCompareResult<Guid> Compare(this IEnumerable<Guid> newList, IEnumerable<Guid> originalList)
        {
            var comparator = new KeyListComparator<Guid>();
            return comparator.Compare(newList, originalList);
        }

        /// <summary>
        /// 比较
        /// </summary>
        /// <param name="newList">新实体标识集合</param>
        /// <param name="originalList">旧实体标识集合</param>
        public static KeyListCompareResult<string> Compare(this IEnumerable<string> newList, IEnumerable<string> originalList)
        {
            var comparator = new KeyListComparator<string>();
            return comparator.Compare(newList, originalList);
        }

        /// <summary>
        /// 比较
        /// </summary>
        /// <param name="newList">新实体标识集合</param>
        /// <param name="originalList">旧实体标识集合</param>
        public static KeyListCompareResult<int> Compare(this IEnumerable<int> newList, IEnumerable<int> originalList)
        {
            var comparator = new KeyListComparator<int>();
            return comparator.Compare(newList, originalList);
        }

        /// <summary>
        /// 比较
        /// </summary>
        /// <param name="newList">新实体标识集合</param>
        /// <param name="originalList">旧实体标识集合</param>
        public static KeyListCompareResult<long> Compare(this IEnumerable<long> newList, IEnumerable<long> originalList)
        {
            var comparator = new KeyListComparator<long>();
            return comparator.Compare(newList, originalList);
        }
    }

