    /// <summary>
    /// 数据过滤器
    /// </summary>
    public interface IFilter : ITransientDependency
    {
        /// <summary>
        /// 过滤器是否启用
        /// </summary>
        bool IsEnabled { get; }
        /// <summary>
        /// 实体是否启用过滤器
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        bool IsEntityEnabled<TEntity>();
        /// <summary>
        /// 启用
        /// </summary>
        void Enable();
        /// <summary>
        /// 禁用
        /// </summary>
        IDisposable Disable();
        /// <summary>
        /// 获取过滤表达式
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// <param name="state">参数</param>
        Expression<Func<TEntity, bool>> GetExpression<TEntity>(object state) where TEntity : class;
    }

    /// <summary>
    /// 数据过滤器
    /// </summary>
    /// <typeparam name="TFilterType">过滤器类型</typeparam>
    public interface IFilter<TFilterType> : IFilter where TFilterType : class
    {
    }

    /// <summary>
    /// 数据过滤器管理器
    /// </summary>
    public interface IFilterManager : IFilterSwitch, IScopeDependency
    {
        /// <summary>
        /// 获取过滤器
        /// </summary>
        /// <typeparam name="TFilterType">过滤器类型</typeparam>
        IFilter GetFilter<TFilterType>() where TFilterType : class;
        /// <summary>
        /// 获取过滤器
        /// </summary>
        /// <param name="filterType">过滤器类型</param>
        IFilter GetFilter(Type filterType);
        /// <summary>
        /// 实体是否启用过滤器
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        bool IsEntityEnabled<TEntity>();
        /// <summary>
        /// 过滤器是否启用
        /// </summary>
        /// <typeparam name="TFilterType">过滤器类型</typeparam>
        bool IsEnabled<TFilterType>() where TFilterType : class;
        /// <summary>
        /// 获取过滤表达式
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// <param name="state">参数</param>
        Expression<Func<TEntity, bool>> GetExpression<TEntity>(object state) where TEntity : class;
    }

    /// <summary>
    /// 数据过滤器开关
    /// </summary>
    public interface IFilterSwitch
    {
        /// <summary>
        /// 启用过滤器
        /// </summary>
        /// <typeparam name="TFilterType">过滤器类型</typeparam>
        void EnableFilter<TFilterType>() where TFilterType : class;
        /// <summary>
        /// 禁用过滤器
        /// </summary>
        /// <typeparam name="TFilterType">过滤器类型</typeparam>
        IDisposable DisableFilter<TFilterType>() where TFilterType : class;
    }

