    /// <summary>
    /// OrIfNotEmpty条件
    /// </summary>
    /// <typeparam name="TEntity">实体类型</typeparam>
    public class OrIfNotEmptyCondition<TEntity> : ICondition<TEntity>
    {
        /// <summary>
        /// 查询条件列表
        /// </summary>
        private readonly List<Expression<Func<TEntity, bool>>> _conditions;

        /// <summary>
        /// WhereIfNotEmpty条件
        /// </summary>
        /// <param name="condition1">查询条件1</param>
        /// <param name="condition2">查询条件2</param>
        /// <param name="conditions">查询条件列表</param>
        public OrIfNotEmptyCondition(Expression<Func<TEntity, bool>> condition1, Expression<Func<TEntity, bool>> condition2, params Expression<Func<TEntity, bool>>[] conditions)
        {
            _conditions = new List<Expression<Func<TEntity, bool>>> { condition1, condition2 };
            _conditions.AddRange(conditions);
        }

        /// <summary>
        /// 获取查询条件
        /// </summary>
        public Expression<Func<TEntity, bool>> GetCondition()
        {
            Expression<Func<TEntity, bool>> result = null;
            foreach (var condition in _conditions)
            {
                var predicate = new WhereIfNotEmptyCondition<TEntity>(condition).GetCondition();
                if (predicate == null)
                    continue;
                result = result.Or(predicate);
            }
            return result;
        }
    }

    /// <summary>
    /// 范围过滤条件
    /// </summary>
    /// <typeparam name="TEntity">实体类型</typeparam>
    /// <typeparam name="TProperty">属性类型</typeparam>
    /// <typeparam name="TValue">值类型</typeparam>
    public abstract class SegmentConditionBase<TEntity, TProperty, TValue> : ICondition<TEntity>
        where TEntity : class
        where TValue : struct
    {
        /// <summary>
        /// 属性表达式
        /// </summary>
        private readonly Expression<Func<TEntity, TProperty>> _propertyExpression;
        /// <summary>
        /// 表达式生成器
        /// </summary>
        private readonly PredicateExpressionBuilder<TEntity> _builder;
        /// <summary>
        /// 最小值
        /// </summary>
        private TValue? _min;
        /// <summary>
        /// 最大值
        /// </summary>
        private TValue? _max;
        /// <summary>
        /// 包含边界
        /// </summary>
        private readonly Boundary _boundary;

        /// <summary>
        /// 初始化范围过滤条件
        /// </summary>
        /// <param name="propertyExpression">属性表达式</param>
        /// <param name="min">最小值</param>
        /// <param name="max">最大值</param>
        /// <param name="boundary">包含边界</param>
        protected SegmentConditionBase(Expression<Func<TEntity, TProperty>> propertyExpression, TValue? min, TValue? max, Boundary boundary)
        {
            _builder = new PredicateExpressionBuilder<TEntity>();
            _propertyExpression = propertyExpression;
            _min = min;
            _max = max;
            _boundary = boundary;
        }

        /// <summary>
        /// 获取属性类型
        /// </summary>
        protected Type GetPropertyType()
        {
            return Lambda.GetType(_propertyExpression);
        }

        /// <summary>
        /// 获取边界
        /// </summary>
        protected Boundary GetBoundary()
        {
            return _boundary;
        }

        /// <summary>
        /// 获取查询条件
        /// </summary>
        public Expression<Func<TEntity, bool>> GetCondition()
        {
            _builder.Clear();
            Adjust(_min, _max);
            CreateLeftExpression();
            CreateRightExpression();
            return _builder.ToLambda();
        }

        /// <summary>
        /// 当最小值大于最大值时进行校正
        /// </summary>
        private void Adjust(TValue? min, TValue? max)
        {
            if (IsMinGreaterMax(min, max) == false)
                return;
            _min = max;
            _max = min;
        }

        /// <summary>
        /// 最小值是否大于最大值
        /// </summary>
        /// <param name="min">最小值</param>
        /// <param name="max">最大值</param>
        protected abstract bool IsMinGreaterMax(TValue? min, TValue? max);

        /// <summary>
        /// 创建左操作数，即 t => t.Property >= Min
        /// </summary>
        private void CreateLeftExpression()
        {
            if (_min == null)
                return;
            var minValueExpression = GetMinValueExpression();
            var expression = Expression.Convert(minValueExpression, GetPropertyType());
            _builder.Append(_propertyExpression, CreateLeftOperator(_boundary), expression);
        }

        /// <summary>
        /// 创建左操作符
        /// </summary>
        protected virtual Operator CreateLeftOperator(Boundary? boundary)
        {
            switch (boundary)
            {
                case Boundary.Left:
                    return Operator.GreaterEqual;
                case Boundary.Both:
                    return Operator.GreaterEqual;
                default:
                    return Operator.Greater;
            }
        }

        /// <summary>
        /// 获取最小值
        /// </summary>
        protected TValue? GetMinValue()
        {
            return _min;
        }

        /// <summary>
        /// 获取最小值表达式
        /// </summary>
        protected virtual Expression GetMinValueExpression()
        {
            return Lambda.Constant(_min, _propertyExpression);
        }

        /// <summary>
        /// 创建右操作数，即 t => t.Property &lt;= Max
        /// </summary>
        private void CreateRightExpression()
        {
            if (_max == null)
                return;
            var maxValueExpression = GetMaxValueExpression();
            var expression = Expression.Convert(maxValueExpression, GetPropertyType());
            _builder.Append(_propertyExpression, CreateRightOperator(_boundary), expression);
        }

        /// <summary>
        /// 创建右操作符
        /// </summary>
        protected virtual Operator CreateRightOperator(Boundary? boundary)
        {
            switch (boundary)
            {
                case Boundary.Right:
                    return Operator.LessEqual;
                case Boundary.Both:
                    return Operator.LessEqual;
                default:
                    return Operator.Less;
            }
        }

        /// <summary>
        /// 获取最大值
        /// </summary>
        protected TValue? GetMaxValue()
        {
            return _max;
        }

        /// <summary>
        /// 获取最大值表达式
        /// </summary>
        protected virtual Expression GetMaxValueExpression()
        {
            return Lambda.Constant(_max, _propertyExpression);
        }
    }

    /// <summary>
    /// WhereIfNotEmpty条件
    /// </summary>
    /// <typeparam name="TEntity">实体类型</typeparam>
    public class WhereIfNotEmptyCondition<TEntity> : ICondition<TEntity>
    {
        /// <summary>
        /// 查询条件
        /// </summary>
        private readonly Expression<Func<TEntity, bool>> _condition;

        /// <summary>
        /// WhereIfNotEmpty条件
        /// </summary>
        /// <param name="condition">查询条件</param>
        public WhereIfNotEmptyCondition(Expression<Func<TEntity, bool>> condition)
        {
            _condition = condition;
        }

        /// <summary>
        /// 获取查询条件
        /// </summary>
        public Expression<Func<TEntity, bool>> GetCondition()
        {
            if (_condition == null)
                return null;
            if (Lambda.GetConditionCount(_condition) > 1)
                throw new InvalidOperationException(string.Format(R.CanOnlyOneCondition, _condition));
            return _condition.Value().SafeString().IsEmpty() ? null : _condition;
        }
    }

    /// <summary>
    /// 查询边界
    /// </summary>
    public enum Boundary
    {
        /// <summary>
        /// 包含左边
        /// </summary>
        Left,
        /// <summary>
        /// 包含右边
        /// </summary>
        Right,
        /// <summary>
        /// 包含两边
        /// </summary>
        Both,
        /// <summary>
        /// 不包含
        /// </summary>
        Neither
    }

    #endregion

