    /// <summary>
    /// 查询对象扩展
    /// </summary>
    public static class QueryableExtensions
    {

        #region Where(添加查询条件对象)

        /// <summary>
        /// 添加查询条件对象
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// <param name="source">源</param>
        /// <param name="condition">查询条件</param>
        public static IQueryable<TEntity> Where<TEntity>(this IQueryable<TEntity> source, ICondition<TEntity> condition) where TEntity : class
        {
            source.CheckNull(nameof(source));
            condition.CheckNull(nameof(condition));
            var predicate = condition.GetCondition();
            if (predicate == null)
                return source;
            return source.Where(predicate);
        }

        #endregion

        #region WhereIf(根据规则添加查询条件)

        /// <summary>
        /// 根据规则添加查询条件
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// <param name="source">数据源</param>
        /// <param name="predicate">查询条件</param>
        /// <param name="condition">该值为true时添加查询条件，否则忽略</param>
        public static IQueryable<TEntity> WhereIf<TEntity>(this IQueryable<TEntity> source, Expression<Func<TEntity, bool>> predicate, bool condition) where TEntity : class
        {
            source.CheckNull(nameof(source));
            return condition ? source.Where(predicate) : source;
        }

        #endregion

        #region WhereIfNotEmpty(根据规则添加查询条件)

        /// <summary>
        /// 根据规则添加查询条件
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// <param name="source">数据源</param>
        /// <param name="condition">查询条件,如果参数值为空，则忽略该查询条件，范例：t => t.Name == ""，该查询条件被忽略。
        /// 注意：一次仅能添加一个条件，范例：t => t.Name == "a" &amp;&amp; t.Mobile == "123"，不支持，将抛出异常</param>
        public static IQueryable<TEntity> WhereIfNotEmpty<TEntity>(this IQueryable<TEntity> source, Expression<Func<TEntity, bool>> condition) where TEntity : class
        {
            source.CheckNull(nameof(source));
            return source.Where(new WhereIfNotEmptyCondition<TEntity>(condition));
        }

        #endregion

        #region OrIfNotEmpty(添加Or查询条件)

        /// <summary>
        /// 添加Or查询条件,对传入的条件使用Or连接
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// <param name="source">数据源</param>
        /// <param name="condition1">查询条件1,如果参数值为空，则忽略该查询条件，范例：t => t.Name == ""，该查询条件被忽略。
        /// 注意：一次仅能添加一个条件，范例：t => t.Name == "a" &amp;&amp; t.Mobile == "123"，不支持，将抛出异常</param>
        /// <param name="condition2">查询条件2,如果参数值为空，则忽略该查询条件，范例：t => t.Name == ""，该查询条件被忽略。
        /// 注意：一次仅能添加一个条件，范例：t => t.Name == "a" &amp;&amp; t.Mobile == "123"，不支持，将抛出异常</param>
        /// <param name="conditions">查询条件列表,如果参数值为空，则忽略该查询条件，范例：t => t.Name == ""，该查询条件被忽略。
        /// 注意：一次仅能添加一个条件，范例：t => t.Name == "a" &amp;&amp; t.Mobile == "123"，不支持，将抛出异常</param>
        public static IQueryable<TEntity> OrIfNotEmpty<TEntity>(this IQueryable<TEntity> source, Expression<Func<TEntity, bool>> condition1,
            Expression<Func<TEntity, bool>> condition2, params Expression<Func<TEntity, bool>>[] conditions) where TEntity : class
        {
            source.CheckNull(nameof(source));
            return source.Where(new OrIfNotEmptyCondition<TEntity>(condition1, condition2, conditions));
        }

        #endregion

        #region Between(添加范围查询条件)

        /// <summary>
        /// 添加范围查询条件
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// <param name="source">数据源</param>
        /// <typeparam name="TProperty">属性类型</typeparam>
        /// <param name="propertyExpression">属性表达式，范例：t => t.Age</param>
        /// <param name="min">最小值</param>
        /// <param name="max">最大值</param>
        /// <param name="boundary">包含边界</param>
        public static IQueryable<TEntity> Between<TEntity, TProperty>(this IQueryable<TEntity> source, Expression<Func<TEntity, TProperty>> propertyExpression, int? min, int? max, Boundary boundary = Boundary.Both) where TEntity : class
        {
            source.CheckNull(nameof(source));
            return source.Where(new IntSegmentCondition<TEntity, TProperty>(propertyExpression, min, max, boundary));
        }

        /// <summary>
        /// 添加范围查询条件
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// <param name="source">数据源</param>
        /// <typeparam name="TProperty">属性类型</typeparam>
        /// <param name="propertyExpression">属性表达式，范例：t => t.Age</param>
        /// <param name="min">最小值</param>
        /// <param name="max">最大值</param>
        /// <param name="boundary">包含边界</param>
        public static IQueryable<TEntity> Between<TEntity, TProperty>(this IQueryable<TEntity> source, Expression<Func<TEntity, TProperty>> propertyExpression, double? min, double? max, Boundary boundary = Boundary.Both) where TEntity : class
        {
            source.CheckNull(nameof(source));
            return source.Where(new DoubleSegmentCondition<TEntity, TProperty>(propertyExpression, min, max, boundary));
        }

        /// <summary>
        /// 添加范围查询条件
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// <param name="source">数据源</param>
        /// <typeparam name="TProperty">属性类型</typeparam>
        /// <param name="propertyExpression">属性表达式，范例：t => t.Age</param>
        /// <param name="min">最小值</param>
        /// <param name="max">最大值</param>
        /// <param name="boundary">包含边界</param>
        public static IQueryable<TEntity> Between<TEntity, TProperty>(this IQueryable<TEntity> source, Expression<Func<TEntity, TProperty>> propertyExpression, decimal? min, decimal? max, Boundary boundary = Boundary.Both) where TEntity : class
        {
            source.CheckNull(nameof(source));
            return source.Where(new DecimalSegmentCondition<TEntity, TProperty>(propertyExpression, min, max, boundary));
        }

        /// <summary>
        /// 添加范围查询条件
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// <param name="source">数据源</param>
        /// <typeparam name="TProperty">属性类型</typeparam>
        /// <param name="propertyExpression">属性表达式，范例：t => t.Time</param>
        /// <param name="min">最小值</param>
        /// <param name="max">最大值</param>
        /// <param name="includeTime">是否包含时间</param>
        /// <param name="boundary">包含边界</param>
        public static IQueryable<TEntity> Between<TEntity, TProperty>(this IQueryable<TEntity> source, Expression<Func<TEntity, TProperty>> propertyExpression, DateTime? min, DateTime? max, bool includeTime = true, Boundary boundary = Boundary.Both) where TEntity : class
        {
            if (source == null)
                throw new ArgumentNullException(nameof(source));
            if (includeTime)
                return source.Where(new DateTimeSegmentCondition<TEntity, TProperty>(propertyExpression, min, max, boundary));
            return source.Where(new DateSegmentCondition<TEntity, TProperty>(propertyExpression, min, max, boundary));
        }

        #endregion

        #region OrderBy(排序)

        /// <summary>
        /// 排序,说明:如果未设置排序条件,则使用Id排序
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// <param name="source">源</param>
        /// <param name="parameter">分页参数</param>
        /// <param name="defaultOrder">默认排序属性,如果未设置排序条件,则使用该排序属性,范例: "Id"</param>
        public static IQueryable<TEntity> OrderBy<TEntity>(this IQueryable<TEntity> source, IPage parameter, string defaultOrder = null) where TEntity : class
        {
            source.CheckNull(nameof(source));
            parameter.CheckNull(nameof(parameter));
            InitOrder(source, parameter, defaultOrder);
            return parameter.Order.IsEmpty() ? source : source.OrderBy(parameter.Order);
        }

        /// <summary>
        /// 初始化排序
        /// </summary>
        private static void InitOrder<TEntity>(IQueryable<TEntity> source, IPage parameter, string defaultOrder)
        {
            if (parameter.Order.IsEmpty() == false)
                return;
            var expression = source.Expression.SafeString();
            if (expression.Contains(".OrderBy(") || expression.Contains(".OrderByDescending("))
                return;
            if (defaultOrder.IsEmpty())
                return;
            parameter.Order = defaultOrder;
        }

        #endregion
    }

    /// <summary>
    /// 工作单元操作管理器
    /// </summary>
    [Ioc(1)]
    public class UnitOfWorkActionManager : IUnitOfWorkActionManager
    {
        /// <summary>
        /// 操作列表
        /// </summary>
        private readonly List<Func<Task>> _actions;

        /// <summary>
        /// 初始化工作单元操作管理器
        /// </summary>
        public UnitOfWorkActionManager()
        {
            _actions = new List<Func<Task>>();
        }

        /// <inheritdoc />
        public void Register(Func<Task> action)
        {
            if (action == null)
                return;
            _actions.Add(action);
        }

        /// <inheritdoc />
        public async Task ExecuteAsync()
        {
            foreach (var action in _actions)
                await action();
            _actions.Clear();
        }
    }

    #endregion

    #region Sql

    #region Builders

    #region Caches
    /// <summary>
    /// 列缓存基类
    /// </summary>
    public abstract class ColumnCacheBase : IColumnCache
    {
        /// <summary>
        /// Sql方言
        /// </summary>
        protected readonly IDialect Dialect;

        /// <summary>
        /// 初始化列缓存
        /// </summary>
        /// <param name="dialect">Sql方言</param>
        protected ColumnCacheBase(IDialect dialect)
        {
            Dialect = dialect;
        }

        /// <summary>
        /// 从缓存中获取处理后的列集合
        /// </summary>
        /// <param name="columns">列集合</param>
        public abstract string GetSafeColumns(string columns);

        /// <summary>
        /// 规范化列集合
        /// </summary>
        /// <param name="columns">列集合</param>
        protected string NormalizeColumns(string columns)
        {
            if (columns.IsEmpty())
                return null;
            var result = new StringBuilder();
            var items = columns.Split(',').Where(column => column.IsEmpty() == false).Select(column => new ColumnItem(Dialect, column));
            foreach (var item in items)
            {
                item.AppendTo(result);
                result.Append(",");
            }
            result.RemoveEnd(",");
            return result.ToString();
        }

        /// <summary>
        /// 从缓存中获取处理后的列
        /// </summary>
        /// <param name="column">列</param>
        public abstract string GetSafeColumn(string column);

        /// <summary>
        /// 规范化列
        /// </summary>
        /// <param name="column">列</param>
        protected string NormalizeColumn(string column)
        {
            if (column.IsEmpty())
                return null;
            var item = new ColumnItem(Dialect, column);
            return item.ToResult();
        }
    }

    /// <summary>
    /// 列缓存
    /// </summary>
    public interface IColumnCache
    {
        /// <summary>
        /// 从缓存中获取处理后的列集合
        /// </summary>
        /// <param name="columns">列集合</param>
        string GetSafeColumns(string columns);
        /// <summary>
        /// 从缓存中获取处理后的列
        /// </summary>
        /// <param name="column">列</param>
        string GetSafeColumn(string column);
    }

    #endregion

    #region Clauses
    /// <summary>
    /// Sql子句基类
    /// </summary>
    public abstract class ClauseBase
    {
        /// <summary>
        /// Sql生成器
        /// </summary>
        protected readonly SqlBuilderBase SqlBuilder;
        /// <summary>
        /// Sql方言
        /// </summary>
        protected readonly IDialect Dialect;

        /// <summary>
        /// 初始化Sql子句
        /// </summary>
        /// <param name="sqlBuilder">Sql生成器</param>
        protected ClauseBase(SqlBuilderBase sqlBuilder)
        {
            SqlBuilder = sqlBuilder ?? throw new ArgumentNullException(nameof(sqlBuilder));
            Dialect = SqlBuilder.Dialect;
        }

        /// <summary>
        /// 替换原始Sql,将[]替换为特定Sql转义符
        /// </summary>
        /// <param name="sql">原始Sql</param>
        protected string ReplaceRawSql(string sql)
        {
            return Dialect.ReplaceSql(sql);
        }
    }

    /// <summary>
    /// 结束子句
    /// </summary>
    public class EndClause : ClauseBase, IEndClause
    {

        #region 字段

        /// <summary>
        /// 结束子句结果
        /// </summary>
        protected readonly StringBuilder Result;
        /// <summary>
        /// 跳过行数参数名
        /// </summary>
        protected string OffsetParam;
        /// <summary>
        /// 限制行数参数名
        /// </summary>
        protected string LimitParam;
        /// <summary>
        /// 参数管理器
        /// </summary>
        protected IParameterManager ParameterManager;
        /// <summary>
        /// 分页
        /// </summary>
        protected IPage Pager;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化结束子句
        /// </summary>
        /// <param name="sqlBuilder">Sql生成器</param>
        /// <param name="result">结束子句结果</param>
        /// <param name="offsetParam">跳过行数参数名</param>
        /// <param name="limitParam">限制行数参数名</param>
        /// <param name="pager">分页</param>
        public EndClause(SqlBuilderBase sqlBuilder, StringBuilder result = null, string offsetParam = null, string limitParam = null, IPage pager = null) : base(sqlBuilder)
        {
            Result = result ?? new StringBuilder();
            OffsetParam = offsetParam;
            LimitParam = limitParam;
            Pager = pager;
            ParameterManager = sqlBuilder.ParameterManager;
        }

        #endregion

        #region Page(设置分页)

        /// <inheritdoc />
        public void Page(IPage page)
        {
            if (page == null)
                return;
            Pager = page;
            Skip(page.GetSkipCount());
            Take(page.PageSize);
        }

        #endregion

        #region Skip(设置跳过行数)

        /// <inheritdoc />
        public void Skip(int count)
        {
            var param = GetOffsetParam();
            ParameterManager.Add(param, count);
        }

        /// <summary>
        /// 获取跳过行数参数名
        /// </summary>
        protected string GetOffsetParam()
        {
            if (OffsetParam.IsEmpty() == false)
                return OffsetParam;
            OffsetParam = CreateOffsetParam();
            return OffsetParam;
        }

        /// <summary>
        /// 创建跳过行数参数名
        /// </summary>
        private string CreateOffsetParam()
        {
            var result = ParameterManager.GenerateName();
            ParameterManager.Add(result, 0);
            return result;
        }

        #endregion

        #region Take(设置获取行数)

        /// <inheritdoc />
        public void Take(int count)
        {
            var param = GetLimitParam();
            ParameterManager.Add(param, count);
        }

        /// <summary>
        /// 获取限制行数的参数名
        /// </summary>
        protected string GetLimitParam()
        {
            if (LimitParam.IsEmpty() == false)
                return LimitParam;
            LimitParam = ParameterManager.GenerateName();
            return LimitParam;
        }

        #endregion

        #region AppendSql(添加到结束位置)

        /// <summary>
        /// 添加到结束位置
        /// </summary>
        /// <param name="sql">Sql语句</param>
        /// <param name="raw">是否原样添加</param>
        public void AppendSql(string sql, bool raw)
        {
            if (string.IsNullOrWhiteSpace(sql))
                return;
            if (raw)
            {
                Result.Append(sql);
                return;
            }
            Result.Append(ReplaceRawSql(sql));
        }

        #endregion

        #region Validate(验证)

        /// <inheritdoc />
        public bool Validate()
        {
            if (Result.Length > 0)
                return true;
            if (LimitParam.IsEmpty() == false)
                return true;
            return false;
        }

        #endregion

        #region AppendTo(添加到字符串生成器)

        /// <inheritdoc />
        public void AppendTo(StringBuilder builder)
        {
            builder.CheckNull(nameof(builder));
            if (Validate() == false)
                return;
            AppendLimit(builder);
            builder.Append(Result);
        }

        #endregion

        #region AppendLimit(添加行限制)

        /// <summary>
        /// 添加行限制
        /// </summary>
        /// <param name="builder">字符串生成器</param>
        protected virtual void AppendLimit(StringBuilder builder)
        {
            if (LimitParam.IsEmpty())
                return;
            builder.AppendFormat("Limit {0} OFFSET {1}", GetLimitParam(), GetOffsetParam());
        }

        #endregion

        #region ClearPage(清理分页)

        /// <inheritdoc />
        public void ClearPage()
        {
            OffsetParam = null;
            LimitParam = null;
            Pager = null;
        }

        #endregion

        #region Clear(清理)

        /// <inheritdoc />
        public void Clear()
        {
            Result.Clear();
            ClearPage();
        }

        #endregion

        #region Clone(复制结束子句)

        /// <inheritdoc />
        public virtual IEndClause Clone(SqlBuilderBase builder)
        {
            var result = new StringBuilder();
            result.Append(Result);
            return new EndClause(builder, result, OffsetParam, LimitParam, Pager);
        }

        #endregion
    }

    /// <summary>
    /// From子句
    /// </summary>
    public class FromClause : ClauseBase, IFromClause
    {

        #region 字段

        /// <summary>
        /// From子句结果
        /// </summary>
        protected readonly StringBuilder Result;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化From子句
        /// </summary>
        /// <param name="sqlBuilder">Sql生成器</param>
        /// <param name="result">From子句结果</param>
        public FromClause(SqlBuilderBase sqlBuilder, StringBuilder result = null) : base(sqlBuilder)
        {
            Result = result ?? new StringBuilder();
        }

        #endregion

        #region From(设置表)

        /// <inheritdoc />
        public void From(string table)
        {
            if (table.IsEmpty())
                return;
            var item = CreateTableItem(table);
            item.AppendTo(Result);
        }

        /// <summary>
        /// 创建表项
        /// </summary>
        /// <param name="table">表名</param>
        protected virtual TableItem CreateTableItem(string table)
        {
            return new(Dialect, table);
        }

        /// <inheritdoc />
        public void From(ISqlBuilder builder, string alias)
        {
            if (builder == null)
                return;
            var item = new SqlBuilderItem(Dialect, builder, alias);
            item.AppendTo(Result);
        }

        /// <inheritdoc />
        public void From(Action<ISqlBuilder> action, string alias)
        {
            if (action == null)
                return;
            var builder = SqlBuilder.New();
            action(builder);
            From(builder, alias);
        }

        #endregion

        #region AppendSql(添加到From子句)

        /// <inheritdoc />
        public void AppendSql(string sql, bool raw)
        {
            if (string.IsNullOrWhiteSpace(sql))
                return;
            if (raw)
            {
                Result.Append(sql);
                return;
            }
            Result.Append(ReplaceRawSql(sql));
        }

        #endregion

        #region Validate(验证)

        /// <inheritdoc />
        public bool Validate()
        {
            return Result.Length > 0;
        }

        #endregion

        #region AppendTo(添加到字符串生成器)

        /// <inheritdoc />
        public void AppendTo(StringBuilder builder)
        {
            builder.CheckNull(nameof(builder));
            if (Validate() == false)
                return;
            builder.Append("From ");
            builder.Append(Result);
        }

        #endregion

        #region Clear(清理)

        /// <inheritdoc />
        public void Clear()
        {
            Result.Clear();
        }

        #endregion

        #region Clone(复制From子句)

        /// <inheritdoc />
        public virtual IFromClause Clone(SqlBuilderBase builder)
        {
            var result = new StringBuilder();
            result.Append(Result);
            return new FromClause(builder, result);
        }

        #endregion
    }

    /// <summary>
    /// Group By子句
    /// </summary>
    public class GroupByClause : ClauseBase, IGroupByClause
    {

        #region 字段

        /// <summary>
        /// 子句结果
        /// </summary>
        protected readonly StringBuilder Result;
        /// <summary>
        /// 分组条件
        /// </summary>
        protected StringBuilder Condition;
        /// <summary>
        /// 列缓存
        /// </summary>
        protected readonly IColumnCache ColumnCache;
        /// <summary>
        /// Sql条件工厂
        /// </summary>
        protected readonly IConditionFactory ConditionFactory;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化Group By子句
        /// </summary>
        /// <param name="sqlBuilder">Sql生成器</param>
        /// <param name="result">Group By子句结果</param>
        /// <param name="condition">分组条件</param>
        public GroupByClause(SqlBuilderBase sqlBuilder, StringBuilder result = null, StringBuilder condition = null) : base(sqlBuilder)
        {
            Result = result ?? new StringBuilder();
            Condition = condition ?? new StringBuilder();
            ColumnCache = sqlBuilder.ColumnCache;
            ConditionFactory = sqlBuilder.ConditionFactory;
        }

        #endregion

        #region GroupBy(添加分组列)

        /// <inheritdoc />
        public void GroupBy(string columns)
        {
            if (string.IsNullOrWhiteSpace(columns))
                return;
            if (Result.Length > 0)
                Result.Append(",");
            Result.Append(ColumnCache.GetSafeColumns(columns));
        }

        #endregion

        #region Having(添加分组条件)

        /// <inheritdoc />
        public void Having(string expression, object value, Operator @operator = Operator.Equal, bool isParameterization = true)
        {
            And(ConditionFactory.Create(expression, value, @operator, isParameterization));
        }

        /// <summary>
        /// And连接条件
        /// </summary>
        private void And(ISqlCondition condition)
        {
            new AndCondition(condition).AppendTo(Condition);
        }

        #endregion

        #region AppendGroupBy(添加到Group By子句)

        /// <inheritdoc />
        public void AppendGroupBy(string sql, bool raw)
        {
            if (string.IsNullOrWhiteSpace(sql))
                return;
            if (raw)
            {
                Result.Append(sql);
                return;
            }
            Result.Append(ReplaceRawSql(sql));
        }

        #endregion

        #region AppendHaving(添加到Having子句)

        /// <inheritdoc />
        public void AppendHaving(string sql, bool raw)
        {
            if (string.IsNullOrWhiteSpace(sql))
                return;
            if (raw)
            {
                And(new SqlCondition(sql));
                return;
            }
            And(new SqlCondition(ReplaceRawSql(sql)));
        }

        #endregion

        #region Validate(验证)

        /// <inheritdoc />
        public bool Validate()
        {
            return Result.Length > 0;
        }

        #endregion

        #region AppendTo(添加到字符串生成器)

        /// <inheritdoc />
        public void AppendTo(StringBuilder builder)
        {
            builder.CheckNull(nameof(builder));
            if (Validate() == false)
                return;
            builder.Append("Group By ");
            builder.Append(Result);
            if (Condition.Length == 0)
                return;
            builder.Append(" Having ");
            builder.Append(Condition);
        }

        #endregion

        #region Clear(清理)

        /// <inheritdoc />
        public void Clear()
        {
            Result.Clear();
            Condition.Clear();
        }

        #endregion

        #region Clone(复制Group By子句)

        /// <inheritdoc />
        public virtual IGroupByClause Clone(SqlBuilderBase builder)
        {
            var result = new StringBuilder();
            result.Append(Result);
            var condition = new StringBuilder();
            condition.Append(Condition);
            return new GroupByClause(builder, result, condition);
        }

        #endregion
    }

