        /// <param name="includeTime">是否包含时间</param>
        /// <param name="boundary">包含边界</param>
        void Between(string column, DateTime? min, DateTime? max, bool includeTime, Boundary? boundary);
        /// <summary>
        /// 设置Exists查询条件
        /// </summary>
        /// <param name="builder">子查询Sql生成器</param>
        void Exists(ISqlBuilder builder);
        /// <summary>
        /// 设置Exists查询条件
        /// </summary>
        /// <param name="action">子查询操作</param>
        void Exists(Action<ISqlBuilder> action);
        /// <summary>
        /// 设置Not Exists查询条件
        /// </summary>
        /// <param name="builder">子查询Sql生成器</param>
        void NotExists(ISqlBuilder builder);
        /// <summary>
        /// 设置Not Exists查询条件
        /// </summary>
        /// <param name="action">子查询操作</param>
        void NotExists(Action<ISqlBuilder> action);
        /// <summary>
        /// 添加到Where子句
        /// </summary>
        /// <param name="sql">Sql语句</param>
        /// <param name="raw">是否原样添加</param>
        void AppendSql(string sql, bool raw);
        /// <summary>
        /// 清理
        /// </summary>
        void Clear();
        /// <summary>
        /// 复制Where子句
        /// </summary>
        /// <param name="builder">Sql生成器</param>
        IWhereClause Clone(SqlBuilderBase builder);
    }

    /// <summary>
    /// Join子句
    /// </summary>
    public class JoinClause : ClauseBase, IJoinClause
    {

        #region 常量

        /// <summary>
        /// Join关键字
        /// </summary>
        private const string JoinKey = "Join";
        /// <summary>
        /// Left Join关键字
        /// </summary>
        private const string LeftJoinKey = "Left Join";
        /// <summary>
        /// Right Join关键字
        /// </summary>
        private const string RightJoinKey = "Right Join";

        #endregion

        #region 字段

        /// <summary>
        /// Join子句结果
        /// </summary>
        protected readonly StringBuilder Result;
        /// <summary>
        /// 连接条件
        /// </summary>
        protected StringBuilder Condition;
        /// <summary>
        /// 列缓存
        /// </summary>
        protected readonly IColumnCache ColumnCache;
        /// <summary>
        /// Sql条件工厂
        /// </summary>
        protected readonly IConditionFactory ConditionFactory;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化Join子句
        /// </summary>
        /// <param name="sqlBuilder">Sql生成器</param>
        /// <param name="result">Join子句结果</param>
        /// <param name="condition">连接条件</param>
        public JoinClause(SqlBuilderBase sqlBuilder, StringBuilder result = null, StringBuilder condition = null) : base(sqlBuilder)
        {
            Result = result ?? new StringBuilder();
            Condition = condition ?? new StringBuilder();
            ColumnCache = sqlBuilder.ColumnCache;
            ConditionFactory = sqlBuilder.ConditionFactory;
        }

        #endregion

        #region Join(内连接)

        /// <inheritdoc />
        public void Join(string table)
        {
            Join(JoinKey, table);
        }

        /// <summary>
        /// 表连接
        /// </summary>
        private void Join(string joinType, string table)
        {
            AppendOn();
            AppendJoin(joinType, table);
        }

        /// <summary>
        /// 添加On条件
        /// </summary>
        private void AppendOn()
        {
            if (Condition.Length == 0)
                return;
            Result.Append(" On ");
            Result.Append(Condition);
            Result.AppendLine(" ");
            Condition.Clear();
        }

        /// <summary>
        /// 添加Join
        /// </summary>
        private void AppendJoin(string joinType, string table)
        {
            Result.AppendFormat("{0} ", joinType);
            var item = CreateTableItem(table);
            item.AppendTo(Result);
        }

        /// <summary>
        /// 创建表项
        /// </summary>
        /// <param name="table">表名</param>
        protected virtual TableItem CreateTableItem(string table)
        {
            return new(Dialect, table);
        }

        /// <inheritdoc />
        public void Join(ISqlBuilder builder, string alias)
        {
            Join(JoinKey, builder, alias);
        }

        /// <summary>
        /// 表连接
        /// </summary>
        private void Join(string joinType, ISqlBuilder builder, string alias)
        {
            if (builder == null)
                return;
            AppendOn();
            Result.AppendFormat("{0} ", joinType);
            var item = new SqlBuilderItem(Dialect, builder, alias);
            item.AppendTo(Result);
        }

        /// <inheritdoc />
        public void Join(Action<ISqlBuilder> action, string alias)
        {
            if (action == null)
                return;
            var builder = SqlBuilder.New();
            action(builder);
            Join(builder, alias);
        }

        #endregion

        #region LeftJoin(左外连接)

        /// <inheritdoc />
        public void LeftJoin(string table)
        {
            Join(LeftJoinKey, table);
        }

        /// <inheritdoc />
        public void LeftJoin(ISqlBuilder builder, string alias)
        {
            Join(LeftJoinKey, builder, alias);
        }

        /// <inheritdoc />
        public void LeftJoin(Action<ISqlBuilder> action, string alias)
        {
            if (action == null)
                return;
            var builder = SqlBuilder.New();
            action(builder);
            LeftJoin(builder, alias);
        }

        #endregion

        #region RightJoin(右外连接)

        /// <inheritdoc />
        public void RightJoin(string table)
        {
            Join(RightJoinKey, table);
        }

        /// <inheritdoc />
        public void RightJoin(ISqlBuilder builder, string alias)
        {
            Join(RightJoinKey, builder, alias);
        }

        /// <inheritdoc />
        public void RightJoin(Action<ISqlBuilder> action, string alias)
        {
            if (action == null)
                return;
            var builder = SqlBuilder.New();
            action(builder);
            RightJoin(builder, alias);
        }

        #endregion

        #region On(设置连接条件)

        /// <inheritdoc />
        public void On(string column, object value, Operator @operator = Operator.Equal, bool isParameterization = false)
        {
            column = ColumnCache.GetSafeColumn(column);
            value = GetValue(value, isParameterization);
            var condition = ConditionFactory.Create(column, value, @operator, isParameterization);
            On(condition);
        }

        /// <summary>
        /// 获取值,非参数化字符串值被认为是列名,将进行规范化处理
        /// </summary>
        private object GetValue(object value, bool isParameterization)
        {
            if (value == null)
                return null;
            if (isParameterization)
                return value;
            if (value.GetType() != typeof(string))
                return value;
            return ColumnCache.GetSafeColumn(value.ToString());
        }

        /// <summary>
        /// 设置连接条件
        /// </summary>
        /// <param name="condition">连接条件</param>
        public void On(ISqlCondition condition)
        {
            if (condition == null)
                return;
            new AndCondition(condition).AppendTo(Condition);
        }

        #endregion

        #region AppendJoin(添加到内连接子句)

        /// <inheritdoc />
        public void AppendJoin(string sql, bool raw)
        {
            AppendSql(JoinKey, sql, raw);
        }

        /// <summary>
        /// 添加到连接子句
        /// </summary>
        private void AppendSql(string joinType, string sql, bool raw)
        {
            if (string.IsNullOrWhiteSpace(sql))
                return;
            AppendOn();
            Result.AppendFormat("{0} ", joinType);
            if (raw)
            {
                Result.Append(sql);
                return;
            }
            Result.Append(ReplaceRawSql(sql));
        }

        #endregion

        #region AppendLeftJoin(添加到左外连接子句)

        /// <inheritdoc />
        public void AppendLeftJoin(string sql, bool raw)
        {
            AppendSql(LeftJoinKey, sql, raw);
        }

        #endregion

        #region AppendRightJoin(添加到右外连接子句)

        /// <inheritdoc />
        public void AppendRightJoin(string sql, bool raw)
        {
            AppendSql(RightJoinKey, sql, raw);
        }

        #endregion

        #region AppendOn(添加到On子句)

        /// <inheritdoc />
        public void AppendOn(string sql, bool raw)
        {
            if (raw)
            {
                On(new SqlCondition(sql));
                return;
            }
            On(new SqlCondition(ReplaceRawSql(sql)));
        }

        #endregion

        #region Validate(验证)

        /// <inheritdoc />
        public bool Validate()
        {
            return Result.Length > 0;
        }

        #endregion

        #region AppendTo(添加到字符串生成器)

        /// <inheritdoc />
        public void AppendTo(StringBuilder builder)
        {
            builder.CheckNull(nameof(builder));
            if (Validate() == false)
                return;
            AppendOn();
            builder.Append(Result);
            builder.RemoveEnd($" {Common.Line}");
        }

        #endregion

        #region Clear(清理)

        /// <inheritdoc />
        public void Clear()
        {
            Result.Clear();
            Condition.Clear();
        }

        #endregion

        #region Clone(复制Join子句)

        /// <inheritdoc />
        public virtual IJoinClause Clone(SqlBuilderBase builder)
        {
            var result = new StringBuilder();
            result.Append(Result);
            var condition = new StringBuilder();
            condition.Append(Condition);
            return new JoinClause(builder, result, condition);
        }

        #endregion
    }

    /// <summary>
    /// Order By子句
    /// </summary>
    public class OrderByClause : ClauseBase, IOrderByClause
    {

        #region 字段

        /// <summary>
        /// 子句结果
        /// </summary>
        protected readonly StringBuilder Result;
        /// <summary>
        /// 列缓存
        /// </summary>
        protected readonly IColumnCache ColumnCache;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化排序子句
        /// </summary>
        /// <param name="sqlBuilder">Sql生成器</param>
        /// <param name="result">Order By子句结果</param>
        public OrderByClause(SqlBuilderBase sqlBuilder, StringBuilder result = null) : base(sqlBuilder)
        {
            Result = result ?? new StringBuilder();
            ColumnCache = sqlBuilder.ColumnCache;
        }

        #endregion

        #region OrderBy(排序)

        /// <inheritdoc />
        public void OrderBy(string order)
        {
            if (string.IsNullOrWhiteSpace(order))
                return;
            var items = order.Split(',').Where(t => t.IsEmpty() == false);
            foreach (var item in items)
            {
                var orderItem = new OrderByItem(item);
                Result.Append(ColumnCache.GetSafeColumn(orderItem.Column));
                if (orderItem.Desc)
                    Result.Append(" Desc");
                Result.Append(",");
            }
        }

        #endregion

        #region AppendSql(添加到排序子句)

        /// <inheritdoc />
        public void AppendSql(string sql, bool raw)
        {
            if (string.IsNullOrWhiteSpace(sql))
                return;
            if (raw)
            {
                Result.Append(sql);
                return;
            }
            Result.Append(ReplaceRawSql(sql));
        }

        #endregion

        #region Validate(验证)

        /// <inheritdoc />
        public bool Validate()
        {
            return Result.Length > 0;
        }

        #endregion

        #region AppendTo(添加到字符串生成器)

        /// <inheritdoc />
        public void AppendTo(StringBuilder builder)
        {
            builder.CheckNull(nameof(builder));
            if (Validate() == false)
                return;
            builder.Append("Order By ");
            builder.Append(Result);
            builder.RemoveEnd(",");
        }

        #endregion

        #region Clear(清理)

        /// <inheritdoc />
        public void Clear()
        {
            Result.Clear();
        }

        #endregion

        #region Clone(复制Order By子句)

        /// <inheritdoc />
        public virtual IOrderByClause Clone(SqlBuilderBase builder)
        {
            var result = new StringBuilder();
            result.Append(Result);
            return new OrderByClause(builder, result);
        }

        #endregion
    }

    /// <summary>
    /// Select子句
    /// </summary>
    public class SelectClause : ClauseBase, ISelectClause
    {

        #region 字段

        /// <summary>
        /// Select子句结果
        /// </summary>
        protected readonly StringBuilder Result;
        /// <summary>
        /// 列缓存
        /// </summary>
        protected readonly IColumnCache ColumnCache;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化Select子句
        /// </summary>
        /// <param name="sqlBuilder">Sql生成器</param>
        /// <param name="result">Select子句结果</param>
        public SelectClause(SqlBuilderBase sqlBuilder, StringBuilder result = null) : base(sqlBuilder)
        {
            Result = result ?? new StringBuilder();
            ColumnCache = sqlBuilder.ColumnCache;
        }

        #endregion

        #region Select(设置列名)

        /// <inheritdoc />
        public void Select()
        {
            Result.Clear();
            Result.Append("*");
        }

        /// <inheritdoc />
        public void Select(string columns)
        {
            if (columns.IsEmpty())
                return;
            if (columns == "*")
            {
                Select();
                return;
            }
            AppendColumns(ColumnCache.GetSafeColumns(columns));
        }

        /// <summary>
        /// 添加列
        /// </summary>
        protected void AppendColumns(string columns)
        {
            if (Result.Length > 0)
                Result.RemoveEnd(",").Append(",");
            Result.Append(columns);
        }

        /// <inheritdoc />
        public void Select(ISqlBuilder builder, string alias)
        {
            if (builder == null)
                return;
            if (Result.Length > 0)
                Result.Append(",");
            var item = new SqlBuilderItem(Dialect, builder, alias);
            item.AppendTo(Result);
        }

        /// <inheritdoc />
        public void Select(Action<ISqlBuilder> action, string alias)
        {
            if (action == null)
                return;
            var builder = SqlBuilder.New();
            action(builder);
            Select(builder, alias);
        }

        #endregion

        #region AppendSql(添加到Select子句)

        /// <inheritdoc />
        public void AppendSql(string sql, bool raw)
        {
            if (string.IsNullOrWhiteSpace(sql))
                return;
            if (raw)
            {
                Result.Append(sql);
                return;
            }
            Result.Append(ReplaceRawSql(sql));
        }

        /// <inheritdoc />
        public void AppendSql(ISqlBuilder builder)
        {
            if (builder == null)
                return;
            builder.AppendTo(Result);
        }

        /// <inheritdoc />
        public void AppendSql(Action<ISqlBuilder> action)
        {
            if (action == null)
                return;
            var builder = SqlBuilder.New();
            action(builder);
            AppendSql(builder);
        }

        #endregion

        #region Validate(验证)

        /// <inheritdoc />
        public bool Validate()
        {
            return Result.Length > 0;
        }

        #endregion

        #region AppendTo(添加到字符串生成器)

        /// <inheritdoc />
        public void AppendTo(StringBuilder builder)
        {
            builder.CheckNull(nameof(builder));
            if (Validate() == false)
                return;
            builder.Append("Select ");
            builder.Append(Result);
        }

        #endregion

        #region Clear(清理)

        /// <inheritdoc />
        public void Clear()
        {
            Result.Clear();
        }

        #endregion

        #region Clone(复制Select子句)

        /// <inheritdoc />
        public virtual ISelectClause Clone(SqlBuilderBase builder)
        {
            var result = new StringBuilder();
            result.Append(Result);
            return new SelectClause(builder, result);
        }

        #endregion
    }

    /// <summary>
    /// 起始子句
    /// </summary>
    public class StartClause : ClauseBase, IStartClause
    {

        #region 字段

        /// <summary>
        /// 起始子句结果
        /// </summary>
        protected readonly StringBuilder Result;
        /// <summary>
        /// 公用表表达式CTE项集合
        /// </summary>
        protected List<CteItem> CteItems;
        /// <summary>
        /// 列缓存
        /// </summary>
        protected readonly IColumnCache ColumnCache;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化起始子句
        /// </summary>
        /// <param name="sqlBuilder">Sql生成器</param>
        /// <param name="result">起始子句结果</param>
        /// <param name="cteItems">公用表表达式CTE项集合</param>
        public StartClause(SqlBuilderBase sqlBuilder, StringBuilder result = null, List<CteItem> cteItems = null) : base(sqlBuilder)
        {
            Result = result ?? new StringBuilder();
            CteItems = cteItems ?? new List<CteItem>();
            ColumnCache = sqlBuilder.ColumnCache;
        }

        #endregion

        #region Cte(公用表表达式CTE)

        /// <summary>
        /// 公用表表达式CTE
        /// </summary>
        /// <param name="name">公用表表达式名称</param>
        /// <param name="builder">Sql生成器</param>
        public void Cte(string name, ISqlBuilder builder)
        {
            if (name.IsEmpty() || builder == null)
                return;
            name = ColumnCache.GetSafeColumn(name);
            CteItems.Add(new CteItem(name, builder));
        }

        #endregion

        #region Append(添加到起始位置)

        /// <summary>
        /// 添加到起始位置
        /// </summary>
        /// <param name="sql">Sql语句</param>
        /// <param name="raw">是否原样添加</param>
        public void Append(string sql, bool raw)
        {
            if (string.IsNullOrWhiteSpace(sql))
                return;
            if (raw)
            {
                Result.Append(sql);
                return;
            }
            Result.Append(ReplaceRawSql(sql));
        }

        #endregion

        #region AppendLine(添加到起始位置并换行)

        /// <summary>
        /// 添加到起始位置并换行
        /// </summary>
        /// <param name="sql">Sql语句</param>
        /// <param name="raw">是否原样添加</param>
        public void AppendLine(string sql, bool raw)
        {
            if (string.IsNullOrWhiteSpace(sql))
                return;
            if (raw)
            {
                Result.AppendLine(sql);
                return;
            }
            Result.AppendLine(ReplaceRawSql(sql));
        }

        #endregion

        #region Validate(验证)

        /// <summary>
        /// 验证
        /// </summary>
        public bool Validate()
        {
            if (Result.Length > 0)
                return true;
            if (CteItems.Count > 0)
                return true;
            return false;
        }

        #endregion

        #region AppendTo(添加到字符串生成器)

        /// <summary>
        /// 添加到字符串生成器
        /// </summary>
        /// <param name="builder">字符串生成器</param>
        public void AppendTo(StringBuilder builder)
        {
            builder.CheckNull(nameof(builder));
            if (Validate() == false)
                return;
            AppendCte(builder);
            builder.Append(Result);
        }

        #endregion

        #region AppendCte(添加公用表表达式CTE)

        /// <summary>
        /// 添加公用表表达式CTE
        /// </summary>
        /// <param name="builder">字符串生成器</param>
        protected virtual void AppendCte(StringBuilder builder)
        {
            if (CteItems.Count == 0)
                return;
            builder.AppendFormat("{0} ", GetCteKeyWord());
            foreach (var item in CteItems)
            {
                builder.Append(item.Name);
                builder.AppendLine(" ");
                builder.Append("As (");
                item.Builder.AppendTo(builder);
                builder.AppendLine("),");
            }
            builder.RemoveEnd($",{Common.Line}");
        }

        /// <summary>
        /// 获取CTE关键字
        /// </summary>
        protected virtual string GetCteKeyWord()
        {
            return "With";
        }

        #endregion

        #region ClearCte(清理公用表表达式CTE)

        /// <summary>
        /// 清理公用表表达式CTE
        /// </summary>
        public void ClearCte()
        {
            CteItems.Clear();
        }

        #endregion

        #region Clear(清理)

        /// <summary>
        /// 清理
        /// </summary>
        public void Clear()
        {
            Result.Clear();
            CteItems.Clear();
        }

        #endregion

        #region Clone(复制起始子句)

        /// <summary>
        /// 复制起始子句
        /// </summary>
        /// <param name="builder">Sql生成器</param>
        public virtual IStartClause Clone(SqlBuilderBase builder)
        {
            var result = new StringBuilder();
            result.Append(Result);
            return new StartClause(builder, result, CteItems.Select(t => t.Clone()).ToList());
        }

        #endregion
    }

    /// <summary>
    /// Where子句
    /// </summary>
    public class WhereClause : ClauseBase, IWhereClause
    {

        #region 字段

        /// <summary>
        /// Where子句结果
        /// </summary>
        protected readonly StringBuilder Result;
        /// <summary>
        /// 列缓存
        /// </summary>
        protected readonly IColumnCache ColumnCache;
        /// <summary>
        /// Sql条件工厂
        /// </summary>
        protected readonly IConditionFactory ConditionFactory;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化Where子句
        /// </summary>
        /// <param name="sqlBuilder">Sql生成器</param>
        /// <param name="result">Where子句结果</param>
        public WhereClause(SqlBuilderBase sqlBuilder, StringBuilder result = null) : base(sqlBuilder)
        {
            Result = result ?? new StringBuilder();
            ColumnCache = sqlBuilder.ColumnCache;
            ConditionFactory = sqlBuilder.ConditionFactory;
        }

        #endregion

        #region And

        /// <inheritdoc />
        public void And(ISqlCondition condition)
        {
            new AndCondition(condition).AppendTo(Result);
        }

        #endregion

        #region Or

        /// <inheritdoc />
        public void Or(ISqlCondition condition)
        {
            new OrCondition(condition).AppendTo(Result);
        }

        #endregion

        #region Where

        /// <inheritdoc />
        public void Where(string column, object value, Operator @operator)
        {
            column = ColumnCache.GetSafeColumn(column);
            And(ConditionFactory.Create(column, value, @operator));
        }

        /// <inheritdoc />
        public void Where(string column, ISqlBuilder builder, Operator @operator)
        {
            if (builder == null)
                return;
            Where(column, (object)builder, @operator);
        }

        /// <inheritdoc />
        public void Where(string column, Action<ISqlBuilder> action, Operator @operator)
        {
            if (action == null)
                return;
            var builder = SqlBuilder.New();
            action(builder);
            Where(column, builder, @operator);
        }

        #endregion

        #region IsNull

        /// <inheritdoc />
        public void IsNull(string column)
        {
            Where(column, (object)null, Operator.Equal);
        }

        #endregion

        #region IsNotNull

        /// <inheritdoc />
        public void IsNotNull(string column)
        {
            Where(column, (object)null, Operator.NotEqual);
        }

        #endregion

        #region IsEmpty

        /// <inheritdoc />
        public void IsEmpty(string column)
        {
            column = ColumnCache.GetSafeColumn(column);
            var nullCondition = ConditionFactory.Create(column, null, Operator.Equal);
            var emptyCondition = ConditionFactory.Create(column, "''", Operator.Equal, false);
            And(new OrCondition(nullCondition, emptyCondition));
        }

        #endregion

        #region IsNotEmpty

        /// <inheritdoc />
        public void IsNotEmpty(string column)
        {
            column = ColumnCache.GetSafeColumn(column);
            var notNullCondition = ConditionFactory.Create(column, null, Operator.NotEqual);
            var notEmptyCondition = ConditionFactory.Create(column, "''", Operator.NotEqual, false);
            And(new AndCondition(notNullCondition, notEmptyCondition));
        }

        #endregion

        #region Between

        /// <inheritdoc />
        public void Between(string column, int? min, int? max, Boundary boundary)
        {
            column = ColumnCache.GetSafeColumn(column);
            if (min > max)
            {
                And(ConditionFactory.Create(column, max, min, boundary));
                return;
            }
            And(ConditionFactory.Create(column, min, max, boundary));
        }

        /// <inheritdoc />
        public void Between(string column, double? min, double? max, Boundary boundary)
        {
            column = ColumnCache.GetSafeColumn(column);
            if (min > max)
            {
                And(ConditionFactory.Create(column, max, min, boundary));
                return;
            }
            And(ConditionFactory.Create(column, min, max, boundary));
        }

        /// <inheritdoc />
        public void Between(string column, decimal? min, decimal? max, Boundary boundary)
        {
            column = ColumnCache.GetSafeColumn(column);
            if (min > max)
            {
                And(ConditionFactory.Create(column, max, min, boundary));
                return;
            }
            And(ConditionFactory.Create(column, min, max, boundary));
        }

        /// <inheritdoc />
        public void Between(string column, DateTime? min, DateTime? max, bool includeTime, Boundary? boundary)
        {
            column = ColumnCache.GetSafeColumn(column);
            And(ConditionFactory.Create(column, GetMin(min, max, includeTime), GetMax(min, max, includeTime), GetBoundary(boundary, includeTime)));
        }

        /// <summary>
        /// 获取最小日期
        /// </summary>
        private DateTime? GetMin(DateTime? min, DateTime? max, bool includeTime)
        {
            if (min == null)
                return null;
            DateTime? result = min;
            if (min > max)
                result = max;
            if (includeTime)
                return result;
            return result.SafeValue().Date;
        }

        /// <summary>
        /// 获取最大日期
        /// </summary>
        private DateTime? GetMax(DateTime? min, DateTime? max, bool includeTime)
        {
            if (max == null)
                return null;
            DateTime? result = max;
            if (min > max)
                result = min;
            if (includeTime)
                return result;
            return result.SafeValue().Date.AddDays(1);
        }

        /// <summary>
        /// 获取日期范围查询条件边界
        /// </summary>
        private Boundary GetBoundary(Boundary? boundary, bool includeTime)
        {
            if (boundary != null)
                return boundary.SafeValue();
            if (includeTime)
                return Boundary.Both;
            return Boundary.Left;
        }

        #endregion

        #region Exists

        /// <inheritdoc />
        public void Exists(ISqlBuilder builder)
        {
            if (builder == null)
                return;
            And(new ExistsCondition(builder));
        }

        /// <inheritdoc />
        public void Exists(Action<ISqlBuilder> action)
        {
            if (action == null)
                return;
            var builder = SqlBuilder.New();
            action(builder);
            Exists(builder);
        }

        #endregion

        #region NotExists

        /// <inheritdoc />
        public void NotExists(ISqlBuilder builder)
        {
            if (builder == null)
                return;
            And(new NotExistsCondition(builder));
        }

        /// <inheritdoc />
        public void NotExists(Action<ISqlBuilder> action)
        {
            if (action == null)
                return;
            var builder = SqlBuilder.New();
            action(builder);
            NotExists(builder);
        }

        #endregion

        #region AppendSql

        /// <inheritdoc />
        public void AppendSql(string sql, bool raw)
        {
            if (string.IsNullOrWhiteSpace(sql))
                return;
            if (raw)
            {
                And(new SqlCondition(sql));
                return;
            }
            And(new SqlCondition(ReplaceRawSql(sql)));
        }

        #endregion

        #region Validate

        /// <inheritdoc />
        public bool Validate()
        {
            return Result.Length > 0;
        }

        #endregion

        #region AppendTo

        /// <inheritdoc />
        public void AppendTo(StringBuilder builder)
        {
            builder.CheckNull(nameof(builder));
            if (Validate() == false)
                return;
            builder.Append("Where ");
            builder.Append(Result);
        }

        #endregion

        #region Clear

        /// <inheritdoc />
        public void Clear()
        {
            Result.Clear();
        }

        #endregion

        #region Clone

        /// <inheritdoc />
        public virtual IWhereClause Clone(SqlBuilderBase builder)
        {
            var result = new StringBuilder();
            result.Append(Result);
            return new WhereClause(builder, result);
        }

        #endregion
    }

    #endregion

    #region Conditions
    /// <summary>
    /// And连接条件
    /// </summary>
    public class AndCondition : ISqlCondition
    {
        /// <summary>
        /// Sql条件1
        /// </summary>
        private readonly ISqlCondition _condition1;
        /// <summary>
        /// Sql条件2
        /// </summary>
        private readonly ISqlCondition _condition2;

        /// <summary>
        /// 初始化And连接条件
        /// </summary>
        /// <param name="condition1">Sql条件1</param>
        /// <param name="condition2">Sql条件2</param>
        public AndCondition(ISqlCondition condition1, ISqlCondition condition2 = null)
        {
            _condition1 = condition1;
            _condition2 = condition2;
        }

        /// <summary>
        /// 添加到字符串生成器
        /// </summary>
        /// <param name="builder">字符串生成器</param>
        public void AppendTo(StringBuilder builder)
        {
            if (_condition1 == null && _condition2 == null)
                return;
            And(builder, _condition1);
            And(builder, _condition2);
        }

        /// <summary>
        /// 与连接
        /// </summary>
        private void And(StringBuilder builder, ISqlCondition condition)
        {
            if (condition == null || condition == NullCondition.Instance)
                return;
            if (builder.Length == 0)
            {
                condition.AppendTo(builder);
                return;
            }
            builder.Append(" And ");
            condition.AppendTo(builder);
        }
    }

