    /// <summary>
    /// Or连接条件
    /// </summary>
    public class OrCondition : ISqlCondition
    {
        /// <summary>
        /// Sql条件1
        /// </summary>
        private readonly ISqlCondition _condition1;
        /// <summary>
        /// Sql条件2
        /// </summary>
        private readonly ISqlCondition _condition2;

        /// <summary>
        /// 初始化Or连接条件
        /// </summary>
        /// <param name="condition1">Sql条件1</param>
        /// <param name="condition2">Sql条件2</param>
        public OrCondition(ISqlCondition condition1, ISqlCondition condition2 = null)
        {
            _condition1 = condition1;
            _condition2 = condition2;
            if (condition1 != null && condition1 == NullCondition.Instance)
                _condition1 = null;
            if (condition2 != null && condition2 == NullCondition.Instance)
                _condition2 = null;
        }

        /// <summary>
        /// 添加到字符串生成器
        /// </summary>
        /// <param name="builder">字符串生成器</param>
        public void AppendTo(StringBuilder builder)
        {
            if (_condition1 == null && _condition2 == null)
                return;
            if (_condition1 != null && _condition2 != null)
            {
                AppendAllCondition(builder);
                return;
            }
            AppendCondition(builder, _condition1);
            AppendCondition(builder, _condition2);
        }

        /// <summary>
        /// 连接两个条件
        /// </summary>
        private void AppendAllCondition(StringBuilder builder)
        {
            if (builder.Length == 0)
            {
                Or(builder);
                return;
            }
            builder.Append(" And ");
            Or(builder);
        }

        /// <summary>
        /// 或操作
        /// </summary>
        private void Or(StringBuilder builder)
        {
            builder.Append("(");
            _condition1.AppendTo(builder);
            builder.Append(" Or ");
            _condition2.AppendTo(builder);
            builder.Append(")");
        }

        /// <summary>
        /// 连接1个条件
        /// </summary>
        private void AppendCondition(StringBuilder builder, ISqlCondition condition)
        {
            if (condition == null)
                return;
            if (builder.Length == 0)
            {
                condition.AppendTo(builder);
                return;
            }
            builder.Insert(0, '(');
            builder.Append(" Or ");
            condition.AppendTo(builder);
            builder.Append(")");
        }
    }

    /// <summary>
    /// 范围过滤条件
    /// </summary>
    public class SegmentCondition : ISqlCondition
    {
        /// <summary>
        /// Sql参数管理器
        /// </summary>
        protected readonly IParameterManager ParameterManager;
        /// <summary>
        /// 列名
        /// </summary>
        protected readonly string Column;
        /// <summary>
        /// 最小值
        /// </summary>
        protected readonly object MinValue;
        /// <summary>
        /// 最大值
        /// </summary>
        protected readonly object MaxValue;
        /// <summary>
        /// 包含边界
        /// </summary>
        protected Boundary Boundary;
        /// <summary>
        /// 是否参数化
        /// </summary>
        protected readonly bool IsParameterization;

        /// <summary>
        /// 初始化范围过滤条件
        /// </summary>
        /// <param name="parameterManager">Sql参数管理器</param>
        /// <param name="column">列名</param>
        /// <param name="minValue">最小值</param>
        /// <param name="maxValue">最大值</param>
        /// <param name="boundary">包含边界</param>
        /// <param name="isParameterization">是否参数化</param>
        public SegmentCondition(IParameterManager parameterManager, string column, object minValue, object maxValue, Boundary boundary, bool isParameterization)
        {
            ParameterManager = parameterManager ?? throw new ArgumentNullException(nameof(parameterManager));
            if (string.IsNullOrWhiteSpace(column))
                throw new ArgumentNullException(nameof(column));
            Column = column;
            MinValue = minValue;
            MaxValue = maxValue;
            Boundary = boundary;
            IsParameterization = isParameterization;
        }

        /// <summary>
        /// 添加到字符串生成器
        /// </summary>
        /// <param name="builder">字符串生成器</param>
        public void AppendTo(StringBuilder builder)
        {
            new AndCondition(CreateLeftCondition(), CreateRightCondition()).AppendTo(builder);
        }

        /// <summary>
        /// 创建左条件
        /// </summary>
        private ISqlCondition CreateLeftCondition()
        {
            if (string.IsNullOrWhiteSpace(MinValue.SafeString()))
                return NullCondition.Instance;
            switch (Boundary)
            {
                case Boundary.Left:
                    return new GreaterEqualCondition(ParameterManager, Column, MinValue, IsParameterization);
                case Boundary.Both:
                    return new GreaterEqualCondition(ParameterManager, Column, MinValue, IsParameterization);
                default:
                    return new GreaterCondition(ParameterManager, Column, MinValue, IsParameterization);
            }
        }

        /// <summary>
        /// 创建右条件
        /// </summary>
        private ISqlCondition CreateRightCondition()
        {
            if (string.IsNullOrWhiteSpace(MaxValue.SafeString()))
                return NullCondition.Instance;
            switch (Boundary)
            {
                case Boundary.Right:
                    return new LessEqualCondition(ParameterManager, Column, MaxValue, IsParameterization);
                case Boundary.Both:
                    return new LessEqualCondition(ParameterManager, Column, MaxValue, IsParameterization);
                default:
                    return new LessCondition(ParameterManager, Column, MaxValue, IsParameterization);
            }
        }
    }

    /// <summary>
    /// Sql查询条件
    /// </summary>
    public class SqlCondition : ISqlCondition
    {
        /// <summary>
        /// Sql查询条件
        /// </summary>
        private readonly string _condition;

        /// <summary>
        /// 初始化Sql查询条件
        /// </summary>
        /// <param name="condition">查询条件</param>
        public SqlCondition(string condition)
        {
            _condition = condition;
        }

        /// <summary>
        /// 添加到字符串生成器
        /// </summary>
        /// <param name="builder">字符串生成器</param>
        public void AppendTo(StringBuilder builder)
        {
            builder.Append(_condition);
        }
    }

    /// <summary>
    /// Sql查询条件
    /// </summary>
    public abstract class SqlConditionBase : ISqlCondition
    {
        /// <summary>
        /// Sql参数管理器
        /// </summary>
        protected readonly IParameterManager ParameterManager;
        /// <summary>
        /// 列名
        /// </summary>
        protected readonly string Column;
        /// <summary>
        /// 值
        /// </summary>
        protected readonly object Value;
        /// <summary>
        /// 是否参数化
        /// </summary>
        protected readonly bool IsParameterization;

        /// <summary>
        /// 初始化Sql查询条件
        /// </summary>
        /// <param name="parameterManager">Sql参数管理器</param>
        /// <param name="column">列名</param>
        /// <param name="value">值</param>
        /// <param name="isParameterization">是否参数化</param>
        protected SqlConditionBase(IParameterManager parameterManager, string column, object value, bool isParameterization)
        {
            ParameterManager = parameterManager ?? throw new ArgumentNullException(nameof(parameterManager));
            if (string.IsNullOrWhiteSpace(column))
                throw new ArgumentNullException(nameof(column));
            Column = column;
            Value = value;
            IsParameterization = isParameterization;
        }

        /// <summary>
        /// 添加到字符串生成器
        /// </summary>
        /// <param name="builder">字符串生成器</param>
        public virtual void AppendTo(StringBuilder builder)
        {
            if (Value is ISqlBuilder sqlBuilder)
            {
                AppendSqlBuilder(builder, Column, sqlBuilder);
                return;
            }
            if (IsParameterization)
            {
                AppendParameterizedCondition(builder);
                return;
            }
            AppendNonParameterizedCondition(builder);
        }

        /// <summary>
        /// 添加Sql生成器
        /// </summary>
        /// <param name="builder">字符串生成器</param>
        /// <param name="column">列名</param>
        /// <param name="sqlBuilder">Sql生成器</param>
        protected virtual void AppendSqlBuilder(StringBuilder builder, string column, ISqlBuilder sqlBuilder)
        {
            throw new NotImplementedException();
        }

        /// <summary>
        /// 添加参数化条件
        /// </summary>
        /// <param name="builder">字符串生成器</param>
        protected virtual void AppendParameterizedCondition(StringBuilder builder)
        {
            var paramName = GenerateParamName();
            var value = GetValue();
            ParameterManager.Add(paramName, value);
            AppendCondition(builder, Column, paramName);
        }

        /// <summary>
        /// 创建参数名
        /// </summary>
        protected virtual string GenerateParamName()
        {
            return ParameterManager.GenerateName();
        }

        /// <summary>
        /// 获取参数值
        /// </summary>
        protected virtual object GetValue()
        {
            return Value;
        }

        /// <summary>
        /// 添加Sql条件
        /// </summary>
        /// <param name="builder">字符串生成器</param>
        /// <param name="column">列名</param>
        /// <param name="value">值</param>
        protected abstract void AppendCondition(StringBuilder builder, string column, object value);

        /// <summary>
        /// 添加非参数化条件
        /// </summary>
        /// <param name="builder">字符串生成器</param>
        protected virtual void AppendNonParameterizedCondition(StringBuilder builder)
        {
            AppendCondition(builder, Column, GetValue());
        }
    }

    /// <summary>
    /// Sql头匹配查询条件
    /// </summary>
    public class StartsCondition : SqlConditionBase
    {
        /// <summary>
        /// 初始化Sql头匹配查询条件
        /// </summary>
        public StartsCondition(IParameterManager parameterManager, string column, object value, bool isParameterization)
            : base(parameterManager, column, value, isParameterization)
        {
        }

        /// <summary>
        /// 获取参数值
        /// </summary>
        protected override object GetValue()
        {
            return $"{Value}%";
        }

        /// <summary>
        /// 添加Sql条件
        /// </summary>
        /// <param name="builder">字符串生成器</param>
        /// <param name="column">列名</param>
        /// <param name="value">值</param>
        protected override void AppendCondition(StringBuilder builder, string column, object value)
        {
            builder.AppendFormat("{0} Like {1}", column, value);
        }

        /// <summary>
        /// 添加非参数化条件
        /// </summary>
        /// <param name="builder">字符串生成器</param>
        protected override void AppendNonParameterizedCondition(StringBuilder builder)
        {
            AppendCondition(builder, Column, $"'{GetValue()}'");
        }
    }

