    #region Core
    /// <summary>
    /// 列项
    /// </summary>
    public class ColumnItem
    {
        /// <summary>
        /// Sql方言
        /// </summary>
        private readonly IDialect _dialect;

        /// <summary>
        /// 初始化列项
        /// </summary>
        /// <param name="dialect">Sql方言</param>
        /// <param name="name">列名</param>
        public ColumnItem(IDialect dialect, string name)
        {
            _dialect = dialect;
            Resolve(name);
        }

        /// <summary>
        /// 解析
        /// </summary>
        private void Resolve(string name)
        {
            var item = new NameItem(name);
            TableAlias = item.Prefix;
            Name = item.Name;
            ColumnAlias = item.Alias;
        }

        /// <summary>
        /// 表别名
        /// </summary>
        public string TableAlias { get; set; }

        /// <summary>
        /// 列名
        /// </summary>
        public string Name { get; set; }

        /// <summary>
        /// 列别名
        /// </summary>
        public string ColumnAlias { get; set; }

        /// <summary>
        /// 获取结果
        /// </summary>
        public string ToResult()
        {
            var builder = new StringBuilder();
            AppendTo(builder);
            return builder.ToString();
        }

        /// <summary>
        /// 添加到字符串生成器
        /// </summary>
        /// <param name="builder">字符串生成器</param>
        public void AppendTo(StringBuilder builder)
        {
            AppendTableAlias(builder);
            AppendColumn(builder);
            AppendColumnAlias(builder);
        }

        /// <summary>
        /// 添加表别名
        /// </summary>
        private void AppendTableAlias(StringBuilder builder)
        {
            if (TableAlias.IsEmpty())
                return;
            builder.AppendFormat("{0}.", _dialect.GetSafeName(TableAlias));
        }

        /// <summary>
        /// 添加列名
        /// </summary>
        private void AppendColumn(StringBuilder builder)
        {
            if (Name.IsEmpty())
                return;
            builder.AppendFormat(_dialect.GetSafeName(Name));
        }

        /// <summary>
        /// 添加列别名
        /// </summary>
        private void AppendColumnAlias(StringBuilder builder)
        {
            if (ColumnAlias.IsEmpty())
                return;
            builder.AppendFormat(" As {0}", _dialect.GetSafeName(ColumnAlias));
        }
    }

    /// <summary>
    /// 公用表表达式CTE项
    /// </summary>
    public class CteItem
    {
        /// <summary>
        /// 初始化公用表表达式CTE项
        /// </summary>
        /// <param name="name">公用表表达式名称</param>
        /// <param name="builder">Sql生成器</param>
        public CteItem(string name, ISqlBuilder builder)
        {
            Name = name;
            Builder = builder;
        }

        /// <summary>
        /// 公用表表达式名称
        /// </summary>
        public string Name { get; }

        /// <summary>
        /// Sql生成器
        /// </summary>
        public ISqlBuilder Builder { get; }

        /// <summary>
        /// 复制公用表表达式CTE项
        /// </summary>
        public CteItem Clone()
        {
            return new CteItem(Name, Builder.Clone());
        }
    }

    /// <summary>
    /// Sql方言
    /// </summary>
    public abstract class DialectBase : IDialect
    {
        /// <summary>
        /// 获取起始转义标识符
        /// </summary>
        public abstract string GetOpeningIdentifier();

        /// <summary>
        /// 获取结束转义标识符
        /// </summary>
        public abstract string GetClosingIdentifier();

        /// <summary>
        /// 获取安全名称
        /// </summary>
        public virtual string GetSafeName(string name)
        {
            if (string.IsNullOrWhiteSpace(name))
                return string.Empty;
            if (name == "*")
                return name;
            return $"{GetOpeningIdentifier()}{FilterName(name)}{GetClosingIdentifier()}";
        }

        /// <summary>
        /// 过滤名称
        /// </summary>
        private string FilterName(string name)
        {
            return name.Trim().RemoveStart(GetOpeningIdentifier()).RemoveEnd(GetClosingIdentifier());
        }

        /// <summary>
        /// 获取参数前缀
        /// </summary>
        public abstract string GetPrefix();

        /// <summary>
        /// Select子句是否支持As关键字
        /// </summary>
        public virtual bool SupportSelectAs()
        {
            return true;
        }

        /// <summary>
        /// 替换Sql,将[]替换为特定Sql转义符
        /// </summary>
        /// <param name="sql">原始Sql</param>
        public virtual string ReplaceSql(string sql)
        {
            return sql?
                .Replace("[[", "|&<&|", StringComparison.Ordinal)
                .Replace("]]", "|&>&|", StringComparison.Ordinal)
                .Replace("[", GetOpeningIdentifier(), StringComparison.Ordinal)
                .Replace("]", GetClosingIdentifier(), StringComparison.Ordinal)
                .Replace("|&<&|", "[", StringComparison.Ordinal)
                .Replace("|&>&|", "]", StringComparison.Ordinal);
        }
    }

    /// <summary>
    /// 名称项,用于拆分列名或表名
    /// </summary>
    public class NameItem
    {
        /// <summary>
        /// 初始化名称项
        /// </summary>
        /// <param name="name">名称</param>
        public NameItem(string name)
        {
            Resolve(name);
        }

        /// <summary>
        /// 解析
        /// </summary>
        private void Resolve(string name)
        {
            name = Filter(name);
            var asItem = new SplitItem(name);
            Alias = asItem.Right;
            var dotItem = new SplitItem(asItem.Left, ".");
            if (dotItem.Right.IsEmpty())
            {
                Name = dotItem.Left;
                return;
            }
            Prefix = dotItem.Left;
            Name = dotItem.Right;
        }

        /// <summary>
        /// 过滤
        /// </summary>
        private string Filter(string name)
        {
            name = FilterAs(name);
            return FilterDotSpace(name);
        }

        /// <summary>
        /// 过滤as关键字,替换为空格
        /// </summary>
        private string FilterAs(string name)
        {
            return name.Replace(" as ", " ", StringComparison.OrdinalIgnoreCase);
        }

        /// <summary>
        /// 过滤.前后空格
        /// </summary>
        private string FilterDotSpace(string name)
        {
            return name.Replace(@" .", ".").Replace(@". ", ".");
        }

        /// <summary>
        /// 前缀，范例:a.b As c，值为 a
        /// </summary>
        public string Prefix { get; private set; }

        /// <summary>
        /// 名称，范例:a.b As c，值为 b
        /// </summary>
        public string Name { get; private set; }

        /// <summary>
        /// 别名，范例:a.b As c，值为 c
        /// </summary>
        public string Alias { get; private set; }
    }

    /// <summary>
    /// 排序项
    /// </summary>
    public class OrderByItem
    {
        /// <summary>
        /// 初始化排序项
        /// </summary>
        /// <param name="order">排序表达式</param>
        public OrderByItem(string order)
        {
            Column = order.SafeString().Trim();
            if (Column.EndsWith(" Asc", StringComparison.OrdinalIgnoreCase))
            {
                Column = Column.Substring(0, Column.Length - 3).Trim();
                return;
            }
            if (Column.EndsWith(" Desc", StringComparison.OrdinalIgnoreCase))
            {
                Desc = true;
                Column = Column.Substring(0, Column.Length - 4).Trim();
            }
        }

        /// <summary>
        /// 排序列
        /// </summary>
        public string Column { get; }

        /// <summary>
        /// 是否倒排
        /// </summary>
        public bool Desc { get; }
    }

    /// <summary>
    /// 拆分项
    /// </summary>
    public class SplitItem
    {
        /// <summary>
        /// 初始化拆分项
        /// </summary>
        /// <param name="value">值</param>
        /// <param name="separator">拆分字符</param>
        public SplitItem(string value, string separator = " ")
        {
            if (string.IsNullOrEmpty(value))
                return;
            var list = value.Trim().Split(separator).Where(item => item.IsEmpty() == false).ToList();
            if (list.Count == 1)
            {
                Left = list[0];
                return;
            }
            if (list.Count == 2)
            {
                Left = list[0];
                Right = list[1];
            }
        }

        /// <summary>
        /// 左拆分值
        /// </summary>
        public string Left { get; set; }

        /// <summary>
        /// 右拆分值
        /// </summary>
        public string Right { get; set; }
    }

    /// <summary>
    /// Sql生成器项 - 用于子查询
    /// </summary>
    public class SqlBuilderItem
    {
        /// <summary>
        /// Sql方言
        /// </summary>
        private readonly IDialect _dialect;
        /// <summary>
        /// Sql生成器实例
        /// </summary>
        private readonly ISqlBuilder _builder;
        /// <summary>
        /// 别名
        /// </summary>
        private readonly string _alias;

        /// <summary>
        /// 初始化Sql生成器列项
        /// </summary>
        /// <param name="dialect">Sql方言</param>
        /// <param name="builder">Sql生成器实例</param>
        /// <param name="alias">别名</param>
        public SqlBuilderItem(IDialect dialect, ISqlBuilder builder, string alias = null)
        {
            _dialect = dialect;
            _builder = builder;
            _alias = alias;
        }

        /// <summary>
        /// 添加到字符串生成器
        /// </summary>
        /// <param name="builder">字符串生成器</param>
        public void AppendTo(StringBuilder builder)
        {
            builder.Append("(");
            _builder.AppendTo(builder);
            builder.Append(")");
            if (_alias.IsEmpty())
                return;
            builder.AppendFormat(" As {0}", _dialect.GetSafeName(_alias));
        }
    }

    /// <summary>
    /// 表项
    /// </summary>
    public class TableItem
    {
        /// <summary>
        /// Sql方言
        /// </summary>
        private readonly IDialect _dialect;

        /// <summary>
        /// 初始化表项
        /// </summary>
        /// <param name="dialect">Sql方言</param>
        /// <param name="name">列名</param>
        public TableItem(IDialect dialect, string name)
        {
            _dialect = dialect;
            Resolve(name);
        }

        /// <summary>
        /// 解析
        /// </summary>
        private void Resolve(string name)
        {
            var item = new NameItem(name);
            Schema = item.Prefix;
            Name = item.Name;
            TableAlias = item.Alias;
        }

        /// <summary>
        /// 架构名
        /// </summary>
        public string Schema { get; set; }

        /// <summary>
        /// 表名
        /// </summary>
        public string Name { get; set; }

        /// <summary>
        /// 表别名
        /// </summary>
        public string TableAlias { get; set; }

        /// <summary>
        /// 验证是否有效
        /// </summary>
        public bool Validate()
        {
            return !string.IsNullOrWhiteSpace(Name);
        }

        /// <summary>
        /// 获取结果
        /// </summary>
        public string ToResult()
        {
            var builder = new StringBuilder();
            AppendTo(builder);
            return builder.ToString();
        }

        /// <summary>
        /// 添加到字符串生成器
        /// </summary>
        /// <param name="builder">字符串生成器</param>
        public virtual void AppendTo(StringBuilder builder)
        {
            AppendSchema(builder);
            AppendTable(builder);
            AppendTableAlias(builder);
        }

        /// <summary>
        /// 添加架构名
        /// </summary>
        private void AppendSchema(StringBuilder builder)
        {
            if (Schema.IsEmpty())
                return;
            builder.AppendFormat("{0}.", _dialect.GetSafeName(Schema));
        }

        /// <summary>
        /// 添加表名
        /// </summary>
        private void AppendTable(StringBuilder builder)
        {
            if (Name.IsEmpty())
                return;
            builder.AppendFormat(_dialect.GetSafeName(Name));
        }

        /// <summary>
        /// 添加表别名
        /// </summary>
        private void AppendTableAlias(StringBuilder builder)
        {
            if (TableAlias.IsEmpty())
                return;
            builder.AppendFormat(" {0}", _dialect.GetSafeName(TableAlias));
        }
    }

