        /// </summary>
        /// <param name="name">参数名</param>
        bool Contains(string name);
        /// <summary>
        /// 获取参数
        /// </summary>
        /// <param name="name">参数名</param>
        SqlParam GetParam(string name);
        /// <summary>
        /// 获取参数值
