        /// <summary>
        /// Join子句
        /// </summary>
        private IJoinClause _joinClause;
        /// <summary>
        /// Where子句
        /// </summary>
        private IWhereClause _whereClause;
        /// <summary>
        /// GroupBy子句
        /// </summary>
