        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化Sql生成器
        /// </summary>
        /// <param name="parameterManager">Sql参数管理器</param>
        protected SqlBuilderBase(IParameterManager parameterManager = null)
        {
            _parameterManager = parameterManager;
        }

        #endregion

        #region 属性

        /// <summary>
        /// Sql方言
        /// </summary>
        public IDialect Dialect => _dialect ??= CreateDialect();
        /// <summary>
        /// 列缓存
        /// </summary>
        public IColumnCache ColumnCache => _columnCache ??= CreateColumnCache();
        /// <summary>
        /// 参数管理器
        /// </summary>
        public IParameterManager ParameterManager => _parameterManager ??= CreateParameterManager();
        /// <summary>
        /// Sql条件工厂
        /// </summary>
        public IConditionFactory ConditionFactory => _conditionFactory ??= CreateConditionFactory();
        /// <summary>
        /// 起始子句
        /// </summary>
        public IStartClause StartClause => _startClause ??= CreateStartClause();
        /// <summary>
        /// Select子句
        /// </summary>
        public ISelectClause SelectClause => _selectClause ??= CreateSelectClause();
        /// <summary>
        /// From子句
        /// </summary>
        public IFromClause FromClause => _fromClause ??= CreateFromClause();
        /// <summary>
        /// Join子句
        /// </summary>
        public IJoinClause JoinClause => _joinClause ??= CreateJoinClause();
        /// <summary>
        /// Where子句
        /// </summary>
        public IWhereClause WhereClause => _whereClause ??= CreatewWhereClause();
        /// <summary>
        /// GroupBy子句
        /// </summary>
        public IGroupByClause GroupByClause => _groupByClause ??= CreateGroupByClause();
        /// <summary>
        /// OrderBy子句
        /// </summary>
        public IOrderByClause OrderByClause => _orderByClause ??= CreateOrderByClause();
        /// <summary>
        /// Insert子句
        /// </summary>
        public IInsertClause InsertClause => _insertClause ??= CreateInsertClause();
        /// <summary>
        /// 结束子句
        /// </summary>
        public IEndClause EndClause => _endClause ??= CreateEndClause();
        /// <summary>
        /// Sql生成器集合
        /// </summary>
        public ISqlBuilderSet SqlBuilderSet => _sqlBuilderSet ??= CreateSqlBuilderSet();

        #endregion

        #region 工厂方法

        /// <summary>
        /// 创建Sql方言
        /// </summary>
        protected abstract IDialect CreateDialect();

        /// <summary>
        /// 创建列缓存
        /// </summary>
        protected abstract IColumnCache CreateColumnCache();

        /// <summary>
        /// 创建参数管理器
        /// </summary>
        protected virtual IParameterManager CreateParameterManager()
        {
            return new ParameterManager(Dialect);
        }

        /// <summary>
        /// 创建Sql条件工厂
        /// </summary>
        protected virtual IConditionFactory CreateConditionFactory()
        {
            return new SqlConditionFactory(ParameterManager);
        }

        /// <summary>
        /// 创建起始子句
        /// </summary>
        protected virtual IStartClause CreateStartClause()
        {
            return new StartClause(this);
        }

        /// <summary>
        /// 创建Insert子句
        /// </summary>
        protected virtual IInsertClause CreateInsertClause()
        {
            return new InsertClause(this);
        }

        /// <summary>
        /// 创建Select子句
        /// </summary>
        protected virtual ISelectClause CreateSelectClause()
        {
            return new SelectClause(this);
        }

        /// <summary>
        /// 创建From子句
        /// </summary>
        protected virtual IFromClause CreateFromClause()
        {
            return new FromClause(this);
        }

        /// <summary>
        /// 创建Join子句
        /// </summary>
        protected virtual IJoinClause CreateJoinClause()
        {
            return new JoinClause(this);
        }

        /// <summary>
        /// 创建Where子句
        /// </summary>
        protected virtual IWhereClause CreatewWhereClause()
        {
            return new WhereClause(this);
        }

        /// <summary>
        /// 创建分组子句
        /// </summary>
        protected virtual IGroupByClause CreateGroupByClause()
        {
            return new GroupByClause(this);
        }

        /// <summary>
        /// 创建排序子句
        /// </summary>
        protected virtual IOrderByClause CreateOrderByClause()
        {
            return new OrderByClause(this);
        }

        /// <summary>
        /// 创建结束子句
        /// </summary>
        protected virtual IEndClause CreateEndClause()
        {
            return new EndClause(this);
        }

        /// <summary>
        /// 创建Sql生成器集合
        /// </summary>
        protected virtual ISqlBuilderSet CreateSqlBuilderSet()
        {
            return new SqlBuilderSet(this);
        }

        #endregion

        #region Clone(复制Sql生成器)

        /// <inheritdoc />
        public abstract ISqlBuilder Clone();

        /// <summary>
        /// 复制Sql生成器
        /// </summary>
        /// <param name="source">源Sql生成器</param>
        protected void Clone(SqlBuilderBase source)
        {
            _dialect = source._dialect;
            _columnCache = source._columnCache;
            _parameterManager = source._parameterManager?.Clone();
            _startClause = source._startClause?.Clone(this);
            _insertClause = source._insertClause?.Clone(this);
            _selectClause = source._selectClause?.Clone(this);
            _fromClause = source._fromClause?.Clone(this);
            _joinClause = source._joinClause?.Clone(this);
            _whereClause = source._whereClause?.Clone(this);
            _groupByClause = source._groupByClause?.Clone(this);
            _orderByClause = source._orderByClause?.Clone(this);
            _endClause = source._endClause?.Clone(this);
            _sqlBuilderSet = source._sqlBuilderSet?.Clone(this);
        }

        #endregion

        #region Clear(清理)

        /// <summary>
        /// 清理
        /// </summary>
        public ISqlBuilder Clear()
        {
            _parameterManager?.Clear();
            _startClause?.Clear();
            _insertClause?.Clear();
            _selectClause?.Clear();
            _fromClause?.Clear();
            _joinClause?.Clear();
            _whereClause?.Clear();
            _groupByClause?.Clear();
            _orderByClause?.Clear();
            _endClause?.Clear();
            _sqlBuilderSet?.Clear();
            return this;
        }

        #endregion

        #region New(创建Sql生成器)

        /// <summary>
        /// 创建Sql生成器
        /// </summary>
        public abstract ISqlBuilder New();

        #endregion

        #region GetSql(获取Sql语句)

        /// <summary>
        /// 生成Sql语句
        /// </summary>
        public virtual string GetSql()
        {
            return SqlBuilderSet.ToResult();
        }

        #endregion

        #region AppendTo(添加到字符串生成器)

        /// <summary>
        /// 添加到字符串生成器
        /// </summary>
        /// <param name="builder">字符串生成器</param>
        public void AppendTo(StringBuilder builder)
        {
            builder.CheckNull(nameof(builder));
            AppendSql(builder, _startClause);
            AppendSql(builder, _insertClause);
            AppendSql(builder, _selectClause);
            AppendSql(builder, _fromClause);
            AppendSql(builder, _joinClause);
            AppendSql(builder, _whereClause);
            AppendSql(builder, _groupByClause);
            AppendSql(builder, _orderByClause);
            AppendSql(builder, _endClause);
            builder.RemoveEnd($" {Common.Line}");
        }

        /// <summary>
        /// 添加Sql
        /// </summary>
        protected void AppendSql(StringBuilder builder, ISqlClause content)
        {
            if (content == null)
                return;
            if (content.Validate() == false)
                return;
            content.AppendTo(builder);
            builder.AppendLine(" ");
        }

        #endregion
    }

    /// <summary>
    /// Sql生成器结果
    /// </summary>
    public class SqlBuilderResult
    {
        /// <summary>
        /// Sql生成器结果
        /// </summary>
        private readonly string _sql;
        /// <summary>
        /// Sql参数列表
        /// </summary>
        private readonly List<SqlParam> _sqlParams;
        /// <summary>
        /// 参数字面值解析器
        /// </summary>
        private readonly IParamLiteralsResolver _resolver;
        /// <summary>
        /// Sql参数管理器
        /// </summary>
        private readonly IParameterManager _parameterManager;

        /// <summary>
        /// 初始化Sql生成器结果
        /// </summary>
        /// <param name="sql">Sql</param>
        /// <param name="sqlParams">Sql参数列表</param>
        /// <param name="resolver">参数字面值解析器</param>
        /// <param name="parameterManager">Sql参数管理器</param>
        public SqlBuilderResult(string sql, List<SqlParam> sqlParams, IParamLiteralsResolver resolver, IParameterManager parameterManager)
        {
            _sql = sql;
            _sqlParams = sqlParams ?? new List<SqlParam>();
            _resolver = resolver;
            _parameterManager = parameterManager;
        }

        /// <summary>
        /// 获取Sql语句
        /// </summary>
        public string GetSql()
        {
            return _sql;
        }

        /// <summary>
        /// 获取Sql参数列表
        /// </summary>
        public List<SqlParam> GetParams()
        {
            return _sqlParams;
        }

        /// <summary>
        /// 获取Sql参数值
        /// </summary>
        /// <typeparam name="T">参数值类型</typeparam>
        /// <param name="name">参数名</param>
        public T GetParam<T>(string name)
        {
            name = _parameterManager.NormalizeName(name);
            var result = _sqlParams.Find(t => t.Name?.ToUpperInvariant() == name?.ToUpperInvariant());
            if (result == null)
                return default;
            return Util.Helpers.Convert.To<T>(result.Value);
        }

        /// <summary>
        /// 获取调试Sql语句
        /// </summary>
        public virtual string GetDebugSql()
        {
            var sql = GetSql();
            var parameters = GetParams();
            foreach (var parameter in parameters)
                sql = Regex.Replace(sql, $@"{parameter.Name}\b", _resolver.GetParamLiterals(parameter.Value));
            return sql;
        }
    }

    /// <summary>
    /// Sql条件工厂
    /// </summary>
    public class SqlConditionFactory : IConditionFactory
    {
        /// <summary>
        /// Sql参数管理器
        /// </summary>
        private readonly IParameterManager _parameterManager;

        /// <summary>
        /// 初始化Sql条件工厂
        /// </summary>
        /// <param name="parameterManager">Sql参数管理器</param>
        public SqlConditionFactory(IParameterManager parameterManager)
        {
            _parameterManager = parameterManager ?? throw new ArgumentNullException(nameof(parameterManager));
        }

        /// <inheritdoc />
        public virtual ISqlCondition Create(string column, object value, Operator @operator, bool isParameterization = true)
        {
            if (IsInCondition(@operator, value))
                return new InCondition(_parameterManager, column, value, isParameterization);
            if (IsNotInCondition(@operator, value))
                return new NotInCondition(_parameterManager, column, value, isParameterization);
            switch (@operator)
            {
                case Operator.Equal:
                    return new EqualCondition(_parameterManager, column, value, isParameterization);
                case Operator.NotEqual:
                    return new NotEqualCondition(_parameterManager, column, value, isParameterization);
                case Operator.Greater:
                    return new GreaterCondition(_parameterManager, column, value, isParameterization);
                case Operator.GreaterEqual:
                    return new GreaterEqualCondition(_parameterManager, column, value, isParameterization);
                case Operator.Less:
                    return new LessCondition(_parameterManager, column, value, isParameterization);
                case Operator.LessEqual:
                    return new LessEqualCondition(_parameterManager, column, value, isParameterization);
                case Operator.Contains:
                    return new ContainsCondition(_parameterManager, column, value, isParameterization);
                case Operator.Starts:
                    return new StartsCondition(_parameterManager, column, value, isParameterization);
                case Operator.Ends:
                    return new EndsCondition(_parameterManager, column, value, isParameterization);
                default:
                    throw new NotImplementedException();
            }
        }

        /// <summary>
        /// 是否In条件
        /// </summary>
        private bool IsInCondition(Operator @operator, object value)
        {
            if (@operator == Operator.In)
                return true;
            return false;
        }

        /// <summary>
        /// 是否Not In条件
        /// </summary>
        private bool IsNotInCondition(Operator @operator, object value)
        {
            if (@operator == Operator.NotIn)
                return true;
            return false;
        }

        /// <inheritdoc />
        public virtual ISqlCondition Create(string column, object minValue, object maxValue, Boundary boundary, bool isParameterization = true)
        {
            return new SegmentCondition(_parameterManager, column, minValue, maxValue, boundary, isParameterization);
        }
    }

