        /// <summary>
        /// 转换为本地时间
        /// </summary>
        private static DateTime ToLocalTime(object date)
        {
            var result = Convert.ToDateTimeOrNull(date);
            if (result == null)
                return DateTime.MinValue;
            return Time.UtcToLocalTime(result.Value);
        }

