    #region Filters
    /// <summary>
    /// 逻辑删除过滤器
    /// </summary>
    public class DeleteFilter : FilterBase<IDelete>
    {
        /// <summary>
        /// 获取过滤表达式
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        public override Expression<Func<TEntity, bool>> GetExpression<TEntity>(object state) where TEntity : class
        {
            var unitOfWork = state as UnitOfWorkBase;
            Expression<Func<TEntity, bool>> expression = entity => !EF.Property<bool>(entity, "IsDeleted");
            if (unitOfWork == null)
                return expression;
            Expression<Func<TEntity, bool>> isEnabled = entity => !unitOfWork.IsDeleteFilterEnabled;
            return isEnabled.Or(expression);
        }
    }

    /// <summary>
    /// 数据过滤器基类
    /// </summary>
    /// <typeparam name="TFilterType">过滤器类型</typeparam>
    public abstract class FilterBase<TFilterType> : IFilter<TFilterType> where TFilterType : class
    {
        /// <summary>
        /// 过滤器是否启用
        /// </summary>
        public virtual bool IsEnabled { get; private set; } = true;

        /// <summary>
        /// 实体是否启用过滤器
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        public virtual bool IsEntityEnabled<TEntity>()
        {
            return typeof(TFilterType).IsAssignableFrom(typeof(TEntity));
        }

        /// <summary>
        /// 启用
        /// </summary>
        public virtual void Enable()
        {
            IsEnabled = true;
        }

        /// <summary>
        /// 禁用
        /// </summary>
        public virtual IDisposable Disable()
        {
            if (IsEnabled == false)
                return DisposeAction.Null;
            IsEnabled = false;
            return new DisposeAction(Enable);
        }

        /// <summary>
        /// 获取过滤表达式
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        /// <param name="state">参数</param>
        public abstract Expression<Func<TEntity, bool>> GetExpression<TEntity>(object state) where TEntity : class;
    }

    /// <summary>
    /// 数据过滤器管理器
    /// </summary>
    public class FilterManager : IFilterManager
    {
        /// <summary>
        /// 同步锁
        /// </summary>
        private static readonly object Sync = new();
        /// <summary>
        /// 过滤器类型列表
        /// </summary>
        private static readonly List<Type> _filterTypes = new();
        /// <summary>
        /// 过滤器字典
        /// </summary>
        private readonly Dictionary<Type, IFilter> _filters = new();
        /// <summary>
        /// 服务提供器
        /// </summary>
        private readonly IServiceProvider _serviceProvider;

        /// <summary>
        /// 初始化数据过滤器管理器
        /// </summary>
        /// <param name="serviceProvider">服务提供器</param>
        public FilterManager(IServiceProvider serviceProvider)
        {
            _serviceProvider = serviceProvider ?? throw new ArgumentNullException(nameof(serviceProvider));
        }

        /// <summary>
        /// 添加过滤器类型
        /// </summary>
        /// <typeparam name="TFilterType">过滤器类型</typeparam>
        public static void AddFilterType<TFilterType>()
        {
            var type = typeof(TFilterType);
            lock (Sync)
            {
                if (_filterTypes.Contains(type))
                    return;
                _filterTypes.Add(type);
            }
        }

        /// <summary>
        /// 移除过滤器类型
        /// </summary>
        /// <typeparam name="TFilterType">过滤器类型</typeparam>
        public static void RemoveFilterType<TFilterType>()
        {
            var type = typeof(TFilterType);
            lock (Sync)
            {
                if (_filterTypes.Contains(type))
                    _filterTypes.Remove(type);
            }
        }

        /// <summary>
        /// 清空过滤器类型
        /// </summary>
        public static void ClearFilterTypes()
        {
            _filterTypes.Clear();
        }

        /// <inheritdoc />
        public void EnableFilter<TFilterType>() where TFilterType : class
        {
            var filter = GetFilter<TFilterType>();
            filter?.Enable();
        }

        /// <inheritdoc />
        public IDisposable DisableFilter<TFilterType>() where TFilterType : class
        {
            var filter = GetFilter<TFilterType>();
            return filter?.Disable();
        }

        /// <inheritdoc />
        public IFilter GetFilter<TFilterType>() where TFilterType : class
        {
            return GetFilter(typeof(TFilterType));
        }

        /// <inheritdoc />
        public IFilter GetFilter(Type filterType)
        {
            if (_filters.ContainsKey(filterType) == false)
            {
                var serviceType = typeof(IFilter<>).MakeGenericType(filterType);
                var filter = _serviceProvider.GetService(serviceType);
                _filters.Add(filterType, (IFilter)filter);
            }
            return _filters[filterType];
        }

        /// <inheritdoc />
        public bool IsEntityEnabled<TEntity>()
        {
            foreach (var type in _filterTypes)
            {
                var filter = GetFilter(type);
                if (filter.IsEntityEnabled<TEntity>())
                    return true;
            }
            return false;
        }

        /// <inheritdoc />
        public bool IsEnabled<TFilterType>() where TFilterType : class
        {
            var filter = GetFilter<TFilterType>();
            if (filter == null)
                return false;
            return filter.IsEnabled;
        }

        /// <inheritdoc />
        public Expression<Func<TEntity, bool>> GetExpression<TEntity>(object state) where TEntity : class
        {
            Expression<Func<TEntity, bool>> expression = null;
            foreach (var type in _filterTypes)
            {
                var filter = GetFilter(type);
                if (filter.IsEntityEnabled<TEntity>())
                    expression = expression.And(filter.GetExpression<TEntity>(state));
            }
            return expression;
        }
    }

    /// <summary>
    /// 租户过滤器
    /// </summary>
    public class TenantFilter : FilterBase<ITenant>
    {
        /// <summary>
        /// 租户管理器
        /// </summary>
        private readonly ITenantManager _manager;

        /// <summary>
        /// 初始化租户过滤器
        /// </summary>
        /// <param name="manager">租户管理器</param>
        public TenantFilter(ITenantManager manager)
        {
            _manager = manager ?? throw new ArgumentNullException(nameof(manager));
        }

        /// <summary>
        /// 获取过滤表达式
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        public override Expression<Func<TEntity, bool>> GetExpression<TEntity>(object state) where TEntity : class
        {
            if (_manager.Enabled() == false)
                return null;
            if (_manager.IsDisableTenantFilter())
                return null;
            var unitOfWork = state as UnitOfWorkBase;
            if (unitOfWork == null)
                return null;
            Expression<Func<TEntity, bool>> isEnabled = entity => !unitOfWork.IsTenantFilterEnabled;
            Expression<Func<TEntity, bool>> expression = entity => EF.Property<string>(entity, "TenantId") == unitOfWork.CurrentTenantId;
            return isEnabled.Or(expression);
        }
    }

