        IMigrationService UpdateEfTool(string version = null);
        /// <summary>
        /// 添加迁移,执行命令: dotnet ef migrations add migrationName
        /// </summary>
        /// <param name="migrationName">迁移名称</param>
        /// <param name="dbContextRootPath">数据上下文项目根目录绝对路径,范例: D:\\Test\\src\\Test.Data.SqlServer</param>
        /// <param name="isRemoveForeignKeys">是否移除迁移文件中的所有外键</param>
        IMigrationService AddMigration(string migrationName, string dbContextRootPath, bool isRemoveForeignKeys = false);
        /// <summary>
        /// 执行迁移,执行命令: dotnet ef database update
        /// </summary>
        /// <param name="dbContextRootPath">数据上下文项目根目录绝对路径,范例: D:\\Test\\src\\Test.Data.SqlServer</param>
        void Migrate(string dbContextRootPath);
    }

    /// <summary>
    /// 迁移文件服务
    /// </summary>
    public class MigrationFileService : IMigrationFileService
    {
        /// <summary>
        /// 日志
        /// </summary>
        private readonly ILogger<MigrationFileService> _logger;
        /// <summary>
        /// 迁移目录绝对路径
        /// </summary>
        private string _migrationsPath;
        /// <summary>
        /// 迁移名称
        /// </summary>
        private string _migrationName;
        /// <summary>
        /// 是否移除所有外键
        /// </summary>
        private bool _isRemoveForeignKeys;

        /// <summary>
        /// 初始化迁移文件服务
        /// </summary>
        /// <param name="logger">日志</param>
        public MigrationFileService(ILogger<MigrationFileService> logger)
        {
            _logger = logger ?? NullLogger<MigrationFileService>.Instance;
        }

        /// <inheritdoc />
        public IMigrationFileService MigrationsPath(string path)
        {
            _migrationsPath = path;
            return this;
        }

        /// <inheritdoc />
        public IMigrationFileService MigrationName(string name)
        {
            _migrationName = name;
            return this;
        }

        /// <inheritdoc />
        public IMigrationFileService RemoveForeignKeys()
        {
            _isRemoveForeignKeys = true;
            return this;
        }

        /// <inheritdoc />
        public string GetFilePath()
        {
            if (_migrationsPath.IsEmpty())
                return null;
            if (_migrationName.IsEmpty())
                return null;
            var files = Util.Helpers.File.GetAllFiles(_migrationsPath, "*.cs");
            var file = files.FirstOrDefault(t => t.Name.EndsWith($"{_migrationName}.cs"));
            if (file == null)
                return null;
            return file.FullName;
        }

        /// <inheritdoc />
        public string GetContent()
        {
            var filePath = GetFilePath();
            if (filePath.IsEmpty())
                return null;
            return Util.Helpers.File.ReadToString(filePath);
        }

        /// <inheritdoc />
        public void Save(string filePath = null)
        {
            if (_isRemoveForeignKeys == false)
                return;
            if (filePath.IsEmpty())
                filePath = GetFilePath();
            var content = GetContent();
            var pattern = @"table.ForeignKey\([\s\S]+?\);";
            var result = Util.Helpers.Regex.Replace(content, pattern, "");
            pattern = @$"\s+{Common.Line}\s+{Common.Line}";
            result = Util.Helpers.Regex.Replace(result, pattern, Common.Line);
            Util.Helpers.File.Write(filePath, result);
            _logger.LogTrace($"修改迁移文件并保存成功,路径:{filePath}");
        }
    }

    /// <summary>
    /// 迁移服务
    /// </summary>
    public class MigrationService : IMigrationService
    {
        /// <summary>
        /// 日志
        /// </summary>
        private readonly ILogger<MigrationService> _logger;
        /// <summary>
        /// 迁移文件服务
        /// </summary>
        private readonly IMigrationFileService _migrationFileService;

        /// <summary>
        /// 初始化迁移服务
        /// </summary>
        /// <param name="logger">日志</param>
        /// <param name="migrationFileService">迁移文件服务</param>
        public MigrationService(ILogger<MigrationService> logger, IMigrationFileService migrationFileService)
        {
            _logger = logger ?? NullLogger<MigrationService>.Instance;
            _migrationFileService = migrationFileService ?? throw new ArgumentNullException(nameof(migrationFileService));
        }

        /// <inheritdoc />
        public IMigrationService InstallEfTool(string version = null)
        {
            _logger.LogTrace("准备安装 dotnet-ef 全局工具.");
            var versionArgs = version.IsEmpty() ? null : $" --version {version}";
            CommandLine.Create("dotnet", $"tool install -g dotnet-ef{versionArgs}")
                .OutputToMatch("dotnet-ef")
                .Log(_logger)
                .Execute();
            return this;
        }

        /// <inheritdoc />
        public IMigrationService UninstallEfTool()
        {
            _logger.LogTrace("准备卸载 dotnet-ef 全局工具.");
            CommandLine.Create("dotnet", "tool uninstall -g dotnet-ef")
                .OutputToMatch("dotnet-ef")
                .Log(_logger)
                .Execute();
            return this;
        }

        /// <inheritdoc />
        public IMigrationService UpdateEfTool(string version = null)
        {
            _logger.LogTrace("准备更新 dotnet-ef 全局工具.");
            var versionArgs = version.IsEmpty() ? null : $" --version {version}";
            CommandLine.Create("dotnet", $"tool update -g dotnet-ef{versionArgs}")
                .OutputToMatch("dotnet-ef")
                .Log(_logger)
                .Execute();
            return this;
        }

        /// <inheritdoc />
        public IMigrationService AddMigration(string migrationName, string dbContextRootPath, bool isRemoveForeignKeys = false)
        {
            if (migrationName.IsEmpty())
                throw new ArgumentException("必须设置迁移名称");
            if (dbContextRootPath.IsEmpty())
                throw new ArgumentException("必须设置数据上下文项目根目录绝对路径");
            _logger.LogTrace("准备添加 ef 迁移.");
            CommandLine.Create("dotnet", $"ef migrations add {migrationName}")
                .WorkingDirectory(dbContextRootPath)
                .OutputToMatch("Done")
                .OutputToMatch("used by an existing migration")
                .Log(_logger)
                .Execute();
            if (isRemoveForeignKeys)
                RemoveMigrationFileForeignKeys(migrationName, dbContextRootPath);
            return this;
        }

        /// <summary>
        /// 删除迁移文件中的外键设置
        /// </summary>
        private void RemoveMigrationFileForeignKeys(string migrationName, string dbContextRootPath)
        {
            _logger.LogTrace("准备移除迁移文件中的外键设置.");
            var migrationsPath = Common.JoinPath(dbContextRootPath, "Migrations");
            _migrationFileService
                .MigrationsPath(migrationsPath)
                .MigrationName(migrationName)
                .RemoveForeignKeys()
                .Save();
        }

        /// <inheritdoc />
        public void Migrate(string dbContextRootPath)
        {
            _logger.LogTrace("准备执行 ef 迁移更新数据库.");
            CommandLine.Create("dotnet", "ef database update")
                .WorkingDirectory(dbContextRootPath)
                .OutputToMatch("The ConnectionString property has not been initialized")
                .OutputToMatch("The server was not found or was not accessible")
                .OutputToMatch("There is already an object named")
                .OutputToMatch("Applying migration")
                .OutputToMatch("Done")
                .Log(_logger)
                .Execute();
        }
    }

    #endregion

