    #region ValueComparers
    /// <summary>
    /// 扩展属性值比较器
    /// </summary>
    public class ExtraPropertyDictionaryValueComparer : ValueComparer<ExtraPropertyDictionary>
    {
        /// <summary>
        /// 初始化扩展属性值比较器
        /// </summary>
        public ExtraPropertyDictionaryValueComparer()
            : base(
                (extraProperties1, extraProperties2) => GetJson(extraProperties1) == GetJson(extraProperties2),
                extraProperties => extraProperties.Aggregate(0, (key, value) => HashCode.Combine(key, value.GetHashCode())),
                extraProperties => new ExtraPropertyDictionary(extraProperties))
        {
        }

        /// <summary>
        /// 获取Json
        /// </summary>
        private static string GetJson(ExtraPropertyDictionary extraProperties)
        {
            var options = new JsonSerializerOptions { DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull };
            return Json.ToJson(extraProperties, options);
        }
    }
    #endregion

    #region ValueConverters
    /// <summary>
    /// 日期值转换器,用于处理Utc日期
    /// </summary>
    public class DateTimeValueConverter : ValueConverter<DateTime?, DateTime?>
    {
        /// <summary>
        /// 初始化日期值转换器
        /// </summary>
        public DateTimeValueConverter()
            : base(date => Normalize(date), date => ToLocalTime(date))
        {
        }

        /// <summary>
        /// 转换为标准化日期
        /// </summary>
        public static DateTime? Normalize(DateTime? date)
        {
            return date.HasValue ? Time.Normalize(date.Value) : null;
        }

        /// <summary>
        /// 转换为本地化日期
        /// </summary>
        public static DateTime? ToLocalTime(DateTime? date)
        {
            return date.HasValue ? Time.UtcToLocalTime(date.Value) : null;
        }
    }

    /// <summary>
    /// 扩展属性值转换器
    /// </summary>
    public class ExtraPropertiesValueConverter : ValueConverter<ExtraPropertyDictionary, string>
    {
        /// <summary>
        /// 初始化扩展属性值转换器
        /// </summary>
        public ExtraPropertiesValueConverter()
            : base(extraProperties => PropertiesToJson(extraProperties), json => JsonToProperties(json))
        {
        }

        /// <summary>
        /// 扩展属性转换为json
        /// </summary>
        private static string PropertiesToJson(ExtraPropertyDictionary extraProperties)
        {
            var options = new JsonSerializerOptions
            {
                DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
                Encoder = JavaScriptEncoder.Create(UnicodeRanges.All),
                Converters = {
                new UtcDateTimeJsonConverter(),
                new UtcNullableDateTimeJsonConverter()
            }
            };
            return Json.ToJson(extraProperties, options);
        }

        /// <summary>
        /// json转换为扩展属性
        /// </summary>
        private static ExtraPropertyDictionary JsonToProperties(string json)
        {
            if (json.IsEmpty() || json == "{}")
                return new ExtraPropertyDictionary();
            var options = new JsonSerializerOptions { PropertyNameCaseInsensitive = true };
            return Json.ToObject<ExtraPropertyDictionary>(json, options) ?? new ExtraPropertyDictionary();
        }
    }

    /// <summary>
    /// 字符串值转换器,用于清除两端空白
    /// </summary>
    public class TrimStringValueConverter : ValueConverter<string, string>
    {
        /// <summary>
        /// 初始化字符串值转换器
        /// </summary>
        public TrimStringValueConverter()
            : base(value => value.SafeString(), value => value)
        {
        }
    }

