    /// <summary>
    /// 存储器
    /// </summary>
    /// <typeparam name="TEntity">实体类型</typeparam>
    /// <typeparam name="TKey">实体标识类型</typeparam>
    public abstract class StoreBase<TEntity, TKey> : IStore<TEntity, TKey>, IFilterSwitch, ITrack where TEntity : class, IKey<TKey>
    {

        #region 字段

        /// <summary>
        /// 是否已释放
        /// </summary>
        private bool _disposed;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化存储器
        /// </summary>
        /// <param name="unitOfWork">工作单元</param>
        protected StoreBase(IUnitOfWork unitOfWork)
        {
            UnitOfWork = (UnitOfWorkBase)unitOfWork;
        }

        #endregion

        #region 属性

        /// <summary>
        /// 工作单元
        /// </summary>
        protected UnitOfWorkBase UnitOfWork { get; }

        /// <summary>
        /// 实体集
        /// </summary>
        protected DbSet<TEntity> Set => UnitOfWork.Set<TEntity>();

        /// <summary>
        /// 查询时是否跟踪对象
        /// </summary>
        protected bool IsTracking { get; private set; } = true;

        #endregion

        #region NoTracking(设置为不跟踪实体)

        /// <summary>
        /// 设置为不跟踪实体
        /// </summary>
        public void NoTracking()
        {
            IsTracking = false;
        }

        #endregion

        #region EnableFilter(启用过滤器)

        /// <summary>
        /// 启用过滤器
        /// </summary>
        /// <typeparam name="TFilterType">过滤器类型</typeparam>
        public void EnableFilter<TFilterType>() where TFilterType : class
        {
            UnitOfWork.EnableFilter<TFilterType>();
        }

        #endregion

        #region DisableFilter(禁用过滤器)

        /// <summary>
        /// 禁用过滤器
        /// </summary>
        /// <typeparam name="TFilterType">过滤器类型</typeparam>
        public IDisposable DisableFilter<TFilterType>() where TFilterType : class
        {
            return UnitOfWork.DisableFilter<TFilterType>();
        }

        #endregion

        #region Find(查找实体)

        /// <inheritdoc />
        public IQueryable<TEntity> Find()
        {
            ThrowIfDisposed();
            if (IsTracking)
                return Set;
            var result = Set.AsNoTracking();
            IsTracking = true;
            return result;
        }

        /// <inheritdoc />
        public IQueryable<TEntity> Find(ICondition<TEntity> condition)
        {
            return Find().Where(condition);
        }

        /// <inheritdoc />
        public IQueryable<TEntity> Find(Expression<Func<TEntity, bool>> condition)
        {
            return Find().Where(condition);
        }

        #endregion

        #region FindById(通过标识查找实体)

        /// <inheritdoc />
        public TEntity FindById(object id)
        {
            ThrowIfDisposed();
            if (id.SafeString().IsEmpty())
                return null;
            var key = GetKey(id);
            if (IsTracking)
                return Set.Find(key);
            return Single(t => t.Id.Equals(key));
        }

        /// <summary>
        /// 获取标识
        /// </summary>
        protected object GetKey(object id)
        {
            if (id is TKey)
                return id;
            return Util.Helpers.Convert.To<TKey>(id);
        }

        #endregion

        #region FindByIdAsync(通过标识查找实体)

        /// <inheritdoc />
        public async Task<TEntity> FindByIdAsync(object id, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            ThrowIfDisposed();
            if (id.SafeString().IsEmpty())
                return null;
            var key = GetKey(id);
            if (IsTracking)
                return await Set.FindAsync(new[] { key }, cancellationToken);
            return await SingleAsync(t => t.Id.Equals(key), cancellationToken);
        }

        #endregion

        #region FindByIds(通过标识列表查找实体列表)

        /// <inheritdoc />
        public virtual List<TEntity> FindByIds(params TKey[] ids)
        {
            return FindByIds((IEnumerable<TKey>)ids);
        }

        /// <inheritdoc />
        public virtual List<TEntity> FindByIds(IEnumerable<TKey> ids)
        {
            return ids == null ? null : Find(t => ids.Contains(t.Id)).ToList();
        }

        /// <inheritdoc />
        public virtual List<TEntity> FindByIds(string ids)
        {
            return FindByIds(Util.Helpers.Convert.ToList<TKey>(ids));
        }

        #endregion

        #region FindByIdsAsync(通过标识列表查找实体列表)

        /// <inheritdoc />
        public virtual async Task<List<TEntity>> FindByIdsAsync(params TKey[] ids)
        {
            return await FindByIdsAsync((IEnumerable<TKey>)ids);
        }

        /// <inheritdoc />
        public virtual async Task<List<TEntity>> FindByIdsAsync(IEnumerable<TKey> ids, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            return ids == null ? null : await Find(t => ids.Contains(t.Id)).ToListAsync(cancellationToken);
        }

        /// <inheritdoc />
        public virtual async Task<List<TEntity>> FindByIdsAsync(string ids, CancellationToken cancellationToken = default)
        {
            return await FindByIdsAsync(Util.Helpers.Convert.ToList<TKey>(ids), cancellationToken);
        }

        #endregion

        #region Single(查找单个实体)

        /// <inheritdoc />
        public virtual TEntity Single(Expression<Func<TEntity, bool>> condition)
        {
            return Find().FirstOrDefault(condition);
        }

        /// <inheritdoc />
        public virtual TEntity Single(Expression<Func<TEntity, bool>> condition, Func<IQueryable<TEntity>, IQueryable<TEntity>> action)
        {
            if (action == null)
                return Single(condition);
            return action(Find()).FirstOrDefault(condition);
        }

        #endregion

        #region SingleAsync(查找单个实体)

        /// <inheritdoc />
        public virtual async Task<TEntity> SingleAsync(Expression<Func<TEntity, bool>> condition, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            return await Find().FirstOrDefaultAsync(condition, cancellationToken);
        }

        /// <inheritdoc />
        public virtual async Task<TEntity> SingleAsync(Expression<Func<TEntity, bool>> condition, Func<IQueryable<TEntity>, IQueryable<TEntity>> action, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            if (action == null)
                return await SingleAsync(condition, cancellationToken);
            return await action(Find()).FirstOrDefaultAsync(condition, cancellationToken);
        }

        #endregion

        #region FindAll(查找实体列表)

        /// <inheritdoc />
        public virtual List<TEntity> FindAll(Expression<Func<TEntity, bool>> condition = null)
        {
            return condition == null ? Find().ToList() : Find(condition).ToList();
        }

        #endregion

        #region FindAllAsync(查找实体列表)

        /// <inheritdoc />
        public virtual async Task<List<TEntity>> FindAllAsync(Expression<Func<TEntity, bool>> condition = null, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            if (condition == null)
                return await Find().ToListAsync(cancellationToken);
            return await Find(condition).ToListAsync(cancellationToken);
        }

        #endregion

        #region Exists(判断是否存在)

        /// <inheritdoc />
        public virtual bool Exists(params TKey[] ids)
        {
            return ids != null && Exists(t => ids.Contains(t.Id));
        }

        /// <inheritdoc />
        public virtual bool Exists(Expression<Func<TEntity, bool>> condition)
        {
            return condition != null && Find().Any(condition);
        }

        #endregion

        #region ExistsAsync(判断是否存在)

        /// <inheritdoc />
        public virtual async Task<bool> ExistsAsync(params TKey[] ids)
        {
            return ids != null && await ExistsAsync(t => ids.Contains(t.Id));
        }

        /// <inheritdoc />
        public virtual async Task<bool> ExistsAsync(Expression<Func<TEntity, bool>> condition, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            return condition != null && await Find().AnyAsync(condition, cancellationToken);
        }

        #endregion

        #region Count(查找数量)

        /// <inheritdoc />
        public virtual int Count(Expression<Func<TEntity, bool>> condition = null)
        {
            return condition == null ? Find().Count() : Find().Count(condition);
        }

        #endregion

        #region CountAsync(查找数量)

        /// <inheritdoc />
        public virtual async Task<int> CountAsync(Expression<Func<TEntity, bool>> condition = null, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            return condition == null
                ? await Find().CountAsync(cancellationToken)
                : await Find().CountAsync(condition, cancellationToken);
        }

        #endregion

        #region AddAsync(添加实体)

        /// <summary>
        /// 添加实体
        /// </summary>
        /// <param name="entity">实体</param>
        /// <param name="cancellationToken">取消令牌</param>
        public virtual async Task AddAsync(TEntity entity, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            ThrowIfDisposed();
            Validate(entity);
            await Set.AddAsync(entity, cancellationToken);
        }

        /// <summary>
        /// 验证
        /// </summary>
        protected virtual void Validate(IEnumerable<TEntity> entities)
        {
            entities.CheckNull(nameof(entities));
            foreach (var entity in entities)
                Validate(entity);
        }

        /// <summary>
        /// 验证
        /// </summary>
        protected virtual void Validate(TEntity entity)
        {
            entity.CheckNull(nameof(entity));
            if (entity is IValidation validation)
                validation.Validate();
        }

        /// <summary>
        /// 添加实体集合
        /// </summary>
        /// <param name="entities">实体集合</param>
        /// <param name="cancellationToken">取消令牌</param>
        public virtual async Task AddAsync(IEnumerable<TEntity> entities, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            ThrowIfDisposed();
            var list = entities.ToList();
            Validate(list);
            await Set.AddRangeAsync(list, cancellationToken);
        }

        #endregion

        #region UpdateAsync(修改实体)

        /// <inheritdoc />
        public virtual Task UpdateAsync(TEntity entity, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            Update(entity);
            return Task.CompletedTask;
        }

        /// <summary>
        /// 更新
        /// </summary>
        protected void Update(TEntity entity)
        {
            ThrowIfDisposed();
            Validate(entity);
            var entry = UnitOfWork.Entry(entity);
            ValidateVersion(entry, entity);
            UpdateEntity(entry, entity);
        }

        /// <summary>
        /// 验证版本号
        /// </summary>
        protected virtual void ValidateVersion(EntityEntry<TEntity> entry, TEntity entity)
        {
            if (entity is not IVersion current)
                return;
            if (entry.State == EntityState.Added)
                return;
            if (current.Version == null || current.Version.Length == 0)
            {
                ThrowConcurrencyException(entity);
                return;
            }
            var oldVersion = entry.OriginalValues.GetValue<byte[]>("Version");
            for (int i = 0; i < oldVersion.Length; i++)
            {
                if (current.Version[i] != oldVersion[i])
                    ThrowConcurrencyException(entity);
            }
        }

        /// <summary>
        /// 抛出并发异常
        /// </summary>
        private void ThrowConcurrencyException(TEntity entity)
        {
            throw new ConcurrencyException(new Exception($"Type:{typeof(TEntity)},Id:{entity.Id}"));
        }

        /// <summary>
        /// 更新实体
        /// </summary>
        protected void UpdateEntity(EntityEntry<TEntity> entry, TEntity entity)
        {
            var oldEntry = UnitOfWork.ChangeTracker.Entries<TEntity>().FirstOrDefault(t => t.Entity.Equals(entity));
            if (oldEntry != null)
            {
                oldEntry.CurrentValues.SetValues(entity);
                return;
            }
            if (entry.State == EntityState.Detached)
                UnitOfWork.Update(entity);
        }

        /// <inheritdoc />
        public virtual Task UpdateAsync(IEnumerable<TEntity> entities, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            Update(entities);
            return Task.CompletedTask;
        }

        /// <summary>
        /// 更新实体集合
        /// </summary>
        protected void Update(IEnumerable<TEntity> entities)
        {
            ThrowIfDisposed();
            entities.CheckNull(nameof(entities));
            foreach (var entity in entities)
                Update(entity);
        }

        #endregion

        #region RemoveAsync(移除实体)

        /// <inheritdoc />
        public virtual async Task RemoveAsync(object id, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            ThrowIfDisposed();
            var entity = await FindByIdAsync(id, cancellationToken);
            Delete(entity);
        }

        /// <summary>
        /// 删除
        /// </summary>
        private void Delete(TEntity entity)
        {
            if (entity == null)
                return;
            if (entity is IDelete model)
            {
                model.IsDeleted = true;
                return;
            }
            Set.Remove(entity);
        }

        /// <inheritdoc />
        public virtual async Task RemoveAsync(TEntity entity, CancellationToken cancellationToken = default)
        {
            if (entity == null)
                return;
            await RemoveAsync(entity.Id, cancellationToken);
        }

        /// <inheritdoc />
        public virtual async Task RemoveAsync(IEnumerable<TKey> ids, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            ThrowIfDisposed();
            if (ids == null)
                return;
            var entities = await FindByIdsAsync(ids, cancellationToken);
            Delete(entities);
        }

        /// <summary>
        /// 删除实体集合
        /// </summary>
        private void Delete(List<TEntity> list)
        {
            if (list == null)
                return;
            if (!list.Any())
                return;
            foreach (var entity in list)
                Delete(entity);
        }

        /// <inheritdoc />
        public virtual async Task RemoveAsync(IEnumerable<TEntity> entities, CancellationToken cancellationToken = default)
        {
            if (entities == null)
                return;
            await RemoveAsync(entities.Select(t => t.Id), cancellationToken);
        }

        #endregion

        #region ThrowIfDisposed(已释放则抛出异常)

        /// <summary>
        /// 已释放则抛出异常
        /// </summary>
        protected void ThrowIfDisposed()
        {
            if (_disposed)
            {
                throw new ObjectDisposedException(GetType().Name);
            }
        }

        #endregion

        #region Dispose(释放)

        /// <summary>
        /// 释放
        /// </summary>
        public void Dispose()
        {
            _disposed = true;
        }

        #endregion
    }

    /// <summary>
    /// 工作单元基类
    /// </summary>
    public abstract class UnitOfWorkBase : DbContext, IUnitOfWork, IFilterSwitch
    {

        #region 构造方法

        /// <summary>
        /// 初始化工作单元
        /// </summary>
        /// <param name="serviceProvider">服务提供器</param>
        /// <param name="options">配置</param>
        protected UnitOfWorkBase(IServiceProvider serviceProvider, DbContextOptions options)
            : base(options)
        {
            ServiceProvider = serviceProvider ?? throw new ArgumentNullException(nameof(serviceProvider));
            Environment = serviceProvider.GetService<IHostEnvironment>();
            FilterManager = ServiceProvider.GetService<IFilterManager>();
            TenantManager = ServiceProvider.GetService<ITenantManager>() ?? NullTenantManager.Instance;
            Session = serviceProvider.GetService<ISession>() ?? NullSession.Instance;
            EventBus = serviceProvider.GetService<ILocalEventBus>() ?? NullEventBus.Instance;
            ActionManager = serviceProvider.GetService<IUnitOfWorkActionManager>() ?? NullUnitOfWorkActionManager.Instance;
            SaveBeforeEvents = new List<IEvent>();
            SaveAfterEvents = new List<IEvent>();
        }

        #endregion

        #region 属性

        /// <summary>
        /// 服务提供器
        /// </summary>
        protected IServiceProvider ServiceProvider { get; }
        /// <summary>
        /// 执行环境
        /// </summary>
        protected IHostEnvironment Environment { get; }
        /// <summary>
        /// 用户会话
        /// </summary>
        protected ISession Session { get; set; }
        /// <summary>
        /// 数据过滤器管理器
        /// </summary>
        protected IFilterManager FilterManager { get; }
        /// <summary>
        /// 租户管理器
        /// </summary>
        protected ITenantManager TenantManager { get; }
        /// <summary>
        /// 事件总线
        /// </summary>
        protected IEventBus EventBus { get; }
        /// <summary>
        /// 工作单元操作管理器
        /// </summary>
        protected IUnitOfWorkActionManager ActionManager { get; }
        /// <summary>
        /// 保存前发送的事件集合
        /// </summary>
        protected List<IEvent> SaveBeforeEvents { get; }
        /// <summary>
        /// 保存后发送的事件集合
        /// </summary>
        protected List<IEvent> SaveAfterEvents { get; }
        /// <summary>
        /// 逻辑删除过滤器是否启用
        /// </summary>
        public virtual bool IsDeleteFilterEnabled => FilterManager?.IsEnabled<IDelete>() ?? false;
        /// <summary>
        /// 租户过滤器是否启用
        /// </summary>
        public virtual bool IsTenantFilterEnabled => FilterManager?.IsEnabled<ITenant>() ?? false;
        /// <summary>
        /// 当前租户标识
        /// </summary>
        public virtual string CurrentTenantId => TenantManager.GetTenantId();
        /// <summary>
        /// 是否清除字符串两端的空白,默认为true
        /// </summary>
        protected virtual bool IsTrimString => true;

        #endregion

        #region 辅助操作

        /// <summary>
        /// 获取用户标识
        /// </summary>
        protected virtual string GetUserId()
        {
            return Session.UserId;
        }

        #endregion

        #region EnableFilter(启用过滤器)

        /// <summary>
        /// 启用过滤器
        /// </summary>
        /// <typeparam name="TFilterType">过滤器类型</typeparam>
        public void EnableFilter<TFilterType>() where TFilterType : class
        {
            FilterManager?.EnableFilter<TFilterType>();
        }

        #endregion

        #region DisableFilter(禁用过滤器)

        /// <summary>
        /// 禁用过滤器
        /// </summary>
        /// <typeparam name="TFilterType">过滤器类型</typeparam>
        public IDisposable DisableFilter<TFilterType>() where TFilterType : class
        {
            if (FilterManager == null)
                return DisposeAction.Null;
            return FilterManager.DisableFilter<TFilterType>();
        }

        #endregion

        #region OnConfiguring(配置)

        /// <summary>
        /// 配置
        /// </summary>
        /// <param name="optionsBuilder">配置生成器</param>
        protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
        {
            ConfigLog(optionsBuilder);
            ConfigTenant(optionsBuilder);
        }

        #endregion

        #region ConfigLog(配置日志)

        /// <summary>
        /// 配置日志
        /// </summary>
        /// <param name="optionsBuilder">配置生成器</param>
        protected virtual void ConfigLog(DbContextOptionsBuilder optionsBuilder)
        {
            if (Environment == null)
                return;
            if (Environment.IsProduction())
                return;
            optionsBuilder.EnableDetailedErrors().EnableSensitiveDataLogging();
        }

        #endregion

        #region ConfigTenant(配置租户)

        /// <summary>
        /// 配置租户
        /// </summary>
        /// <param name="optionsBuilder">配置生成器</param>
        protected virtual void ConfigTenant(DbContextOptionsBuilder optionsBuilder)
        {
            if (TenantManager.Enabled() == false)
                return;
            if (TenantManager.AllowMultipleDatabase() == false)
                return;
            var tenant = TenantManager.GetTenant();
            if (tenant == null)
                return;
            var name = ConnectionStringNameAttribute.GetName(GetType());
            var connectionString = tenant.ConnectionStrings.GetConnectionString(name);
            if (connectionString.IsEmpty())
                return;
            ConfigTenantConnectionString(optionsBuilder, connectionString);
        }

        /// <summary>
        /// 配置租户连接字符串
        /// </summary>
        /// <param name="optionsBuilder">配置生成器</param>
        /// <param name="connectionString">连接字符串</param>
        protected virtual void ConfigTenantConnectionString(DbContextOptionsBuilder optionsBuilder, string connectionString)
        {
        }

        #endregion

        #region OnModelCreating(配置模型)

        /// <summary>
        /// 配置模型
        /// </summary>
        /// <param name="modelBuilder">模型生成器</param>
        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            ApplyConfigurations(modelBuilder);
            foreach (var entityType in modelBuilder.Model.GetEntityTypes())
            {
                ApplyFilters(modelBuilder, entityType);
                ApplyExtraProperties(modelBuilder, entityType);
                ApplyVersion(modelBuilder, entityType);
                ApplyIsDeleted(modelBuilder, entityType);
                ApplyTenantId(modelBuilder, entityType);
                ApplyUtc(modelBuilder, entityType);
                ApplyTrimString(modelBuilder, entityType);
            }
        }

        #endregion

        #region ApplyConfigurations(配置实体类型)

        /// <summary>
        /// 配置实体类型
        /// </summary>
        /// <param name="modelBuilder">模型生成器</param>
        protected virtual void ApplyConfigurations(ModelBuilder modelBuilder)
        {
            modelBuilder.ApplyConfigurationsFromAssembly(GetType().Assembly);
        }

        #endregion

        #region ApplyFilters(配置过滤器)

        /// <summary>
        /// 配置过滤器
        /// </summary>
        /// <param name="modelBuilder">模型生成器</param>
        /// <param name="entityType">实体类型</param>
        protected virtual void ApplyFilters(ModelBuilder modelBuilder, IMutableEntityType entityType)
        {
            var method = GetType().GetMethod(nameof(ApplyFiltersImp), BindingFlags.Instance | BindingFlags.NonPublic);
            method?.MakeGenericMethod(entityType.ClrType).Invoke(this, new object[] { modelBuilder });
        }

        /// <summary>
        /// 配置过滤器
        /// </summary>
        /// <param name="modelBuilder">模型生成器</param>
        protected virtual void ApplyFiltersImp<TEntity>(ModelBuilder modelBuilder) where TEntity : class
        {
            if (FilterManager == null)
                return;
            if (FilterManager.IsEntityEnabled<TEntity>() == false)
                return;
            var expression = GetFilterExpression<TEntity>();
            if (expression == null)
                return;
            modelBuilder.Entity<TEntity>().HasQueryFilter(expression);
        }

        /// <summary>
        /// 获取过滤器表达式
        /// </summary>
        /// <typeparam name="TEntity">实体类型</typeparam>
        protected virtual Expression<Func<TEntity, bool>> GetFilterExpression<TEntity>() where TEntity : class
        {
            return FilterManager.GetExpression<TEntity>(this);
        }

        #endregion

        #region ApplyExtraProperties(配置扩展属性)

        /// <summary>
        /// 配置扩展属性
        /// </summary>
        /// <param name="modelBuilder">模型生成器</param>
        /// <param name="entityType">实体类型</param>
        protected virtual void ApplyExtraProperties(ModelBuilder modelBuilder, IMutableEntityType entityType)
        {
            if (typeof(IExtraProperties).IsAssignableFrom(entityType.ClrType) == false)
                return;
            modelBuilder.Entity(entityType.ClrType)
                .Property("ExtraProperties")
                .HasColumnName("ExtraProperties")
                .HasComment(R.ExtraProperties)
                .HasConversion(new ExtraPropertiesValueConverter())
                .Metadata.SetValueComparer(new ExtraPropertyDictionaryValueComparer());
        }

        #endregion

        #region ApplyVersion(配置乐观锁)

        /// <summary>
        /// 配置乐观锁
        /// </summary>
        /// <param name="modelBuilder">模型生成器</param>
        /// <param name="entityType">实体类型</param>
        protected virtual void ApplyVersion(ModelBuilder modelBuilder, IMutableEntityType entityType)
        {
            if (typeof(IVersion).IsAssignableFrom(entityType.ClrType) == false)
                return;
            modelBuilder.Entity(entityType.ClrType)
                .Property("Version")
                .HasColumnName("Version")
                .HasComment(R.Version)
                .IsConcurrencyToken();
        }

        #endregion

        #region ApplyIsDeleted(配置逻辑删除)

        /// <summary>
        /// 配置逻辑删除
        /// </summary>
        /// <param name="modelBuilder">模型生成器</param>
        /// <param name="entityType">实体类型</param>
        protected virtual void ApplyIsDeleted(ModelBuilder modelBuilder, IMutableEntityType entityType)
        {
            if (typeof(IDelete).IsAssignableFrom(entityType.ClrType) == false)
                return;
            modelBuilder.Entity(entityType.ClrType)
                .Property("IsDeleted")
                .HasColumnName("IsDeleted")
                .HasComment(R.IsDeleted);
        }

        #endregion

        #region ApplyTenantId(配置租户标识)

        /// <summary>
        /// 配置租户标识
        /// </summary>
        /// <param name="modelBuilder">模型生成器</param>
        /// <param name="entityType">实体类型</param>
        protected virtual void ApplyTenantId(ModelBuilder modelBuilder, IMutableEntityType entityType)
        {
            if (typeof(ITenant).IsAssignableFrom(entityType.ClrType) == false)
                return;
            modelBuilder.Entity(entityType.ClrType)
                .Property("TenantId")
                .HasColumnName("TenantId")
                .HasComment(R.TenantId);
        }

        #endregion

        #region ApplyUtc(配置Utc日期)

        /// <summary>
        /// 配置Utc日期
        /// </summary>
        /// <param name="modelBuilder">模型生成器</param>
        /// <param name="entityType">实体类型</param>
        protected virtual void ApplyUtc(ModelBuilder modelBuilder, IMutableEntityType entityType)
        {
            if (TimeOptions.IsUseUtc == false)
                return;
            var properties = entityType.ClrType.GetProperties()
                .Where(property => (property.PropertyType == typeof(DateTime) || property.PropertyType == typeof(DateTime?)) && property.CanWrite &&
                                    property.GetCustomAttribute<NotMappedAttribute>() == null)
                .ToList();
            properties.ForEach(property =>
            {
                modelBuilder.Entity(entityType.ClrType)
                    .Property(property.Name)
                    .HasConversion(new DateTimeValueConverter());
            });
        }

        #endregion

        #region ApplyTrimString(配置清除空白字符串)

        /// <summary>
        /// 配置清除空白字符串
        /// </summary>
        /// <param name="modelBuilder">模型生成器</param>
        /// <param name="entityType">实体类型</param>
        protected virtual void ApplyTrimString(ModelBuilder modelBuilder, IMutableEntityType entityType)
        {
            if (IsTrimString == false)
                return;
            var properties = entityType.ClrType.GetProperties()
                .Where(property => property.PropertyType == typeof(string) && property.CanWrite &&
                                    property.GetCustomAttribute<NotMappedAttribute>() == null)
                .ToList();
            properties.ForEach(property =>
            {
                modelBuilder.Entity(entityType.ClrType)
                    .Property(property.Name)
                    .HasConversion(new TrimStringValueConverter());
            });
        }

        #endregion

        #region CommitAsync(提交)

        /// <summary>
        /// 提交,返回影响的行数
        /// </summary>
        public async Task<int> CommitAsync()
        {
            try
            {
                return await SaveChangesAsync();
            }
            catch (DbUpdateConcurrencyException ex)
            {
                throw new ConcurrencyException(ex);
            }
        }

        #endregion

        #region SaveChangesAsync(保存)

        /// <summary>
        /// 保存
        /// </summary>
        public override async Task<int> SaveChangesAsync(CancellationToken cancellationToken = default)
        {
            await SaveChangesBefore();
            var result = await base.SaveChangesAsync(cancellationToken);
            await SaveChangesAfter();
            return result;
        }

        #endregion

        #region SaveChangesBefore(保存前操作)

        /// <summary>
        /// 保存前操作
        /// </summary>
        protected virtual async Task SaveChangesBefore()
        {
            foreach (var entry in ChangeTracker.Entries())
            {
                UpdateTenantId(entry);
                AddDomainEvents(entry);
                switch (entry.State)
                {
                    case EntityState.Added:
                        AddBefore(entry);
                        break;
                    case EntityState.Modified:
                        UpdateBefore(entry);
                        break;
                    case EntityState.Deleted:
                        DeleteBefore(entry);
                        break;
                }
            }
            await PublishSaveBeforeEventsAsync();
        }

        #endregion

        #region UpdateTenantId(更新租户标识)

        /// <summary>
        /// 更新租户标识
        /// </summary>
        protected virtual void UpdateTenantId(EntityEntry entry)
        {
            if (TenantManager.Enabled() == false)
                return;
            if (entry.Entity is not ITenant tenant)
                return;
            var tenantId = TenantManager.GetTenantId();
            if (tenantId.IsEmpty())
                return;
            tenant.TenantId = tenantId;
        }

        #endregion

        #region AddDomainEvents(添加领域事件)

        /// <summary>
        /// 添加领域事件
        /// </summary>
        protected virtual void AddDomainEvents(EntityEntry entry)
        {
            if (entry.Entity is not IDomainEventManager eventManager)
                return;
            if (eventManager.DomainEvents == null)
                return;
            foreach (var domainEvent in eventManager.DomainEvents)
            {
                if (domainEvent is IIntegrationEvent)
                {
                    SaveAfterEvents.Add(domainEvent);
                    continue;
                }
                SaveBeforeEvents.Add(domainEvent);
            }
            eventManager.ClearDomainEvents();
        }

        #endregion

        #region AddBefore(添加前操作)

        /// <summary>
        /// 添加前操作
        /// </summary>
        protected virtual void AddBefore(EntityEntry entry)
        {
            SetCreationAudited(entry.Entity);
            SetModificationAudited(entry.Entity);
            SetVersion(entry.Entity);
            AddEntityCreatedEvent(entry.Entity);
        }

        #endregion

        #region UpdateBefore(修改前操作)

        /// <summary>
        /// 修改前操作
        /// </summary>
        protected virtual void UpdateBefore(EntityEntry entry)
        {
            SetModificationAudited(entry.Entity);
            SetVersion(entry.Entity);
            AddEntityUpdatedEvent(entry);
        }

        #endregion

        #region DeleteBefore(删除前操作)

        /// <summary>
        /// 删除前操作
        /// </summary>
        protected virtual void DeleteBefore(EntityEntry entry)
        {
            SetModificationAudited(entry.Entity);
            AddEntityDeletedEvent(entry.Entity);
        }

        #endregion

        #region SetCreationAudited(设置创建审计信息)

        /// <summary>
        /// 设置创建审计信息
        /// </summary>
        protected virtual void SetCreationAudited(object entity)
        {
            CreationAuditedSetter.Set(entity, GetUserId());
        }

        #endregion

        #region SetModificationAudited(设置修改审计信息)

        /// <summary>
        /// 设置修改审计信息
        /// </summary>
        protected virtual void SetModificationAudited(object entity)
        {
            ModificationAuditedSetter.Set(entity, GetUserId());
        }

        #endregion

        #region SetVersion(设置版本号)

        /// <summary>
        /// 设置版本号
        /// </summary>
        protected virtual void SetVersion(object obj)
        {
            if (!(obj is IVersion entity))
                return;
            var version = GetVersion();
            if (version == null)
                return;
            entity.Version = version;
        }

        #endregion

        #region GetVersion(获取版本号)

        /// <summary>
        /// 获取版本号
        /// </summary>
        protected virtual byte[] GetVersion()
        {
            return Encoding.UTF8.GetBytes(Guid.NewGuid().ToString());
        }

        #endregion

        #region AddEntityChangedEvent(添加实体变更事件)

        /// <summary>
        /// 添加实体变更事件
        /// </summary>
        protected virtual void AddEntityChangedEvent(object entity, EntityChangeType changeType, ChangeValueCollection changeValues = null)
        {
            var eventType = typeof(EntityChangedEvent<>).MakeGenericType(entity.GetType());
            var @event = Reflection.CreateInstance<IEvent>(eventType, entity, changeType, changeValues);
            SaveAfterEvents.Add(@event);
        }

        #endregion

        #region AddEntityCreatedEvent(添加实体创建事件)

        /// <summary>
        /// 添加实体创建事件
        /// </summary>
        protected virtual void AddEntityCreatedEvent(object entity)
        {
            var @event = CreateEntityEvent(typeof(EntityCreatedEvent<>), entity);
            SaveAfterEvents.Add(@event);
            AddEntityChangedEvent(entity, EntityChangeType.Created);
        }

        /// <summary>
        /// 创建实体事件
        /// </summary>
        protected IEvent CreateEntityEvent(Type eventType, object entity, object parameter = null)
        {
            var eventGenericType = eventType.MakeGenericType(entity.GetType());
            if (parameter == null)
                return Reflection.CreateInstance<IEvent>(eventGenericType, entity);
            return Reflection.CreateInstance<IEvent>(eventGenericType, entity, parameter);
        }

        #endregion

        #region AddEntityUpdatedEvent(添加实体修改事件)

        /// <summary>
        /// 添加实体修改事件
        /// </summary>
        protected virtual void AddEntityUpdatedEvent(EntityEntry entry)
        {
            var entity = entry.Entity;
            if (entity is IDelete { IsDeleted: true })
            {
                AddEntityDeletedEvent(entity);
                return;
            }
            var changeValues = GetChangeValues(entry);
            var @event = CreateEntityEvent(typeof(EntityUpdatedEvent<>), entity, changeValues);
            SaveAfterEvents.Add(@event);
            AddEntityChangedEvent(entity, EntityChangeType.Updated, changeValues);
        }

        #endregion

        #region GetChangeValues(获取变更值集合)

        /// <summary>
        /// 获取变更值集合
        /// </summary>
        protected virtual ChangeValueCollection GetChangeValues(EntityEntry entry)
        {
            var result = new ChangeValueCollection();
            var properties = entry.Metadata.GetProperties();
            foreach (var property in properties)
            {
                var propertyEntry = entry.Property(property.Name);
                if (property.Name == "ExtraProperties")
                {
                    var changeValues = GetExtraPropertiesChangeValues(property, propertyEntry);
                    changeValues.ForEach(value =>
                    {
                        if (value != null)
                            result.Add(value);
                    });
                    continue;
                }
                var changeValue = GetPropertyChangeValue(property, propertyEntry);
                if (changeValue == null)
                    continue;
                result.Add(changeValue);
            }
            return result;
        }

        /// <summary>
        /// 获取扩展属性变更值集合
        /// </summary>
        protected virtual List<ChangeValue> GetExtraPropertiesChangeValues(IProperty property, PropertyEntry propertyEntry)
        {
            var result = new List<ChangeValue>();
            if (propertyEntry.CurrentValue is not ExtraPropertyDictionary currentExtraValue)
                return result;
            if (propertyEntry.OriginalValue is not ExtraPropertyDictionary originalExtraValue)
                return result;
            foreach (var key in currentExtraValue.Keys)
            {
                currentExtraValue.TryGetValue(key, out var current);
                originalExtraValue.TryGetValue(key, out var original);
                var currentValue = Util.Helpers.Json.ToJson(current);
                var originalValue = Util.Helpers.Json.ToJson(original);
                result.Add(ToChangeValue(key, property.Name, originalValue, currentValue));
            }
            return result;
        }

        /// <summary>
        /// 转换为变更值
        /// </summary>
        protected virtual ChangeValue ToChangeValue(string name, string description, string originalValue, string currentValue)
        {
            if (originalValue == "[]")
                originalValue = string.Empty;
            if (currentValue == "[]")
                currentValue = string.Empty;
            if (originalValue == currentValue)
                return null;
            return new ChangeValue(name, description, originalValue, currentValue);
        }

        /// <summary>
        /// 获取属性变更值
        /// </summary>
        protected virtual ChangeValue GetPropertyChangeValue(IProperty property, PropertyEntry propertyEntry)
        {
            var description = Reflection.GetDisplayNameOrDescription(property.PropertyInfo);
            return ToChangeValue(property.Name, description, propertyEntry.OriginalValue.SafeString(), propertyEntry.CurrentValue.SafeString());
        }

        #endregion

        #region AddEntityDeletedEvent(添加实体删除事件)

        /// <summary>
        /// 添加实体删除事件
        /// </summary>
        protected virtual void AddEntityDeletedEvent(object entity)
        {
            var @event = CreateEntityEvent(typeof(EntityDeletedEvent<>), entity);
            SaveAfterEvents.Add(@event);
            AddEntityChangedEvent(entity, EntityChangeType.Deleted);
        }

        #endregion

        #region PublishSaveBeforeEventsAsync(发布保存前事件)

        /// <summary>
        /// 发布保存前事件
        /// </summary>
        protected virtual async Task PublishSaveBeforeEventsAsync()
        {
            if (SaveBeforeEvents.Count == 0)
                return;
            var events = new List<IEvent>(SaveBeforeEvents);
            SaveBeforeEvents.Clear();
            await EventBus.PublishAsync(events);
        }

        #endregion

        #region SaveChangesAfter(保存后操作)

        /// <summary>
        /// 保存后操作
        /// </summary>
        protected virtual async Task SaveChangesAfter()
        {
            await PublishSaveAfterEventsAsync();
            await ExecuteActionsAsync();
        }

        #endregion

        #region PublishSaveAfterEventsAsync(发布保存后事件)

        /// <summary>
        /// 发布保存后事件
        /// </summary>
        protected virtual async Task PublishSaveAfterEventsAsync()
        {
            var events = new List<IEvent>(SaveAfterEvents);
            SaveAfterEvents.Clear();
            await EventBus.PublishAsync(events);
        }

        #endregion

        #region ExecuteActionsAsync(执行工作单元操作集合)

        /// <summary>
        /// 执行工作单元操作集合
        /// </summary>
        protected virtual async Task ExecuteActionsAsync()
        {
            await ActionManager.ExecuteAsync();
        }

        #endregion
    }

    /// <summary>
    /// 工作单元扩展
    /// </summary>
    public static class UnitOfWorkExtensions
    {
        /// <summary>
        /// 获取已应用的迁移列表
        /// </summary>
        /// <param name="source">工作单元</param>
        public static async Task<List<string>> GetAppliedMigrationsAsync(this IUnitOfWork source)
        {
            source.CheckNull(nameof(source));
            if (source is not DbContext unitOfWork)
                return new List<string>();
            var result = await unitOfWork.Database.GetAppliedMigrationsAsync();
            return result.ToList();
        }

        /// <summary>
        /// 应用迁移
        /// </summary>
        /// <param name="source">工作单元</param>
        /// <param name="cancellationToken">取消令牌</param>
        public static async Task MigrateAsync(this IUnitOfWork source, CancellationToken cancellationToken = default)
        {
            source.CheckNull(nameof(source));
            if (source is not DbContext unitOfWork)
                return;
            await unitOfWork.Database.MigrateAsync(cancellationToken);
        }

        /// <summary>
        /// 创建数据库架构
        /// </summary>
        /// <param name="source">工作单元</param>
        public static bool EnsureCreated(this IUnitOfWork source)
        {
            source.CheckNull(nameof(source));
            if (source is not DbContext unitOfWork)
                return false;
            return unitOfWork.Database.EnsureCreated();
        }

        /// <summary>
        /// 创建数据库架构
        /// </summary>
        /// <param name="source">工作单元</param>
        public static async Task<bool> EnsureCreatedAsync(this IUnitOfWork source)
        {
            source.CheckNull(nameof(source));
            if (source is not DbContext unitOfWork)
                return false;
            return await unitOfWork.Database.EnsureCreatedAsync();
        }

        /// <summary>
        /// 删除数据库架构
        /// </summary>
        /// <param name="source">工作单元</param>
        public static bool EnsureDeleted(this IUnitOfWork source)
        {
            source.CheckNull(nameof(source));
            if (source is not DbContext unitOfWork)
                return false;
            return unitOfWork.Database.EnsureDeleted();
        }

        /// <summary>
        /// 删除数据库架构
        /// </summary>
        /// <param name="source">工作单元</param>
        public static async Task<bool> EnsureDeletedAsync(this IUnitOfWork source)
        {
            source.CheckNull(nameof(source));
            if (source is not DbContext unitOfWork)
                return false;
            return await unitOfWork.Database.EnsureDeletedAsync();
        }

        /// <summary>
        /// 清空缓存
        /// </summary>
        /// <param name="source">工作单元</param>
        public static void ClearCache(this IUnitOfWork source)
        {
            source.CheckNull(nameof(source));
            if (source is not DbContext unitOfWork)
                return;
            unitOfWork.ChangeTracker.Clear();
        }

        /// <summary>
        /// 获取更改跟踪调试视图
        /// </summary>
        /// <param name="source">工作单元</param>
        public static string GetChangeTrackerDebugView(this IUnitOfWork source)
        {
            source.CheckNull(nameof(source));
            if (source is not DbContext unitOfWork)
                return null;
            unitOfWork.ChangeTracker.DetectChanges();
            return unitOfWork.ChangeTracker.DebugView.LongView;
        }

        /// <summary>
        /// 是否更改
        /// </summary>
        /// <param name="source">工作单元</param>
        public static bool IsChange(this IUnitOfWork source)
        {
            source.CheckNull(nameof(source));
            if (source is not DbContext unitOfWork)
                return false;
            return unitOfWork.ChangeTracker.Entries().Any(t => t.State == EntityState.Modified);
        }

        /// <summary>
        /// 是否可连接
        /// </summary>
        /// <param name="source">工作单元</param>
        /// <param name="cancellationToken">取消令牌</param>
        public static async Task<bool> CanConnectAsync(this IUnitOfWork source, CancellationToken cancellationToken = default)
        {
            source.CheckNull(nameof(source));
            if (source is not DbContext unitOfWork)
                return false;
            return await unitOfWork.Database.CanConnectAsync(cancellationToken);
        }
    }

