        /// <summary>
        /// Sql生成器
        /// </summary>
        private ISqlBuilder _sqlBuilder;
        /// <summary>
        /// 数据库连接
        /// </summary>
        private IDbConnection _connection;
        /// <summary>
        /// 事务
        /// </summary>
        private IDbTransaction _transaction;
        /// <summary>
        /// Sql结果字符串
        /// </summary>
        private string _sql;
        /// <summary>
        /// 动态参数列表
        /// </summary>
        private DynamicParameters _parameters;
        /// <summary>
        /// 参数字面值解析器
        /// </summary>
        private IParamLiteralsResolver _paramLiteralsResolver;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化Sql查询对象
        /// </summary>
        /// <param name="serviceProvider">服务提供器</param>
        /// <param name="options">Sql配置</param>
        /// <param name="database">数据库信息,用于接入其它数据源,比如EF DbContext</param>
        protected SqlQueryBase(IServiceProvider serviceProvider, SqlOptions options, IDatabase database)
        {
            ServiceProvider = serviceProvider ?? throw new ArgumentNullException(nameof(serviceProvider));
            Options = options ?? throw new ArgumentNullException(nameof(options));
            Logger = CreateLogger();
            _connection = options.Connection;
            _database = database;
            ContextId = Id.Create();
        }

        /// <summary>
        /// 创建日志
        /// </summary>
        private ILogger CreateLogger()
        {
            var loggerFactory = ServiceProvider.GetService<ILoggerFactory>();
            if (loggerFactory == null)
                return NullLogger.Instance;
            return loggerFactory.CreateLogger(Options.LogCategory);
        }

        #endregion

        #region 属性

        /// <summary>
        /// 上下文标识
        /// </summary>
        public string ContextId { get; private set; }
        /// <summary>
