        /// <typeparam name="T">参数值类型</typeparam>
        /// <param name="name">参数名</param>
        public virtual T GetParam<T>(string name)
        {
            if (_parameters == null && PreviousSql != null)
                return PreviousSql.GetParam<T>(name);
            return Params.Get<T>(name);
        }

