        #region GetConnection(获取数据库连接)

        /// <summary>
        /// 获取数据库连接
        /// </summary>
        public IDbConnection GetConnection()
        {
            if (_connection != null)
                return _connection;
            _connection = Database.GetConnection();
            if (_connection == null)
                throw new InvalidOperationException(UtilDataDapperResource.ConnectionIsEmpty);
            return _connection;
        }

        #endregion

        #region SetConnection(设置数据库连接)

        /// <summary>
        /// 设置数据库连接
        /// </summary>
        /// <param name="connection">数据库连接</param>
        public void SetConnection(IDbConnection connection)
        {
            if (connection == null)
                return;
            _connection = connection;
        }

        #endregion

        #region GetTransaction(获取数据库事务)

        /// <summary>
        /// 获取数据库事务
        /// </summary>
        public IDbTransaction GetTransaction()
        {
            return _transaction;
        }

        #endregion

        #region SetTransaction(设置数据库事务)

        /// <summary>
        /// 设置数据库事务
        /// </summary>
        /// <param name="transaction">数据库事务</param>
        public void SetTransaction(IDbTransaction transaction)
        {
            if (transaction == null)
                return;
            _transaction = transaction;
            _connection = transaction.Connection;
        }

        #endregion

        #region BeginTransaction(开始事务)

        /// <summary>
        /// 开始事务
        /// </summary>
        public IDbTransaction BeginTransaction()
        {
            return BeginTransactionImpl(null);
        }

        /// <summary>
        /// 开始事务
        /// </summary>
        /// <param name="isolationLevel">隔离级别</param>
        public IDbTransaction BeginTransaction(IsolationLevel isolationLevel)
        {
            return BeginTransactionImpl(isolationLevel);
        }

        /// <summary>
        /// 开始事务
        /// </summary>
        private IDbTransaction BeginTransactionImpl(IsolationLevel? isolationLevel)
        {
            try
            {
                if (_transaction != null)
                    return _transaction;
                var connection = GetConnection();
                if (connection.State == ConnectionState.Closed)
                    connection.Open();
                _transaction = isolationLevel == null ? connection.BeginTransaction() : connection.BeginTransaction(isolationLevel.SafeValue());
                return _transaction;
            }
            catch
            {
                if (_connection?.State == ConnectionState.Open)
                    _connection?.Close();
                _transaction?.Dispose();
                throw;
            }
        }

        #endregion

        #region CommitTransaction(提交事务)

        /// <summary>
        /// 提交事务
        /// </summary>
        public void CommitTransaction()
        {
            try
            {
                _transaction?.Commit();
            }
            catch
            {
                _transaction?.Rollback();
                throw;
            }
            finally
            {
                if (_connection?.State == ConnectionState.Open)
                    _connection?.Close();
                _transaction?.Dispose();
                _transaction = null;
            }
        }

        #endregion

        #region RollbackTransaction(回滚事务)

        /// <summary>
        /// 回滚事务
        /// </summary>
        public void RollbackTransaction()
        {
            try
            {
                if (_connection.State != ConnectionState.Closed)
                    _transaction?.Rollback();
            }
            finally
            {
                if (_connection?.State == ConnectionState.Open)
                    _connection?.Close();
                _transaction?.Dispose();
                _transaction = null;
            }
        }

        #endregion

        #region ExecuteExists(判断是否存在)

        /// <summary>
        /// 判断是否存在
