        #region 钩子方法

        /// <summary>
        /// 执行前操作,返回false停止执行
        /// </summary>
        protected virtual bool ExecuteBefore()
        {
            return true;
        }

        /// <summary>
        /// 执行后操作
        /// </summary>
        /// <param name="result">结果</param>
        protected virtual void ExecuteAfter(object result)
        {
            SetPreviousSql();
            Clear();
            WriteLog();
        }

        #endregion

        #region GetSql(获取Sql语句)

        /// <summary>
        /// 获取Sql语句
        /// </summary>
        public string GetSql()
        {
            return _sql ??= SqlBuilder.GetSql();
        }

        #endregion

        #region SetSql(设置Sql语句)

        /// <summary>
        /// 设置Sql语句
        /// </summary>
        /// <param name="sql">sql语句或存储过程名</param>
        protected void SetSql(string sql)
        {
            _sql = sql;
        }

        #endregion

        #region GetProcedure(获取存储过程名称)

        /// <summary>
        /// 获取存储过程名称
        /// </summary>
        /// <param name="procedure">存储过程</param>
        protected virtual string GetProcedure(string procedure)
        {
            return new TableItem(Dialect, procedure).ToResult();
        }

        #endregion

        #region GetProcedureCommandType(获取存储过程命令类型)

        /// <summary>
        /// 获取存储过程命令类型
        /// </summary>
        protected virtual CommandType GetProcedureCommandType()
        {
            return CommandType.StoredProcedure;
        }

        #endregion

        #region SetPreviousSql(设置前一次执行的Sql及参数)

        /// <summary>
        /// 设置前一次执行的Sql及参数
        /// </summary>
        protected virtual void SetPreviousSql()
        {
            var sqlParams = GetSqlParams();
            PreviousSql = new SqlBuilderResult(_sql, sqlParams, ParamLiteralsResolver, ParameterManager);
        }

        #endregion

        #region GetSqlParams(获取Sql参数列表)

        /// <summary>
        /// 获取Sql参数列表
        /// </summary>
        protected List<SqlParam> GetSqlParams()
        {
            var result = new List<SqlParam>();
            if (_parameters == null)
                return result;
            foreach (var parameterName in _parameters.ParameterNames)
            {
                if (ParameterManager.Contains(parameterName))
                {
                    var param = ParameterManager.GetParam(parameterName);
                    if (param.Direction != ParameterDirection.Input)
                        param = new SqlParam(param.Name, _parameters.Get<object>(parameterName), param.DbType, param.Direction, param.Size, param.Precision, param.Scale);
                    result.Add(param);
                    continue;
                }
                var sqlParam = new SqlParam(ParameterManager.NormalizeName(parameterName), _parameters.Get<object>(parameterName));
                result.Add(sqlParam);
            }
            return result;
        }

        #endregion

        #region Clear(清理)

        /// <summary>
        /// 清理
        /// </summary>
        protected void Clear()
        {
            _sql = null;
            SqlBuilder.Clear();
            ClearParams();
        }

        #endregion

        #region WriteLog(写日志)

        /// <summary>
        /// 写日志
        /// </summary>
        protected virtual void WriteLog()
        {
            if (Logger.IsEnabled(LogLevel.Trace) == false)
                return;
            var message = new StringBuilder();
            message.AppendLine("标题: Sql日志");
            message.AppendLine("原始Sql:");
            message.AppendLine(PreviousSql.GetSql());
            message.AppendLine("调试Sql:");
            message.AppendLine(PreviousSql.GetDebugSql());
            message.AppendLine("Sql参数:");
            foreach (var param in PreviousSql.GetParams())
            {
                message.Append("参数名: ");
                message.Append(param.Name);
                if (param.Value != null)
                {
                    message.Append(",参数值: ");
                    message.Append(param.Value);
                }
                if (param.DbType != null)
                {
                    message.Append(",参数类型: ");
                    message.Append(param.DbType);
                }
                if (param.Direction != null)
                {
                    message.Append(",参数方向: ");
                    message.Append(param.Direction);
                }
                if (param.Size != null)
                {
                    message.Append(",Size: ");
                    message.Append(param.Size);
                }
                if (param.Precision != null)
                {
                    message.Append(",Precision: ");
                    message.Append(param.Precision);
                }
                if (param.Scale != null)
                {
                    message.Append(",Scale: ");
                    message.Append(param.Scale);
                }
                message.AppendLine();
            }
            Logger.LogTrace(message.ToString());
        }

        #endregion

        #region Dispose(释放资源)

        /// <summary>
        /// 释放资源
        /// </summary>
        public void Dispose()
        {
            if (_connection != null)
                _connection.Dispose();
            _transaction = null;
        }

        #endregion
    }
    #endregion

    #region TypeHandlers
    /// <summary>
    /// 扩展属性类型转换器
    /// </summary>
    public class ExtraPropertiesTypeHandler : SqlMapper.TypeHandler<ExtraPropertyDictionary>
    {
        /// <summary>
        /// 设置值
        /// </summary>
        /// <param name="parameter">参数</param>
        /// <param name="value">扩展属性值</param>
        public override void SetValue(IDbDataParameter parameter, ExtraPropertyDictionary value)
        {
            if (parameter == null)
                return;
            if (value == null)
                return;
            parameter.Value = PropertiesToJson(value);
        }

        /// <summary>
        /// 扩展属性转换为json
        /// </summary>
        private static string PropertiesToJson(ExtraPropertyDictionary extraProperties)
        {
            var options = new JsonSerializerOptions
            {
                DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
                Encoder = JavaScriptEncoder.Create(UnicodeRanges.All),
                Converters = {
                new UtcDateTimeJsonConverter(),
                new UtcNullableDateTimeJsonConverter()
            }
            };
            return Util.Helpers.Json.ToJson(extraProperties, options);
        }

        /// <summary>
        /// 转换值
        /// </summary>
        /// <param name="value">json字符串</param>
        public override ExtraPropertyDictionary Parse(object value)
        {
            return JsonToProperties(value.SafeString());
        }

        /// <summary>
        /// json转换为扩展属性
        /// </summary>
        private static ExtraPropertyDictionary JsonToProperties(string json)
        {
            if (json.IsEmpty() || json == "{}")
                return new ExtraPropertyDictionary();
            var options = new JsonSerializerOptions { PropertyNameCaseInsensitive = true };
            return Util.Helpers.Json.ToObject<ExtraPropertyDictionary>(json, options) ?? new ExtraPropertyDictionary();
        }
    }
    #endregion

    #endregion

    #region Dapper.SqlServer
    /// <summary>
    /// Sql Server数据库元数据服务
    /// </summary>
    public class SqlServerMetadataService : IMetadataService
    {
        /// <summary>
        /// Sql查询对象
        /// </summary>
        private readonly ISqlQuery _sqlQuery;

        /// <summary>
        /// 初始化Sql Server数据库元数据服务
        /// </summary>
        /// <param name="sqlQuery">Sql查询对象</param>
        public SqlServerMetadataService(ISqlQuery sqlQuery)
        {
            _sqlQuery = sqlQuery ?? throw new ArgumentNullException(nameof(sqlQuery));
        }

        /// <summary>
        /// 获取数据库信息
        /// </summary>
        public async Task<DatabaseInfo> GetDatabaseInfoAsync()
        {
            var result = await GetDatabase();
            var tables = await GetTables();
            result.Tables.AddRange(tables);
            return result;
        }

        /// <summary>
        /// 获取数据库信息
        /// </summary>
        private async Task<DatabaseInfo> GetDatabase()
        {
            return await _sqlQuery
                .Select("Dbid Id,Name")
                .From("sys.SysDataBases")
                .Where("DbId", t => t.Select("Dbid").From("sys.SysProcesses").AppendWhere("Spid = @@spid"))
                .ToEntityAsync<DatabaseInfo>();
        }

        /// <summary>
        /// 获取表信息
        /// </summary>
        private async Task<List<TableInfo>> GetTables()
        {
            SetGetTablesSql();
            var dic = new Dictionary<string, TableInfo>();
            var tables = (await _sqlQuery.ToListAsync<TableInfo, ColumnInfo, TableInfo>((table, column) =>
            {
                if (table == null || column == null)
                    return null;
                dic.TryAdd(table.Id, table);
                TableInfo result = dic[table.Id];
                result.Columns.Add(column);
                return result;
            })).Distinct().ToList();
            return tables;
        }

        /// <summary>
        /// 设置获取表信息Sql
        /// </summary>
        private void SetGetTablesSql()
        {
            _sqlQuery
                .Select("o.object_id Id,o.name,s.name Schema,ep.value Comment")
                .Select("c.Id,c.name,c.Comment")
                .AppendSelect(",(Case When Exists(")
                .AppendSelect(GetIsPrimaryKeySql())
                .AppendSelect(") Then Cast(1 As Bit) Else Cast(0 As Bit) End) As IsPrimaryKey")
                .Select("c.is_identity IsAutoIncrement,c.is_nullable IsNullable")
                .Select("c.DataType,c.max_length Length,c.precision,c.scale")
                .From("sys.Objects o")
                .LeftJoin("sys.Schemas s").On("o.schema_id", "s.schema_id")
                .LeftJoin("sys.Extended_Properties ep").On("o.object_id", "ep.major_id").On("ep.minor_id", 0)
                .Join(GetColumnsSql(), "c").On("c.object_id", "o.object_id")
                .In("o.type", new[] { 'U' });
        }

        /// <summary>
        /// 获取是否主键子查询
        /// </summary>
        private ISqlBuilder GetIsPrimaryKeySql()
        {
            return _sqlQuery.NewSqlBuilder()
                .Select()
                .From("Information_Schema.Key_Column_Usage k")
                .Join("Information_Schema.Table_Constraints tc")
                .On("k.table_name", "tc.table_name")
                .On("k.Constraint_Name", "tc.Constraint_Name")
                .AppendOn("tc.Constraint_Type='PRIMARY KEY'")
                .AppendWhere("o.name=k.table_name")
                .AppendWhere("c.name=k.column_name");
        }

        /// <summary>
        /// 获取列信息子查询
        /// </summary>
        private ISqlBuilder GetColumnsSql()
        {
            return _sqlQuery.NewSqlBuilder()
                .Select("c.object_id,c.column_id Id,c.name,ep.value Comment")
                .Select("c.is_identity,c.is_nullable,t.name DataType,c.max_length")
                .Select("c.precision,c.scale")
                .From("sys.Columns c")
                .LeftJoin("sys.Extended_Properties ep").On("c.object_id", "ep.major_id").On("c.column_id", "ep.minor_id")
                .LeftJoin("sys.Types t").On("c.system_type_id", "t.system_type_id")
                .AppendWhere("t.name!='sysname'");
        }
    }

    /// <summary>
    /// Sql Server数据类型转换器
    /// </summary>
    public class SqlServerTypeConverter : ITypeConverter
    {
        /// <inheritdoc />
        public DbType? ToType(string dataType, int? length = null)
        {
            if (dataType.IsEmpty())
                return null;
            switch (dataType.ToLower())
            {
                case "uniqueidentifier":
                    return DbType.Guid;
                case "char":
                    return DbType.AnsiStringFixedLength;
                case "nchar":
                    return DbType.StringFixedLength;
                case "varchar":
                    return DbType.AnsiString;
                case "nvarchar":
                case "text":
                case "ntext":
                    return DbType.String;
                case "bit":
                    return DbType.Boolean;
                case "tinyint":
                    return DbType.Byte;
                case "smallint":
                    return DbType.Int16;
                case "int":
                    return DbType.Int32;
                case "bigint":
                    return DbType.Int64;
                case "real":
                    return DbType.Single;
                case "float":
                    return DbType.Double;
                case "decimal":
                case "numeric":
                case "money":
                case "smallmoney":
                    return DbType.Decimal;
                case "date":
                    return DbType.Date;
                case "time":
                    return DbType.Time;
                case "datetime":
                case "smalldatetime":
                    return DbType.DateTime;
                case "datetime2":
                    return DbType.DateTime2;
                case "datetimeoffset":
                    return DbType.DateTimeOffset;
                case "binary":
                case "varbinary":
                case "varbinary(max)":
                case "image":
                case "rowversion":
                case "timestamp":
                    return DbType.Binary;
                case "xml":
                    return DbType.Xml;
                case "sql_variant":
                    return DbType.Object;
            }
            throw new NotImplementedException(dataType);
        }
    }

