    #region Locks
    /// <summary>
    /// 业务锁
    /// </summary>
    public class DefaultLock : ILock
    {
        /// <summary>
        /// 缓存
        /// </summary>
        private readonly ICache _cache;
        /// <summary>
        /// 锁定标识
        /// </summary>
        private string _key;
        /// <summary>
        /// 锁定时间间隔
        /// </summary>
        private TimeSpan? _expiration;

        /// <summary>
        /// 初始化业务锁
        /// </summary>
        /// <param name="cache">缓存</param>
        public DefaultLock(ICache cache)
        {
            _cache = cache;
        }

        /// <inheritdoc />
        public async Task<bool> LockAsync(string key, TimeSpan? expiration = null)
        {
            _key = key;
            _expiration = expiration;
            if (await _cache.ExistsAsync(key))
                return false;
            return await _cache.TrySetAsync(key, 1, new CacheOptions { Expiration = expiration });
        }

        /// <inheritdoc />
        public async Task UnLockAsync()
        {
            if (_expiration != null)
                return;
            if (await _cache.ExistsAsync(_key) == false)
                return;
            await _cache.RemoveAsync(_key);
        }
    }

    /// <summary>
    /// 业务锁
    /// </summary>
    public interface ILock
    {
        /// <summary>
        /// 锁定，true表示本次操作成功锁定资源，false表示资源已被之前的操作锁定
        /// </summary>
        /// <param name="key">锁定标识</param>
        /// <param name="expiration">锁定时间间隔</param>
        Task<bool> LockAsync(string key, TimeSpan? expiration = null);
        /// <summary>
        /// 解除锁定
        /// </summary>
        Task UnLockAsync();
    }

    /// <summary>
    /// 业务锁类型
    /// </summary>
    public enum LockType
    {
        /// <summary>
        /// 用户锁，当用户发出多个执行该操作的请求，只有第一个请求被执行，其它请求被抛弃，其它用户不受影响
        /// </summary>
        User = 0,
        /// <summary>
        /// 全局锁，该操作同时只有一个用户的请求被执行
        /// </summary>
        Global = 1
    }

    /// <summary>
    /// 空业务锁
    /// </summary>
    public class NullLock : ILock
    {
        /// <summary>
        /// 空业务锁
        /// </summary>
        public static readonly ILock Instance = new NullLock();

        /// <inheritdoc />
        public Task<bool> LockAsync(string key, TimeSpan? expiration = null)
        {
            return Task.FromResult(true);
        }

        /// <inheritdoc />
        public Task UnLockAsync()
        {
            return Task.CompletedTask;
        }
    }

