    /// <summary>
    /// 树形查询操作
    /// </summary>
    /// <typeparam name="TDto">参数类型</typeparam>
    /// <typeparam name="TQuery">查询参数类型</typeparam>
    public abstract class TreeQueryActionBase<TDto, TQuery>
        where TDto : class, ITreeNode, new()
        where TQuery : class, ITreeQueryParameter
    {

        #region 字段

        /// <summary>
        /// 查询服务
        /// </summary>
        private readonly ITreeQueryService<TDto, TQuery> _service;
        /// <summary>
        /// 加载模式
        /// </summary>
        private readonly LoadMode _loadMode;
        /// <summary>
        /// 加载操作
        /// </summary>
        private readonly LoadOperation _loadOperation;
        /// <summary>
        /// 最大分页大小
        /// </summary>
        private readonly int _maxPageSize;
        /// <summary>
        /// 是否首次加载
        /// </summary>
        private readonly bool _isFirstLoad;
        /// <summary>
        /// 是否展开所有节点
        /// </summary>
        private readonly bool _isExpandAll;
        /// <summary>
        /// 根节点异步加载模式是否展开子节点列表
        /// </summary>
        private readonly bool _isExpandForRootAsync;
        /// <summary>
        /// 需要加载的标识列表
        /// </summary>
        private readonly string _loadKeys;
        /// <summary>
        /// 查询前操作
        /// </summary>
        private readonly Action<TQuery> _queryBefore;
        /// <summary>
        /// 数据处理操作
        /// </summary>
        private readonly Action<PageList<TDto>, TQuery> _queryAfter;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化树形查询操作
        /// </summary>
        /// <param name="service">查询服务</param>
        /// <param name="loadMode">加载模式</param>
        /// <param name="loadOperation">加载操作</param>
        /// <param name="maxPageSize">最大分页大小</param>
        /// <param name="isFirstLoad">是否首次加载</param>
        /// <param name="isExpandAll">是否展开所有节点</param>
        /// <param name="isExpandForRootAsync">根节点异步加载模式是否展开子节点列表</param>
        /// <param name="loadKeys">需要加载的标识列表</param>
        /// <param name="queryBefore">查询前操作</param>
        /// <param name="queryAfter">查询后操作</param>
        protected TreeQueryActionBase(ITreeQueryService<TDto, TQuery> service, LoadMode loadMode, LoadOperation loadOperation,
            int maxPageSize, bool isFirstLoad, bool isExpandAll, bool isExpandForRootAsync, string loadKeys,
            Action<TQuery> queryBefore, Action<PageList<TDto>, TQuery> queryAfter)
        {
            _service = service ?? throw new ArgumentNullException(nameof(service));
            _loadMode = loadMode;
            _loadOperation = loadOperation;
            _maxPageSize = maxPageSize;
            _isFirstLoad = isFirstLoad;
            _isExpandAll = isExpandAll;
            _isExpandForRootAsync = isExpandForRootAsync;
            _loadKeys = loadKeys;
            _queryBefore = queryBefore;
            _queryAfter = queryAfter;
        }

        #endregion

        #region QueryAsync

        /// <summary>
        /// 查询
        /// </summary>
        /// <param name="query">查询参数</param>
        public async Task<dynamic> QueryAsync(TQuery query)
        {
            query.CheckNull(nameof(query));
            _queryBefore?.Invoke(query);
            InitQueryParam(query);
            return await GetQueryResult(query);
        }

        /// <summary>
        /// 初始化查询参数
        /// </summary>
        /// <param name="query">查询参数</param>
        protected virtual void InitQueryParam(TQuery query)
        {
            if (query.Order.IsEmpty())
                query.Order = "SortId";
            query.Path = null;
            if (_loadOperation == LoadOperation.LoadChildren)
                return;
            query.ParentId = null;
        }

        /// <summary>
        /// 获取查询结果
        /// </summary>
        protected virtual async Task<dynamic> GetQueryResult(TQuery query)
        {
            if (_loadOperation == LoadOperation.LoadChildren)
                return await LoadChildren(query);
            return await LoadQuery(query);
        }

        #endregion

        #region SyncQuery

        /// <summary>
        /// 同步查询
        /// </summary>
        protected virtual async Task<PageList<TDto>> SyncQuery(TQuery query)
        {
            query.PageSize = _maxPageSize;
            return await _service.PageQueryAsync(query);
        }

        #endregion

        #region AsyncQuery

        /// <summary>
        /// 异步查询
        /// </summary>
        protected virtual async Task<PageList<TDto>> AsyncQuery(TQuery query)
        {
            return await _service.PageQueryAsync(query);
        }

        #endregion

        #region ToResult

        /// <summary>
        /// 转换为树形结果
        /// </summary>
        /// <param name="data">数据列表</param>
        /// <param name="async">是否异步加载</param>
        /// <param name="allExpand">所有节点是否全部展开</param>
        protected abstract dynamic ToResult(PageList<TDto> data, bool async = false, bool allExpand = false);

        #endregion

        #region LoadChildren

        /// <summary>
        /// 加载子节点列表
        /// </summary>
        protected virtual async Task<dynamic> LoadChildren(TQuery query)
        {
            if (query.ParentId.IsEmpty())
                throw new InvalidOperationException(ApplicationResource.ParentIdIsEmpty);
            query.Page = 1;
            if (_loadMode == LoadMode.RootAsync)
                return await SyncLoadChildren(query);
            return await AsyncLoadChildren(query);
        }

        /// <summary>
        /// 同步加载子节点列表 - 用于根节点异步加载模式
        /// </summary>
        protected virtual async Task<dynamic> SyncLoadChildren(TQuery query)
        {
            var parentId = query.ParentId.SafeString();
            var queryParam = await InitSyncLoadChildrenQuery(query);
            var data = await SyncQuery(queryParam);
            data.Total -= 1;
            data.Data.RemoveAll(t => t.Id == parentId);
            _queryAfter?.Invoke(data, query);
            return ToResult(data, false, _isExpandForRootAsync);
        }

        /// <summary>
        /// 初始化同步加载子节点查询参数
        /// </summary>
        /// <param name="query">查询参数</param>
        protected virtual async Task<TQuery> InitSyncLoadChildrenQuery(TQuery query)
        {
            var parent = await _service.GetByIdAsync(query.ParentId);
            query.Path = parent.Path;
            query.Level = null;
            query.ParentId = null;
            return query;
        }

        /// <summary>
        /// 异步加载子节点列表
        /// </summary>
        protected virtual async Task<dynamic> AsyncLoadChildren(TQuery query)
        {
            var queryParam = await InitAsyncLoadChildrenQuery(query);
            var data = await SyncQuery(queryParam);
            _queryAfter?.Invoke(data, query);
            return ToResult(data, true, _isExpandAll);
        }

        /// <summary>
        /// 初始化异步加载子节点查询参数
        /// </summary>
        /// <param name="query">查询参数</param>
        protected virtual Task<TQuery> InitAsyncLoadChildrenQuery(TQuery query)
        {
            query.Level = null;
            query.Path = null;
            return Task.FromResult(query);
        }

        #endregion

        #region LoadQuery

        /// <summary>
        /// 加载查询结果
        /// </summary>
        protected virtual async Task<dynamic> LoadQuery(TQuery query)
        {
            if (_loadMode == LoadMode.Sync)
                return await SyncLoadQuery(query);
            return await AsyncLoadQuery(query);
        }

        /// <summary>
        /// 同步查询
        /// </summary>
        protected virtual async Task<dynamic> SyncLoadQuery(TQuery query)
        {
            var data = await SyncQuery(query);
            await AddMissingParents(data);
            _queryAfter?.Invoke(data, query);
            return ToResult(data, false, _isExpandAll);
        }

        /// <summary>
        /// 添加缺失的父节点
        /// </summary>
        protected virtual async Task AddMissingParents(PageList<TDto> data)
        {
            if (data.Data.Any(t => t.Level > 1) == false)
                return;
            var ids = data.Data.GetMissingParentIds();
            var list = await _service.GetByIdsAsync(ids.Join());
            data.Data.AddRange(list.DistinctBy(t => t.Id));
        }

        /// <summary>
        /// 异步查询
        /// </summary>
        protected virtual async Task<dynamic> AsyncLoadQuery(TQuery query)
        {
            if (_isFirstLoad)
                return await AsyncFirstLoadQuery(query);
            query.PageSize = _maxPageSize;
            var data = await AsyncQuery(query);
            await AddMissingParents(data);
            _queryAfter?.Invoke(data, query);
            return ToResult(data, true, _isExpandAll);
        }

        /// <summary>
        /// 异步首次加载
        /// </summary>
        protected virtual async Task<dynamic> AsyncFirstLoadQuery(TQuery query)
        {
            query.Level = 1;
            var data = await AsyncQuery(query);
            if (_loadKeys.IsEmpty() == false)
            {
                var parentIds = await GetLoadParentIds(_loadKeys);
                var nodes = await GetLoadNodes(parentIds.Join());
                data.Data.AddRange(nodes);
                ExpandParentNodes(data, parentIds);
            }
            _queryAfter?.Invoke(data, query);
            return ToResult(data, true, _isExpandAll);
        }

        /// <summary>
        /// 获取需要加载的父标识列表
        /// </summary>
        protected virtual async Task<List<string>> GetLoadParentIds(string keys)
        {
            var result = new List<string>();
            var selectedNodes = await _service.GetByIdsAsync(keys);
            selectedNodes.ForEach(t => result.AddRange(t.GetParentIdsFromPath(false)));
            return result;
        }

        /// <summary>
        /// 根据父标识列表加载节点
        /// </summary>
        protected virtual async Task<List<TDto>> GetLoadNodes(string parentIds)
        {
            return await _service.GetByParentIds(parentIds);
        }

        /// <summary>
        /// 展开父节点
        /// </summary>
        protected virtual void ExpandParentNodes(PageList<TDto> data, List<string> parentIds)
        {
            var nodes = data.Data.FindAll(node => parentIds.Any(id => node.Id == id));
            nodes.ForEach(t => t.Expanded = true);
        }

        #endregion
    }

    /// <summary>
    /// 树形结果
    /// </summary>
    /// <typeparam name="TSourceNode">源节点类型</typeparam>
    /// <typeparam name="TDestinationNode">目标节点类型</typeparam>
    /// <typeparam name="TResult">树形结果</typeparam>
    public abstract class TreeResultBase<TSourceNode, TDestinationNode, TResult> : TreeTableResultBase<TSourceNode, TDestinationNode, TResult>
        where TSourceNode : ITreeNode<TSourceNode>
        where TDestinationNode : class
        where TResult : class
    {
        /// <summary>
        /// 初始化树形结果
        /// </summary>
        /// <param name="data">树形参数列表</param>
        /// <param name="async">是否异步加载</param>
        /// <param name="allExpand">所有节点是否全部展开</param>
        protected TreeResultBase(IEnumerable<TSourceNode> data, bool async = false, bool allExpand = false) : base(data, async, allExpand)
        {
        }

        /// <summary>
        /// 添加节点
        /// </summary>
        /// <param name="root">根节点</param>
        protected override void AddNode(TSourceNode root)
        {
            if (root == null)
                return;
            InitNode(root);
            AddChildren(root);
            var destinationNode = ToDestinationNode(root);
            AddDestinationNode(destinationNode);
        }

        /// <summary>
        /// 添加子节点
        /// </summary>
        protected virtual void AddChildren(TSourceNode node)
        {
            if (node == null)
                return;
            var children = GetChildren(node);
            children.ForEach(InitNode);
            node.Children = children;
            foreach (var child in node.Children)
                AddChildren(child);
        }
    }

    /// <summary>
    /// 树形表格查询操作
    /// </summary>
    /// <typeparam name="TDto">参数类型</typeparam>
    /// <typeparam name="TQuery">查询参数类型</typeparam>
    public class TreeTableQueryAction<TDto, TQuery> : TreeQueryActionBase<TDto, TQuery>
        where TDto : class, ITreeNode, new()
        where TQuery : class, ITreeQueryParameter
    {
        /// <summary>
        /// 初始化树形表格查询操作
        /// </summary>
        /// <param name="service">查询服务</param>
        /// <param name="loadMode">加载模式</param>
        /// <param name="loadOperation">加载操作</param>
        /// <param name="maxPageSize">最大分页大小</param>
        /// <param name="isFirstLoad">是否首次加载</param>
        /// <param name="isExpandAll">是否展开所有节点</param>
        /// <param name="isExpandForRoot">根节点异步加载模式是否展开子节点列表</param>
        /// <param name="queryBefore">查询前操作</param>
        /// <param name="processData">数据处理操作</param>
        public TreeTableQueryAction(ITreeQueryService<TDto, TQuery> service, LoadMode loadMode, LoadOperation loadOperation,
            int maxPageSize, bool isFirstLoad, bool isExpandAll, bool isExpandForRoot,
            Action<TQuery> queryBefore, Action<PageList<TDto>, TQuery> processData)
            : base(service, loadMode, loadOperation, maxPageSize, isFirstLoad, isExpandAll, isExpandForRoot, null, queryBefore, processData)
        {
        }

        /// <summary>
        /// 转换为树形结果
        /// </summary>
        /// <param name="data">数据列表</param>
        /// <param name="async">是否异步加载</param>
        /// <param name="allExpand">所有节点是否全部展开</param>
        protected override dynamic ToResult(PageList<TDto> data, bool async = false, bool allExpand = false)
        {
            return data.Convert(new TreeTableResult<TDto>(data.Data, async, allExpand).GetResult());
        }
    }

    /// <summary>
    /// 树形表格结果
    /// </summary>
    /// <typeparam name="TNode">节点类型</typeparam>
    public class TreeTableResult<TNode> : TreeTableResultBase<TNode, TNode, List<TNode>> where TNode : class, ITreeNode
    {
        /// <summary>
        /// 初始化树形表格结果
        /// </summary>
        /// <param name="data">树形参数列表</param>
        /// <param name="async">是否异步加载</param>
        /// <param name="allExpand">所有节点是否全部展开</param>
        public TreeTableResult(IEnumerable<TNode> data, bool async = false, bool allExpand = false) : base(data, async, allExpand)
        {
        }

        /// <summary>
        /// 转换结果
        /// </summary>
        protected override List<TNode> ToResult(List<TNode> nodes)
        {
            return nodes;
        }
    }

    /// <summary>
    /// 树形表格结果
    /// </summary>
    /// <typeparam name="TSourceNode">源节点类型</typeparam>
    /// <typeparam name="TDestinationNode">目标节点类型</typeparam>
    /// <typeparam name="TResult">树形结果</typeparam>
    public abstract class TreeTableResultBase<TSourceNode, TDestinationNode, TResult>
        where TSourceNode : ITreeNode
        where TDestinationNode : class
        where TResult : class
    {
        /// <summary>
        /// 源节点列表
        /// </summary>
        private readonly List<TSourceNode> _data;
        /// <summary>
        /// 目标节点列表
        /// </summary>
        private readonly List<TDestinationNode> _result;
        /// <summary>
        /// 是否异步加载
        /// </summary>
        private readonly bool _async;
        /// <summary>
        /// 所有节点是否全部展开
        /// </summary>
        private readonly bool _allExpand;

        /// <summary>
        /// 初始化树形表格结果
        /// </summary>
        /// <param name="data">树形参数列表</param>
        /// <param name="async">是否异步加载</param>
        /// <param name="allExpand">所有节点是否全部展开</param>
        protected TreeTableResultBase(IEnumerable<TSourceNode> data, bool async = false, bool allExpand = false)
        {
            data.CheckNull(nameof(data));
            _data = data.ToList();
            _async = async;
            _allExpand = allExpand;
            _result = new List<TDestinationNode>();
        }

        /// <summary>
        /// 获取源数据
        /// </summary>
        protected List<TSourceNode> GetData()
        {
            return _data;
        }

        /// <summary>
        /// 获取树形结果
        /// </summary>
        public TResult GetResult()
        {
            if (_data == null)
                return ToResult(null);
            foreach (var root in GetRootNodes())
                AddNode(root);
            return ToResult(_result);
        }

        /// <summary>
        /// 获取根节点列表
        /// </summary>
        protected virtual List<TSourceNode> GetRootNodes()
        {
            return _data.Where(IsRoot).OrderBy(t => t.SortId).ToList();
        }

        /// <summary>
        /// 是否根节点
        /// </summary>
        protected virtual bool IsRoot(TSourceNode dto)
        {
            if (_data.Any(t => t.ParentId.IsEmpty()))
                return dto.ParentId.IsEmpty();
            return dto.Level == _data.Min(t => t.Level);
        }

        /// <summary>
        /// 添加节点
        /// </summary>
        protected virtual void AddNode(TSourceNode node)
        {
            if (node == null)
                return;
            InitNode(node);
            var destinationNode = ToDestinationNode(node);
            AddDestinationNode(destinationNode);
            var children = GetChildren(node);
            foreach (var child in children)
                AddNode(child);
        }

        /// <summary>
        /// 初始化节点
        /// </summary>
        protected void InitNode(TSourceNode node)
        {
            InitLeaf(node);
            InitExpanded(node);
        }

        /// <summary>
        /// 初始化叶节点状态
        /// </summary>
        protected virtual void InitLeaf(TSourceNode node)
        {
            node.Leaf = false;
            if (_async)
                return;
            if (IsLeaf(node))
                node.Leaf = true;
        }

        /// <summary>
        /// 是否叶节点
        /// </summary>
        protected virtual bool IsLeaf(TSourceNode node)
        {
            if (_data.All(t => t.ParentId != node.Id))
                return true;
            var children = _data.FindAll(t => t.ParentId == node.Id);
            if (children.All(t => t.Hide == true))
                return true;
            return false;
        }

        /// <summary>
        /// 初始化节点展开状态
        /// </summary>
        protected virtual void InitExpanded(TSourceNode node)
        {
            if (_allExpand == false)
                return;
            if (_async == false)
            {
                node.Expanded = true;
                return;
            }
            if (_data.All(t => t.Level == 1))
                return;
            if (node.Leaf == false)
                node.Expanded = true;
        }

        /// <summary>
        /// 添加目标节点
        /// </summary>
        /// <param name="node">目标节点</param>
        protected void AddDestinationNode(TDestinationNode node)
        {
            _result.Add(node);
        }

        /// <summary>
        /// 获取节点直接下级
        /// </summary>
        protected List<TSourceNode> GetChildren(TSourceNode node)
        {
            return _data.Where(t => t.ParentId == node.Id).OrderBy(t => t.SortId).ToList();
        }

        /// <summary>
        /// 将源节点转换为目标节点
        /// </summary>
        /// <param name="node">源节点</param>
        protected virtual TDestinationNode ToDestinationNode(TSourceNode node)
        {
            return node.MapTo<TDestinationNode>();
        }

        /// <summary>
        /// 转换为结果
        /// </summary>
        /// <param name="nodes">目标节点列表</param>
        protected abstract TResult ToResult(List<TDestinationNode> nodes);
    }

    #endregion

    /// <summary>
    /// 业务锁操作扩展
    /// </summary>
    public static class AppBuilderExtensions
    {
        /// <summary>
        /// 配置业务锁
        /// </summary>
        /// <param name="builder">应用生成器</param>
        public static IAppBuilder AddLock(this IAppBuilder builder)
        {
            builder.CheckNull(nameof(builder));
            builder.Host.ConfigureServices((context, services) =>
            {
                services.TryAddTransient<ILock, DefaultLock>();
            });
            return builder;
        }
    }

    /// <summary>
    /// 异常扩展
    /// </summary>
    public static class ExceptionExtensions
    {
        /// <summary>
        /// 获取异常提示
        /// </summary>
        /// <param name="exception">异常</param>
        /// <param name="isProduction">是否生产环境</param>
        public static string GetPrompt(this Exception exception, bool isProduction = false)
        {
            if (exception == null)
                return null;
            exception = exception.GetRawException();
            if (exception == null)
                return null;
            if (exception is Warning warning)
                return warning.GetMessage(isProduction);
            return isProduction ? R.SystemError : exception.Message;
        }

        /// <summary>
        /// 获取Http状态码
        /// </summary>
        /// <param name="exception">异常</param>
        public static int? GetHttpStatusCode(this Exception exception)
        {
            if (exception == null)
                return null;
            exception = exception.GetRawException();
            if (exception == null)
                return null;
            if (exception is Warning warning)
                return warning.HttpStatusCode;
            return null;
        }

        /// <summary>
        /// 获取错误码
        /// </summary>
        /// <param name="exception">异常</param>
        public static string GetErrorCode(this Exception exception)
        {
            if (exception == null)
                return null;
            exception = exception.GetRawException();
            if (exception == null)
                return null;
            if (exception is Warning warning)
                return warning.Code;
            return null;
        }
    }

