        where TDto : class, ITreeNode, new()
        where TCreateRequest : class, IRequest, new()
        where TUpdateRequest : class, IDto, new()
        where TQuery : class, ITreeQueryParameter
    {

        #region 字段

        /// <summary>
        /// 树形仓储
        /// </summary>
