    /// <summary>
    /// 增删改查服务
    /// </summary>
    /// <typeparam name="TEntity">实体类型</typeparam>
    /// <typeparam name="TDto">数据传输对象类型</typeparam>
    /// <typeparam name="TCreateRequest">创建参数类型</typeparam>
    /// <typeparam name="TUpdateRequest">修改参数类型</typeparam>
    /// <typeparam name="TQuery">查询参数类型</typeparam>
    /// <typeparam name="TKey">实体标识类型</typeparam>
    public abstract class CrudServiceBase<TEntity, TDto, TCreateRequest, TUpdateRequest, TQuery, TKey>
        : QueryServiceBase<TEntity, TDto, TQuery, TKey>, ICrudService<TDto, TCreateRequest, TUpdateRequest, TQuery>
        where TEntity : class, IAggregateRoot<TEntity, TKey>, new()
        where TDto : class, IDto, new()
        where TCreateRequest : class, IRequest, new()
        where TUpdateRequest : class, IDto, new()
        where TQuery : IPage
    {

        #region 字段

        /// <summary>
        /// 仓储
        /// </summary>
        private readonly IRepository<TEntity, TKey> _repository;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化增删改查服务
        /// </summary>
        /// <param name="serviceProvider">服务提供器</param>
        /// <param name="unitOfWork">工作单元</param>
        /// <param name="repository">仓储</param>
        protected CrudServiceBase(IServiceProvider serviceProvider, IUnitOfWork unitOfWork, IRepository<TEntity, TKey> repository) : base(serviceProvider, repository)
        {
            UnitOfWork = unitOfWork ?? throw new ArgumentNullException(nameof(unitOfWork));
            _repository = repository ?? throw new ArgumentNullException(nameof(repository));
            EntityDescription = Reflection.GetDisplayNameOrDescription<TEntity>();
        }

        #endregion

        #region 属性

        /// <summary>
        /// 工作单元
        /// </summary>
        protected IUnitOfWork UnitOfWork { get; }

        /// <summary>
        /// 实体描述
        /// </summary>
        protected string EntityDescription { get; }

        #endregion

        #region CreateAsync(创建)

        /// <inheritdoc />
        public virtual async Task<string> CreateAsync(TCreateRequest request)
        {
            request.CheckNull(nameof(request));
            request.Validate();
            var entity = ToEntity(request);
            entity.CheckNull(nameof(entity));
            await CreateAsync(entity);
            await CommitAsync();
            await CreateCommitAfterAsync(entity);
            return entity.Id.ToString();
        }

        /// <summary>
        /// 转换为实体
        /// </summary>
        /// <param name="request">创建参数</param>
        protected virtual TEntity ToEntity(TCreateRequest request)
        {
            return request.MapTo<TEntity>();
        }

        /// <summary>
        /// 创建实体
        /// </summary>
        private async Task CreateAsync(TEntity entity)
        {
            await CreateBeforeAsync(entity);
            entity.Init();
            await _repository.AddAsync(entity);
            await CreateAfterAsync(entity);
        }

        /// <summary>
        /// 创建前操作
        /// </summary>
        /// <param name="entity">实体</param>
        protected virtual Task CreateBeforeAsync(TEntity entity)
        {
            return Task.CompletedTask;
        }

        /// <summary>
        /// 创建后操作
        /// </summary>
        /// <param name="entity">实体</param>
        protected virtual Task CreateAfterAsync(TEntity entity)
        {
            return Task.CompletedTask;
        }

        /// <summary>
        /// 提交工作单元
        /// </summary>
        protected virtual async Task CommitAsync()
        {
            await UnitOfWork.CommitAsync();
        }

        /// <summary>
        /// 创建提交后操作
        /// </summary>
        /// <param name="entity">实体</param>
        protected virtual Task CreateCommitAfterAsync(TEntity entity)
        {
            return Task.CompletedTask;
        }

        #endregion

        #region UpdateAsync(修改)

        /// <inheritdoc />
        public virtual async Task UpdateAsync(TUpdateRequest request)
        {
            request.CheckNull(nameof(request));
            request.Validate();
            if (request.Id.IsEmpty())
                throw new InvalidOperationException(R.IdIsEmpty);
            var oldEntity = await FindOldEntityAsync(request.Id);
            oldEntity.CheckNull(nameof(oldEntity));
            var entity = ToEntity(oldEntity.Clone(), request);
            entity.CheckNull(nameof(entity));
            var changes = oldEntity.GetChanges(entity);
            await UpdateAsync(entity);
            await CommitAsync();
            await UpdateCommitAfterAsync(entity, changes);
        }

        /// <summary>
        /// 查找旧实体
        /// </summary>
        /// <param name="id">标识</param>
        private async Task<TEntity> FindOldEntityAsync(object id)
        {
            return await _repository.FindByIdAsync(id);
        }

        /// <summary>
        /// 转换为实体
        /// </summary>
        /// <param name="oldEntity">旧实体</param>
        /// <param name="request">修改参数</param>
        protected virtual TEntity ToEntity(TEntity oldEntity, TUpdateRequest request)
        {
            return request.MapTo(oldEntity);
        }

        /// <summary>
        /// 修改实体
        /// </summary>
        /// <param name="entity">实体</param>
        private async Task UpdateAsync(TEntity entity)
        {
            await UpdateBeforeAsync(entity);
            await _repository.UpdateAsync(entity);
            await UpdateAfterAsync(entity);
        }

        /// <summary>
        /// 修改前操作
        /// </summary>
        /// <param name="entity">实体</param>
        protected virtual Task UpdateBeforeAsync(TEntity entity)
        {
            return Task.CompletedTask;
        }

        /// <summary>
        /// 修改后操作
        /// </summary>
        /// <param name="entity">实体</param>
        protected virtual Task UpdateAfterAsync(TEntity entity)
        {
            return Task.CompletedTask;
        }

        /// <summary>
        /// 修改提交后操作
        /// </summary>
        /// <param name="entity">实体</param>
        /// <param name="changeValues">变更值集合</param>
        protected virtual Task UpdateCommitAfterAsync(TEntity entity, ChangeValueCollection changeValues)
        {
            return Task.CompletedTask;
        }

        #endregion

        #region DeleteAsync(删除)

        /// <inheritdoc />
        public virtual async Task DeleteAsync(string ids)
        {
            if (ids.IsEmpty())
                return;
            var entities = await _repository.FindByIdsAsync(ids);
            if (entities?.Count == 0)
                return;
            await DeleteBeforeAsync(entities);
            await _repository.RemoveAsync(entities);
            await DeleteAfterAsync(entities);
            await CommitAsync();
            await DeleteCommitAfterAsync(entities);
        }

        /// <summary>
        /// 删除前操作
        /// </summary>
        /// <param name="entities">实体列表</param>
        protected virtual Task DeleteBeforeAsync(List<TEntity> entities)
        {
            return Task.CompletedTask;
        }

        /// <summary>
        /// 删除后操作
        /// </summary>
        /// <param name="entities">实体集合</param>
        protected virtual Task DeleteAfterAsync(List<TEntity> entities)
        {
            return Task.CompletedTask;
        }

        /// <summary>
        /// 删除提交后操作
        /// </summary>
        /// <param name="entities">实体集合</param>
        protected virtual Task DeleteCommitAfterAsync(List<TEntity> entities)
        {
            return Task.CompletedTask;
        }

        #endregion

        #region SaveAsync(批量保存)

        /// <summary>
        /// 批量保存
        /// </summary>
        /// <param name="creationList">新增列表</param>
        /// <param name="updateList">修改列表</param>
        /// <param name="deleteList">删除列表</param>
        public virtual async Task<List<TDto>> SaveAsync(List<TDto> creationList, List<TDto> updateList, List<TDto> deleteList)
        {
            if (creationList == null && updateList == null && deleteList == null)
                return new List<TDto>();
            creationList ??= new List<TDto>();
            updateList ??= new List<TDto>();
            deleteList ??= new List<TDto>();
            FilterList(creationList, updateList, deleteList);
            var addEntities = ToEntities(creationList);
            var updateEntities = ToEntities(updateList);
            var deleteEntities = ToEntities(deleteList);
            await SaveBeforeAsync(addEntities, updateEntities, deleteEntities);
            await AddListAsync(addEntities);
            var changeValues = await UpdateListAsync(updateEntities);
            await DeleteListAsync(deleteEntities);
            await SaveAfterAsync(addEntities, updateEntities, deleteEntities);
            await CommitAsync();
            await SaveCommitAfterAsync(addEntities, updateEntities, deleteEntities, changeValues);
            return GetResult(addEntities, updateEntities);
        }

        /// <summary>
        /// 过滤列表
        /// </summary>
        private void FilterList(List<TDto> creationList, List<TDto> updateList, List<TDto> deleteList)
        {
            FilterByDeleteList(creationList, deleteList);
            FilterByDeleteList(updateList, deleteList);
        }

        /// <summary>
        /// 过滤需要删除的项
        /// </summary>
        private void FilterByDeleteList(List<TDto> list, List<TDto> deleteList)
        {
            for (int i = 0; i < list.Count; i++)
            {
                var item = list[i];
                if (deleteList.Any(d => d.Id == item.Id))
                    list.Remove(item);
            }
        }

        /// <summary>
        /// 转换为实体集合
        /// </summary>
        private List<TEntity> ToEntities(List<TDto> dtos)
        {
            return dtos.Select(ToEntity).Distinct().ToList();
        }

        /// <summary>
        /// 转换为实体
        /// </summary>
        /// <param name="request">参数</param>
        protected virtual TEntity ToEntity(TDto request)
        {
            return request.MapTo<TEntity>();
        }

        /// <summary>
        /// 保存前操作
        /// </summary>
        /// <param name="creationList">新增列表</param>
        /// <param name="updateList">修改列表</param>
        /// <param name="deleteList">删除列表</param>
        protected virtual Task SaveBeforeAsync(List<TEntity> creationList, List<TEntity> updateList, List<TEntity> deleteList)
        {
            return Task.CompletedTask;
        }

        /// <summary>
        /// 添加实体列表
        /// </summary>
        private async Task AddListAsync(List<TEntity> list)
        {
            if (list.Count == 0)
                return;
            foreach (var entity in list)
                await CreateAsync(entity);
        }

        /// <summary>
        /// 更新实体列表
        /// </summary>
        private async Task<List<Tuple<TEntity, ChangeValueCollection>>> UpdateListAsync(List<TEntity> list)
        {
            var result = new List<Tuple<TEntity, ChangeValueCollection>>();
            if (list.Count == 0)
                return result;
            var oldEntities = await FindOldEntities(list);
            foreach (var entity in list)
            {
                var oldEntity = oldEntities.Find(t => t.Id.Equals(entity.Id));
                if (oldEntity != null)
                    result.Add(new Tuple<TEntity, ChangeValueCollection>(entity, oldEntity.GetChanges(entity)));
                await UpdateAsync(entity);
            }
            return result;
        }

        /// <summary>
        /// 查找旧实体集合
        /// </summary>
        private async Task<List<TEntity>> FindOldEntities(List<TEntity> list)
        {
            return await _repository.FindAllAsync(item => list.Select(t => t.Id).Contains(item.Id));
        }

        /// <summary>
        /// 删除实体列表
        /// </summary>
        private async Task DeleteListAsync(List<TEntity> list)
        {
            if (list.Count == 0)
                return;
            foreach (var entity in list)
                await DeleteChildrenAsync(entity);
        }

        /// <summary>
        /// 删除子节点集合
        /// </summary>
        protected virtual async Task DeleteChildrenAsync(TEntity parent)
        {
            await _repository.RemoveAsync(parent.Id);
        }

        /// <summary>
        /// 保存后操作
        /// </summary>
        /// <param name="creationList">新增列表</param>
        /// <param name="updateList">修改列表</param>
        /// <param name="deleteList">删除列表</param>
        protected virtual Task SaveAfterAsync(List<TEntity> creationList, List<TEntity> updateList, List<TEntity> deleteList)
        {
            return Task.CompletedTask;
        }

        /// <summary>
        /// 保存提交后操作
        /// </summary>
        /// <param name="creationList">新增列表</param>
        /// <param name="updateList">修改列表</param>
        /// <param name="deleteList">删除列表</param>
        /// <param name="changeValues">变更值集合</param>
        protected virtual Task SaveCommitAfterAsync(List<TEntity> creationList, List<TEntity> updateList, List<TEntity> deleteList, List<Tuple<TEntity, ChangeValueCollection>> changeValues)
        {
            return Task.CompletedTask;
        }

        /// <summary>
        /// 获取结果
        /// </summary>
        protected virtual List<TDto> GetResult(List<TEntity> creationList, List<TEntity> updateList)
        {
            return creationList.Concat(updateList).Select(ToDto).ToList();
        }

        #endregion
    }

    /// <summary>
    /// 查询服务
    /// </summary>
    /// <typeparam name="TEntity">实体类型</typeparam>
    /// <typeparam name="TDto">数据传输对象类型</typeparam>
    /// <typeparam name="TQuery">查询参数类型</typeparam>
    public abstract class QueryServiceBase<TEntity, TDto, TQuery> : QueryServiceBase<TEntity, TDto, TQuery, Guid>
        where TEntity : class, IKey<Guid>
        where TDto : new()
        where TQuery : IPage
    {
        /// <summary>
        /// 初始化查询服务
        /// </summary>
        /// <param name="serviceProvider">服务提供器</param>
        /// <param name="store">查询存储器</param>
        protected QueryServiceBase(IServiceProvider serviceProvider, IQueryStore<TEntity, Guid> store) : base(serviceProvider, store)
        {
        }
    }

    /// <summary>
    /// 查询服务
    /// </summary>
    /// <typeparam name="TEntity">实体类型</typeparam>
    /// <typeparam name="TDto">数据传输对象类型</typeparam>
    /// <typeparam name="TQuery">查询参数类型</typeparam>
    /// <typeparam name="TKey">实体标识类型</typeparam>
    public abstract class QueryServiceBase<TEntity, TDto, TQuery, TKey> : ServiceBase, IQueryService<TDto, TQuery>
        where TEntity : class, IKey<TKey>
        where TDto : new()
        where TQuery : IPage
    {

        #region 字段

        /// <summary>
        /// 查询存储器
        /// </summary>
        private readonly IQueryStore<TEntity, TKey> _store;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化查询服务
        /// </summary>
        /// <param name="serviceProvider">服务提供器</param>
        /// <param name="store">查询存储器</param>
        protected QueryServiceBase(IServiceProvider serviceProvider, IQueryStore<TEntity, TKey> store) : base(serviceProvider)
        {
            _store = store ?? throw new ArgumentNullException(nameof(store));
        }

        #endregion

        #region 属性

        /// <summary>
        /// 查询时是否跟踪实体
        /// </summary>
        protected virtual bool IsTracking => false;

        #endregion

        #region ToDto(转换)

        /// <summary>
        /// 转换为数据传输对象
        /// </summary>
        /// <param name="entity">实体</param>
        protected virtual TDto ToDto(TEntity entity)
        {
            return entity.MapTo<TDto>();
        }

        #endregion

        #region GetAllAsync(获取全部实体)

        /// <inheritdoc />
        public virtual async Task<List<TDto>> GetAllAsync()
        {
            var entities = await GetStore().FindAllAsync();
            return entities.Select(ToDto).ToList();
        }

        /// <summary>
        /// 获取查询存储器
        /// </summary>
        private IQueryStore<TEntity, TKey> GetStore()
        {
            if (IsTracking)
                return _store;
            return _store.NoTracking();
        }

        #endregion

        #region GetByIdAsync(通过标识获取实体)

        /// <inheritdoc />
        public virtual async Task<TDto> GetByIdAsync(object id)
        {
            var key = Util.Helpers.Convert.To<TKey>(id);
            return ToDto(await GetStore().FindByIdAsync(key));
        }

        #endregion

        #region GetByIdsAsync(通过标识列表获取实体列表)

        /// <inheritdoc />
        public virtual async Task<List<TDto>> GetByIdsAsync(string ids)
        {
            var entities = await GetStore().FindByIdsAsync(ids);
            return entities.Select(ToDto).ToList();
        }

        #endregion

        #region QueryAsync(查询)

        /// <inheritdoc />
        public virtual async Task<List<TDto>> QueryAsync(TQuery param)
        {
            if (param == null)
                return new List<TDto>();
            var queryable = GetStore().Find();
            queryable = AddConditions(queryable, param);
            queryable = Filter(queryable, param);
            var result = await queryable.OrderBy(param).ToListAsync();
            return result.Select(ToDto).ToList();
        }

        /// <summary>
        /// 添加条件列表
        /// </summary>
        private IQueryable<TEntity> AddConditions(IQueryable<TEntity> queryable, TQuery param)
        {
            var conditions = GetConditions(param);
            if (conditions == null)
                return queryable;
            foreach (var condition in conditions)
                queryable = queryable.Where(condition);
            return queryable;
        }

        /// <summary>
        /// 获取条件列表
        /// </summary>
        protected virtual IEnumerable<ICondition<TEntity>> GetConditions(TQuery param)
        {
            return null;
        }

        /// <summary>
        /// 过滤
        /// </summary>
        protected virtual IQueryable<TEntity> Filter(IQueryable<TEntity> queryable, TQuery param)
        {
            return queryable;
        }

        #endregion

        #region PageQueryAsync(分页查询)

        /// <inheritdoc />
        public virtual async Task<PageList<TDto>> PageQueryAsync(TQuery param)
        {
            if (param == null)
                return new PageList<TDto>();
            var queryable = GetStore().Find();
            queryable = AddConditions(queryable, param);
            queryable = Filter(queryable, param);
            var result = await queryable.ToPageListAsync(param);
            return result.Convert(ToDto);
        }

        #endregion
    }

    #endregion

    #region Application.WebApi

    #region Controllers
    /// <summary>
    /// Crud控制器
    /// </summary>
    /// <typeparam name="TDto">数据传输对象类型</typeparam>
    /// <typeparam name="TQuery">查询参数类型</typeparam>
    public abstract class CrudControllerBase<TDto, TQuery> : CrudControllerBase<TDto, TDto, TDto, TQuery>
        where TDto : IDto, new()
        where TQuery : IPage
    {
        /// <summary>
        /// 初始化Crud控制器
        /// </summary>
        /// <param name="service">Crud服务</param>
        protected CrudControllerBase(ICrudService<TDto, TQuery> service)
            : base(service)
        {
        }
    }

    /// <summary>
    /// Crud控制器
    /// </summary>
    /// <typeparam name="TDto">数据传输对象类型</typeparam>
    /// <typeparam name="TCreateRequest">创建参数类型</typeparam>
    /// <typeparam name="TUpdateRequest">修改参数类型</typeparam>
    /// <typeparam name="TQuery">查询参数类型</typeparam>
    public abstract class CrudControllerBase<TDto, TCreateRequest, TUpdateRequest, TQuery> : QueryControllerBase<TDto, TQuery>
        where TDto : IDto, new()
        where TCreateRequest : IRequest, new()
        where TUpdateRequest : IDto, new()
        where TQuery : IPage
    {
        /// <summary>
        /// Crud服务
        /// </summary>
        private readonly ICrudService<TDto, TCreateRequest, TUpdateRequest, TQuery> _service;

        /// <summary>
        /// 初始化Crud控制器
        /// </summary>
        /// <param name="service">Crud服务</param>
        protected CrudControllerBase(ICrudService<TDto, TCreateRequest, TUpdateRequest, TQuery> service)
            : base(service)
        {
            _service = service;
        }

        /// <summary>
        /// 创建
        /// </summary>
        /// <param name="request">创建参数</param>
        protected async Task<IActionResult> CreateAsync(TCreateRequest request)
        {
            if (request == null)
                return Fail(ApplicationResource.CreateRequestIsEmpty);
            CreateBefore(request);
            var id = await _service.CreateAsync(request);
            var result = await _service.GetByIdAsync(id);
            return Success(result);
        }

        /// <summary>
        /// 创建前操作
        /// </summary>
        /// <param name="request">创建参数</param>
        protected virtual void CreateBefore(TCreateRequest request)
        {
        }

        /// <summary>
        /// 修改
        /// </summary>
        /// <param name="id">标识</param>
        /// <param name="request">修改参数</param>
        protected async Task<IActionResult> UpdateAsync(string id, TUpdateRequest request)
        {
            if (request == null)
                return Fail(ApplicationResource.UpdateRequestIsEmpty);
            if (id.IsEmpty() && request.Id.IsEmpty())
                return Fail(ApplicationResource.IdIsEmpty);
            if (request.Id.IsEmpty())
                request.Id = id;
            UpdateBefore(request);
            await _service.UpdateAsync(request);
            var result = await _service.GetByIdAsync(request.Id);
            return Success(result);
        }

        /// <summary>
        /// 修改前操作
        /// </summary>
        /// <param name="dto">修改参数</param>
        protected virtual void UpdateBefore(TUpdateRequest dto)
        {
        }

        /// <summary>
        /// 删除
        /// </summary>
        /// <param name="ids">标识列表</param>
        protected async Task<IActionResult> DeleteAsync(string ids)
        {
            await _service.DeleteAsync(ids);
            return Success();
        }

        /// <summary>
        /// 批量保存
        /// </summary>
        /// <param name="request">保存参数</param>
        protected async Task<IActionResult> SaveAsync(SaveModel request)
        {
            if (request == null)
                return Fail(ApplicationResource.RequestIsEmpty);
            var creationList = Util.Helpers.Json.ToObject<List<TDto>>(request.CreationList);
            var updateList = Util.Helpers.Json.ToObject<List<TDto>>(request.UpdateList);
            var deleteList = Util.Helpers.Json.ToObject<List<TDto>>(request.DeleteList);
            await _service.SaveAsync(creationList, updateList, deleteList);
            return Success();
        }
    }

    /// <summary>
    /// 查询控制器
    /// </summary>
    /// <typeparam name="TDto">数据传输对象类型</typeparam>
    /// <typeparam name="TQuery">查询参数类型</typeparam>    
    public abstract class QueryControllerBase<TDto, TQuery> : WebApiControllerBase
        where TQuery : IPage
        where TDto : IDto, new()
    {

        #region 字段

        /// <summary>
        /// 查询服务
        /// </summary>
        private readonly IQueryService<TDto, TQuery> _service;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化查询控制器
        /// </summary>
        /// <param name="service">查询服务</param>
        protected QueryControllerBase(IQueryService<TDto, TQuery> service)
        {
            _service = service;
        }

        #endregion

        #region GetAsync(获取单个实体)

        /// <summary>
        /// 获取单个实体
        /// </summary>
        /// <param name="id">标识</param>
        protected async Task<IActionResult> GetAsync(string id)
        {
            var result = await _service.GetByIdAsync(id);
            return Success(result);
        }

        #endregion

        #region QueryAsync(查询)

        /// <summary>
        /// 查询
        /// </summary>
        /// <param name="query">查询参数</param>
        protected async Task<IActionResult> QueryAsync(TQuery query)
        {
            if (query == null)
                return Fail(ApplicationResource.QueryIsEmpty);
            QueryBefore(query);
            var list = await _service.QueryAsync(query);
            var result = QueryAfter(list);
            return Success(result);
        }

        /// <summary>
        /// 查询前操作
        /// </summary>
        /// <param name="query">查询参数</param>
        protected virtual void QueryBefore(TQuery query)
        {
        }

        /// <summary>
        /// 查询后操作,用于转换查询结果
        /// </summary>
        /// <param name="list">查询结果</param>
        protected virtual dynamic QueryAfter(List<TDto> list)
        {
            return list;
        }

        #endregion

        #region PageQueryAsync(分页查询)

        /// <summary>
        /// 分页查询
        /// </summary>
        /// <param name="query">查询参数</param>
        protected async Task<IActionResult> PageQueryAsync(TQuery query)
        {
            if (query == null)
                return Fail(ApplicationResource.QueryIsEmpty);
            PageQueryBefore(query);
            var pageList = await _service.PageQueryAsync(query);
            var result = PageQueryAfter(pageList);
            return Success(result);
        }

        /// <summary>
        /// 分页查询前操作
        /// </summary>
        /// <param name="query">查询参数</param>
        protected virtual void PageQueryBefore(TQuery query)
        {
        }

        /// <summary>
        /// 分页查询后操作,用于转换查询结果
        /// </summary>
        /// <param name="pageList">分页查询结果</param>
        protected virtual dynamic PageQueryAfter(PageList<TDto> pageList)
        {
            return pageList;
        }

        #endregion

        #region GetItemsAsync(获取项列表)

        /// <summary>
        /// 获取项列表
        /// </summary>
        /// <param name="query">查询参数</param>
        protected async Task<IActionResult> GetItemsAsync(TQuery query)
        {
            if (query == null)
                return Fail(ApplicationResource.QueryIsEmpty);
            var result = new List<TDto>();
            await LoadSelectedItems(result);
            query = FilterGetItemsQuery(query);
            await LoadItemsByQuery(result, query);
            return Success(result.Select(dto => ToItem(dto, query)));
        }

        /// <summary>
        /// 加载选中项
        /// </summary>
        protected virtual async Task LoadSelectedItems(List<TDto> items)
        {
            var keys = GetLoadKeys();
            if (keys.IsEmpty())
                return;
            var selectedItems = await _service.GetByIdsAsync(keys);
            items.AddRange(selectedItems);
        }

        /// <summary>
        /// 获取选中项标识列表
        /// </summary>
        protected string GetLoadKeys()
        {
            return Request.Query["load_keys"].SafeString();
        }

        /// <summary>
        /// 过滤 GetItemsAsync 方法的查询参数
        /// </summary>
        /// <param name="query">查询参数</param>
        protected virtual TQuery FilterGetItemsQuery(TQuery query)
        {
            return query;
        }

        /// <summary>
        /// 查询加载项
        /// </summary>
        protected virtual async Task LoadItemsByQuery(List<TDto> items, TQuery query)
        {
            var pageList = await _service.PageQueryAsync(query);
            items.AddRange(pageList.Data);
        }

        /// <summary>
        /// 将Dto转换为列表项
        /// </summary>
        /// <param name="dto">数据传输对象</param>
        /// <param name="query">查询参数</param>
        protected virtual Item ToItem(TDto dto, TQuery query)
        {
            return ToItem(dto);
        }

        /// <summary>
        /// 将Dto转换为列表项
        /// </summary>
        /// <param name="dto">数据传输对象</param>
        protected virtual Item ToItem(TDto dto)
        {
            throw new NotImplementedException(nameof(ToItem));
        }

        #endregion
    }

