    /// <summary>
    /// 树形查询控制器
    /// </summary>
    /// <typeparam name="TDto">参数类型</typeparam>
    /// <typeparam name="TQuery">查询参数类型</typeparam>
    public abstract class TreeQueryControllerBase<TDto, TQuery> : WebApiControllerBase
        where TDto : class, ITreeNode, new()
        where TQuery : class, ITreeQueryParameter
    {

        #region 字段

        /// <summary>
        /// 树形服务
        /// </summary>
        private readonly ITreeQueryService<TDto, TQuery> _service;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化树形查询控制器
        /// </summary>
        /// <param name="service">树形服务</param>
        protected TreeQueryControllerBase(ITreeQueryService<TDto, TQuery> service)
        {
            _service = service ?? throw new ArgumentNullException(nameof(service));
        }

        #endregion

        #region GetMaxPageSize(获取最大分页大小 )

        /// <summary>
        /// 获取最大分页大小,默认值: 999
        /// </summary>
        protected virtual int GetMaxPageSize()
        {
            return 999;
        }

        #endregion

        #region GetLoadMode(获取加载模式)

        /// <summary>
        /// 获取加载模式,默认值: 同步加载模式
        /// </summary>
        protected virtual LoadMode GetLoadMode()
        {
            var loadMode = Request.Query["loadMode"].SafeString();
            var result = Util.Helpers.Enum.Parse<LoadMode?>(loadMode);
            if (result != null)
                return result.Value;
            return LoadMode.Sync;
        }

        #endregion

        #region IsFirstLoad(是否首次加载)

        /// <summary>
        /// 是否首次加载
        /// </summary>
        protected virtual bool IsFirstLoad()
        {
            var isSearch = Request.Query["is_search"].SafeString();
            if (isSearch == "false")
                return true;
            return false;
        }

        #endregion

        #region IsExpandAll(是否展开所有节点)

        /// <summary>
        /// 是否展开所有节点,仅对同步加载和同步查询有效
        /// </summary>
        protected virtual bool IsExpandAll()
        {
            var isExpandAll = Request.Query["is_expand_all"].SafeString();
            if (isExpandAll == "true")
                return true;
            return false;
        }

        #endregion

        #region IsExpandForRootAsync(根节点异步加载模式是否展开子节点)

        /// <summary>
        /// 根节点异步加载模式是否展开子节点,默认值: true
        /// </summary>
        protected virtual bool IsExpandForRootAsync()
        {
            var isExpand = Request.Query["is_expand_for_root_async"].SafeString();
            if (isExpand == "false")
                return false;
            return true;
        }

        #endregion

        #region GetLoadKeys(获取需要加载的标识列表)

        /// <summary>
        /// 获取需要加载的标识列表,当异步模式首次加载时,将选中节点的相关父节点加载回来,标识列表以逗号分隔
        /// </summary>
        /// <param name="query">查询参数</param>
        protected virtual string GetLoadKeys(TQuery query)
        {
            return Request.Query["load_keys"].SafeString();
        }

        #endregion

        #region GetAsync(获取单个实体)

        /// <summary>
        /// 获取单个实体
        /// </summary>
        /// <param name="id">标识</param>
        protected async Task<IActionResult> GetAsync(string id)
        {
            var result = await _service.GetByIdAsync(id);
            return Success(result);
        }

        #endregion

        #region QueryAsync(树形表格查询)

        /// <summary>
        /// 树形表格查询
        /// </summary>
        /// <param name="query">查询参数</param>
        protected async Task<IActionResult> QueryAsync(TQuery query)
        {
            var action = new TreeTableQueryAction<TDto, TQuery>(_service, GetLoadMode(), GetOperation(query),
                GetMaxPageSize(), IsFirstLoad(), IsExpandAll(), IsExpandForRootAsync(), QueryBefore, QueryAfter);
            var result = await action.QueryAsync(query);
            return Success(result);
        }

        /// <summary>
        /// 获取加载操作
        /// </summary>
        protected virtual LoadOperation GetOperation(TQuery query)
        {
            if (query.ParentId.IsEmpty())
                return LoadOperation.Query;
            return LoadOperation.LoadChildren;
        }

        /// <summary>
        /// 查询前操作
        /// </summary>
        /// <param name="query">查询参数</param>
        protected virtual void QueryBefore(TQuery query)
        {
        }

        /// <summary>
        /// 查询后操作
        /// </summary>
        /// <param name="data">数据列表</param>
        /// <param name="query">查询参数</param>
        protected virtual void QueryAfter(PageList<TDto> data, TQuery query)
        {
        }

        #endregion
    }

    /// <summary>
    /// WebApi控制器基类
    /// </summary>
    [ApiController]
    [Route("api/[controller]")]
    [ExceptionHandler(Order = 1)]
    [ErrorLogFilter(Order = 2)]
    public abstract class WebApiControllerBase : ControllerBase
    {
        /// <summary>
        /// 会话
        /// </summary>
        protected virtual ISession Session => UserSession.Instance;

        /// <summary>
        /// 获取日志操作
        /// </summary>
        protected virtual ILog GetLog()
        {
            try
            {
                var logFactory = Ioc.Create<ILogFactory>();
                return logFactory.CreateLog(GetType());
            }
            catch
            {
                return NullLog.Instance;
            }
        }

        /// <summary>
        /// 返回成功消息
        /// </summary>
        /// <param name="data">数据</param>
        /// <param name="message">消息</param>
        /// <param name="statusCode">Http状态码</param>
        protected virtual IActionResult Success(dynamic data = null, string message = null, int? statusCode = 200)
        {
            message ??= R.Success;
            return GetResult(StateCode.Ok, message, data, statusCode);
        }

        /// <summary>
        /// 获取结果
        /// </summary>
        private IActionResult GetResult(string code, string message, dynamic data, int? httpStatusCode)
        {
            var options = GetJsonSerializerOptions();
            var resultFactory = HttpContext.RequestServices.GetService<IResultFactory>();
            if (resultFactory == null)
                return new Result(code, message, data, httpStatusCode, options);
            return resultFactory.CreateResult(code, message, data, httpStatusCode, options);
        }

        /// <summary>
        /// 获取Json序列化配置
        /// </summary>
        private JsonSerializerOptions GetJsonSerializerOptions()
        {
            var factory = HttpContext.RequestServices.GetService<IJsonSerializerOptionsFactory>();
            if (factory != null)
                return factory.CreateOptions();
            return new JsonSerializerOptions
            {
                PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
                Encoder = JavaScriptEncoder.Create(UnicodeRanges.All),
                DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
                Converters = {
                new DateTimeJsonConverter(),
                new NullableDateTimeJsonConverter(),
                new LongJsonConverter(),
                new NullableLongJsonConverter()
            }
            };
        }

        /// <summary>
        /// 返回失败消息
        /// </summary>
        /// <param name="message">消息</param>
        /// <param name="statusCode">Http状态码</param>
        protected virtual IActionResult Fail(string message, int? statusCode = 200)
        {
            return GetResult(StateCode.Fail, message, null, statusCode);
        }

        /// <summary>
        /// 获取文件流结果,内容类型设置为 application/octet-stream
        /// </summary>
        /// <param name="stream">文件流</param>
        protected IActionResult GetStreamResult(Stream stream)
        {
            return new FileStreamResult(stream, "application/octet-stream");
        }

        /// <summary>
        /// 获取文件流结果,内容类型设置为 application/octet-stream
        /// </summary>
        /// <param name="stream">文件流</param>
        protected IActionResult GetStreamResult(byte[] stream)
        {
            return GetStreamResult(new MemoryStream(stream));
        }
    }

    #endregion

    #region Filters
    /// <summary>
    /// 错误日志过滤器
    /// </summary>
    public class ErrorLogFilterAttribute : ExceptionFilterAttribute
    {
        /// <summary>
        /// 异常处理
        /// </summary>
        public override void OnException(ExceptionContext context)
        {
            if (context == null)
                return;
            var log = context.HttpContext.RequestServices.GetService<ILogger<ErrorLogFilterAttribute>>();
            var exception = context.Exception.GetRawException();
            if (exception is Warning warning)
            {
                log.LogWarning(warning, exception.Message);
                return;
            }
            log.LogError(exception, exception.Message);
        }
    }

    /// <summary>
    /// 异常处理过滤器
    /// </summary>
    public class ExceptionHandlerAttribute : ExceptionFilterAttribute
    {
        /// <summary>
        /// 异常处理
        /// </summary>
        public override void OnException(ExceptionContext context)
        {
            context.ExceptionHandled = true;
            var message = context.Exception.GetPrompt(Web.Environment.IsProduction());
            message = GetLocalizedMessages(context, message);
            var errorCode = context.Exception.GetErrorCode() ?? StateCode.Fail;
            var httpStatusCode = context.Exception.GetHttpStatusCode() ?? 200;
            context.Result = GetResult(context, errorCode, message, httpStatusCode);
        }

        /// <summary>
        /// 获取本地化异常消息
        /// </summary>
        protected virtual string GetLocalizedMessages(ExceptionContext context, string message)
        {
            var exception = context.Exception.GetRawException();
            if (exception is not Warning warning)
                return message;
            if (warning.IsLocalization == false)
                return message;
            if (warning.IsLocalization == null)
            {
                var localizationOptions = context.HttpContext.RequestServices.GetService<IOptions<Util.Localization.LocalizationOptions>>();
                if (localizationOptions.Value.IsLocalizeWarning == false)
                    return message;
            }
            var stringLocalizerFactory = context.HttpContext.RequestServices.GetService<IStringLocalizerFactory>();
            if (stringLocalizerFactory == null)
                return message;
            var stringLocalizer = stringLocalizerFactory.Create("Warning", null);
            var localizedString = stringLocalizer[message];
            if (localizedString.ResourceNotFound == false)
                return localizedString.Value;
            stringLocalizer = context.HttpContext.RequestServices.GetService<IStringLocalizer>();
            if (stringLocalizer == null)
                return message;
            return stringLocalizer[message];
        }

        /// <summary>
        /// 获取结果
        /// </summary>
        protected virtual IActionResult GetResult(ExceptionContext context, string code, string message, int? httpStatusCode)
        {
            var options = GetJsonSerializerOptions(context);
            var resultFactory = context.HttpContext.RequestServices.GetService<IResultFactory>();
            if (resultFactory == null)
                return new Result(code, message, null, httpStatusCode, options);
            return resultFactory.CreateResult(code, message, null, httpStatusCode, options);
        }

        /// <summary>
        /// 获取Json序列化配置
        /// </summary>
        private JsonSerializerOptions GetJsonSerializerOptions(ExceptionContext context)
        {
            var factory = context.HttpContext.RequestServices.GetService<IJsonSerializerOptionsFactory>();
            if (factory != null)
                return factory.CreateOptions();
            return new JsonSerializerOptions
            {
                PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
                Encoder = JavaScriptEncoder.Create(UnicodeRanges.All),
                DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
                Converters = {
                new DateTimeJsonConverter(),
                new NullableDateTimeJsonConverter(),
                new LongJsonConverter(),
                new NullableLongJsonConverter()
            }
            };
        }
    }

    /// <summary>
    /// 请求锁过滤器,用于防止重复提交
    /// </summary>
    [AttributeUsage(AttributeTargets.Method)]
    public class LockAttribute : ActionFilterAttribute
    {
        /// <summary>
        /// 业务标识
        /// </summary>
        public string Key { get; set; }
        /// <summary>
        /// 业务锁类型
        /// </summary>
        public LockType Type { get; set; } = LockType.User;
        /// <summary>
        /// 再次提交时间间隔，单位：秒
        /// </summary>
        public int Interval { get; set; }

        /// <summary>
        /// 执行
        /// </summary>
        public override async Task OnActionExecutionAsync(ActionExecutingContext context, ActionExecutionDelegate next)
        {
            context.CheckNull(nameof(context));
            next.CheckNull(nameof(next));
            var @lock = CreateLock(context);
            var key = GetKey(context);
            var isSuccess = false;
            try
            {
                isSuccess = await @lock.LockAsync(key, GetExpiration());
                if (isSuccess == false)
                {
                    context.Result = GetResult(context, StateCode.Fail, GetFailMessage(context));
                    return;
                }
                OnActionExecuting(context);
                if (context.Result != null)
                    return;
                var executedContext = await next();
                OnActionExecuted(executedContext);
            }
            finally
            {
                if (isSuccess)
                {
                    await @lock.UnLockAsync();
                }
            }
        }

        /// <summary>
        /// 创建业务锁
        /// </summary>
        protected virtual ILock CreateLock(ActionExecutingContext context)
        {
            return context.HttpContext.RequestServices.GetService<ILock>() ?? NullLock.Instance;
        }

        /// <summary>
        /// 获取锁定标识
        /// </summary>
        protected virtual string GetKey(ActionExecutingContext context)
        {
            var userId = string.Empty;
            if (Type == LockType.User)
                userId = $"{GetUserId(context)}_";
            return string.IsNullOrWhiteSpace(Key) ? $"{userId}{Web.Request.Path}" : $"{userId}{Key}";
        }

        /// <summary>
        /// 获取用户标识
        /// </summary>
        protected string GetUserId(ActionExecutingContext context)
        {
            var session = context.HttpContext.RequestServices.GetService<ISession>();
            return session?.UserId;
        }

        /// <summary>
        /// 获取到期时间间隔
        /// </summary>
        private TimeSpan? GetExpiration()
        {
            if (Interval == 0)
                return null;
            return TimeSpan.FromSeconds(Interval);
        }

        /// <summary>
        /// 获取结果
        /// </summary>
        private IActionResult GetResult(ActionExecutingContext context, string code, string message)
        {
            var options = GetJsonSerializerOptions(context);
            var resultFactory = context.HttpContext.RequestServices.GetService<IResultFactory>();
            if (resultFactory == null)
                return new Result(code, message, options: options);
            return resultFactory.CreateResult(code, message, null, null, options);
        }

        /// <summary>
        /// 获取Json序列化配置
        /// </summary>
        private JsonSerializerOptions GetJsonSerializerOptions(ActionExecutingContext context)
        {
            var factory = context.HttpContext.RequestServices.GetService<IJsonSerializerOptionsFactory>();
            if (factory != null)
                return factory.CreateOptions();
            return new JsonSerializerOptions
            {
                PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
                Encoder = JavaScriptEncoder.Create(UnicodeRanges.All),
                DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
                Converters = {
                new DateTimeJsonConverter(),
                new NullableDateTimeJsonConverter(),
                new LongJsonConverter(),
                new NullableLongJsonConverter()
            }
            };
        }

        /// <summary>
        /// 获取失败消息
        /// </summary>
        protected virtual string GetFailMessage(ActionExecutingContext context)
        {
            if (Type == LockType.User)
                return GetLocalizedMessage(context, R.UserDuplicateRequest);
            return GetLocalizedMessage(context, R.GlobalDuplicateRequest);
        }

        /// <summary>
        /// 获取本地化消息
        /// </summary>
        protected virtual string GetLocalizedMessage(ActionExecutingContext context, string message)
        {
            var stringLocalizer = context.HttpContext.RequestServices.GetService<IStringLocalizer>();
            if (stringLocalizer == null)
                return message;
            return stringLocalizer[message];
        }
    }

