    #region Logging
    /// <summary>
    /// 日志上下文访问器
    /// </summary>
    public class LogContextAccessor : ILogContextAccessor
    {
        /// <summary>
        /// 日志上下文键名
        /// </summary>
        public const string LogContextKey = "Logging.LogContext";

        /// <summary>
        /// 日志上下文
        /// </summary>
        public LogContext Context
        {
            get => Util.Helpers.Convert.To<LogContext>(Web.HttpContext?.Items[LogContextKey]);
            set => Web.HttpContext.Items[LogContextKey] = value;
        }
    }

    /// <summary>
    /// 日志上下文中间件
    /// </summary>
    public class LogContextMiddleware
    {
        /// <summary>
        /// 下个中间件
        /// </summary>
        private readonly RequestDelegate _next;

        /// <summary>
        /// 初始化日志上下文中间件
        /// </summary>
        /// <param name="next">下个中间件</param>
        public LogContextMiddleware(RequestDelegate next)
        {
            _next = next;
        }

        /// <summary>
        /// 执行中间件
        /// </summary>
        /// <param name="context">Http上下文</param>
        public async Task Invoke(HttpContext context)
        {
            var traceId = context.Request.Headers["x-correlation-id"].SafeString();
            if (traceId.IsEmpty())
                traceId = context.TraceIdentifier;
            var session = context.RequestServices.GetService<Util.Sessions.ISession>();
            var environment = context.RequestServices.GetService<IWebHostEnvironment>();
            var logContext = new LogContext
            {
                Stopwatch = Stopwatch.StartNew(),
                TraceId = traceId,
                UserId = session?.UserId,
                Application = environment?.ApplicationName,
                Environment = environment?.EnvironmentName
            };
            context.Items[LogContextAccessor.LogContextKey] = logContext;
            await _next(context);
        }
    }

    /// <summary>
    /// 日志上下文中间件扩展
    /// </summary>
    public static class LogContextMiddlewareExtensions
    {
        /// <summary>
        /// 注册日志上下文中间件
        /// </summary>
        /// <param name="builder">应用程序生成器</param>
        public static IApplicationBuilder UseLogContext(this IApplicationBuilder builder)
        {
            return builder.UseMiddleware<LogContextMiddleware>();
        }
    }

    /// <summary>
    /// 日志上下文启动过滤器
    /// </summary>
    public class LogContextStartupFilter : IStartupFilter
    {
        /// <summary>
        /// 配置日志上下文中间件
        /// </summary>
        /// <param name="next">下个中间件操作</param>
        public Action<IApplicationBuilder> Configure(Action<IApplicationBuilder> next)
        {
            return app =>
            {
                app.UseLogContext();
                next(app);
            };
        }
    }

