    #region Events
    /// <summary>
    /// 事件状态
    /// </summary>
    public enum EventState
    {
        /// <summary>
        /// 已发布
        /// </summary>
        [Description("util.eventState.published")]
        Published = 1,
        /// <summary>
        /// 处理中
        /// </summary>
        [Description("util.eventState.processing")]
        Processing = 2,
        /// <summary>
        /// 所有订阅全部成功完成
        /// </summary>
        [Description("util.eventState.success")]
        Success = 3,
        /// <summary>
        /// 失败
        /// </summary>
        [Description("util.eventState.fail")]
        Fail = 4
    }

    /// <summary>
    /// 集成事件日志记录存储器
    /// </summary>
    public interface IIntegrationEventLogStore : ITransientDependency
    {
        /// <summary>
        /// 获取集成事件日志记录
        /// </summary>
        /// <param name="eventId">事件标识</param>
        /// <param name="cancellationToken">取消令牌</param>
        Task<IntegrationEventLog> GetAsync(string eventId, CancellationToken cancellationToken = default);
        /// <summary>
        /// 保存集成事件日志记录
        /// </summary>
        /// <param name="eventLog">集成事件日志记录</param>
        /// <param name="cancellationToken">取消令牌</param>
        Task SaveAsync(IntegrationEventLog eventLog, CancellationToken cancellationToken = default);
        /// <summary>
        /// 集成事件总条数加1
        /// </summary>
        /// <param name="cancellationToken">取消令牌</param>
        Task IncrementAsync(CancellationToken cancellationToken = default);
        /// <summary>
        /// 获取集成事件总条数
        /// </summary>
        /// <param name="cancellationToken">取消令牌</param>
        Task<int> GetCountAsync(CancellationToken cancellationToken = default);
        /// <summary>
        /// 清空集成事件总条数
        /// </summary>
        /// <param name="cancellationToken">取消令牌</param>
