        bool CanSubscription(IntegrationEventLog eventLog);
        /// <summary>
        /// 订阅是否已处理成功
        /// </summary>
        /// <param name="eventLog">集成事件日志记录</param>
        bool IsSubscriptionSuccess(IntegrationEventLog eventLog);
        /// <summary>
