    #region Events

    #region Fiters
    /// <summary>
    /// 集成事件订阅错误日志过滤器
    /// </summary>
    public class SubscriptionErrorLogFilterAttribute : ExceptionFilterAttribute
    {
        /// <summary>
        /// 异常处理
        /// </summary>
        public override void OnException(ExceptionContext context)
        {
            if (context == null)
                return;
            var log = context.HttpContext.RequestServices.GetService<ILogger<SubscriptionErrorLogFilterAttribute>>();
            var exception = context.Exception.GetRawException();
            if (exception is Warning warning)
            {
                log.LogWarning(warning, $"集成事件订阅处理失败:{exception.Message}");
                return;
            }
            log.LogError(exception, $"集成事件订阅处理失败:{exception.Message}");
        }
    }

    /// <summary>
    /// 集成事件订阅异常处理过滤器
    /// </summary>
    public class SubscriptionExceptionHandlerAttribute : ExceptionFilterAttribute
    {
        /// <summary>
        /// 异常处理
        /// </summary>
        public override void OnException(ExceptionContext context)
        {
            context.ExceptionHandled = true;
            var exception = context.Exception.GetRawException();
            if (exception == null)
                return;
            if (exception is ConcurrencyException concurrencyException)
            {
                context.Result = PubsubResult.Fail(concurrencyException.Message);
                return;
            }
            if (exception is Warning warning)
            {
                context.Result = PubsubResult.Drop(warning.Message);
                return;
            }
            context.Result = PubsubResult.Fail(Warning.GetMessage(exception));
        }
    }

    /// <summary>
    /// 集成事件订阅处理过滤器
    /// </summary>
    public class SubscriptionFilterAttribute : ActionFilterAttribute
    {
        /// <summary>
        /// 执行
        /// </summary>
        public override async Task OnActionExecutionAsync(ActionExecutingContext context, ActionExecutionDelegate next)
        {
            if (context == null)
                return;
            if (next == null)
                return;
            if (context.HttpContext.Request.ContentType != "application/cloudevents+json")
                return;
            var log = context.HttpContext.RequestServices.GetService<ILogger<SubscriptionFilterAttribute>>() ?? NullLogger<SubscriptionFilterAttribute>.Instance;
            try
            {
                var body = await GetBodyJsonElement(context);
                var routeUrl = context.HttpContext.Request.GetDisplayUrl();
                var eventId = GetEventId(body);
                if (eventId.IsEmpty())
                {
                    log.LogError("集成事件标识为空,body:{@body},routeUrl:{routeUrl}", body, routeUrl);
                    return;
                }
                log.LogTrace("准备处理集成事件订阅,eventId={@eventId},routeUrl={routeUrl}", eventId, routeUrl);
                var manager = context.HttpContext.RequestServices.GetRequiredService<IIntegrationEventManager>();
                var eventLog = await GetEventLog(manager, eventId);
                if (eventLog == null)
                {
                    log.LogError("集成事件为空,eventId={@eventId},body:{@body},routeUrl:{routeUrl}", eventId, body, routeUrl);
                    return;
                }
                if (manager.CanSubscription(eventLog) == false)
                {
                    log.LogDebug("集成事件订阅无需处理,eventId={@eventId},body:{@body},routeUrl={routeUrl}", eventId, body, routeUrl);
                    if (manager.IsSubscriptionSuccess(eventLog))
                        context.Result = PubsubResult.Success;
                    return;
                }
                var callback = context.HttpContext.RequestServices.GetRequiredService<IPubsubCallback>();
                await callback.OnSubscriptionBefore(eventLog, routeUrl);
                var executedContext = await next();
                OnActionExecuted(executedContext);
                if (executedContext.Result is PubsubResult result)
                {
                    await callback.OnSubscriptionAfter(eventId, result == PubsubResult.Success, result.Message);
                    return;
                }
                if (executedContext.Exception != null)
                {
                    await callback.OnSubscriptionAfter(eventId, false, Warning.GetMessage(executedContext.Exception));
                    return;
                }
            }
            catch (Exception exception)
            {
                log.LogError(exception, "集成事件订阅处理过滤器执行失败.");
                throw;
            }
        }

        /// <summary>
        /// 获取请求正文Json元素
        /// </summary>
        protected async Task<JsonElement> GetBodyJsonElement(ActionExecutingContext context)
        {
            var body = await GetBody(context);
            var client = context.HttpContext.RequestServices.GetService<DaprClient>();
            return await Util.Helpers.Json.ToObjectAsync<JsonElement>(body, client?.JsonSerializerOptions);
        }

        /// <summary>
        /// 获取请求正文
        /// </summary>
        protected async Task<byte[]> GetBody(ActionExecutingContext context)
        {
            context.HttpContext.Request.EnableBuffering();
            return await Util.Helpers.File.ReadToBytesAsync(context.HttpContext.Request.Body);
        }

        /// <summary>
        /// 获取集成事件标识
        /// </summary>
        protected string GetEventId(JsonElement body)
        {
            return body.TryGetProperty("eventId", out var eventId) ? eventId.Deserialize<string>() : null;
        }

        /// <summary>
        /// 获取集成事件
        /// </summary>
        protected async Task<IntegrationEventLog> GetEventLog(IIntegrationEventManager manager, string eventId)
        {
            for (var i = 0; i < 100; i++)
            {
                var eventLog = await manager.GetAsync(eventId);
                if (eventLog != null)
                    return eventLog;
                await Task.Delay(100);
            }
            return null;
        }
    }

    #endregion

    /// <summary>
    /// 云事件消息
    /// </summary>
    /// <typeparam name="TData">内容数据类型</typeparam>
    public class CloudEvent<TData> : CloudEvent
    {
        /// <summary>
        /// 初始化云事件消息
        /// </summary>
        /// <param name="id">事件标识</param>
        /// <param name="data">事件数据</param>
        public CloudEvent(string id, TData data)
        {
            Id = id.IsEmpty() ? Guid.NewGuid().ToString() : id;
            Data = data;
            DataContentType = "application/cloudevents+json";
            Headers = new Dictionary<string, string>();
        }

        /// <summary>
        /// 事件标识
        /// </summary>
        [JsonPropertyName("id")]
        public string Id { get; }

        /// <summary>
        /// 事件数据
        /// </summary>
        [JsonPropertyName("data")]
        public TData Data { get; set; }

        /// <summary>
        /// 事件标头
        /// </summary>
        [JsonPropertyName("headers")]
        public Dictionary<string, string> Headers { get; set; }

        /// <summary>
        /// 事件数据内容类型
        /// </summary>
        [JsonPropertyName("datacontenttype")]
        public string DataContentType { get; init; }

        /// <summary>
        /// 获取事件数据
        /// </summary>
        public T GetData<T>()
        {
            return (T)(object)Data;
        }
    }

    /// <summary>
    /// 云事件标头处理中间件
    /// </summary>
    public class CloudEventHeadersMiddleware
    {
        /// <summary>
        /// 中间件管道
        /// </summary>
        private readonly RequestDelegate _next;

        /// <summary>
        /// 初始化云事件标头处理中间件
        /// </summary>
        /// <param name="next">中间件管道</param>
        public CloudEventHeadersMiddleware(RequestDelegate next)
        {
            _next = next;
        }

        /// <summary>
        /// 执行管道
        /// </summary>
        /// <param name="httpContext">Http上下文</param>
        public async Task InvokeAsync(HttpContext httpContext)
        {
            if (_next == null)
                return;
            if (httpContext == null)
            {
                await _next(httpContext);
                return;
            }
            await ImportHeaders(httpContext);
            await _next(httpContext);
        }

        /// <summary>
        /// 导入请求头
        /// </summary>
        protected virtual async Task ImportHeaders(HttpContext httpContext)
        {
            if (httpContext.Request.ContentType != "application/cloudevents+json")
                return;
            httpContext.Request.EnableBuffering();
            var jsonElement = await JsonSerializer.DeserializeAsync<JsonElement>(httpContext.Request.Body);
            httpContext.Request.Body.Seek(0, SeekOrigin.Begin);
            if (jsonElement.TryGetProperty("headers", out var headers) == false)
                return;
            var result = headers.Deserialize<Dictionary<string, string>>();
            foreach (var item in result)
                httpContext.Request.Headers[item.Key] = item.Value;
        }
    }

    /// <summary>
    /// Dapr事件总线
    /// </summary>
    [Ioc(1)]
    public class DaprEventBus : IEventBus
    {
        /// <summary>
        /// 本地事件总线
        /// </summary>
        private readonly ILocalEventBus _localEventBus;
        /// <summary>
        /// 集成事件总线
        /// </summary>
        private readonly IIntegrationEventBus _integrationEventBus;

        /// <summary>
        /// 初始化Dapr事件总线
        /// </summary>
        /// <param name="localEventBus">本地事件总线</param>
        /// <param name="integrationEventBus">集成事件总线</param>
        public DaprEventBus(ILocalEventBus localEventBus, IIntegrationEventBus integrationEventBus)
        {
            _localEventBus = localEventBus ?? throw new ArgumentNullException(nameof(localEventBus));
            _integrationEventBus = integrationEventBus ?? throw new ArgumentNullException(nameof(integrationEventBus));
        }

        /// <inheritdoc />
        public async Task PublishAsync<TEvent>(TEvent @event, CancellationToken cancellationToken = default) where TEvent : IEvent
        {
            await _localEventBus.PublishAsync(@event, cancellationToken);
            if (@event is not IIntegrationEvent integrationEvent)
                return;
            await _integrationEventBus.PublishAsync(integrationEvent, cancellationToken);
        }
    }

    /// <summary>
    /// 基于Dapr的集成事件总线
    /// </summary>
    public class DaprIntegrationEventBus : IIntegrationEventBus
    {

        #region 字段

        /// <summary>
        /// Dapr客户端
        /// </summary>
        protected readonly DaprClient Client;
        /// <summary>
        /// 配置
        /// </summary>
        protected DaprOptions Options;
        /// <summary>
        /// 日志操作
        /// </summary>
        protected readonly ILogger Logger;
        /// <summary>
        /// 发布订阅回调操作
        /// </summary>
        protected IPubsubCallback PubsubCallback;
        /// <summary>
        /// 集成事件管理器
        /// </summary>
        protected IIntegrationEventManager EventManager;
        /// <summary>
        /// 发布订阅配置名称
        /// </summary>
        protected string Pubsub;
        /// <summary>
        /// 事件主题
        /// </summary>
        protected string TopicName;
        /// <summary>
        /// 事件类型
        /// </summary>
        protected string CloudEventType;
        /// <summary>
        /// 请求头集合
        /// </summary>
        protected Dictionary<string, string> Headers;
        /// <summary>
        /// 导入请求头键名集合
        /// </summary>
        protected List<string> ImportHeaderKeys;
        /// <summary>
        /// 移除请求头键名集合
        /// </summary>
        protected IList<string> RemoveHeaderKeys;
        /// <summary>
        /// 元数据
        /// </summary>
        protected Dictionary<string, string> Metadatas;
        /// <summary>
        /// 发布前操作
        /// </summary>
        protected Func<IIntegrationEvent, Dictionary<string, string>, Dictionary<string, string>, bool> OnBeforeAction;
        /// <summary>
        /// 发布后操作
        /// </summary>
        protected Func<IIntegrationEvent, Dictionary<string, string>, Dictionary<string, string>, Task> OnAfterAction;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化Dapr集成事件总线
        /// </summary>
        /// <param name="client">Dapr客户端</param>
        /// <param name="options">Dapr配置</param>
        /// <param name="loggerFactory">日志工厂</param>
        /// <param name="serviceProvider">服务提供器</param>
        public DaprIntegrationEventBus(DaprClient client, IOptions<DaprOptions> options, ILoggerFactory loggerFactory, IServiceProvider serviceProvider)
        {
            Client = client ?? throw new ArgumentNullException(nameof(client));
            Options = options?.Value ?? new DaprOptions();
            Logger = loggerFactory?.CreateLogger(typeof(DaprEventBus)) ?? NullLogger<DaprEventBus>.Instance;
            serviceProvider.CheckNull(nameof(serviceProvider));
            PubsubCallback = serviceProvider.GetService<IPubsubCallback>() ?? NullPubsubCallback.Instance;
            EventManager = serviceProvider.GetRequiredService<IIntegrationEventManager>();
            Headers = new Dictionary<string, string>();
            ImportHeaderKeys = new List<string>();
            RemoveHeaderKeys = new List<string>();
            Metadatas = new Dictionary<string, string>();
        }

        #endregion

        #region PubsubName

        /// <inheritdoc />
        public IIntegrationEventBus PubsubName(string pubsubName)
        {
            Pubsub = pubsubName;
            return this;
        }

        #endregion

        #region Topic

        /// <inheritdoc />
        public IIntegrationEventBus Topic(string topic)
        {
            TopicName = topic;
            return this;
        }

        #endregion

        #region Header

        /// <inheritdoc />
        public IIntegrationEventBus Header(string key, string value)
        {
            if (key.IsEmpty())
                return this;
            if (Headers.ContainsKey(key))
                Headers.Remove(key);
            Headers.Add(key, value);
            return this;
        }

        /// <inheritdoc />
        public IIntegrationEventBus Header(IDictionary<string, string> headers)
        {
            if (headers == null)
                return this;
            foreach (var header in headers)
                Header(header.Key, header.Value);
            return this;
        }

        #endregion

        #region ImportHeader

        /// <summary>
        /// 从当前HttpContext导入请求头
        /// </summary>
        /// <param name="key">请求头键名</param>
        public IIntegrationEventBus ImportHeader(string key)
        {
            if (key.IsEmpty())
                return this;
            if (ImportHeaderKeys.Contains(key) == false)
                ImportHeaderKeys.Add(key);
            return this;
        }

        /// <summary>
        /// 从当前HttpContext导入请求头
        /// </summary>
        /// <param name="keys">请求头键名集合</param>
        public IIntegrationEventBus ImportHeader(IEnumerable<string> keys)
        {
            if (keys == null)
                return this;
            foreach (var key in keys)
                ImportHeader(key);
            return this;
        }

        #endregion

        #region RemoveHeader

        /// <summary>
        /// 移除请求头
        /// </summary>
        /// <param name="key">请求头键名</param>
        public IIntegrationEventBus RemoveHeader(string key)
        {
            if (key.IsEmpty())
                return this;
            if (RemoveHeaderKeys.Contains(key) == false)
                RemoveHeaderKeys.Add(key);
            return this;
        }

        #endregion

        #region Metadata

        /// <inheritdoc />
        public IIntegrationEventBus Metadata(string key, string value)
        {
            if (key.IsEmpty())
                return this;
            if (value.IsEmpty())
                return this;
            RemoveMetadata(key);
            Metadatas.Add(key, value);
            return this;
        }

        /// <inheritdoc />
        public IIntegrationEventBus Metadata(IDictionary<string, string> metadata)
        {
            if (metadata == null)
                return this;
            foreach (var item in metadata)
                Metadata(item.Key, item.Value);
            return this;
        }

        #endregion

        #region RemoveMetadata

        /// <inheritdoc />
        public IIntegrationEventBus RemoveMetadata(string key)
        {
            if (key.IsEmpty())
                return this;
            if (Metadatas.ContainsKey(key))
                Metadatas.Remove(key);
            return this;
        }

        #endregion

        #region Type

        /// <inheritdoc />
        public IIntegrationEventBus Type(string value)
        {
            CloudEventType = value;
            return this;
        }

        #endregion

        #region OnBefore

        /// <inheritdoc />
        public IIntegrationEventBus OnBefore(Func<IIntegrationEvent, Dictionary<string, string>, Dictionary<string, string>, bool> action)
        {
            OnBeforeAction = action;
            return this;
        }

        #endregion

        #region OnAfter

        /// <inheritdoc />
        public IIntegrationEventBus OnAfter(Func<IIntegrationEvent, Dictionary<string, string>, Dictionary<string, string>, Task> action)
        {
            OnAfterAction = action;
            return this;
        }

        #endregion

        #region PublishAsync

        /// <inheritdoc />
        public virtual async Task PublishAsync<TEvent>(TEvent @event, CancellationToken cancellationToken = default) where TEvent : IIntegrationEvent
        {
            @event.CheckNull(nameof(@event));
            cancellationToken.ThrowIfCancellationRequested();
            ImportHeaders();
            Init(@event);
            if (OnBeforeAction != null && OnBeforeAction(@event, Headers, Metadatas) == false)
                return;
            await PublishEventAsync(@event, cancellationToken);
        }

        /// <summary>
        /// 导入请求头
        /// </summary>
        protected virtual void ImportHeaders()
        {
            RemoveHeaders();
            SetHeaders();
        }

        /// <summary>
        /// 移除请求头
        /// </summary>
        private void RemoveHeaders()
        {
            foreach (var key in RemoveHeaderKeys)
            {
                Headers.Remove(key);
                ImportHeaderKeys.Remove(key);
                Options.Pubsub.ImportHeaderKeys.Remove(key);
            }
        }

        /// <summary>
        /// 设置请求头
        /// </summary>
        private void SetHeaders()
        {
            var headers = GetImportHeaders();
            foreach (var item in headers)
                Headers.TryAdd(item.Key, item.Value);
        }

        /// <summary>
        /// 获取导入的请求头
        /// </summary>
        private IDictionary<string, string> GetImportHeaders()
        {
            var result = new Dictionary<string, string>();
            ImportHeaderKeys.AddRange(Options.Pubsub.ImportHeaderKeys);
            if (ImportHeaderKeys.Count == 0)
                return result;
            var headers = Web.Request?.Headers;
            if (headers == null)
                return result;
            foreach (var key in ImportHeaderKeys.Distinct())
            {
                if (headers.TryGetValue(key, out var value))
                    result.Add(key, value);
            }
            return result;
        }

        /// <summary>
        /// 初始化
        /// </summary>
        protected void Init(IIntegrationEvent integrationEvent)
        {
            InitPubsubName(integrationEvent);
            InitTopic(integrationEvent);
        }

        /// <summary>
        /// 初始化发布订阅名称
        /// </summary>
        protected void InitPubsubName(IIntegrationEvent integrationEvent)
        {
            if (Pubsub.IsEmpty() == false)
                return;
            Pubsub = PubsubNameAttribute.GetName(integrationEvent.GetType());
        }

        /// <summary>
        /// 初始化事件主题
        /// </summary>
        protected void InitTopic(IIntegrationEvent integrationEvent)
        {
            if (TopicName.IsEmpty() == false)
                return;
            TopicName = TopicNameAttribute.GetName(integrationEvent.GetType());
        }

        /// <summary>
        /// 发布事件
        /// </summary>
        protected virtual async Task PublishEventAsync(IIntegrationEvent @event, CancellationToken cancellationToken)
        {
            Logger.LogTrace("Publishing event {@Event} to {PubsubName}.{Topic}", @event, Pubsub, TopicName);
            var cloudEvent = CreateCloudEvent(@event);
            var argument = CreatePubsubArgument(cloudEvent);
            await PubsubCallback.OnPublishBefore(argument, cancellationToken);
            await Client.PublishEventAsync(Pubsub, TopicName, cloudEvent, Metadatas, cancellationToken);
            await PubsubCallback.OnPublishAfter(argument, cancellationToken);
            if (OnAfterAction != null)
                await OnAfterAction(@event, Headers, Metadatas);
        }

        /// <summary>
        /// 创建云事件
        /// </summary>
        protected CloudEvent<object> CreateCloudEvent(IIntegrationEvent @event)
        {
            var result = new CloudEvent<object>(@event.EventId, @event)
            {
                Type = CloudEventType,
                Headers = Headers.Count > 0 ? Headers : null
            };
            return result;
        }

        /// <summary>
        /// 创建发布订阅参数
        /// </summary>
        protected PubsubArgument CreatePubsubArgument(CloudEvent<object> cloudEvent)
        {
            return Metadatas.Count > 0 ? new PubsubArgument(Pubsub, TopicName, cloudEvent, Metadatas) : new PubsubArgument(Pubsub, TopicName, cloudEvent);
        }

        #endregion

        #region RepublishAsync

        /// <inheritdoc />
        public virtual async Task RepublishAsync(string eventId, CancellationToken cancellationToken = default)
        {
            if (Options.Pubsub.EnableEventLog == false)
                return;
            if (eventId.IsEmpty())
            {
                Logger.LogWarning("重新发布集成事件失败,事件标识不能为空.");
                return;
            }
            var eventLog = await EventManager.GetAsync(eventId, cancellationToken);
            await RepublishAsync(eventLog, cancellationToken);
        }

        /// <summary>
        /// 重新发布集成事件
        /// </summary>
        /// <param name="eventLog">集成事件日志记录</param>
        /// <param name="cancellationToken">取消令牌</param>
        protected virtual async Task RepublishAsync(IntegrationEventLog eventLog, CancellationToken cancellationToken = default)
        {
            eventLog.CheckNull(nameof(eventLog));
            eventLog.SubscriptionLogs.ForEach(t =>
            {
                if (t.State == SubscriptionState.Fail)
                    t.RetryCount = 0;
            });
            await EventManager.SaveAsync(eventLog, cancellationToken);
            var json = Util.Helpers.Json.ToJson(eventLog.Value);
            var argument = Util.Helpers.Json.ToObject<PubsubArgument<CloudEvent<object>>>(json);
            var cloudEvent = argument.GetEventData<CloudEvent<object>>();
            Logger.LogTrace("Republishing event {@Event} to {PubsubName}.{Topic}", cloudEvent.Data, eventLog.PubsubName, eventLog.Topic);
            await PubsubCallback.OnRepublishBefore(eventLog, cancellationToken);
            await Client.PublishEventAsync(eventLog.PubsubName, eventLog.Topic, cloudEvent, argument.Metadata ?? new Dictionary<string, string>(), cancellationToken);
            await PubsubCallback.OnRepublishAfter(eventLog, cancellationToken);
        }

        #endregion
    }

    /// <summary>
    /// 发布订阅回调操作 - 集成事件日志记录
    /// </summary>
    public class EventLogPubsubCallback : IPubsubCallback
    {
        /// <summary>
        /// 初始化发布订阅回调操作
        /// </summary>
        /// <param name="manager">集成事件管理器</param>
        public EventLogPubsubCallback(IIntegrationEventManager manager)
        {
            Manager = manager ?? throw new ArgumentNullException(nameof(manager));
        }

        /// <summary>
        /// 集成事件管理器
        /// </summary>
        protected IIntegrationEventManager Manager;

        /// <inheritdoc />
        public virtual Task OnPublishBefore(PubsubArgument argument, CancellationToken cancellationToken = default)
        {
            return Task.CompletedTask;
        }

        /// <inheritdoc />
        public virtual async Task OnPublishAfter(PubsubArgument argument, CancellationToken cancellationToken = default)
        {
            var result = await Manager.CreatePublishLogAsync(argument, cancellationToken);
            if (result == NullIntegrationEventLog.Instance)
                return;
            await Manager.IncrementAsync(cancellationToken);
        }

        /// <inheritdoc />
        public virtual async Task OnSubscriptionBefore(IntegrationEventLog eventLog, string routeUrl, CancellationToken cancellationToken = default)
        {
            await Manager.CreateSubscriptionLogAsync(eventLog, routeUrl, cancellationToken);
        }

        /// <inheritdoc />
        public virtual async Task OnSubscriptionAfter(string eventId, bool isSuccess, string message, CancellationToken cancellationToken = default)
        {
            if (isSuccess)
            {
                await Manager.SubscriptionSuccessAsync(eventId, cancellationToken);
                return;
            }
            await Manager.SubscriptionFailAsync(eventId, message, cancellationToken);
        }

        /// <inheritdoc />
        public virtual Task OnRepublishBefore(IntegrationEventLog eventLog, CancellationToken cancellationToken = default)
        {
            return Task.CompletedTask;
        }

        /// <inheritdoc />
        public virtual Task OnRepublishAfter(IntegrationEventLog eventLog, CancellationToken cancellationToken = default)
        {
            return Task.CompletedTask;
        }
    }

    /// <summary>
    /// 获取应用标识服务
    /// </summary>
    public class GetAppIdService : IGetAppId
    {
        /// <summary>
        /// Dapr配置
        /// </summary>
        private readonly DaprOptions _options;
        /// <summary>
        /// 主机环境
        /// </summary>
        private readonly IWebHostEnvironment _environment;

        /// <summary>
        /// 初始化获取应用标识服务
        /// </summary>
        /// <param name="options">Dapr配置</param>
        /// <param name="environment">主机环境</param>
        public GetAppIdService(IOptions<DaprOptions> options, IWebHostEnvironment environment = null)
        {
            _options = options?.Value ?? new DaprOptions();
            _environment = environment;
        }

        /// <summary>
        /// 获取应用标识
        /// </summary>
        public string GetAppId()
        {
            var result = DaprHelper.GetAppId();
            if (result.IsEmpty() == false)
                return result;
            return _options.AppId.IsEmpty() ? _environment?.ApplicationName : _options.AppId;
        }
    }

    /// <summary>
    /// 获取应用标识
    /// </summary>
    public interface IGetAppId : ISingletonDependency
    {
        /// <summary>
        /// 获取应用标识
        /// </summary>
        string GetAppId();
    }

    /// <summary>
    /// 集成事件计数
    /// </summary>
    public class IntegrationEventCount : IDataKey, IETag
    {
        /// <inheritdoc />
        public string Id { get; set; }

        /// <inheritdoc />
        public string ETag { get; set; }

        /// <summary>
        /// 集成事件总条数
        /// </summary>
        public int? Count { get; set; }
    }

    /// <summary>
    /// 集成事件日志记录存储器
    /// </summary>
    public class IntegrationEventLogStore : IIntegrationEventLogStore
    {
        /// <summary>
        /// 初始化集成事件日志记录存储器
        /// </summary>
        /// <param name="stateManager">状态管理操作</param>
        /// <param name="options">配置</param>
        public IntegrationEventLogStore(IStateManager stateManager, IOptions<DaprOptions> options)
        {
            StateManager = stateManager ?? throw new ArgumentNullException(nameof(stateManager));
            StateManager.StoreName(options?.Value.Pubsub?.EventLogStoreName ?? "statestore");
        }

        /// <summary>
        /// 集成事件总条数键名
        /// </summary>
        public const string KeyCount = "IntegrationEventCount";
        /// <summary>
        /// 状态管理操作
        /// </summary>
        protected IStateManager StateManager;

        /// <inheritdoc />
        public virtual async Task<IntegrationEventLog> GetAsync(string eventId, CancellationToken cancellationToken = default)
        {
            return await StateManager.GetByIdAsync<IntegrationEventLog>(eventId, cancellationToken);
        }

        /// <inheritdoc />
        public virtual async Task SaveAsync(IntegrationEventLog eventLog, CancellationToken cancellationToken = default)
        {
            await StateManager.SaveAsync(eventLog, cancellationToken);
        }

        /// <inheritdoc />
        public virtual async Task IncrementAsync(CancellationToken cancellationToken = default)
        {
            var result = await GetIntegrationEventCount(cancellationToken);
            result.Count = result.Count.SafeValue() + 1;
            await StateManager.SaveAsync(result, cancellationToken, KeyCount);
        }

        /// <summary>
        /// 获取集成事件计数
        /// </summary>
        protected async Task<IntegrationEventCount> GetIntegrationEventCount(CancellationToken cancellationToken)
        {
            return await StateManager.GetAsync<IntegrationEventCount>(KeyCount, cancellationToken) ?? new IntegrationEventCount();
        }

        /// <inheritdoc />
        public virtual async Task<int> GetCountAsync(CancellationToken cancellationToken = default)
        {
            var result = await GetIntegrationEventCount(cancellationToken);
            return result.Count.SafeValue();
        }

        /// <inheritdoc />
        public virtual async Task ClearCountAsync(CancellationToken cancellationToken = default)
        {
            await StateManager.RemoveAsync(KeyCount, cancellationToken);
        }
    }

    /// <summary>
    /// 集成事件管理器
    /// </summary>
    public class IntegrationEventManager : IIntegrationEventManager
    {

        #region 字段

        /// <summary>
        /// 集成事件日志记录存储器
        /// </summary>
        protected IIntegrationEventLogStore Store;
        /// <summary>
        /// 用户会话
        /// </summary>
        protected ISession Session;
        /// <summary>
        /// 获取应用标识服务
        /// </summary>
        protected IGetAppId GetAppIdService;
        /// <summary>
        /// 配置
        /// </summary>
        protected DaprOptions Options;
        /// <summary>
        /// 日志
        /// </summary>
        protected ILogger<IntegrationEventManager> Log;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化集成事件日志记录存储器
        /// </summary>
        /// <param name="store">集成事件日志记录存储器</param>
        /// <param name="session">用户会话</param>
        /// <param name="getAppIdService">获取应用标识服务</param>
        /// <param name="options">Dapr配置</param>
        /// <param name="logger">日志</param>
        public IntegrationEventManager(IIntegrationEventLogStore store, Util.Sessions.ISession session, IGetAppId getAppIdService,
            IOptions<DaprOptions> options, ILogger<IntegrationEventManager> logger)
        {
            Store = store ?? throw new ArgumentNullException(nameof(store));
            Session = session ?? Util.Sessions.NullSession.Instance;
            GetAppIdService = getAppIdService ?? throw new ArgumentNullException(nameof(getAppIdService));
            Options = options?.Value ?? new DaprOptions();
            Log = logger ?? NullLogger<IntegrationEventManager>.Instance;
        }

        #endregion

        #region IncrementAsync

        /// <inheritdoc />
        public virtual async Task IncrementAsync(CancellationToken cancellationToken = default)
        {
            try
            {
                await Store.IncrementAsync(cancellationToken);
            }
            catch (ConcurrencyException)
            {
                Log.LogDebug("更新集成事件计数出现并发异常,即将重试");
                await IncrementAsync(cancellationToken);
            }
            catch (Exception exception)
            {
                Log.LogError(exception, "更新集成事件计数失败");
            }
        }

        #endregion

        #region GetCountAsync

        /// <inheritdoc />
        public virtual async Task<int> GetCountAsync(CancellationToken cancellationToken = default)
        {
            return await Store.GetCountAsync(cancellationToken);
        }

        #endregion

        #region ClearCountAsync

        /// <inheritdoc />
        public virtual async Task ClearCountAsync(CancellationToken cancellationToken = default)
        {
            await Store.ClearCountAsync(cancellationToken);
        }

        #endregion

        #region GetAsync

        /// <inheritdoc />
        public virtual async Task<IntegrationEventLog> GetAsync(string eventId, CancellationToken cancellationToken = default)
        {
            if (Options.Pubsub.EnableEventLog == false)
                return NullIntegrationEventLog.Instance;
            return await Store.GetAsync(eventId, cancellationToken);
        }

        #endregion

        #region SaveAsync

        /// <summary>
        /// 保存集成事件日志记录
        /// </summary>
        /// <param name="eventLog">集成事件日志记录</param>
        /// <param name="cancellationToken">取消令牌</param>
        public virtual async Task SaveAsync(IntegrationEventLog eventLog, CancellationToken cancellationToken = default)
        {
            eventLog.CheckNull(nameof(eventLog));
            await Store.SaveAsync(eventLog, cancellationToken);
        }

        #endregion

        #region CanSubscriptionAsync

        /// <inheritdoc />
        public async Task<bool> CanSubscriptionAsync(string eventId, CancellationToken cancellationToken = default)
        {
            if (Options.Pubsub.EnableEventLog == false)
                return true;
            var eventLog = await GetAsync(eventId, cancellationToken);
            return CanSubscription(eventLog);
        }

        #endregion

        #region CanSubscription

        /// <inheritdoc />
        public virtual bool CanSubscription(IntegrationEventLog eventLog)
        {
            if (Options.Pubsub.EnableEventLog == false)
                return true;
            if (eventLog == null)
                return false;
            var subscriptionLog = GetSubscriptionLog(eventLog);
            if (subscriptionLog == null)
                return true;
            return subscriptionLog.State == SubscriptionState.Fail && subscriptionLog.RetryCount.SafeValue() < Options.Pubsub.MaxRetry;
        }

        /// <summary>
        /// 获取当前应用的订阅日志
        /// </summary>
        protected SubscriptionLog GetSubscriptionLog(IntegrationEventLog eventLog)
        {
            var appId = GetAppId(eventLog.Id);
            return GetSubscriptionLog(eventLog, appId);
        }

        /// <summary>
        /// 获取应用标识
        /// </summary>
        protected string GetAppId(string eventId)
        {
            var appId = GetAppIdService.GetAppId();
            if (appId.IsEmpty())
                throw new Warning($"应用标识不能为空,eventId:{eventId}");
            return appId;
        }

        /// <summary>
        /// 获取当前应用的订阅日志
        /// </summary>
        protected SubscriptionLog GetSubscriptionLog(IntegrationEventLog eventLog, string appId)
        {
            return eventLog.SubscriptionLogs.Find(t => t.AppId == appId);
        }

        #endregion

        #region IsSubscriptionSuccess

        /// <inheritdoc />
        public virtual bool IsSubscriptionSuccess(IntegrationEventLog eventLog)
        {
            if (Options.Pubsub.EnableEventLog == false)
                return true;
            var subscriptionLog = GetSubscriptionLog(eventLog);
            return subscriptionLog is { State: SubscriptionState.Success };
        }

        #endregion

        #region CreatePublishLogAsync

        /// <inheritdoc />
        public virtual async Task<IntegrationEventLog> CreatePublishLogAsync(PubsubArgument argument, CancellationToken cancellationToken = default)
        {
            if (Options.Pubsub.EnableEventLog == false)
                return NullIntegrationEventLog.Instance;
            var result = CreateEventLog(argument);
            if (result == null)
                return NullIntegrationEventLog.Instance;
            await SaveAsync(result, cancellationToken);
            Log.LogDebug("创建集成事件发布日志记录成功,EventLog={@EventLog}", result);
            return result;
        }

        /// <summary>
        /// 创建集成事件日志
        /// </summary>
        protected virtual IntegrationEventLog CreateEventLog(PubsubArgument argument)
        {
            if (argument.EventData is not CloudEvent<object> cloudEvent)
                return null;
            if (cloudEvent.Data is not IIntegrationEvent integrationEvent)
                return null;
            var appId = GetAppId(integrationEvent.EventId);
            if (appId.IsEmpty())
                throw new Warning($"应用标识不能为空,eventId:{cloudEvent.Id}");
            var result = new IntegrationEventLog
            {
                Id = integrationEvent.EventId,
                AppId = appId,
                UserId = Session.UserId,
                PubsubName = argument.Pubsub,
                Topic = argument.Topic,
                Value = argument,
                State = EventState.Published,
                PublishTime = integrationEvent.EventTime,
                LastModificationTime = Time.Now
            };
            return result;
        }

        #endregion

        #region CreateSubscriptionLogAsync

        /// <inheritdoc />
        public virtual async Task<IntegrationEventLog> CreateSubscriptionLogAsync(string eventId, string routeUrl, CancellationToken cancellationToken = default)
        {
            if (Options.Pubsub.EnableEventLog == false)
                return NullIntegrationEventLog.Instance;
            if (eventId.IsEmpty())
            {
                Log.LogWarning("创建集成事件订阅日志记录失败,事件标识不能为空,routeUrl={@routeUrl}", routeUrl);
                return NullIntegrationEventLog.Instance;
            }
            var eventLog = await GetAsync(eventId, cancellationToken);
            return await CreateSubscriptionLogAsync(eventLog, routeUrl, cancellationToken);
        }

        /// <inheritdoc />
        public virtual async Task<IntegrationEventLog> CreateSubscriptionLogAsync(IntegrationEventLog eventLog, string routeUrl, CancellationToken cancellationToken = default)
        {
            if (Options.Pubsub.EnableEventLog == false)
                return NullIntegrationEventLog.Instance;
            eventLog.CheckNull(nameof(eventLog));
            if (CanSubscription(eventLog) == false)
                return eventLog;
            AddSubscriptionLog(eventLog, routeUrl);
            eventLog.State = EventState.Processing;
            eventLog.LastModificationTime = Time.Now;
            try
            {
                await SaveAsync(eventLog, cancellationToken);
                Log.LogDebug("创建集成事件订阅日志记录成功,EventLog={@EventLog}", ToDebugEventLog(eventLog));
            }
            catch (ConcurrencyException)
            {
                Log.LogDebug("创建集成事件订阅日志记录出现并发异常,即将重试,eventId={eventId},routeUrl={routeUrl}", eventLog.Id, routeUrl);
                return await CreateSubscriptionLogAsync(eventLog.Id, routeUrl, cancellationToken);
            }
            catch (Exception exception)
            {
                Log.LogError(exception, "创建集成事件订阅日志记录失败,EventLog={@EventLog}", ToDebugEventLog(eventLog));
            }
            return eventLog;
        }

        /// <summary>
        /// 转换为调试状态
        /// </summary>
        protected IntegrationEventLog<PubsubArgument<CloudEvent<object>>> ToDebugEventLog(IntegrationEventLog eventLog)
        {
            var json = Util.Helpers.Json.ToJson(eventLog.Value);
            var result = new IntegrationEventLog<PubsubArgument<CloudEvent<object>>>
            {
                Id = eventLog.Id,
                UserId = eventLog.UserId,
                AppId = eventLog.AppId,
                LastModificationTime = eventLog.LastModificationTime,
                DataType = eventLog.DataType,
                ETag = eventLog.ETag,
                PublishTime = eventLog.PublishTime,
                State = eventLog.State,
                PubsubName = eventLog.PubsubName,
                Topic = eventLog.Topic,
                SubscriptionLogs = eventLog.SubscriptionLogs,
                Value = Util.Helpers.Json.ToObject<PubsubArgument<CloudEvent<object>>>(json)
            };
            if (result.Value is { EventData: not null })
                result.Value.EventData.Data = Util.Helpers.Json.ToJson(result.Value.EventData.Data);
            return result;
        }

        /// <summary>
        /// 添加订阅日志
        /// </summary>
        protected virtual void AddSubscriptionLog(IntegrationEventLog eventLog, string routeUrl)
        {
            var appId = GetAppId(eventLog.Id);
            var subscriptionLog = eventLog.SubscriptionLogs.Find(t => t.AppId == appId);
            if (subscriptionLog == null)
            {
                subscriptionLog = CreateSubscriptionLog(appId, routeUrl);
                eventLog.SubscriptionLogs.Add(subscriptionLog);
                return;
            }
            subscriptionLog.State = SubscriptionState.Processing;
            subscriptionLog.LastModificationTime = Time.Now;
            subscriptionLog.RetryCount = subscriptionLog.RetryCount.SafeValue() + 1;
            UpdateRetryTime(subscriptionLog);
        }

        /// <summary>
        /// 创建订阅日志
        /// </summary>
        protected virtual SubscriptionLog CreateSubscriptionLog(string appId, string routeUrl)
        {
            return new SubscriptionLog
            {
                AppId = appId,
                RouteUrl = routeUrl,
                State = SubscriptionState.Processing,
                SubscriptionTime = Time.Now,
                LastModificationTime = Time.Now,
            };
        }

        /// <summary>
        /// 更新重试时间
        /// </summary>
        protected virtual void UpdateRetryTime(SubscriptionLog subscriptionLog)
        {
            if (subscriptionLog.RetryLogs.Count == 0)
                return;
            var retryLog = subscriptionLog.RetryLogs.MaxBy(t => t.Number);
            retryLog.RetryTime = Time.Now;
        }

        #endregion

        #region SubscriptionSuccessAsync

        /// <inheritdoc />
        public virtual async Task<IntegrationEventLog> SubscriptionSuccessAsync(string eventId, CancellationToken cancellationToken = default)
        {
            if (Options.Pubsub.EnableEventLog == false)
                return NullIntegrationEventLog.Instance;
            if (eventId.IsEmpty())
            {
                Log.LogWarning("SubscriptionSuccessAsync更新集成事件订阅日志记录失败,事件标识不能为空.");
                return NullIntegrationEventLog.Instance;
            }
            var eventLog = await GetAsync(eventId, cancellationToken);
            return await SubscriptionSuccessAsync(eventLog, cancellationToken);
        }

        /// <summary>
        /// 集成事件订阅处理成功
        /// </summary>
        /// <param name="eventLog">集成事件日志记录</param>
        /// <param name="cancellationToken">取消令牌</param>
        public virtual async Task<IntegrationEventLog> SubscriptionSuccessAsync(IntegrationEventLog eventLog, CancellationToken cancellationToken = default)
        {
            if (Options.Pubsub.EnableEventLog == false)
                return NullIntegrationEventLog.Instance;
            eventLog.CheckNull(nameof(eventLog));
            var appId = GetAppId(eventLog.Id);
            var subscriptionLog = GetSubscriptionLog(eventLog, appId);
            if (subscriptionLog == null)
            {
                Log.LogWarning("更新集成事件订阅日志记录失败,未找到订阅日志记录,appId={appId},EventLog={@EventLog}", appId, ToDebugEventLog(eventLog));
                return NullIntegrationEventLog.Instance;
            }
            subscriptionLog.State = SubscriptionState.Success;
            subscriptionLog.LastModificationTime = Time.Now;
            eventLog.LastModificationTime = Time.Now;
            UpdateEventLogState(eventLog);
            try
            {
                await SaveAsync(eventLog, cancellationToken);
                Log.LogDebug("集成事件订阅处理成功,appId={appId},EventLog={@EventLog}", appId, ToDebugEventLog(eventLog));
            }
            catch (ConcurrencyException)
            {
                Log.LogDebug("更新集成事件订阅日志记录出现并发异常,即将重试,eventId={eventId},appId={appId}", eventLog.Id, appId);
                return await SubscriptionSuccessAsync(eventLog.Id, cancellationToken);
            }
            catch (Exception exception)
            {
                Log.LogError(exception, "更新集成事件订阅日志记录失败,appId={appId},EventLog={@EventLog}", appId, ToDebugEventLog(eventLog));
            }
            return eventLog;
        }

        /// <summary>
        /// 更新集成事件日志状态
        /// </summary>
        protected void UpdateEventLogState(IntegrationEventLog eventLog)
        {
            if (eventLog.SubscriptionLogs.All(t => t.State == SubscriptionState.Success))
            {
                eventLog.State = EventState.Success;
                return;
            }
            if (eventLog.SubscriptionLogs.Any(t => t.State == SubscriptionState.Processing))
            {
                eventLog.State = EventState.Processing;
                return;
            }
            eventLog.State = EventState.Fail;
        }

        #endregion

        #region SubscriptionFailAsync

        /// <summary>
        /// 集成事件订阅处理失败
        /// </summary>
        /// <param name="eventId">事件标识</param>
        /// <param name="message">消息</param>
        /// <param name="cancellationToken">取消令牌</param>
        public virtual async Task<IntegrationEventLog> SubscriptionFailAsync(string eventId, string message, CancellationToken cancellationToken = default)
        {
            if (Options.Pubsub.EnableEventLog == false)
                return NullIntegrationEventLog.Instance;
            if (eventId.IsEmpty())
            {
                Log.LogWarning("SubscriptionFailAsync更新集成事件订阅日志记录失败,事件标识不能为空.");
                return NullIntegrationEventLog.Instance;
            }
            var eventLog = await GetAsync(eventId, cancellationToken);
            return await SubscriptionFailAsync(eventLog, message, cancellationToken);
        }

        /// <summary>
        /// 集成事件订阅处理失败
        /// </summary>
        /// <param name="eventLog">集成事件日志记录</param>
        /// <param name="message">消息</param>
        /// <param name="cancellationToken">取消令牌</param>
        public virtual async Task<IntegrationEventLog> SubscriptionFailAsync(IntegrationEventLog eventLog, string message, CancellationToken cancellationToken = default)
        {
            if (Options.Pubsub.EnableEventLog == false)
                return NullIntegrationEventLog.Instance;
            eventLog.CheckNull(nameof(eventLog));
            var appId = GetAppId(eventLog.Id);
            var subscriptionLog = GetSubscriptionLog(eventLog, appId);
            if (subscriptionLog == null)
            {
                Log.LogWarning("更新集成事件订阅日志记录失败,未找到订阅日志记录,appId={appId},EventLog={@EventLog}", appId, ToDebugEventLog(eventLog));
                return NullIntegrationEventLog.Instance;
            }
            subscriptionLog.State = SubscriptionState.Fail;
            subscriptionLog.LastModificationTime = Time.Now;
            subscriptionLog.RetryLogs.Add(CreateSubscriptionRetryLog(subscriptionLog, message));
            eventLog.LastModificationTime = Time.Now;
            UpdateEventLogState(eventLog);
            try
            {
                await SaveAsync(eventLog, cancellationToken);
                Log.LogDebug("集成事件订阅处理失败,appId={appId},EventLog={@EventLog}", appId, ToDebugEventLog(eventLog));
            }
            catch (ConcurrencyException)
            {
                Log.LogDebug("更新集成事件订阅日志记录出现并发异常,即将重试,eventId={eventId},appId={appId}", eventLog.Id, appId);
                return await SubscriptionFailAsync(eventLog.Id, message, cancellationToken);
            }
            catch (Exception exception)
            {
                Log.LogError(exception, "更新集成事件订阅日志记录失败,appId={appId},EventLog={@EventLog}", appId, ToDebugEventLog(eventLog));
            }
            return eventLog;
        }

        /// <summary>
        /// 创建订阅重试记录
        /// </summary>
        protected SubscriptionRetryLog CreateSubscriptionRetryLog(SubscriptionLog subscriptionLog, string message)
        {
            var retryLog = subscriptionLog.RetryLogs.MaxBy(t => t.Number);
            var maxNumber = retryLog?.Number ?? 0;
            return new SubscriptionRetryLog { Number = maxNumber + 1, Message = message };
        }

        #endregion
    }

    /// <summary>
    /// 空发布订阅回调操作
    /// </summary>
    [Ioc(-9)]
    public class NullPubsubCallback : IPubsubCallback
    {
        /// <summary>
        /// 空发布订阅回调操作实例
        /// </summary>
        public static readonly IPubsubCallback Instance = new NullPubsubCallback();

        /// <inheritdoc />
        public Task OnPublishBefore(PubsubArgument argument, CancellationToken cancellationToken = default)
        {
            return Task.CompletedTask;
        }

        /// <inheritdoc />
        public Task OnPublishAfter(PubsubArgument argument, CancellationToken cancellationToken = default)
        {
            return Task.CompletedTask;
        }

        /// <inheritdoc />
        public Task OnSubscriptionBefore(IntegrationEventLog integrationEventLog, string routeUrl, CancellationToken cancellationToken = default)
        {
            return Task.CompletedTask;
        }

        /// <inheritdoc />
        public Task OnSubscriptionAfter(string eventId, bool isSuccess, string message, CancellationToken cancellationToken = default)
        {
            return Task.CompletedTask;
        }

        /// <inheritdoc />
        public Task OnRepublishBefore(IntegrationEventLog eventLog, CancellationToken cancellationToken = default)
        {
            return Task.CompletedTask;
        }

        /// <inheritdoc />
        public Task OnRepublishAfter(IntegrationEventLog eventLog, CancellationToken cancellationToken = default)
        {
            return Task.CompletedTask;
        }
    }

    /// <summary>
    /// Dapr发布订阅结果
    /// </summary>
    public class PubsubResult : JsonResult
    {
        /// <summary>
        /// 状态
        /// </summary>
        public string Status { get; }

        /// <summary>
        /// 消息
        /// </summary>
        public string Message { get; }

        /// <summary>
        /// 初始化发布订阅结果
        /// </summary>
        /// <param name="status">状态</param>
        /// <param name="message">消息</param>
        public PubsubResult(string status, string message = null) : base(null)
        {
            Status = status;
            Message = message;
            SerializerSettings = GetOptions();
        }

        /// <summary>
        /// 获取Json序列化配置
        /// </summary>
        private JsonSerializerOptions GetOptions()
        {
            return new JsonSerializerOptions
            {
                PropertyNamingPolicy = JsonNamingPolicy.CamelCase
            };
        }

        /// <summary>
        /// 执行结果
        /// </summary>
        public override Task ExecuteResultAsync(ActionContext context)
        {
            Value = new { Status };
            return base.ExecuteResultAsync(context);
        }

        /// <summary>
        /// 成功
        /// </summary>
        public static readonly PubsubResult Success = new("SUCCESS");

        /// <summary>
        /// 失败并重试
        /// </summary>
        /// <param name="message">错误消息</param>
        public static PubsubResult Fail(string message)
        {
            return new PubsubResult("RETRY", message);
        }

        /// <summary>
        /// 失败并删除消息
        /// </summary>
        /// <param name="message">错误消息</param>
        public static PubsubResult Drop(string message)
        {
            return new PubsubResult("DROP", message);
        }
    }

    /// <summary>
    /// 事件主题
    /// </summary>
    [AttributeUsage(AttributeTargets.All, AllowMultiple = true)]
    public class TopicAttribute : Topic
    {
        /// <summary>
        /// 初始化事件主题
        /// </summary>
        /// <param name="name">事件主题</param>
        public TopicAttribute(string name) : base("pubsub", name)
        {
        }

        /// <summary>
        /// 初始化事件主题
        /// </summary>
        /// <param name="pubsubName">发布订阅组件名称</param>
        /// <param name="name">事件主题</param>
        public TopicAttribute(string pubsubName, string name) : base(pubsubName, name)
        {
        }

        /// <summary>
        /// 初始化事件主题
        /// </summary>
        /// <param name="pubsubName">发布订阅组件名称</param>
        /// <param name="name">事件主题</param>
        /// <param name="match">匹配规则,范例: "event.type ==\"v1\""</param>
        /// <param name="priority">匹配优先级</param>
        public TopicAttribute(string pubsubName, string name, string match, int priority) : base(pubsubName, name, match, priority)
        {
        }
    }

    #endregion

    #region ServiceInvocations

    /// <summary>
    /// Dapr WebApi服务调用操作
    /// </summary>
    public class DaprServiceInvocation : DaprServiceInvocationBase<IServiceInvocation>, IServiceInvocation
    {

        #region 构造方法

        /// <summary>
        /// 初始化Dapr WebApi服务调用操作
        /// </summary>
        /// <param name="client">Dapr客户端</param>
        /// <param name="options">Dapr配置</param>
        /// <param name="loggerFactory">日志工厂</param>
        public DaprServiceInvocation(DaprClient client, IOptions<DaprOptions> options, ILoggerFactory loggerFactory) : base(client, options, loggerFactory)
        {
        }

        #endregion

        #region 事件

        /// <summary>
        /// 调用前事件
        /// </summary>
        protected Func<HttpRequestMessage, bool> OnBeforeAction { get; set; }
        /// <summary>
        /// 响应结果转换事件
        /// </summary>
        protected Func<HttpResponseMessage, JsonSerializerOptions, CancellationToken, Task<object>> OnResultAction { get; set; }
        /// <summary>
        /// 调用后事件
        /// </summary>
        protected Action<HttpResponseMessage> OnAfterAction { get; set; }
        /// <summary>
        /// 调用成功事件
        /// </summary>
        protected Func<HttpRequestMessage, HttpResponseMessage, object, Task> OnSuccessAction { get; set; }
        /// <summary>
        /// 调用失败事件
        /// </summary>
        protected Func<HttpRequestMessage, HttpResponseMessage, Exception, Task> OnFailAction { get; set; }
        /// <summary>
        /// 调用未授权事件
        /// </summary>
        protected Func<HttpRequestMessage, HttpResponseMessage, Task> OnUnauthorizedAction { get; set; }
        /// <summary>
        /// 调用完成事件
        /// </summary>
        protected Func<HttpRequestMessage, HttpResponseMessage, Task> OnCompleteAction { get; set; }

        /// <inheritdoc />
        public IServiceInvocation OnBefore(Func<HttpRequestMessage, bool> action)
        {
            OnBeforeAction = action;
            return this;
        }

        /// <summary>
        /// 响应结果转换事件
        /// </summary>
        /// <param name="action">响应结果转换操作</param>
        public IServiceInvocation OnResult(Func<HttpResponseMessage, JsonSerializerOptions, CancellationToken, Task<object>> action)
        {
            OnResultAction = action;
            return this;
        }

        /// <summary>
        /// 调用后事件
        /// </summary>
        /// <param name="action">调用后处理操作</param>
        public IServiceInvocation OnAfter(Action<HttpResponseMessage> action)
        {
            OnAfterAction = action;
            return this;
        }

        /// <inheritdoc />
        public IServiceInvocation OnSuccess<TResponse>(Func<HttpRequestMessage, HttpResponseMessage, TResponse, Task> action)
        {
            if (action != null)
                OnSuccessAction = (request, response, result) => action(request, response, (TResponse)result);
            return this;
        }

        /// <summary>
        /// 调用失败事件
        /// </summary>
        /// <param name="action">调用失败处理操作</param>
        public IServiceInvocation OnFail(Func<HttpRequestMessage, HttpResponseMessage, Exception, Task> action)
        {
            OnFailAction = action;
            return this;
        }

        /// <summary>
        /// 调用未授权事件
        /// </summary>
        /// <param name="action">调用未授权处理操作</param>
        public IServiceInvocation OnUnauthorized(Func<HttpRequestMessage, HttpResponseMessage, Task> action)
        {
            OnUnauthorizedAction = action;
            return this;
        }

        /// <summary>
        /// 调用完成事件
        /// </summary>
        /// <param name="action">调用完成处理操作</param>
        public IServiceInvocation OnComplete(Func<HttpRequestMessage, HttpResponseMessage, Task> action)
        {
            OnCompleteAction = action;
            return this;
        }

        #endregion

        #region 方法调用重载 

        /// <inheritdoc />
        public async Task InvokeAsync(string methodName, CancellationToken cancellationToken = default)
        {
            await InvokeAsync(methodName, HttpMethod.Get, cancellationToken);
        }

        /// <inheritdoc />
        public async Task InvokeAsync(string methodName, HttpMethod httpMethod, CancellationToken cancellationToken = default)
        {
            await InvokeAsync<object, object>(methodName, null, httpMethod, cancellationToken);
        }

        /// <inheritdoc />
        public async Task InvokeAsync(string methodName, object data, CancellationToken cancellationToken = default)
        {
            await InvokeAsync(methodName, data, HttpMethod.Post, cancellationToken);
        }

        /// <inheritdoc />
        public async Task InvokeAsync(string methodName, object data, HttpMethod httpMethod, CancellationToken cancellationToken = default)
        {
            await InvokeAsync<object, object>(methodName, data, httpMethod, cancellationToken);
        }

        /// <inheritdoc />
        public async Task<TResponse> InvokeAsync<TResponse>(string methodName, CancellationToken cancellationToken = default)
        {
            return await InvokeAsync<TResponse>(methodName, HttpMethod.Get, cancellationToken);
        }

        /// <inheritdoc />
        public async Task<TResponse> InvokeAsync<TResponse>(string methodName, HttpMethod httpMethod, CancellationToken cancellationToken = default)
        {
            return await InvokeAsync<TResponse>(methodName, null, httpMethod, cancellationToken);
        }

        /// <inheritdoc />
        public async Task<TResponse> InvokeAsync<TResponse>(string methodName, object data, CancellationToken cancellationToken = default)
        {
            return await InvokeAsync<TResponse>(methodName, data, HttpMethod.Get, cancellationToken);
        }

        /// <inheritdoc />
        public async Task<TResponse> InvokeAsync<TResponse>(string methodName, object data, HttpMethod httpMethod, CancellationToken cancellationToken = default)
        {
            return await InvokeAsync<object, TResponse>(methodName, data, httpMethod, cancellationToken);
        }

        /// <inheritdoc />
        public async Task<TResponse> InvokeAsync<TRequest, TResponse>(string methodName, TRequest data, CancellationToken cancellationToken = default)
        {
            return await InvokeAsync<TRequest, TResponse>(methodName, data, HttpMethod.Get, cancellationToken);
        }

        #endregion

        #region InvokeAsync

        /// <inheritdoc />
        public async Task<TResponse> InvokeAsync<TRequest, TResponse>(string methodName, TRequest data, HttpMethod httpMethod, CancellationToken cancellationToken = default)
        {
            Log.LogTrace("准备调用服务方法,AppId:{AppId},MethodName:{MethodName}", AppId, methodName);
            var request = CreateRequest(methodName, data, httpMethod);
            request = FilterRequest(request);
            if (await InvokeBefore(methodName, data, httpMethod, request) == false)
                return default;
            HttpResponseMessage response = null;
            try
            {
                response = await Client.InvokeMethodWithResponseAsync(request, cancellationToken);
                response = FilterResponse(response);
                OnAfterAction?.Invoke(response);
                var result = await ToResult<TResponse>(response, cancellationToken);
                await InvokeAfter(methodName, data, httpMethod, request, response, result);
                return result.Data;
            }
            catch (Warning)
            {
                throw;
            }
            catch (Exception exception)
            {
                await FailHandlerAsync(methodName, data, httpMethod, request, response, exception, null);
            }
            finally
            {
                await CompleteHandlerAsync(methodName, data, httpMethod, request, response);
            }
            return default;
        }

        #endregion

        #region CreateRequest

        /// <summary>
        /// 创建请求消息
        /// </summary>
        protected virtual HttpRequestMessage CreateRequest<TRequest>(string methodName, TRequest data, HttpMethod httpMethod)
        {
            var result = CreateInvokeMethodRequest(methodName, data, httpMethod);
            AddHeaders(result, methodName);
            return result;
        }

        /// <summary>
        /// 创建请求消息
        /// </summary>
        private HttpRequestMessage CreateInvokeMethodRequest<TRequest>(string methodName, TRequest data, HttpMethod httpMethod)
        {
            methodName = GetMethodName(methodName);
            methodName = GetMethodNameWithQueryString(methodName, data, httpMethod);
            if (data == null || httpMethod == HttpMethod.Get)
                return Client.CreateInvokeMethodRequest(httpMethod, AppId, methodName);
            return Client.CreateInvokeMethodRequest(httpMethod, AppId, methodName, data);
        }

        /// <summary>
        /// 获取方法名
        /// </summary>
        /// <param name="methodName">方法名</param>
        protected virtual string GetMethodName(string methodName)
        {
            if (methodName.IsEmpty())
                return string.Empty;
            if (methodName.StartsWith("/"))
                return methodName;
            return $"/api/{methodName}";
        }

        /// <summary>
        /// 获取带查询字符串的方法名
        /// </summary>
        protected virtual string GetMethodNameWithQueryString<TRequest>(string methodName, TRequest data, HttpMethod httpMethod)
        {
            if (httpMethod != HttpMethod.Get)
                return methodName;
            if (data == null)
                return methodName;
            return QueryHelpers.AddQueryString(methodName, ToDictionary(data));
        }

        /// <summary>
        /// 对象转换为字典
        /// </summary>
        /// <param name="data">对象</param>
        protected IDictionary<string, string> ToDictionary(object data)
        {
            var result = Util.Helpers.Convert.ToDictionary(data);
            return result.Where(t => t.Value != null).ToDictionary(t => t.Key, t => t.Value.SafeString());
        }

        /// <summary>
        /// 添加请求头
        /// </summary>
        protected virtual void AddHeaders(HttpRequestMessage message, string methodName)
        {
            RemoveHeaders();
            var headers = GetHeaders();
            foreach (var key in headers.Keys)
            {
                bool? success = message.Headers.TryAddWithoutValidation(key, headers[key].ToArray());
                if (success.SafeValue())
                    continue;
                message.Content ??= new StringContent(string.Empty);
                success = message.Content.Headers.TryAddWithoutValidation(key, headers[key].ToArray());
                if (success.SafeValue())
                    continue;
                Log.LogWarning("添加请求头失败,Key:{RequestHeaderKey},AppId:{AppId},MethodName:{MethodName}", key, AppId, methodName);
            }
        }

        /// <summary>
        /// 移除请求头
        /// </summary>
        private void RemoveHeaders()
        {
            foreach (var key in RemoveHeaderKeys)
            {
                Headers.Remove(key);
                ImportHeaderKeys.Remove(key);
                Options.ServiceInvocation.ImportHeaderKeys.Remove(key);
            }
        }

        /// <summary>
        /// 获取请求头
        /// </summary>
        private IDictionary<string, StringValues> GetHeaders()
        {
            var result = GetImportHeaders();
            foreach (var key in Headers.Keys)
            {
                if (result.ContainsKey(key))
                    result.Remove(key);
                result.Add(key, Headers[key]);
            }
            return result;
        }

        /// <summary>
        /// 获取导入的请求头
        /// </summary>
        private IDictionary<string, StringValues> GetImportHeaders()
        {
            var result = new Dictionary<string, StringValues>();
            ImportHeaderKeys.AddRange(Options.ServiceInvocation.ImportHeaderKeys);
            if (ImportHeaderKeys.Count == 0)
                return result;
            var headers = Util.Helpers.Web.Request?.Headers;
            if (headers == null)
                return result;
            foreach (var key in ImportHeaderKeys.Distinct())
            {
                if (headers.TryGetValue(key, out var value))
                    result.Add(key, value);
            }
            return result;
        }

        #endregion

        #region InvokeBefore

        /// <summary>
        /// 调用前操作
        /// </summary>
        protected async Task<bool> InvokeBefore(string methodName, object data, HttpMethod httpMethod, HttpRequestMessage message)
        {
            if (Options?.ServiceInvocation?.OnBefore != null)
                await Options.ServiceInvocation.OnBefore(new ServiceInvocationArgument(AppId, methodName, httpMethod, data, message));
            if (OnBeforeAction == null)
                return true;
            return OnBeforeAction(message);
        }

        #endregion

        #region FilterRequest

        /// <summary>
        /// 过滤请求
        /// </summary>
        /// <param name="request">请求消息</param>
        protected virtual HttpRequestMessage FilterRequest(HttpRequestMessage request)
        {
            var context = new RequestContext(request, Util.Helpers.Web.HttpContext);
            var requestFilters = Options?.ServiceInvocation?.RequestFilters;
            if (requestFilters == null || requestFilters.Count == 0)
                return request;
            foreach (var filter in requestFilters.Where(t => t is { Enabled: true }).OrderBy(t => t.Order))
                filter.Handle(context);
            return context.RequestMessage;
        }

        #endregion

        #region FilterResponse

        /// <summary>
        /// 过滤响应
        /// </summary>
        /// <param name="response">响应消息</param>
        protected virtual HttpResponseMessage FilterResponse(HttpResponseMessage response)
        {
            var context = new ResponseContext(response, Util.Helpers.Web.HttpContext);
            var responseFilters = Options?.ServiceInvocation?.ResponseFilters;
            if (responseFilters == null || responseFilters.Count == 0)
                return response;
            foreach (var filter in responseFilters.Where(t => t is { Enabled: true }).OrderBy(t => t.Order))
                filter.Handle(context);
            return context.ResponseMessage;
        }

        #endregion

        #region ToResult

        /// <summary>
        /// 转换结果
        /// </summary>
        /// <param name="response">响应消息</param>
        /// <param name="cancellationToken">取消令牌</param>
        protected virtual async Task<ServiceResult<TResponse>> ToResult<TResponse>(HttpResponseMessage response, CancellationToken cancellationToken)
        {
            if (IsUnpackResult)
                return await ToUnpackResult<TResponse>(response, cancellationToken);
            return await ToNotUnpackResult<TResponse>(response, cancellationToken);
        }

        /// <summary>
        /// 转换结果 - 使用ServiceResult解包
        /// </summary>
        /// <param name="response">响应消息</param>
        /// <param name="cancellationToken">取消令牌</param>
        protected virtual async Task<ServiceResult<TResponse>> ToUnpackResult<TResponse>(HttpResponseMessage response, CancellationToken cancellationToken)
        {
            response.EnsureSuccessStatusCode();
            if (OnResultAction == null)
                return await response.Content.ReadFromJsonAsync<ServiceResult<TResponse>>(Client.JsonSerializerOptions, cancellationToken);
            var objResult = await OnResultAction(response, Client.JsonSerializerOptions, cancellationToken);
            var result = objResult as ServiceResult<TResponse>;
            result!.CheckNull(nameof(result));
            return result;
        }

        /// <summary>
        /// 转换结果 - 不解包
        /// </summary>
        /// <param name="response">响应消息</param>
        /// <param name="cancellationToken">取消令牌</param>
        protected virtual async Task<ServiceResult<TResponse>> ToNotUnpackResult<TResponse>(HttpResponseMessage response, CancellationToken cancellationToken)
        {
            var result = new ServiceResult<TResponse>
            {
                Code = GetNotUnpackStateCode(response)
            };
            if (result.Code != StateCode.Ok)
            {
                result.Message = await response.Content.ReadAsStringAsync(cancellationToken);
                return result;
            }
            if (OnResultAction == null)
            {
                var json = await response.Content.ReadAsStringAsync(cancellationToken);
                if (json.IsEmpty())
                    return result;
                result.Data = Util.Helpers.Json.ToObject<TResponse>(json, Client.JsonSerializerOptions);
                return result;
            }
            var content = await OnResultAction(response, Client.JsonSerializerOptions, cancellationToken);
            result.Data = Util.Helpers.Convert.To<TResponse>(content);
            return result;
        }

        /// <summary>
        /// 获取未解包结果的状态码
        /// </summary>
        protected virtual string GetNotUnpackStateCode(HttpResponseMessage response)
        {
            if (response.IsSuccessStatusCode)
                return StateCode.Ok;
            if (response.StatusCode == HttpStatusCode.Unauthorized || response.StatusCode == HttpStatusCode.Forbidden)
                return StateCode.Unauthorized;
            return StateCode.Fail;
        }

        #endregion

        #region InvokeAfter

        /// <summary>
        /// 调用方法后操作
        /// </summary>
        protected virtual async Task InvokeAfter<TResponse>(string methodName, object data, HttpMethod httpMethod, HttpRequestMessage request, HttpResponseMessage response, ServiceResult<TResponse> result)
        {
            var state = ToState(result);
            if (state == ServiceState.Ok)
            {
                await SuccessHandlerAsync(methodName, data, httpMethod, request, response, result.Data);
                return;
            }
            if (state == ServiceState.Fail)
            {
                await FailHandlerAsync(methodName, data, httpMethod, request, response, null, result?.Message);
                return;
            }
            if (state == ServiceState.Unauthorized)
            {
                await UnauthorizedHandlerAsync(methodName, data, httpMethod, request, response);
                return;
            }
        }

        #endregion

        #region ToState

        /// <summary>
        /// 转换为服务状态
        /// </summary>
        protected virtual ServiceState ToState<TResponse>(ServiceResult<TResponse> result)
        {
            if (result == null)
                return ServiceState.Fail;
            if (OnStateAction != null)
                return OnStateAction(result.Code);
            switch (result.Code)
            {
                case StateCode.Ok:
                    return ServiceState.Ok;
                case StateCode.Unauthorized:
                    return ServiceState.Unauthorized;
                default:
                    return ServiceState.Fail;
            }
        }

        #endregion

        #region SuccessHandlerAsync

        /// <summary>
        /// 成功处理操作
        /// </summary>
        protected virtual async Task SuccessHandlerAsync<TResponse>(string methodName, object data, HttpMethod httpMethod, HttpRequestMessage request, HttpResponseMessage response, TResponse result)
        {
            Log.LogTrace("调用服务成功,AppId:{AppId},MethodName:{MethodName}", AppId, methodName);
            if (Options?.ServiceInvocation?.OnSuccess != null)
                await Options.ServiceInvocation.OnSuccess(new ServiceInvocationArgument(AppId, methodName, httpMethod, data, request, response, result));
            if (OnSuccessAction == null)
                return;
            await OnSuccessAction(request, response, result);
        }

        #endregion

        #region FailHandlerAsync

        /// <summary>
        /// 失败处理操作
        /// </summary>
        protected virtual async Task FailHandlerAsync(string methodName, object data, HttpMethod httpMethod, HttpRequestMessage request, HttpResponseMessage response, Exception exception, string message)
        {
            if (exception == null)
                Log.LogWarning("调用服务失败,AppId:{AppId},MethodName:{MethodName}", AppId, methodName);
            else
            {
                Log.LogError(exception, "调用服务失败,AppId:{AppId},MethodName:{MethodName}", AppId, methodName);
            }
            if (Options?.ServiceInvocation?.OnFail != null)
                await Options.ServiceInvocation.OnFail(new ServiceInvocationArgument(AppId, methodName, httpMethod, data, request, response, null, exception, message));
            if (OnFailAction != null)
            {
                await OnFailAction(request, response, exception);
                return;
            }
            if (exception != null)
                throw new InvocationException(AppId, methodName, exception, response);
            throw new Warning(message);
        }

        #endregion

        #region UnauthorizedHandlerAsync

        /// <summary>
        /// 未授权处理操作
        /// </summary>
        protected virtual async Task UnauthorizedHandlerAsync(string methodName, object data, HttpMethod httpMethod, HttpRequestMessage request, HttpResponseMessage response)
        {
            Log.LogWarning("调用未授权的服务,AppId:{AppId},MethodName:{MethodName}", AppId, methodName);
            if (Options?.ServiceInvocation?.OnUnauthorized != null)
                await Options.ServiceInvocation.OnUnauthorized(new ServiceInvocationArgument(AppId, methodName, httpMethod, data, request, response));
            if (OnUnauthorizedAction != null)
            {
                await OnUnauthorizedAction(request, response);
                return;
            }
            throw new Warning(R.UnauthorizedMessage, code: StateCode.Unauthorized);
        }

        #endregion

        #region CompleteHandlerAsync

        /// <summary>
        /// 调用完成操作
        /// </summary>
        protected virtual async Task CompleteHandlerAsync(string methodName, object data, HttpMethod httpMethod, HttpRequestMessage request, HttpResponseMessage response)
        {
            Log.LogTrace("调用服务完成,AppId:{AppId},MethodName:{MethodName}", AppId, methodName);
            if (Options?.ServiceInvocation?.OnComplete != null)
                await Options.ServiceInvocation.OnComplete(new ServiceInvocationArgument(AppId, methodName, httpMethod, data, request, response));
            if (OnCompleteAction == null)
                return;
            await OnCompleteAction(request, response);
        }

        #endregion
    }

    /// <summary>
    /// Dapr服务调用操作
    /// </summary>
    /// <typeparam name="TServiceInvocation">服务调用接口类型</typeparam>
    public abstract class DaprServiceInvocationBase<TServiceInvocation> : IServiceInvocationBase<TServiceInvocation> where TServiceInvocation : IServiceInvocationBase<TServiceInvocation>
    {
        /// <summary>
        /// Dapr客户端
        /// </summary>
        protected DaprClient Client { get; }
        /// <summary>
        /// 配置
        /// </summary>
        protected DaprOptions Options { get; }
        /// <summary>
        /// 日志
        /// </summary>
        protected ILogger Log { get; set; }
        /// <summary>
        /// 应用标识
        /// </summary>
        protected string AppId { get; set; }
        /// <summary>
        /// 是否对结果解包
        /// </summary>
        protected bool IsUnpackResult { get; set; }
        /// <summary>
        /// 请求头集合
        /// </summary>
        protected IDictionary<string, string> Headers { get; set; }
        /// <summary>
        /// 导入请求头键名集合
        /// </summary>
        protected List<string> ImportHeaderKeys { get; set; }
        /// <summary>
        /// 移除请求头键名集合
        /// </summary>
        protected IList<string> RemoveHeaderKeys { get; set; }
        /// <summary>
        /// 服务状态码转换事件
        /// </summary>
        protected Func<string, ServiceState> OnStateAction { get; set; }

        /// <summary>
        /// 初始化Dapr服务调用操作
        /// </summary>
        /// <param name="client">Dapr客户端</param>
        /// <param name="options">Dapr配置</param>
        /// <param name="loggerFactory">日志工厂</param>
        protected DaprServiceInvocationBase(DaprClient client, IOptions<DaprOptions> options, ILoggerFactory loggerFactory)
        {
            Client = client ?? throw new ArgumentNullException(nameof(client));
            Options = options?.Value ?? new DaprOptions();
            Log = loggerFactory?.CreateLogger(typeof(IServiceInvocation)) ?? NullLogger.Instance;
            Headers = new Dictionary<string, string>();
            ImportHeaderKeys = new List<string>();
            RemoveHeaderKeys = new List<string>();
            IsUnpackResult = Options.ServiceInvocation.IsUnpackResult;
        }

        /// <inheritdoc />
        public TServiceInvocation Service(string appId)
        {
            AppId = appId;
            return Return();
        }

        /// <summary>
        /// 返回
        /// </summary>
        private TServiceInvocation Return()
        {
            return (TServiceInvocation)(object)this;
        }

        /// <inheritdoc />
        public TServiceInvocation UnpackResult(bool isUnpack)
        {
            IsUnpackResult = isUnpack;
            return Return();
        }

        /// <inheritdoc />
        public TServiceInvocation BearerToken(string token)
        {
            Header("Authorization", $"Bearer {token}");
            return Return();
        }

        /// <inheritdoc />
        public TServiceInvocation Header(string key, string value)
        {
            if (key.IsEmpty())
                return Return();
            if (Headers.ContainsKey(key))
                Headers.Remove(key);
            Headers.Add(key, value);
            return Return();
        }

        /// <inheritdoc />
        public TServiceInvocation Header(IDictionary<string, string> headers)
        {
            if (headers == null)
                return Return();
            foreach (var header in headers)
                Header(header.Key, header.Value);
            return Return();
        }

        /// <inheritdoc />
        public TServiceInvocation ImportHeader(string key)
        {
            if (key.IsEmpty())
                return Return();
            if (ImportHeaderKeys.Contains(key) == false)
                ImportHeaderKeys.Add(key);
            return Return();
        }

        /// <inheritdoc />
        public TServiceInvocation ImportHeader(IEnumerable<string> keys)
        {
            if (keys == null)
                return Return();
            foreach (var key in keys)
                ImportHeader(key);
            return Return();
        }

        /// <inheritdoc />
        public TServiceInvocation RemoveHeader(string key)
        {
            if (key.IsEmpty())
                return Return();
            if (RemoveHeaderKeys.Contains(key) == false)
                RemoveHeaderKeys.Add(key);
            return Return();
        }

        /// <summary>
        /// 服务状态码转换事件
        /// </summary>
        /// <param name="action">转换为服务状态码,参数为业务状态码或Http状态码,取决于是否使用约定结果类型</param>
        public TServiceInvocation OnState(Func<string, ServiceState> action)
        {
            OnStateAction = action;
            return Return();
        }
    }

    /// <summary>
    /// WebApi服务调用请求过滤器
    /// </summary>
    public abstract class RequestFilterBase : IRequestFilter
    {
        /// <summary>
        /// 是否启用
        /// </summary>
        public bool Enabled => true;
        /// <summary>
        /// 序号
        /// </summary>
        public int Order => 0;
        /// <summary>
        /// 处理请求
        /// </summary>
        /// <param name="context">请求上下文</param>
        public abstract void Handle(RequestContext context);
    }

    /// <summary>
    /// WebApi服务调用响应过滤器
    /// </summary>
    public abstract class ResponseFilterBase : IResponseFilter
    {
        /// <summary>
        /// 是否启用
        /// </summary>
        public bool Enabled => true;
        /// <summary>
        /// 序号
        /// </summary>
        public int Order => 0;
        /// <summary>
        /// 处理响应
        /// </summary>
        /// <param name="context">响应上下文</param>
        public abstract void Handle(ResponseContext context);
    }

    /// <summary>
    /// 服务调用参数
    /// </summary>
    /// <param name="AppId">应用标识</param>
    /// <param name="MethodName">调用方法名称</param>
    /// <param name="HttpMethod">Http方法</param>
    /// <param name="RequestData">请求参数</param>
    /// <param name="RequestMessage">Http请求消息</param>
    /// <param name="ResponseMessage">Http响应消息</param>
    /// <param name="Result">响应结果</param>
    /// <param name="Exception">异常</param>
    /// <param name="Message">消息</param>
    public record ServiceInvocationArgument(
        string AppId,
        string MethodName,
        HttpMethod HttpMethod,
        object RequestData,
        HttpRequestMessage RequestMessage,
        HttpResponseMessage ResponseMessage = null,
        object Result = null,
        Exception Exception = null,
        string Message = null
    );

    #endregion

    #region StateManagements

    #region Queries
    /// <summary>
    /// And连接条件
    /// </summary>
    public class AndCondition : IStateCondition
    {
        /// <summary>
        /// 初始化And连接条件
        /// </summary>
        /// <param name="condition1">条件1</param>
        /// <param name="condition2">条件2</param>
        public AndCondition(IStateCondition condition1, IStateCondition condition2 = null)
        {
            if (condition1 == null && condition2 == null)
                return;
            And = new List<object>();
            AddCondition(condition1);
            AddCondition(condition2);
        }

        /// <summary>
        /// And连接条件
        /// </summary>
        [JsonPropertyName("AND")]
        public List<object> And { get; set; }

        /// <summary>
        /// 添加条件
        /// </summary>
        /// <param name="condition">条件</param>
        public void AddCondition(IStateCondition condition)
        {
            if (condition == null)
                return;
            if (condition is AndCondition andCondition)
            {
                foreach (var item in andCondition.And)
                {
                    And.Add(item);
                }
                return;
            }
            And.Add(condition);
        }
    }

    /// <summary>
    /// 状态对象相等查询条件
    /// </summary>
    public class EqualCondition : IStateCondition
    {
        /// <summary>
        /// 初始化状态对象相等查询条件
        /// </summary>
        /// <param name="property">属性名</param>
        /// <param name="value">属性值</param>
        public EqualCondition(string property, object value)
        {
            if (property.IsEmpty())
                return;
            Equal = new Dictionary<string, object> { { property, value } };
        }

        /// <summary>
        /// 相等操作
        /// </summary>
        [JsonPropertyName("EQ")]
        public Dictionary<string, object> Equal { get; set; }
    }

    /// <summary>
    /// 状态对象In查询条件
    /// </summary>
    public class InCondition : IStateCondition
    {
        /// <summary>
        /// 初始化状态对象In查询条件
        /// </summary>
        /// <param name="property">属性名</param>
        /// <param name="values">属性值</param>
        public InCondition(string property, IEnumerable<object> values)
        {
            if (property.IsEmpty())
                return;
            In = new Dictionary<string, IEnumerable<object>> { { property, values } };
        }

        /// <summary>
        /// In操作
        /// </summary>
        [JsonPropertyName("IN")]
        public Dictionary<string, IEnumerable<object>> In { get; set; }
    }

    /// <summary>
    /// Or连接条件
    /// </summary>
    public class OrCondition : IStateCondition
    {
        /// <summary>
        /// 初始化Or连接条件
        /// </summary>
        /// <param name="condition1">条件1</param>
        /// <param name="condition2">条件2</param>
        public OrCondition(IStateCondition condition1, IStateCondition condition2 = null)
        {
            if (condition1 == null && condition2 == null)
                return;
            Or = new List<object>();
            AddCondition(condition1);
            AddCondition(condition2);
        }

        /// <summary>
        /// Or连接条件
        /// </summary>
        [JsonPropertyName("OR")]
        public List<object> Or { get; set; }

        /// <summary>
        /// 添加条件
        /// </summary>
        /// <param name="condition">条件</param>
        public void AddCondition(IStateCondition condition)
        {
            if (condition == null)
                return;
            if (condition is OrCondition orCondition)
            {
                foreach (var item in orCondition.Or)
                {
                    Or.Add(item);
                }
                return;
            }
            Or.Add(condition);
        }
    }

    /// <summary>
    /// 排序项
    /// </summary>
    public class OrderByItem
    {
        /// <summary>
        /// 初始化排序项
        /// </summary>
        /// <param name="order">排序表达式</param>
        public OrderByItem(string order)
        {
            Key = order.SafeString().Trim();
            if (Key.EndsWith(" Asc", StringComparison.OrdinalIgnoreCase))
            {
                Key = Key.Substring(0, Key.Length - 3).Trim();
                return;
            }
            if (Key.EndsWith(" Desc", StringComparison.OrdinalIgnoreCase))
            {
                Order = "DESC";
                Key = Key.Substring(0, Key.Length - 4).Trim();
            }
        }

        /// <summary>
        /// 排序属性
        /// </summary>
        [JsonPropertyName("key")]
        public string Key { get; }

        /// <summary>
        /// 排序方向,可选值: ASC,DESC
        /// </summary>
        [JsonPropertyName("order")]
        public string Order { get; }
    }

    /// <summary>
    /// 状态过滤器
    /// </summary>
    public class StateFilter
    {
        /// <summary>
        /// 过滤条件
        /// </summary>
        private IStateCondition _condition;

        /// <summary>
        /// 获取过滤条件
        /// </summary>
        public object GetCondition()
        {
            return _condition;
        }

        /// <summary>
        /// 清理
        /// </summary>
        public StateFilter Clear()
        {
            _condition = null;
            return this;
        }

        /// <summary>
        /// 相等条件
        /// </summary>
        /// <param name="property">属性名</param>
        /// <param name="value">属性值</param>
        public StateFilter Equal(string property, object value)
        {
            _condition = _condition.And(new EqualCondition(property, value));
            return this;
        }

        /// <summary>
        /// In条件
        /// </summary>
        /// <param name="property">属性名</param>
        /// <param name="values">属性值</param>
        public StateFilter In(string property, IEnumerable<object> values)
        {
            _condition = _condition.And(new InCondition(property, values));
            return this;
        }

        /// <summary>
        /// And连接
        /// </summary>
        /// <param name="condition">查询条件</param>
        public StateFilter And(IStateCondition condition)
        {
            _condition = _condition.And(condition);
            return this;
        }

        /// <summary>
        /// Or连接
        /// </summary>
        /// <param name="condition">查询条件</param>
        public StateFilter Or(IStateCondition condition)
        {
            _condition = _condition.Or(condition);
            return this;
        }

        /// <summary>
        /// 相等条件
        /// </summary>
        /// <param name="expression">属性名表达式</param>
        /// <param name="value">属性值</param>
        public StateFilter Equal<T>(Expression<Func<T, object>> expression, object value)
        {
            return Equal(StateQueryHelper.GetProperty(expression), value);
        }

        /// <summary>
        /// In条件
        /// </summary>
        /// <param name="expression">属性名表达式</param>
        /// <param name="values">属性值</param>
        public StateFilter In<T>(Expression<Func<T, object>> expression, IEnumerable<object> values)
        {
            return In(StateQueryHelper.GetProperty(expression), values);
        }
    }

    /// <summary>
    /// 状态分页
    /// </summary>
    public class StatePage
    {
        /// <summary>
        /// 分页大小,相对于PageSize
        /// </summary>
        [JsonPropertyName("limit")]
        public int? Limit { get; set; }

        /// <summary>
        /// 迭代令牌
        /// </summary>
        [JsonPropertyName("token")]
        public string Token { get; set; }
    }

    /// <summary>
    /// 状态查询对象
    /// </summary>
    public class StateQuery
    {
        /// <summary>
        /// 过滤条件
        /// </summary>
        [JsonPropertyName("filter")]
        public object Filter { get; set; }
        /// <summary>
        /// 排序条件
        /// </summary>
        [JsonPropertyName("sort")]
        public StateSort Sort { get; set; }
        /// <summary>
        /// 分页条件
        /// </summary>
        [JsonPropertyName("page")]
        public StatePage Page { get; set; }
    }

    /// <summary>
    /// 状态查询辅助操作
    /// </summary>
    public static class StateQueryHelper
    {
        /// <summary>
        /// 获取属性名
        /// </summary>
        public static string GetProperty<T>(Expression<Func<T, object>> expression)
        {
            var property = Lambda.GetName(expression);
            return property.IsEmpty() ? null : property.Split('.').Select(Util.Helpers.String.FirstLowerCase).Join(separator: ".");
        }
    }

    /// <summary>
    /// 状态排序
    /// </summary>
    public class StateSort : List<OrderByItem>
    {
        /// <summary>
        /// 添加升序排序属性
        /// </summary>
        /// <param name="property">升序排序属性</param>
        public void OrderBy(string property)
        {
            Add(property);
        }

        /// <summary>
        /// 添加降序排序属性
        /// </summary>
        /// <param name="property">降序排序属性</param>
        public void OrderByDescending(string property)
        {
            Add($"{property} DESC");
        }

        /// <summary>
        /// 添加排序条件
        /// </summary>
        /// <param name="orderBy">排序条件</param>
        public void Add(string orderBy)
        {
            if (orderBy.IsEmpty())
                return;
            var items = orderBy.Split(",");
            foreach (var item in items)
            {
                Add(new OrderByItem(item));
            }
        }

        /// <summary>
        /// 添加升序排序属性
        /// </summary>
        /// <param name="expression">属性表达式</param>
        public void OrderBy<T>(Expression<Func<T, object>> expression)
        {
            OrderBy(StateQueryHelper.GetProperty(expression));
        }

        /// <summary>
        /// 添加降序排序属性
        /// </summary>
        /// <param name="expression">属性表达式</param>
        public void OrderByDescending<T>(Expression<Func<T, object>> expression)
        {
            OrderByDescending(StateQueryHelper.GetProperty(expression));
        }
    }

    #endregion

    /// <summary>
    /// Dapr状态管理
    /// </summary>
    public class DaprStateManager : DaprStateManagerBase<IStateManager>, IStateManager
    {
        /// <summary>
        /// 初始化Dapr状态管理
        /// </summary>
        /// <param name="client">Dapr客户端</param>
        /// <param name="options">Dapr配置</param>
        /// <param name="loggerFactory">日志工厂</param>
        /// <param name="keyGenerator">状态存储键生成器</param>
        public DaprStateManager(DaprClient client, IOptions<DaprOptions> options, ILoggerFactory loggerFactory, IKeyGenerator keyGenerator)
            : base(client, options, loggerFactory, keyGenerator)
        {
        }

        /// <inheritdoc />
        public IStateManager OrderBy<T>(Expression<Func<T, object>> expression)
        {
            Sort.OrderBy(expression);
            return this;
        }

        /// <inheritdoc />
        public IStateManager OrderByDescending<T>(Expression<Func<T, object>> expression)
        {
            Sort.OrderByDescending(expression);
            return this;
        }

        /// <inheritdoc />
        public IStateManager Equal<T>(Expression<Func<T, object>> expression, object value)
        {
            Filter.Equal(expression, value);
            return this;
        }

        /// <inheritdoc />
        public IStateManager In<T>(Expression<Func<T, object>> expression, IEnumerable<object> values)
        {
            Filter.In(expression, values);
            return this;
        }

        /// <inheritdoc />
        public IStateManager In<T>(Expression<Func<T, object>> expression, params object[] values)
        {
            Filter.In(expression, values);
            return this;
        }
    }

    /// <summary>
    /// Dapr状态管理
    /// </summary>
    public partial class DaprStateManagerBase<TStateManager> : IStateManagerBase<TStateManager> where TStateManager : IStateManagerBase<TStateManager>
    {

        #region 字段

        /// <summary>
        /// Dapr客户端
        /// </summary>
        protected readonly DaprClient Client;
        /// <summary>
        /// 配置
        /// </summary>
        protected DaprOptions Options;
        /// <summary>
        /// 日志操作
        /// </summary>
        protected readonly ILogger Logger;
        /// <summary>
        /// 状态存储键生成器
        /// </summary>
        protected IKeyGenerator KeyGenerator;
        /// <summary>
        /// 元数据
        /// </summary>
        protected Dictionary<string, string> Metadatas;
        /// <summary>
        /// 一致性模式
        /// </summary>
        protected ConsistencyMode ConsistencyMode;
        /// <summary>
        /// 事务参数列表
        /// </summary>
        protected List<StateTransactionRequest> StateTransactionRequests;
        /// <summary>
        /// Json序列化配置
        /// </summary>
        protected JsonSerializerOptions SerializerOptions;
        /// <summary>
        /// 是否开启事务
        /// </summary>
        protected bool IsTransaction;
        /// <summary>
        /// 过滤条件
        /// </summary>
        protected StateFilter Filter;
        /// <summary>
        /// 排序条件
        /// </summary>
        protected StateSort Sort;
        /// <summary>
        /// 分页条件
        /// </summary>
        protected StatePage Page;
        /// <summary>
        /// 状态组件名称
        /// </summary>
        private string _storeName;

        #endregion

        #region 构造方法

        /// <summary>
        /// 初始化Dapr状态管理
        /// </summary>
        /// <param name="client">Dapr客户端</param>
        /// <param name="options">Dapr配置</param>
        /// <param name="loggerFactory">日志工厂</param>
        /// <param name="keyGenerator">状态存储键生成器</param>
        public DaprStateManagerBase(DaprClient client, IOptions<DaprOptions> options, ILoggerFactory loggerFactory, IKeyGenerator keyGenerator)
        {
            Client = client ?? throw new ArgumentNullException(nameof(client));
            Options = options?.Value ?? new DaprOptions();
            Logger = loggerFactory?.CreateLogger(typeof(DaprStateManager)) ?? NullLogger<DaprStateManager>.Instance;
            KeyGenerator = keyGenerator ?? throw new ArgumentNullException(nameof(keyGenerator));
            Metadatas = new Dictionary<string, string>();
            ConsistencyMode = ConsistencyMode.Eventual;
            StateTransactionRequests = new List<StateTransactionRequest>();
            Filter = new StateFilter();
            Sort = new StateSort();
            Page = new StatePage();
        }

        #endregion

        #region 辅助操作

        /// <summary>
        /// 返回
        /// </summary>
        private TStateManager Return()
        {
            return (TStateManager)(object)this;
        }

        /// <summary>
        /// 获取状态组件名称
        /// </summary>
        protected string GetStoreName()
        {
            return _storeName.IsEmpty() ? "statestore" : _storeName;
        }

        /// <summary>
        /// 获取存储键
        /// </summary>
        protected virtual string GetKey<TValue>(string key, TValue value) where TValue : IDataKey
        {
            if (key.IsEmpty() == false)
                return key;
            return KeyGenerator.CreateKey<TValue>(value.Id);
        }

        /// <summary>
        /// 是否实现IDataType接口
        /// </summary>
        protected bool IsDataType<TValue>()
        {
            return typeof(TValue).IsAssignableTo(typeof(IDataType));
        }

        /// <summary>
        /// 是否实现IDataKey接口
        /// </summary>
        protected bool IsDataKey<TValue>()
        {
            return typeof(TValue).IsAssignableTo(typeof(IDataKey));
        }

        /// <summary>
        /// 是否实现IETag接口
        /// </summary>
        protected bool IsETag<TValue>()
        {
            return typeof(TValue).IsAssignableTo(typeof(IETag));
        }

        /// <summary>
        /// 设置数据类型查询条件
        /// </summary>
        protected void SetDataTypeCondition<TValue>()
        {
            EqualIf("dataType", typeof(TValue).FullName, IsDataType<TValue>());
        }

        #endregion

        #region StoreName

        /// <inheritdoc />
        public TStateManager StoreName(string storeName)
        {
            _storeName = storeName;
            return Return();
        }

        #endregion

        #region Clear

        /// <inheritdoc />
        public TStateManager Clear()
        {
            Metadatas.Clear();
            ConsistencyMode = ConsistencyMode.Eventual;
            StateTransactionRequests.Clear();
            IsTransaction = false;
            ClearQuery();
            return Return();
        }

        /// <summary>
        /// 清理查询条件
        /// </summary>
        protected void ClearQuery()
        {
            Filter.Clear();
            Sort.Clear();
            Page = new StatePage();
        }

        #endregion

        #region BeginTransaction

        /// <inheritdoc />
        public TStateManager BeginTransaction()
        {
            IsTransaction = true;
            return Return();
        }

        #endregion

        #region JsonSerializerOptions

        /// <inheritdoc />
        public TStateManager JsonSerializerOptions(JsonSerializerOptions options)
        {
            SerializerOptions = options;
            return Return();
        }

        #endregion

        #region Metadata

        /// <summary>
        /// 设置元数据
        /// </summary>
        /// <param name="key">键</param>
        /// <param name="value">值</param>
        public TStateManager Metadata(string key, string value)
        {
            if (key.IsEmpty())
                return Return();
            if (value.IsEmpty())
                return Return();
            RemoveMetadata(key);
            Metadatas.Add(key, value);
            return Return();
        }

        /// <summary>
        /// 设置元数据
        /// </summary>
        /// <param name="metadata">元数据键值对集合</param>
        public TStateManager Metadata(IDictionary<string, string> metadata)
        {
            if (metadata == null)
                return Return();
            foreach (var item in metadata)
                Metadata(item.Key, item.Value);
            return Return();
        }

        #endregion

        #region RemoveMetadata

        /// <summary>
        /// 移除元数据
        /// </summary>
        /// <param name="key">键</param>
        public TStateManager RemoveMetadata(string key)
        {
            if (key.IsEmpty())
                return Return();
            if (Metadatas.ContainsKey(key))
                Metadatas.Remove(key);
            return Return();
        }

        #endregion

        #region ContentType

        /// <inheritdoc />
        public TStateManager ContentType(string type)
        {
            Metadata("contentType", type);
            return Return();
        }

        #endregion

        #region JsonType

        /// <summary>
        /// 设置contentType为application/json
        /// </summary>
        public TStateManager JsonType()
        {
            return ContentType("application/json");
        }

        #endregion

        #region AddAsync

        /// <inheritdoc />
        public virtual async Task AddAsync<TValue>(string key, TValue value, CancellationToken cancellationToken = default)
        {
            if (key.IsEmpty())
                throw new ArgumentNullException(nameof(key));
            InitAdd(value);
            if (IsTransaction == false)
            {
                await Client.SaveStateAsync(GetStoreName(), key, value, CreateStateOptions(), Metadatas, cancellationToken);
                Clear();
                return;
            }
            var request = new StateTransactionRequest(key, ToBytes(value), StateOperationType.Upsert, null, Metadatas, CreateStateOptions());
            StateTransactionRequests.Add(request);
        }

        /// <summary>
        /// 初始化新增
        /// </summary>
        protected virtual void InitAdd<TValue>(TValue value)
        {
            InitId(value);
            InitDataType(value);
            InitJsonType<TValue>();
        }

        /// <summary>
        /// 初始化标识
        /// </summary>
        protected virtual void InitId<TValue>(TValue value)
        {
            if (value is not IDataKey data)
                return;
            if (data.Id.IsEmpty())
                data.Id = Guid.NewGuid().ToString();
        }

        /// <summary>
        /// 初始化数据类型
        /// </summary>
        protected virtual void InitDataType<TValue>(TValue value)
        {
            if (value is IDataType dataType)
                dataType.DataType = typeof(TValue).FullName;
        }

        /// <summary>
        /// 初始化Json内容类型
        /// </summary>
        protected virtual void InitJsonType<TValue>()
        {
            var type = typeof(TValue);
            if (type == typeof(string))
                return;
            JsonType();
        }

        /// <summary>
        /// 创建状态配置
        /// </summary>
        protected StateOptions CreateStateOptions()
        {
            return new StateOptions
            {
                Consistency = ConsistencyMode,
                Concurrency = ConcurrencyMode.FirstWrite
            };
        }

        /// <summary>
        /// 转换为字节数组
        /// </summary>
        protected virtual byte[] ToBytes<TValue>(TValue value)
        {
            return Json.ToBytes(value, SerializerOptions);
        }

        #endregion

        #region UpdateAsync

        /// <inheritdoc />
        public async Task<bool> UpdateAsync<TValue>(string key, TValue value, string etag, CancellationToken cancellationToken = default)
        {
            if (key.IsEmpty())
                throw new ArgumentNullException(nameof(key));
            InitJsonType<TValue>();
            if (IsTransaction == false)
            {
                try
                {
                    var result = await Client.TrySaveStateAsync(GetStoreName(), key, value, etag, CreateStateOptions(), Metadatas, cancellationToken);
                    Clear();
                    return result;
                }
                catch (DaprException ex)
                {
                    Clear();
                    var exception = ex.InnerException;
                    if (exception != null && exception.Message.Contains("E11000"))
                        return false;
                    throw;
                }
            }
            var request = new StateTransactionRequest(key, ToBytes(value), StateOperationType.Upsert, etag, Metadatas, CreateStateOptions());
            StateTransactionRequests.Add(request);
            return true;
        }

        #endregion

        #region RemoveAsync

        /// <inheritdoc />
        public async Task RemoveAsync(string key, CancellationToken cancellationToken = default)
        {
            if (key.IsEmpty())
                throw new ArgumentNullException(nameof(key));
            if (IsTransaction == false)
            {
                await Client.DeleteStateAsync(GetStoreName(), key, CreateStateOptions(), Metadatas, cancellationToken);
                Clear();
                return;
            }
            var request = new StateTransactionRequest(key, null, StateOperationType.Delete, null, Metadatas, CreateStateOptions());
            StateTransactionRequests.Add(request);
        }

        #endregion

        #region RemoveByIdAsync

        /// <summary>
        /// 通过标识删除数据
        /// </summary>
        /// <typeparam name="TValue">值类型</typeparam>
        /// <param name="id">标识</param>
        /// <param name="cancellationToken">取消令牌</param>
        public async Task RemoveByIdAsync<TValue>(string id, CancellationToken cancellationToken = default) where TValue : IDataKey
        {
            var key = await GetKeyByIdAsync<TValue>(id, cancellationToken);
            await RemoveAsync(key, cancellationToken);
        }

        #endregion

        #region SaveAsync

        /// <inheritdoc />
        public async Task<string> SaveAsync<TValue>(TValue value, CancellationToken cancellationToken = default, string key = null) where TValue : IDataKey, IETag
        {
            value.CheckNull(nameof(value));
            InitSave(value);
            key = GetKey(key, value);
            if (IsTransaction == false)
            {
                var result = await UpdateAsync(key, value, value.ETag ?? string.Empty, cancellationToken);
                if (result == false)
                    throw new ConcurrencyException($"保存状态失败,key:{key}");
                Clear();
                return key;
            }
            var bytes = ToBytes(value);
            var request = new StateTransactionRequest(key, bytes, StateOperationType.Upsert, value.ETag ?? string.Empty, Metadatas, CreateStateOptions());
            StateTransactionRequests.Add(request);
            return key;
        }

        /// <summary>
        /// 初始化保存数据
        /// </summary>
        protected virtual void InitSave<TValue>(TValue value) where TValue : IDataKey, IETag
        {
            InitId(value);
            InitDataType(value);
        }

        /// <inheritdoc />
        public async Task SaveAsync<TValue>(IEnumerable<TValue> values, CancellationToken cancellationToken = default) where TValue : IDataKey, IETag
        {
            values.CheckNull(nameof(values));
            InitJsonType<TValue>();
            var items = ToSaveStateItems(values);
            if (IsTransaction == false)
            {
                await Client.SaveBulkStateAsync(GetStoreName(), items, cancellationToken);
                Clear();
                return;
            }
            foreach (var item in items)
            {
                var bytes = ToBytes(item.Value);
                var request = new StateTransactionRequest(item.Key, bytes, StateOperationType.Upsert, item.ETag ?? string.Empty, Metadatas, CreateStateOptions());
                StateTransactionRequests.Add(request);
            }
        }

        /// <summary>
        /// 转换为SaveStateItems
        /// </summary>
        protected List<SaveStateItem<TValue>> ToSaveStateItems<TValue>(IEnumerable<TValue> values) where TValue : IDataKey, IETag
        {
            var result = new List<SaveStateItem<TValue>>();
            foreach (var value in values)
            {
                InitSave(value);
                var key = GetKey(null, value);
                var item = new SaveStateItem<TValue>(key, value, value.ETag, CreateStateOptions(), Metadatas);
                result.Add(item);
            }
            return result;
        }

        #endregion

        #region CommitAsync

        /// <inheritdoc />
        public async Task CommitAsync(CancellationToken cancellationToken = default)
        {
            await Client.ExecuteStateTransactionAsync(GetStoreName(), StateTransactionRequests, Metadatas, cancellationToken);
            Clear();
        }

        #endregion
    }

    /// <summary>
    /// Dapr状态管理 - 查询
    /// </summary>
    public partial class DaprStateManagerBase<TStateManager>
    {

        #region Limit

        /// <summary>
        /// 添加分页大小
        /// </summary>
        /// <param name="pageSize">分页大小</param>
        public TStateManager Limit(int pageSize)
        {
            Page.Limit = pageSize;
            return Return();
        }

        #endregion

        #region Token

        /// <summary>
        /// 添加迭代令牌
        /// </summary>
        /// <param name="token">迭代令牌</param>
        public TStateManager Token(int token)
        {
            Page.Token = token.ToString();
            return Return();
        }

        #endregion

        #region OrderBy

        /// <inheritdoc />
        public TStateManager OrderBy(string orderBy)
        {
            Sort.OrderBy(orderBy);
            return Return();
        }

        #endregion

        #region Equal

        /// <inheritdoc />
        public TStateManager Equal(string property, object value)
        {
            Filter.Equal(property, value);
            return Return();
        }

        #endregion

        #region EqualIf

        /// <inheritdoc />
        public TStateManager EqualIf(string property, object value, bool condition)
        {
            return condition ? Equal(property, value) : Return();
        }

        #endregion

        #region In

        /// <inheritdoc />
        public TStateManager In(string property, IEnumerable<object> values)
        {
            Filter.In(property, values);
            return Return();
        }

        /// <inheritdoc />
        public TStateManager In(string property, params object[] values)
        {
            Filter.In(property, values);
            return Return();
        }

        #endregion

        #region And

        /// <inheritdoc />
        public TStateManager And(params IStateCondition[] conditions)
        {
            if (conditions == null)
                return Return();
            foreach (var condition in conditions)
                Filter.And(condition);
            return Return();
        }

        #endregion

        #region Or

        /// <inheritdoc />
        public TStateManager Or(params IStateCondition[] conditions)
        {
            if (conditions == null)
                return Return();
            foreach (var condition in conditions)
                Filter.Or(condition);
            return Return();
        }

        #endregion

        #region GetKeyByIdAsync

        /// <summary>
        /// 通过标识获取存储键
        /// </summary>
        /// <typeparam name="TValue">值类型</typeparam>
        /// <param name="id">标识</param>
        /// <param name="cancellationToken">取消令牌</param>
        public virtual async Task<string> GetKeyByIdAsync<TValue>(string id, CancellationToken cancellationToken = default) where TValue : IDataKey
        {
            if (id.IsEmpty())
                return null;
            SetDataTypeCondition<TValue>();
            Page.Limit = 1;
            Equal("id", id);
            var query = CreateQuery();
            var response = await Client.QueryStateAsync<TValue>(GetStoreName(), query, Metadatas, cancellationToken);
            var result = response.Results.FirstOrDefault();
            ClearQuery();
            return result?.Key;
        }

        #endregion

        #region GetStateAndETagAsync

        /// <inheritdoc />
        public virtual async Task<(TValue value, string etag)> GetStateAndETagAsync<TValue>(string key, CancellationToken cancellationToken = default)
        {
            var result = await Client.GetStateAndETagAsync<TValue>(GetStoreName(), key, ConsistencyMode, Metadatas, cancellationToken);
            ClearQuery();
            return result;
        }

        #endregion

        #region GetAsync

        /// <inheritdoc />
        public virtual async Task<TValue> GetAsync<TValue>(string key, CancellationToken cancellationToken = default)
        {
            if (IsETag<TValue>() == false)
            {
                var state = await Client.GetStateAsync<TValue>(GetStoreName(), key, ConsistencyMode, Metadatas, cancellationToken);
                ClearQuery();
                return state;
            }
            var result = await GetStateAndETagAsync<TValue>(key, cancellationToken);
            if (result.value == null)
                return default;
            if (result.value is IETag eTag)
                eTag.ETag = result.etag;
            return result.value;
        }

        /// <inheritdoc />
        public virtual async Task<IList<TValue>> GetAsync<TValue>(IReadOnlyList<string> keys, int? parallelism = 0, CancellationToken cancellationToken = default)
        {
            var result = new List<TValue>();
            var items = await Client.GetBulkStateAsync(GetStoreName(), keys, parallelism, Metadatas, cancellationToken);
            if (items == null || items.Count == 0)
                return result;
            foreach (var item in items)
            {
                var state = Json.ToObject<TValue>(item.Value, SerializerOptions);
                if (state is IETag eTag)
                    eTag.ETag = item.ETag;
                result.Add(state);
            }
            ClearQuery();
            return result;
        }

        #endregion

        #region GetByIdAsync

        /// <inheritdoc />
        public virtual async Task<TValue> GetByIdAsync<TValue>(string id, CancellationToken cancellationToken = default) where TValue : IDataKey
        {
            if (id.IsEmpty())
                return default;
            var key = KeyGenerator.CreateKey<TValue>(id);
            var result = await GetAsync<TValue>(key, cancellationToken);
            if (result != null)
                return result;
            key = await GetKeyByIdAsync<TValue>(id, cancellationToken);
            return await GetAsync<TValue>(key, cancellationToken);
        }

        #endregion

        #region SingleAsync

        /// <inheritdoc />
        public virtual async Task<TValue> SingleAsync<TValue>(CancellationToken cancellationToken = default) where TValue : IDataKey
        {
            SetDataTypeCondition<TValue>();
            Page.Limit = 1;
            var result = await QueryAsync<TValue>(cancellationToken);
            var value = result.FirstOrDefault();
            return await GetByIdAsync<TValue>(value?.Id, cancellationToken);
        }

        #endregion

        #region GetAllAsync

        /// <summary>
        /// 获取全部数据
        /// </summary>
        /// <typeparam name="TValue">值类型</typeparam>
        /// <param name="cancellationToken">取消令牌</param>
        public virtual async Task<IList<TValue>> GetAllAsync<TValue>(CancellationToken cancellationToken = default)
        {
            SetDataTypeCondition<TValue>();
            return await QueryAsync<TValue>(cancellationToken);
        }

        #endregion

        #region QueryAsync

        /// <summary>
        /// 查询
        /// </summary>
        /// <typeparam name="TValue">值类型</typeparam>
        /// <param name="cancellationToken">取消令牌</param>
        public virtual async Task<IList<TValue>> QueryAsync<TValue>(CancellationToken cancellationToken = default)
        {
            var result = new List<TValue>();
            var query = CreateQuery();
            var response = await Client.QueryStateAsync<TValue>(GetStoreName(), query, Metadatas, cancellationToken);
            ClearQuery();
            if (response == null)
                return result;
            foreach (var item in response.Results)
            {
                if (item.Data is IETag eTag)
                    eTag.ETag = item.ETag;
                result.Add(item.Data);
            }
            return result;
        }

        /// <summary>
        /// 创建状态查询对象
        /// </summary>
        protected virtual string CreateQuery()
        {
            var query = new StateQuery
            {
                Filter = Filter.GetCondition(),
                Sort = Sort,
                Page = Page
            };
            return Json.ToJson(query, SerializerOptions);
        }

        #endregion

        #region PageQueryAsync

        /// <summary>
        /// 分页查询
        /// </summary>
        /// <typeparam name="TValue">值类型</typeparam>
        /// <param name="page">分页参数</param>
        /// <param name="cancellationToken">取消令牌</param>
        public virtual async Task<PageList<TValue>> PageQueryAsync<TValue>(IPage page, CancellationToken cancellationToken = default)
        {
            Sort.OrderBy(page.Order);
            Page.Limit = page.PageSize;
            Page.Token = page.GetSkipCount() > 0 ? page.GetSkipCount().ToString() : null;
            var data = await QueryAsync<TValue>(cancellationToken);
            return new PageList<TValue>(page, data);
        }

        #endregion
    }

    /// <summary>
    /// Dapr状态管理
    /// </summary>
    public class DaprStateManager<T> : DaprStateManagerBase<IStateManager<T>>, IStateManager<T>
    {
        /// <summary>
        /// 初始化Dapr状态管理
        /// </summary>
        /// <param name="client">Dapr客户端</param>
        /// <param name="options">Dapr配置</param>
        /// <param name="loggerFactory">日志工厂</param>
        /// <param name="keyGenerator">状态存储键生成器</param>
        public DaprStateManager(DaprClient client, IOptions<DaprOptions> options, ILoggerFactory loggerFactory, IKeyGenerator keyGenerator)
            : base(client, options, loggerFactory, keyGenerator)
        {
        }

        /// <inheritdoc />
        public IStateManager<T> OrderBy(Expression<Func<T, object>> expression)
        {
            Sort.OrderBy(expression);
            return this;
        }

        /// <inheritdoc />
        public IStateManager<T> OrderByDescending(Expression<Func<T, object>> expression)
        {
            Sort.OrderByDescending(expression);
            return this;
        }

        /// <inheritdoc />
        public IStateManager<T> Equal(Expression<Func<T, object>> expression, object value)
        {
            Filter.Equal(expression, value);
            return this;
        }

        /// <inheritdoc />
        public IStateManager<T> In(Expression<Func<T, object>> expression, IEnumerable<object> values)
        {
            Filter.In(expression, values);
            return this;
        }

        /// <inheritdoc />
        public IStateManager<T> In(Expression<Func<T, object>> expression, params object[] values)
        {
            Filter.In(expression, values);
            return this;
        }
    }

