    /// <summary>
    /// 状态对象查询条件扩展
    /// </summary>
    public static class StateConditionExtensions
    {
        /// <summary>
        /// 使用And条件连接
        /// </summary>
        /// <param name="source">源查询条件</param>
        /// <param name="condition">目标查询条件</param>
        public static IStateCondition And(this IStateCondition source, IStateCondition condition)
        {
            if (condition == null)
                return source;
            if (source == null)
                return condition;
            if (source is AndCondition andCondition)
            {
                andCondition.AddCondition(condition);
                return andCondition;
            }
            if (condition is AndCondition andCondition2)
            {
                andCondition2.AddCondition(source);
                return andCondition2;
            }
            return new AndCondition(source, condition);
        }

        /// <summary>
        /// 使用Or条件连接
        /// </summary>
        /// <param name="source">源查询条件</param>
        /// <param name="condition">目标查询条件</param>
        public static IStateCondition Or(this IStateCondition source, IStateCondition condition)
        {
            if (condition == null)
                return source;
            if (source == null)
                return condition;
            if (source is OrCondition orCondition)
            {
                orCondition.AddCondition(condition);
                return orCondition;
            }
            if (condition is OrCondition orCondition2)
            {
                orCondition2.AddCondition(source);
                return orCondition2;
            }
            return new OrCondition(source, condition);
        }
    }

    /// <summary>
    /// 状态管理操作扩展
    /// </summary>
    public static class StateManagerExtensions
    {

        #region EqualIfNotEmpty

        /// <summary>
        /// 根据规则添加相等查询条件,如果参数值为空，则忽略该查询条件
        /// </summary>
        /// <param name="source">状态管理操作</param>
        /// <param name="property">属性名</param>
        /// <param name="value">属性值,如果为空，则忽略该查询条件</param>
        public static TStateManager EqualIfNotEmpty<TStateManager>(this TStateManager source, string property, object value) where TStateManager : IStateManagerBase<TStateManager>
        {
            source.CheckNull(nameof(source));
            return value.SafeString().IsEmpty() ? source : source.Equal(property, value);
        }

        #endregion

        #region InIf

        /// <summary>
        /// 根据规则添加In查询条件
        /// </summary>
        /// <param name="source">状态管理操作</param>
        /// <param name="property">属性名</param>
        /// <param name="values">属性值</param>
        /// <param name="condition">该值为true时添加查询条件，否则忽略</param>
        public static TStateManager InIf<TStateManager>(this TStateManager source, string property, IEnumerable<object> values, bool condition) where TStateManager : IStateManagerBase<TStateManager>
        {
            source.CheckNull(nameof(source));
            return condition ? source.In(property, values) : source;
        }

        #endregion
    }

    #endregion

    #region Microservices.HealthChecks
    /// <summary>
    /// Dapr健康检查
    /// </summary>
    public class DaprHealthCheck : IHealthCheck
    {
        /// <summary>
        /// Dapr客户端
        /// </summary>
        private readonly DaprClient _client;

        /// <summary>
        /// 初始化Dapr健康检查
        /// </summary>
        /// <param name="client">Dapr客户端</param>
        public DaprHealthCheck(DaprClient client)
        {
            _client = client ?? throw new ArgumentNullException(nameof(client));
        }

        /// <summary>
        /// 健康检查
        /// </summary>
        /// <param name="context">健康检查上下文</param>
        /// <param name="cancellationToken">取消令牌</param>
        public async Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext context, CancellationToken cancellationToken = default)
        {
            try
            {
                var healthy = await _client.CheckHealthAsync(cancellationToken);
                return healthy ? HealthCheckResult.Healthy() : new HealthCheckResult(context.Registration.FailureStatus);
            }
            catch (Exception exception)
            {
                return HealthCheckResult.Unhealthy(exception.Message, exception);
            }
        }
    }

    /// <summary>
    /// 工作单元健康检查
    /// </summary>
    /// <typeparam name="TUnitOfWork">工作单元类型</typeparam>
    public class UnitOfWorkHealthCheck<TUnitOfWork> : IHealthCheck where TUnitOfWork : IUnitOfWork
    {
        /// <summary>
        /// 工作单元
        /// </summary>
        private readonly TUnitOfWork _unitOfWork;

        /// <summary>
        /// 初始化工作单元健康检查
        /// </summary>
        /// <param name="unitOfWork">工作单元</param>
        public UnitOfWorkHealthCheck(TUnitOfWork unitOfWork)
        {
            _unitOfWork = unitOfWork ?? throw new ArgumentNullException(nameof(unitOfWork));
        }

        /// <summary>
        /// 健康检查
        /// </summary>
        /// <param name="context">健康检查上下文</param>
        /// <param name="cancellationToken">取消令牌</param>
        public async Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext context, CancellationToken cancellationToken = default)
        {
            context.CheckNull(nameof(context));
            try
            {
                var healthy = await _unitOfWork.CanConnectAsync(cancellationToken);
                return healthy ? HealthCheckResult.Healthy() : new HealthCheckResult(context.Registration.FailureStatus);
            }
            catch (Exception exception)
            {
                return HealthCheckResult.Unhealthy(exception.Message, exception);
            }
        }
    }

    /// <summary>
    /// 健康检查生成器扩展
    /// </summary>
    public static class HealthCheckBuilderExtensions
    {
        /// <summary>
        /// 配置Dapr健康检查
        /// </summary>
        /// <param name="builder">健康检查生成器</param>
        /// <param name="name">健康检查器名称，默认值：dapr</param>
        /// <param name="tags">标签集合</param>
        /// <param name="failureStatus">检测失败状态，默认值：HealthStatus.Unhealthy</param>
        public static IHealthChecksBuilder AddDapr(this IHealthChecksBuilder builder, string name = "dapr", IEnumerable<string> tags = null, HealthStatus? failureStatus = null)
        {
            builder.CheckNull(nameof(builder));
            failureStatus ??= HealthStatus.Unhealthy;
            tags ??= Enumerable.Empty<string>();
            return builder.AddCheck<DaprHealthCheck>(name, failureStatus, tags);
        }

        /// <summary>
        /// 配置工作单元健康检查
        /// </summary>
        /// <param name="builder">健康检查生成器</param>
        /// <param name="name">健康检查器名称，默认值：unitOfWork</param>
        /// <param name="tags">标签集合</param>
        /// <param name="failureStatus">检测失败状态，默认值：HealthStatus.Unhealthy</param>
        public static IHealthChecksBuilder AddUnitOfWork<TUnitOfWork>(this IHealthChecksBuilder builder, string name = "unitOfWork", IEnumerable<string> tags = null, HealthStatus? failureStatus = null)
            where TUnitOfWork : IUnitOfWork
        {
            builder.CheckNull(nameof(builder));
            failureStatus ??= HealthStatus.Unhealthy;
            tags ??= Enumerable.Empty<string>();
            return builder.AddCheck<UnitOfWorkHealthCheck<TUnitOfWork>>(name, failureStatus, tags);
        }

        /// <summary>
        /// 配置Url健康检查
        /// </summary>
        /// <param name="builder">健康检查生成器</param>
        /// <param name="url">请求地址</param>
        /// <param name="name">健康检查器名称</param>
        /// <param name="tags">标签集合</param>
        /// <param name="failureStatus">检测失败状态，默认值：HealthStatus.Unhealthy</param>
        public static IHealthChecksBuilder AddUrl(this IHealthChecksBuilder builder, string url, string name, IEnumerable<string> tags = null, HealthStatus? failureStatus = null)
        {
            builder.CheckNull(nameof(builder));
            failureStatus ??= HealthStatus.Unhealthy;
            tags ??= Enumerable.Empty<string>();
            return builder.AddUrlGroup(new Uri(url), name, failureStatus, tags);
        }
    }


    #endregion
}

