    #region Expressions
    /// <summary>
    /// 表达式加载器
    /// </summary>
    public class ExpressionLoader : ExpressionLoaderBase
    {
        /// <summary>
        /// 加载模型信息
        /// </summary>
        /// <param name="config">配置</param>
        /// <param name="info">模型表达式信息</param>
        protected override void Load(Config config, ModelExpressionInfo info)
        {
            LoadName(config, info);
            LoadDisplayName(config, info);
            LoadRequired(config, info);
        }

        /// <summary>
        /// 加载属性名
        /// </summary>
        protected virtual void LoadName(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(UiConst.Name, info.PropertyName, false);
        }

        /// <summary>
        /// 加载显示名称
        /// </summary>
        protected virtual void LoadDisplayName(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(UiConst.Title, info.DisplayName, false);
        }

        /// <summary>
        /// 加载必填项验证
        /// </summary>
        protected virtual void LoadRequired(Config config, ModelExpressionInfo info)
        {
            if (info.IsRequired == false)
                return;
            config.SetAttribute(UiConst.Required, "true", false);
            config.SetAttribute(UiConst.RequiredMessage, info.RequiredMessage, false);
        }
    }

    /// <summary>
    /// 表达式加载器
    /// </summary>
    public abstract class ExpressionLoaderBase : IExpressionLoader
    {
        /// <inheritdoc />
        public virtual void Load(Config config, string expressionPropertyName = "for")
        {
            if (config == null)
                return;
            if (config.Contains(expressionPropertyName) == false)
                return;
            var info = ResolveModelExpression(config, expressionPropertyName);
            info.ExpressionPropertyName = expressionPropertyName;
            Load(config, info);
        }

        /// <summary>
        /// 解析模型表达式
        /// </summary>
        protected virtual ModelExpressionInfo ResolveModelExpression(Config config, string expressionPropertyName)
        {
            var expression = config.GetValue<ModelExpression>(expressionPropertyName);
            var resolver = CreateExpressionResolver(config);
            return resolver.Resolve(expression);
        }

        /// <summary>
        /// 创建模型表达式解析器
        /// </summary>
        /// <param name="config">配置</param>
        protected virtual IExpressionResolver CreateExpressionResolver(Config config)
        {
            return new ExpressionResolver();
        }

        /// <summary>
        /// 加载模型信息
        /// </summary>
        /// <param name="config">配置</param>
        /// <param name="info">模型表达式信息</param>
        protected virtual void Load(Config config, ModelExpressionInfo info)
        {
        }
    }

    /// <summary>
    /// 模型表达式解析器
    /// </summary>
    public class ExpressionResolver : IExpressionResolver
    {
        /// <inheritdoc />
        public ModelExpressionInfo Resolve(ModelExpression expression)
        {
            var result = new ModelExpressionInfo();
            if (expression == null)
                return result;
            result.ModelType = expression.Metadata.ModelType;
            result.OriginalPropertyName = expression.Name;
            result.PropertyName = GetPropertyName(expression.Name);
            result.ModelName = GetModelName(expression.ModelExplorer);
            var property = GetProperty(expression.Metadata);
            if (property == null)
                return result;
            result.Property = property;
            result.LastPropertyName = GetLastPropertyName(property);
            result.DisplayName = GetDisplayName(property);
            result.IsPassword = GetIsPassword(property);
            result.IsBool = GetIsBool(property);
            result.IsEnum = GetIsEnum(property);
            result.IsDate = GetIsDate(property);
            result.IsInt = GetIsInt(property);
            result.IsNumber = GetIsNumber(property);
            ValidateRequired(result, property);
            ValidateLength(result, property);
            ValidateRange(result, property);
            ValidateEmail(result, property);
            ValidatePhone(result, property);
            ValidateIdCard(result, property);
            ValidateUrl(result, property);
            ValidateRegularExpression(result, property);
            return result;
        }

        /// <summary>
        /// 获取属性信息
        /// </summary>
        protected virtual MemberInfo GetProperty(ModelMetadata metadata)
        {
            if (metadata == null)
                return null;
            if (metadata.ContainerType == null)
                return null;
            var members = metadata.ContainerType.GetMember(metadata.PropertyName!);
            return members.Length == 0 ? null : members[0];
        }

        /// <summary>
        /// 获取属性名
        /// </summary>
        protected virtual string GetPropertyName(string originalPropertyName)
        {
            if (originalPropertyName.IsEmpty())
                return null;
            var array = originalPropertyName.Split('.');
            return array.Select(ModelExpressionHelper.ConvertName).Join(separator: ".");
        }

        /// <summary>
        /// 获取模型名称
        /// </summary>
        protected virtual string GetModelName(ModelExplorer explorer)
        {
            var result = GetDefaultModel();
            if (explorer == null)
                return result;
            if (explorer.Container == null)
                return result;
            if (explorer.Container.ModelType == null)
                return result;
            var modelAttribute = explorer.Container.ModelType.GetCustomAttribute<ModelAttribute>();
            if (modelAttribute != null)
                return modelAttribute.Model;
            var modelName = ModelName.Get(explorer.Container.ModelType);
            if (modelName.IsEmpty())
                return result;
            return modelName;
        }

        /// <summary>
        /// 获取默认模型名称
        /// </summary>
        protected virtual string GetDefaultModel()
        {
            return "model";
        }

        /// <summary>
        /// 获取最后一级属性名
        /// </summary>
        protected virtual string GetLastPropertyName(MemberInfo property)
        {
            return ModelExpressionHelper.ConvertName(property.Name);
        }

        /// <summary>
        /// 获取显示名称
        /// </summary>
        protected virtual string GetDisplayName(MemberInfo property)
        {
            return Util.Helpers.Reflection.GetDisplayNameOrDescription(property);
        }

        /// <summary>
        /// 获取是否密码类型
        /// </summary>
        protected virtual bool GetIsPassword(MemberInfo property)
        {
            var attribute = property.GetCustomAttribute<DataTypeAttribute>();
            if (attribute == null)
                return false;
            if (attribute.DataType == DataType.Password)
                return true;
            return false;
        }

        /// <summary>
        /// 获取是否布尔类型
        /// </summary>
        protected virtual bool GetIsBool(MemberInfo property)
        {
            return Util.Helpers.Reflection.IsBool(property);
        }

        /// <summary>
        /// 获取是否枚举类型
        /// </summary>
        protected virtual bool GetIsEnum(MemberInfo property)
        {
            return Util.Helpers.Reflection.IsEnum(property);
        }

        /// <summary>
        /// 获取是否日期类型
        /// </summary>
        protected virtual bool GetIsDate(MemberInfo property)
        {
            return Util.Helpers.Reflection.IsDate(property);
        }

        /// <summary>
        /// 获取是否整型
        /// </summary>
        protected virtual bool GetIsInt(MemberInfo property)
        {
            return Util.Helpers.Reflection.IsInt(property);
        }

        /// <summary>
        /// 获取是否数值类型
        /// </summary>
        protected virtual bool GetIsNumber(MemberInfo property)
        {
            return Util.Helpers.Reflection.IsNumber(property);
        }

        /// <summary>
        /// 验证必填项
        /// </summary>
        protected virtual void ValidateRequired(ModelExpressionInfo result, MemberInfo property)
        {
            var attribute = property.GetCustomAttribute<RequiredAttribute>();
            if (attribute == null)
                return;
            result.IsRequired = true;
            result.RequiredMessage = attribute.ErrorMessage;
        }

        /// <summary>
        /// 验证长度
        /// </summary>
        protected virtual void ValidateLength(ModelExpressionInfo result, MemberInfo property)
        {
            ValidateStringLength(result, property);
            ValidateMaxLength(result, property);
            ValidateMinLength(result, property);
        }

        /// <summary>
        /// 验证StringLengthAttribute特性
        /// </summary>
        protected virtual void ValidateStringLength(ModelExpressionInfo result, MemberInfo property)
        {
            var attribute = property.GetCustomAttribute<StringLengthAttribute>();
            if (attribute == null)
                return;
            if (attribute.MaximumLength > 0)
            {
                result.MaxLength = attribute.MaximumLength;
                result.MaxLengthMessage = attribute.ErrorMessage;
            }
            if (attribute.MinimumLength > 0)
            {
                result.MinLength = attribute.MinimumLength;
                result.MinLengthMessage = attribute.ErrorMessage;
            }
        }

        /// <summary>
        /// 验证MaxLengthAttribute特性
        /// </summary>
        protected virtual void ValidateMaxLength(ModelExpressionInfo result, MemberInfo property)
        {
            var attribute = property.GetCustomAttribute<MaxLengthAttribute>();
            if (attribute == null)
                return;
            result.MaxLength = attribute.Length;
            result.MaxLengthMessage = attribute.ErrorMessage;
        }

        /// <summary>
        /// 验证MinLengthAttribute特性
        /// </summary>
        protected virtual void ValidateMinLength(ModelExpressionInfo result, MemberInfo property)
        {
            var attribute = property.GetCustomAttribute<MinLengthAttribute>();
            if (attribute == null)
                return;
            result.MinLength = attribute.Length;
            result.MinLengthMessage = attribute.ErrorMessage;
        }

        /// <summary>
        /// 验证RangeAttribute特性
        /// </summary>
        protected virtual void ValidateRange(ModelExpressionInfo result, MemberInfo property)
        {
            var attribute = property.GetCustomAttribute<RangeAttribute>();
            if (attribute == null)
                return;
            result.Min = attribute.Minimum;
            result.Max = attribute.Maximum;
            result.MinMessage = attribute.ErrorMessage;
            result.MaxMessage = attribute.ErrorMessage;
        }

        /// <summary>
        /// 验证EmailAddressAttribute特性
        /// </summary>
        protected virtual void ValidateEmail(ModelExpressionInfo result, MemberInfo property)
        {
            var attribute = property.GetCustomAttribute<EmailAddressAttribute>();
            if (attribute == null)
                return;
            result.IsEmail = true;
            if (attribute.ErrorMessage != null && attribute.ErrorMessage.Contains("field is not a valid e-mail address"))
                return;
            result.EmailMessage = attribute.ErrorMessage;
        }

        /// <summary>
        /// 验证PhoneAttribute特性
        /// </summary>
        protected virtual void ValidatePhone(ModelExpressionInfo result, MemberInfo property)
        {
            var attribute = property.GetCustomAttribute<PhoneAttribute>();
            if (attribute == null)
                return;
            result.IsPhone = true;
            if (attribute.ErrorMessage != null && attribute.ErrorMessage.Contains("field is not a valid phone number"))
                return;
            result.PhoneMessage = attribute.ErrorMessage;
        }

        /// <summary>
        /// 验证IdCardAttribute特性
        /// </summary>
        protected virtual void ValidateIdCard(ModelExpressionInfo result, MemberInfo property)
        {
            var attribute = property.GetCustomAttribute<IdCardAttribute>();
            if (attribute == null)
                return;
            result.IsIdCard = true;
            if (attribute.ErrorMessage == R.InvalidIdCard)
                return;
            result.IdCardMessage = attribute.ErrorMessage;
        }

        /// <summary>
        /// 验证UrlAttribute特性
        /// </summary>
        protected virtual void ValidateUrl(ModelExpressionInfo result, MemberInfo property)
        {
            var attribute = property.GetCustomAttribute<UrlAttribute>();
            if (attribute == null)
                return;
            result.IsUrl = true;
            if (attribute.ErrorMessage != null && attribute.ErrorMessage.Contains("field is not a valid fully-qualified http, https, or ftp URL"))
                return;
            result.UrlMessage = attribute.ErrorMessage;
        }

        /// <summary>
        /// 验证RegularExpressionAttribute特性
        /// </summary>
        protected virtual void ValidateRegularExpression(ModelExpressionInfo result, MemberInfo property)
        {
            var attribute = property.GetCustomAttribute<RegularExpressionAttribute>();
            if (attribute == null)
                return;
            result.IsRegularExpression = true;
            result.Pattern = attribute.Pattern;
            result.RegularExpressionMessage = attribute.ErrorMessage;
        }
    }

    /// <summary>
    /// 表达式加载器
    /// </summary>
    public interface IExpressionLoader
    {
        /// <summary>
        /// 加载模型表达式配置
        /// </summary>
        /// <param name="config">配置</param>
        /// <param name="expressionPropertyName">模型表达式属性名,默认值为for</param>
        void Load(Config config, string expressionPropertyName = "for");
    }

    /// <summary>
    /// 模型表达式解析器
    /// </summary>
    public interface IExpressionResolver
    {
        /// <summary>
        /// 解析
        /// </summary>
        /// <param name="expression">模型表达式</param>
        ModelExpressionInfo Resolve(ModelExpression expression);
    }

    /// <summary>
    /// 模型表达式辅助操作
    /// </summary>
    public static class ModelExpressionHelper
    {
        /// <summary>
        /// 创建模型表达式
        /// </summary>
        /// <typeparam name="TModel">模型类型</typeparam>
        /// <typeparam name="TProperty">属性类型</typeparam>
        /// <param name="name">属性名</param>
        /// <param name="expression">属性表达式</param>
        public static ModelExpression Create<TModel, TProperty>(string name, Expression<Func<TModel, TProperty>> expression)
        {
            var property = Util.Helpers.Lambda.GetMember(expression) as PropertyInfo;
            property!.CheckNull(nameof(property));
            var provider = CreateModelMetadataProvider();
            var metadata = provider.GetMetadataForProperty(property, typeof(TProperty));
            var modelExplorer = new ModelExplorer(provider, metadata, null);
            return new ModelExpression(name, modelExplorer);
        }

        /// <summary>
        /// 创建模型表达式
        /// </summary>
        /// <typeparam name="TModel">模型类型</typeparam>
        /// <param name="name">属性名</param>
        public static ModelExpression Create<TModel>(string name)
        {
            return Create(name, typeof(TModel), typeof(TModel));
        }

        /// <summary>
        /// 获取模型元数据提供程序
        /// </summary>
        private static ModelMetadataProvider CreateModelMetadataProvider()
        {
            return new EmptyModelMetadataProvider();
        }

        /// <summary>
        /// 创建模型表达式
        /// </summary>
        /// <typeparam name="TModel">模型类型</typeparam>
        /// <typeparam name="TContainer">容器模型类型</typeparam>
        /// <param name="name">属性名</param>
        public static ModelExpression Create<TModel, TContainer>(string name)
        {
            return Create(name, typeof(TModel), typeof(TContainer));
        }

        /// <summary>
        /// 创建模型表达式
        /// </summary>
        /// <param name="name">属性名</param>
        /// <param name="modelType">模型类型</param>
        /// <param name="containerType">容器模型类型</param>
        private static ModelExpression Create(string name, Type modelType, Type containerType)
        {
            var provider = CreateModelMetadataProvider();
            var containerModelExplorer = provider.GetModelExplorerForType(containerType, null);
            var metadata = provider.GetMetadataForType(modelType);
            var modelExplorer = new ModelExplorer(provider, containerModelExplorer, metadata, null);
            return new ModelExpression(name, modelExplorer);
        }

        /// <summary>
        /// 按System.Text.Json转换命名
        /// </summary>
        /// <param name="name">属性名</param>
        public static string ConvertName(string name)
        {
            if (string.IsNullOrEmpty(name) || !char.IsUpper(name[0]))
            {
                return name;
            }
            return string.Create(name.Length, name, (chars, name2) =>
            {
                name2.AsSpan().CopyTo(chars);
                FixCasing(chars);
            });
        }

        /// <summary>
        /// 修复小写
        /// </summary>
        private static void FixCasing(Span<char> chars)
        {
            for (int i = 0; i < chars.Length; i++)
            {
                if (i == 1 && !char.IsUpper(chars[i]))
                    break;
                bool hasNext = (i + 1 < chars.Length);
                if (i > 0 && hasNext && !char.IsUpper(chars[i + 1]))
                {
                    if (chars[i + 1] == ' ')
                    {
                        chars[i] = char.ToLowerInvariant(chars[i]);
                    }
                    break;
                }
                chars[i] = char.ToLowerInvariant(chars[i]);
            }
        }
    }

    /// <summary>
    /// 模型表达式信息
    /// </summary>
    public class ModelExpressionInfo
    {
        /// <summary>
        /// 表达式属性名
        /// </summary>
        public string ExpressionPropertyName { get; set; }
        /// <summary>
        /// 模型类型
        /// </summary>
        public Type ModelType { get; set; }
        /// <summary>
        /// 属性
        /// </summary>
        public MemberInfo Property { get; set; }
        /// <summary>
        /// 原始属性名
        /// </summary>
        public string OriginalPropertyName { get; set; }
        /// <summary>
        /// 属性名,修正为驼峰形式,范例: 原始属性名为 Customer.Name,则该值为 customer.name
        /// </summary>
        public string PropertyName { get; set; }
        /// <summary>
        /// 安全属性名,范例: 原始属性名为 Customer.Name,则该值为 model.customer&amp;&amp;model.customer.name
        /// </summary>
        public string SafePropertyName => GetSafePropertyName(ModelName);
        /// <summary>
        /// 最后一级属性名,范例: 原始属性名为 Customer.Name,则该值为 name
        /// </summary>
        public string LastPropertyName { get; set; }
        /// <summary>
        /// 显示名称
        /// </summary>
        public string DisplayName { get; set; }
        /// <summary>
        /// 模型名称,默认值: model
        /// </summary>
        public string ModelName { get; set; } = "model";
        /// <summary>
        /// 是否密码类型
        /// </summary>
        public bool IsPassword { get; set; }
        /// <summary>
        /// 是否布尔类型
        /// </summary>
        public bool IsBool { get; set; }
        /// <summary>
        /// 是否枚举类型
        /// </summary>
        public bool IsEnum { get; set; }
        /// <summary>
        /// 是否日期类型
        /// </summary>
        public bool IsDate { get; set; }
        /// <summary>
        /// 是否整型
        /// </summary>
        public bool IsInt { get; set; }
        /// <summary>
        /// 是否数值类型
        /// </summary>
        public bool IsNumber { get; set; }
        /// <summary>
        /// 是否必填项
        /// </summary>
        public bool IsRequired { get; set; }
        /// <summary>
        /// 必填项验证消息
        /// </summary>
        public string RequiredMessage { get; set; }
        /// <summary>
        /// 最小长度
        /// </summary>
        public int? MinLength { get; set; }
        /// <summary>
        /// 最小长度验证消息
        /// </summary>
        public string MinLengthMessage { get; set; }
        /// <summary>
        /// 最大长度
        /// </summary>
        public int? MaxLength { get; set; }
        /// <summary>
        /// 最大长度验证消息
        /// </summary>
        public string MaxLengthMessage { get; set; }
        /// <summary>
        /// 最小值
        /// </summary>
        public object Min { get; set; }
        /// <summary>
        /// 最小值验证消息
        /// </summary>
        public string MinMessage { get; set; }
        /// <summary>
        /// 最大值
        /// </summary>
        public object Max { get; set; }
        /// <summary>
        /// 最大值验证消息
        /// </summary>
        public string MaxMessage { get; set; }
        /// <summary>
        /// 是否电子邮件
        /// </summary>
        public bool IsEmail { get; set; }
        /// <summary>
        /// 电子邮件验证消息
        /// </summary>
        public string EmailMessage { get; set; }
        /// <summary>
        /// 是否手机号
        /// </summary>
        public bool IsPhone { get; set; }
        /// <summary>
        /// 手机号验证消息
        /// </summary>
        public string PhoneMessage { get; set; }
        /// <summary>
        /// 是否身份证
        /// </summary>
        public bool IsIdCard { get; set; }
        /// <summary>
        /// 身份证验证消息
        /// </summary>
        public string IdCardMessage { get; set; }
        /// <summary>
        /// 是否网址
        /// </summary>
        public bool IsUrl { get; set; }
        /// <summary>
        /// 网址验证消息
        /// </summary>
        public string UrlMessage { get; set; }
        /// <summary>
        /// 是否正则表达式
        /// </summary>
        public bool IsRegularExpression { get; set; }
        /// <summary>
        /// 正则表达式模式
        /// </summary>
        public string Pattern { get; set; }
        /// <summary>
        /// 正则表达式验证消息
        /// </summary>
        public string RegularExpressionMessage { get; set; }

        /// <summary>
        /// 获取安全属性名,范例: 原始属性名为 Customer.Name,则该值为 model.customer&amp;&amp;model.customer.name
        /// </summary>
        /// <param name="model">模型名称</param>
        public string GetSafePropertyName(string model = "model")
        {
            if (OriginalPropertyName.IsEmpty())
                return null;
            var result = new List<string>();
            var temp = new List<string> { model };
            var array = OriginalPropertyName.Split('.');
            foreach (var item in array)
            {
                temp.Add(ModelExpressionHelper.ConvertName(item));
                result.Add(temp.Join(separator: "."));
            }
            return result.Join(separator: "&&");
        }
    }

