        }

        /// <summary>
        /// 隐藏
        /// </summary>
        /// <param name="builder">标签生成器</param>
        /// <param name="config">配置</param>
        public static TagBuilder Hidden(this TagBuilder builder, Config config)
        {
            builder.AttributeIfNotEmpty("[hidden]", config.GetValue(UiConst.Hidden));
            return builder;
        }
