    /// <summary>
    /// 主视图
    /// </summary>
    public class MainView : RazorView
    {
        /// <summary>
        /// 初始化主视图
        /// </summary>
        public MainView(string path) : base(path)
        {
        }
    }

    /// <summary>
    /// 分部视图
    /// </summary>
    public class PartView : RazorView
    {
        /// <summary>
        /// 初始化分部视图
        /// </summary>
        public PartView(string path) : base(path)
        {
            MainViews = [];
        }

        /// <summary>
        /// 引用了当前分部视图的视图集合
        /// </summary>
        public List<RazorView> MainViews { get; set; }

        /// <summary>
        /// 添加主视图
        /// </summary>
        /// <param name="mainView">主视图</param>
        public void AddMainView(RazorView mainView)
        {
            if (mainView == null)
                return;
            if (MainViews.Any(t => t.Path == mainView.Path))
                return;
            MainViews.Add(mainView);
        }

        /// <inheritdoc />
        public override List<string> GetMainViewPaths()
        {
            var result = new List<string>();
            foreach (var view in MainViews)
                result.AddRange(view.GetMainViewPaths());
            return result;
        }
    }

    /// <summary>
    /// 分部视图路径查找器
    /// </summary>
    public class PartViewPathFinder : IPartViewPathFinder
    {
        /// <summary>
        /// 视图引擎
        /// </summary>
        private readonly ICompositeViewEngine _viewEngine;
        /// <summary>
        /// Razor配置
        /// </summary>
        private readonly RazorOptions _options;

        /// <summary>
        /// 初始化分部视图路径查找器
        /// </summary>
        /// <param name="viewEngine">视图引擎</param>
        /// <param name="options">Razor配置</param>
        public PartViewPathFinder(ICompositeViewEngine viewEngine, IOptions<RazorOptions> options)
        {
            _viewEngine = viewEngine ?? throw new ArgumentNullException(nameof(viewEngine));
            _options = options.Value;
        }

        /// <inheritdoc />
        public string Find(string viewPath, string partViewName)
        {
            if (viewPath.IsEmpty())
                return null;
            if (partViewName.IsEmpty())
                return null;
            var result = _viewEngine.GetView(GetRouteValue(viewPath), partViewName, false);
            if (result.Success)
                return result.View.Path;
            var view = _viewEngine.FindView(CreateViewContext(viewPath), GetPartViewName(partViewName), isMainPage: false);
            return view.Success ? view.View.Path : null;
        }

        /// <summary>
        /// 获取路由值
        /// </summary>
        private string GetRouteValue(string viewPath)
        {
            return viewPath.RemoveStart(_options.RazorRootDirectory).RemoveEnd(".cshtml");
        }

        /// <summary>
        /// 创建视图上下文
        /// </summary>
        private ViewContext CreateViewContext(string viewPath)
        {
            return new ViewContext
            {
                ExecutingFilePath = viewPath,
                RouteData = new RouteData
                {
                    Values = { { "page", GetRouteValue(viewPath) } }
                },
                ActionDescriptor = new PageActionDescriptor
                {
                    RouteValues = { { "page", GetRouteValue(viewPath) } }
                }
            };
        }

        /// <summary>
        /// 获取分部视图路径
        /// </summary>
        private string GetPartViewName(string partViewName)
        {
            return partViewName.RemoveEnd(".cshtml");
        }
    }

    /// <summary>
    /// 分部视图路径解析器
    /// </summary>
    public class PartViewPathResolver : IPartViewPathResolver
    {
        /// <summary>
        /// 分部视图路径查找器
        /// </summary>
        private readonly IPartViewPathFinder _pathFinder;

        /// <summary>
        /// 初始化分部视图路径解析器
        /// </summary>
        /// <param name="pathFinder">分部视图路径查找器</param>
        public PartViewPathResolver(IPartViewPathFinder pathFinder)
        {
            _pathFinder = pathFinder ?? throw new ArgumentNullException(nameof(pathFinder));
        }

        /// <inheritdoc />
        public List<string> Resolve(string path, string content)
        {
            var result = new List<string>();
            if (path.IsEmpty())
                return result;
            if (content.IsEmpty())
                return result;
            var matches = Regex.Matches(content, "<[ ]*partial[ ]+name[ ]*=[ ]*\"(.+?)\"[ ]*/[ ]*>", RegexOptions.IgnoreCase);
            foreach (Match match in matches)
            {
                if (match.Success == false)
                    continue;
                var partPath = _pathFinder.Find(path, match.Groups[1].Value);
                result.Add(partPath);
            }
            return result;
        }
    }

    /// <summary>
    /// Razor视图
    /// </summary>
    public class RazorView
    {
        /// <summary>
        /// 初始化主视图
        /// </summary>
        /// <param name="path">视图路径</param>
        protected RazorView(string path)
        {
            if (path.IsEmpty())
                throw new ArgumentNullException(nameof(path));
            Path = path;
            PartViews = [];
        }

        /// <summary>
        /// 视图路径
        /// </summary>
        public string Path { get; }

        /// <summary>
        /// 包含的分部视图集合
        /// </summary>
        public List<PartView> PartViews { get; set; }

        /// <summary>
        /// 添加分部视图
        /// </summary>
        /// <param name="partView">分部视图</param>
        public virtual void AddPartView(PartView partView)
        {
            if (partView == null)
                return;
            if (PartViews.Any(t => t.Path == partView.Path))
                return;
            partView.AddMainView(this);
            PartViews.Add(partView);
        }

        /// <summary>
        /// 获取主视图路径集合
        /// </summary>
        public virtual List<string> GetMainViewPaths()
        {
            return [Path];
        }
    }

    /// <summary>
    /// Razor视图容器
    /// </summary>
    public class RazorViewContainer
    {
        /// <summary>
        /// Razor视图集合
        /// </summary>
        private readonly Dictionary<string, RazorView> _views;
        /// <summary>
        /// 分部视图路径解析器
        /// </summary>
        private readonly IPartViewPathResolver _partViewPathResolver;
        /// <summary>
        /// 视图内容解析器
        /// </summary>
        private readonly IViewContentResolver _contentResolver;

        /// <summary>
        /// 初始化Razor视图容器
        /// </summary>
        /// <param name="partViewPathResolver">分部视图路径解析器</param>
        /// <param name="contentResolver">视图内容解析器</param>
        public RazorViewContainer(IPartViewPathResolver partViewPathResolver, IViewContentResolver contentResolver = null)
        {
            _partViewPathResolver = partViewPathResolver ?? throw new ArgumentNullException(nameof(partViewPathResolver));
            _contentResolver = contentResolver ?? new ViewContentResolver();
            _views = [];
        }

        /// <summary>
        /// 获取全部视图
        /// </summary>
        public List<RazorView> GetAllViews()
        {
            return _views.Values.ToList();
        }

        /// <summary>
        /// 获取全部主视图
        /// </summary>
        public List<RazorView> GetMainViews()
        {
            return _views.Values.Where(view => view is MainView).ToList();
        }

        /// <summary>
        /// 获取全部主视图路径
        /// </summary>
        public List<string> GetMainViewPaths()
        {
            return GetMainViews().Select(t => t.Path).ToList();
        }

        /// <summary>
        /// 获取随机视图路径
        /// </summary>
        public List<string> GetRandomPaths()
        {
            return Util.Helpers.Random.GetValues(_views.Values.Where(view => view is MainView).Select(t => t.Path), 3);
        }

        /// <summary>
        /// 查找视图
        /// </summary>
        /// <param name="path">视图路径</param>
        public RazorView FindView(string path)
        {
            if (path.IsEmpty())
                return null;
            return _views.TryGetValue(path.SafeString().ToLower(), out var view) ? view : null;
        }

        /// <summary>
        /// 添加视图到容器
        /// </summary>
        /// <param name="view">视图</param>
        public void AddView(RazorView view)
        {
            if (view == null)
                return;
            _views.TryAdd(view.Path.SafeString().ToLower(), view);
        }

        /// <summary>
        /// 初始化视图容器
        /// </summary>
        /// <param name="paths">视图路径列表</param>
        public void Init(List<string> paths)
        {
            if (paths == null)
                return;
            foreach (var path in paths)
                AddView(path);
        }

        /// <summary>
        /// 添加视图
        /// </summary>
        /// <param name="path">视图路径</param>
        public RazorView AddView(string path)
        {
            if (path.IsEmpty())
                return null;
            var content = GetContent(path);
            if (content.IsEmpty())
                return null;
            RazorView view = FindOrCreateView(path, content);
            var partViewPaths = _partViewPathResolver.Resolve(path, content) ?? [];
            foreach (var partViewPath in partViewPaths)
            {
                var partView = AddView(partViewPath);
                if (partView != null)
                    view.AddPartView((PartView)partView);
            }
            AddView(view);
            return view;
        }

        /// <summary>
        /// 获取Razor文件内容
        /// </summary>
        protected string GetContent(string relativePath)
        {
            return _contentResolver.Resolve(relativePath);
        }

        /// <summary>
        /// 查找或创建视图
        /// </summary>
        protected RazorView FindOrCreateView(string path, string content)
        {
            var result = FindView(path);
            if (result != null)
                return result;
            return IsPartView(content) ? new PartView(path) : new MainView(path);
        }

        /// <summary>
        /// 是否分部视图
        /// </summary>
        /// <param name="content">视图内容</param>
        protected bool IsPartView(string content)
        {
            return content.SafeString().StartsWith("@page") == false;
        }

        /// <summary>
        /// 获取关联的视图路径列表,如果是主视图,获取它本身的路径,如果是分部视图,获取引用它的主视图路径集合
        /// </summary>
        /// <param name="path">视图路径</param>
        public List<string> GetViewPaths(string path)
        {
            if (path.IsEmpty())
                return new List<string>();
            var view = FindView(path);
            if (view == null)
                return new List<string>();
            return view.GetMainViewPaths();
        }
    }

    /// <summary>
    /// 视图内容解析器
    /// </summary>
    public class ViewContentResolver : IViewContentResolver
    {
        /// <inheritdoc />
        public string Resolve(string path)
        {
            if (path.IsEmpty())
                return null;
            if (File.FileExists(path) == false)
                path = Url.JoinPath(Util.Helpers.Common.GetCurrentDirectory(), path);
            return File.ReadToString(path);
        }
    }

    #endregion

    /// <summary>
    /// 生成Html静态页面过滤器
    /// </summary>
    public class GenerateHtmlFilter : IAsyncPageFilter
    {
        /// <summary>
        /// 执行
        /// </summary>
        public async Task OnPageHandlerExecutionAsync(PageHandlerExecutingContext context, PageHandlerExecutionDelegate next)
        {
            await next();
        }

        /// <summary>
        /// 选择操作
        /// </summary>
        public async Task OnPageHandlerSelectionAsync(PageHandlerSelectedContext context)
        {
            var options = context.HttpContext.RequestServices.GetService<IOptions<RazorOptions>>()?.Value ?? new RazorOptions();
            if (options.IsGenerateHtml == false)
                return;
            if (context.ActionDescriptor.ViewEnginePath == "/Error")
                return;
            var path = CreatePath(context, options);
            if (string.IsNullOrWhiteSpace(path))
                return;
            if (options.EnableOverrideHtml == false)
            {
                var filePath = Util.Helpers.Web.GetPhysicalPath(path);
                if (File.Exists(filePath))
                    return;
            }
            var log = GetLogger(context);
            try
            {
                var html = await GetHtml(context);
                await WriteFile(path, html);
                log.LogDebug($"Razor生成Html成功: Razor Path: {context.ActionDescriptor.ViewEnginePath}, Html Path: {path}");
            }
            catch (Exception exception)
            {
                log.LogError(exception, $"Razor页面生成 html 失败: razor path: {context.ActionDescriptor.ViewEnginePath}");
                throw;
            }
        }

        /// <summary>
        /// 获取日志记录器
        /// </summary>
        protected virtual ILogger<GenerateHtmlFilter> GetLogger(PageHandlerSelectedContext context)
        {
            return context?.HttpContext?.RequestServices?.GetService<ILogger<GenerateHtmlFilter>>() ?? NullLogger<GenerateHtmlFilter>.Instance;
        }

        /// <summary>
        /// 创建Html文件路径
        /// </summary>
        private string CreatePath(PageHandlerSelectedContext context, RazorOptions options)
        {
            var attribute = context?.ActionDescriptor?.ModelTypeInfo?.GetCustomAttribute<HtmlAttribute>();
            if (attribute == null)
                return GetPath(context?.ActionDescriptor.ViewEnginePath, options);
            if (attribute.Ignore)
                return string.Empty;
            return string.IsNullOrWhiteSpace(attribute.Path) ? string.Empty : attribute.Path;
        }

        /// <summary>
        /// 获取Html文件路径
        /// </summary>
        /// <param name="path">路径</param>
        /// <param name="options">配置</param>
        public static string GetPath(string path, RazorOptions options)
        {
            if (string.IsNullOrWhiteSpace(path))
                return string.Empty;
            if (path.Contains("/") == false)
                return Util.Helpers.Url.JoinPath(options.RazorRootDirectory, options.GenerateHtmlFolder, $"{path}.html");
            var lastIndex = path.LastIndexOf("/", StringComparison.Ordinal);
            return Util.Helpers.Url.JoinPath(options.RazorRootDirectory, path.Substring(0, lastIndex), options.GenerateHtmlFolder, $"{path.Substring(lastIndex + 1)}.html");
        }

        /// <summary>
        /// 获取页面Html
        /// </summary>
        private async Task<string> GetHtml(PageHandlerSelectedContext context)
        {
            var serviceProvider = context.HttpContext.RequestServices;
            var engine = serviceProvider.GetService<IRazorViewEngine>();
            var activator = serviceProvider.GetService<IRazorPageActivator>();
            dynamic model = System.Convert.ChangeType(context.HandlerInstance, context.HandlerInstance.GetType(), CultureInfo.InvariantCulture);
            var actionContext = new ActionContext(context.HttpContext, model.RouteData, context.ActionDescriptor);
            var page = FindPage(engine, context.ActionDescriptor.RelativePath);
            await using var stringWriter = new StringWriter();
            var view = new RazorView(engine, activator, new List<IRazorPage>(), page, HtmlEncoder.Default, new DiagnosticListener("ViewRenderService"));
            var viewContext = new ViewContext(actionContext, view, Reflection.GetPropertyValue(model, "ViewData"), Reflection.GetPropertyValue(model, "TempData"), stringWriter, new HtmlHelperOptions())
            {
                ExecutingFilePath = context.ActionDescriptor.RelativePath
            };
            var razorPage = (Page)page;
            razorPage.PageContext = model.PageContext;
            razorPage.ViewContext = viewContext;
            activator.Activate(razorPage, viewContext);
            await page.ExecuteAsync();
            return stringWriter.ToString();
        }

        /// <summary>
        /// 查找Razor页面
        /// </summary>
        private IRazorPage FindPage(IRazorViewEngine razorViewEngine, string pageName)
        {
            var result = razorViewEngine.GetPage(null!, pageName);
            return result.Page;
        }

        /// <summary>
        /// 写入文件
        /// </summary>
        private async Task WriteFile(string path, string html)
        {
            path = Util.Helpers.Web.GetPhysicalPath(path);
            var directory = Path.GetDirectoryName(path);
            if (string.IsNullOrWhiteSpace(directory))
                return;
            if (Directory.Exists(directory) == false)
                Directory.CreateDirectory(directory);
            await File.WriteAllTextAsync(path, html);
        }
    }

    /// <summary>
    /// Html生成器
    /// </summary>
    public static class HtmlGenerator
    {
        /// <summary>
        /// 生成Html
        /// </summary>
        public static async Task<List<string>> GenerateAsync(CancellationToken cancellationToken = default)
        {
            EnableGenerateHtml();
            var result = new List<string>();
            var descriptors = GetPageActionDescriptors();
            foreach (var descriptor in descriptors)
            {
                var path = $"{GetHost()}/view{descriptor.ViewEnginePath}";
                result.Add(path);
                await Web.Client.Get(path).GetResultAsync(cancellationToken);
            }
            return result.Distinct().ToList();
        }

        /// <summary>
        /// 启用Html自动生成
        /// </summary>
        private static void EnableGenerateHtml(bool isGenerateHtml = true)
        {
            var options = Ioc.Create<IOptions<RazorOptions>>();
            options.Value.IsGenerateHtml = isGenerateHtml;
        }

        /// <summary>
        /// 获取页面操作描述符列表
        /// </summary>
        private static List<PageActionDescriptor> GetPageActionDescriptors()
        {
            var provider = Ioc.Create<IActionDescriptorCollectionProvider>();
            return provider.ActionDescriptors.Items.OfType<PageActionDescriptor>().ToList();
        }

        /// <summary>
        /// 获取请求主机
        /// </summary>
        private static string GetHost()
        {
            return $"{Web.Request.Scheme}://{Web.Request.Host}";
        }
    }

    /// <summary>
    /// Razor页面监听服务,当保存Razor页面时生成该页面的html文件
    /// </summary>
    public interface IRazorWatchService
    {
        /// <summary>
        /// 启动监听
        /// </summary>
        /// <param name="cancellationToken">取消令牌</param>
        Task StartAsync(CancellationToken cancellationToken);
        /// <summary>
        /// 停止监听
        /// </summary>
        /// <param name="cancellationToken">取消令牌</param>
        Task StopAsync(CancellationToken cancellationToken);
    }

    /// <summary>
    /// 页面默认路由添加view前缀
    /// </summary>
    public class PageRouteConvention : IPageRouteModelConvention
    {
        /// <summary>
        /// 修改默认路由
        /// </summary>
        public void Apply(PageRouteModel model)
        {
            foreach (var selector in model.Selectors.ToList())
            {
                var template = selector.AttributeRouteModel?.Template;
                if (string.IsNullOrWhiteSpace(template))
                    continue;
                if (template == "Error")
                    continue;
                selector.AttributeRouteModel.Template = $"view/{template}";
            }
        }
    }

    /// <summary>
    /// Razor配置
    /// </summary>
    public class RazorOptions
    {
        /// <summary>
        /// Razor文件根路径,默认值: /ClientApp
        /// </summary>
        public string RazorRootDirectory { get; set; } = "/ClientApp";
        /// <summary>
        /// Spa静态文件根路径,默认值: ClientApp
        /// </summary>
        public string RootPath { get; set; } = "ClientApp";
        /// <summary>
        /// 是否在Razor页面运行时自动生成html文件
        /// </summary>
        public bool IsGenerateHtml { get; set; }
        /// <summary>
        /// Razor生成Html文件的目录名称，默认值：html
        /// </summary>
        public string GenerateHtmlFolder { get; set; } = "html";
        /// <summary>
        /// 是否启用Razor监视服务,默认值: true
        /// </summary>
        public bool EnableWatchRazor { get; set; } = true;
        /// <summary>
        /// Razor监听服务启动初始化的延迟时间，单位: 毫秒, 默认值：1000, 注意: 需要等待Web服务启动完成才能开始初始化 
        /// </summary>
        public int StartInitDelay { get; set; } = 1000;
        /// <summary>
        /// 修改Razor页面生成Html文件的延迟时间，单位: 毫秒, 默认值：300 ,注意: 延迟太短可能导致生成异常
        /// </summary>
        public int HtmlRenderDelayOnRazorChange { get; set; } = 300;
        /// <summary>
        /// 启动Razor监视服务时是否预热,默认值: true
        /// </summary>
        public bool EnablePreheat { get; set; } = true;
        /// <summary>
        /// 启用Razor生成覆盖已存在的html文件,默认值: true
        /// </summary>
        public bool EnableOverrideHtml { get; set; } = true;
        /// <summary>
        /// 启动Razor监视服务时, 是否重新生成全部html文件,默认值: false
        /// </summary>
        public bool EnableGenerateAllHtml { get; set; }
        /// <summary>
        /// 启动超时间隔,默认值: 300 秒
        /// </summary>
        public TimeSpan StartupTimeout { get; set; } = TimeSpan.FromSeconds(300);
    }

    /// <summary>
    /// Razor页面扩展
    /// </summary>
    public static class RazorPageExtensions
    {
        /// <summary>
        /// 添加约定
        /// </summary>
        /// <param name="builder">mvc生成器</param>
        public static IMvcBuilder AddConventions(this IMvcBuilder builder)
        {
            return builder.AddRazorPagesOptions(options =>
            {
                options.Conventions.Add(new PageRouteConvention());
                options.Conventions.AddFolderApplicationModelConvention("/", model => model.Filters.Add(new GenerateHtmlFilter()));
            });
        }
    }

    /// <summary>
    /// Razor页面监视服务
    /// </summary>
    public class RazorWatchService : IRazorWatchService
    {
        /// <summary>
        /// 是否启动完成
        /// </summary>
        public static bool IsStartComplete { get; set; }
        /// <summary>
        /// 文件监视器
        /// </summary>
        private readonly FileWatcher _watcher;
        /// <summary>
        /// Razor视图容器
        /// </summary>
        private readonly RazorViewContainer _container;
        /// <summary>
        /// Http客户端
        /// </summary>
        private readonly HttpClient _client;
        /// <summary>
        /// 操作描述符集合提供器
        /// </summary>
        private readonly IActionDescriptorCollectionProvider _provider;
        /// <summary>
        /// Razor配置
        /// </summary>
        private readonly RazorOptions _options;
        /// <summary>
        /// 是否生成缺失的html
        /// </summary>
        private bool _isGenerateMissingHtml;
        /// <summary>
        /// 新增视图事件
        /// </summary>
        private readonly SequentialSimpleAsyncSubject<string> _addViewSubject;

        /// <summary>
        /// 初始化Razor页面监视服务
        /// </summary>
        public RazorWatchService(IServiceProvider serviceProvider, IPartViewPathResolver resolver, HttpClient client,
                IActionDescriptorCollectionProvider provider, IOptions<RazorOptions> options)
        {
            Ioc.SetServiceProviderAction(() => serviceProvider);
            _watcher = new FileWatcher();
            _client = client;
            _provider = provider;
            _options = options.Value;
            _container = new RazorViewContainer(resolver);
            _addViewSubject = new SequentialSimpleAsyncSubject<string>();
            client.Timeout = options.Value.StartupTimeout;
            InitAddViewSubject();
        }

        /// <summary>
        /// 初始化添加视图事件
        /// </summary>
        private void InitAddViewSubject()
        {
            _addViewSubject.Where(path => path.IsEmpty() == false)
                .Delay(TimeSpan.FromSeconds(1))
                .SubscribeAsync(async path =>
                {
                    WriteLog($"发现新增文件: {path}");
                    _container.AddView(path);
                    EnableOverrideHtml(false);
                    await Request(path);
                    EnableOverrideHtml();
                    await Task.Delay(200);
                });
        }

        /// <summary>
        /// 启用Html覆盖
        /// </summary>
        protected void EnableOverrideHtml(bool isOverrideHtml = true)
        {
            _options.EnableOverrideHtml = isOverrideHtml;
        }

        /// <summary>
        /// 发送请求
        /// </summary>
        /// <param name="path">视图路径</param>
        /// <param name="isWrite">是否写入日志</param>
        /// <param name="times">请求次数</param>
        public async Task Request(string path, bool isWrite = true, int times = 0)
        {
            try
            {
                times++;
                if (times > 3)
                    return;
                await Task.Delay(TimeSpan.FromMilliseconds(_options.HtmlRenderDelayOnRazorChange));
                var requestPath = Url.JoinPath(GetApplicationUrl(), "view", path.RemoveStart(_options.RazorRootDirectory).RemoveEnd(".cshtml"));
                WriteLog($"发送请求: {requestPath}", isWrite);
                var response = await _client.GetAsync(requestPath);
                if (response.IsSuccessStatusCode)
                {
                    WriteLog($"请求成功: {requestPath}", isWrite);
                    return;
                }
                await Task.Delay(2000);
                if (response.StatusCode == HttpStatusCode.NotFound)
                {
                    await AddView(path);
                    return;
                }
                await Request(path, isWrite, times);
            }
            catch (InvalidOperationException)
            {
                await Task.Delay(2000);
                await Request(path, isWrite, times);
            }
        }

        /// <summary>
        /// 获取应用地址
        /// </summary>
        protected string GetApplicationUrl()
        {
            var path = GetProjectPath("Properties");
            var builder = new ConfigurationBuilder()
                .SetBasePath(path)
                .AddJsonFile("launchSettings.json", true, false);
            var config = builder.Build();
            foreach (var child in config.AsEnumerable())
            {
                if (child.Key.Contains("applicationUrl", StringComparison.OrdinalIgnoreCase))
                    return child.Value;
            }
            return null;
        }

        /// <summary>
        /// 添加视图
        /// </summary>
        protected async Task AddView(string path)
        {
            await _addViewSubject.OnNextAsync(path);
        }

        /// <inheritdoc />
        public virtual async Task StartAsync(CancellationToken cancellationToken)
        {
            WriteLog("启动中...");
            WriteLog("准备初始化...");
            InitRazorViewContainer();
            await Task.Factory.StartNew(async () =>
            {
                await Task.Delay(_options.StartInitDelay, cancellationToken);
                try
                {
                    await GenerateAllHtml();
                    await GenerateMissingHtml();
                    await Preheat();
                    IsStartComplete = true;
                    WriteLog("初始化完成.");
                    await StartWatch();
                }
                catch (Exception exception)
                {
                    WriteLog(exception.Message);
                    throw;
                }

            }, cancellationToken);
        }

        /// <summary>
        /// 写入控制台日志
        /// </summary>
        private void WriteLog(string content, bool isWrite = true)
        {
            if (isWrite == false)
                return;
            Console.WriteLine($"dbug: {DateTime.Now.ToMillisecondString()} - Util应用框架 - Razor监听服务 - {content}");
        }

        /// <summary>
        /// 初始化Razor视图容器
        /// </summary>
        protected virtual void InitRazorViewContainer()
        {
            _container.Init(GetAllViewPaths());
        }

        /// <summary>
        /// 获取所有主视图路径列表
        /// </summary>
        protected List<string> GetAllViewPaths()
        {
            var result = new List<string>();
            var descriptors = GetPageActionDescriptors();
            foreach (var descriptor in descriptors)
                result.Add(descriptor.RelativePath);
            return result.Distinct().ToList();
        }

        /// <summary>
        /// 获取页面操作描述符列表
        /// </summary>
        protected List<PageActionDescriptor> GetPageActionDescriptors()
        {
            return _provider.ActionDescriptors.Items.OfType<PageActionDescriptor>().ToList();
        }

        /// <summary>
        /// 重新生成全部html
        /// </summary>
        protected async Task GenerateAllHtml()
        {
            if (_options.EnableGenerateAllHtml == false)
                return;
            WriteLog("准备重新生成全部html...");
            _isGenerateMissingHtml = true;
            EnableGenerateHtml();
            var requestPath = Url.JoinPath(GetApplicationUrl(), "api/html");
            var response = await _client.GetAsync(requestPath);
            if (response.IsSuccessStatusCode)
            {
                WriteLog("重新生成全部html完成...");
                return;
            }
            var result = await response.Content.ReadAsStringAsync();
            WriteLog("重新生成全部html失败...");
            WriteLog(result);
        }

        /// <summary>
        /// 生成缺失的html
        /// </summary>
        protected async Task GenerateMissingHtml()
        {
            if (_options.EnableGenerateAllHtml)
                return;
            WriteLog("准备生成缺失的html...");
            EnableGenerateHtml();
            EnableOverrideHtml(false);
            var fileBasePath = GetProjectPath(_options.RazorRootDirectory);
            var files = Util.Helpers.File.GetAllFiles(fileBasePath, "*.html");
            foreach (var path in _container.GetMainViewPaths())
            {
                if (Exists(files.Select(t => t.FullName).ToList(), path))
                    continue;
                _isGenerateMissingHtml = true;
                await Request(path);
            }
            EnableOverrideHtml();
            WriteLog("生成缺失的html完成...");
        }

        /// <summary>
        /// 启用Html生成
        /// </summary>
        protected void EnableGenerateHtml(bool isGenerateHtml = true)
        {
            _options.IsGenerateHtml = isGenerateHtml;
        }

        /// <summary>
        /// 获取项目路径
        /// </summary>
        protected string GetProjectPath(string relativePath)
        {
            return Url.JoinPath(Common.GetCurrentDirectory(), relativePath);
        }

        /// <summary>
        /// html是否存在
        /// </summary>
        protected bool Exists(List<string> htmlPaths, string razorPath)
        {
            if (string.Equals(razorPath, $"{_options.RazorRootDirectory}/Error.cshtml", StringComparison.OrdinalIgnoreCase))
                return true;
            var path = GenerateHtmlFilter.GetPath(razorPath.RemoveStart(_options.RazorRootDirectory).RemoveEnd(".cshtml"), _options);
            return htmlPaths.Any(t => t.Replace("\\", "/").EndsWith(path, StringComparison.OrdinalIgnoreCase));
        }

        /// <summary>
        /// Razor页面预热
        /// </summary>
        protected async Task Preheat()
        {
            if (_isGenerateMissingHtml)
                return;
            if (_options.EnablePreheat == false)
                return;
            WriteLog("Razor页面准备预热...");
            EnableGenerateHtml(false);
            var paths = _container.GetRandomPaths();
            foreach (var path in paths)
                await Request(path, false);
            WriteLog("Razor页面预热完成...");
        }

        /// <summary>
        /// 启动监听器
        /// </summary>
        protected virtual Task StartWatch()
        {
            WriteLog("开始监听...");
            var path = GetProjectPath(_options.RazorRootDirectory.RemoveStart("/"));
            _watcher.Path(path)
                .Filter("*.cshtml")
                .OnChangedAsync(async (_, e) => await GenerateAsync(e.FullPath))
                .OnRenamedAsync(async (_, e) => await GenerateAsync(e.FullPath))
                .Start();
            return Task.CompletedTask;
        }

        /// <summary>
        /// 生成Html
        /// </summary>
        private async Task GenerateAsync(string fullPath)
        {
            if (IsIgnore(fullPath))
                return;
            EnableGenerateHtml();
            var file = new FileInfo(fullPath);
            var path = file.FullName.Replace(Common.GetCurrentDirectory(), "").Replace("\\", "/");
            WriteLog($"发现修改: {file.FullName.Replace("\\", "/")}");
            var viewPaths = _container.GetViewPaths(path);
            if (viewPaths == null || viewPaths.Count == 0)
            {
                await AddView(path);
                return;
            }
            foreach (var viewPath in viewPaths)
                await Request(viewPath);
        }

        /// <summary>
        /// 是否忽略
        /// </summary>
        protected bool IsIgnore(string path)
        {
            if (path.EndsWith(".cshtml", StringComparison.OrdinalIgnoreCase) == false)
                return true;
            if (path.Contains("_ViewImports", StringComparison.OrdinalIgnoreCase))
                return true;
            return false;
        }

        /// <inheritdoc />
        public virtual Task StopAsync(CancellationToken cancellationToken)
        {
            WriteLog("准备关闭服务...");
            _watcher.Dispose();
            return Task.CompletedTask;
        }
    }

    #endregion

    #region Renders
    /// <summary>
    /// 渲染器
    /// </summary>
    public interface IRender : IHtmlContent
    {
        /// <summary>
        /// 复制副本
        /// </summary>
        IHtmlContent Clone();
    }

    /// <summary>
    /// 渲染器
    /// </summary>
    public abstract class RenderBase : IRender
    {
        /// <summary>
        /// 标签生成器
        /// </summary>
        private TagBuilder _builder;

        /// <summary>
        /// 初始化渲染器
        /// </summary>
        protected RenderBase()
        {
        }

        /// <summary>
        /// 标签生成器
        /// </summary>
        protected TagBuilder Builder => _builder ??= GetTagBuilder();

        /// <summary>
        /// 获取标签生成器
        /// </summary>
        protected abstract TagBuilder GetTagBuilder();

        /// <summary>
        /// 渲染
        /// </summary>
        /// <param name="writer">流写入器</param>
        /// <param name="encoder">编码</param>
        public virtual void WriteTo(TextWriter writer, HtmlEncoder encoder)
        {
            Builder.WriteTo(writer, encoder);
        }

        /// <inheritdoc />
        public abstract IHtmlContent Clone();
    }

