    #region Alerts
    /// <summary>
    /// 警告提示标签生成器
    /// </summary>
    public class AlertBuilder : AngularTagBuilder
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化警告提示标签生成器
        /// </summary>
        public AlertBuilder(Config config) : base(config, "nz-alert")
        {
            _config = config;
        }

        /// <summary>
        /// 配置是否顶部公告
        /// </summary>
        public AlertBuilder Banner()
        {
            AttributeIfNotEmpty("[nzBanner]", _config.GetValue(UiConst.Banner));
            return this;
        }

        /// <summary>
        /// 配置是否可关闭
        /// </summary>
        public AlertBuilder Closeable()
        {
            AttributeIfNotEmpty("[nzCloseable]", _config.GetValue(UiConst.Closeable));
            return this;
        }

        /// <summary>
        /// 配置关闭按钮文字
        /// </summary>
        public AlertBuilder CloseText()
        {
            AttributeIfNotEmpty("nzCloseText", _config.GetValue(UiConst.CloseText));
            AttributeIfNotEmpty("[nzCloseText]", _config.GetValue(AngularConst.BindCloseText));
            return this;
        }

        /// <summary>
        /// 配置描述
        /// </summary>
        public AlertBuilder Description()
        {
            AttributeIfNotEmpty("nzDescription", _config.GetValue(UiConst.Description));
            AttributeIfNotEmpty("[nzDescription]", _config.GetValue(AngularConst.BindDescription));
            return this;
        }

        /// <summary>
        /// 配置提示内容
        /// </summary>
        public AlertBuilder Message()
        {
            AttributeIfNotEmpty("nzMessage", _config.GetValue(UiConst.Message));
            BindMessage(_config.GetValue(AngularConst.BindMessage));
            return this;
        }

        /// <summary>
        /// 配置提示内容
        /// </summary>
        public AlertBuilder BindMessage(string value)
        {
            AttributeIfNotEmpty("[nzMessage]", value);
            return this;
        }

        /// <summary>
        /// 配置是否显示图标
        /// </summary>
        public AlertBuilder ShowIcon()
        {
            if (_config.GetValue(UiConst.IconType).IsEmpty() == false ||
                _config.GetValue(AngularConst.BindIconType).IsEmpty() == false ||
                _config.GetValue(UiConst.Icon).IsEmpty() == false)
            {
                Attribute("[nzShowIcon]", "true");
                return this;
            }
            AttributeIfNotEmpty("[nzShowIcon]", _config.GetValue(UiConst.ShowIcon));
            return this;
        }

        /// <summary>
        /// 配置图标
        /// </summary>
        public AlertBuilder Icon()
        {
            AttributeIfNotEmpty("nzIconType", _config.GetValue<AntDesignIcon?>(UiConst.IconType)?.Description());
            AttributeIfNotEmpty("[nzIconType]", _config.GetValue(AngularConst.BindIconType));
            AttributeIfNotEmpty("[nzIcon]", _config.GetValue(UiConst.Icon));
            return this;
        }

        /// <summary>
        /// 配置警告类型
        /// </summary>
        public AlertBuilder Type()
        {
            AttributeIfNotEmpty("nzType", _config.GetValue<AlertType?>(UiConst.Type)?.Description());
            AttributeIfNotEmpty("[nzType]", _config.GetValue(AngularConst.BindType));
            return this;
        }

        /// <summary>
        /// 配置自定义操作项
        /// </summary>
        public AlertBuilder Action()
        {
            AttributeIfNotEmpty("[nzAction]", _config.GetValue(UiConst.Action));
            return this;
        }

        /// <summary>
        /// 配置事件
        /// </summary>
        public AlertBuilder Events()
        {
            AttributeIfNotEmpty("(nzOnClose)", _config.GetValue(UiConst.OnClose));
            return this;
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.ConfigBase(_config);
            Banner().Closeable().CloseText().Description()
                .Message().ShowIcon().Icon().Type().Action()
                .Events();
        }
    }

    /// <summary>
    /// 警告提示共享配置
    /// </summary>
    public class AlertShareConfig
    {
        /// <summary>
        /// 标识
        /// </summary>
        private readonly string _id;

        /// <summary>
        /// 初始化警告提示共享配置
        /// </summary>
        /// <param name="id">标识</param>
        public AlertShareConfig(string id)
        {
            _id = id.IsEmpty() ? Id.Create() : id;
        }

        /// <summary>
        /// 是否自动创建ng-template
        /// </summary>
        public bool? IsAutoCreateTemplate { get; set; }

        /// <summary>
        /// 模板标识
        /// </summary>
        public string TemplateId => $"t_{_id}";
    }

    /// <summary>
    /// 警告提示共享服务
    /// </summary>
    public class AlertShareConfigService
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;
        /// <summary>
        /// 警告提示共享配置
        /// </summary>
        private AlertShareConfig _shareConfig;

        /// <summary>
        /// 初始化输入框组合共享服务
        /// </summary>
        /// <param name="config">配置</param>
        public AlertShareConfigService(Config config)
        {
            _config = config;
        }

        /// <summary>
        /// 设置自动创建ng-template
        /// </summary>
        /// <param name="value">是否自动创建</param>
        public void AutoCreateTemplate(bool value)
        {
            _shareConfig.IsAutoCreateTemplate = value;
        }

        /// <summary>
        /// 初始化表单共享配置
        /// </summary>
        public void Init()
        {
            InitShareConfig();
        }

        /// <summary>
        /// 初始化
        /// </summary>
        private void InitShareConfig()
        {
            _shareConfig = GetShareConfig();
            _config.SetValueToItems(_shareConfig);
        }

        /// <summary>
        /// 获取共享配置
        /// </summary>
        private AlertShareConfig GetShareConfig()
        {
            return _config.GetValueFromItems<AlertShareConfig>() ?? new AlertShareConfig(GetId());
        }

        /// <summary>
        /// 获取标识
        /// </summary>
        private string GetId()
        {
            return _config.GetValue(UiConst.Id);
        }
    }

    /// <summary>
    /// 警告提示渲染器
    /// </summary>
    public class AlertRender : RenderBase
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;
        /// <summary>
        /// 警告提示共享配置
        /// </summary>
        private readonly AlertShareConfig _shareConfig;

        /// <summary>
        /// 初始化警告提示渲染器
        /// </summary>
        /// <param name="config">配置</param>
        public AlertRender(Config config)
        {
            _config = config;
            _shareConfig = GetShareConfig();
        }

        /// <summary>
        /// 获取共享配置
        /// </summary>
        private AlertShareConfig GetShareConfig()
        {
            return _config.GetValueFromItems<AlertShareConfig>();
        }

        /// <summary>
        /// 获取标签生成器
        /// </summary>
        protected override TagBuilder GetTagBuilder()
        {
            var builder = new AlertBuilder(_config);
            builder.Config();
            SetContent(builder);
            return builder;
        }

        /// <summary>
        /// 设置内容
        /// </summary>
        private void SetContent(AlertBuilder alertBuilder)
        {
            if (IsAutoCreateTemplate() == false)
            {
                _config.Content.AppendTo(alertBuilder);
                return;
            }
            alertBuilder.BindMessage(_shareConfig.TemplateId);
            var template = CreateTemplate();
            alertBuilder.SetContent(template);
            _config.Content.AppendTo(template);
        }

        /// <summary>
        /// 是否自动创建ng-template
        /// </summary>
        private bool IsAutoCreateTemplate()
        {
            if (_shareConfig.IsAutoCreateTemplate == false)
                return false;
            if (_config.Content.IsEmpty())
                return false;
            if (_config.Contains(AngularConst.BindMessage))
                return false;
            return true;
        }

        /// <summary>
        /// 创建模板
        /// </summary>
        private TagBuilder CreateTemplate()
        {
            if (IsAutoCreateTemplate() == false)
                return new EmptyContainerTagBuilder();
            var result = new TemplateBuilder(_config);
            result.Id(_shareConfig.TemplateId);
            return result;
        }

        /// <inheritdoc />
        public override IHtmlContent Clone()
        {
            return new AlertRender(_config.Copy());
        }
    }

    /// <summary>
    /// 警告提示,生成的标签为&lt;nz-alert>&lt;/nz-alert>
    /// </summary>
    [HtmlTargetElement("alert")]
    public class AlertTagHelper : AngularTagHelperBase
    {
        /// <summary>
        /// 配置
        /// </summary>
        private Config _config;
        /// <summary>
        /// [nzBanner],是否顶部公告, 类型: boolean, 默认值: false
        /// </summary>
        public string Banner { get; set; }
        /// <summary>
        /// [nzCloseable],是否可关闭,类型: boolean, 默认值: false
        /// </summary>
        public string Closeable { get; set; }
        /// <summary>
        /// nzCloseText,自定义关闭按钮显示文字,类型: string | TemplateRef&lt;void>
        /// </summary>
        public string CloseText { get; set; }
        /// <summary>
        /// [nzCloseText],自定义关闭按钮显示文字,类型: string | TemplateRef&lt;void>
        /// </summary>
        public string BindCloseText { get; set; }
        /// <summary>
        /// nzDescription,描述,类型: string | TemplateRef&lt;void>
        /// </summary>
        public string Description { get; set; }
        /// <summary>
        /// [nzDescription],描述,类型: string | TemplateRef&lt;void>
        /// </summary>
        public string BindDescription { get; set; }
        /// <summary>
        /// nzMessage,警告提示内容,类型: string | TemplateRef&lt;void>
        /// </summary>
        public string Message { get; set; }
        /// <summary>
        /// [nzMessage],警告提示内容,类型: string | TemplateRef&lt;void>
        /// </summary>
        public string BindMessage { get; set; }
        /// <summary>
        /// [nzShowIcon],是否显示图标, 类型: boolean, 默认值: false, nzBanner 模式下默认值为 true
        /// </summary>
        public string ShowIcon { get; set; }
        /// <summary>
        /// nzIconType,自定义图标类型
        /// </summary>
        public AntDesignIcon IconType { get; set; }
        /// <summary>
        /// [nzIconType],自定义图标类型
        /// </summary>
        public string BindIconType { get; set; }
        /// <summary>
        /// [nzIcon],自定义图标,类型: string | TemplateRef&lt;void>
        /// </summary>
        public string Icon { get; set; }
        /// <summary>
        /// nzType,警告类型,指定警告提示的样式,可选值: 'success' | 'info' | 'warning' | 'error',默认值: 'info',nzBanner 模式下默认值为 'warning'
        /// </summary>
        public AlertType Type { get; set; }
        /// <summary>
        /// [nzType],警告类型,指定警告提示的样式,可选值: 'success' | 'info' | 'warning' | 'error',默认值: 'info',nzBanner 模式下默认值为 'warning'
        /// </summary>
        public string BindType { get; set; }
        /// <summary>
        /// [nzAction],自定义操作项,类型: string | TemplateRef&lt;void>
        /// </summary>
        public string Action { get; set; }
        /// <summary>
        /// (nzOnClose),关闭事件,类型: EventEmitter&lt;void>
        /// </summary>
        public string OnClose { get; set; }

        /// <summary>
        /// 渲染前操作
        /// </summary>
        /// <param name="context">上下文</param>
        /// <param name="output">输出</param>
        protected override void ProcessBefore(TagHelperContext context, TagHelperOutput output)
        {
            _config = new Config(context, output);
            var service = new AlertShareConfigService(_config);
            service.Init();
        }

        /// <inheritdoc />
        protected override IRender GetRender(TagHelperContext context, TagHelperOutput output, TagHelperContent content)
        {
            _config.Content = content;
            return new AlertRender(_config);
        }
    }

