    /// <summary>
    /// 头像标签生成器
    /// </summary>
    public class AvatarBuilder : AngularTagBuilder
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化头像标签生成器
        /// </summary>
        public AvatarBuilder(Config config) : base(config, "nz-avatar")
        {
            _config = config;
        }

        /// <summary>
        /// 配置图标
        /// </summary>
