        public string Title { get; set; }
        /// <summary>
        /// [nzTitle],设置鼠标放在状态点上时显示的文字,为 null 时隐藏,类型: string | null,默认值: nzCount
        /// </summary>
        public string BindTitle { get; set; }
        /// <summary>
        /// [nzOffset],设置状态点的位置偏移，格式为 [left, top]，表示状态点距默认位置左侧、上方的偏移量,类型: [number, number]
        /// </summary>
        public string Offset { get; set; }
        /// <summary>
        /// nzSize,设置徽标尺寸,仅在设置了 `count` 时有效, 可选值: default | small , 默认值: default
        /// </summary>
        public BadgeSize Size { get; set; }
        /// <summary>
        /// [nzSize],设置徽标尺寸,仅在设置了 `count` 时有效, 可选值: default | small , 默认值: default
        /// </summary>
        public string BindSize { get; set; }

        /// <inheritdoc />
        protected override IRender GetRender(TagHelperContext context, TagHelperOutput output, TagHelperContent content)
        {
            var config = new Config(context, output, content);
            return new BadgeRender(config);
        }
    }

    /// <summary>
    /// 缎带徽标,生成的标签为&lt;nz-ribbon>&lt;/nz-ribbon>
    /// </summary>
    [HtmlTargetElement("ribbon")]
    public class RibbonTagHelper : AngularTagHelperBase
    {
        /// <summary>
        /// nzColor,颜色
        /// </summary>
        public AntDesignColor ColorType { get; set; }
        /// <summary>
        /// nzColor,颜色
        /// </summary>
        public string Color { get; set; }
        /// <summary>
        /// [nzColor],颜色
        /// </summary>
        public string BindColor { get; set; }
        /// <summary>
        /// nzPlacement,位置,可选值: 'start' | 'end',默认值: 'end'
        /// </summary>
        public RibbonPlacement Placement { get; set; }
        /// <summary>
        /// [nzPlacement],位置,可选值: 'start' | 'end',默认值: 'end'
        /// </summary>
        public string BindPlacement { get; set; }
        /// <summary>
        /// nzText,文本内容,支持多语言
        /// </summary>
        public string Text { get; set; }
        /// <summary>
        /// [nzText],文本内容
        /// </summary>
        public string BindText { get; set; }

        /// <inheritdoc />
        protected override IRender GetRender(TagHelperContext context, TagHelperOutput output, TagHelperContent content)
        {
            var config = new Config(context, output, content);
            return new RibbonRender(config);
        }
    }
