        /// </summary>
        public string ErrorTip { get; set; }
        /// <summary>
        /// 正在校验时的提示信息,自动创建nz-form-control,nz-form-item容器标签,并设置nz-form-control的 nzValidatingTip 属性
        /// </summary>
        public string ValidatingTip { get; set; }
    }

    /// <summary>
    /// 表单控件渲染器基类
    /// </summary>
    public abstract class FormControlRenderBase : IRender
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;
        /// <summary>
        /// 表单项共享配置
        /// </summary>
        protected readonly FormItemShareConfig ShareConfig;
        /// <summary>
        /// 标识
        /// </summary>
        private string _id;

        /// <summary>
        /// 初始化表单控件渲染器基类
        /// </summary>
        /// <param name="config">配置</param>
        protected FormControlRenderBase(Config config)
        {
            _config = config;
            ShareConfig = GetFormItemShareConfig();
        }

        /// <summary>
        /// 获取表单项共享配置
        /// </summary>
        protected FormItemShareConfig GetFormItemShareConfig()
        {
            return _config.GetValueFromItems<FormItemShareConfig>() ?? new FormItemShareConfig();
        }

        /// <summary>
        /// 获取标识
        /// </summary>
        protected virtual string GetId()
        {
            if (_id.IsEmpty() == false)
                return _id;
            _id = _config.GetValue(UiConst.Id);
            if (_id.IsEmpty() == false)
                return _id;
            return _id = Util.Helpers.Id.Create();
        }

        /// <summary>
        /// 渲染
        /// </summary>
        /// <param name="writer">流写入器</param>
        /// <param name="encoder">编码</param>
        public void WriteTo(TextWriter writer, HtmlEncoder encoder)
        {
            Init();
            var formItem = GetFormItem();
            var formLabel = GetFormLabel();
            var formControl = GetFormControl();
            formItem.AppendContent(formLabel).AppendContent(formControl);
            formItem.WriteTo(writer, encoder);
        }

        /// <summary>
        /// 初始化
        /// </summary>
        protected virtual void Init()
        {
        }

        /// <summary>
        /// 获取表单项
        /// </summary>
        protected virtual TagBuilder GetFormItem()
        {
            TagBuilder builder = new EmptyContainerTagBuilder();
            if (_config.Id == ShareConfig.Id && ShareConfig.AutoCreateFormItem == true)
            {
                builder = new FormItemBuilder(_config.CopyRemoveAttributes());
                ShareConfig.FormItemCreated = true;
            }
            builder.Config();
            return builder;
        }

        /// <summary>
        /// 获取表单标签
        /// </summary>
        protected virtual TagBuilder GetFormLabel()
        {
            if (_config.Id == ShareConfig.Id && ShareConfig.AutoCreateFormLabel == true)
            {
                var builder = new FormLabelBuilder(GetFormLabelConfig());
                builder.Config();
                SetLabelText(builder);
                SetBindLabelText(builder);
                return builder;
            }
            return new EmptyContainerTagBuilder();
        }

        /// <summary>
        /// 获取表单标签配置
        /// </summary>
        protected Config GetFormLabelConfig()
        {
            var result = _config.CopyRemoveAttributes();
            result.Content = null;
            return result;
        }

        /// <summary>
        /// 设置表单标签文本
        /// </summary>
        protected virtual void SetLabelText(FormLabelBuilder builder)
        {
            if (ShareConfig.LabelText.IsEmpty())
                return;
            var options = NgZorroOptionsService.GetOptions();
            if (options.EnableI18n)
            {
                builder.AppendContentByI18n(ShareConfig.LabelText);
                return;
            }
            builder.SetContent(ShareConfig.LabelText);
        }

        /// <summary>
        /// 设置表单标签文本
        /// </summary>
        protected virtual void SetBindLabelText(FormLabelBuilder builder)
        {
            if (ShareConfig.BindLabelText.IsEmpty())
                return;
            builder.SetContent("{{" + ShareConfig.BindLabelText + "}}");
        }

        /// <summary>
        /// 获取表单控件
        /// </summary>
        protected virtual TagBuilder GetFormControl()
        {
            TagBuilder builder = new EmptyContainerTagBuilder();
            if (_config.Id == ShareConfig.Id && ShareConfig.AutoCreateFormControl == true)
                builder = new FormControlBuilder(_config.CopyRemoveAttributes());
            builder.Config();
            AppendControl(builder);
            if (IsAppendValidationTempalte())
                AppendValidationTempalte(builder);
            return builder;
        }

        /// <summary>
        /// 添加表单控件
        /// </summary>
        protected virtual void AppendControl(TagBuilder formControlBuilder)
        {
        }

        /// <summary>
        /// 是否添加验证模板
        /// </summary>
        protected virtual bool IsAppendValidationTempalte()
        {
            return true;
        }

        /// <summary>
        /// 添加验证模板
        /// </summary>
        protected virtual void AppendValidationTempalte(TagBuilder formControlBuilder)
        {
            if (ShareConfig.ValidationTempalteId.IsEmpty())
                return;
            var templateBuilder = new TemplateBuilder(_config.CopyRemoveAttributes());
            templateBuilder.Id(ShareConfig.ValidationTempalteId);
            templateBuilder.SetContent($"{{{{{ShareConfig.ValidationExtendId}.getErrorMessage()}}}}");
            formControlBuilder.AppendContent(templateBuilder);
        }

        /// <inheritdoc />
        public abstract IHtmlContent Clone();
    }

    /// <summary>
    /// 表单控件基类
    /// </summary>
    public abstract class FormControlTagHelperBase : FormControlContainerTagHelperBase
    {
        /// <summary>
        /// 属性表达式
        /// </summary>
        public ModelExpression For { get; set; }
        /// <summary>
        /// [(ngModel)],模型双向绑定
        /// </summary>
        public string NgModel { get; set; }
        /// <summary>
        /// [ngModel],模型绑定
        /// </summary>
        public string BindNgModel { get; set; }
        /// <summary>
        /// [formControl],表单控件实例
        /// </summary>
        public string FormControl { get; set; }
        /// <summary>
        /// formControlName,表单控件名
        /// </summary>
        public string FormControlName { get; set; }
        /// <summary>
        /// [formControlName],表单控件名
        /// </summary>
        public string BindFormControlName { get; set; }
        /// <summary>
        /// (ngModelChange),模型变化事件
        /// </summary>
        public string OnModelChange { get; set; }
        /// <summary>
        /// name,名称
        /// </summary>
        public string Name { get; set; }
        /// <summary>
        /// [name],名称
        /// </summary>
        public string BindName { get; set; }
        /// <summary>
        /// *nzSpaceItem,值为 true 时设置为间距项,放入 &lt;util-space> 中使用
        /// </summary>
        public bool SpaceItem { get; set; }
    }

    /// <summary>
    /// 栅格行标签生成器基类
    /// </summary>
    public abstract class RowBuilderBase<TBuilder> : AngularTagBuilder where TBuilder : RowBuilderBase<TBuilder>
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化栅格行标签生成器基类
        /// </summary>
        /// <param name="config">配置</param>
        /// <param name="tagName">标签名称，范例：div</param>
        /// <param name="renderMode">渲染模式</param>
        protected RowBuilderBase(Config config, string tagName, TagRenderMode renderMode = TagRenderMode.Normal) : base(config, tagName, renderMode)
        {
            _config = config;
        }

        /// <summary>
        /// 配置对齐
        /// </summary>
        public virtual TBuilder Align()
        {
            Align(_config.GetValue<Align?>(UiConst.Align));
            BindAlign(_config.GetValue(AngularConst.BindAlign));
            return (TBuilder)this;
        }

        /// <summary>
        /// 配置对齐
        /// </summary>
        /// <param name="align">对齐方式</param>
        protected void Align(Align? align)
        {
            AttributeIfNotEmpty("nzAlign", align?.Description(), true);
        }

        /// <summary>
        /// 配置对齐
        /// </summary>
        /// <param name="align">对齐方式</param>
        protected void BindAlign(string align)
        {
            AttributeIfNotEmpty("[nzAlign]", align, true);
        }

        /// <summary>
        /// 配置间隔
        /// </summary>
        public virtual TBuilder Gutter()
        {
            Gutter(_config.GetValue(UiConst.Gutter));
            return (TBuilder)this;
        }

        /// <summary>
        /// 配置间隔
        /// </summary>
        protected void Gutter(string gutter)
        {
            AttributeIfNotEmpty("[nzGutter]", gutter, true);
        }

        /// <summary>
        /// 配置水平排列方式
        /// </summary>
        public virtual TBuilder Justify()
        {
            Justify(_config.GetValue<Justify?>(UiConst.Justify));
            BindJustify(_config.GetValue(AngularConst.BindJustify));
            return (TBuilder)this;
        }

        /// <summary>
        /// 配置水平排列方式
        /// </summary>
        /// <param name="justify">排列方式</param>
        protected void Justify(Justify? justify)
        {
            AttributeIfNotEmpty("nzJustify", justify?.Description(), true);
        }

        /// <summary>
        /// 配置水平排列方式
        /// </summary>
        /// <param name="justify">排列方式</param>
        protected void BindJustify(string justify)
        {
            AttributeIfNotEmpty("[nzJustify]", justify, true);
        }

        /// <summary>
        /// 配置栅格行
        /// </summary>
        protected TBuilder ConfigRow()
        {
            return Align().Gutter().Justify();
        }
    }

