        {
            _config = config;
        }

        /// <summary>
        /// 添加表单控件
        /// </summary>
        protected override void AppendControl(TagBuilder formControlBuilder)
        {
            var builder = new CascaderBuilder(_config);
            builder.Config();
            _config.Content.AppendTo(builder);
            formControlBuilder.AppendContent(builder);
