    /// <summary>
    /// 复选框表达式加载器
    /// </summary>
    public class CheckboxExpressionLoader : NgZorroExpressionLoaderBase
    {
        /// <summary>
        /// 加载模型信息
        /// </summary>
        /// <param name="config">配置</param>
        /// <param name="info">模型表达式信息</param>
        protected override void Load(Config config, ModelExpressionInfo info)
        {
            LoadLabel(config, info);
            LoadId(config, info);
            LoadName(config, info);
            LoadNgModel(config, info);
        }

        /// <summary>
        /// 加载标签
        /// </summary>
        protected virtual void LoadLabel(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(UiConst.LabelText, info.DisplayName, false);
        }

        /// <summary>
        /// 加载标识
        /// </summary>
        protected virtual void LoadId(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(UiConst.Id, GeKebaberizePropertyName(config, info), false);
        }

        /// <summary>
        /// 加载名称
        /// </summary>
        protected virtual void LoadName(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(UiConst.Name, GeKebaberizePropertyName(config, info), false);
        }

        /// <summary>
        /// 加载模型绑定
        /// </summary>
        protected virtual void LoadNgModel(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(AngularConst.NgModel, info.SafePropertyName, false);
        }
    }

    /// <summary>
    /// 复选框服务
    /// </summary>
    public class CheckboxService
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;
        /// <summary>
        /// 是否禁用自动设置表单标签 nzFor
        /// </summary>
        private bool _isDisableAutoNzFor;

        /// <summary>
        /// 初始化复选框服务
        /// </summary>
        /// <param name="config">配置</param>
        public CheckboxService(Config config)
        {
            _config = config;
        }

        /// <summary>
        /// 禁用自动设置表单标签 nzFor
        /// </summary>
        public void DisableAutoNzFor()
        {
            _isDisableAutoNzFor = true;
        }

        /// <summary>
        /// 初始化
        /// </summary>
        public void Init()
        {
            LoadExpression();
            InitFormShareService();
            InitFormItemShareService();
        }

        /// <summary>
        /// 加载表达式
        /// </summary>
        private void LoadExpression()
        {
            var loader = new CheckboxExpressionLoader();
            loader.Load(_config);
        }

        /// <summary>
        /// 初始化表单共享服务
        /// </summary>
        private void InitFormShareService()
        {
            var service = new FormShareService(_config);
            service.Init();
        }

        /// <summary>
        /// 初始化表单项共享服务
        /// </summary>
        private void InitFormItemShareService()
        {
            var service = new FormItemShareService(_config);
            if (_isDisableAutoNzFor)
                service.DisableAutoNzFor();
            service.Init();
            service.InitId();
        }
    }

