        /// </summary>
        public ColorPickerBuilder Trigger()
        {
            AttributeIfNotEmpty("nzTrigger", _config.GetValue<ColorPickerTrigger?>(UiConst.Trigger)?.Description());
            AttributeIfNotEmpty("[nzTrigger]", _config.GetValue(AngularConst.BindTrigger));
