        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.ConfigBase(_config);
            ConfigForm().NzId().Name().AllowClear().AutoFocus()
                .Backdrop().DefaultPickerValue()
                .Disabled().DisabledDate().DisabledTime()
                .DropdownClassName().PopupStyle()
                .Format().InputReadonly().Locale().Mode()
                .Placeholder().RenderExtraFooter().DateRender()
                .Size().SuffixIcon().Borderless().Inline().ShowWeekNumber()
                .Ranges().Separator().ShowTime().Status().Placement()
                .Events();
            EnableExtend();
        }

        /// <summary>
        /// 启用扩展
        /// </summary>
        private void EnableExtend()
        {
            if (IsEnableExtend() == false)
                return;
            Attribute("x-range-picker-extend");
            Attribute($"#{ExtendId}", "xRangePickerExtend");
            Attribute("[(ngModel)]", $"{ExtendId}.rangeDates", true);
            BeginDate();
            EndDate();
        }

        /// <summary>
        /// 扩展标识
        /// </summary>
        private string ExtendId
        {
            get
            {
                if (_id.IsEmpty())
                    _id = _config.GetValue(UiConst.Id);
                if (_id.IsEmpty())
                    _id = Id.Create();
                return $"x_{_id}";
            }
        }

        /// <summary>
        /// 是否启用扩展
        /// </summary>
        private bool IsEnableExtend()
        {
            if (_config.Contains(UiConst.BeginDate))
                return true;
            if (_config.Contains(UiConst.EndDate))
                return true;
            return false;
        }

        /// <summary>
        /// 配置起始日期
        /// </summary>
        private void BeginDate()
        {
            AttributeIfNotEmpty("[(beginDate)]", _config.GetValue(UiConst.BeginDate));
        }

        /// <summary>
        /// 配置结束日期
        /// </summary>
        private void EndDate()
        {
            AttributeIfNotEmpty("[(endDate)]", _config.GetValue(UiConst.EndDate));
        }
    }

    /// <summary>
    /// 日期范围选择表达式加载器
    /// </summary>
    public class RangePickerExpressionLoader : NgZorroExpressionLoaderBase
    {
        /// <summary>
        /// 加载模型信息
        /// </summary>
        /// <param name="config">配置</param>
        /// <param name="info">模型表达式信息</param>
        protected override void Load(Config config, ModelExpressionInfo info)
        {
            LoadLabel(config, info);
            LoadId(config, info);
            LoadName(config, info);
            LoadDate(config, info);
            LoadRequired(config, info);
        }

        /// <summary>
        /// 加载标签
        /// </summary>
        protected virtual void LoadLabel(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(UiConst.LabelText, info.DisplayName, false);
        }

        /// <summary>
        /// 加载标识
        /// </summary>
        protected virtual void LoadId(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(UiConst.Id, GeKebaberizePropertyName(config, info), false);
        }

        /// <summary>
        /// 加载名称
        /// </summary>
        protected virtual void LoadName(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(UiConst.Name, GeKebaberizePropertyName(config, info), false);
        }

        /// <summary>
        /// 加载日期
        /// </summary>
        protected virtual void LoadDate(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(AngularConst.NgModel, info.SafePropertyName);
            if (info.ExpressionPropertyName == UiConst.ForBegin)
            {
                config.SetAttribute(UiConst.BeginDate, info.SafePropertyName);
                return;
            }
            if (info.ExpressionPropertyName == UiConst.ForEnd)
            {
                config.SetAttribute(UiConst.EndDate, info.SafePropertyName);
                return;
            }
        }

        /// <summary>
        /// 加载必填项验证
        /// </summary>
        protected virtual void LoadRequired(Config config, ModelExpressionInfo info)
        {
            if (info.IsRequired == false)
                return;
            config.SetAttribute(UiConst.Required, "true", false);
            config.SetAttribute(UiConst.RequiredMessage, info.RequiredMessage, false);
        }
    }

    /// <summary>
    /// 日期范围选择服务
    /// </summary>
    public class RangePickerService
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化日期范围选择服务
        /// </summary>
        /// <param name="config">配置</param>
        public RangePickerService(Config config)
        {
            _config = config;
        }

        /// <summary>
        /// 初始化
        /// </summary>
        public void Init()
        {
            LoadExpression();
        }

        /// <summary>
        /// 加载表达式
        /// </summary>
        private void LoadExpression()
        {
            var loader = new RangePickerExpressionLoader();
            loader.Load(_config, UiConst.ForBegin);
            loader.Load(_config, UiConst.ForEnd);
        }
    }

