    #region Descriptions
    /// <summary>
    /// 描述列表标签生成器
    /// </summary>
    public class DescriptionBuilder : AngularTagBuilder
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化描述列表标签生成器
        /// </summary>
        /// <param name="config">配置</param>
        public DescriptionBuilder(Config config) : base(config, "nz-descriptions")
        {
            _config = config;
        }

        /// <summary>
        /// 配置标题
        /// </summary>
        public DescriptionBuilder Title()
        {
            SetTitle(_config.GetValue(UiConst.Title));
            AttributeIfNotEmpty("[nzTitle]", _config.GetValue(AngularConst.BindTitle));
            return this;
        }

        /// <summary>
        /// 设置标题
        /// </summary>
        private void SetTitle(string value)
        {
            var options = NgZorroOptionsService.GetOptions();
            if (options.EnableI18n)
            {
                this.AttributeByI18n("[nzTitle]", value);
                return;
            }
            AttributeIfNotEmpty("nzTitle", value);
        }

        /// <summary>
        /// 配置操作区域
        /// </summary>
        public DescriptionBuilder Extra()
        {
            AttributeIfNotEmpty("nzExtra", _config.GetValue(UiConst.Extra));
            AttributeIfNotEmpty("[nzExtra]", _config.GetValue(AngularConst.BindExtra));
            return this;
        }

        /// <summary>
        /// 配置是否显示边框
        /// </summary>
        public DescriptionBuilder Bordered()
        {
            AttributeIfNotEmpty("[nzBordered]", _config.GetValue(UiConst.Bordered));
            return this;
        }

        /// <summary>
        /// 配置一行包含的描述列表项数量
        /// </summary>
        public DescriptionBuilder Column()
        {
            var column = _config.GetValue(UiConst.Column);
            if (column.IsEmpty() == false)
                return Column(column);
            var value = _config.GetValue<int?>(UiConst.XxlColumn);
            if (value == null)
                return this;
            var model = new ColumnModel
            {
                Xs = 1,
                Sm = 1,
                Md = 1,
                Lg = 1,
                Xl = 2,
                Xxl = value
            };
            Column(model.ToJson());
            return this;
        }

        /// <summary>
        /// 配置一行包含的描述列表项数量
        /// </summary>
        public DescriptionBuilder Column(string column)
        {
            AttributeIfNotEmpty("[nzColumn]", column);
            return this;
        }

        /// <summary>
        /// 配置列表大小
        /// </summary>
        public DescriptionBuilder Size()
        {
            AttributeIfNotEmpty("nzSize", _config.GetValue<DescriptionSize?>(UiConst.Size)?.Description());
            AttributeIfNotEmpty("[nzSize]", _config.GetValue(AngularConst.BindSize));
            return this;
        }

        /// <summary>
        /// 配置列表布局
        /// </summary>
        public DescriptionBuilder Layout()
        {
            AttributeIfNotEmpty("nzLayout", _config.GetValue<DescriptionLayout?>(UiConst.Layout)?.Description());
            AttributeIfNotEmpty("[nzLayout]", _config.GetValue(AngularConst.BindLayout));
            return this;
        }

        /// <summary>
        /// 配置是否显示冒号
        /// </summary>
        public DescriptionBuilder Colon()
        {
            AttributeIfNotEmpty("[nzColon]", _config.GetValue(UiConst.Colon));
            return this;
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.Config();
            Title().Extra().Bordered().Column().Size().Layout().Colon();
        }
    }

    /// <summary>
    /// 描述列表项标签生成器
    /// </summary>
    public class DescriptionItemBuilder : AngularTagBuilder
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化描述列表项标签生成器
        /// </summary>
        /// <param name="config">配置</param>
        public DescriptionItemBuilder(Config config) : base(config, "nz-descriptions-item")
        {
            _config = config;
        }

        /// <summary>
        /// 配置标题
        /// </summary>
        public DescriptionItemBuilder Title()
        {
            SetTitle(_config.GetValue(UiConst.Title));
            AttributeIfNotEmpty("[nzTitle]", _config.GetValue(AngularConst.BindTitle));
            return this;
        }

        /// <summary>
        /// 设置标题
        /// </summary>
        private void SetTitle(string value)
        {
            var options = NgZorroOptionsService.GetOptions();
            if (options.EnableI18n)
            {
                this.AttributeByI18n("[nzTitle]", value);
                return;
            }
            AttributeIfNotEmpty("nzTitle", value);
        }

        /// <summary>
        /// 配置列跨度
        /// </summary>
        public DescriptionItemBuilder Span()
        {
            AttributeIfNotEmpty("nzSpan", _config.GetValue(UiConst.Span));
            AttributeIfNotEmpty("[nzSpan]", _config.GetValue(AngularConst.BindSpan));
            return this;
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.Config();
            Title().Span();
        }

        /// <summary>
        /// 配置内容
        /// </summary>
        protected override void ConfigContent(Config config)
        {
            if (config.Content.IsEmpty() == false)
            {
                config.Content.AppendTo(this);
                return;
            }
            ConfigValue();
            CopyToClipboard();
        }

        /// <summary>
        /// 配置值
        /// </summary>
        private void ConfigValue()
        {
            var dataType = _config.GetValue<DataType?>(UiConst.Type);
            var value = _config.GetValue(UiConst.Value);
            if (value.IsEmpty())
                return;
            if (dataType == DataType.Bool)
            {
                LoadBool(value);
                return;
            }
            if (dataType == DataType.Date)
            {
                LoadDate(value);
                return;
            }
            if (dataType == DataType.Number)
            {
                LoadNumber(value);
                return;
            }
            SetContent("{{" + GetValue(value) + "}}");
        }

        /// <summary>
        /// 加载布尔值
        /// </summary>
        protected void LoadBool(string value)
        {
            AppendContent(new IconBuilder(_config).Type(AntDesignIcon.Check.Description()).Attribute("*ngIf", $"{value}"));
            AppendContent(new IconBuilder(_config).Type(AntDesignIcon.Close.Description()).Attribute("*ngIf", $"!({value})"));
        }

        /// <summary>
        /// 加载日期值
        /// </summary>
        protected void LoadDate(string value)
        {
            var format = _config.GetValue(UiConst.DateFormat);
            if (format.IsEmpty())
                format = "yyyy-MM-dd HH:mm:ss";
            SetContent($"{{{{{value}|date:\"{format}\"}}}}");
        }

        /// <summary>
        /// 加载数值
        /// </summary>
        protected void LoadNumber(string value)
        {
            SetContent("{{" + value + "}}");
        }

        /// <summary>
        /// 获取值
        /// </summary>
        private string GetValue(string value)
        {
            var enabledI18n = _config.GetValue<bool>(UiConst.ValueI18n);
            if (enabledI18n)
                return $"{value}|i18n";
            return value;
        }

        /// <summary>
        /// 配置复制到剪贴板
        /// </summary>
        private void CopyToClipboard()
        {
            if (_config.GetValue<bool?>(UiConst.Clipboard) != true)
                return;
            var value = _config.GetValue(UiConst.Value);
            if (value.IsEmpty())
                return;
            _config.SetAttribute(UiConst.CopyToClipboard, value);
            var buttonBuilder = new ButtonBuilder(_config);
            buttonBuilder.Attribute("nz-button");
            buttonBuilder.NgIf(value);
            buttonBuilder.CopyToClipboard().Type().Icon();
            AppendContent(buttonBuilder);
        }
    }

