    #region Dropdowns
    /// <summary>
    /// 下拉菜单标签生成器
    /// </summary>
    public class DropdownMenuBuilder : AngularTagBuilder
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化下拉菜单标签生成器
        /// </summary>
        /// <param name="config">配置</param>
        public DropdownMenuBuilder(Config config) : base(config, "nz-dropdown-menu")
        {
            _config = config;
        }

        /// <summary>
        /// 配置标识
        /// </summary>
        protected override void ConfigId(Config config)
        {
            if (config.Contains(UiConst.Id))
                Attribute($"#{config.GetValue(UiConst.Id)}", "nzDropdownMenu");
            AttributeIfNotEmpty("id", config.GetValue(AngularConst.RawId));
        }

        /// <summary>
        /// 配置内容元素
        /// </summary>
        protected override void ConfigContent(Config config)
        {
            var shareConfig = GetShareConfig();
            if (shareConfig.AutoCreateUl == false)
            {
                config.Content.AppendTo(this);
                return;
            }
            var ulBuilder = CreateUlBuilder();
            ConfigSelectable(ulBuilder);
            ConfigEvents(ulBuilder);
            SetContent(ulBuilder);
            _config.Content.AppendTo(ulBuilder);
        }

        /// <summary>
        /// 获取下拉菜单共享配置
        /// </summary>
        private DropdownMenuShareConfig GetShareConfig()
        {
            return _config.GetValueFromItems<DropdownMenuShareConfig>() ?? new DropdownMenuShareConfig();
        }

        /// <summary>
        /// 创建ul标签生成器
        /// </summary>
        private TagBuilder CreateUlBuilder()
        {
            var builder = new UlBuilder();
            builder.Attribute("nz-menu");
            return builder;
        }

        /// <summary>
        /// 配置允许选中
        /// </summary>
        private void ConfigSelectable(TagBuilder builder)
        {
            builder.AttributeIfNotEmpty("[nzSelectable]", _config.GetValue(UiConst.Selectable));
        }

        /// <summary>
        /// 配置事件
        /// </summary>
        private void ConfigEvents(TagBuilder builder)
        {
            builder.AttributeIfNotEmpty("(nzClick)", _config.GetValue(UiConst.OnClick));
        }
    }

    /// <summary>
    /// 下拉菜单共享配置
    /// </summary>
    public class DropdownMenuShareConfig
    {
        /// <summary>
        /// 自动创建 ul
        /// </summary>
        public bool? AutoCreateUl { get; set; }
    }

    /// <summary>
    /// 下拉菜单共享服务
    /// </summary>
    public class DropdownMenuService
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;
        /// <summary>
        /// 下拉菜单共享配置
        /// </summary>
        private DropdownMenuShareConfig _shareConfig;

        /// <summary>
        /// 初始化表单项共享服务
        /// </summary>
        /// <param name="config">配置</param>
        public DropdownMenuService(Config config)
        {
            _config = config;
        }

        /// <summary>
        /// 设置自动创建 ul
        /// </summary>
        /// <param name="value">是否自动创建</param>
        public void AutoCreateUl(bool value)
        {
            if (_shareConfig.AutoCreateUl == false)
                return;
            _shareConfig.AutoCreateUl = value;
        }

        /// <summary>
        /// 初始化
        /// </summary>
        public void Init()
        {
            InitShareConfig();
        }

        /// <summary>
        /// 初始化
        /// </summary>
        private void InitShareConfig()
        {
            _shareConfig = GetShareConfig();
            _config.SetValueToItems(_shareConfig);
        }

        /// <summary>
        /// 获取下拉菜单共享配置
        /// </summary>
        private DropdownMenuShareConfig GetShareConfig()
        {
            return _config.GetValueFromItems<DropdownMenuShareConfig>() ?? new DropdownMenuShareConfig();
        }
    }

    /// <summary>
    /// 下拉菜单渲染器
    /// </summary>
    public class DropdownMenuRender : RenderBase
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化下拉菜单渲染器
        /// </summary>
        /// <param name="config">配置</param>
        public DropdownMenuRender(Config config)
        {
            _config = config;
        }

        /// <summary>
        /// 获取标签生成器
        /// </summary>
        protected override TagBuilder GetTagBuilder()
        {
            var builder = new DropdownMenuBuilder(_config);
            builder.Config();
            return builder;
        }

        /// <inheritdoc />
        public override IHtmlContent Clone()
        {
            return new DropdownMenuRender(_config.Copy());
        }
    }

