        /// <summary>
        /// 配置文本
        /// </summary>
        public FormLabelBuilder Text()
        {
            return SetText(_config.GetValue(UiConst.Text));
        }

        /// <summary>
        /// 配置内容
        /// </summary>
        private FormLabelBuilder SetText(string value)
        {
            var options = NgZorroOptionsService.GetOptions();
            if (value.IsEmpty())
                return this;
            if (options.EnableI18n)
            {
                this.AppendContentByI18n(value);
                return this;
            }
            AppendContent(value);
            return this;
        }

        /// <summary>
        /// 配置宽度
        /// </summary>
        public FormLabelBuilder Width()
        {
            var shareConfig = GetFormItemShareConfig();
            if (shareConfig.LabelWidth.IsEmpty() == false)
                Style(_config, "width", shareConfig.LabelWidth);
            return this;
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            Width();
            base.Config();
            ConfigColumn().Required().NoColon().LabelWrap().LabelAlign()
                .NzFor().TooltipTitle().TooltipIcon();
            Text();
        }

        /// <summary>
        /// 配置内容
        /// </summary>
        protected override void ConfigContent(Config config)
        {
            if (config.Content.IsEmpty())
            {
                SetText(config.GetValue(UiConst.Title));
                return;
            }
            base.ConfigContent(config);
        }
    }

