        public ColumnService(Config config)
        {
            _config = config;
        }

        /// <summary>
        /// 初始化
        /// </summary>
        /// <param name="id">标识</param>
        public void Init(string id)
        {
            var formShareConfig = _config.GetValueFromItems<FormShareConfig>();
