        public TextareaBuilder(Config config) : base(config, "textarea")
        {
            base.Attribute("nz-input");
            _config = config;
        }

        /// <summary>
        /// 配置占位符
        /// </summary>
        public virtual TextareaBuilder Placeholder()
        {
            AttributeIfNotEmpty("placeholder", _config.GetValue(UiConst.Placeholder));
            AttributeIfNotEmpty("[placeholder]", _config.GetValue(AngularConst.BindPlaceholder));
            return this;
        }

        /// <summary>
        /// 配置禁用
        /// </summary>
        public TextareaBuilder Disabled()
        {
            AttributeIfNotEmpty("[disabled]", _config.GetValue(UiConst.Disabled));
            return this;
        }

        /// <summary>
        /// 配置只读
        /// </summary>
        public TextareaBuilder Readonly()
        {
            AttributeIfNotEmpty("[readOnly]", _config.GetValue(UiConst.Readonly));
            return this;
        }

        /// <summary>
        /// 配置行数
        /// </summary>
        public TextareaBuilder Rows()
        {
            AttributeIfNotEmpty("[rows]", _config.GetValue(UiConst.Rows));
            return this;
        }

        /// <summary>
        /// 配置列数
        /// </summary>
        public TextareaBuilder Columns()
        {
            AttributeIfNotEmpty("[cols]", _config.GetValue(UiConst.Columns));
            return this;
        }

        /// <summary>
        /// 配置自适应内容高度
        /// </summary>
        public TextareaBuilder Autosize()
        {
            AttributeIfNotEmpty("[nzAutosize]", _config.GetValue(UiConst.Autosize));
            var model = new RowsModel { MinRows = _config.GetValue<int?>(UiConst.MinRows), MaxRows = _config.GetValue<int?>(UiConst.MaxRows) };
            AttributeIfNotEmpty("[nzAutosize]", model.ToJson());
            return this;
        }

        /// <summary>
        /// 配置输入框大小
        /// </summary>
        public TextareaBuilder Size()
        {
            AttributeIfNotEmpty("nzSize", _config.GetValue<InputSize?>(UiConst.Size)?.Description());
            AttributeIfNotEmpty("[nzSize]", _config.GetValue(AngularConst.BindSize));
            return this;
        }

        /// <summary>
        /// 配置必填项验证
        /// </summary>
        public override TextareaBuilder Required()
        {
            AttributeIfNotEmpty("[x-required-extend]", _config.GetValue(UiConst.Required));
            return this;
        }

        /// <summary>
        /// 配置自动完成
        /// </summary>
        public TextareaBuilder Autocomplete()
        {
            var autocompleteId = _config.GetValue(UiConst.Autocomplete);
            if (autocompleteId.IsEmpty())
                return this;
            AttributeIfNotEmpty("[nzAutocomplete]", autocompleteId);
            var autocompleteSearchKeyword = _config.GetValue<bool?>(UiConst.AutocompleteSearchKeyword);
            if (autocompleteSearchKeyword == true)
                OnInput($"x_{autocompleteId}.search($event.target)");
            return this;
        }

        /// <summary>
        /// 配置事件
        /// </summary>
        public TextareaBuilder Events()
        {
            OnInput(_config.GetValue(UiConst.OnInput));
            AttributeIfNotEmpty("(blur)", _config.GetValue(UiConst.OnBlur));
            AttributeIfNotEmpty("(keyup.enter)", _config.GetValue(UiConst.OnKeyupEnter));
            AttributeIfNotEmpty("(keydown.enter)", _config.GetValue(UiConst.OnKeydownEnter));
            return this;
        }

        /// <summary>
        /// 输入事件
        /// </summary>
        public TextareaBuilder OnInput(string value)
        {
            AttributeIfNotEmpty("(input)", value);
            return this;
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.ConfigBase(_config);
            ConfigForm().Name().Placeholder().Disabled().Readonly().Size().Rows().Columns()
                .Autosize().Size().Autocomplete()
                .Events()
                .Required().RequiredMessage()
                .MinLength().MinLengthMessage()
                .MaxLength()
                .ValidationExtend();
        }

        /// <summary>
        /// 配置间距项
        /// </summary>
        public override TextareaBuilder SpaceItem()
        {
            if (FormItemShareConfig.FormItemCreated)
                return this;
            var inputGroupShareConfig = GetInputGroupShareConfig();
            if (inputGroupShareConfig.InputGroupCreated)
                return this;
            this.SpaceItem(FormItemShareConfig.SpaceItem);
            return this;
        }

        /// <summary>
        /// 获取输入框组合共享配置
        /// </summary>
        private InputGroupShareConfig GetInputGroupShareConfig()
        {
            return _config.GetValueFromItems<InputGroupShareConfig>() ?? new InputGroupShareConfig();
        }
    }

