    /// <summary>
    /// 输入框表达式加载器
    /// </summary>
    public class InputExpressionLoader : NgZorroExpressionLoaderBase
    {
        /// <summary>
        /// 加载模型信息
        /// </summary>
        /// <param name="config">配置</param>
        /// <param name="info">模型表达式信息</param>
        protected override void Load(Config config, ModelExpressionInfo info)
        {
            LoadLabel(config, info);
            LoadId(config, info);
            LoadName(config, info);
            LoadNgModel(config, info);
            LoadMinRows(config, info);
            LoadVirtualHeight(config, info);
            LoadKeys(config, info);
            LoadPassword(config, info);
            LoadRequired(config, info);
            LoadMinLength(config, info);
            LoadMaxLength(config, info);
            LoadMin(config, info);
            LoadMax(config, info);
            LoadEmail(config, info);
            LoadRegex(config, info);
            LoadPhone(config, info);
            LoadIdCard(config, info);
        }

        /// <summary>
        /// 加载标签
        /// </summary>
        protected virtual void LoadLabel(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(UiConst.LabelText, info.DisplayName, false);
        }

        /// <summary>
        /// 加载标识
        /// </summary>
        protected virtual void LoadId(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(UiConst.Id, GeKebaberizePropertyName(config, info), false);
        }

        /// <summary>
        /// 加载名称
        /// </summary>
        protected virtual void LoadName(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(UiConst.Name, GeKebaberizePropertyName(config, info), false);
        }

        /// <summary>
        /// 加载模型绑定
        /// </summary>
        protected virtual void LoadNgModel(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(AngularConst.NgModel, info.SafePropertyName, false);
        }

        /// <summary>
        /// 加载文本域最小行数
        /// </summary>
        protected virtual void LoadMinRows(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(UiConst.MinRows, 3, false);
        }

        /// <summary>
        /// 加载下拉树虚拟高度
        /// </summary>
        protected virtual void LoadVirtualHeight(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(UiConst.VirtualHeight, "300px", false);
        }

        /// <summary>
        /// 加载下拉树标识列表
        /// </summary>
        protected virtual void LoadKeys(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(UiConst.LoadKeys, info.SafePropertyName, false);
        }

        /// <summary>
        /// 加载密码类型
        /// </summary>
        protected virtual void LoadPassword(Config config, ModelExpressionInfo info)
        {
            if (info.IsPassword == false)
                return;
            config.SetAttribute(UiConst.Type, "password", false);
        }

        /// <summary>
        /// 加载必填项验证
        /// </summary>
        protected virtual void LoadRequired(Config config, ModelExpressionInfo info)
        {
            if (info.IsRequired == false)
                return;
            config.SetAttribute(UiConst.Required, "true", false);
            config.SetAttribute(UiConst.RequiredMessage, info.RequiredMessage, false);
        }

        /// <summary>
        /// 加载最小长度验证
        /// </summary>
        protected virtual void LoadMinLength(Config config, ModelExpressionInfo info)
        {
            if (info.MinLength == null)
                return;
            config.SetAttribute(UiConst.MinLength, info.MinLength, false);
            config.SetAttribute(UiConst.MinLengthMessage, info.MinLengthMessage, false);
        }

        /// <summary>
        /// 加载最大长度验证
        /// </summary>
        protected virtual void LoadMaxLength(Config config, ModelExpressionInfo info)
        {
            if (info.MaxLength == null)
                return;
            config.SetAttribute(UiConst.MaxLength, info.MaxLength, false);
            config.SetAttribute(UiConst.MaxLengthMessage, info.MaxLengthMessage, false);
        }

        /// <summary>
        /// 加载最小值验证
        /// </summary>
        protected virtual void LoadMin(Config config, ModelExpressionInfo info)
        {
            if (info.Min == null)
                return;
            config.SetAttribute(UiConst.Min, info.Min, false);
            config.SetAttribute(UiConst.MinMessage, info.MinMessage, false);
        }

        /// <summary>
        /// 加载最大值验证
        /// </summary>
        protected virtual void LoadMax(Config config, ModelExpressionInfo info)
        {
            if (info.Max == null)
                return;
            config.SetAttribute(UiConst.Max, info.Max, false);
            config.SetAttribute(UiConst.MaxMessage, info.MaxMessage, false);
        }

        /// <summary>
        /// 加载电子邮件验证
        /// </summary>
        protected virtual void LoadEmail(Config config, ModelExpressionInfo info)
        {
            if (info.IsEmail == false)
                return;
            config.SetAttribute(UiConst.Type, InputType.Email, false);
            config.SetAttribute(UiConst.EmailMessage, info.EmailMessage, false);
        }

        /// <summary>
        /// 加载正则表达式验证
        /// </summary>
        protected virtual void LoadRegex(Config config, ModelExpressionInfo info)
        {
            if (info.IsRegularExpression == false)
                return;
            config.SetAttribute(UiConst.Pattern, info.Pattern, false);
            config.SetAttribute(UiConst.PatternMessage, info.RegularExpressionMessage, false);

        }
        /// <summary>
        /// 加载手机号验证
        /// </summary>
        protected virtual void LoadPhone(Config config, ModelExpressionInfo info)
        {
            if (info.IsPhone == false)
                return;
            config.SetAttribute(UiConst.IsInvalidPhone, "true", false);
            config.SetAttribute(UiConst.Pattern, ValidatePattern.MobilePhonePattern, false);
            config.SetAttribute(UiConst.PatternMessage, info.PhoneMessage, false);
        }

        /// <summary>
        /// 加载身份证验证
        /// </summary>
        protected virtual void LoadIdCard(Config config, ModelExpressionInfo info)
        {
            if (info.IsIdCard == false)
                return;
            config.SetAttribute(UiConst.IsInvalidIdCard, "true", false);
            config.SetAttribute(UiConst.Pattern, ValidatePattern.IdCardPattern, false);
            config.SetAttribute(UiConst.PatternMessage, info.IdCardMessage, false);
        }
    }

    /// <summary>
    /// 输入框组合共享服务
    /// </summary>
    public class InputGroupShareService
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;
        /// <summary>
        /// 输入框组合共享配置
        /// </summary>
        private InputGroupShareConfig _shareConfig;

        /// <summary>
        /// 初始化输入框组合共享服务
        /// </summary>
        /// <param name="config">配置</param>
        public InputGroupShareService(Config config)
        {
            _config = config;
        }

        /// <summary>
        /// 设置nz-input-group已创建
        /// </summary>
        public void Created()
        {
            _shareConfig.InputGroupCreated = true;
        }

        /// <summary>
        /// 设置自动创建nz-input-group
        /// </summary>
        /// <param name="value">是否自动创建</param>
        public void AutoCreateInputGroup(bool value)
        {
            if (_shareConfig.AutoCreateInputGroup == false)
                return;
            _shareConfig.AutoCreateInputGroup = value;
        }

        /// <summary>
        /// 设置输入框标识
        /// </summary>
        /// <param name="id">输入框标识</param>
        public void SetInputId(string id)
        {
            _shareConfig.InputId = id;
        }

        /// <summary>
        /// 设置样式类
        /// </summary>
        /// <param name="value">样式类</param>
        public void SetClass(string value)
        {
            _shareConfig.Class = value;
        }

        /// <summary>
        /// 初始化输入框组合共享配置
        /// </summary>
        public void Init()
        {
            InitShareConfig();
            SetShareConfig();
            AutoCreateInputGroup();
            SetNgIf();
        }

        /// <summary>
        /// 初始化
        /// </summary>
        private void InitShareConfig()
        {
            _shareConfig = GetShareConfig();
            _config.SetValueToItems(_shareConfig);
        }

        /// <summary>
        /// 获取共享配置
        /// </summary>
        private InputGroupShareConfig GetShareConfig()
        {
            return _config.GetValueFromItems<InputGroupShareConfig>() ?? new InputGroupShareConfig();
        }

        /// <summary>
        /// 设置共享配置
        /// </summary>
        private void SetShareConfig()
        {
            if (_shareConfig.AddOnBefore.IsEmpty())
                _shareConfig.AddOnBefore = _config.GetValue(UiConst.AddOnBefore);
            if (_shareConfig.BindAddOnBefore.IsEmpty())
                _shareConfig.BindAddOnBefore = _config.GetValue(AngularConst.BindAddOnBefore);
            if (_shareConfig.AddOnAfter.IsEmpty())
                _shareConfig.AddOnAfter = _config.GetValue(UiConst.AddOnAfter);
            if (_shareConfig.BindAddOnAfter.IsEmpty())
                _shareConfig.BindAddOnAfter = _config.GetValue(AngularConst.BindAddOnAfter);
            _shareConfig.AddOnBeforeIcon ??= _config.GetValue<AntDesignIcon?>(UiConst.AddOnBeforeIcon);
            if (_shareConfig.BindAddOnBeforeIcon.IsEmpty())
                _shareConfig.BindAddOnBeforeIcon = _config.GetValue(AngularConst.BindAddOnBeforeIcon);
            _shareConfig.AddOnAfterIcon ??= _config.GetValue<AntDesignIcon?>(UiConst.AddOnAfterIcon);
            if (_shareConfig.BindAddOnAfterIcon.IsEmpty())
                _shareConfig.BindAddOnAfterIcon = _config.GetValue(AngularConst.BindAddOnAfterIcon);
            if (_shareConfig.Prefix.IsEmpty())
                _shareConfig.Prefix = _config.GetValue(UiConst.Prefix);
            if (_shareConfig.BindPrefix.IsEmpty())
                _shareConfig.BindPrefix = _config.GetValue(AngularConst.BindPrefix);
            if (_shareConfig.Suffix.IsEmpty())
                _shareConfig.Suffix = _config.GetValue(UiConst.Suffix);
            if (_shareConfig.BindSuffix.IsEmpty())
                _shareConfig.BindSuffix = _config.GetValue(AngularConst.BindSuffix);
            _shareConfig.PrefixIcon ??= _config.GetValue<AntDesignIcon?>(UiConst.PrefixIcon);
            if (_shareConfig.BindPrefixIcon.IsEmpty())
                _shareConfig.BindPrefixIcon = _config.GetValue(AngularConst.BindPrefixIcon);
            _shareConfig.SuffixIcon ??= _config.GetValue<AntDesignIcon?>(UiConst.SuffixIcon);
            if (_shareConfig.BindSuffixIcon.IsEmpty())
                _shareConfig.BindSuffixIcon = _config.GetValue(AngularConst.BindSuffixIcon);
            _shareConfig.Size ??= _config.GetValue<InputSize?>(UiConst.Size);
            if (_shareConfig.BindSize.IsEmpty())
                _shareConfig.BindSize = _config.GetValue(AngularConst.BindSize);
            _shareConfig.Status ??= _config.GetValue<FormControlStatus?>(UiConst.Status);
            if (_shareConfig.BindStatus.IsEmpty())
                _shareConfig.BindStatus = _config.GetValue(AngularConst.BindStatus);
            _shareConfig.AllowClear = IsAllowClear();
            _shareConfig.IsPassword = IsPassword();
        }

        /// <summary>
        /// 是否允许清除
        /// </summary>
        private bool IsAllowClear()
        {
            if (IsFormControl())
                return false;
            if (_config.GetValue(AngularConst.NgModel).IsEmpty())
                return false;
            var isAllowClear = _config.GetValue<bool?>(UiConst.AllowClear);
            if (isAllowClear == null)
            {
                var options = NgZorroOptionsService.GetOptions();
                if (options.EnableAllowClear)
                    return true;
            }
            return isAllowClear.SafeValue();
        }

        /// <summary>
        /// 是否表单控件
        /// </summary>
        private bool IsFormControl()
        {
            if (_config.GetValue(UiConst.FormControl).IsEmpty() == false)
                return true;
            if (_config.GetValue(UiConst.FormControlName).IsEmpty() == false)
                return true;
            if (_config.GetValue(AngularConst.BindFormControlName).IsEmpty() == false)
                return true;
            return false;
        }

        /// <summary>
        /// 是否密码类型
        /// </summary>
        private bool IsPassword()
        {
            return _config.GetValue<InputType?>(UiConst.Type) == InputType.Password;
        }

        /// <summary>
        /// 自动创建nz-input-group
        /// </summary>
        private void AutoCreateInputGroup()
        {
            if (IsAutoCreateInputGroup() == false)
                return;
            AutoCreateInputGroup(true);
        }

        /// <summary>
        /// 是否自动创建nz-input-group
        /// </summary>
        private bool IsAutoCreateInputGroup()
        {
            if (_shareConfig.AutoCreateInputGroup == false)
                return false;
            if (string.IsNullOrWhiteSpace(_shareConfig.AddOnBefore) == false)
                return true;
            if (string.IsNullOrWhiteSpace(_shareConfig.BindAddOnBefore) == false)
                return true;
            if (string.IsNullOrWhiteSpace(_shareConfig.AddOnAfter) == false)
                return true;
            if (string.IsNullOrWhiteSpace(_shareConfig.BindAddOnAfter) == false)
                return true;
            if (_shareConfig.AddOnBeforeIcon != null)
                return true;
            if (string.IsNullOrWhiteSpace(_shareConfig.BindAddOnBeforeIcon) == false)
                return true;
            if (_shareConfig.AddOnAfterIcon != null)
                return true;
            if (string.IsNullOrWhiteSpace(_shareConfig.BindAddOnAfterIcon) == false)
                return true;
            if (string.IsNullOrWhiteSpace(_shareConfig.Prefix) == false)
                return true;
            if (string.IsNullOrWhiteSpace(_shareConfig.BindPrefix) == false)
                return true;
            if (string.IsNullOrWhiteSpace(_shareConfig.Suffix) == false)
                return true;
            if (string.IsNullOrWhiteSpace(_shareConfig.BindSuffix) == false)
                return true;
            if (_shareConfig.PrefixIcon != null)
                return true;
            if (string.IsNullOrWhiteSpace(_shareConfig.BindPrefixIcon) == false)
                return true;
            if (_shareConfig.SuffixIcon != null)
                return true;
            if (string.IsNullOrWhiteSpace(_shareConfig.BindSuffixIcon) == false)
                return true;
            return false;
        }

        /// <summary>
        /// 设置ngIf*
        /// </summary>
        private void SetNgIf()
        {
            var value = _config.GetValueFromAttributes(AngularConst.NgIf);
            if (value.IsEmpty())
                return;
            if (_shareConfig.AllowClear == false)
                return;
            _shareConfig.NgIf = value;
            _config.RemoveAttribute(AngularConst.NgIf);
        }
    }

    /// <summary>
    /// 输入框服务
    /// </summary>
    public class InputService
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;
        /// <summary>
        /// 输入框组样式类
        /// </summary>
        private readonly string _inputGroupClass;

        /// <summary>
        /// 初始化输入框服务
        /// </summary>
        /// <param name="config">配置</param>
        /// <param name="inputGroupClass">输入框组样式类</param>
        public InputService(Config config, string inputGroupClass = null)
        {
            _config = config;
            _inputGroupClass = inputGroupClass;
        }

        /// <summary>
        /// 初始化
        /// </summary>
        public void Init()
        {
            LoadExpression();
            InitValidationService();
            InitFormShareService();
            InitFormItemShareService();
            InitInputGroupShareService();
        }

        /// <summary>
        /// 加载表达式
        /// </summary>
        private void LoadExpression()
        {
            var loader = new InputExpressionLoader();
            loader.Load(_config);
        }

        /// <summary>
        /// 初始化验证服务
        /// </summary>
        private void InitValidationService()
        {
            var service = new ValidationService(_config);
            service.Init();
        }

        /// <summary>
        /// 初始化表单共享服务
        /// </summary>
        private void InitFormShareService()
        {
            var service = new FormShareService(_config);
            service.Init();
        }

        /// <summary>
        /// 初始化表单项共享服务
        /// </summary>
        private void InitFormItemShareService()
        {
            var service = new FormItemShareService(_config);
            service.Init();
            service.InitId();
        }

        /// <summary>
        /// 初始化输入框组合共享服务
        /// </summary>
        private void InitInputGroupShareService()
        {
            var service = new InputGroupShareService(_config);
            service.Init();
            service.SetInputId(GetId());
            service.SetClass(_inputGroupClass);
        }

        /// <summary>
        /// 获取输入框标识
        /// </summary>
        private string GetId()
        {
            var id = _config.GetValue(UiConst.Id);
            return id.IsEmpty() ? Util.Helpers.Id.Create() : id;
        }
    }

    /// <summary>
    /// 行高模型
    /// </summary>
    public class RowsModel
    {
        /// <summary>
        /// 最小行数
        /// </summary>
        public int? MinRows { get; set; }
        /// <summary>
        /// 最大行数
        /// </summary>
        public int? MaxRows { get; set; }

        /// <summary>
        /// 输出json
        /// </summary>
        public string ToJson()
        {
            var result = Json.ToJson(this, new JsonSerializerOptions
            {
                DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
                PropertyNamingPolicy = JsonNamingPolicy.CamelCase
            }, true);
            return result == "{}" ? null : result;
