    #region Label
    /// <summary>
    /// 标签生成器
    /// </summary>
    public class LabelBuilder : AngularTagBuilder
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化标签生成器
        /// </summary>
        /// <param name="config">配置</param>
        public LabelBuilder(Config config) : base(config, "span")
        {
            _config = config;
        }

        /// <summary>
        /// 配置文本
        /// </summary>
        public LabelBuilder Text()
        {
            return SetText(_config.GetValue(UiConst.Text));
        }

        /// <summary>
        /// 配置标题
        /// </summary>
        public LabelBuilder Title()
        {
            return SetText(_config.GetValue(UiConst.Title));
        }

        /// <summary>
        /// 配置内容
        /// </summary>
        private LabelBuilder SetText(string value)
        {
            var options = NgZorroOptionsService.GetOptions();
            if (value.IsEmpty())
                return this;
            if (options.EnableI18n)
            {
                this.AppendContentByI18n(value);
                return this;
            }
            AppendContent(value);
            return this;
        }

        /// <inheritdoc />
        public override void Config()
        {
            base.Config();
            Text().Title();
        }
    }

    /// <summary>
    /// 标签渲染器
    /// </summary>
    public class LabelRender : RenderBase
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化标签渲染器
        /// </summary>
        /// <param name="config">配置</param>
        public LabelRender(Config config)
        {
            _config = config ?? throw new ArgumentNullException(nameof(config));
        }

        /// <summary>
        /// 获取标签生成器
        /// </summary>
        protected override TagBuilder GetTagBuilder()
        {
            var builder = new LabelBuilder(_config);
            builder.Config();
            return builder;
        }

        /// <inheritdoc />
        public override IHtmlContent Clone()
        {
            return new LabelRender(_config.Copy());
        }
    }

    /// <summary>
    /// 标签,生成的标签为&lt;span&gt;&lt;/span&gt;
    /// </summary>
    [HtmlTargetElement("label")]
    public class LabelTagHelper : AngularTagHelperBase
    {
        /// <summary>
        /// 配置
        /// </summary>
        private Config _config;
        /// <summary>
        /// 内容文本,支持i18n
        /// </summary>
        public string Text { get; set; }
        /// <summary>
        /// 属性表达式
        /// </summary>
        public ModelExpression For { get; set; }

        /// <inheritdoc />
        protected override void ProcessBefore(TagHelperContext context, TagHelperOutput output)
        {
            _config = new Config(context, output);
            LoadExpression();
        }

        /// <summary>
        /// 加载表达式
        /// </summary>
        private void LoadExpression()
        {
            var loader = new DisplayExpressionLoader();
            loader.Load(_config);
        }

        /// <inheritdoc />
        protected override IRender GetRender(TagHelperContext context, TagHelperOutput output, TagHelperContent content)
        {
            _config.Content = content;
            return new LabelRender(_config);
        }
    }

