    /// <summary>
    /// 单选框标签生成器
    /// </summary>
    public class RadioBuilder : FormControlBuilderBase<RadioBuilder>
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;
        /// <summary>
        /// 单选框组合共享配置
        /// </summary>
        private readonly RadioGroupShareConfig _shareConfig;

        /// <summary>
        /// 初始化单选框标签生成器
        /// </summary>
        /// <param name="config">配置</param>
        public RadioBuilder(Config config) : base(config, "label")
        {
            _config = config;
            _shareConfig = GetShareConfig();
        }

        /// <summary>
        /// 获取单选框组合共享配置
        /// </summary>
        private RadioGroupShareConfig GetShareConfig()
        {
            return _config.GetValueFromItems<RadioGroupShareConfig>() ?? new RadioGroupShareConfig();
        }

        /// <summary>
        /// 配置名称
        /// </summary>
        public override RadioBuilder Name()
        {
            if (_shareConfig.IsAutoCreateRadioGroup == true)
                return this;
            return base.Name();
        }

        /// <summary>
        /// 配置自动获取焦点
        /// </summary>
        public RadioBuilder AutoFocus()
        {
            AttributeIfNotEmpty("[nzAutoFocus]", _config.GetValue(UiConst.AutoFocus));
            return this;
        }

        /// <summary>
        /// 配置禁用
        /// </summary>
        public RadioBuilder Disabled()
        {
            AttributeIfNotEmpty("[nzDisabled]", _config.GetValue(UiConst.Disabled));
            return this;
        }

        /// <summary>
        /// 配置值
        /// </summary>
        public RadioBuilder Value()
        {
            AttributeIfNotEmpty("nzValue", _config.GetValue(UiConst.Value));
            AttributeIfNotEmpty("[nzValue]", _config.GetValue(AngularConst.BindValue));
            return this;
        }

        /// <summary>
        /// 配置标签
        /// </summary>
        public RadioBuilder Label()
        {
            var options = NgZorroOptionsService.GetOptions();
            var text = _config.GetValue(UiConst.Label);
            if (text.IsEmpty() == false)
            {
                if (options.EnableI18n)
                {
                    this.AppendContentByI18n(text);
                    return this;
                }
                SetContent(_config.GetValue(UiConst.Label));
                return this;
            }
            var bindLabel = _config.GetValue(AngularConst.BindLabel);
            if (string.IsNullOrWhiteSpace(bindLabel))
                return this;
            SetContent($"{{{{{bindLabel}}}}}");
            return this;
        }

        /// <summary>
        /// 配置事件
        /// </summary>
        public RadioBuilder Events()
        {
            return this;
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.ConfigBase(_config);
            NgModel().FormControl().OnModelChange()
                .TableEdit().SpaceItem()
                .Name().AutoFocus().Disabled().Value()
                .Label().Events();
        }

        /// <summary>
        /// 配置模型绑定
        /// </summary>
        public override RadioBuilder NgModel()
        {
            if (_shareConfig.IsAutoCreateRadioGroup != true)
                base.NgModel();
            return this;
        }

        /// <summary>
        /// 数据绑定扩展
        /// </summary>
        public void Extend()
        {
            Attribute("[nzValue]", "item.value");
            Attribute("[nzDisabled]", "item.disabled");
            var options = NgZorroOptionsService.GetOptions();
            if (options.EnableI18n)
            {
                SetContent("{{item.text|i18n}}");
                return;
            }
            SetContent("{{item.text}}");
        }

        /// <summary>
        /// 配置模型变更事件
        /// </summary>
        public override RadioBuilder OnModelChange()
        {
            if (_shareConfig.IsAutoCreateRadioGroup == true)
                return this;
            return base.OnModelChange();
        }

        /// <summary>
        /// 配置间距项
        /// </summary>
        public override RadioBuilder SpaceItem()
        {
            if (FormItemShareConfig.FormItemCreated)
                return this;
            var radioGroupShareConfig = GetRadioGroupShareConfig();
            if (radioGroupShareConfig.RadioGroupCreated)
                return this;
            this.SpaceItem(FormItemShareConfig.SpaceItem);
            return this;
        }

        /// <summary>
        /// 获取输入框组合共享配置
        /// </summary>
        private RadioGroupShareConfig GetRadioGroupShareConfig()
        {
            return _config.GetValueFromItems<RadioGroupShareConfig>() ?? new RadioGroupShareConfig();
        }
    }

