    /// <summary>
    /// 分段控制器,生成的标签为&lt;nz-segmented&gt;&lt;/nz-segmented&gt;
    /// </summary>
    [HtmlTargetElement("segmented")]
    public class SegmentedTagHelper : FormControlTagHelperBase
    {
        /// <summary>
        /// 配置
        /// </summary>
        private Config _config;
        /// <summary>
        /// 扩展属性,是否启用扩展指令,当设置Url或Data属性时自动启用
        /// </summary>
        public bool EnableExtend { get; set; }
        /// <summary>
        /// 扩展属性 [autoLoad],初始化时是否自动加载数据，默认为true,设置成false则手工加载
        /// </summary>
        public string AutoLoad { get; set; }
        /// <summary>
        /// 扩展属性 [(queryParam)],查询参数
        /// </summary>
        public string QueryParam { get; set; }
        /// <summary>
        /// 扩展属性 url,Api地址
        /// </summary>
        public string Url { get; set; }
        /// <summary>
        /// 扩展属性 [url],Api地址
        /// </summary>
        public string BindUrl { get; set; }
        /// <summary>
        /// 扩展属性 [data],数据源
        /// </summary>
        public string Data { get; set; }
        /// <summary>
        /// 扩展属性 [(value)],双向绑定选项值
        /// </summary>
        public string Value { get; set; }
        /// <summary>
        /// [nzDisabled],是否禁用, 类型: boolean, 默认值: false
        /// </summary>
        public string Disabled { get; set; }
        /// <summary>
        /// nzSize,尺寸，可选值: 'large'|'small'|'default', 默认值: default
        /// </summary>
        public InputSize Size { get; set; }
        /// <summary>
        /// [nzSize],尺寸，可选值: 'large'|'small'|'default', 默认值: default
        /// </summary>
        public string BindSize { get; set; }
        /// <summary>
        /// [nzOptions],选项列表,类型: string[] | number[] | Array&lt;{ label: string; value: string | number; icon: string; disabled?: boolean; useTemplate?: boolean }>
        /// </summary>
        public string Options { get; set; }
        /// <summary>
        /// [nzBlock],是否将宽度调整为父元素宽度,类型: boolean, 默认值: false
        /// </summary>
        public string Block { get; set; }
        /// <summary>
        /// [nzLabelTemplate],自定义渲染选项, 类型: TemplateRef&lt;{ $implicit: NzSegmentedOption; index: number }>
        /// </summary>
        public string LabelTemplate { get; set; }
        /// <summary>
        /// (nzValueChange),选中项索引变化事件,参数为选中项的索引, 类型: EventEmitter&lt;number>
        /// </summary>
        public string OnIndexChange { get; set; }
        /// <summary>
        /// (valueChange),扩展事件, 选中值变化事件,参数为选中项的值, 类型: EventEmitter&lt;any>
        /// </summary>
        public string OnValueChange { get; set; }
        /// <summary>
        /// 扩展事件 (onLoad),数据加载完成事件,类型: EventEmitter&lt;any>,参数为服务端返回结果
        /// </summary>
        public string OnLoad { get; set; }

        /// <inheritdoc />
        protected override void ProcessBefore(TagHelperContext context, TagHelperOutput output)
        {
            _config = new Config(context, output);
            var service = new SegmentedService(_config);
            service.Init();
        }

        /// <inheritdoc />
        protected override IRender GetRender(TagHelperContext context, TagHelperOutput output, TagHelperContent content)
        {
            _config.Content = content;
            return new SegmentedRender(_config);
        }
    }

