        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.Config();
            ConfigForm().NzId().Name().CompareWith().AutoClearSearchValue().AllowClear()
                .Borderless().Open().AutoFocus().Disabled()
                .DropdownClassName().DropdownStyle().DropdownMatchSelectWidth()
                .CustomTemplate().ServerSearch().FilterOption().MaxMultipleCount()
                .Mode().NotFoundContent().Placeholder()
                .ShowArrow().ShowSearch().Size().DropdownRender()
                .SuffixIcon().RemoveIcon().ClearIcon().MenuItemSelectedIcon()
                .TokenSeparators().Loading().MaxTagCount().MaxTagPlaceholder()
                .Options().OptionHeightPx().OptionOverflowSize()
                .AutoLoad().QueryParam().Sort().Url().Data()
                .Events();
            ConfigDefaultOptionText();
            EnableExtend();
        }

        /// <summary>
        /// 配置默认项文本
        /// </summary>
        private void ConfigDefaultOptionText()
        {
            var value = _config.AllAttributes[UiConst.DefaultOptionText]?.Value?.ToString();
            var optionBuilder = new OptionBuilder(_config);
            if (string.IsNullOrEmpty(value) == false)
            {
                optionBuilder.Label(value);
                AppendContent(optionBuilder);
                return;
            }
            if (IsEnableDefaultOptionText() == false)
                return;
            optionBuilder.BindLabel($"'{I18nKeys.DefaultOptionText}'|i18n");
            AppendContent(optionBuilder);
        }

        /// <summary>
        /// 是否启用默认项文本
        /// </summary>
        private bool IsEnableDefaultOptionText()
        {
            var mode = _config.GetValue<SelectMode?>(UiConst.Mode);
            if (mode == SelectMode.Multiple || mode == SelectMode.Tags)
                return false;
            var showDefaultOption = _config.GetValue<bool?>(UiConst.ShowDefaultOption);
            if (showDefaultOption != null)
                return showDefaultOption.SafeValue();
            var options = NgZorroOptionsService.GetOptions();
            return options is { EnableDefaultOptionText: true };
        }

        /// <summary>
        /// 启用扩展
        /// </summary>
        public SelectBuilder EnableExtend()
        {
            if (IsEnableExtend() == false)
                return this;
            Attribute($"#{ExtendId}", "xSelectExtend");
            Attribute("x-select-extend");
            EnableLoading();
            EnableSearchKeyword();
            EnableScrollLoad();
            ConfigOption();
            ConfigOptionGroup();
            return this;
        }

        /// <summary>
        /// 是否启用基础扩展
        /// </summary>
        public bool IsEnableExtend()
        {
            if (GetEnableExtend() == false)
            {
                return false;
            }
            return GetEnableExtend() == true ||
                   GetUrl().IsEmpty() == false ||
                   GetBindUrl().IsEmpty() == false ||
                   GetData().IsEmpty() == false ||
                   IsEnableDefaultOptionText();
        }

        /// <summary>
        /// 获取启用扩展属性
        /// </summary>
        private bool? GetEnableExtend()
        {
            return _config.GetValue<bool?>(UiConst.EnableExtend);
        }

        /// <summary>
        /// 获取地址
        /// </summary>
        private string GetUrl()
        {
            return _config.GetValue(UiConst.Url);
        }

        /// <summary>
        /// 获取地址
        /// </summary>
        private string GetBindUrl()
        {
            return _config.GetValue(AngularConst.BindUrl);
        }

        /// <summary>
        /// 获取数据源
        /// </summary>
        private string GetData()
        {
            return _config.GetValue(UiConst.Data);
        }

        /// <summary>
        /// 启用加载状态
        /// </summary>
        private void EnableLoading()
        {
            if (GetUrl().IsEmpty() && GetBindUrl().IsEmpty())
                return;
            Loading($"{ExtendId}.loading");
        }

        /// <summary>
        /// 启用搜索关键字
        /// </summary>
        private void EnableSearchKeyword()
        {
            var result = _config.GetValue<bool?>(UiConst.SearchKeyword);
            if (result != true)
                return;
            ShowSearch("true");
            ServerSearch("true");
            OnSearch($"{ExtendId}.search($event)");
            AttributeIfNotEmpty("[searchDelay]", _config.GetValue(UiConst.SearchDelay));
        }

        /// <summary>
        /// 启用滚动加载
        /// </summary>
        private void EnableScrollLoad()
        {
            var result = _config.GetValue<bool?>(UiConst.ScrollLoad);
            if (result != true)
                return;
            ServerSearch("true");
            OnScrollToBottom($"{ExtendId}.scrollToBottom()");
            AttributeIfNotEmpty("[isScrollLoad]", "true");
            ConfigDropdownTemplate();
        }

        /// <summary>
        /// 配置下拉加载图标
        /// </summary>
        private void ConfigDropdownTemplate()
        {
            var templateId = $"tpl_{ExtendId}";
            DropdownRender(templateId);
            var templateBuilder = new TemplateBuilder(_config);
            templateBuilder.Id(templateId);
            var spinBuilder = new SpinBuilder(_config);
            spinBuilder.NgIf($"{ExtendId}.loading");
            templateBuilder.AppendContent(spinBuilder);
            PostBuilder = templateBuilder;
        }

        /// <summary>
        /// 配置选项
        /// </summary>
        private void ConfigOption()
        {
            var containerBuilder = new ContainerBuilder(_config);
            containerBuilder.NgIf($"!{ExtendId}.isGroup");
            var optionBuilder = new OptionBuilder(_config);
            containerBuilder.AppendContent(optionBuilder);
            optionBuilder.NgFor($"let item of {ExtendId}.options");
            ConfigBindLabel(optionBuilder);
            optionBuilder.BindValue("item.value");
            optionBuilder.Disabled("item.disabled");
            AppendContent(containerBuilder);
        }

        /// <summary>
        /// 配置标签文本
        /// </summary>
        private void ConfigBindLabel(OptionBuilder optionBuilder)
        {
            var options = NgZorroOptionsService.GetOptions();
            if (options.EnableI18n)
            {
                optionBuilder.BindLabel("item.text|i18n");
                return;
            }
            optionBuilder.BindLabel("item.text");
        }

        /// <summary>
        /// 配置选项组
        /// </summary>
        private void ConfigOptionGroup()
        {
            var containerBuilder = new ContainerBuilder(_config);
            containerBuilder.NgIf($"{ExtendId}.isGroup");
            var groupBuilder = new OptionGroupBuilder(_config);
            containerBuilder.AppendContent(groupBuilder);
            groupBuilder.NgFor($"let group of {ExtendId}.optionGroups");
            ConfigGroupBindLabel(groupBuilder);
            var optionBuilder = new OptionBuilder(_config);
            groupBuilder.AppendContent(optionBuilder);
            optionBuilder.NgFor("let item of group.value");
            ConfigBindLabel(optionBuilder);
            optionBuilder.BindValue("item.value");
            optionBuilder.Disabled("item.disabled");
            AppendContent(containerBuilder);
        }

        /// <summary>
        /// 配置选项组标签文本
        /// </summary>
        private void ConfigGroupBindLabel(OptionGroupBuilder groupBuilder)
        {
            var options = NgZorroOptionsService.GetOptions();
            if (options.EnableI18n)
            {
                groupBuilder.BindLabel("group.text|i18n");
                return;
            }
            groupBuilder.BindLabel("group.text");
        }
    }

    /// <summary>
    /// 选择框表达式加载器
    /// </summary>
    public class SelectExpressionLoader : NgZorroExpressionLoaderBase
    {
        /// <summary>
        /// 加载模型信息
        /// </summary>
        /// <param name="config">配置</param>
        /// <param name="info">模型表达式信息</param>
        protected override void Load(Config config, ModelExpressionInfo info)
        {
            var formShareConfig = GetFormShareConfig(config);
            LoadLabel(config, info, formShareConfig);
            LoadId(config, info);
            LoadName(config, info);
            LoadNgModel(config, info);
            LoadData(config, info);
            LoadRequired(config, info);
        }

        /// <summary>
        /// 获取表单共享配置
        /// </summary>
        private FormShareConfig GetFormShareConfig(Config config)
        {
            return config.GetValueFromItems<FormShareConfig>() ?? new FormShareConfig();
        }

        /// <summary>
        /// 加载标签
        /// </summary>
        protected virtual void LoadLabel(Config config, ModelExpressionInfo info, FormShareConfig formShareConfig)
        {
            if (formShareConfig.FormCreated)
                config.SetAttribute(UiConst.LabelText, info.DisplayName, false);
        }

        /// <summary>
        /// 加载标识
        /// </summary>
        protected virtual void LoadId(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(UiConst.Id, GeKebaberizePropertyName(config, info), false);
        }

        /// <summary>
        /// 加载名称
        /// </summary>
        protected virtual void LoadName(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(UiConst.Name, GeKebaberizePropertyName(config, info), false);
        }

        /// <summary>
        /// 加载模型绑定
        /// </summary>
        protected virtual void LoadNgModel(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(AngularConst.NgModel, info.SafePropertyName, false);
        }

        /// <summary>
        /// 加载数据源
        /// </summary>
        protected virtual void LoadData(Config config, ModelExpressionInfo info)
        {
            LoadBool(config, info);
            LoadEnum(config, info);
        }

        /// <summary>
        /// 加载布尔值
        /// </summary>
        protected virtual void LoadBool(Config config, ModelExpressionInfo info)
        {
            if (info.IsBool == false)
                return;
            config.SetAttribute(UiConst.Data, GetBoolData(), false);
        }

        /// <summary>
        /// 获取布尔类型数据
        /// </summary>
        private string GetBoolData()
        {
            var result = new StringBuilder();
            result.Append("[{");
            result.Append($"'text':'{GetYes()}','value':true,'sortId':1");
            result.Append("},");
            result.Append("{");
            result.Append($"'text':'{GetNo()}','value':false,'sortId':2");
            result.Append("}]");
            return result.ToString();
        }

        /// <summary>
        /// 获取yes文本
        /// </summary>
        private string GetYes()
        {
            var options = NgZorroOptionsService.GetOptions();
            return options.EnableI18n ? I18nKeys.Yes : "是";
        }

        /// <summary>
        /// 获取no文本
        /// </summary>
        private string GetNo()
        {
            var options = NgZorroOptionsService.GetOptions();
            return options.EnableI18n ? I18nKeys.No : "否";
        }

        /// <summary>
        /// 加载枚举值
        /// </summary>
        protected virtual void LoadEnum(Config config, ModelExpressionInfo info)
        {
            if (info.IsEnum == false)
                return;
            var items = Util.Helpers.Enum.GetItems(info.ModelType);
            var options = new JsonSerializerOptions
            {
                DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
                Encoder = JavaScriptEncoder.Create(UnicodeRanges.All)
            };
            var result = Util.Helpers.Json.ToJson(items, options, toSingleQuotes: true);
            config.SetAttribute(UiConst.Data, result, false);
        }

        /// <summary>
        /// 加载必填项验证
        /// </summary>
        protected virtual void LoadRequired(Config config, ModelExpressionInfo info)
        {
            if (info.IsRequired == false)
                return;
            config.SetAttribute(UiConst.Required, "true", false);
            config.SetAttribute(UiConst.RequiredMessage, info.RequiredMessage, false);
        }
    }

    /// <summary>
    /// 选择器服务
    /// </summary>
    public class SelectService
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;
        /// <summary>
        /// 是否禁用自动设置表单标签 nzFor
        /// </summary>
        private bool _isDisableAutoNzFor;

        /// <summary>
        /// 初始化选择器服务
        /// </summary>
        /// <param name="config">配置</param>
        public SelectService(Config config)
        {
            _config = config;
        }

        /// <summary>
        /// 禁用自动设置表单标签 nzFor
        /// </summary>
        public void DisableAutoNzFor()
        {
            _isDisableAutoNzFor = true;
        }

        /// <summary>
        /// 初始化
        /// </summary>
        public void Init()
        {
            LoadExpression();
            InitValidationService();
            InitFormShareService();
            InitFormItemShareService();
        }

        /// <summary>
        /// 加载表达式
        /// </summary>
        private void LoadExpression()
        {
            var loader = new SelectExpressionLoader();
            loader.Load(_config);
        }

        /// <summary>
        /// 初始化验证服务
        /// </summary>
        private void InitValidationService()
        {
            var service = new ValidationService(_config);
            service.Init();
        }

        /// <summary>
        /// 初始化表单共享服务
        /// </summary>
        private void InitFormShareService()
        {
            var service = new FormShareService(_config);
            service.Init();
        }

        /// <summary>
        /// 初始化表单项共享服务
        /// </summary>
        private void InitFormItemShareService()
        {
            var service = new FormItemShareService(_config);
            if (_isDisableAutoNzFor)
                service.DisableAutoNzFor();
            service.Init();
            service.InitId();
        }
    }

