        /// <summary>
        /// nzSize,选择框大小，可选值: 'large'|'small'|'default',默认值: 'default'
        /// </summary>
        public InputSize Size { get; set; }
        /// <summary>
        /// [nzSize],选择框大小，可选值: 'large'|'small'|'default',默认值: 'default'
        /// </summary>
        public string BindSize { get; set; }
        /// <summary>
        /// nzSuffixIcon,选择框后缀图标,类型: string | TemplateRef&lt;/any&gt;
        /// </summary>
        public AntDesignIcon SuffixIcon { get; set; }
        /// <summary>
