        /// <summary>
        /// nzUnCheckedChildren,未选中时显示的标签内容,类型: string | TemplateRef&lt;void>
        /// </summary>
        public string UncheckedChildren { get; set; }
        /// <summary>
        /// [nzUnCheckedChildren],未选中时显示的标签内容,类型: string | TemplateRef&lt;void>
        /// </summary>
        public string BindUncheckedChildren { get; set; }
        /// <summary>
        /// nzSize,可选值: 'small' | 'default',默认值: 'default'
        /// </summary>
