    /// <summary>
    /// 非编辑模式非第一列内容加载器
    /// </summary>
    public class NoEditContentLoader : ITableColumnContentLoader
    {
        /// <inheritdoc />
        public void Load(TableColumnBuilder builder, IHtmlContent content)
        {
            content = GetContent(builder, content);
            builder.SetContent(content);
        }

        /// <summary>
        /// 获取内容
        /// </summary>
        private IHtmlContent GetContent(TableColumnBuilder builder, IHtmlContent htmlContent)
        {
            var content = builder.GetConfig().Content;
            if (content.IsEmpty() == false)
                return content;
            return htmlContent;
        }
    }

    /// <summary>
    /// 非编辑模式第一列内容加载器
    /// </summary>
    public class NoEditFirstColumnContentLoader : ITableColumnContentLoader
    {
        /// <summary>
        /// 表格列选择框创建服务
        /// </summary>
        private readonly ISelectCreateService _selectCreateService;

        /// <summary>
        /// 初始化非编辑模式第一列内容加载器
        /// </summary>
        /// <param name="service">表格列选择框创建服务</param>
        public NoEditFirstColumnContentLoader(ISelectCreateService service)
        {
            _selectCreateService = service ?? throw new ArgumentNullException(nameof(service));
        }

        /// <inheritdoc />
        public virtual void Load(TableColumnBuilder builder, IHtmlContent displayContent)
        {
            displayContent = GetDisplayContent(builder, displayContent);
            AddCheckbox(builder, displayContent);
            AddRadio(builder, displayContent);
            AddLineNumber(builder);
            if (_selectCreateService.IsAddContentToSelect(builder))
                return;
            AddContent(builder, displayContent);
        }

        /// <summary>
        /// 获取显示内容
        /// </summary>
        protected virtual IHtmlContent GetDisplayContent(TableColumnBuilder builder, IHtmlContent htmlContent)
        {
            var content = builder.GetConfig().Content;
            if (content.IsEmpty() == false)
                return content;
            return htmlContent;
        }

        /// <summary>
        /// 添加复选框
        /// </summary>
        protected virtual void AddCheckbox(TableColumnBuilder builder, IHtmlContent content)
        {
            if (builder.GetTableColumnShareConfig().IsShowCheckbox == false)
                return;
            _selectCreateService.CreateCheckbox(builder, content);
        }

        /// <summary>
        /// 添加单选框
        /// </summary>
        protected virtual void AddRadio(TableColumnBuilder builder, IHtmlContent content)
        {
            if (builder.GetTableColumnShareConfig().IsShowCheckbox)
                return;
            if (builder.GetTableColumnShareConfig().IsShowRadio == false)
                return;
            _selectCreateService.CreateRadio(builder, content);
        }

        /// <summary>
        /// 添加序号
        /// </summary>
        protected virtual void AddLineNumber(TableColumnBuilder builder)
        {
            if (builder.GetTableColumnShareConfig().IsShowLineNumber == false)
                return;
            var lineNumberBuilder = new TableColumnBuilder(builder.GetConfig(), builder.GetTableColumnShareConfig());
            lineNumberBuilder.AddLineNumber();
            if (builder.PreBuilder == null)
            {
                builder.PreBuilder = lineNumberBuilder;
                return;
            }
            builder.PreBuilder.PostBuilder = lineNumberBuilder;
        }

        /// <summary>
        /// 添加内容
        /// </summary>
        protected virtual void AddContent(TableColumnBuilder builder, IHtmlContent content)
        {
            builder.SetContent(content);
        }
    }

    /// <summary>
    /// 表格单元格布尔内容
    /// </summary>
    public class TableColumnBoolContent : ITableColumnContent
    {
        /// <inheritdoc />
        public IHtmlContent GetDisplayContent(TableColumnBuilder builder)
        {
            var column = builder.GetConfig().GetValue(UiConst.Column);
            if (column.IsEmpty())
                return null;
            var options = NgZorroOptionsService.GetOptions();
            var result = GetResult(options, column);
            return new StringHtmlContent(result);
        }

        /// <summary>
        /// 获取结果
        /// </summary>
        private string GetResult(NgZorroOptions options, string column)
        {
            if (options.GetTableColumnBoolContentAction != null)
                return options.GetTableColumnBoolContentAction(column);
            var result = new StringBuilder();
            result.AppendLine($"<i *ngIf=\"!row.{column}\" nz-icon nzType=\"close\"></i>");
            result.AppendLine($"<i *ngIf=\"row.{column}\" nz-icon nzType=\"check\"></i>");
            return result.ToString();
        }
    }

    /// <summary>
    /// 表格单元格内容服务
    /// </summary>
    public class TableColumnContentService
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;
        /// <summary>
        /// 表格列选择框创建服务
        /// </summary>
        private readonly ISelectCreateService _service;

        /// <summary>
        /// 初始化表格单元格内容
        /// </summary>
        /// <param name="builder">表格单元格标签生成器</param>
        /// <param name="service">表格列选择框创建服务</param>
        public TableColumnContentService(TableColumnBuilder builder, ISelectCreateService service)
        {
            Builder = builder ?? throw new ArgumentNullException(nameof(builder));
            _service = service ?? throw new ArgumentNullException(nameof(service));
            _config = builder.GetConfig();
            ShareConfig = builder.GetTableColumnShareConfig();
        }

        /// <summary>
        /// 表格单元格标签生成器
        /// </summary>
        protected TableColumnBuilder Builder { get; }

        /// <summary>
        /// 表格列共享配置
        /// </summary>
        protected TableColumnShareConfig ShareConfig { get; }

        /// <summary>
        /// 配置内容
        /// </summary>
        public void Config()
        {
            var displayContent = GetDisplayContent();
            var loader = CreateContentLoader();
            loader.Load(Builder, displayContent);
        }

        /// <summary>
        /// 获取显示内容
        /// </summary>
        private IHtmlContent GetDisplayContent()
        {
            var content = GetTableColumnContent();
            return content.GetDisplayContent(Builder);
        }

        /// <summary>
        /// 获取表格单元格内容
        /// </summary>
        private ITableColumnContent GetTableColumnContent()
        {
            var type = _config.GetValue<TableColumnType?>(UiConst.Type);
            switch (type)
            {
                case TableColumnType.Bool:
                    return new TableColumnBoolContent();
                case TableColumnType.Date:
                    return new TableColumnDateContent();
                case TableColumnType.Enum:
                    return new TableColumnEnumContent();
                default:
                    return new TableColumnTextContent();
            }
        }

        /// <summary>
        /// 创建表格单元格内容加载器
        /// </summary>
        private ITableColumnContentLoader CreateContentLoader()
        {
            if (IsEdit)
            {
                if (ShareConfig.IsFirst)
                    return new EditFirstColumnContentLoader(_service);
                return new EditContentLoader();
            }
            if (ShareConfig.IsFirst)
                return new NoEditFirstColumnContentLoader(_service);
            return new NoEditContentLoader();
        }

        /// <summary>
        /// 是否编辑模式
        /// </summary>
        private bool IsEdit => _config.GetValue<bool>(UiConst.IsEdit);
    }

    /// <summary>
    /// 表格单元格日期内容
    /// </summary>
    public class TableColumnDateContent : ITableColumnContent
    {
        /// <inheritdoc />
        public IHtmlContent GetDisplayContent(TableColumnBuilder builder)
        {
            var config = builder.GetConfig();
            var column = config.GetValue(UiConst.Column);
            if (column.IsEmpty())
                return null;
            var result = GetResult(config, column);
            return new StringHtmlContent(result);
        }

        /// <summary>
        /// 获取结果
        /// </summary>
        private string GetResult(Config config, string column)
        {
            var result = new StringBuilder();
            result.Append("{{");
            result.Append($"row.{column}|date:'{GetFormat(config)}'");
            result.Append("}}");
            return result.ToString();
        }

        /// <summary>
        /// 获取日期格式
        /// </summary>
        private string GetFormat(Config config)
        {
            var format = config.GetValue(UiConst.DateFormat);
            if (format.IsEmpty() == false)
                return format;
            var showDateOnly = config.GetValue<bool>(UiConst.ShowDateOnly);
            if (showDateOnly)
                return "yyyy-MM-dd";
            return "yyyy-MM-dd HH:mm";
        }
    }

    /// <summary>
    /// 表格单元格枚举内容
    /// </summary>
    public class TableColumnEnumContent : ITableColumnContent
    {
        /// <inheritdoc />
        public IHtmlContent GetDisplayContent(TableColumnBuilder builder)
        {
            var column = builder.GetConfig().GetValue(UiConst.Column);
            var content = builder.GetConfig().GetValue(UiConst.EnumContent);
            return column.IsEmpty() ? null : new StringHtmlContent(content);
        }
    }

    /// <summary>
    /// 表格单元格文本内容
    /// </summary>
    public class TableColumnTextContent : ITableColumnContent
    {
        /// <inheritdoc />
        public IHtmlContent GetDisplayContent(TableColumnBuilder builder)
        {
            var config = builder.GetConfig();
            var column = config.GetValue(UiConst.Column);
            if (column.IsEmpty())
                return null;
            var columnBuilder = new StringHtmlContent($"{{{{row.{column}}}}}");
            var buttonBuilder = GetCopyToClipboardButton(config.Copy());
            if (buttonBuilder == null)
                return columnBuilder;
            var containerBuilder = new EmptyContainerTagBuilder();
            containerBuilder.AppendContent(columnBuilder);
            containerBuilder.AppendContent(buttonBuilder);
            return containerBuilder;
        }

        /// <summary>
        /// 获取复制到剪贴板按钮
        /// </summary>
        private IHtmlContent GetCopyToClipboardButton(Config config)
        {
            if (config.GetValue<bool?>(UiConst.Clipboard) != true)
                return null;
            var id = config.GetValue(UiConst.Id);
            var column = config.GetValue(UiConst.Column);
            var value = $"row.{column}";
            config.SetAttribute(UiConst.Id, $"btn_{id}_{column.Kebaberize().Replace("-", "_")}");
            config.SetAttribute(UiConst.CopyToClipboard, value);
            var buttonBuilder = new ButtonBuilder(config);
            buttonBuilder.Attribute("nz-button");
            buttonBuilder.NgIf(value);
            buttonBuilder.Id(config).CopyToClipboard().Type().Icon();
            return buttonBuilder;
        }
    }

    /// <summary>
    /// 表格列选择框创建服务
    /// </summary>
    public class TableSelectCreateService : ISelectCreateService
    {
        /// <inheritdoc />
        public void CreateCheckbox(TableColumnBuilder builder, IHtmlContent content)
        {
            var columnBuilder = new TableColumnBuilder(builder.GetConfig(), builder.GetTableColumnShareConfig());
            columnBuilder.AddCheckbox();
            builder.PreBuilder = columnBuilder;
        }

        /// <inheritdoc />
        public void CreateRadio(TableColumnBuilder builder, IHtmlContent content)
        {
            var columnBuilder = new TableColumnBuilder(builder.GetConfig(), builder.GetTableColumnShareConfig());
            columnBuilder.AddRadio();
            builder.PreBuilder = columnBuilder;
        }

        /// <summary>
        /// 是否将内容添加到选择框
        /// </summary>
        /// <param name="builder">表格单元格标签生成器</param>
        public bool IsAddContentToSelect(TableColumnBuilder builder)
        {
            return false;
        }
    }


