                return this;
            CustomColumn($"{_shareConfig.TableSettingsId}.columns");
            return this;
        }

        /// <summary>
        /// 配置事件
        /// </summary>
        public TableBuilder Events()
        {
            return OnPageIndexChange(_config.GetValue(UiConst.OnPageIndexChange))
                .OnPageSizeChange(_config.GetValue(UiConst.OnPageSizeChange))
                .OnCurrentPageDataChange(_config.GetValue(UiConst.OnCurrentPageDataChange))
                .OnQueryParams(_config.GetValue(UiConst.OnQueryParams))
                .OnLoad(_config.GetValue(UiConst.OnLoad));
        }

        /// <summary>
        /// 页索引变化事件
        /// </summary>
        protected TableBuilder OnPageIndexChange(string value)
        {
            AttributeIfNotEmpty("(nzPageIndexChange)", value);
            return this;
        }

        /// <summary>
        /// 页大小变化事件
        /// </summary>
        protected TableBuilder OnPageSizeChange(string value)
        {
            AttributeIfNotEmpty("(nzPageSizeChange)", value);
            return this;
        }

        /// <summary>
        /// 当前页数据变化事件
        /// </summary>
        protected TableBuilder OnCurrentPageDataChange(string value)
        {
            AttributeIfNotEmpty("(nzCurrentPageDataChange)", value);
            return this;
        }

        /// <summary>
        /// 查询参数变化事件
        /// </summary>
        protected TableBuilder OnQueryParams(string value)
        {
            AttributeIfNotEmpty("(nzQueryParams)", value);
            return this;
        }

        /// <summary>
        /// 数据加载完成事件
        /// </summary>
        protected TableBuilder OnLoad(string value)
        {
            AttributeIfNotEmpty("(onLoad)", value);
            return this;
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.ConfigBase(_config);
            Data().FrontPagination().Total().PageIndex().PageSize()
                .ShowPagination().PaginationPosition().PaginationType()
                .Bordered().OuterBordered().WidthConfig().Size()
                .Loading().LoadingIndicator().LoadingDelay()
                .Scroll().Title().Footer().NoResult().PageSizeOptions()
                .ShowQuickJumper().ShowSizeChanger().ShowTotal()
                .ItemRender().HideOnSinglePage().Simple().TemplateMode()
                .VirtualItemSize().VirtualMaxBufferPx().VirtualMinBufferPx().VirtualForTrackBy()
                .Layout()
                .QueryParam().Url().DeleteUrl()
                .Sort().AutoLoad().ConfigKeys()
                .CustomColumn().EnableCustomColumn()
                .Events();
            ConfigAutoCreate();
            if (_shareConfig.IsEnableExtend)
                ConfigExtend();
            ConfigEdit();
            ConfigTableSettingsExtend();
            ConfigContent();
        }

        /// <summary>
        /// 配置自动创建嵌套结构
        /// </summary>
        private void ConfigAutoCreate()
        {
            var service = new TableAutoCreateService(this);
            service.Init();
        }

        /// <summary>
        /// 配置表格扩展指令及默认属性
        /// </summary>
        protected virtual void ConfigExtend()
        {
            Attribute("x-table-extend");
            Attribute($"#{ExtendId}", "xTableExtend");
            Attribute("[nzPageSizeOptions]", $"{GetShareConfig().TableExtendId}.pageSizeOptions");
            ConfigDefault();
        }

        /// <summary>
        /// 配置默认属性
        /// </summary>
        protected void ConfigDefault()
        {
            Loading($"{ExtendId}.loading");
            ShowSizeChanger("true");
            ShowQuickJumper("true");
            FrontPagination("false");
            Total($"{ExtendId}.total");
            OnPageIndexChange($"{ExtendId}.pageIndexChange($event)");
            OnPageSizeChange($"{ExtendId}.pageSizeChange($event)");
            BindonPageIndex($"{ExtendId}.queryParam.page");
            BindonPageSize($"{ExtendId}.queryParam.pageSize");
            ShowTotal(_shareConfig.TotalTemplateId);
        }

        /// <summary>
        /// 配置编辑模式
        /// </summary>
        private void ConfigEdit()
        {
            if (_shareConfig.IsEnableEdit == false)
                return;
            Attribute("x-edit-table");
            Attribute($"#{EditId}", "xEditTable");
            AttributeIfNotEmpty("[isBatch]", _config.GetBoolValue(UiConst.IsBatchEdit));
        }

        /// <summary>
        /// 配置表格设置扩展
        /// </summary>
        private void ConfigTableSettingsExtend()
        {
            if (_shareConfig.IsEnableTableSettings == false)
                return;
            Attribute("[nzSize]", $"{_shareConfig.TableSettingsId}.size");
            Attribute("[nzBordered]", $"{_shareConfig.TableSettingsId}.bordered");
        }

        /// <summary>
        /// 配置内容
        /// </summary>
        private void ConfigContent()
        {
            if (_shareConfig.BodyAutoCreated)
                return;
            if (_shareConfig.BodyRowAutoCreated)
                return;
            _config.Content.AppendTo(this);
        }
    }

    /// <summary>
    /// 表格单元格标签生成器
    /// </summary>
    public class TableColumnBuilder : AngularTagBuilder
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;
        /// <summary>
        /// 表格列共享配置
        /// </summary>
        private readonly TableColumnShareConfig _shareConfig;

        /// <summary>
        /// 初始化表格单元格标签生成器
        /// </summary>
        public TableColumnBuilder(Config config, TableColumnShareConfig shareConfig) : base(config, "td")
        {
            _config = config;
            _shareConfig = shareConfig;
        }

        /// <summary>
        /// 获取配置
        /// </summary>
        public Config GetConfig()
        {
            return _config;
        }

        /// <summary>
        /// 获取表格列共享配置
        /// </summary>
        public TableColumnShareConfig GetTableColumnShareConfig()
        {
            return _shareConfig;
        }

        /// <summary>
        /// 配置是否显示复选框
        /// </summary>
        public TableColumnBuilder ShowCheckbox()
        {
            AttributeIfNotEmpty("[nzShowCheckbox]", _config.GetValue(UiConst.ShowCheckbox));
            return this;
        }

        /// <summary>
        /// 配置是否禁用复选框
        /// </summary>
        public TableColumnBuilder Disabled()
        {
            AttributeIfNotEmpty("[nzDisabled]", _config.GetValue(UiConst.Disabled));
            return this;
        }

        /// <summary>
        /// 配置复选框是否中间状态
        /// </summary>
        public TableColumnBuilder Indeterminate()
        {
            AttributeIfNotEmpty("[nzIndeterminate]", _config.GetValue(UiConst.Indeterminate));
            return this;
        }

        /// <summary>
        /// 配置是否选中复选框
        /// </summary>
        public TableColumnBuilder Checked()
        {
            AttributeIfNotEmpty("[nzChecked]", _config.GetValue(UiConst.Checked));
            AttributeIfNotEmpty("[(nzChecked)]", _config.GetValue(AngularConst.BindonChecked));
            return this;
        }

        /// <summary>
        /// 配置是否显示展开按钮
        /// </summary>
        public TableColumnBuilder ShowExpand()
        {
            AttributeIfNotEmpty("[nzShowExpand]", _config.GetValue(UiConst.ShowExpand));
            return this;
        }

        /// <summary>
        /// 配置是否已展开
        /// </summary>
        public TableColumnBuilder Expand()
        {
            AttributeIfNotEmpty("[nzExpand]", _config.GetValue(UiConst.Expand));
            AttributeIfNotEmpty("[(nzExpand)]", _config.GetValue(AngularConst.BindonExpand));
            return this;
        }

        /// <summary>
        /// 配置左侧距离
        /// </summary>
        public TableColumnBuilder Left()
        {
            if (_shareConfig.IsEnableFixedColumn)
            {
                BindLeft($"{_shareConfig.TableSettingsId}.isLeft('{_shareConfig.Title}')");
                return this;
            }
            Left(_shareConfig.IsLeft);
            BindLeft(_config.GetValue(AngularConst.BindLeft));
            return this;
        }

        /// <summary>
        /// 配置左侧距离
        /// </summary>
        public TableColumnBuilder Left(string value, string title)
        {
            if (_shareConfig.IsEnableFixedColumn)
            {
                BindLeft($"{_shareConfig.TableSettingsId}.isLeft('{title}')");
                return this;
            }
            Left(value);
            return this;
        }

        /// <summary>
        /// 配置左侧距离
        /// </summary>
        public TableColumnBuilder Left(string value)
        {
            if (value.IsEmpty())
                return this;
