            return this;
        }

        /// <summary>
        /// 配置启用自定义列
        /// </summary>
        public TableColumnBuilder EnableCustomColumn()
        {
            if (_shareConfig.IsEnableCustomColumn == false)
                return this;
            CellControl(_shareConfig.CellControl);
            return this;
        }

        /// <summary>
        /// 配置事件
        /// </summary>
        public TableColumnBuilder Events()
        {
            AttributeIfNotEmpty("(nzCheckedChange)", _config.GetValue(UiConst.OnCheckedChange));
            AttributeIfNotEmpty("(nzExpandChange)", _config.GetValue(UiConst.OnExpandChange));
            this.OnClick(_config);
            return this;
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.ConfigBase(_config);
            this.Tooltip(_config).Popover(_config).Popconfirm(_config);
            ShowCheckbox().Disabled().Indeterminate().Checked()
                .ShowExpand().Expand()
                .Left().Right().Align().BreakWord().Ellipsis()
                .IndentSize().CellControl().EnableCustomColumn()
                .Events();
            ConfigContent();
        }

        /// <summary>
        /// 配置内容
        /// </summary>
        protected virtual void ConfigContent()
        {
            var service = new TableColumnContentService(this, new TableSelectCreateService());
            service.Config();
        }

        /// <summary>
        /// 添加复选框
        /// </summary>
        public virtual void AddCheckbox()
        {
            var title = "util.checkbox";
            Attribute("[nzShowCheckbox]", "true");
            Attribute("(click)", "$event.stopPropagation()");
            Attribute("(nzCheckedChange)", $"{_shareConfig.TableExtendId}.toggle(row)");
            Attribute("[nzChecked]", $"{_shareConfig.TableExtendId}.isChecked(row)");
            if (_shareConfig.IsEnableCustomColumn)
                Attribute("nzCellControl", title);
            Left(_shareConfig.IsCheckboxLeft, title);
            if (_shareConfig.IsEnableFixedColumn)
                Right(_shareConfig.IsCheckboxLeft, title);
            Align(title);
        }

        /// <summary>
        /// 添加复选框
        /// </summary>
        /// <param name="checkBoxBuilder">复选框生成器</param>
        public virtual void AddCheckbox(TagBuilder checkBoxBuilder)
        {
            AppendContent(checkBoxBuilder);
            Left(_shareConfig.IsCheckboxLeft);
        }

        /// <summary>
        /// 添加单选框
        /// </summary>
        public virtual void AddRadio()
        {
            var radioBuilder = new TableColumnRadioBuilder(_config, _shareConfig.TableExtendId);
            AddRadio(radioBuilder);
        }

        /// <summary>
        /// 添加单选框
        /// </summary>
        public virtual void AddRadio(TagBuilder radioBuilder)
        {
            var title = "util.radio";
            AppendContent(radioBuilder);
            if (_shareConfig.IsEnableCustomColumn)
                Attribute("nzCellControl", title);
            Left(_shareConfig.IsRadioLeft, title);
            if (_shareConfig.IsEnableFixedColumn)
                Right(_shareConfig.IsRadioLeft, title);
            Align(title);
        }

        /// <summary>
        /// 添加序号
        /// </summary>
        public void AddLineNumber()
        {
            var title = "util.lineNumber";
            AppendContent("{{row.lineNumber}}");
            if (_shareConfig.IsEnableCustomColumn)
                Attribute("nzCellControl", title);
            Left(_shareConfig.IsLineNumberLeft, title);
            if (_shareConfig.IsEnableFixedColumn)
                Right(_shareConfig.IsLineNumberLeft, title);
            Align(title);
        }
    }

    /// <summary>
    /// 表格编辑列控件区域标签生成器
    /// </summary>
    public class TableColumnControlBuilder : AngularTagBuilder
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;
        /// <summary>
        /// 表格列共享配置
        /// </summary>
        private readonly TableColumnShareConfig _shareConfig;

        /// <summary>
        /// 初始化表格编辑列控件区域标签生成器
        /// </summary>
        public TableColumnControlBuilder(Config config) : base(config, "ng-template")
        {
            _config = config;
            _shareConfig = GetTableColumnShareConfig();
        }

        /// <summary>
        /// 获取表格列共享配置
        /// </summary>
        private TableColumnShareConfig GetTableColumnShareConfig()
        {
            return _config.GetValueFromItems<TableColumnShareConfig>();
        }

        /// <inheritdoc />
        protected override void ConfigId(Config config)
        {
            this.RawId(_config);
            if (config.Contains(UiConst.Id))
            {
                this.Id(_config.GetValue(UiConst.Id));
                return;
            }
            this.Id(_shareConfig?.ControlTemplateId);
        }
    }

    /// <summary>
    /// 表格编辑列显示区域标签生成器
    /// </summary>
    public class TableColumnDisplayBuilder : AngularTagBuilder
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;
        /// <summary>
        /// 表格列共享配置
        /// </summary>
        private readonly TableColumnShareConfig _shareConfig;

        /// <summary>
        /// 初始化表格编辑列显示区域标签生成器
        /// </summary>
        /// <param name="config">配置</param>
        public TableColumnDisplayBuilder(Config config) : base(config, "ng-container")
        {
            _config = config;
            _shareConfig = GetTableColumnShareConfig();
        }

        /// <summary>
        /// 获取表格列共享配置
        /// </summary>
        private TableColumnShareConfig GetTableColumnShareConfig()
        {
            return _config.GetValueFromItems<TableColumnShareConfig>();
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.Config();
            if (_shareConfig == null)
                return;
            this.NgIf($"{_shareConfig.TableEditId}.editId !== row.id;else {_shareConfig.ControlTemplateId}");
        }
    }

    /// <summary>
    /// 表格单元格单选框标签生成器
    /// </summary>
    public class TableColumnRadioBuilder : AngularTagBuilder
    {
        /// <summary>
        /// 初始化表格单元格单选框标签生成器
        /// </summary>
        /// <param name="config">配置</param>
        /// <param name="tableExtendId">表格扩展标识</param>
        /// <param name="content">内容</param>
        public TableColumnRadioBuilder(Config config, string tableExtendId, IHtmlContent content = null) : base(config, "label")
        {
            base.Attribute("nz-radio");
            base.Attribute("(click)", "$event.stopPropagation()");
            base.Attribute("name", $"r_{tableExtendId}");
            base.Attribute("[ngModel]", $"{tableExtendId}.isChecked(row)");
            base.Attribute("(ngModelChange)", $"{tableExtendId}.checkRowOnly(row)");
            if (content == null)
                return;
            base.SetContent(content);
        }
    }

    /// <summary>
    /// 表头标签生成器
    /// </summary>
    public class TableHeadBuilder : AngularTagBuilder
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;
        /// <summary>
        /// 表格共享配置
        /// </summary>
        private TableShareConfig _tableShareConfig;

        /// <summary>
        /// 初始化表头标签生成器
        /// </summary>
        /// <param name="config">配置</param>
        public TableHeadBuilder(Config config) : base(config, "thead")
        {
            _config = config;
            _tableShareConfig = GetTableShareConfig();
        }

        /// <summary>
        /// 获取配置
        /// </summary>
        public Config GetConfig()
        {
            return _config;
        }

        /// <summary>
        /// 获取表格共享配置
        /// </summary>
        public TableShareConfig GetTableShareConfig()
        {
            return _tableShareConfig ??= _config.GetValueFromItems<TableShareConfig>() ?? new TableShareConfig();
        }

        /// <summary>
        /// 创建表头行标签生成器
        /// </summary>
        public virtual TableHeadRowBuilder CreateTableHeadRowBuilder()
        {
            return new TableHeadRowBuilder(_config.CopyRemoveAttributes());
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.ConfigBase(_config);
            ConfigAutoCreate();
            ConfigContent();
        }

        /// <summary>
        /// 配置自动创建嵌套结构
        /// </summary>
        public void ConfigAutoCreate()
        {
            var service = new TableHeadAutoCreateService(this);
            service.Init();
        }

        /// <summary>
        /// 配置内容
        /// </summary>
        public void ConfigContent()
        {
            if (_tableShareConfig.HeadRowAutoCreated)
                return;
            _config.Content.AppendTo(this);
        }
    }

