            var options = NgZorroOptionsService.GetOptions();
            if (options.EnableI18n)
            {
                _config.SetAttribute(UiConst.Title, I18nKeys.Operation);
                return this;
            }
            _config.SetAttribute(UiConst.Title, "Operation");
            return this;
        }

        /// <summary>
        /// 配置标题
        /// </summary>
        public TableHeadColumnBuilder Title()
        {
            Title(_config.GetValue(UiConst.Title));
            return this;
        }

        /// <summary>
        /// 配置标题
        /// </summary>
        /// <param name="title">标题</param>
        public virtual void Title(string title)
        {
            var options = NgZorroOptionsService.GetOptions();
            if (title.IsEmpty())
                return;
            if (options.EnableI18n)
            {
                this.AppendContentByI18n(title);
                return;
            }
            AppendContent(title);
        }

        /// <summary>
        /// 配置单元格控件
        /// </summary>
        public virtual TableHeadColumnBuilder CellControl()
        {
            CellControl(_config.GetValue(UiConst.CellControl));
            AttributeIfNotEmpty("[nzCellControl]", _config.GetValue(AngularConst.BindCellControl));
            return this;
        }

        /// <summary>
        /// 配置单元格控件
        /// </summary>
        /// <param name="value">值</param>
        public virtual TableHeadColumnBuilder CellControl(string value)
        {
            AttributeIfNotEmpty("nzCellControl", value);
            return this;
        }

        /// <summary>
        /// 配置启用自定义列
        /// </summary>
        public TableHeadColumnBuilder EnableCustomColumn()
        {
            return EnableCustomColumn(_shareConfig.CellControl);
        }

        /// <summary>
        /// 配置启用自定义列
        /// </summary>
        public TableHeadColumnBuilder EnableCustomColumn(string cellControl)
        {
            if (_shareConfig.IsEnableCustomColumn == false)
                return this;
            CellControl(cellControl);
            return this;
        }

        /// <summary>
        /// 配置启用拖动调整列宽
        /// </summary>
        public TableHeadColumnBuilder EnableResizable()
        {
            if (_shareConfig.IsEnableResizable == false)
                return this;
            return Resizable(_shareConfig.Title);
        }

        /// <summary>
        /// 配置拖动调整列宽
        /// </summary>
        public virtual TableHeadColumnBuilder Resizable(string title)
        {
            Attribute("nz-resizable");
            Attribute("nzPreview");
            Attribute("nzBounds", "window");
            Attribute("(nzResizeEnd)", $"{_shareConfig.TableSettingsId}.handleResize($event,'{title}')");
            AppendHandleBuilder();
            return this;
        }

        /// <summary>
        /// 添加拖动手柄生成器
        /// </summary>
        protected void AppendHandleBuilder()
        {
            var handleBuilder = new ResizeHandleBuilder(_config);
            handleBuilder.Direction(ResizeDirection.Right);
            AppendContent(handleBuilder);
        }

        /// <summary>
        /// 配置事件
        /// </summary>
        public TableHeadColumnBuilder Events()
        {
            AttributeIfNotEmpty("(nzCheckedChange)", _config.GetValue(UiConst.OnCheckedChange));
            AttributeIfNotEmpty("(nzFilterChange)", _config.GetValue(UiConst.OnFilterChange));
            OnSortOrderChange(_config.GetValue(UiConst.OnSortOrderChange));
            return this;
        }

        /// <summary>
        /// 排序事件
        /// </summary>
        public TableHeadColumnBuilder OnSortOrderChange(string value)
        {
            AttributeIfNotEmpty("(nzSortOrderChange)", value);
            return this;
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.Config();
            ShowCheckbox().Disabled().Indeterminate().Checked()
                .ShowRowSelection().Selections()
                .ShowSort().SortFn().SortDirections().SortOrder().Sort()
                .ShowFilter().FilterFn().Filters().FilterMultiple()
                .Width().Left().Right().Align().BreakWord().Ellipsis()
                .Colspan().Rowspan().ColumnKey()
                .TitleOperation().Title().TitleAlign()
                .CellControl().EnableCustomColumn().EnableResizable()
                .Events()
                .CheckBox().Radio().LineNumber();
        }

        /// <summary>
        /// 添加复选框
        /// </summary>
        public TableHeadColumnBuilder CheckBox()
        {
            if (_shareConfig.IsShowCheckbox == false)
                return this;
            if (_shareConfig.IsFirst == false)
                return this;
            AddCheckBox();
            return this;
        }

        /// <summary>
        /// 添加复选框
        /// </summary>
        protected virtual void AddCheckBox(string title = null)
        {
            var checkboxBuilder = new TableHeadColumnBuilder(_config, _shareConfig);
            checkboxBuilder.ConfigCheckBox();
            PreBuilder = checkboxBuilder;
        }

        /// <summary>
        /// 配置复选框
        /// </summary>
        public void ConfigCheckBox()
        {
            var title = "util.checkbox";
            Attribute("[nzShowCheckbox]", "true");
            Attribute("(nzCheckedChange)", $"{_shareConfig.TableExtendId}.masterToggle()");
            Attribute("[nzChecked]", $"{_shareConfig.TableExtendId}.isMasterChecked()");
            Attribute("[nzDisabled]", $"!{_shareConfig.TableExtendId}.dataSource.length");
            Attribute("[nzIndeterminate]", $"{_shareConfig.TableExtendId}.isMasterIndeterminate()");
            EnableCustomColumn(title);
            if (_shareConfig.IsEnableCustomColumn == false)
                BindWidth($"{_shareConfig.TableExtendId}.config.table.checkboxWidth");
            Left(_shareConfig.IsCheckboxLeft, title);
            if (_shareConfig.IsEnableFixedColumn)
                Right(_shareConfig.IsCheckboxLeft, title);
            TitleAlign(title);
            ConfigRowSpan();
        }

        /// <summary>
        /// 配置行跨度
        /// </summary>
        protected void ConfigRowSpan()
        {
            if (_shareConfig.HeadRowNumber < 2)
                return;
            Rowspan(_shareConfig.HeadRowNumber.ToString());
        }

        /// <summary>
        /// 添加单选框列头
        /// </summary>
        public TableHeadColumnBuilder Radio()
        {
            if (_shareConfig.IsShowCheckbox)
                return this;
            if (_shareConfig.IsShowRadio == false)
                return this;
            if (_shareConfig.IsFirst == false)
                return this;
            AddRadio();
            return this;
        }

        /// <summary>
        /// 添加单选框列头
        /// </summary>
        protected virtual void AddRadio(string title = null)
        {
            var radioTitle = "util.radio";
            var radioBuilder = new TableHeadColumnBuilder(_config, _shareConfig);
            radioBuilder.EnableCustomColumn(radioTitle);
            radioBuilder.TitleAlign(radioTitle);
            radioBuilder.Left(_shareConfig.IsRadioLeft, radioTitle);
            if (_shareConfig.IsEnableFixedColumn)
                radioBuilder.Right(_shareConfig.IsRadioLeft, radioTitle);
            if (_shareConfig.IsEnableCustomColumn == false)
                radioBuilder.BindWidth($"{_shareConfig.TableExtendId}.config.table.radioWidth");
            radioBuilder.ConfigRowSpan();
            PreBuilder = radioBuilder;
        }

        /// <summary>
        /// 配置序号
        /// </summary>
        public TableHeadColumnBuilder LineNumber()
        {
            if (_shareConfig.IsShowLineNumber == false)
                return this;
            if (_shareConfig.IsFirst == false)
                return this;
            AddLineNumber();
            return this;
        }

        /// <summary>
        /// 添加序号
        /// </summary>
        protected virtual void AddLineNumber()
        {
            var title = "util.lineNumber";
            var lineNumberBuilder = new TableHeadColumnBuilder(_config, _shareConfig);
            lineNumberBuilder.ConfigLineNumber();
            lineNumberBuilder.EnableCustomColumn(title);
            lineNumberBuilder.TitleAlign(title);
            lineNumberBuilder.ConfigRowSpan();
            if (PreBuilder == null)
            {
                PreBuilder = lineNumberBuilder;
                return;
            }
            PreBuilder.PostBuilder = lineNumberBuilder;
        }

        /// <summary>
        /// 配置序号
        /// </summary>
        public void ConfigLineNumber()
        {
            var options = NgZorroOptionsService.GetOptions();
            Title(options.EnableI18n ? "util.lineNumber" : "序号");
            if (_shareConfig.IsEnableCustomColumn == false)
                BindWidth($"{_shareConfig.TableExtendId}.config.table.lineNumberWidth");
            Left(_shareConfig.IsLineNumberLeft, "util.lineNumber");
            if (_shareConfig.IsEnableFixedColumn)
                Right(_shareConfig.IsLineNumberLeft, "util.lineNumber");
        }

        /// <summary>
        /// 添加表头单元格
        /// </summary>
        /// <param name="column">列</param>
        public virtual void AddColumn(ColumnInfo column)
        {
            if (column.IsFirst)
            {
                if (_shareConfig.IsShowCheckbox)
                    AddCheckBox();
                if (_shareConfig.IsShowCheckbox == false && _shareConfig.IsShowRadio)
                    AddRadio();
                if (_shareConfig.IsShowLineNumber)
                    AddLineNumber();
            }
            if (column.IsSort)
                Sort(column.Column);
            Title(column.Title);
            SetColumnWidth(column);
            Left(column.IsLeft, column.Title);
            Right(column.IsRight, column.Title);
            SetAcl(column.Acl, column.AclElseTemplateId);
            EnableCustomColumn(column.GetCellControl());
            EnableResizable(column);
            TitleAlign(column.Title);
        }

        /// <summary>
        /// 设置列宽
        /// </summary>
        protected void SetColumnWidth(ColumnInfo column)
        {
            if (_shareConfig.IsEnableCustomColumn)
                return;
            if (IsEnableResizable(column))
            {
                Attribute("[nzWidth]", GetWidthByTableSettings(column.Title, column.Width));
                return;
            }
            this.Width(column.Width);
        }

        /// <summary>
        /// 从表格设置获取宽度
        /// </summary>
        protected string GetWidthByTableSettings(string title, string width)
        {
            if (width.IsEmpty())
                return $"{_shareConfig.TableSettingsId}.getWidth('{title}')";
            return $"{_shareConfig.TableSettingsId}.getWidth('{title}','{width}')";
        }

        /// <summary>
        /// 配置访问控制列表
        /// </summary>
        public TableHeadColumnBuilder SetAcl(string acl, string aclElseTemplateId)
        {
            _config.SetAttribute(UiConst.Acl, acl);
            _config.SetAttribute(UiConst.AclElseTemplateId, aclElseTemplateId);
            this.Acl(_config);
            return this;
        }

        /// <summary>
        /// 配置启用拖动调整列宽
        /// </summary>
        protected void EnableResizable(ColumnInfo column)
        {
            if (IsEnableResizable(column) == false)
                return;
            Resizable(column.Title);
        }

        /// <summary>
        /// 是否启用拖动调整列宽
        /// </summary>
        protected bool IsEnableResizable(ColumnInfo column)
        {
            if (column.IsEnableResizable)
                return true;
            return _shareConfig.IsEnableResizable;
        }
    }

    /// <summary>
    /// 表头行标签生成器
    /// </summary>
    public class TableHeadRowBuilder : TableRowBuilder
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化表格主体行标签生成器
        /// </summary>
        public TableHeadRowBuilder(Config config) : base(config)
        {
            _config = config;
        }

        /// <summary>
        /// 创建表头单元格标签生成器
        /// </summary>
        public virtual TableHeadColumnBuilder CreateTableHeadColumnBuilder()
        {
            return new TableHeadColumnBuilder(_config.CopyRemoveAttributes(), GetTableHeadColumnShareConfig());
        }

        /// <summary>
        /// 获取表头列共享配置
        /// </summary>
        protected TableHeadColumnShareConfig GetTableHeadColumnShareConfig()
        {
            return _config.GetValueFromItems<TableHeadColumnShareConfig>() ?? new TableHeadColumnShareConfig(GetTableShareConfig());
        }

        /// <summary>
        /// 获取表格共享配置
        /// </summary>
        private TableShareConfig GetTableShareConfig()
        {
            return _config.GetValueFromItems<TableShareConfig>() ?? new TableShareConfig();
        }

        /// <summary>
        /// 配置事件
        /// </summary>
        public override TableRowBuilder Events()
        {
            this.OnClick(_config);
            return this;
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.Config();
            ConfigAutoCreate();
            ConfigContent();
        }

        /// <summary>
        /// 配置自动创建嵌套结构
        /// </summary>
        public void ConfigAutoCreate()
        {
            var service = new TableHeadRowAutoCreateService(this);
            service.Init();
        }

        /// <summary>
        /// 配置内容
        /// </summary>
        public void ConfigContent()
        {
            if (TableShareConfig.HeadColumnAutoCreated)
                return;
            _config.Content.AppendTo(this);
        }
    }

    /// <summary>
    /// 表格行标签生成器
    /// </summary>
    public class TableRowBuilder : AngularTagBuilder
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;
        /// <summary>
        /// 表格共享配置
        /// </summary>
        private TableShareConfig _tableShareConfig;
        /// <summary>
        /// 点击事件列表
        /// </summary>
        private readonly List<string> _onClick;

        /// <summary>
        /// 初始化表格行标签生成器
        /// </summary>
        /// <param name="config">配置</param>
        public TableRowBuilder(Config config) : base(config, "tr")
        {
            _config = config;
            _onClick = [];
        }

        /// <summary>
        /// 获取配置
        /// </summary>
        public Config GetConfig()
        {
            return _config;
        }

        /// <summary>
        /// 获取表格共享配置
        /// </summary>
        public TableShareConfig TableShareConfig => _tableShareConfig ??= _config.GetValueFromItems<TableShareConfig>() ?? new TableShareConfig();

        /// <summary>
        /// 配置当前列是否展开
        /// </summary>
        public TableRowBuilder Expand()
        {
            AttributeIfNotEmpty("[nzExpand]", _config.GetValue(UiConst.Expand));
            return this;
        }

        /// <summary>
        /// 配置事件
        /// </summary>
        public virtual TableRowBuilder Events()
        {
            ConfigOnClick();
            return this;
        }

        /// <summary>
        /// 配置单击事件
        /// </summary>
        private void ConfigOnClick()
        {
            AddOnClick();
            this.OnClick(_onClick.Join(separator: ";"));
        }

        /// <summary>
        /// 添加单击事件
        /// </summary>
        private void AddOnClick()
        {
            AddOnClick(_config.GetValue(UiConst.OnClick));
            AddOnClick(TableShareConfig.OnClickRow);
            if (IsSelectOnClick())
                AddOnClick($"{TableShareConfig.TableExtendId}.toggleSelect(row)");
            if (IsSelectOnlyOnClick())
                AddOnClick($"{TableShareConfig.TableExtendId}.selectRowOnly(row)");
            if (IsCheckRowOnClick())
                AddOnClick($"{TableShareConfig.TableExtendId}.toggle(row)");
            if (IsCheckRowOnlyOnClick())
                AddOnClick($"{TableShareConfig.TableExtendId}.checkRowOnly(row)");
        }

        /// <summary>
        /// 添加单击事件
        /// </summary>
        private void AddOnClick(string onClick)
        {
            if (onClick.IsEmpty())
                return;
            _onClick.Add(onClick);
        }

        /// <summary>
        /// 是否单击选中行
        /// </summary>
        private bool IsSelectOnClick()
        {
            var result = _config.GetValue<bool>(UiConst.SelectOnClick);
            return result || TableShareConfig.SelectOnClickRow;
        }

        /// <summary>
        /// 是否单击仅选中该行
        /// </summary>
        private bool IsSelectOnlyOnClick()
        {
            var result = _config.GetValue<bool>(UiConst.SelectOnlyOnClick);
            return result || TableShareConfig.SelectOnlyOnClickRow;
        }

        /// <summary>
        /// 是否单击选中复选框
        /// </summary>
        private bool IsCheckRowOnClick()
        {
            if (TableShareConfig.IsShowCheckbox == false)
                return false;
            var result = _config.GetValue<bool>(UiConst.CheckOnClick);
            return result || TableShareConfig.CheckOnClickRow;
        }

        /// <summary>
        /// 是否单击选中单选框
        /// </summary>
        private bool IsCheckRowOnlyOnClick()
        {
            if (TableShareConfig.IsShowRadio == false)
                return false;
            var result = _config.GetValue<bool>(UiConst.CheckOnClick);
            return result || TableShareConfig.CheckOnClickRow;
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.ConfigBase(_config);
            Expand().Events();
            ConfigSelect();
        }

        /// <summary>
        /// 配置选中行
        /// </summary>
        private void ConfigSelect()
        {
            if (IsSelectOnClick() || IsSelectOnlyOnClick())
                Attribute("[class.table-row-selected]", $"{TableShareConfig.TableExtendId}.isSelected(row)");
        }
    }

    /// <summary>
    /// 表格设置标签生成器
    /// </summary>
    public class TableSettingsBuilder : AngularTagBuilder
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;
        /// <summary>
        /// 表格共享配置
        /// </summary>
        private TableShareConfig _tableShareConfig;

        /// <summary>
        /// 初始化表格设置标签生成器
        /// </summary>
        /// <param name="config">配置</param>
        public TableSettingsBuilder(Config config) : base(config, NgZorroOptionsService.GetOptions().TableSettingsTag)
        {
            _config = config;
            _tableShareConfig = GetTableShareConfig();
        }

        /// <summary>
        /// 获取表格共享配置
        /// </summary>
        public TableShareConfig GetTableShareConfig()
        {
            return _tableShareConfig ??= _config.GetValueFromItems<TableShareConfig>() ?? new TableShareConfig();
        }

        /// <summary>
        /// 设置表格尺寸
        /// </summary>
        public TableSettingsBuilder IsTreeTable()
        {
            if (_tableShareConfig.IsTreeTable == false)
                return this;
            Attribute("[isTreeTable]", "true");
            return this;
        }

        /// <summary>
        /// 设置表格尺寸
        /// </summary>
        public TableSettingsBuilder Size()
        {
            AttributeIfNotEmpty("initSize", _config.GetValue<TableSize?>(UiConst.Size)?.Description());
            return this;
        }

        /// <summary>
        /// 设置表格边框
        /// </summary>
        public TableSettingsBuilder Bordered()
        {
            AttributeIfNotEmpty("[initBordered]", _config.GetValue(UiConst.Bordered));
            return this;
        }

        /// <summary>
        /// 设置滚动宽高
        /// </summary>
        public TableSettingsBuilder Scroll()
        {
            AttributeIfNotEmpty("scrollHeight", _tableShareConfig.ScrollHeight);
            AttributeIfNotEmpty("scrollWidth", _tableShareConfig.ScrollWidth);
            AttributeIfNotEmpty("[initScroll]", _config.GetValue(UiConst.Scroll));
            return this;
        }

        /// <summary>
        /// 配置是否启用固定列
        /// </summary>
        public TableSettingsBuilder EnableFixedColumn()
        {
            if (_tableShareConfig.IsEnableFixedColumn)
                Attribute("[enableFixedColumn]", "true");
            return this;
        }

        /// <summary>
        /// 配置初始设置的列集合
        /// </summary>
        public TableSettingsBuilder InitColumns()
        {
            if (_tableShareConfig.ColumnNumber == 0)
                return this;
            Attribute("[initColumns]", GetColumnsJson());
            return this;
        }

        /// <summary>
        /// 获取自定义列Json
        /// </summary>
        private string GetColumnsJson()
        {
            var result = new List<CustomColumn>();
            AddRadioColumn(result);
            AddCheckboxColumn(result);
            AddLineNumberColumn(result);
            result.AddRange(_tableShareConfig.Columns.Where(column => column.IsInner == false).Select(column => column.ToCustomColumn()));
            var json = Util.Helpers.Json.ToJson(result, new JsonOptions { ToSingleQuotes = true, IgnoreNullValues = true });
            return json.Replace($"'{GetCheckboxWidth()}'", GetCheckboxWidth())
                .Replace($"'{GetRadioWidth()}'", GetRadioWidth())
                .Replace($"'{GetLineNumberWidth()}'", GetLineNumberWidth());
        }

        /// <summary>
        /// 获取表格复选框宽度
        /// </summary>
        private string GetCheckboxWidth()
        {
            return $"{_tableShareConfig.TableExtendId}.config.table.checkboxWidth";
        }

        /// <summary>
        /// 获取表格单选框宽度
        /// </summary>
        private string GetRadioWidth()
        {
            return $"{_tableShareConfig.TableExtendId}.config.table.radioWidth";
        }

        /// <summary>
        /// 获取表格序号宽度
        /// </summary>
        private string GetLineNumberWidth()
        {
            return $"{_tableShareConfig.TableExtendId}.config.table.lineNumberWidth";
        }

        /// <summary>
        /// 添加单选列信息
        /// </summary>
        private void AddRadioColumn(List<CustomColumn> result)
        {
            if (_tableShareConfig.IsTreeTable)
                return;
            if (_tableShareConfig.IsShowRadio == false)
                return;
            var options = NgZorroOptionsService.GetOptions();
            result.Add(new CustomColumn("util.radio", GetRadioWidth(), _tableShareConfig.GetRadioLeft(), align: options.TableRadioAlign.Description()));
        }

        /// <summary>
        /// 添加复选列信息
        /// </summary>
        private void AddCheckboxColumn(List<CustomColumn> result)
        {
            if (_tableShareConfig.IsTreeTable)
                return;
            if (_tableShareConfig.IsShowCheckbox == false)
                return;
            var options = NgZorroOptionsService.GetOptions();
            result.Add(new CustomColumn("util.checkbox", GetCheckboxWidth(), _tableShareConfig.GetCheckboxLeft(), align: options.TableCheckboxAlign.Description()));
        }

        /// <summary>
        /// 添加序号信息
        /// </summary>
        private void AddLineNumberColumn(List<CustomColumn> result)
        {
            if (_tableShareConfig.IsTreeTable)
                return;
            if (_tableShareConfig.IsShowLineNumber == false)
                return;
            var options = NgZorroOptionsService.GetOptions();
            result.Add(new CustomColumn("util.lineNumber", GetLineNumberWidth(), _tableShareConfig.GetLineNumberLeft(), align: options.TableLineNumberAlign.Description()));
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            if (_tableShareConfig.Key.IsEmpty())
                throw new ArgumentNullException("表格存储标识属性 Key 必须设置!");
            Attribute($"#{_tableShareConfig.TableSettingsId}");
            Attribute("key", _tableShareConfig.Key);
            IsTreeTable().Size().Bordered().Scroll().EnableFixedColumn();
            InitColumns();
        }
    }

    /// <summary>
