    /// </summary>
    [HtmlTargetElement("filter-trigger")]
    public class FilterTriggerTagHelper : AngularTagHelperBase
    {
        /// <summary>
        /// [nzDropdownMenu],下拉菜单组件,类型: NzDropdownMenuComponent
        /// </summary>
        public string DropdownMenu { get; set; }
