        /// <summary>
        /// [nzSize],表格大小,可选值: 'middle' | 'small' | 'default',默认值: 'default'
        /// </summary>
        public string BindSize { get; set; }
        /// <summary>
        /// [nzLoading],是否加载状态,默认值: false
        /// </summary>
