        /// <summary>
        /// [nzNoResult],无数据时显示内容,类型: string | TemplateRef&lt;void>
        /// </summary>
        public string BindNoResult { get; set; }
        /// <summary>
        /// [nzPageSizeOptions],每页行数选择列表,类型: number[],默认值: [ 10, 20, 30, 40, 50 ]
        /// </summary>
        public string PageSizeOptions { get; set; }
        /// <summary>
        /// [nzShowQuickJumper],是否显示分页快速跳转,默认值: false
        /// </summary>
        public string ShowQuickJumper { get; set; }
        /// <summary>
        /// [nzShowSizeChanger],是否显示改变分页大小按钮,默认值: false,当启用扩展时自动设置为 true
        /// </summary>
        public string ShowSizeChanger { get; set; }
        /// <summary>
        /// [nzShowTotal],设置显示总行数和当前数据范围的模板,类型: TemplateRef&lt;{ $implicit: number, range: [ number, number ] }>
        /// </summary>
        public string ShowTotal { get; set; }
        /// <summary>
        /// [nzItemRender],自定义页码结构,类型: TemplateRef&lt;{ $implicit: 'page' | 'prev' | 'next', page: number }>
        /// </summary>
        public string ItemRender { get; set; }
        /// <summary>
        /// [nzHideOnSinglePage],只有一页时是否隐藏分页器,默认值: false
        /// </summary>
        public string HideOnSinglePage { get; set; }
        /// <summary>
        /// [nzSimple],是否显示简单分页
        /// </summary>
        public string Simple { get; set; }
        /// <summary>
        /// [nzTemplateMode],是否模板模式,无需将数据传递给 nzData,默认值: false
        /// </summary>
        public string TemplateMode { get; set; }
        /// <summary>
        /// [nzVirtualItemSize],虚拟滚动时每一列的高度,单位:像素,默认值: 0
        /// </summary>
        public string VirtualItemSize { get; set; }
        /// <summary>
        /// [nzVirtualMaxBufferPx],虚拟滚动缓冲区最大高度,单位:像素,默认值: 200
        /// </summary>
        public string VirtualMaxBufferPx { get; set; }
        /// <summary>
        /// [nzVirtualMinBufferPx],虚拟滚动缓冲区最小高度，低于该值时将加载新结构,单位:像素,默认值: 100
        /// </summary>
        public string VirtualMinBufferPx { get; set; }
        /// <summary>
        /// [nzVirtualForTrackBy],虚拟滚动数据 TrackByFunction 函数，类型: TrackByFunction&lt;T>
        /// </summary>
        public string VirtualForTrackBy { get; set; }
        /// <summary>
        /// nzTableLayout,表格布局,可选值: 'fixed' | 'auto'
        /// </summary>
        public TableLayout Layout { get; set; }
        /// <summary>
        /// [nzTableLayout],表格布局,可选值: 'fixed' | 'auto'
        /// </summary>
        public string BindLayout { get; set; }
        /// <summary>
        /// [nzCustomColumn],自定义列, 控制表格列的展示与排序, 类型: NzCustomColumn[], 注意: 开启后 nzWidthConfig 和 th 的 nzWidth 将不生效
        /// </summary>
        public string CustomColumn { get; set; }
        /// <summary>
        /// 扩展属性,是否启用表格设置,将启用表格设置的全部功能, 默认值: false
        /// </summary>
        public bool EnableTableSettings { get; set; }
        /// <summary>
        /// 扩展属性,是否启用自定义列,默认值: false
        /// </summary>
        public bool EnableCustomColumn { get; set; }
        /// <summary>
        /// 扩展属性,是否启用拖动调整列宽,默认值: false
        /// </summary>
        public bool EnableResizable { get; set; }
        /// <summary>
        /// 扩展属性,是否启用固定列,默认值: false
        /// </summary>
        public bool EnableFixedColumn { get; set; }
        /// <summary>
        /// 扩展属性 [isBatch],是否批量编辑, false表示单行编辑模式,true表示批量编辑模式,一次性保存所有更改, 默认值: false
        /// </summary>
        public bool IsBatchEdit { get; set; }
        /// <summary>
        /// (nzPageIndexChange),页码变化事件,类型: EventEmitter&lt;number>
        /// </summary>
        public string OnPageIndexChange { get; set; }
        /// <summary>
        /// (nzPageSizeChange),每页显示行数变化事件,类型: EventEmitter&lt;number>
        /// </summary>
        public string OnPageSizeChange { get; set; }
        /// <summary>
        /// (nzCurrentPageDataChange),当前页数据变化事件,类型: EventEmitter&lt;any[]>
        /// </summary>
        public string OnCurrentPageDataChange { get; set; }
        /// <summary>
        /// (nzQueryParams),查询参数变化事件,当服务端分页、筛选、排序时，用于获得参数，类型: EventEmitter&lt;NzTableQueryParams>
        /// </summary>
        public string OnQueryParams { get; set; }
        /// <summary>
        /// 扩展事件 (onLoad),数据加载完成事件,类型: EventEmitter&lt;any>,参数为服务端返回结果
        /// </summary>
        public string OnLoad { get; set; }
        /// <summary>
        /// 扩展事件,行单击事件，使用row访问行对象，范例：on-click-row="click(row)"
        /// </summary>
        public string OnClickRow { get; set; }

        /// <inheritdoc />
        protected override void ProcessBefore(TagHelperContext context, TagHelperOutput output)
        {
            _config = new Config(context, output);
            var service = new TableService(_config);
            service.Init();
        }

        /// <inheritdoc />
        protected override IRender GetRender(TagHelperContext context, TagHelperOutput output, TagHelperContent content)
        {
            _config.Content = content;
            return new TableRender(_config);
        }
    }

    #endregion

    #region Tabs
    /// <summary>
    /// 标签标签生成器
    /// </summary>
    public class TabBuilder : AngularTagBuilder
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化标签标签生成器
        /// </summary>
        public TabBuilder(Config config) : base(config, "nz-tab")
        {
            _config = config;
        }

        /// <summary>
        /// 配置标题
        /// </summary>
        public TabBuilder Title()
        {
            SetTitle(_config.GetValue(UiConst.Title));
            AttributeIfNotEmpty("[nzTitle]", _config.GetValue(AngularConst.BindTitle));
            return this;
        }

        /// <summary>
        /// 设置标题
        /// </summary>
        private void SetTitle(string value)
        {
            var options = NgZorroOptionsService.GetOptions();
            if (options.EnableI18n)
            {
                this.AttributeByI18n("[nzTitle]", value);
                return;
            }
            AttributeIfNotEmpty("nzTitle", value);
        }

        /// <summary>
        /// 配置是否强制渲染
        /// </summary>
        public TabBuilder ForceRender()
        {
            AttributeIfNotEmpty("[nzForceRender]", _config.GetValue(UiConst.ForceRender));
            return this;
        }

        /// <summary>
        /// 配置是否禁用
        /// </summary>
        public TabBuilder Disabled()
        {
            AttributeIfNotEmpty("[nzDisabled]", _config.GetValue(UiConst.Disabled));
            return this;
        }

        /// <summary>
        /// 配置是否显示关闭按钮
        /// </summary>
        public TabBuilder Closable()
        {
            AttributeIfNotEmpty("[nzClosable]", _config.GetValue(UiConst.Closable));
            return this;
        }

        /// <summary>
        /// 配置关闭按钮图标
        /// </summary>
        public TabBuilder CloseIcon()
        {
            AttributeIfNotEmpty("nzCloseIcon", _config.GetValue<AntDesignIcon?>(UiConst.CloseIcon)?.Description());
            AttributeIfNotEmpty("[nzCloseIcon]", _config.GetValue(AngularConst.BindCloseIcon));
            return this;
        }

        /// <summary>
        /// 配置事件
        /// </summary>
        public TabBuilder Events()
        {
            AttributeIfNotEmpty("(nzClick)", _config.GetValue(UiConst.OnClick));
            AttributeIfNotEmpty("(nzSelect)", _config.GetValue(UiConst.OnSelect));
            AttributeIfNotEmpty("(nzDeselect)", _config.GetValue(UiConst.OnDeselect));
            return this;
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.Config();
            Title().ForceRender().Disabled().Closable().CloseIcon()
                .Events();
        }

        /// <summary>
        /// 配置内容
        /// </summary>
        protected override void ConfigContent(Config config)
        {
            var isLazy = _config.GetValue<bool?>(UiConst.Lazy);
            if (isLazy != true)
            {
                base.ConfigContent(config);
                return;
            }
            var templateBuilder = new TemplateBuilder(_config);
            templateBuilder.Tab(true);
            config.Content.AppendTo(templateBuilder);
            SetContent(templateBuilder);
        }

        /// <summary>
        /// 配置右键上下文菜单事件
        /// </summary>
        protected override void ConfigOnContextmenu(Config config)
        {
            AttributeIfNotEmpty("(nzContextmenu)", _config.GetValue(UiConst.OnContextmenu));
        }
    }

    /// <summary>
    /// 标签页标签生成器
    /// </summary>
    public class TabSetBuilder : AngularTagBuilder
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化标签页标签生成器
        /// </summary>
        /// <param name="config">配置</param>
        public TabSetBuilder(Config config) : base(config, "nz-tabset")
        {
            _config = config;
        }

        /// <summary>
        /// 配置选中标签索引
        /// </summary>
        public TabSetBuilder SelectedIndex()
        {
            AttributeIfNotEmpty("[nzSelectedIndex]", _config.GetValue(UiConst.SelectedIndex));
            AttributeIfNotEmpty("[(nzSelectedIndex)]", _config.GetValue(AngularConst.BindonSelectedIndex));
            return this;
        }

        /// <summary>
        /// 配置是否使用动画切换选项卡
        /// </summary>
        public TabSetBuilder Animated()
        {
            AttributeIfNotEmpty("[nzAnimated]", _config.GetValue(UiConst.Animated));
            return this;
        }

        /// <summary>
        /// 配置标签大小
        /// </summary>
        public TabSetBuilder Size()
        {
            AttributeIfNotEmpty("nzSize", _config.GetValue<TabSize?>(UiConst.Size)?.Description());
            AttributeIfNotEmpty("[nzSize]", _config.GetValue(AngularConst.BindSize));
            return this;
        }

        /// <summary>
        /// 配置标签栏附加内容
        /// </summary>
        public TabSetBuilder TabBarExtraContent()
        {
            AttributeIfNotEmpty("[nzTabBarExtraContent]", _config.GetValue(UiConst.TabBarExtraContent));
            return this;
        }

        /// <summary>
        /// 配置标签栏样式
        /// </summary>
        public TabSetBuilder TabBarStyle()
        {
            AttributeIfNotEmpty("[nzTabBarStyle]", _config.GetValue(UiConst.TabBarStyle));
            return this;
        }

        /// <summary>
        /// 配置标签位置
        /// </summary>
        public TabSetBuilder TabPosition()
        {
            AttributeIfNotEmpty("nzTabPosition", _config.GetValue<TabPosition?>(UiConst.TabPosition)?.Description());
            AttributeIfNotEmpty("[nzTabPosition]", _config.GetValue(AngularConst.BindTabPosition));
            return this;
        }

        /// <summary>
        /// 配置标签类型
        /// </summary>
        public TabSetBuilder Type()
        {
            AttributeIfNotEmpty("nzType", _config.GetValue<TabType?>(UiConst.Type)?.Description());
            AttributeIfNotEmpty("[nzType]", _config.GetValue(AngularConst.BindType));
            return this;
        }

        /// <summary>
        /// 配置标签间隙
        /// </summary>
        public TabSetBuilder TabBarGutter()
        {
            AttributeIfNotEmpty("[nzTabBarGutter]", _config.GetValue(UiConst.TabBarGutter));
            return this;
        }

        /// <summary>
        /// 配置是否隐藏全部标签
        /// </summary>
        public TabSetBuilder HideAll()
        {
            AttributeIfNotEmpty("[nzHideAll]", _config.GetValue(UiConst.HideAll));
            return this;
        }

        /// <summary>
        /// 配置是否支持路由联动
        /// </summary>
        public TabSetBuilder LinkRouter()
        {
            AttributeIfNotEmpty("[nzLinkRouter]", _config.GetValue(UiConst.LinkRouter));
            return this;
        }

        /// <summary>
        /// 配置是否以严格模式匹配路由联动
        /// </summary>
        public TabSetBuilder LinkExact()
        {
            AttributeIfNotEmpty("[nzLinkExact]", _config.GetValue(UiConst.LinkExact));
            return this;
        }

        /// <summary>
        /// 配置标签守卫函数
        /// </summary>
        public TabSetBuilder CanDeactivate()
        {
            AttributeIfNotEmpty("[nzCanDeactivate]", _config.GetValue(UiConst.CanDeactivate));
            return this;
        }

        /// <summary>
        /// 配置标签是否居中显示
        /// </summary>
        public TabSetBuilder Centered()
        {
            AttributeIfNotEmpty("[nzCentered]", _config.GetValue(UiConst.Centered));
            return this;
        }

        /// <summary>
        /// 配置是否隐藏添加按钮
        /// </summary>
        public TabSetBuilder HideAdd()
        {
            AttributeIfNotEmpty("[nzHideAdd]", _config.GetValue(UiConst.HideAdd));
            return this;
        }

        /// <summary>
        /// 配置添加按钮图标
        /// </summary>
        public TabSetBuilder AddIcon()
        {
            AttributeIfNotEmpty("nzAddIcon", _config.GetValue<AntDesignIcon?>(UiConst.AddIcon)?.Description());
            AttributeIfNotEmpty("[nzAddIcon]", _config.GetValue(AngularConst.BindAddIcon));
            return this;
        }

        /// <summary>
        /// 配置关闭按钮图标
        /// </summary>
        public TabSetBuilder CloseIcon()
        {
            AttributeIfNotEmpty("nzCloseIcon", _config.GetValue<AntDesignIcon?>(UiConst.CloseIcon)?.Description());
            AttributeIfNotEmpty("[nzCloseIcon]", _config.GetValue(AngularConst.BindCloseIcon));
            return this;
        }

        /// <summary>
        /// 配置事件
        /// </summary>
        public TabSetBuilder Events()
        {
            AttributeIfNotEmpty("(nzSelectedIndexChange)", _config.GetValue(UiConst.OnSelectedIndexChange));
            AttributeIfNotEmpty("(nzSelectChange)", _config.GetValue(UiConst.OnSelectChange));
            AttributeIfNotEmpty("(nzAdd)", _config.GetValue(UiConst.OnAdd));
            AttributeIfNotEmpty("(nzClose)", _config.GetValue(UiConst.OnClose));
            return this;
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.Config();
            SelectedIndex().Animated().Size().Type()
                .TabBarExtraContent().TabBarStyle().TabPosition().TabBarGutter()
                .HideAll().LinkRouter().LinkExact().CanDeactivate().Centered()
                .HideAdd().AddIcon().CloseIcon()
                .Events();
        }
    }

    /// <summary>
    /// 标签渲染器
    /// </summary>
    public class TabRender : RenderBase
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化标签渲染器
        /// </summary>
        /// <param name="config">配置</param>
        public TabRender(Config config)
        {
            _config = config;
        }

        /// <summary>
        /// 获取标签生成器
        /// </summary>
        protected override TagBuilder GetTagBuilder()
        {
            var builder = new TabBuilder(_config);
            builder.Config();
            return builder;
        }

        /// <inheritdoc />
        public override IHtmlContent Clone()
        {
            return new TabRender(_config.Copy());
        }
    }

