    /// <summary>
    /// 标签容器标签生成器
    /// </summary>
    public class TagContainerTagBuilder : AngularTagBuilder
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;
        /// <summary>
        /// 标识
        /// </summary>
        private string _id;

        /// <summary>
        /// 初始化标签标签生成器
        /// </summary>
        /// <param name="config">配置</param>
        /// <param name="id">标识</param>
        public TagContainerTagBuilder(Config config, string id) : base(config, "ng-container")
        {
            _config = config;
            _id = id;
        }

        /// <summary>
        /// 扩展标识
        /// </summary>
        public string ExtendId => $"x_{GetId()}";

        /// <summary>
        /// 获取标识
        /// </summary>
        private string GetId()
        {
            if (_id.IsEmpty() == false)
                return _id;
            _id = _config.GetValue(UiConst.Id);
            if (_id.IsEmpty())
                _id = Util.Helpers.Id.Create();
            return _id;
        }

        /// <summary>
        /// 配置事件
        /// </summary>
        public TagContainerTagBuilder Events()
        {
            AttributeIfNotEmpty("(onLoad)", _config.GetValue(UiConst.OnLoad));
            AttributeIfNotEmpty("(selectedTextChange)", _config.GetValue(UiConst.OnSelectedTextChange));
            AttributeIfNotEmpty("(selectedValueChange)", _config.GetValue(UiConst.OnSelectedValueChange));
            AttributeIfNotEmpty("(allSelectedChange)", _config.GetValue(UiConst.OnAllSelectedChange));
            return this;
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.Config();
            Events();
            EnableExtend();
            AutoLoad().QueryParam().Url().Data()
                .AllSelected().SelectedText().SelectedValue();
        }

        /// <summary>
        /// 启用扩展
        /// </summary>
        public TagContainerTagBuilder EnableExtend()
        {
            Attribute($"#{ExtendId}", "xTagExtend");
            Attribute("x-tag-extend");
            return this;
        }

        /// <summary>
        /// 配置自动加载
        /// </summary>
        private TagContainerTagBuilder AutoLoad()
        {
            AttributeIfNotEmpty("[autoLoad]", _config.GetBoolValue(UiConst.AutoLoad));
            return this;
        }

        /// <summary>
        /// 配置查询参数
        /// </summary>
        private TagContainerTagBuilder QueryParam()
        {
            AttributeIfNotEmpty("[(queryParam)]", _config.GetValue(UiConst.QueryParam));
            return this;
        }

        /// <summary>
        /// 配置Api地址
        /// </summary>
        private TagContainerTagBuilder Url()
        {
            AttributeIfNotEmpty("url", _config.GetValue(UiConst.Url));
            AttributeIfNotEmpty("[url]", _config.GetValue(AngularConst.BindUrl));
            return this;
        }

        /// <summary>
        /// 配置数据源
        /// </summary>
        private TagContainerTagBuilder Data()
        {
            AttributeIfNotEmpty("[data]", _config.GetValue(UiConst.Data));
            return this;
        }

        /// <summary>
        /// 配置全部选中
        /// </summary>
        private TagContainerTagBuilder AllSelected()
        {
            AttributeIfNotEmpty("[(allSelected)]", _config.GetValue(UiConst.AllSelected));
            return this;
        }

        /// <summary>
        /// 配置选中文本
        /// </summary>
        private TagContainerTagBuilder SelectedText()
        {
            AttributeIfNotEmpty("[(selectedText)]", _config.GetValue(UiConst.SelectedText));
            return this;
        }

        /// <summary>
        /// 配置选中值
        /// </summary>
        private TagContainerTagBuilder SelectedValue()
        {
            AttributeIfNotEmpty("[(selectedValue)]", _config.GetValue(UiConst.SelectedValue));
            return this;
        }

        /// <summary>
        /// 配置内容
        /// </summary>
        /// <param name="config">配置</param>
        protected override void ConfigContent(Config config)
        {
        }
    }

    /// <summary>
    /// 标签标签生成器
    /// </summary>
    public class TagTagBuilder : AngularTagBuilder
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化标签标签生成器
        /// </summary>
        /// <param name="config">配置</param>
        /// <param name="isEnableExtend">是否启用扩展</param>
        /// <param name="extendId">扩展标识</param>
        public TagTagBuilder(Config config, bool isEnableExtend, string extendId) : base(config, "nz-tag")
        {
            _config = config;
            IsEnableExtend = isEnableExtend;
            ExtendId = extendId;
        }

        /// <summary>
        /// 是否启用扩展
        /// </summary>
        protected bool IsEnableExtend { get; }
        /// <summary>
        /// 扩展标识
        /// </summary>
        protected string ExtendId { get; }

        /// <summary>
        /// 配置模式
        /// </summary>
        public TagTagBuilder Mode()
        {
            AttributeIfNotEmpty("nzMode", _config.GetValue<TagMode?>(UiConst.Mode)?.Description());
            AttributeIfNotEmpty("[nzMode]", _config.GetValue(AngularConst.BindMode));
            return this;
        }

        /// <summary>
        /// 配置是否选中
        /// </summary>
        public TagTagBuilder Checked()
        {
            AttributeIfNotEmpty("[nzChecked]", _config.GetValue(UiConst.Checked));
            AttributeIfNotEmpty("[(nzChecked)]", _config.GetValue(AngularConst.BindonChecked));
            return this;
        }

        /// <summary>
        /// 配置颜色
        /// </summary>
        public TagTagBuilder Color()
        {
            AttributeIfNotEmpty("nzColor", _config.GetValue<TagColor?>(UiConst.ColorType)?.Description());
            AttributeIfNotEmpty("nzColor", _config.GetValue(UiConst.Color));
            AttributeIfNotEmpty("[nzColor]", _config.GetValue(AngularConst.BindColor));
            return this;
        }

        /// <summary>
        /// 配置边框
        /// </summary>
        public TagTagBuilder Bordered()
        {
            AttributeIfNotEmpty("[nzBordered]", _config.GetValue(UiConst.Bordered));
            return this;
        }

        /// <summary>
        /// 配置事件
        /// </summary>
        public TagTagBuilder Events()
        {
            AttributeIfNotEmpty("(click)", _config.GetValue(UiConst.OnClick));
            AttributeIfNotEmpty("(nzOnClose)", _config.GetValue(UiConst.OnClose));
            AttributeIfNotEmpty("(nzCheckedChange)", _config.GetValue(UiConst.OnCheckedChange));
            return this;
        }

        /// <summary>
        /// 配置Enabled文本
        /// </summary>
        public TagTagBuilder TextEnabled()
        {
            var value = _config.GetValue<bool?>(UiConst.TextEnabled);
            if (value != true)
                return this;
            var options = NgZorroOptionsService.GetOptions();
            if (options.EnableI18n)
            {
                _config.SetAttribute(UiConst.Text, "util.enabled");
                return this;
            }
            _config.SetAttribute(UiConst.Text, "Enabled");
            return this;
        }

        /// <summary>
        /// 配置Not Enabled文本
        /// </summary>
        public TagTagBuilder TextNotEnabled()
        {
            var value = _config.GetValue<bool?>(UiConst.TextNotEnabled);
            if (value != true)
                return this;
            var options = NgZorroOptionsService.GetOptions();
            if (options.EnableI18n)
            {
                _config.SetAttribute(UiConst.Text, "util.notEnabled");
                return this;
            }
            _config.SetAttribute(UiConst.Text, "Not Enabled");
            return this;
        }

        /// <summary>
        /// 配置文本
        /// </summary>
        public TagTagBuilder Text()
        {
            var options = NgZorroOptionsService.GetOptions();
            var text = _config.GetValue(UiConst.Text);
            if (text.IsEmpty())
                return this;
            if (options.EnableI18n)
            {
                this.AppendContentByI18n(text);
                return this;
            }
            AppendContent(text);
            return this;
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.Config();
            Mode().Checked().Color().Bordered().Events();
            TextEnabled().TextNotEnabled().Text();
            SetChecked();
        }

        /// <summary>
        /// 设置选中状态
        /// </summary>
        private void SetChecked()
        {
            if (IsEnableExtend == false)
                return;
            var mode = _config.GetValue<TagMode?>(UiConst.Mode);
            if (mode != TagMode.Checkable)
                return;
            if (_config.GetValue(UiConst.Checked).IsEmpty() == false)
                return;
            if (_config.GetValue(AngularConst.BindChecked).IsEmpty() == false)
                return;
            if (_config.GetValue(AngularConst.BindonChecked).IsEmpty() == false)
                return;
            Attribute("[nzChecked]", "item.selected");
            if (_config.GetValue(UiConst.OnCheckedChange).IsEmpty() == false)
                return;
            Attribute("(nzCheckedChange)", $"{ExtendId}.selectItem($event,item.text)");
        }

        /// <summary>
        /// 配置内容
        /// </summary>
        protected override void ConfigContent(Config config)
        {
            if (config.Content.IsEmpty() && IsEnableExtend)
            {
                var options = NgZorroOptionsService.GetOptions();
                if (options.EnableI18n)
                {
                    AppendContent("{{item.text|i18n}}");
                    return;
                }
                AppendContent("{{item.text}}");
                return;
            }
            base.ConfigContent(config);
        }
    }

    /// <summary>
    /// 标签表达式加载器
    /// </summary>
    public class TagExpressionLoader : NgZorroExpressionLoaderBase
    {
        /// <summary>
        /// 加载模型信息
        /// </summary>
        /// <param name="config">配置</param>
        /// <param name="info">模型表达式信息</param>
        protected override void Load(Config config, ModelExpressionInfo info)
        {
            LoadData(config, info);
        }

        /// <summary>
        /// 加载数据源
        /// </summary>
        protected virtual void LoadData(Config config, ModelExpressionInfo info)
        {
            LoadEnum(config, info);
        }

        /// <summary>
        /// 加载枚举值
        /// </summary>
        protected virtual void LoadEnum(Config config, ModelExpressionInfo info)
        {
            if (info.IsEnum == false)
                return;
            var items = Util.Helpers.Enum.GetItems(info.ModelType);
            var options = new JsonSerializerOptions
            {
                DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
                Encoder = JavaScriptEncoder.Create(UnicodeRanges.All)
            };
            var result = Util.Helpers.Json.ToJson(items, options, toSingleQuotes: true);
            config.SetAttribute(UiConst.Data, result, false);
        }
    }

    /// <summary>
    /// 标签渲染器
    /// </summary>
    public class TagRender : RenderBase
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化标签渲染器
        /// </summary>
        /// <param name="config">配置</param>
        public TagRender(Config config)
        {
            _config = config;
        }

        /// <summary>
        /// 获取标签生成器
        /// </summary>
        protected override TagBuilder GetTagBuilder()
        {
            var config = _config.Copy();
            config.RemoveAttribute(UiConst.Id);
            var containerTagBuilder = new TagContainerTagBuilder(config, _config.GetValue(UiConst.Id));
            containerTagBuilder.Config();
            TagBuilder container = IsEnableExtend() ? containerTagBuilder : new EmptyContainerTagBuilder();
            if (IsEnableExtend())
            {
                container.AppendContent($"@for(item of {containerTagBuilder.ExtendId}.options;track item.text)");
                container.AppendContent("{");
            }
            var builder = new TagTagBuilder(_config, IsEnableExtend(), containerTagBuilder.ExtendId);
            container.AppendContent(builder);
            builder.Config();
            if (IsEnableExtend())
            {
                container.AppendContent("}");
            }
            return container;
        }

        /// <summary>
        /// 是否启用基础扩展
        /// </summary>
        public bool IsEnableExtend()
        {
            if (GetEnableExtend() == false)
                return false;
            return GetEnableExtend() == true ||
                   GetUrl().IsEmpty() == false ||
                   GetBindUrl().IsEmpty() == false ||
                   GetData().IsEmpty() == false;
        }

        /// <summary>
        /// 获取启用扩展属性
        /// </summary>
        private bool? GetEnableExtend()
        {
            return _config.GetValue<bool?>(UiConst.EnableExtend);
        }

        /// <summary>
        /// 获取地址
        /// </summary>
        private string GetUrl()
        {
            return _config.GetValue(UiConst.Url);
        }

        /// <summary>
        /// 获取地址
        /// </summary>
        private string GetBindUrl()
        {
            return _config.GetValue(AngularConst.BindUrl);
        }

        /// <summary>
        /// 获取数据源
        /// </summary>
        private string GetData()
        {
            return _config.GetValue(UiConst.Data);
        }

        /// <inheritdoc />
        public override IHtmlContent Clone()
        {
            return new TagRender(_config.Copy());
        }
    }

    /// <summary>
    /// 标签,生成的标签为&lt;nz-tag>&lt;/nz-tag>
    /// </summary>
    [HtmlTargetElement("tag")]
    public class TagTagHelper : AngularTagHelperBase
    {
        /// <summary>
