            AttributeIfNotEmpty("(nzDblClick)", _config.GetValue(UiConst.OnDblClick));
            AttributeIfNotEmpty("(nzCheckBoxChange)", _config.GetValue(UiConst.OnCheckboxChange));
            OnExpandChange(_config.GetValue(UiConst.OnExpandChange));
            AttributeIfNotEmpty("(nzSearchValueChange)", _config.GetValue(UiConst.OnSearchValueChange));
            AttributeIfNotEmpty("(nzOnDragStart)", _config.GetValue(UiConst.OnDragStart));
            AttributeIfNotEmpty("(nzOnDragEnter)", _config.GetValue(UiConst.OnDragEnter));
            AttributeIfNotEmpty("(nzOnDragOver)", _config.GetValue(UiConst.OnDragOver));
            AttributeIfNotEmpty("(nzOnDragLeave)", _config.GetValue(UiConst.OnDragLeave));
            AttributeIfNotEmpty("(nzOnDrop)", _config.GetValue(UiConst.OnDrop));
            AttributeIfNotEmpty("(nzOnDragEnd)", _config.GetValue(UiConst.OnDragEnd));
            AttributeIfNotEmpty("(onLoad)", _config.GetValue(UiConst.OnLoad));
            return this;
        }

        /// <summary>
        /// 展开收缩节点事件
        /// </summary>
        public TreeBuilder OnExpandChange(string value)
        {
            AttributeIfNotEmpty("(nzExpandChange)", value);
            return this;
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.Config();
            Data().BlockNode().Checkable().ShowExpand().ShowLine().ExpandedIcon().ShowIcon()
                .AsyncData().Draggable().Multiple().HideUnMatched().CheckStrictly().TreeTemplate().ExpandAll()
                .ExpandedKeys().CheckedKeys().SelectedKeys()
                .SearchValue().SearchFunc().BeforeDrop()
                .VirtualHeight().VirtualItemSize().VirtualMaxBufferPx().VirtualMinBufferPx()
                .Events();
            _service.ConfigBuilder(this);
            ConfigDefault();
        }

        /// <summary>
        /// 配置默认属性
        /// </summary>
        private void ConfigDefault()
        {
            if (_service.IsEnableExtend() == false)
                return;
            Checkable("true").
                Data($"{ExtendId}.dataSource")
                .CheckedKeys($"{ExtendId}.checkedKeys")
                .SelectedKeys($"{ExtendId}.selectedKeys")
                .OnExpandChange($"{ExtendId}.expandChange($event)");
        }

        /// <summary>
        /// 配置右键上下文菜单事件
        /// </summary>
        protected override void ConfigOnContextmenu(Config config)
        {
            AttributeIfNotEmpty("(nzContextMenu)", _config.GetValue(UiConst.OnContextmenu));
        }
    }

    /// <summary>
    /// 树形服务
    /// </summary>
    public class TreeService
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 标识
        /// </summary>
        private string _id;

        /// <summary>
        /// 初始化树形服务
        /// </summary>
        /// <param name="config">配置</param>
        public TreeService(Config config)
        {
            _config = config;
        }

        /// <summary>
        /// 扩展标识
        /// </summary>
        public string ExtendId => $"x_{GetId()}";

        /// <summary>
        /// 获取标识
        /// </summary>
        private string GetId()
        {
            if (_id.IsEmpty() == false)
                return _id;
            _id = _config.GetValue(UiConst.Id);
            if (_id.IsEmpty())
                _id = Id.Create();
            return _id;
        }

        /// <summary>
        /// 是否启用基础扩展
        /// </summary>
        public bool IsEnableExtend()
        {
            if (GetEnableExtend() == false)
            {
                return false;
            }
            if (GetEnableExtend() == true ||
                 GetUrl().IsEmpty() == false ||
                 GetBindUrl().IsEmpty() == false ||
                 GetLoadUrl().IsEmpty() == false ||
                 GetBindLoadUrl().IsEmpty() == false ||
                 GetQueryUrl().IsEmpty() == false ||
                 GetBindQueryUrl().IsEmpty() == false ||
                 GetLoadChildrenUrl().IsEmpty() == false ||
                 GetBindLoadChildrenUrl().IsEmpty() == false)
            {
                return true;
            }
            return false;
        }

        /// <summary>
        /// 获取启用扩展属性
        /// </summary>
        private bool? GetEnableExtend()
        {
            return _config.GetValue<bool?>(UiConst.EnableExtend);
        }

        /// <summary>
        /// 获取地址
        /// </summary>
        private string GetUrl()
        {
            return _config.GetValue(UiConst.Url);
        }

        /// <summary>
        /// 获取地址
        /// </summary>
        private string GetBindUrl()
        {
            return _config.GetValue(AngularConst.BindUrl);
        }

        /// <summary>
        /// 获取加载地址
        /// </summary>
        private string GetLoadUrl()
        {
            return _config.GetValue(UiConst.LoadUrl);
        }

        /// <summary>
        /// 获取加载地址
        /// </summary>
        private string GetBindLoadUrl()
        {
            return _config.GetValue(AngularConst.BindLoadUrl);
        }

        /// <summary>
        /// 获取查询地址
        /// </summary>
        private string GetQueryUrl()
        {
            return _config.GetValue(UiConst.QueryUrl);
        }

        /// <summary>
        /// 获取查询地址
        /// </summary>
        private string GetBindQueryUrl()
        {
            return _config.GetValue(AngularConst.BindQueryUrl);
        }

        /// <summary>
        /// 获取加载下级节点地址
        /// </summary>
        private string GetLoadChildrenUrl()
        {
            return _config.GetValue(UiConst.LoadChildrenUrl);
        }

        /// <summary>
        /// 获取加载下级节点地址
        /// </summary>
        private string GetBindLoadChildrenUrl()
        {
            return _config.GetValue(AngularConst.BindLoadChildrenUrl);
        }

        /// <summary>
        /// 配置标签生成器
        /// </summary>
        /// <param name="builder">标签生成器</param>
        public void ConfigBuilder(TagBuilder builder)
        {
            Url(builder);
            LoadUrl(builder);
            QueryUrl(builder);
            LoadChildrenUrl(builder);
            AutoLoad(builder);
            QueryParam(builder);
            Sort(builder);
            ExpandForRootAsync(builder);
            LoadMode(builder);
            Events(builder);
            ConfigExtend(builder);
        }

        /// <summary>
        /// 配置Api地址
        /// </summary>
        private void Url(TagBuilder builder)
        {
            builder.AttributeIfNotEmpty("url", _config.GetValue(UiConst.Url));
            builder.AttributeIfNotEmpty("[url]", _config.GetValue(AngularConst.BindUrl));
        }

        /// <summary>
        /// 配置加载地址
        /// </summary>
        private void LoadUrl(TagBuilder builder)
        {
            builder.AttributeIfNotEmpty("loadUrl", _config.GetValue(UiConst.LoadUrl));
            builder.AttributeIfNotEmpty("[loadUrl]", _config.GetValue(AngularConst.BindLoadUrl));
        }

        /// <summary>
        /// 配置查询地址
        /// </summary>
        private void QueryUrl(TagBuilder builder)
        {
            builder.AttributeIfNotEmpty("queryUrl", _config.GetValue(UiConst.QueryUrl));
            builder.AttributeIfNotEmpty("[queryUrl]", _config.GetValue(AngularConst.BindQueryUrl));
        }

        /// <summary>
        /// 配置加载子节点地址
        /// </summary>
        private void LoadChildrenUrl(TagBuilder builder)
        {
            builder.AttributeIfNotEmpty("loadChildrenUrl", _config.GetValue(UiConst.LoadChildrenUrl));
            builder.AttributeIfNotEmpty("[loadChildrenUrl]", _config.GetValue(AngularConst.BindLoadChildrenUrl));
        }

        /// <summary>
        /// 配置自动加载
        /// </summary>
        private void AutoLoad(TagBuilder builder)
        {
            builder.AttributeIfNotEmpty("[autoLoad]", _config.GetBoolValue(UiConst.AutoLoad));
        }

        /// <summary>
        /// 配置查询参数
        /// </summary>
        private void QueryParam(TagBuilder builder)
        {
            builder.AttributeIfNotEmpty("[(queryParam)]", _config.GetValue(UiConst.QueryParam));
        }

        /// <summary>
        /// 配置排序条件
        /// </summary>
        private void Sort(TagBuilder builder)
        {
            builder.AttributeIfNotEmpty("order", _config.GetValue(UiConst.Sort));
            builder.AttributeIfNotEmpty("[order]", _config.GetValue(AngularConst.BindSort));
        }

        /// <summary>
        /// 配置根节点异步加载模式是否展开子节点
        /// </summary>
        private void ExpandForRootAsync(TagBuilder builder)
        {
            builder.AttributeIfNotEmpty("[isExpandForRootAsync]", _config.GetBoolValue(UiConst.ExpandForRootAsync));
        }

        /// <summary>
        /// 配置加载模式
        /// </summary>
        private void LoadMode(TagBuilder builder)
        {
            var value = _config.GetValue<LoadMode?>(UiConst.LoadMode);
            if (value == null)
                return;
            builder.AttributeIfNotEmpty("loadMode", value.Value().SafeString());
            if (value == Applications.Trees.LoadMode.Sync)
                return;
            builder.AttributeIfNotEmpty("[nzAsyncData]", "true");
        }

        /// <summary>
        /// 配置事件
        /// </summary>
        private void Events(TagBuilder builder)
        {
            builder.AttributeIfNotEmpty("[onLoadChildrenBefore]", _config.GetValue(UiConst.OnLoadChildrenBefore));
            builder.AttributeIfNotEmpty("(onLoadChildren)", _config.GetValue(UiConst.OnLoadChildren));
            builder.AttributeIfNotEmpty("(onExpand)", _config.GetValue(UiConst.OnExpand));
            builder.AttributeIfNotEmpty("(onCollapse)", _config.GetValue(UiConst.OnCollapse));
        }

        /// <summary>
        /// 配置树形扩展指令及默认属性
        /// </summary>
        public void ConfigExtend(TagBuilder builder)
        {
            if (IsEnableExtend() == false)
                return;
            builder.Attribute("x-tree-extend");
            builder.Attribute($"#{ExtendId}", "xTreeExtend");
        }
    }

    /// <summary>
    /// 树形控件渲染器
    /// </summary>
    public class TreeRender : RenderBase
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化树形控件渲染器
        /// </summary>
        /// <param name="config">配置</param>
        public TreeRender(Config config)
        {
            _config = config;
        }

        /// <summary>
        /// 获取标签生成器
        /// </summary>
        protected override TagBuilder GetTagBuilder()
        {
            var builder = new TreeBuilder(_config);
            builder.Config();
            return builder;
        }

        /// <inheritdoc />
        public override IHtmlContent Clone()
        {
            return new TreeRender(_config.Copy());
        }
    }

    /// <summary>
    /// 树形,生成的标签为&lt;nz-tree>&lt;/nz-tree>
    /// </summary>
    [HtmlTargetElement("tree")]
    public class TreeTagHelper : AngularTagHelperBase
    {
        /// <summary>
        /// [nzData],数据源,类型: NzTreeNodeOptions[] | NzTreeNode[],默认值: []
        /// </summary>
        public string Data { get; set; }
        /// <summary>
        /// [nzCheckedKeys],指定选中复选框的节点标识列表,类型: string[]
        /// </summary>
        public string CheckedKeys { get; set; }
        /// <summary>
        /// [nzExpandedKeys],指定展开的节点标识列表,类型: string[]
        /// </summary>
        public string ExpandedKeys { get; set; }
        /// <summary>
        /// [nzSelectedKeys],指定选中的节点标识列表,类型: string[]
        /// </summary>
        public string SelectedKeys { get; set; }
        /// <summary>
        /// [nzCheckable],节点前是否显示复选框,类型: boolean, 默认值: false
        /// </summary>
        public string Checkable { get; set; }
        /// <summary>
        /// [nzCheckStrictly],严格勾选,父子节点选中状态不再关联,类型: boolean, 默认值: false
        /// </summary>
        public string CheckStrictly { get; set; }
        /// <summary>
        /// [nzDraggable],节点是否可拖拽,类型: boolean, 默认值: false
        /// </summary>
        public string Draggable { get; set; }
        /// <summary>
        /// [nzMultiple],是否支持点选多个节点,类型: boolean, 默认值: false
        /// </summary>
        public string Multiple { get; set; }
        /// <summary>
        /// [nzExpandAll],是否默认展开所有节点,类型: boolean, 默认值: false
        /// </summary>
        public string ExpandAll { get; set; }
        /// <summary>
        /// [nzBlockNode],节点是否占据一行,类型: boolean, 默认值: false
        /// </summary>
        public string BlockNode { get; set; }
        /// <summary>
        /// [nzAsyncData],是否异步加载,类型: boolean, 默认值: false
        /// </summary>
        public string AsyncData { get; set; }
        /// <summary>
        /// [nzShowLine],是否显示连接线,类型: boolean, 默认值: false
        /// </summary>
        public string ShowLine { get; set; }
        /// <summary>
        /// [nzShowExpand],节点前是否显示展开图标,类型: boolean, 默认值: true
        /// </summary>
        public string ShowExpand { get; set; }
        /// <summary>
        /// [nzShowIcon],是否显示节点文本前图标,没有默认样式,类型: boolean,默认值: false
        /// </summary>
        public string ShowIcon { get; set; }
        /// <summary>
        /// [nzBeforeDrop],拖拽前二次校验函数，决定是否允许放置,类型: (confirm: NzFormatBeforeDropEvent) => Observable&lt;boolean>
        /// </summary>
        public string BeforeDrop { get; set; }
        /// <summary>
        /// [nzExpandedIcon],自定义展开图标,类型: TemplateRef&lt;{ $implicit: NzTreeNode }>
        /// </summary>
        public string ExpandedIcon { get; set; }
        /// <summary>
        /// [nzTreeTemplate],自定义节点模板,类型: TemplateRef&lt;{ $implicit: NzTreeNode }>
        /// </summary>
        public string TreeTemplate { get; set; }
        /// <summary>
        /// nzSearchValue,搜索值,高亮节点,默认值: null
        /// </summary>
        public string SearchValue { get; set; }
        /// <summary>
        /// [nzSearchValue],搜索值,高亮节点,默认值: null
        /// </summary>
        public string BindSearchValue { get; set; }
        /// <summary>
        /// [(nzSearchValue)],搜索值,高亮节点,默认值: null
        /// </summary>
        public string BindonSearchValue { get; set; }
        /// <summary>
        /// [nzSearchFunc],自定义搜索方法，类型: (node: NzTreeNodeOptions) => boolean,默认值: null
        /// </summary>
        public string SearchFunc { get; set; }
        /// <summary>
        /// [nzHideUnMatched],是否隐藏搜索未匹配节点,类型: boolean, 默认值: false
        /// </summary>
        public string HideUnmatched { get; set; }
        /// <summary>
        /// nzVirtualHeight,虚拟滚动的总高度,范例: '300px'
        /// </summary>
        public string VirtualHeight { get; set; }
        /// <summary>
        /// [nzVirtualHeight],虚拟滚动的总高度,范例: '300px'
        /// </summary>
        public string BindVirtualHeight { get; set; }
        /// <summary>
        /// [nzVirtualItemSize],虚拟滚动时每一列的高度,类型: number, 单位:像素, 默认值: 28
        /// </summary>
        public string VirtualItemSize { get; set; }
        /// <summary>
        /// [nzVirtualMaxBufferPx],虚拟滚动缓冲区最大高度,类型: number, 单位:像素,默认值: 500
        /// </summary>
        public string VirtualMaxBufferPx { get; set; }
        /// <summary>
        /// [nzVirtualMinBufferPx],虚拟滚动缓冲区最小高度，低于该值时将加载新结构,类型: number, 单位:像素,默认值: 28
        /// </summary>
        public string VirtualMinBufferPx { get; set; }
        /// <summary>
        /// (nzClick),单击事件,点击树节点时触发,类型: EventEmitter&lt;NzFormatEmitEvent>
        /// </summary>
        public string OnClick { get; set; }
        /// <summary>
        /// (nzDblClick),双击事件,双击树节点时触发,类型: EventEmitter&lt;NzFormatEmitEvent>
        /// </summary>
        public string OnDblClick { get; set; }
        /// <summary>
        /// (nzContextMenu),上下文菜单事件,右键点击树节点时触发,类型: EventEmitter&lt;NzFormatEmitEvent>
        /// </summary>
        public new string OnContextmenu { get; set; }
        /// <summary>
        /// (nzCheckBoxChange),树节点复选框选中状态变化事件,点击树节点复选框时触发,类型: EventEmitter&lt;NzFormatEmitEvent>
        /// </summary>
        public string OnCheckboxChange { get; set; }
        /// <summary>
        /// (nzExpandChange),展开收缩节点事件,点击展开树节点图标时触发,类型: EventEmitter&lt;NzFormatEmitEvent>
        /// </summary>
        public string OnExpandChange { get; set; }
        /// <summary>
        /// (nzSearchValueChange),搜索值变化事件,搜索节点时触发,与 nzSearchValue 配合使用,类型: EventEmitter&lt;NzFormatEmitEvent>
        /// </summary>
        public string OnSearchValueChange { get; set; }
        /// <summary>
        /// (nzOnDragStart),开始拖拽时触发,类型: EventEmitter&lt;NzFormatEmitEvent>
        /// </summary>
        public string OnDragStart { get; set; }
        /// <summary>
        /// (nzOnDragEnter),拖拽树节点进入目标容器范围时触发,类型: EventEmitter&lt;NzFormatEmitEvent>
        /// </summary>
        public string OnDragEnter { get; set; }
        /// <summary>
        /// (nzOnDragOver),拖拽树节点在目标容器范围内移动时触发,类型: EventEmitter&lt;NzFormatEmitEvent>
        /// </summary>
        public string OnDragOver { get; set; }
        /// <summary>
        /// (nzOnDragLeave),拖拽树节点离开目标容器范围时触发,类型: EventEmitter&lt;NzFormatEmitEvent>
        /// </summary>
        public string OnDragLeave { get; set; }
        /// <summary>
        /// (nzOnDragEnd),拖拽结束时触发,类型: EventEmitter&lt;NzFormatEmitEvent>
        /// </summary>
        public string OnDragEnd { get; set; }
        /// <summary>
        /// (nzOnDrop),鼠标在拖放目标上释放时触发,类型: EventEmitter&lt;NzFormatEmitEvent>
        /// </summary>
        public string OnDrop { get; set; }
        /// <summary>
        /// 扩展属性,是否启用扩展指令,当设置Api地址时自动启用
        /// </summary>
        public bool EnableExtend { get; set; }
        /// <summary>
        /// 扩展属性 [autoLoad],初始化时是否自动加载数据，默认为true,设置成false则手工加载
        /// </summary>
        public bool AutoLoad { get; set; }
        /// <summary>
        /// 扩展属性 url,Api地址
        /// </summary>
        public string Url { get; set; }
        /// <summary>
        /// 扩展属性 [url],Api地址
        /// </summary>
        public string BindUrl { get; set; }
        /// <summary>
        /// 扩展属性 loadUrl,首次加载地址，对于异步请求,仅加载第一级节点,如果未设置该属性,则使用 url 地址
        /// </summary>
        public string LoadUrl { get; set; }
        /// <summary>
        /// 扩展属性 [loadUrl],首次加载地址，对于异步请求,仅加载第一级节点,如果未设置该属性,则使用 url 地址
        /// </summary>
        public string BindLoadUrl { get; set; }
        /// <summary>
        /// 扩展属性 queryUrl,查询地址，如果未设置该属性,则使用 url 地址
        /// </summary>
        public string QueryUrl { get; set; }
        /// <summary>
        /// 扩展属性 [queryUrl],查询地址，如果未设置该属性,则使用 url 地址
        /// </summary>
        public string BindQueryUrl { get; set; }
        /// <summary>
        /// 扩展属性 loadChildrenUrl,加载子节点地址，如果未设置该属性,则使用 url 地址
        /// </summary>
        public string LoadChildrenUrl { get; set; }
        /// <summary>
        /// 扩展属性 [loadChildrenUrl],加载子节点地址，如果未设置该属性,则使用 url 地址
        /// </summary>
        public string BindLoadChildrenUrl { get; set; }
        /// <summary>
        /// 扩展属性 loadMode,加载模式，默认为同步加载
        /// </summary>
        public LoadMode LoadMode { get; set; }
        /// <summary>
        /// 扩展属性 [isExpandForRootAsync],根节点异步加载模式是否展开子节点,默认为 true
        /// </summary>
        public bool ExpandForRootAsync { get; set; }
        /// <summary>
        /// 扩展属性[(queryParam)],查询参数
        /// </summary>
        public string QueryParam { get; set; }
        /// <summary>
        /// 扩展属性 order,排序条件,范例: creationTime desc
        /// </summary>
        public string Sort { get; set; }
        /// <summary>
        /// 扩展属性 [order],排序条件,范例: creationTime desc
        /// </summary>
        public string BindSort { get; set; }
        /// <summary>
        /// 扩展属性 [onLoadChildrenBefore],子节点加载前事件,返回false停止加载,类型: (parentNode:NzTreeNode,queryParam) => boolean,参数为父节点和查询参数
        /// </summary>
        public string OnLoadChildrenBefore { get; set; }
        /// <summary>
        /// 扩展事件 (onLoadChildren),子节点加载完成事件,类型: EventEmitter&lt;{ node: NzTreeNode, result }>
        /// </summary>
        public string OnLoadChildren { get; set; }
        /// <summary>
        /// 扩展事件 (onExpand),节点展开事件,类型: EventEmitter&lt;NzTreeNode>
        /// </summary>
        public string OnExpand { get; set; }
        /// <summary>
        /// 扩展事件 (onCollapse),节点折叠事件,类型: EventEmitter&lt;NzTreeNode>
        /// </summary>
        public string OnCollapse { get; set; }
        /// <summary>
        /// 扩展事件 (onLoad),数据加载完成事件,参数为服务端返回结果
        /// </summary>
        public string OnLoad { get; set; }

        /// <inheritdoc />
        protected override IRender GetRender(TagHelperContext context, TagHelperOutput output, TagHelperContent content)
        {
            var config = new Config(context, output, content);
            return new TreeRender(config);
        }
    }

