    #region TreeSelects
    /// <summary>
    /// 树形选择标签生成器
    /// </summary>
    public class TreeSelectBuilder : FormControlBuilderBase<TreeSelectBuilder>
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;
        /// <summary>
        /// 树形服务
        /// </summary>
        private readonly TreeService _service;

        /// <summary>
        /// 初始化树选择标签生成器
        /// </summary>
        /// <param name="config">配置</param>
