        /// </summary>
        public TreeTableBuilder LoadUrl()
        {
            AttributeIfNotEmpty("loadUrl", _config.GetValue(UiConst.LoadUrl));
            AttributeIfNotEmpty("[loadUrl]", _config.GetValue(AngularConst.BindLoadUrl));
            return this;
        }

        /// <summary>
        /// 配置查询地址
        /// </summary>
        public TreeTableBuilder QueryUrl()
        {
