        /// <summary>
        /// 配置间距项
        /// </summary>
        public UploadBuilder SpaceItem()
        {
            var shareConfig = GetShareConfig();
            if (shareConfig.FormItemCreated)
                return this;
            this.SpaceItem(shareConfig.SpaceItem);
            return this;
        }

        /// <summary>
        /// 获取表单项共享配置
        /// </summary>
        private FormItemShareConfig GetShareConfig()
        {
            return _config.GetValueFromItems<FormItemShareConfig>() ?? new FormItemShareConfig();
        }

        /// <summary>
        /// 配置
        /// </summary>
        public override void Config()
        {
            base.ConfigBase(_config);
            Accept().Action().Directory().BeforeUpload().CustomRequest()
                .Data().Disabled().FileList().Limit().Size().FileType().Filter()
                .Headers().ListType().Multiple().Name()
                .ShowUploadList().ShowButton().WithCredentials().OpenFileDialogOnClick()
                .Preview().PreviewFile().PreviewIsImage()
                .Remove().Download().TransformFile()
                .IconRender().FileListRender()
                .Events();
            Model().SpaceItem();
            AddButton();
            EnableExtend();
        }

        /// <summary>
        /// 添加按钮
        /// </summary>
        private void AddButton()
        {
            var buttonBuilder = new ButtonBuilder(_config);
            buttonBuilder.Attribute("nz-button");
            buttonBuilder.Icon(AntDesignIcon.Upload);
            buttonBuilder.AppendContentByI18n(I18nKeys.Upload);
            AppendContent(buttonBuilder);
        }

        /// <summary>
        /// 启用扩展
        /// </summary>
        public UploadBuilder EnableExtend()
        {
            if (IsEnableExtend() == false)
                return this;
            Attribute($"#{ExtendId}", "xUploadExtend");
            Attribute("x-upload-extend");
            AddInput();
            SetFileList();
            HandleChange();
            ClearFiles();
            ModelToFilesDebounceTime();
            SetFilter();
            return this;
        }

        /// <summary>
        /// 是否启用基础扩展
        /// </summary>
        public bool IsEnableExtend()
        {
            if (GetEnableExtend() == false)
            {
                return false;
            }
            return GetEnableExtend() == true ||
                   IsContainsModel() ||
                   GetRequired() == true;
        }

        /// <summary>
        /// 获取启用扩展属性
        /// </summary>
        protected bool? GetEnableExtend()
        {
            return _config.GetValue<bool?>(UiConst.EnableExtend);
        }

        /// <summary>
        /// 是否包含模型绑定
        /// </summary>
        protected bool IsContainsModel()
        {
            return _config.GetValue(AngularConst.NgModel).IsEmpty() == false;
        }

        /// <summary>
        /// 获取是否必填项
        /// </summary>
        protected bool? GetRequired()
        {
            return _config.GetValue<bool?>(UiConst.Required);
        }

        /// <summary>
        /// 添加输入框,用于支持验证
        /// </summary>
        protected void AddInput()
        {
            if (GetRequired() != true)
                return;
            var inputBuilder = new InputBuilder(_config);
            inputBuilder.Attribute("style", "display: none");
            inputBuilder.Name($"input_{GetId()}")
                .ValidationExtend()
                .BindNgModel($"{ExtendId}.inputValue")
                .Attribute("[required]", "true");
            PostBuilder = inputBuilder;
        }

        /// <summary>
        /// 配置文件列表
        /// </summary>
        public void SetFileList()
        {
            if (_config.GetValue<bool>(AngularConst.NotBindFileList))
                return;
            if (_config.Contains(UiConst.FileList))
                return;
            if (_config.Contains(AngularConst.BindonFileList))
                return;
            Attribute("[(nzFileList)]", $"{ExtendId}.files");
        }

        /// <summary>
        /// 配置文件状态变更处理函数
        /// </summary>
        public void HandleChange()
        {
            if (_config.Contains(UiConst.OnChange))
                return;
            Attribute("(nzChange)", $"{ExtendId}.handleChange($event)");
        }

        /// <summary>
        /// 配置是否清除文件列表
        /// </summary>
        public void ClearFiles()
        {
            AttributeIfNotEmpty("[isClearFiles]", _config.GetValue(UiConst.ClearFiles));
        }

        /// <summary>
        /// 配置模型数据转换为上传文件列表的延迟时间
        /// </summary>
        public void ModelToFilesDebounceTime()
        {
            AttributeIfNotEmpty("[modelToFilesDebounceTime]", _config.GetValue(UiConst.ModelToFilesDebounceTime));
        }

        /// <summary>
        /// 配置过滤器
        /// </summary>
        public void SetFilter()
        {
            if (_config.Contains(UiConst.Filter))
                return;
            Filter($"{ExtendId}.filters");
        }
    }

    /// <summary>
    /// 上传组件表达式加载器
    /// </summary>
    public class UploadExpressionLoader : NgZorroExpressionLoaderBase
    {
        /// <summary>
        /// 加载模型信息
        /// </summary>
        /// <param name="config">配置</param>
        /// <param name="info">模型表达式信息</param>
        protected override void Load(Config config, ModelExpressionInfo info)
        {
            LoadLabel(config, info);
            LoadId(config, info);
            LoadNgModel(config, info);
            LoadRequired(config, info);
        }

        /// <summary>
        /// 加载标签
        /// </summary>
        protected virtual void LoadLabel(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(UiConst.LabelText, info.DisplayName, false);
        }

        /// <summary>
        /// 加载标识
        /// </summary>
        protected virtual void LoadId(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(UiConst.Id, GeKebaberizePropertyName(config, info), false);
        }

        /// <summary>
        /// 加载模型绑定
        /// </summary>
        protected virtual void LoadNgModel(Config config, ModelExpressionInfo info)
        {
            config.SetAttribute(AngularConst.NgModel, info.SafePropertyName, false);
        }

        /// <summary>
        /// 加载必填项验证
        /// </summary>
        protected virtual void LoadRequired(Config config, ModelExpressionInfo info)
        {
            if (info.IsRequired == false)
                return;
            config.SetAttribute(UiConst.Required, "true", false);
            config.SetAttribute(UiConst.RequiredMessage, info.RequiredMessage, false);
        }
    }

    /// <summary>
    /// 上传组件服务
    /// </summary>
    public class UploadService
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化上传组件服务
        /// </summary>
        /// <param name="config">配置</param>
        public UploadService(Config config)
        {
            _config = config;
        }

        /// <summary>
        /// 初始化
        /// </summary>
        public void Init()
        {
            LoadExpression();
            InitValidationService();
            InitFormShareService();
            InitFormItemShareService();
        }

        /// <summary>
        /// 加载表达式
        /// </summary>
        private void LoadExpression()
        {
            var loader = new UploadExpressionLoader();
            loader.Load(_config);
        }

        /// <summary>
        /// 初始化验证服务
        /// </summary>
        private void InitValidationService()
        {
            var service = new ValidationService(_config);
            service.Init();
        }

        /// <summary>
        /// 初始化表单共享服务
        /// </summary>
        private void InitFormShareService()
        {
            var service = new FormShareService(_config);
            service.Init();
        }

        /// <summary>
        /// 初始化表单项共享服务
        /// </summary>
        private void InitFormItemShareService()
        {
            var service = new FormItemShareService(_config);
            service.Init();
            service.InitId();
        }
    }

    /// <summary>
    /// 上传渲染器
    /// </summary>
    public class UploadRender : FormControlRenderBase
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化上传渲染器
        /// </summary>
        /// <param name="config">配置</param>
        public UploadRender(Config config) : base(config)
        {
            _config = config;
        }

        /// <summary>
        /// 添加表单控件
        /// </summary>
        protected override void AppendControl(TagBuilder formControlBuilder)
        {
            var builder = new UploadBuilder(_config);
            builder.Config();
            _config.Content.SetTo(builder);
            formControlBuilder.AppendContent(builder);
        }

        /// <inheritdoc />
        public override IHtmlContent Clone()
        {
            return new UploadRender(_config.Copy());
        }
    }

