    #region Data
    /// <summary>
    /// Ng-Zorro树节点
    /// </summary>
    public class NgZorroTreeNode
    {
        /// <summary>
        /// 标识
        /// </summary>
        public string Key { get; set; }
        /// <summary>
        /// 标题
        /// </summary>
        public string Title { get; set; }
        /// <summary>
        /// 图标
        /// </summary>
        public string Icon { get; set; }
        /// <summary>
        /// 是否叶节点
        /// </summary>
        public bool IsLeaf { get; set; }
        /// <summary>
        /// 是否展开
        /// </summary>
        public bool Expanded { get; set; }
        /// <summary>
        /// 是否禁用
        /// </summary>
        public bool Disabled { get; set; }
        /// <summary>
        /// 是否禁用复选框
        /// </summary>
        public bool DisableCheckbox { get; set; }
        /// <summary>
        /// 是否可选中
        /// </summary>
        public bool Selectable { get; set; } = true;
        /// <summary>
        /// 复选框是否被选中
        /// </summary>
        public bool Checked { get; set; }
        /// <summary>
        /// 当前节点是否被选中
        /// </summary>
        public bool Selected { get; set; }
        /// <summary>
        /// 原始节点
        /// </summary>
        public object OriginalNode { get; set; }
        /// <summary>
        /// 子节点列表
        /// </summary>
        public List<NgZorroTreeNode> Children { get; set; }

        /// <summary>
        /// 获取原始节点
        /// </summary>
        /// <typeparam name="TNode">原始节点类型</typeparam>
        public TNode GetOriginalNode<TNode>()
        {
            return Util.Helpers.Convert.To<TNode>(OriginalNode);
        }
    }

    /// <summary>
    /// Ng-Zorro树形结果
    /// </summary>
    public class NgZorroTreeResult
    {
        /// <summary>
        /// 初始化树形结果
        /// </summary>
        public NgZorroTreeResult()
        {
            Nodes = new List<NgZorroTreeNode>();
            CheckedKeys = new List<string>();
            SelectedKeys = new List<string>();
        }

        /// <summary>
        /// 树节点列表
        /// </summary>
        public List<NgZorroTreeNode> Nodes { get; set; }
        /// <summary>
        /// 复选框选中节点标识列表
        /// </summary>
        public List<string> CheckedKeys { get; set; }
        /// <summary>
        /// 选中节点标识列表
        /// </summary>
        public List<string> SelectedKeys { get; set; }
    }

    /// <summary>
    /// 树形结果
    /// </summary>
    public class TreeResult<TNode> : TreeResultBase<TNode, NgZorroTreeNode, NgZorroTreeResult> where TNode : TreeDtoBase<TNode>
    {
        /// <summary>
        /// 树形结果
        /// </summary>
        private readonly NgZorroTreeResult _result;

        /// <summary>
        /// 初始化树形结果
        /// </summary>
        /// <param name="data">树形参数列表</param>
        /// <param name="async">是否异步加载</param>
        /// <param name="allExpand">所有节点是否全部展开</param>
        public TreeResult(IEnumerable<TNode> data, bool async = false, bool allExpand = false) : base(data, async, allExpand)
        {
            _result = new NgZorroTreeResult();
        }

        /// <summary>
        /// 转换为目标节点
        /// </summary>
        protected override NgZorroTreeNode ToDestinationNode(TNode dto)
        {
            List<TNode> children = dto.Children;
            dto.Children = null;
            var result = new NgZorroTreeNode
            {
                Key = dto.Id,
                Title = dto.GetText(),
                Icon = dto.Icon,
                Disabled = !dto.Enabled.SafeValue(),
                Expanded = dto.Expanded.SafeValue(),
                Checked = dto.Checked.SafeValue(),
                DisableCheckbox = dto.DisableCheckbox.SafeValue(),
                Selectable = dto.Selectable.SafeValue(),
                Selected = dto.Selected.SafeValue(),
                IsLeaf = dto.Leaf.SafeValue(),
                OriginalNode = dto,
                Children = children.Select(ToDestinationNode).ToList()
            };
            return result;
        }

        /// <summary>
        /// 转换为结果
        /// </summary>
        protected override NgZorroTreeResult ToResult(List<NgZorroTreeNode> nodes)
        {
            var data = GetData();
            _result.CheckedKeys = data.Where(t => t.Checked == true).Select(t => t.Id).ToList();
            _result.SelectedKeys = data.Where(t => t.Selected == true).Select(t => t.Id).ToList();
            _result.Nodes = nodes;
            return _result;
        }
    }
    #endregion

