    #region Popover
    /// <summary>
    /// 气泡框扩展
    /// </summary>
    public static class TagBuilderExtensions
    {
        /// <summary>
        /// 气泡框指令扩展
        /// </summary>
        /// <typeparam name="TBuilder">生成器类型</typeparam>
        /// <param name="builder">生成器实例</param>
        /// <param name="config">配置</param>
        public static TBuilder Popover<TBuilder>(this TBuilder builder, Config config) where TBuilder : TagBuilder
        {
            builder.AttributeIf("nz-popover", string.IsNullOrWhiteSpace(config.GetValue(UiConst.PopoverContent)) == false);
            builder.AttributeIf("nz-popover", string.IsNullOrWhiteSpace(config.GetValue(AngularConst.BindPopoverContent)) == false);
            builder.PopoverTitle(config.GetValue(UiConst.PopoverTitle));
            builder.BindPopoverTitle(config.GetValue(AngularConst.BindPopoverTitle));
            builder.AttributeIfNotEmpty("nzPopoverContent", config.GetValue(UiConst.PopoverContent));
            builder.AttributeIfNotEmpty("[nzPopoverContent]", config.GetValue(AngularConst.BindPopoverContent));
            builder.AttributeIfNotEmpty("nzPopoverTrigger", config.GetValue<PopoverTrigger?>(UiConst.PopoverTrigger)?.Description());
            builder.AttributeIfNotEmpty("[nzPopoverTrigger]", config.GetValue(AngularConst.BindPopoverTrigger));
            builder.AttributeIfNotEmpty("nzPopoverPlacement", config.GetValue<PopoverPlacement?>(UiConst.PopoverPlacement)?.Description());
            builder.AttributeIfNotEmpty("[nzPopoverPlacement]", config.GetValue(AngularConst.BindPopoverPlacement));
            builder.AttributeIfNotEmpty("[nzPopoverArrowPointAtCenter]", config.GetValue(UiConst.PopoverArrowPointAtCenter));
            builder.AttributeIfNotEmpty("[nzPopoverOrigin]", config.GetValue(UiConst.PopoverOrigin));
            builder.AttributeIfNotEmpty("[nzPopoverVisible]", config.GetValue(UiConst.PopoverVisible));
            builder.AttributeIfNotEmpty("[(nzPopoverVisible)]", config.GetValue(AngularConst.BindonPopoverVisible));
            builder.AttributeIfNotEmpty("[nzPopoverMouseEnterDelay]", config.GetValue(UiConst.PopoverMouseEnterDelay));
            builder.AttributeIfNotEmpty("[nzPopoverMouseLeaveDelay]", config.GetValue(UiConst.PopoverMouseLeaveDelay));
            builder.AttributeIfNotEmpty("nzPopoverOverlayClassName", config.GetValue(UiConst.PopoverOverlayClassName));
            builder.AttributeIfNotEmpty("[nzPopoverOverlayClassName]", config.GetValue(AngularConst.BindPopoverOverlayClassName));
            builder.AttributeIfNotEmpty("[nzPopoverOverlayStyle]", config.GetValue(UiConst.PopoverOverlayStyle));
            builder.AttributeIfNotEmpty("[nzPopoverBackdrop]", config.GetValue(UiConst.PopoverBackdrop));
            builder.AttributeIfNotEmpty("(nzPopoverVisibleChange)", config.GetValue(UiConst.OnPopoverVisibleChange));
            return builder;
        }

        /// <summary>
        /// nzPopoverTitle,气泡卡片标题
        /// </summary>
        /// <typeparam name="TBuilder">生成器类型</typeparam>
        /// <param name="builder">生成器实例</param>
        /// <param name="value">值</param>
        public static TBuilder PopoverTitle<TBuilder>(this TBuilder builder, string value) where TBuilder : TagBuilder
        {
            builder.AttributeIf("nz-popover", value.IsEmpty() == false);
            SetPopoverTitle(builder, value);
            return builder;
        }

        /// <summary>
        /// 设置标题
        /// </summary>
        public static void SetPopoverTitle(TagBuilder builder, string value)
        {
            var options = NgZorroOptionsService.GetOptions();
            if (options.EnableI18n)
            {
                builder.AttributeByI18n("[nzPopoverTitle]", value);
                return;
            }
            builder.AttributeIfNotEmpty("nzPopoverTitle", value);
        }

        /// <summary>
        /// [nzPopoverTitle],气泡卡片标题
        /// </summary>
        /// <typeparam name="TBuilder">生成器类型</typeparam>
        /// <param name="builder">生成器实例</param>
        /// <param name="value">值</param>
        public static TBuilder BindPopoverTitle<TBuilder>(this TBuilder builder, string value) where TBuilder : TagBuilder
        {
            builder.AttributeIf("nz-popover", value.IsEmpty() == false);
            builder.AttributeIfNotEmpty("[nzPopoverTitle]", value);
            return builder;
        }
    }
    #endregion

    #region Tooltips
    /// <summary>
    /// 文字提示扩展
    /// </summary>
    public static class TagBuilderExtensions
    {
        /// <summary>
        /// 文字提示指令扩展
        /// </summary>
        /// <typeparam name="TBuilder">生成器类型</typeparam>
        /// <param name="builder">生成器实例</param>
        /// <param name="config">配置</param>
        public static TBuilder Tooltip<TBuilder>(this TBuilder builder, Config config) where TBuilder : TagBuilder
        {
            TooltipTitleUpdate(builder, config);
            TooltipTitleDelete(builder, config);
            TooltipTitleDetail(builder, config);
            builder.TooltipTitle(config.GetValue(UiConst.TooltipTitle));
            builder.BindTooltipTitle(config.GetValue(AngularConst.BindTooltipTitle));
            builder.AttributeIfNotEmpty("nzTooltipPlacement", config.GetValue<TooltipPlacement?>(UiConst.TooltipPlacement)?.Description());
            builder.AttributeIfNotEmpty("[nzTooltipPlacement]", config.GetValue(AngularConst.BindTooltipPlacement));
            builder.AttributeIfNotEmpty("[nzTooltipArrowPointAtCenter]", config.GetValue(UiConst.TooltipArrowPointAtCenter));
            builder.AttributeIfNotEmpty("[nzTooltipTitleContext]", config.GetValue(UiConst.TooltipTitleContext));
            builder.AttributeIfNotEmpty("nzTooltipTrigger", config.GetValue<TooltipTrigger?>(UiConst.TooltipTrigger)?.Description());
            builder.AttributeIfNotEmpty("[nzTooltipTrigger]", config.GetValue(AngularConst.BindTooltipTrigger));
            builder.AttributeIfNotEmpty("nzTooltipColor", config.GetValue<AntDesignColor?>(UiConst.TooltipColorType)?.Description());
            builder.AttributeIfNotEmpty("nzTooltipColor", config.GetValue(UiConst.TooltipColor));
            builder.AttributeIfNotEmpty("[nzTooltipColor]", config.GetValue(AngularConst.BindTooltipColor));
            builder.AttributeIfNotEmpty("[nzTooltipOrigin]", config.GetValue(UiConst.TooltipOrigin));
            builder.AttributeIfNotEmpty("[nzTooltipVisible]", config.GetValue(UiConst.TooltipVisible));
            builder.AttributeIfNotEmpty("[(nzTooltipVisible)]", config.GetValue(AngularConst.BindonTooltipVisible));
            builder.AttributeIfNotEmpty("[nzTooltipMouseEnterDelay]", config.GetValue(UiConst.TooltipMouseEnterDelay));
            builder.AttributeIfNotEmpty("[nzTooltipMouseLeaveDelay]", config.GetValue(UiConst.TooltipMouseLeaveDelay));
            builder.AttributeIfNotEmpty("nzTooltipOverlayClassName", config.GetValue(UiConst.TooltipOverlayClassName));
            builder.AttributeIfNotEmpty("[nzTooltipOverlayClassName]", config.GetValue(AngularConst.BindTooltipOverlayClassName));
            builder.AttributeIfNotEmpty("[nzTooltipOverlayStyle]", config.GetValue(UiConst.TooltipOverlayStyle));
            builder.AttributeIfNotEmpty("(nzTooltipVisibleChange)", config.GetValue(UiConst.OnTooltipVisibleChange));
            return builder;
        }

        /// <summary>
        /// 设置nzTooltipTitle为update
        /// </summary>
        /// <param name="builder">生成器实例</param>
        /// <param name="config">配置</param>
        private static void TooltipTitleUpdate(TagBuilder builder, Config config)
        {
            var value = config.GetValue<bool?>(UiConst.TooltipTitleUpdate);
            if (value != true)
                return;
            var options = NgZorroOptionsService.GetOptions();
            if (options.EnableI18n)
            {
                builder.TooltipTitle(I18nKeys.Update);
                return;
            }
            builder.TooltipTitle("Update");
        }

        /// <summary>
        /// 设置nzTooltipTitle为delete
        /// </summary>
        /// <param name="builder">生成器实例</param>
        /// <param name="config">配置</param>
        private static void TooltipTitleDelete(TagBuilder builder, Config config)
        {
            var value = config.GetValue<bool?>(UiConst.TooltipTitleDelete);
            if (value != true)
                return;
            var options = NgZorroOptionsService.GetOptions();
            if (options.EnableI18n)
            {
                builder.TooltipTitle(I18nKeys.Delete);
                return;
            }
            builder.TooltipTitle("Delete");
        }

        /// <summary>
        /// 设置nzTooltipTitle为detail
        /// </summary>
        /// <param name="builder">生成器实例</param>
        /// <param name="config">配置</param>
        private static void TooltipTitleDetail(TagBuilder builder, Config config)
        {
            var value = config.GetValue<bool?>(UiConst.TooltipTitleDetail);
            if (value != true)
                return;
            var options = NgZorroOptionsService.GetOptions();
            if (options.EnableI18n)
            {
                builder.TooltipTitle(I18nKeys.Detail);
                return;
            }
            builder.TooltipTitle("Detail");
        }

        /// <summary>
        /// nzTooltipTitle,提示文字
        /// </summary>
        /// <typeparam name="TBuilder">生成器类型</typeparam>
        /// <param name="builder">生成器实例</param>
        /// <param name="value">值</param>
        public static TBuilder TooltipTitle<TBuilder>(this TBuilder builder, string value) where TBuilder : TagBuilder
        {
            builder.AttributeIf("nz-tooltip", value.IsEmpty() == false);
            SetTooltipTitle(builder, value);
            return builder;
        }

        /// <summary>
        /// 设置标题
        /// </summary>
        public static void SetTooltipTitle(TagBuilder builder, string value)
        {
            var options = NgZorroOptionsService.GetOptions();
            if (options.EnableI18n)
            {
                builder.AttributeByI18n("[nzTooltipTitle]", value);
                return;
            }
            builder.AttributeIfNotEmpty("nzTooltipTitle", value);
        }

        /// <summary>
        /// [nzTooltipTitle],提示文字
        /// </summary>
        /// <typeparam name="TBuilder">生成器类型</typeparam>
        /// <param name="builder">生成器实例</param>
        /// <param name="value">值</param>
        public static TBuilder BindTooltipTitle<TBuilder>(this TBuilder builder, string value) where TBuilder : TagBuilder
        {
            builder.AttributeIf("nz-tooltip", value.IsEmpty() == false);
            builder.AttributeIfNotEmpty("[nzTooltipTitle]", value);
            return builder;
        }
    }
