    #region Expressions
    /// <summary>
    /// NgZorro表达式加载器
    /// </summary>
    public abstract class NgZorroExpressionLoaderBase : ExpressionLoaderBase
    {
        /// <summary>
        /// 创建模型表达式解析器
        /// </summary>
        /// <param name="config">配置</param>
        protected override IExpressionResolver CreateExpressionResolver(Config config)
        {
            return new NgZorroExpressionResolver(config);
        }

        /// <summary>
        /// 获取下划线分隔的小写属性名
        /// </summary>
        protected virtual string GeKebaberizePropertyName(Config config, ModelExpressionInfo info)
        {
            var columnConfig = GetTableColumnShareConfig(config);
            var name = info.LastPropertyName.Kebaberize().Replace("-", "_");
            if (columnConfig == null || columnConfig.IsEnableEdit == false)
                return name;
            return $"control_{name}";
        }

        /// <summary>
        /// 获取表格列共享配置
        /// </summary>
        public TableColumnShareConfig GetTableColumnShareConfig(Config config)
        {
            return config.GetValueFromItems<TableColumnShareConfig>();
        }
    }

    /// <summary>
    /// NgZorro模型表达式解析器
    /// </summary>
    public class NgZorroExpressionResolver : ExpressionResolver
    {
        /// <summary>
        /// 配置
        /// </summary>
        private readonly Config _config;

        /// <summary>
        /// 初始化NgZorro模型表达式解析器
        /// </summary>
        /// <param name="config">配置</param>
        public NgZorroExpressionResolver(Config config)
        {
            _config = config;
        }

        /// <summary>
        /// 获取默认模型名称
        /// </summary>
        protected override string GetDefaultModel()
        {
            var config = GetTableColumnShareConfig();
            if (config == null)
                return "model";
            return "row";
        }

        /// <summary>
        /// 获取表格列共享配置
        /// </summary>
        public TableColumnShareConfig GetTableColumnShareConfig()
        {
            return _config.GetValueFromItems<TableColumnShareConfig>();
        }
    }
    #endregion

    #region Extensions
    /// <summary>
    /// ng-zorro扩展
    /// </summary>
    public static class TagBuilderExtensions
    {
        /// <summary>
        /// *nzSpaceItem,间距项
        /// </summary>
        /// <typeparam name="TBuilder">生成器类型</typeparam>
        /// <param name="builder">生成器实例</param>
        /// <param name="value">值</param>
        public static TBuilder SpaceItem<TBuilder>(this TBuilder builder, bool? value) where TBuilder : TagBuilder
        {
            if (value == true)
                builder.Attribute("*nzSpaceItem");
            return builder;
        }

        /// <summary>
        /// *nzSpaceItem,间距项
        /// </summary>
        /// <typeparam name="TBuilder">生成器类型</typeparam>
        /// <param name="builder">生成器实例</param>
        /// <param name="config">配置</param>
        public static TBuilder SpaceItem<TBuilder>(this TBuilder builder, Config config) where TBuilder : TagBuilder
        {
            builder.SpaceItem(config.GetValue<bool?>(UiConst.SpaceItem));
            return builder;
        }

        /// <summary>
        /// 宽度
        /// </summary>
        /// <typeparam name="TBuilder">生成器类型</typeparam>
        /// <param name="builder">生成器实例</param>
        /// <param name="value">值</param>
        /// <param name="attributeName">属性名</param>
        public static TBuilder Width<TBuilder>(this TBuilder builder, string value, string attributeName = "nzWidth") where TBuilder : TagBuilder
        {
            builder.AttributeIfNotEmpty(attributeName, GetPixelValue(value));
            return builder;
        }

        /// <summary>
        /// 获取像素值，如果传入数字，后加px，否则按原样返回
        /// </summary>
        /// <param name="value">值</param>
        private static string GetPixelValue(string value)
        {
            if (value.IsEmpty())
                return null;
            if (Util.Helpers.Validation.IsNumber(value))
                return $"{value}px";
            return value;
        }

        /// <summary>
        /// 添加到内容,支持i18n管道
        /// </summary>
        /// <typeparam name="TBuilder">生成器类型</typeparam>
        /// <param name="builder">生成器实例</param>
        /// <param name="value">值</param>
        public static TBuilder AppendContentByI18n<TBuilder>(this TBuilder builder, string value) where TBuilder : TagBuilder
        {
            if (value.IsEmpty())
                return builder;
            var result = new StringBuilder();
            result.Append("{{");
            result.Append($"'{value}'|i18n");
            result.Append("}}");
            builder.AppendContent(result.ToString());
            return builder;
        }

        /// <summary>
        /// 添加属性,支持i18n管道
        /// </summary>
        /// <typeparam name="TBuilder">生成器类型</typeparam>
        /// <param name="builder">生成器实例</param>
        /// <param name="name">属性名</param>
        /// <param name="value">值</param>
        public static TBuilder AttributeByI18n<TBuilder>(this TBuilder builder, string name, string value) where TBuilder : TagBuilder
        {
            if (value.IsEmpty())
                return builder;
            builder.Attribute(name, $"'{value}'|i18n");
            return builder;
        }
    }
    #endregion

    #region Services
    /// <summary>
    /// 树形查询操作
    /// </summary>
    /// <typeparam name="TDto">参数类型</typeparam>
    /// <typeparam name="TQuery">查询参数类型</typeparam>
    public class NgZorroTreeQueryAction<TDto, TQuery> : TreeQueryActionBase<TDto, TQuery>
        where TDto : TreeDtoBase<TDto>, new()
        where TQuery : class, ITreeQueryParameter
    {
        /// <summary>
        /// 查询服务
        /// </summary>
        private readonly ITreeQueryService<TDto, TQuery> _service;
        /// <summary>
        /// 最大分页大小
        /// </summary>
        private readonly int _maxPageSize;
        /// <summary>
        /// 初始化树形查询操作
        /// </summary>
        /// <param name="service">查询服务</param>
        /// <param name="loadMode">加载模式</param>
        /// <param name="loadOperation">加载操作</param>
        /// <param name="maxPageSize">最大分页大小</param>
        /// <param name="isFirstLoad">是否首次加载</param>
        /// <param name="isExpandAll">是否展开所有节点</param>
        /// <param name="isExpandForRoot">根节点异步加载模式是否展开子节点列表</param>
        /// <param name="loadKeys">需要加载的标识列表</param>
        /// <param name="queryBefore">查询前操作</param>
        /// <param name="processData">数据处理操作</param>
        public NgZorroTreeQueryAction(ITreeQueryService<TDto, TQuery> service, LoadMode loadMode, LoadOperation loadOperation,
            int maxPageSize, bool isFirstLoad, bool isExpandAll, bool isExpandForRoot, string loadKeys,
            Action<TQuery> queryBefore, Action<PageList<TDto>, TQuery> processData)
            : base(service, loadMode, loadOperation, maxPageSize, isFirstLoad, isExpandAll, isExpandForRoot, loadKeys, queryBefore, processData)
        {
            _service = service;
            _maxPageSize = maxPageSize;
        }

        /// <summary>
        /// 转换为树形结果
        /// </summary>
        /// <param name="data">数据列表</param>
        /// <param name="async">是否异步加载</param>
        /// <param name="allExpand">所有节点是否全部展开</param>
        protected override dynamic ToResult(PageList<TDto> data, bool async = false, bool allExpand = false)
        {
            return data.Data.ToTreeResult(async, allExpand);
        }

        /// <summary>
        /// 异步查询
        /// </summary>
        protected override async Task<PageList<TDto>> AsyncQuery(TQuery query)
        {
            query.PageSize = _maxPageSize;
            return await _service.PageQueryAsync(query);
        }
    }
    #endregion

    /// <summary>
    /// NgZorro配置扩展
    /// </summary>
    public static class AppBuilderExtensions
    {
        /// <summary>
        /// 配置NgZorro依赖服务
        /// </summary>
        /// <param name="builder">应用生成器</param>
        public static IAppBuilder AddNgZorro(this IAppBuilder builder)
        {
            return builder.AddNgZorro(null);
        }

        /// <summary>
        /// 配置NgZorro依赖服务
        /// </summary>
        /// <param name="builder">应用生成器</param>
        /// <param name="setupAction">NgZorro配置操作</param>
        public static IAppBuilder AddNgZorro(this IAppBuilder builder, Action<NgZorroOptions> setupAction)
        {
            builder.CheckNull(nameof(builder));
            builder.Host.ConfigureServices((context, services) =>
            {
                var options = new NgZorroOptions();
                setupAction?.Invoke(options);
                services.AddRazorPages(razorPageOptions =>
                {
                    razorPageOptions.RootDirectory = options.RazorRootDirectory;
                }).AddRazorRuntimeCompilation().AddConventions();
                services.TryAddSingleton<IRazorWatchService, RazorWatchService>();
                services.TryAddSingleton<IPartViewPathResolver, PartViewPathResolver>();
                services.TryAddSingleton<IPartViewPathFinder, PartViewPathFinder>();
                if (options.EnableWatchRazor)
                    services.AddHostedService<WatchHostedService>();
                ConfigSpaStaticFiles(services, options);
                ConfigRazorOptions(services, options);
                ConfigNgZorroOptions(services, setupAction);
            });
            return builder;
        }

        /// <summary>
        /// 配置Spa静态文件
        /// </summary>
        private static void ConfigSpaStaticFiles(IServiceCollection services, NgZorroOptions options)
        {
            services.AddSpaStaticFiles(configuration =>
            {
                configuration.RootPath = options.RootPath;
            });
        }

        /// <summary>
        /// 配置Razor
        /// </summary>
        private static void ConfigRazorOptions(IServiceCollection services, NgZorroOptions options)
        {
            void Action(RazorOptions razorOptions)
            {
                options.MapTo(razorOptions);
            }
            services.Configure((Action<RazorOptions>)Action);
        }

        /// <summary>
        /// 配置NgZorro
        /// </summary>
        private static void ConfigNgZorroOptions(IServiceCollection services, Action<NgZorroOptions> setupAction)
        {
            if (setupAction != null)
                services.Configure(setupAction);
        }
    }

    /// <summary>
    /// NgZorro配置
    /// </summary>
    public class NgZorroOptions : RazorOptions
    {
        /// <summary>
        /// 初始化NgZorro配置
        /// </summary>
        public NgZorroOptions()
        {
            if (Util.Helpers.Environment.IsTest)
            {
                EnableDefaultOptionText = false;
                EnableI18n = false;
                EnableAllowClear = false;
                EnableWatchRazor = false;
            }
        }

        /// <summary>
        /// 是否启用默认项文本,默认值: true
        /// </summary>
        public bool EnableDefaultOptionText { get; set; } = true;
        /// <summary>
        /// 是否启用多语言,默认值: true
        /// </summary>
        public bool EnableI18n { get; set; } = true;
        /// <summary>
        /// 是否启用关闭浏览器自动完成功能, 设置 autocomplete="off",默认值: false
        /// </summary>
        public bool EnableAutocompleteOff { get; set; }
        /// <summary>
        /// 是否启用允许清除输入框,默认值: true
        /// </summary>
        public bool EnableAllowClear { get; set; } = true;
        /// <summary>
        /// 是否启用自动设置表单标签 nzFor,默认值: null
        /// </summary>
        public bool? EnableAutoNzFor { get; set; } = null;
        /// <summary>
        /// 是否启用勾选表格行复选框时添加样式类 table-row-checked ,默认值: false
        /// </summary>
        public bool EnableTableRowCheckedClass { get; set; }
        /// <summary>
        /// 获取表格布尔列内容操作
        /// </summary>
        public Func<string, string> GetTableColumnBoolContentAction { get; set; }
        /// <summary>
        /// 表格设置组件标签名，默认值：x-table-settings
        /// </summary>
        public string TableSettingsTag { get; set; } = "x-table-settings";
        /// <summary>
        /// 表格复选框对齐方式，默认值：左对齐
        /// </summary>
        public TableHeadColumnAlign TableCheckboxAlign { get; set; } = TableHeadColumnAlign.Left;
        /// <summary>
        /// 表格单选按钮对齐方式，默认值：左对齐
        /// </summary>
        public TableHeadColumnAlign TableRadioAlign { get; set; } = TableHeadColumnAlign.Left;
        /// <summary>
        /// 表格序号对齐方式，默认值：左对齐
        /// </summary>
        public TableHeadColumnAlign TableLineNumberAlign { get; set; } = TableHeadColumnAlign.Left;
        /// <summary>
        /// 对话框内容容器 &lt;util-dialog-container> 的最大高度,默认值: 500px
        /// </summary>
        public string DialogContainerMaxHeight { get; set; } = "500px";
        /// <summary>
        /// 启用表格排序,注意: 仅在使用 for 表达式时生效,且对树形表格无效, 默认值: false
        /// </summary>
        public bool EnableTableSort { get; set; }
    }

