    #region Contexts
    /// <summary>
    /// 数据类型扩展操作
    /// </summary>
    public static class DbTypeExtensions
    {
        /// <summary>
        /// 转换为系统类型
        /// </summary>
        public static SystemType? ToSystemType(this DbType? type)
        {
            if (type == null)
                return null;
            switch (type)
            {
                case DbType.Guid:
                    return SystemType.Guid;
                case DbType.AnsiString:
                case DbType.String:
                case DbType.AnsiStringFixedLength:
                case DbType.StringFixedLength:
                    return SystemType.String;
                case DbType.Boolean:
                    return SystemType.Bool;
                case DbType.Byte:
                    return SystemType.Byte;
                case DbType.Int16:
                    return SystemType.Short;
                case DbType.Int32:
                    return SystemType.Int;
                case DbType.Int64:
                    return SystemType.Long;
                case DbType.Single:
                    return SystemType.Single;
                case DbType.Double:
                    return SystemType.Double;
                case DbType.Decimal:
                    return SystemType.Decimal;
                case DbType.Date:
                case DbType.Time:
                case DbType.DateTime:
                case DbType.DateTime2:
                case DbType.DateTimeOffset:
                    return SystemType.DateTime;
                case DbType.Binary:
                    return SystemType.Binary;
            }
            return null;
        }
    }

    /// <summary>
    /// 实体上下文
    /// </summary>
    public class EntityContext
    {
        /// <summary>
        /// 初始化实体上下文
        /// </summary>
        /// <param name="projectContext">项目上下文</param>
        /// <param name="name">实体名称</param>
        public EntityContext(ProjectContext projectContext, string name)
        {
            ProjectContext = projectContext ?? throw new ArgumentNullException(nameof(projectContext));
            Name = name;
            Id = Util.Helpers.Id.Create();
            Output = new Output
            {
                RootPath = System.IO.Path.Combine(projectContext.GeneratorContext.OutputRootPath, projectContext.Name),
                FileNameNoExtension = name
            };
            Properties = new List<Property>();
        }

        /// <summary>
        /// 实体标识
        /// </summary>
        public string Id { get; private init; }
        /// <summary>
        /// 项目上下文
        /// </summary>
        public ProjectContext ProjectContext { get; }
        /// <summary>
        /// 输出
        /// </summary>
        public Output Output { get; }
        /// <summary>
        /// 实体名称
        /// </summary>
        public string Name { get; }
        /// <summary>
        /// 架构名
        /// </summary>
        public string Schema { get; set; }
        /// <summary>
        /// 描述
        /// </summary>
        public string Description { get; set; }
        /// <summary>
        /// 属性列表
        /// </summary>
        public List<Property> Properties { get; }
        /// <summary>
        /// 项目名称
        /// </summary>
        public string ProjectName => ProjectContext.Name;
        /// <summary>
        /// 项目复数名称
        /// </summary>
        public string PluralName => Name.Pluralize().Pascalize();
        /// <summary>
        /// 项目Pascal名称
        /// </summary>
        public string PascalName => Name.Pascalize();
        /// <summary>
        /// 项目驼峰名称
        /// </summary>
        public string CamelName => Name.Camelize();

        /// <summary>
        /// 标识属性
        /// </summary>
        public Property Key
        {
            get
            {
                var result = Properties.FirstOrDefault(t => t.IsKey);
                if (result == null)
                {
                    var message = string.Format(GeneratorResource.NotSetPrimaryKey, GetNameWithSchema());
                    throw new InvalidOperationException(message);
                }
                return result;
            }
        }
        /// <summary>
        /// 版本属性
        /// </summary>
        public Property Version
        {
            get
            {
                return Properties.FirstOrDefault(t => t.IsVersion);
            }
        }

        /// <summary>
        /// 是否包含逻辑删除
        /// </summary>
        public bool HasIsDeleted => Properties.Any(t => t.IsDeleted);

        /// <summary>
        /// 是否包含创建时间
        /// </summary>
        public bool HasCreationTime => Properties.Any(t => t.IsCreationTime);

        /// <summary>
        /// 是否包含树形属性
        /// </summary>
        public bool HasTree => Properties.Any(t => t.IsTree);

        /// <summary>
        /// 是否包含排序号
        /// </summary>
        public bool HasSortId => Properties.Any(t => t.IsSortId);

        /// <summary>
        /// 是否多对多关联表
        /// </summary>
        public bool IsRelationTable => Properties.Count == 2 && Properties.All(t => t.IsKey);

        /// <summary>
        /// 获取带架构的名称
        /// </summary>
        public string GetNameWithSchema()
        {
            if (Schema.IsEmpty())
                return Name;
            return $"{Schema}.{Name}";
        }

        /// <summary>
        /// 复制
        /// </summary>
        public EntityContext Clone()
        {
            var generatorContext = ProjectContext.GeneratorContext.Clone();
            var projectContext = generatorContext.Projects.Find(t => t.Id == ProjectContext.Id);
            if (projectContext == null)
                throw new InvalidOperationException();
            return projectContext.Entities.Find(t => t.Id == Id);
        }

        /// <summary>
        /// 复制
        /// </summary>
        /// <param name="projectContext">项目上下文</param>
        public EntityContext Clone(ProjectContext projectContext)
        {
            var result = new EntityContext(projectContext, Name)
            {
                Id = Id,
                Schema = Schema,
                Description = Description
            };
            Output.CopyTo(result.Output);
            Properties.ForEach(property => result.Properties.Add(property.Clone(result)));
            return result;
        }
    }

    /// <summary>
    /// 生成器上下文
    /// </summary>
    public class GeneratorContext
    {
        /// <summary>
        /// 初始化生成器上下文
        /// </summary>
        public GeneratorContext()
        {
            Projects = new List<ProjectContext>();
        }

        /// <summary>
        /// 模板根目录路径
        /// </summary>
        [Required(ErrorMessageResourceType = typeof(GeneratorResource), ErrorMessageResourceName = "TemplateRootPathIsEmpty")]
        public string TemplateRootPath { get; set; }
        /// <summary>
        /// 输出根目录路径
        /// </summary>
        [Required(ErrorMessageResourceType = typeof(GeneratorResource), ErrorMessageResourceName = "OutputRootPathIsEmpty")]
        public string OutputRootPath { get; set; }
        /// <summary>
        /// 消息上下文
        /// </summary>
        public MessageOptions Message { get; set; }
        /// <summary>
        /// 项目上下文列表
        /// </summary>
        public List<ProjectContext> Projects { get; }

        /// <summary>
        /// 验证
        /// </summary>
        public void Validate()
        {
            var validationResult = DataAnnotationValidation.Validate(this);
            if (validationResult.IsValid == false)
                throw new InvalidOperationException(validationResult.First().ErrorMessage);
            Projects.ForEach(t => t.Validate());
        }

        /// <summary>
        /// 复制
        /// </summary>
        public GeneratorContext Clone()
        {
            var result = new GeneratorContext
            {
                TemplateRootPath = TemplateRootPath,
                OutputRootPath = OutputRootPath,
                Message = Message?.Clone()
            };
            Projects.ForEach(project => result.Projects.Add(project.Clone(result)));
            return result;
        }
    }

    /// <summary>
    /// 生成器上下文构建器
    /// </summary>
    public class GeneratorContextBuilder : IGeneratorContextBuilder
    {
        /// <summary>
        /// 生成器日志操作
        /// </summary>
        private readonly IGeneratorLogger _logger;
        /// <summary>
        /// 生成器配置项构建器
        /// </summary>
        private readonly IGeneratorOptionsBuilder _optionsBuilder;
        /// <summary>
        /// 元数据服务工厂
        /// </summary>
        private readonly IMetadataServiceFactory _metadataServiceFactory;
        /// <summary>
        /// 数据类型转换器工厂
        /// </summary>
        private readonly ITypeConverterFactory _typeConverterFactory;

        /// <summary>
        /// 初始化生成器上下文构建器
        /// </summary>
        /// <param name="logger">日志</param>
        /// <param name="optionsBuilder">生成器配置项构建器</param>
        /// <param name="metadataServiceFactory">元数据服务工厂</param>
        /// <param name="typeConverterFactory">数据类型转换器工厂</param>
        public GeneratorContextBuilder(IGeneratorLogger logger, IGeneratorOptionsBuilder optionsBuilder, IMetadataServiceFactory metadataServiceFactory, ITypeConverterFactory typeConverterFactory)
        {
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
            _optionsBuilder = optionsBuilder ?? throw new ArgumentNullException(nameof(optionsBuilder));
            _metadataServiceFactory = metadataServiceFactory ?? throw new ArgumentNullException(nameof(metadataServiceFactory));
            _typeConverterFactory = typeConverterFactory ?? throw new ArgumentNullException(nameof(typeConverterFactory));
        }

        /// <summary>
        /// 创建生成器上下文
        /// </summary>
        public async Task<GeneratorContext> BuildAsync()
        {
            var options = await GetGeneratorOptions();
            _logger.LogOptions(options);
            _logger.BeginBuildContext();
            var result = new GeneratorContext
            {
                TemplateRootPath = GetPhysicalPath(options.TemplatePath),
                OutputRootPath = GetPhysicalPath(options.OutputPath),
                Message = options.Messages.Clone()
            };
            _logger.LogGeneratorContextBaseInfo(result);
            await AddProjectContexts(result, options.Projects.Select(t => t.Value));
            result.Validate();
            return result;
        }

        /// <summary>
        /// 获取生成器配置
        /// </summary>
        protected async Task<GeneratorOptions> GetGeneratorOptions()
        {
            return await _optionsBuilder.BuildAsync();
        }

        /// <summary>
        /// 获取物理路径
        /// </summary>
        protected virtual string GetPhysicalPath(string path)
        {
            if (IsAbsolutePath(path))
                return path;
            return Util.Helpers.Common.GetPhysicalPath(path);
        }

        /// <summary>
        /// 是否绝对路径
        /// </summary>
        protected virtual bool IsAbsolutePath(string path)
        {
            if (Common.IsWindows == false && path.StartsWith("/"))
                return true;
            if (path.Contains(@":\"))
                return true;
            if (path.Contains(":/"))
                return true;
            return false;
        }

        /// <summary>
        /// 添加项目上下文集合
        /// </summary>
        protected async Task AddProjectContexts(GeneratorContext generatorContext, IEnumerable<ProjectOptions> projectOptions)
        {
            foreach (var projectOption in projectOptions)
            {
                var projectContext = await CreateProjectContext(generatorContext, projectOption);
                generatorContext.Projects.Add(projectContext);
            }
        }

        /// <summary>
        /// 创建项目上下文
        /// </summary>
        protected async Task<ProjectContext> CreateProjectContext(GeneratorContext generatorContext, ProjectOptions projectOptions)
        {
            _logger.BeginBuildProjectContext(projectOptions.Name);
            var result = new ProjectContext(generatorContext)
            {
                Name = projectOptions.Name,
                UnitOfWorkName = projectOptions.UnitOfWorkName,
                Client = projectOptions.Client.Clone(),
                DbType = projectOptions.DbType,
                TargetDbType = projectOptions.TargetDbType ?? projectOptions.DbType,
                ConnectionString = projectOptions.ConnectionString,
                Enabled = projectOptions.Enabled,
                Utc = projectOptions.Utc,
                I18n = projectOptions.I18n,
                ProjectType = projectOptions.ProjectType,
                ApiPort = projectOptions.ApiPort,
                UiPort = projectOptions.UiPort,
                EnableSchema = projectOptions.EnableSchema,
                Extend = projectOptions.Extend
            };
            if (projectOptions.Enabled == false)
                return result;
            _logger.BeginGetDbMetadata(projectOptions);
            var databaseInfo = await GetDatabaseInfo(projectOptions);
            _logger.EndGetDbMetadata(databaseInfo);
            var typeConverter = _typeConverterFactory.Create(projectOptions.DbType);
            foreach (var table in databaseInfo.Tables)
                AddEntityContext(result, table, typeConverter);
            result.Schemas.AddRange(result.Entities.GroupBy(t => t.Schema).Select(t => t.Key));
            _logger.EndProjectContext(result);
            return result;
        }

        /// <summary>
        /// 获取数据库元数据信息
        /// </summary>
        protected async Task<DatabaseInfo> GetDatabaseInfo(ProjectOptions projectOptions)
        {
            var metadataService = _metadataServiceFactory.Create(projectOptions.DbType, projectOptions.ConnectionString);
            return await metadataService.GetDatabaseInfoAsync();
        }

        /// <summary>
        /// 添加实体上下文
        /// </summary>
        protected void AddEntityContext(ProjectContext project, TableInfo table, ITypeConverter typeConverter)
        {
            var entity = new EntityContext(project, table.Name)
            {
                Schema = table.Schema,
                Description = table.Comment
            };
            table.Columns.ForEach(column =>
            {
                var length = Util.Helpers.Convert.ToInt(column.Length);
                var property = new Property(entity)
                {
                    Name = column.Name,
                    Description = column.Comment,
                    IsKey = column.IsPrimaryKey,
                    IsRequired = column.IsNullable == false,
                    Type = typeConverter.ToType(column.DataType, length),
                    NativeType = column.DataType,
                    MaxLength = length,
                    IsAutoIncrement = column.IsAutoIncrement,
                    Precision = column.Precision,
                    Scale = column.Scale
                };
                property.SystemType = property.Type.ToSystemType();
                entity.Properties.Add(property);
            });
            project.Entities.Add(entity);
        }
    }

    /// <summary>
    /// 生成器上下文构建器
    /// </summary>
    public interface IGeneratorContextBuilder
    {
        /// <summary>
        /// 创建生成器上下文
        /// </summary>
        Task<GeneratorContext> BuildAsync();
    }

    /// <summary>
    /// 输出
    /// </summary>
    public class Output
    {
        /// <summary>
        /// 根路径
        /// </summary>
        public string RootPath { get; set; }
        /// <summary>
        /// 相对根路径
        /// </summary>
        public string RelativeRootPath { get; set; }
        /// <summary>
        /// 输出文件名,不包含扩展名
        /// </summary>
        public string FileNameNoExtension { get; set; }
        /// <summary>
        /// 输出文件扩展名,范例: ".txt"
        /// </summary>
        public string Extension { get; set; }
        /// <summary>
        /// 命名约定
        /// </summary>
        public NamingConvention? NamingConvention { get; set; }

        /// <summary>
        /// 输出路径
        /// </summary>
        public string Path
        {
            get
            {
                if (RelativeRootPath.IsEmpty())
                    return Common.JoinPath(RootPath, GetFileName());
                return Common.JoinPath(RootPath, RelativeRootPath, GetFileName());
            }
        }

        /// <summary>
        /// 获取文件名
        /// </summary>
        private string GetFileName()
        {
            string result = null;
            if (NamingConvention == null)
                result = FileNameNoExtension;
            if (NamingConvention == Generators.NamingConvention.PascalCase)
                result = FileNameNoExtension.Pascalize();
            if (NamingConvention == Generators.NamingConvention.CamelCase)
                result = FileNameNoExtension.Camelize();
            return result + Extension;
        }

        /// <summary>
        /// 复制到输出副本
        /// </summary>
        /// <param name="copy">输出副本</param>
        public void CopyTo(Output copy)
        {
            copy.CheckNull(nameof(copy));
            copy.RootPath = RootPath;
            copy.RelativeRootPath = RelativeRootPath;
            copy.FileNameNoExtension = FileNameNoExtension;
            copy.Extension = Extension;
            copy.NamingConvention = NamingConvention;
        }
    }

    /// <summary>
    /// 项目上下文
    /// </summary>
    public class ProjectContext
    {
        /// <summary>
        /// 初始化项目上下文
        /// </summary>
        public ProjectContext(GeneratorContext generatorContext)
        {
            GeneratorContext = generatorContext ?? throw new ArgumentNullException(nameof(generatorContext));
            Entities = new List<EntityContext>();
            Schemas = new List<string>();
            Client = new ClientOptions();
            Id = Util.Helpers.Id.Create();
        }

        /// <summary>
        /// 项目标识
        /// </summary>
        public string Id { get; private init; }

        /// <summary>
        /// 项目名称
        /// </summary>
        [Required(ErrorMessageResourceType = typeof(GeneratorResource), ErrorMessageResourceName = "ProjectNameIsEmpty")]
        public string Name { get; set; }

        /// <summary>
        /// 数据库类型
        /// </summary>
        public DatabaseType DbType { get; set; }

        /// <summary>
        /// 目标数据库类型
        /// </summary>
        public DatabaseType TargetDbType { get; set; }

        /// <summary>
        /// 数据库连接字符串
        /// </summary>
        public string ConnectionString { get; set; }

        /// <summary>
        /// 工作单元名称
        /// </summary>
        public string UnitOfWorkName { get; set; }

        /// <summary>
        /// 是否启用
        /// </summary>
        public bool Enabled { get; set; }

        /// <summary>
        /// 是否启用Utc
        /// </summary>
        public bool Utc { get; set; }

        /// <summary>
        /// 是否启用多语言
        /// </summary>
        public bool I18n { get; set; }

        /// <summary>
        /// Web Api项目端口
        /// </summary>
        public string ApiPort { get; set; }

        /// <summary>
        /// UI项目端口
        /// </summary>
        public string UiPort { get; set; }

        /// <summary>
        /// 项目类型
        /// </summary>
        public ProjectType? ProjectType { get; set; }

        /// <summary>
        /// 是否启用架构
        /// </summary>
        public bool EnableSchema { get; set; }

        /// <summary>
        /// 客户端配置
        /// </summary>
        public ClientOptions Client { get; set; }

        /// <summary>
        /// 扩展
        /// </summary>
        public string Extend { get; set; }

        /// <summary>
        /// 生成器上下文
        /// </summary>
        public GeneratorContext GeneratorContext { get; }

        /// <summary>
        /// 实体上下文列表
        /// </summary>
        public List<EntityContext> Entities { get; }

        /// <summary>
        /// 架构列表
        /// </summary>
        public List<string> Schemas { get; }

        /// <summary>
        /// 获取扩展
        /// </summary>
        public T GetExtend<T>()
        {
            return Util.Helpers.Json.ToObject<T>(Extend);
        }

        /// <summary>
        /// 验证
        /// </summary>
        public void Validate()
        {
            var validationResult = DataAnnotationValidation.Validate(this);
            if (validationResult.IsValid)
                return;
            throw new InvalidOperationException(validationResult.First().ErrorMessage);
        }

        /// <summary>
        /// 复制
        /// </summary>
        /// <param name="generatorContext">生成器上下文</param>
        public ProjectContext Clone(GeneratorContext generatorContext)
        {
            var result = new ProjectContext(generatorContext)
            {
                Id = Id,
                Name = Name,
                UnitOfWorkName = UnitOfWorkName,
                DbType = DbType,
                TargetDbType = TargetDbType,
                ConnectionString = ConnectionString,
                Client = Client.Clone(),
                Enabled = Enabled,
                Utc = Utc,
                I18n = I18n,
                ProjectType = ProjectType,
                ApiPort = ApiPort,
                UiPort = UiPort,
                EnableSchema = EnableSchema,
                Extend = Extend
            };
            result.Schemas.AddRange(Schemas);
            Entities.ForEach(entity => result.Entities.Add(entity.Clone(result)));
            return result;
        }
    }

    /// <summary>
    /// 属性
    /// </summary>
    public class Property
    {
        /// <summary>
        /// 初始化属性
        /// </summary>
        /// <param name="entity">实体上下文</param>
        public Property(EntityContext entity)
        {
            Entity = entity ?? throw new ArgumentNullException(nameof(entity));
        }

        /// <summary>
        /// 实体上下文
        /// </summary>
        public EntityContext Entity { get; }
        /// <summary>
        /// 名称
        /// </summary>
        public string Name { get; set; }
        /// <summary>
        /// 描述
        /// </summary>
        public string Description { get; set; }
        /// <summary>
        /// 是否标识
        /// </summary>
        public bool IsKey { get; set; }
        /// <summary>
        /// 是否必填项
        /// </summary>
        public bool IsRequired { get; set; }
        /// <summary>
        /// 是否自增
        /// </summary>
        public bool IsAutoIncrement { get; set; }
        /// <summary>
        /// 数据类型
        /// </summary>
        public DbType? Type { get; set; }
        /// <summary>
        /// 系统类型
        /// </summary>
        public SystemType? SystemType { get; set; }
        /// <summary>
        /// 原生类型
        /// </summary>
        public string NativeType { get; set; }
        /// <summary>
        /// 最大长度
        /// </summary>
        public int? MaxLength { get; set; }
        /// <summary>
        /// 精度,即数值位数
        /// </summary>
        public int? Precision { get; set; }
        /// <summary>
        /// 小数位数
        /// </summary>
        public int? Scale { get; set; }
        /// <summary>
        /// 获取字段名称
        /// </summary>
        public string FieldName => $"_{Name.Camelize()}";
        /// <summary>
        /// 获取类型名称
        /// </summary>
        public string TypeName => SystemType.ToTypeString(!IsRequired);
        /// <summary>
        /// 获取可空类型名称
        /// </summary>
        public string NullableTypeName => SystemType.ToTypeString(true);
        /// <summary>
        /// 是否行版本
        /// </summary>
        public bool IsVersion => Name.ToUpperInvariant() == "Version".ToUpperInvariant() && SystemType == Generators.SystemType.Binary;
        /// <summary>
        /// 是否逻辑删除
        /// </summary>
        public bool IsDeleted => Name.ToUpperInvariant() == "IsDeleted".ToUpperInvariant() && SystemType == Generators.SystemType.Bool;
        /// <summary>
        /// 是否创建人标识
        /// </summary>
        public bool IsCreatorId => Name.ToUpperInvariant() == "CreatorId".ToUpperInvariant();
        /// <summary>
        /// 是否修改人标识
        /// </summary>
        public bool IsLastModifierId => Name.ToUpperInvariant() == "LastModifierId".ToUpperInvariant();
        /// <summary>
        /// 是否创建时间
        /// </summary>
        public bool IsCreationTime => Name.ToUpperInvariant() == "CreationTime".ToUpperInvariant() && SystemType == Generators.SystemType.DateTime;
        /// <summary>
        /// 是否最后修改时间
        /// </summary>
        public bool IsLastModificationTime => Name.ToUpperInvariant() == "LastModificationTime".ToUpperInvariant() && SystemType == Generators.SystemType.DateTime;
        /// <summary>
        /// 是否拼音简码
        /// </summary>
        public bool IsPinYin => Name.ToUpperInvariant() == "PinYin".ToUpperInvariant();
        /// <summary>
        /// 是否排序号
        /// </summary>
        public bool IsSortId => Name.ToUpperInvariant() == "SortId".ToUpperInvariant();
        /// <summary>
        /// 是否父标识
        /// </summary>
        public bool IsParentId => Name.ToUpperInvariant() == "ParentId".ToUpperInvariant();
        /// <summary>
        /// 是否扩展属性
        /// </summary>
        public bool IsExtraProperties => Name.ToUpperInvariant() == "ExtraProperties".ToUpperInvariant();
        /// <summary>
        /// 是否审计属性
        /// </summary>
        public bool IsAudited => Name.ToUpperInvariant() == "CreatorId".ToUpperInvariant() ||
                                 Name.ToUpperInvariant() == "CreationTime".ToUpperInvariant() ||
                                 Name.ToUpperInvariant() == "LastModifierId".ToUpperInvariant() ||
                                 Name.ToUpperInvariant() == "LastModificationTime".ToUpperInvariant();
        /// <summary>
        /// 是否字符串
        /// </summary>
        public bool IsString => SystemType == Generators.SystemType.String;
        /// <summary>
        /// 是否布尔值
        /// </summary>
        public bool IsBool => SystemType == Generators.SystemType.Bool;
        /// <summary>
        /// 是否日期
        /// </summary>
        public bool IsDateTime => SystemType == Generators.SystemType.DateTime;
        /// <summary>
        /// 是否整数
        /// </summary>
        public bool IsInteger => SystemType is Generators.SystemType.Short or Generators.SystemType.Int or Generators.SystemType.Long;
        /// <summary>
        /// 是否浮点数
        /// </summary>
        public bool IsFloat => SystemType is Generators.SystemType.Single or Generators.SystemType.Double or Generators.SystemType.Decimal;
        /// <summary>
        /// 是否数值类型,包含整数和浮点数
        /// </summary>
        public bool IsNumber => IsInteger || IsFloat;
        /// <summary>
        /// 是否Guid类型
        /// </summary>
        public bool IsGuid => SystemType == Generators.SystemType.Guid;

        /// <summary>
        /// 是否树形属性
        /// </summary>
        public bool IsTree => Entity.Properties.Exists(t => t.Name.ToUpperInvariant() == "ParentId".ToUpperInvariant()) &&
                              Entity.Properties.Exists(t => t.Name.ToUpperInvariant() == "Path".ToUpperInvariant()) &&
                              (Name.ToUpperInvariant() == "ParentId".ToUpperInvariant() ||
                                Name.ToUpperInvariant() == "Path".ToUpperInvariant() ||
                                Name.ToUpperInvariant() == "Level".ToUpperInvariant() ||
                                Name.ToUpperInvariant() == "SortId".ToUpperInvariant());

        /// <summary>
        /// 属性驼峰名称
        /// </summary>
        public string CamelName => Name.Camelize();

        /// <summary>
        /// 获取属性最大安全长度
        /// </summary>
        public int GetSafeMaxLength()
        {
            if (NativeType == "nvarchar")
                return MaxLength.SafeValue() / 2;
            return MaxLength.SafeValue();
        }

        /// <summary>
        /// 复制
        /// </summary>
        /// <param name="entityContext">实体上下文</param>
        public Property Clone(EntityContext entityContext)
        {
            var result = new Property(entityContext)
            {
                Name = Name,
                Description = Description,
                IsKey = IsKey,
                IsRequired = IsRequired,
                Type = Type,
                SystemType = SystemType,
                NativeType = NativeType,
                MaxLength = MaxLength,
                IsAutoIncrement = IsAutoIncrement,
                Precision = Precision,
                Scale = Scale
            };
            return result;
        }
    }

    #endregion

    #region Logs

    /// <summary>
    /// 生成器日志操作
    /// </summary>
    public class GeneratorLogger : IGeneratorLogger
    {
        /// <summary>
        /// 日志
        /// </summary>
        private readonly ILog<Generator> _logger;

        /// <summary>
        /// 初始化生成器日志操作
        /// </summary>
        /// <param name="logger">日志</param>
        public GeneratorLogger(ILog<Generator> logger)
        {
            _logger = logger ?? Log<Generator>.Null;
        }

        /// <inheritdoc />
        public void LogException(Exception exception)
        {
            _logger.Exception(exception).LogError();
        }

        /// <inheritdoc />
        public void LogOptions(GeneratorOptions options)
        {
            _logger.AppendLine("读取生成器配置:")
                .AppendLine($"   模板根路径: {options.TemplatePath},")
                .AppendLine($"   输出根路径: {options.OutputPath},")
                .AppendLine($"   消息配置:")
                .AppendLine($"       必填项消息: {options.Messages.RequiredMessage}")
                .AppendLine($"       最大长度消息: {options.Messages.MaxLengthMessage}")
                .AppendLine($"   项目配置:");
            foreach (var project in options.Projects.Values)
            {
                _logger.AppendLine($"       项目名称: {project.Name}")
                    .AppendLine($"           数据库类型: {project.DbType}")
                    .AppendLine($"           目标数据库类型: {project.TargetDbType}")
                    .AppendLine($"           数据库连接字符串: {project.ConnectionString}")
                    .AppendLine($"           工作单元名称: {project.UnitOfWorkName}")
                    .AppendLine($"           是否启用: {project.Enabled.Description()}");
            }
            _logger.LogDebug();
        }

        /// <inheritdoc />
        public void BeginBuildContext()
        {
            _logger.Message("开始构建生成器上下文").LogDebug();
        }

        /// <inheritdoc />
        public void LogGeneratorContextBaseInfo(GeneratorContext context)
        {
            _logger.AppendLine("生成器上下文基础信息:")
                .AppendLine($"   模板根路径: {context.TemplateRootPath},")
                .AppendLine($"   输出根路径: {context.OutputRootPath},")
                .AppendLine($"   消息上下文信息:")
                .AppendLine($"       必填项消息: {context.Message.RequiredMessage}")
                .AppendLine($"       最大长度消息: {context.Message.MaxLengthMessage}")
                .LogDebug();
        }

        /// <inheritdoc />
        public void BeginBuildProjectContext(string project)
        {
            _logger.Message($"开始构建生成器项目上下文: {project}").LogDebug();
        }

        /// <inheritdoc />
        public void BeginGetDbMetadata(ProjectOptions projectOptions)
        {
            _logger.AppendLine("开始获取数据库元数据,")
                .AppendLine($"    数据库类型: {projectOptions.DbType},")
                .AppendLine($"    数据库连接字符串: {projectOptions.ConnectionString}")
                .LogDebug();
        }

        /// <inheritdoc />
        public void EndGetDbMetadata(DatabaseInfo info)
        {
            _logger.AppendLine("获取数据库元数据完成,")
                .AppendLine($"    数据库名称: {info.Name}")
                .LogDebug();
        }

        /// <inheritdoc />
        public void EndProjectContext(ProjectContext context)
        {
            _logger.AppendLine("构建生成器项目上下文完成:")
                .AppendLine($"   项目名称: {context.Name},")
                .AppendLine($"   目标数据库类型: {context.TargetDbType},")
                .AppendLine($"   工作单元名称: {context.UnitOfWorkName},")
                .AppendLine($"   是否启用: {context.Enabled.Description()}");
            foreach (var entity in context.Entities)
            {
                _logger.AppendLine($"   实体: {entity.Name},")
                    .AppendLineIf($"       架构: {entity.Schema},", entity.Schema.IsEmpty() == false)
                    .AppendLine($"       描述: {entity.Description},")
                    .AppendLine($"       输出根路径: {entity.Output.RootPath},")
                    .AppendLineIf($"       输出相对根路径: {entity.Output.RelativeRootPath},", entity.Output.RelativeRootPath.IsEmpty() == false)
                    .AppendLine($"       输出文件名: {entity.Output.FileNameNoExtension},")
                    .AppendLineIf($"       输出文件扩展名: {entity.Output.Extension},", entity.Output.Extension.IsEmpty() == false)
                    .AppendLineIf($"       输出文件命名约定: {entity.Output.NamingConvention},", entity.Output.NamingConvention != null);
                foreach (var property in entity.Properties)
                {
                    _logger.AppendLine($"      属性: {property.Name}")
                        .AppendLine($"         描述: {property.Description},")
                        .AppendLine($"         是否主键: {property.IsKey.Description()},")
                        .AppendLine($"         是否必填: {property.IsRequired.Description()},")
                        .AppendLine($"         是否自增: {property.IsAutoIncrement.Description()},")
                        .AppendLine($"         DbType: {property.Type},")
                        .AppendLine($"         SystemType: {property.SystemType},")
                        .AppendLine($"         NativeType: {property.NativeType},")
                        .AppendLineIf($"         最大长度: {property.MaxLength},", property.MaxLength.SafeValue() > 0)
                        .AppendLineIf($"         数值精度: {property.Precision},", property.Precision.SafeValue() != 0)
                        .AppendLineIf($"         小数位数: {property.Scale}", property.Scale.SafeValue() != 0);
                }
            }
            _logger.LogDebug();
        }

        /// <inheritdoc />
        public void BeginGeTemplates(string project, string templateRootPath)
        {
            _logger.AppendLine($"开始获取 {project}项目 的模板列表")
                .AppendLine($"    模板根路径: {templateRootPath}")
                .LogDebug();
        }

        /// <inheritdoc />
        public void EndGeTemplates(string project, List<ITemplate> templates)
        {
            _logger.AppendLine($"获取 {project}项目 的模板列表完成");
            foreach (var template in templates)
            {
                _logger.AppendLine($"    {template.Path},");
                _logger.Line();
            }
            _logger.LogDebug();
        }

        /// <inheritdoc />
        public void FilterTemplate(string path)
        {
            _logger.AppendLine($"过滤模板: {path}").LogDebug();
        }

        /// <inheritdoc />
        public void BeginGenerateProject(string project)
        {
            _logger.AppendLine($"开始生成项目: {project}").LogInformation();
        }

        /// <inheritdoc />
        public void DisableProject(string project)
        {
            _logger.AppendLine($"项目 {project} 已禁用,不生成该项目代码").LogInformation();
        }

        /// <inheritdoc />
        public void BeginGenerateEntity(EntityContext entity)
        {
            _logger.AppendLine($"开始生成 {entity.Description}( {entity.Name} ) 全部模板代码").LogDebug();
        }

        /// <inheritdoc />
        public void SkipRelationTable(EntityContext entity)
        {
            _logger.AppendLine($"{entity.Description}( {entity.Name} ) 是关联表,已跳过生成").LogDebug();
        }

        /// <inheritdoc />
        public void RenderTemplate(EntityContext entity, ITemplate template)
        {
            _logger.AppendLine($"生成 {entity.Description}( {entity.Name} ) 代码")
                .AppendLine($"    模板: {template.Path}")
                .LogDebug();
        }

        /// <inheritdoc />
        public void EndGenerateEntity(EntityContext entity)
        {
            _logger.AppendLine($"{entity.Description}( {entity.Name} ) 代码生成成功").LogInformation();
        }

        /// <inheritdoc />
        public void FilterResource(string path)
        {
            _logger.AppendLine($"过滤资源: {path}").LogDebug();
        }

        /// <inheritdoc />
        public void ImportResource(string templateRootPath, string outputRootPath, string project, Resource resource)
        {
            _logger.AppendLine("开始导入静态资源")
                .AppendLine($"    模板根目录路径: {templateRootPath}")
                .AppendLine($"    输出根目录路径: {outputRootPath}")
                .AppendLine($"    项目名称: {project}")
                .AppendLine($"    资源路径: {resource.From}")
                .AppendLine($"    目标路径: {resource.To}")
                .LogDebug();
        }

        /// <inheritdoc />
        public void ImportDirectory(string templateRootPath, string outputRootPath, string project, string from, string to)
        {
            _logger.AppendLine("开始导入静态资源目录")
                .AppendLine($"    模板根目录路径: {templateRootPath}")
                .AppendLine($"    输出根目录路径: {outputRootPath}")
                .AppendLine($"    项目名称: {project}")
                .AppendLine($"    资源路径: {from}")
                .AppendLine($"    目标路径: {to}")
                .LogDebug();
        }

        /// <inheritdoc />
        public void BeginImportFile(string sourceFile, string destFile)
        {
            _logger.AppendLine("开始导入静态资源文件")
                .AppendLine($"    资源路径: {sourceFile}")
                .AppendLine($"    目标路径: {destFile}")
                .LogDebug();
        }

        /// <inheritdoc />
        public void EndImportFile(string sourceFile, string destFile)
        {
            _logger.AppendLine("导入静态资源文件成功")
                .AppendLine($"    资源路径: {sourceFile}")
                .AppendLine($"    目标路径: {destFile}")
                .LogInformation();
        }

        /// <inheritdoc />
        public void EndGenerateProject(string project)
        {
            _logger.AppendLine($"项目 {project} 生成完成").LogInformation();
        }

        /// <summary>
        /// 生成完成
        /// </summary>
        /// <param name="stopwatch">计时器</param>
        public void EndGenerate(Stopwatch stopwatch)
        {
            _logger.AppendLine($"代码生成完成,耗时: {stopwatch.Elapsed.Description()}").LogInformation();
        }
    }

