    /// <summary>
    /// 生成器
    /// </summary>
    public class Generator : IGenerator
    {
        /// <summary>
        /// 日志
        /// </summary>
        private readonly IGeneratorLogger _logger;
        /// <summary>
        /// 生成器上下文构建器
        /// </summary>
        private readonly IGeneratorContextBuilder _contextBuilder;
        /// <summary>
        /// 生成器上下文
        /// </summary>
        private GeneratorContext _context;
        /// <summary>
        /// 模板查找器
        /// </summary>
        private readonly ITemplateFinder _templateFinder;
        /// <summary>
        /// 静态资源管理器
        /// </summary>
        private readonly IResourceManager _resourceManager;
        /// <summary>
        /// 计时器
        /// </summary>
        private readonly Stopwatch _stopwatch;

        /// <summary>
        /// 初始化生成器
        /// </summary>
        /// <param name="logger">日志</param>
        /// <param name="contextBuilder">生成器上下文构建器</param>
        /// <param name="templateFinder">模板查找器</param>
        /// <param name="resourceManager">静态资源管理器</param>
        public Generator(IGeneratorLogger logger, IGeneratorContextBuilder contextBuilder, ITemplateFinder templateFinder, IResourceManager resourceManager)
        {
            _logger = logger;
            _contextBuilder = contextBuilder ?? throw new ArgumentNullException(nameof(contextBuilder));
            _templateFinder = templateFinder ?? throw new ArgumentNullException(nameof(templateFinder));
            _resourceManager = resourceManager ?? throw new ArgumentNullException(nameof(resourceManager));
            _stopwatch = new Stopwatch();
        }

        /// <inheritdoc />
        public async Task GenerateAsync()
        {
            try
            {
                _stopwatch.Start();
                _context = await _contextBuilder.BuildAsync();
                foreach (var project in _context.Projects)
                {
                    await GenerateProject(project);
                }
                _logger.EndGenerate(_stopwatch);
            }
            catch (Exception ex)
            {
                _logger.LogException(ex);
                throw;
            }
        }

        /// <summary>
        /// 生成项目
        /// </summary>
        /// <param name="projectContext">项目上下文</param>
        protected virtual async Task GenerateProject(ProjectContext projectContext)
        {
            if (projectContext.Enabled == false)
            {
                _logger.DisableProject(projectContext.Name);
                return;
            }
            var templates = GeTemplates(_context.TemplateRootPath, projectContext);
            _logger.BeginGenerateProject(projectContext.Name);
            foreach (var entity in projectContext.Entities)
            {
                await GenerateEntity(entity, templates);
            }
            await _resourceManager.ImportsAsync(_context.TemplateRootPath, _context.OutputRootPath, projectContext);
            _logger.EndGenerateProject(projectContext.Name);
        }

        /// <summary>
        /// 获取模板列表
        /// </summary>
        /// <param name="templateRootPath">模板根路径</param>
        /// <param name="projectContext">项目上下文</param>
        protected virtual List<ITemplate> GeTemplates(string templateRootPath, ProjectContext projectContext)
        {
            _logger.BeginGeTemplates(projectContext.Name, templateRootPath);
            var result = _templateFinder.Find(templateRootPath, projectContext).ToList();
            _logger.EndGeTemplates(projectContext.Name, result);
            return result;
        }

        /// <summary>
        /// 生成实体
        /// </summary>
        /// <param name="entityContext">实体上下文</param>
        /// <param name="templates">模板列表</param>
        protected virtual async Task GenerateEntity(EntityContext entityContext, List<ITemplate> templates)
        {
            _logger.BeginGenerateEntity(entityContext);
            if (IsSkip(entityContext))
                return;
            foreach (var template in templates)
            {
                await template.RenderAsync(entityContext.Clone());
                _logger.RenderTemplate(entityContext, template);
            }
            _logger.EndGenerateEntity(entityContext);
        }

        /// <summary>
        /// 是否跳过
        /// </summary>
        protected virtual bool IsSkip(EntityContext entityContext)
        {
            if (entityContext.IsRelationTable)
            {
                _logger.SkipRelationTable(entityContext);
                return true;
            }
            return false;
        }
    }

    /// <summary>
    /// 生成器
    /// </summary>
    public interface IGenerator
    {
        /// <summary>
        /// 生成
        /// </summary>
        Task GenerateAsync();
    }

    /// <summary>
    /// 命名约定
    /// </summary>
    public enum NamingConvention
    {
        /// <summary>
        /// 帕斯卡命名,所有单词首字母大写
        /// </summary>
        PascalCase,
        /// <summary>
        /// 驼峰命名,第一个单词首字母小写,其余单词首字母大写
        /// </summary>
        CamelCase
    }

    /// <summary>
    /// 系统类型
    /// </summary>
    public enum SystemType
    {
        /// <summary>
        /// 全局唯一标识
        /// </summary>
        Guid,
        /// <summary>
        /// 字符串
        /// </summary>
        String,
        /// <summary>
        /// 字节
        /// </summary>
        Byte,
        /// <summary>
        /// 16位整型
        /// </summary>
        Short,
        /// <summary>
        /// 32位整型
        /// </summary>
        Int,
        /// <summary>
        /// 64位整型
        /// </summary>
        Long,
        /// <summary>
        /// 32位浮点型
        /// </summary>
        Single,
        /// <summary>
        /// 64位浮点型
        /// </summary>
        Double,
        /// <summary>
        /// 128位浮点型
        /// </summary>
        Decimal,
        /// <summary>
        /// 布尔
        /// </summary>
        Bool,
        /// <summary>
        /// 日期
        /// </summary>
        DateTime,
        /// <summary>
        /// 字节流
        /// </summary>
        Binary
    }

    /// <summary>
    /// 系统类型扩展操作
    /// </summary>
    public static class SystemTypeExtensions
    {
        /// <summary>
        /// 获取类型字符串
        /// </summary>
        /// <param name="type">系统类型</param>
        /// <param name="isNullable">是否可空</param>
        public static string ToTypeString(this SystemType? type, bool isNullable)
        {
            if (type == null)
                return null;
            switch (type)
            {
                case SystemType.Guid:
                    return isNullable ? "Guid?" : "Guid";
                case SystemType.String:
                    return "string";
                case SystemType.Byte:
                    return isNullable ? "byte?" : "byte";
                case SystemType.Short:
                    return isNullable ? "short?" : "short";
                case SystemType.Int:
                    return isNullable ? "int?" : "int";
                case SystemType.Long:
                    return isNullable ? "long?" : "long";
                case SystemType.Single:
                    return isNullable ? "float?" : "float";
                case SystemType.Double:
                    return isNullable ? "double?" : "double";
                case SystemType.Decimal:
                    return isNullable ? "decimal?" : "decimal";
                case SystemType.Bool:
                    return isNullable ? "bool?" : "bool";
                case SystemType.DateTime:
                    return isNullable ? "DateTime?" : "DateTime";
                case SystemType.Binary:
                    return "byte[]";
                default:
                    return null;
            }
        }
    }

    #endregion

    #region Generators.Razor
    /// <summary>
    /// Razor生成服务注册器
    /// </summary>
    public class RazorGeneratorServiceRegistrar : IServiceRegistrar
    {
        /// <summary>
        /// 获取服务名
        /// </summary>
        public static string ServiceName => "Util.Generators.Razor.Infrastructure.RazorGeneratorServiceRegistrar";

        /// <summary>
        /// 排序号
        /// </summary>
        public int OrderId => 10010;

        /// <summary>
        /// 是否启用
        /// </summary>
        public bool Enabled => ServiceRegistrarConfig.IsEnabled(ServiceName);

        /// <summary>
        /// 注册服务
        /// </summary>
        /// <param name="serviceContext">服务上下文</param>
        public Action Register(ServiceContext serviceContext)
        {
            serviceContext.HostBuilder.ConfigureServices((context, services) =>
            {
                services.TryAddSingleton<IGenerator, Generator>();
                services.TryAddSingleton<IGeneratorContextBuilder, GeneratorContextBuilder>();
                services.TryAddSingleton<IGeneratorOptionsBuilder, GeneratorOptionsBuilder>();
                services.TryAddSingleton<ITemplateFinder, RazorTemplateFinder>();
                services.TryAddSingleton<ITemplateFilterManager, TemplateFilterManager>();
                services.TryAddSingleton<IResourceManager, ResourceManager>();
            });
            AddFilters();
            return null;
        }

        /// <summary>
        /// 添加模板过滤器
        /// </summary>
        private void AddFilters()
        {
            TemplateFilterManager.AddFilter(new PartTemplateFilter());
        }
    }

    /// <summary>
    /// Razor生成服务注册器配置扩展
    /// </summary>
    public static class ServiceRegistrarConfigExtensions
    {
        /// <summary>
        /// 启用Razor生成服务注册器
        /// </summary>
        /// <param name="config">服务注册器配置</param>
        public static ServiceRegistrarConfig EnableRazorGeneratorServiceRegistrar(this ServiceRegistrarConfig config)
        {
            ServiceRegistrarConfig.Enable(RazorGeneratorServiceRegistrar.ServiceName);
            return config;
        }

        /// <summary>
        ///禁用Razor生成服务注册器
        /// </summary>
        /// <param name="config">服务注册器配置</param>
        public static ServiceRegistrarConfig DisableRazorGeneratorServiceRegistrar(this ServiceRegistrarConfig config)
        {
            ServiceRegistrarConfig.Disable(RazorGeneratorServiceRegistrar.ServiceName);
            return config;
        }
    }

    /// <summary>
    /// 部分模板过滤器
    /// </summary>
    public class PartTemplateFilter : ITemplateFilter
    {
        /// <inheritdoc />
        public bool IsFilter(string path, ProjectContext projectContext)
        {
            if (path.IsEmpty())
                return true;
            return path.EndsWith(".Part.cshtml", StringComparison.OrdinalIgnoreCase);
        }
    }

    /// <summary>
    /// Razor模板
    /// </summary>
    public class RazorTemplate : ITemplate
    {
        /// <summary>
        /// Razor模板引擎
        /// </summary>
        protected readonly ITemplateEngine TemplateEngine;
        /// <summary>
        /// 模板文件
        /// </summary>
        protected readonly FileInfo TemplateFile;

        /// <summary>
        /// 初始化Razor模板
        /// </summary>
        /// <param name="templateEngine">Razor模板引擎</param>
        /// <param name="file">模板文件</param>
        public RazorTemplate(ITemplateEngine templateEngine, FileInfo file)
        {
            TemplateEngine = templateEngine;
            TemplateFile = file;
        }

        /// <summary>
        /// 模板路径
        /// </summary>
        public string Path => TemplateFile.FullName;

        /// <summary>
        /// 渲染
        /// </summary>
        /// <param name="context">实体上下文</param>
        public async Task<string> RenderAsync(EntityContext context)
        {
            ValidateEntityContext(context);
            InitRelativeRootPath(context);
            var result = await RenderResult(context);
            await WriteFile(context, result);
            return result;
        }

        /// <summary>
        /// 验证实体上下文
        /// </summary>
        /// <param name="context">实体上下文</param>
        protected virtual void ValidateEntityContext(EntityContext context)
        {
            context.CheckNull(nameof(context));
        }

        /// <summary>
        /// 初始化相对根路径
        /// </summary>
        /// <param name="context">实体上下文</param>
        protected virtual void InitRelativeRootPath(EntityContext context)
        {
            var relativeRootPath = GetRelativeRootPath(context);
            context.Output.RelativeRootPath = relativeRootPath;
        }

        /// <summary>
        /// 获取模板相对根路径
        /// </summary>
        /// <param name="context">实体上下文</param>
        protected string GetRelativeRootPath(EntityContext context)
        {
            return TemplateFile.DirectoryName.RemoveStart(context.ProjectContext.GeneratorContext.TemplateRootPath).RemoveStart("\\").RemoveStart("/");
        }

        /// <summary>
        /// 渲染结果
        /// </summary>
        /// <param name="context">实体上下文</param>
        protected virtual async Task<string> RenderResult(EntityContext context)
        {
            return await TemplateEngine.RenderByPathAsync(TemplateFile.FullName, context);
        }

        /// <summary>
        /// 写入文件
        /// </summary>
        /// <param name="context">实体上下文</param>
        /// <param name="result">渲染结果</param>
        protected virtual async Task WriteFile(EntityContext context, string result)
        {
            if (context.Output.Path.IsEmpty())
                return;
            if (result.IsEmpty())
                return;
            await Util.Helpers.File.WriteAsync(context.Output.Path, result);
        }
    }

    /// <summary>
    /// Razor模板查找器
    /// </summary>
    public class RazorTemplateFinder : ITemplateFinder
    {
        /// <summary>
        /// Razor模板引擎
        /// </summary>
        private readonly ITemplateEngine _templateEngine;
        /// <summary>
        /// 模板过滤器管理器
        /// </summary>
        private readonly ITemplateFilterManager _filterManager;
        /// <summary>
        /// 日志操作
        /// </summary>
        private readonly IGeneratorLogger _logger;

        /// <summary>
        /// 初始化Razor模板查找器
        /// </summary>
        /// <param name="templateEngine">Razor模板引擎</param>
        /// <param name="filterManager">模板过滤器管理器</param>
        /// <param name="logger">日志操作</param>
        public RazorTemplateFinder(ITemplateEngine templateEngine, ITemplateFilterManager filterManager, IGeneratorLogger logger = null)
        {
            _templateEngine = templateEngine ?? throw new ArgumentNullException(nameof(templateEngine));
            _filterManager = filterManager ?? throw new ArgumentNullException(nameof(filterManager));
            _logger = logger ?? NullGeneratorLogger.Instance;
        }

        /// <inheritdoc />
        public IEnumerable<ITemplate> Find(string rootPath, ProjectContext projectContext)
        {
            var result = new List<ITemplate>();
            var files = GetFiles(rootPath);
            foreach (var file in files)
            {
                if (_filterManager.IsFilter(file.FullName, projectContext))
                {
                    _logger.FilterTemplate(file.FullName);
                    continue;
                }
                result.Add(new RazorTemplate(_templateEngine, file));
            }
            return result;
        }

        /// <summary>
        /// 获取cshtml文件列表
        /// </summary>
        protected virtual List<FileInfo> GetFiles(string rootPath)
        {
            return Util.Helpers.File.GetAllFiles(rootPath, "*.cshtml");
        }
    }

    #endregion
}